[10296] = { ["id"] = 10296, ["name"] = "The Black Morass", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 2366, ["series"] = { 10297 }, ["description"] = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending. You must venture through the timeway leading to the Black Morass . Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at .", ["rewardXP"] = 430, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.385, ["mapID"] = 75, ["npcID"] = 20130 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.385, ["mapID"] = 75, ["npcID"] = 20130 } }, ["coords"] = { ["mapID"] = 75, ["x"] = 0.416, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2366 } }, ["questGiverID"] = 20130, ["questTurnInID"] = 20130, ["questType"] = "dungeon" },
[12431] = { ["id"] = 12431, ["name"] = "The Conquest Pit: Final Showdown", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 394, ["mapID"] = 116, ["series"] = { 12427, 12428, 12429, 12430 }, ["description"] = "You must've really upset Krenna. She and Gorgonna have had a spat and you're wanted in the pit immediately. There are some wild rumors that it's a fight to the death! That would be bad news for you, but great news for our business venture! At any rate, you can't run away from fate... best get in there on the quick and get it over with.", ["rewardGold"] = 315000, ["rewardXP"] = 3135, ["rewardChoices"] = { 39181, 39183, 39182, 39179, 39180 }, ["starts"] = { { ["npcID"] = 27719, ["x"] = 0.224, ["y"] = 0.638, ["mapID"] = 116 } }, ["ends"] = { { ["npcID"] = 27102, ["x"] = 0.208, ["y"] = 0.64, ["mapID"] = 116 } }, ["coords"] = { ["x"] = 0.224, ["y"] = 0.638, ["source"] = "quest_giver", ["mapID"] = 116 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "group", ["sourceQuests"] = { 12430 }, ["questLines"] = { { ["id"] = 537, ["name"] = "Grizzly Hills", ["orderIndex"] = 100, ["flags"] = 0 } } },
[12807] = { ["id"] = 12807, ["name"] = "The Story Thus Far...", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["series"] = { 12806, 12810, 12814 }, ["description"] = "We have much to do, but first I believe a short refresher is in order. We death knights have a colorful past with our Scarlet friends who idiotically rest comfortably in the harbor below us to the northwest. When you are ready for an earful, speak with me again and I shall provide enlightenment.", ["rewardXP"] = 430, ["starts"] = { { ["npcID"] = 29344, ["x"] = 0.196, ["y"] = 0.48, ["mapID"] = 118 } }, ["ends"] = { { ["npcID"] = 29344, ["x"] = 0.196, ["y"] = 0.48, ["mapID"] = 118 } }, ["coords"] = { ["x"] = 0.196, ["y"] = 0.48, ["source"] = "quest_giver", ["mapID"] = 118 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 12806 } },
[13161] = { ["id"] = 13161, ["name"] = "The Rider of the Unholy", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["description"] = "It's time that we start cutting off the heads of the beast. I served beside Rokir for quite some time. He knows the unholy arts better than most any other death knight I've met and he's equally as ruthless. Rokir 's strengths are most apparent when you are fighting him on his own ground. Sadly, we don't have much option in those regards, but stay on your feet to avoid his undead minions and you should come out victorious. Be nimble, , and do not take him lightly.", ["rewardGold"] = 561800, ["rewardXP"] = 4300, ["rewardChoices"] = { 43904, 43948, 43940, 43873 }, ["starts"] = { { ["npcID"] = 30944, ["x"] = 0.54, ["y"] = 0.71, ["mapID"] = 118 } }, ["ends"] = { { ["npcID"] = 30944, ["x"] = 0.54, ["y"] = 0.71, ["mapID"] = 118 } }, ["coords"] = { ["x"] = 0.54, ["y"] = 0.71, ["source"] = "quest_giver", ["mapID"] = 118 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "group", ["sourceQuests"] = { 13146, 13147, 13160 }, ["questLines"] = { { ["id"] = 538, ["name"] = "Icecrown", ["orderIndex"] = 94, ["flags"] = 0 } } },
