[24928] = { ["id"] = 24928, ["name"] = "To The Ground!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 440, ["mapID"] = 71, ["series"] = { 24927, 24949, 25534, 25541, 24950, 25103 }, ["description"] = "I've conducted a thorough appraisal of the real estate here and, unfortunately, its market value is just far too low to be of any use. We're going to have to renovate. Luckily for you, I've learned a few things about arson. Hopefully you have too! You're going to be throwing these perfectly safe bottles of flaming rum at those filthy ramshackle huts over there. Try not to stand downwind.", ["rewardGold"] = 124440, ["rewardXP"] = 2090, ["starts"] = { { ["npcID"] = 38703, ["x"] = 0.718, ["y"] = 0.454, ["mapID"] = 71 } }, ["ends"] = { { ["npcID"] = 38703, ["x"] = 0.718, ["y"] = 0.454, ["mapID"] = 71 } }, ["coords"] = { ["x"] = 0.718, ["y"] = 0.454, ["source"] = "quest_giver", ["mapID"] = 71 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 24910 }, ["questLines"] = { { ["id"] = 511, ["name"] = "Tanaris", ["orderIndex"] = 14, ["flags"] = 0 } } },
[25053] = { ["id"] = 25053, ["name"] = "To The Ground!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 440, ["mapID"] = 71, ["series"] = { 25052, 25054, 26886, 26887, 25166, 26889 }, ["description"] = "You know, this place would probably make a great home for us gnomes if it wasn't so old and dirty and full of pirates! We're taking care of the pirates problem, but the awful and dirty problem needs fixing. I mean, no self-respecting gnome would ever live in such an ugly hovel like these buildings! So here, take this bottle of flaming rum and go burn those ugly shacks down for us!", ["rewardGold"] = 117960, ["rewardXP"] = 2090, ["starts"] = { { ["npcID"] = 38704, ["x"] = 0.722, ["y"] = 0.452, ["mapID"] = 71 } }, ["ends"] = { { ["npcID"] = 38704, ["x"] = 0.722, ["y"] = 0.452, ["mapID"] = 71 } }, ["coords"] = { ["x"] = 0.722, ["y"] = 0.452, ["source"] = "quest_giver", ["mapID"] = 71 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 24910 }, ["questLines"] = { { ["id"] = 511, ["name"] = "Tanaris", ["orderIndex"] = 4, ["flags"] = 0 } } },
[27141] = { ["id"] = 27141, ["name"] = "Exploding Through", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 249, ["series"] = { 27993 }, ["description"] = "What a find! Right here... exactly where my notes predicted it would be. With any luck, inside this chamber will lie clues to the location of the legendary Coffer of the Promise. That's right, . It's not just a myth. I believe it truly exists. I'll explain more later. For now, just give me a hand with these explosives.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["starts"] = { { ["npcID"] = 44860, ["x"] = 0.644, ["y"] = 0.224, ["mapID"] = 249 } }, ["ends"] = { { ["npcID"] = 45180, ["x"] = 0.646, ["y"] = 0.286, ["mapID"] = 249 } }, ["coords"] = { ["x"] = 0.644, ["y"] = 0.224, ["source"] = "quest_giver", ["mapID"] = 249 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27993 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 47, ["flags"] = 0 } } },
[27760] = { ["id"] = 27760, ["name"] = "Artificial Intelligence", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 249, ["description"] = "Emergency code: 55-729. Upper cerebral cortex functions in expedition members have been compromised. Please report to your nearest terminal location, to the southeast of the Sunstone Terrace, for further analysis.", ["rewardGold"] = 78750, ["rewardXP"] = 3085, ["ends"] = { { ["npcID"] = 206293, ["x"] = 0.741, ["y"] = 0.644, ["mapID"] = 249 } }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 37, ["flags"] = 0 } } },
[27779] = { ["id"] = 27779, ["name"] = "Gnomebliteration", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 249, ["description"] = "I have downloaded my program to the fusion core and have complete control over it. I've created a small pocket of air inside to avoid vaporizing user . I will yield control of all movement functions so I can dedicate my cycles to keeping the core stable. Go down the hill and neutralize as many of the expedition members as possible. My analysis reveals you might feel... \"guilt\" as a result of such high fatality numbers. User , you must be assured that expedition members are without hope.", ["rewardGold"] = 274800, ["rewardXP"] = 5145, ["rewardChoices"] = { 65776, 65775, 65774, 65773 }, ["starts"] = { { ["npcID"] = 46750, ["x"] = 0.772, ["y"] = 0.632, ["mapID"] = 249 } }, ["ends"] = { { ["npcID"] = 46750, ["x"] = 0.772, ["y"] = 0.632, ["mapID"] = 249 } }, ["coords"] = { ["x"] = 0.772, ["y"] = 0.632, ["source"] = "quest_giver", ["mapID"] = 249 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27778 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 41, ["flags"] = 0 } } },
[27961] = { ["id"] = 27961, ["name"] = "Out of Place", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 51, ["mapID"] = 32, ["description"] = "The gorge is an unforgiving place. We don't get a whole lot of fuzzy wildlife wandering around here. We tried bringing in some wild game, but they haven't fared well at all. There's just no food for them to eat. Now the nearby spiders - which were already dangerous - are getting big and fat on chicken meat. We'll never get rid of all the spiders, but we can salvage what few chickens remain. Not only will you be feeding the Brotherhood, you'll be saving them a painful death by spider bite.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 62934 }, ["rewardChoices"] = { 63215, 63214, 63213, 63212 }, ["starts"] = { { ["npcID"] = 47267, ["x"] = 0.684, ["y"] = 0.534, ["mapID"] = 32 } }, ["ends"] = { { ["npcID"] = 47267, ["x"] = 0.684, ["y"] = 0.534, ["mapID"] = 32 } }, ["coords"] = { ["x"] = 0.684, ["y"] = 0.534, ["source"] = "quest_giver", ["mapID"] = 32 }, ["mapCandidates"] = { ["npc"] = { 32 }, ["zone"] = { 51 } }, ["questType"] = "standard", ["sourceQuests"] = { 27960 } },
[28028] = { ["id"] = 28028, ["name"] = "Siege!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 51, ["mapID"] = 32, ["series"] = { 28029, 28030, 28033, 28034, 28035, 28052 }, ["description"] = "That Overseer Oilfist couldn't'a picked a worse time to ask me to join a fight. My summit's already under siege! It's nothin' my guards can't handle, but still, it won't be easy for me to just pick up and send some dwarves into that infernal gorge. Tell ya what: you take out their marksmen that're holding our fortress under siege, and I'll consider your offer. Ye'll find 'em slinkin' around the flats to the east.", ["rewardGold"] = 257400, ["rewardXP"] = 2090, ["starts"] = { { ["npcID"] = 47393, ["x"] = 0.408, ["y"] = 0.518, ["mapID"] = 32 } }, ["ends"] = { { ["npcID"] = 47393, ["x"] = 0.408, ["y"] = 0.518, ["mapID"] = 32 } }, ["coords"] = { ["x"] = 0.408, ["y"] = 0.518, ["source"] = "quest_giver", ["mapID"] = 32 }, ["mapCandidates"] = { ["npc"] = { 32 }, ["zone"] = { 51 } }, ["questType"] = "standard", ["sourceQuests"] = { 27986 }, ["questLines"] = { { ["id"] = 386, ["name"] = "Searing Gorge", ["orderIndex"] = 9, ["flags"] = 0 } } },
[28404] = { ["id"] = 28404, ["name"] = "I'll Do It By Hand", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 249, ["series"] = { 28353, 28271, 28272, 28363, 28367, 28402, 28403 }, ["description"] = "Yes, this all looks familiar enough. Thanks to all the information you gathered for me, I'm sure that I can activate the mechanism. I'll just need some time free from distraction. As soon as I get started, you can count on that titan construct to try and stop me. That's where you come in. I don't need to remind you of what's riding on this. Take down that guardian!", ["rewardGold"] = 274800, ["rewardXP"] = 5145, ["rewardChoices"] = { 65873, 65885, 65871 }, ["starts"] = { { ["npcID"] = 48558, ["x"] = 0.39, ["y"] = 0.232, ["mapID"] = 249 } }, ["ends"] = { { ["npcID"] = 48558, ["x"] = 0.39, ["y"] = 0.232, ["mapID"] = 249 } }, ["coords"] = { ["x"] = 0.39, ["y"] = 0.232, ["source"] = "quest_giver", ["mapID"] = 249 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 28403 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 92, ["flags"] = 0 } } },
[56000] = { ["id"] = 56000, ["name"] = "We've Got Crabs!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56000 }, ["description"] = "<name>, you're just in time. Everything's ready for the crab hunt! Okay, okay... I know what you're thinking. A founding member of D.E.H.T.A. that condones hunting? I'm going to level with you, <name>. I've got a bar full of hungry murlocs that only eat three things: crabs, fish, and people. If that's not reason enough, crabs are overpopulated in this region and they're decimating the local grub worm population! How many innocent grub worms need to die before we do something, <name>?", ["objectivesText"] = "Collect 12 Crackleclaw Crabs . Progress: How many innocent grub worms need to die before we do something, <name>?", ["rewardGold"] = 341600, ["rewardItems"] = { 168628 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1749, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.254667, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56001] = { ["id"] = 56001, ["name"] = "Drunk Angry Murlocs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56001 }, ["description"] = "Those no-good Bloodfins ran off with all of the beer! I've been experimenting with brews that only use ingredients native to Nazjatar , but it's still a work in progress. For now, I must rely on whatever I can scrounge up from the shipwreck. My supply of beer was already limited, but now it's all gone thanks to those thieving Bloodfin murlocs! We're going to have some very angry customers here if we don't get it back. Please recover the stolen lager from Bloodfin Village before it's too late!", ["objectivesText"] = "Collect 12 Ocean \"Infused\" Lagers . Progress: Those no-good Bloodfins ran off with all of the beer!", ["rewardGold"] = 309800, ["rewardItems"] = { 168629, 169280, 170075 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1748, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.254667, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56002] = { ["id"] = 56002, ["name"] = "Mgglurky's Mugglrgl", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["description"] = "My cook, Mgglurky, lost his mugglrgl and he's refusing to work until he gets it back. I've got a bar full of hungry murlocs and nothing to feed them until Mgglurky starts cooking. If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands! I don't know about you, but I definitely don't want to be the main course tonight. There were some Bloodfins lurking around earlier. Search Bloodfin Village for the mugglrgl and bring it back to me once you find it.", ["rewardGold"] = 234000, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1750, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 153884, ["x"] = 0.254, ["y"] = 0.264, ["mapID"] = 1355 } }, ["ends"] = { { ["npcID"] = 153884, ["x"] = 0.254, ["y"] = 0.264, ["mapID"] = 1355 } }, ["coords"] = { ["x"] = 0.254, ["y"] = 0.264, ["source"] = "quest_giver", ["mapID"] = 1355 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
