[56030] = { ["id"] = 56030, ["name"] = "The Warchief's Order", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 862, ["storyline"] = { 56030, 56044 }, ["series"] = { 56044 }, ["description"] = "Champion, the Dark Lady summons you. The time has come to set her plan into motion. Our warships are ready to embark. The key to victory over the Alliance is within our grasp. Meet me in Zuldazar, aboard the Banshee's Wail. What we do next... we do for the Horde.", ["objectivesText"] = "Meet with Nathanos Blightcaller on The Banshee's Wail.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["nextQuests"] = { 56044 }, ["questLines"] = { { ["id"] = 939, ["name"] = "The Depths of Nazjatar", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2DetailThemeID"] = 11, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[56031] = { ["id"] = 56031, ["name"] = "The Wolf's Offensive", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1161, ["storyline"] = { 56031, 56043 }, ["series"] = { 56043 }, ["description"] = "Champion, Spymaster Shaw reports that the remains of the Horde fleet is preparing to depart. They will be easy pickings for our superior forces. Let us seize this opportunity to eliminate their threat once and for all! Preparations are underway to set sail. Come to Boralus Harbor and meet with me upon the Wind's Redemption with all haste!", ["objectivesText"] = "Meet with Genn Greymane on the Wind's Redemption.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 18230, 113364 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 153932, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 153932, ["x"] = 0.705, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["nextQuests"] = { 56043 }, ["questLines"] = { { ["id"] = 939, ["name"] = "The Depths of Nazjatar", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2DetailThemeID"] = 12, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161 },
[56034] = { ["id"] = 56034, ["name"] = "Re-sizing the Situation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "The Re-Sizer v9.0.1 barely works on inanimate objects. I have no idea what it will do to organic matter! But if we do nothing, Wrathion will die! Desperate times call for massively experimental science, <name>. Take the Re-Sizer v9.0.1 . I'll follow you around and calibrate it. We're going to whip up a giant boar!", ["objectivesText"] = "Use the Re-Sizer v9.0.1 on 3 Wandering Boars. Progress: Be careful where you point the Re-Sizer v9.0.1 . Make sure you're only using it on the boars in the immediate area.", ["rewardGold"] = 40, ["rewardXP"] = 150, ["rewardItems"] = { 170557 }, ["starts"] = { { ["x"] = 0.561, ["y"] = 0.591, ["mapID"] = 1409, ["npcID"] = 149899 } }, ["ends"] = { { ["x"] = 0.561, ["y"] = 0.591, ["mapID"] = 1409, ["npcID"] = 149899 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.561, ["y"] = 0.591 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 149899, ["questTurnInID"] = 149899, ["questType"] = "standard", ["sourceQuests"] = { 55193 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[56035] = { ["id"] = 56035, ["name"] = "Most Delicious Clams", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56035 }, ["description"] = "This pool is filled with creepy fish. It is also the home of some of the most delicious clams you will ever eat. Fresh water somehow mixes into the ocean water in this one part of Nazjatar , and that gives the meat a totally new flavor. Every now and then, we come down here and collect them for our friends in Newhome. We could sure use some help with all these extra mouths to feed!", ["objectivesText"] = "Collect 10 Neptulian Clams . Progress: Did you find enough?", ["rewardGold"] = 234000, ["rewardItems"] = { 168658, 168672 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1747, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153900, ["x"] = 0.486, ["y"] = 0.2305 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153900, ["x"] = 0.486, ["y"] = 0.2305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.2305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
