[56037] = { ["id"] = 56037, ["name"] = "Stealing the Naga's Secrets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "<Upon closer inspection, it becomes clear that the blades have been forged from Azerite . Weapons of this power should never be in the hands of the naga.>", ["objectivesText"] = "Steal the Azerite weaponry and fight your way out of Zanj'ir Terrace! Progress: I recognize the craftsmanship. This is Priscilla Ashvane's work. She must have taught the naga how to forge Azerite weaponry, but why?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168515 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 600 } }, ["starts"] = { { ["x"] = 0.346, ["y"] = 0.211, ["mapID"] = 1355, ["objectID"] = 327170 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153384, ["x"] = 0.388, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56039 }, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 33, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56038] = { ["id"] = 56038, ["name"] = "Working with Purpose", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. Before you came along, it was my job to crawl around the cavern, cracking open clams. So you see, you have some purpose, other than being a mindless sack of flesh.", ["objectivesText"] = "Collect 6 Iridescent Pearls from Chittershell Clams. Progress: Do you have them all?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168810 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55599 }, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 31, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56039] = { ["id"] = 56039, ["name"] = "We Can't Have Dull Weapons", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "For a squid head, you sure are making my life easier. I guess you get to live long enough to complete another task. Our new weapons are forged from some foreign material that I don't quite trust. You won't catch me sharpening any blades, but the work still needs to get done. Get to it!", ["objectivesText"] = "Find the special weaponry within Zanj'ir Terrace.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questTurnInID"] = 153936, ["questType"] = "standard", ["sourceQuests"] = { 55600, 56038 }, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 32, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
