[56043] = { ["id"] = 56043, ["name"] = "Send the Fleet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1161, ["storyline"] = { 56031, 56043 }, ["series"] = { 56031 }, ["description"] = "This war has cost us dearly, but victory will soon be in our grasp. What remains of the Horde fleet has departed Zuldazar and our spies say that the Banshee Queen's hand sails at their helm. This is our chance, <name>! With one strike we can eliminate what remains of their fleet and rid Azeroth of Blightcaller's filth once and for all! The fleet is preparing to depart, report to the Harbormaster when you are ready to set sail.", ["objectivesText"] = "Speak to Harbormaster Cyrus Crestfall to set sail.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 153932, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150087, ["x"] = 0.4696, ["y"] = 0.8276 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1161, 1355 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["sourceQuests"] = { 56031 }, ["questLines"] = { { ["id"] = 939, ["name"] = "The Depths of Nazjatar", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56044] = { ["id"] = 56044, ["name"] = "Send the Fleet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 862, ["storyline"] = { 56030, 56044 }, ["series"] = { 56030 }, ["description"] = "The Warchief has entrusted me with a mission of the highest priority, <name>. The mission will succeed, of this there is no question, but to ensure that any obstacles I encounter are dealt with swiftly I once again have need of your particular skills. The Zandalari have offered us use of their ships for this endeavor. Clear out whatever affairs you have remaining and report to Captain Rez'okun when you are ready to set sail.", ["objectivesText"] = "Speak to Captain Rez'okun to set sail.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150187, ["x"] = 0.368, ["y"] = 0.935 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 1355 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 56030 }, ["questLines"] = { { ["id"] = 939, ["name"] = "The Depths of Nazjatar", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56045] = { ["id"] = 56045, ["name"] = "Stealing the Naga's Secrets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "<Upon closer inspection, it becomes clear that the blades have been forged from Azerite . Weapons of this power should never be in the hands of the naga.>", ["objectivesText"] = "Steal the Azerite weaponry and fight your way out of Zanj'ir Terrace! Progress: I recognize the craftsmanship. This is Priscilla Ashvane's work. She must have taught the naga how to forge Azerite weaponry, but why?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168516 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 600 } }, ["starts"] = { { ["x"] = 0.346, ["y"] = 0.211, ["mapID"] = 1355, ["objectID"] = 327170 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153421, ["x"] = 0.388, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56047 }, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 33, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56046] = { ["id"] = 56046, ["name"] = "Working with Purpose", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. Before you came along, it was my job to crawl around the cavern, cracking open clams. So you see, you have some purpose, other than being a mindless sack of flesh.", ["objectivesText"] = "Collect 6 Iridescent Pearls from Chittershell Clams. Progress: Do you have them all?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168810 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55866 }, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 31, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56047] = { ["id"] = 56047, ["name"] = "We Can't Have Dull Weapons", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "For a squid head, you sure are making my life easier. I guess you get to live long enough to complete another task. Our new weapons are forged from some foreign material that I don't quite trust. You won't catch me sharpening any blades, but the work still needs to get done. Get to it!", ["objectivesText"] = "Find the special weaponry within Zanj'ir Terrace.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questTurnInID"] = 153936, ["questType"] = "standard", ["sourceQuests"] = { 55967, 56046 }, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 32, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56049] = { ["id"] = 56049, ["name"] = "Deck 'Em", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56049 }, ["description"] = "That ooze seems really hungry! He ate my backpack, compass, pickaxe, and my hearthstone cards. Get my cards back!", ["objectivesText"] = "Recover Adalin's Hearthstone Cards. Progress: I'm not leaving till I get my cards back!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 168236, 168256, 168754, 169864 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 153538, ["x"] = 0.752, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 153538, ["x"] = 0.752, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 55717 }, ["db2LabelIDs"] = { 5672 } },
