[56053] = { ["id"] = 56053, ["name"] = "The Final Act", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56053 }, ["description"] = "Those of us with enough mechanization survived, but it didn't matter. Bondo Bigblock sold us out. In exchange for full mechanization, he built giant bots and attacked Rustbolt. He will continue to act against us, till those few of us left are dead. We must remove this threat immediately.", ["objectivesText"] = "Kill Bondo Bigblock . Progress: Will you help me deal with this threat?", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 167062, 169114 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 153982, ["x"] = 0.728, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 153982, ["x"] = 0.728, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questTurnInID"] = 153982, ["questType"] = "standard", ["sourceQuests"] = { 56142 }, ["db2LabelIDs"] = { 5672 } },
