[56070] = { ["id"] = 56070, ["name"] = "Vengeance for the Venthyr", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10472, ["storyline"] = { 56070 }, ["description"] = "Lord Denathrius has fallen under the sway of the Jailer. His betrayal of our people shall not stand. We will show the Jailer that the venthyr are not to be underestimated... nor are you, Maw Walker. Slay his sub-lords. Let him know that he is now being hunted. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(56070)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(56070))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Defeat the Jailer's lieutenants on floors 5 and 10 of the Jailer's Tower.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10472 } }, ["questType"] = "standard" },
