[56083] = { ["id"] = 56083, ["name"] = "Unsafe Work Conditions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56083 }, ["description"] = "Those rampaging bots ain't lettin' up! We're payin' good money for the best and brightest goblins on the planet, and I ain't gonna let some malfunctionin' machinery take 'em outta the shift schedule. This is textbook unsafe working conditions, and the Greasemonkey Union reps are givin' me an earful for it. Protect the workers!", ["objectivesText"] = "15 attacking bots slain. Progress: The greasemonkeys could use your help!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150563, ["x"] = 0.738, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150563, ["x"] = 0.738, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 55736 }, ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
