[56091] = { ["id"] = 56091, ["name"] = "Usurper's Scent Gland", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 56091 }, ["description"] = "When a new queen is born and old enough to start proliferating her own hive, she will leave the nest. Her scent will attract some of the hive to fly with her to their new home. This one likely never got the chance to do so, thanks to you. The Hivemother will be interested in this item.", ["objectivesText"] = "Take the Usurper's Scent Gland to the Honeyback Hivemother for a reward. Provided item:", ["rewardItems"] = { 169658, 172142 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 153365, ["x"] = 0.626667, ["y"] = 0.263333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.263333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["startItems"] = { 169658 } },
[56092] = { ["id"] = 56092, ["name"] = "Hivethief's Jelly Stash", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 56092 }, ["description"] = "This ettin was a well known and oft dreaded face among the bees of the Honeyback hive. Their jelly stores will benefit from his demise. The Hivemother will be interested in this item.", ["objectivesText"] = "Take the Hivethief's Jelly Stash to the Honeyback Hivemother for a reward. Provided item:", ["rewardItems"] = { 169657, 172147 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 153365, ["x"] = 0.626667, ["y"] = 0.263333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.263333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["startItems"] = { 169657 } },
[56095] = { ["id"] = 56095, ["name"] = "Legacy of Nar'anan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56095 }, ["series"] = { 56118, 56143 }, ["description"] = "Hey there, <race>. Mind helping me out? You see, I found these pylons here and it seems they contain memories from a notable Highborne who lived here long ago. I can't get any closer to the rest of em' because of the snapdragons. Especially the terrormaws... Can you go and activate the pylons for me? We Tortollans love old things, and this is a potential goldmine! Oh, and be sure to write down what you see!", ["objectivesText"] = "Activate the Memory Pylons in Nar'anan and witness what happened.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154143, ["x"] = 0.665, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154143, ["x"] = 0.665, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500, 56156 } },
