[56098] = { ["id"] = 56098, ["name"] = "Defensive in Death", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56098 }, ["description"] = "<Having handled zin'anthid for a while now, you pluck one of its tentacles from the main body. As you do, the tentacle retracts, spiraling in on itself preventing you from getting to the blooms that reside along it. Perhaps Instructor Ulooaka will have more insight on how to keep this herb from defending itself.>", ["objectivesText"] = "Ask Instructor Ulooaka about the tentacles of the Zin'anthid. Provided item:", ["rewardItems"] = { 168919 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 168919 } },
