[56131] = { ["id"] = 56131, ["name"] = "Security First", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "Many dangerous creatures and allies of my father still seek to destroy us. Help secure this island, seek out and and eliminate five of our most powerful enemies.", ["objectivesText"] = "Defeat Rare enemies on the island of Mechagon .", ["rewardXP"] = 1415, ["rewardItems"] = { 168832 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10290 } }, ["questType"] = "world", ["sourceQuests"] = { 55736 }, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Rare Enemies slain in Mechagon", ["amount"] = 3, ["type"] = 0, ["objectID"] = 154198, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[56136] = { ["id"] = 56136, ["name"] = "Heroic Warfront: The Battle for Stromgarde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56136 }, ["description"] = "If the Horde thinks it can assault Stromgarde, it is sorely mistaken! We will not let Arathi fall! Prepare yourself for battle.", ["objectivesText"] = "Defeat the Horde at the Battle for Stromgarde.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 158075, 169196, 169197 }, ["rewardCurrencies"] = { { ["id"] = 1717, ["amount"] = 15 }, { ["id"] = 1553, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
