[56142] = { ["id"] = 56142, ["name"] = "Adapt, Improve, Overcome!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56142 }, ["description"] = "Izira Gearsworn is still alive, she is Rustbolt's strongest fighter, but her legs are broken. If we're going to survive I need parts to repair and upgrade her. There are machines all over with parts we can salvage. With some perseverance we should be able to fix Izira's legs. Help me obtain the following parts.", ["objectivesText"] = "20 Pristine Hound Bolts , 4 Steel Tibia XS, and 2 Machined Heel Nut. Progress: We need to start searching!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 167062, 169114, 169212, 169213, 169214 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154214, ["x"] = 0.721333, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154214, ["x"] = 0.721333, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.721333, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56143] = { ["id"] = 56143, ["name"] = "The Fate of Professor Elryna", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56143 }, ["series"] = { 56095, 56118 }, ["description"] = "From the looks of it, Elryna's story should have a very interesting end. This pylon here has been acting up, but I think I know why! These things use memory cores , little crystals found within the center of the orb. I bet there's one in that old magi tower. There's a snapdragon that's bigger than the terrormaws in there so here, keep the scroll for now. It should help in your fight. She's a big one!", ["objectivesText"] = "Defeat the Snapdragon Matriarch , collect the Memory Core , and activate the Memory Pylon to witness the fate of Professor Elryna. Progress: What happened that fateful day?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 169207, 169209 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154143, ["x"] = 0.665, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154143, ["x"] = 0.665, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56095, 56118 } },
