[56148] = { ["id"] = 56148, ["name"] = "Call to Arms: Nazjatar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 862, ["storyline"] = { 56148 }, ["description"] = "Our objectives in Nazjatar are being interrupted by the influx of Alliance scum. Clear as many of them out of the area that you find, then report back.", ["objectivesText"] = "Slay Alliance within Nazjatar .", ["rewardItems"] = { 167744, 169614 }, ["rewardCurrencies"] = { { ["id"] = 1602, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 143536, ["x"] = 0.515, ["y"] = 0.582 }, { ["mapID"] = 1355, ["npcID"] = 154641, ["x"] = 0.486, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143536, ["x"] = 0.515, ["y"] = 0.582 }, { ["mapID"] = 1355, ["npcID"] = 154641, ["x"] = 0.486, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 862, 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56149] = { ["id"] = 56149, ["name"] = "Feed Them All", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56149 }, ["description"] = "I am grateful for the help that your Alliance has given my people, but we are desperately short on food and supplies. If we do not gather enough supplies to take care of both the Alliance and my clan, we will run out of food within the week. Thankfully, there appears to be an abundance of fathom rays in the area, but I will need help hunting them in order to gather enough food for our camp. Take this fathom hook and use it to pull down the fathom rays from above.", ["objectivesText"] = "Collect 10 Fathom Flesh . Progress: Have you returned from the hunt?", ["rewardGold"] = 234000, ["rewardItems"] = { 168253, 168254 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1749, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154235, ["x"] = 0.556, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154235, ["x"] = 0.556, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56150] = { ["id"] = 56150, ["name"] = "Kill the Kritch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56150 }, ["description"] = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr. < Rlgmrr jumps around anxiously and points toward the cave.> Grrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr. <He makes a scary face and pinching motions with his hands.> Mrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", ["objectivesText"] = "Kill the Kritch . Progress: Mrgglrmr grm?", ["rewardGold"] = 234000, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1749, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153537, ["x"] = 0.45, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153537, ["x"] = 0.45, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56151] = { ["id"] = 56151, ["name"] = "Poen's Favorite Dish", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56151 }, ["description"] = "Poen is always helping us take care of every rescue we find. Can you collect some meat from the eels south of here? I like to make his favorite dish every now and then, to repay him. It also has a great effect on the ones recovering. The power of deliciousness, I tell you!", ["objectivesText"] = "Collect 15 Fresh Unagi . Progress: Did you get enough meat?", ["rewardGold"] = 309800, ["rewardItems"] = { 169234, 169280 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1747, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151635, ["x"] = 0.508, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151635, ["x"] = 0.508, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56152] = { ["id"] = 56152, ["name"] = "Turn the Scale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56152 }, ["description"] = "I am in need of your help, <class>. I have been hunting the nearby hydras for their scales, but my weapon was broken in the melee. The scales of the hydra make durable and resilient armor for our warriors. Our clan requires the scales to craft and repair our armor. If we do not resupply soon, we will be ill-equipped in our fight against the naga.", ["objectivesText"] = "Collect 20 Hydra Scales . Progress: Have you completed the hunt?", ["rewardGold"] = 234000, ["rewardItems"] = { 168519 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1749, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154238, ["x"] = 0.312, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154238, ["x"] = 0.312, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56153] = { ["id"] = 56153, ["name"] = "Most Delicious Clams", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56153 }, ["description"] = "Neptulian clams are an important part of the ankoan diet. Many forget how important proper nutrition is during a time of war. A warrior can be armed with the finest weapons and training, but if she is not healthy and well-nourished she will be ineffective in battle. Now that Mezzamere is home to your Alliance, we must work hard to gather enough food to feed our soldiers. Gather as many Neptulian clams as you can find and I will see that they make it back to camp safely.", ["objectivesText"] = "Collect 10 Neptulian Clams . Progress: Have you gathered the Neptulian clams ?", ["rewardGold"] = 234000, ["rewardItems"] = { 168658, 168672 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1748, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154239, ["x"] = 0.456, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154239, ["x"] = 0.456, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56154] = { ["id"] = 56154, ["name"] = "Where They Hide", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56154 }, ["description"] = "The naga are sending assassins to eliminate our forces. They hide nearby and murder those they cannot steal away to the slave pens. Take this special sea sponge with you. The spores will reveal the naga in all their treachery. Once revealed, slay the assassins before they can flee for reinforcements. Azshara will fall!", ["objectivesText"] = "Use the Fresh Sponge to reveal and kill 5 Zanj'ir Assassins . Progress: Have the naga assassins been eliminated?", ["rewardGold"] = 234000, ["rewardItems"] = { 168432 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1748, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154241, ["x"] = 0.412, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154241, ["x"] = 0.412, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56155] = { ["id"] = 56155, ["name"] = "Plug the Geysers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["description"] = "The geysers are dangerously unstable and will be erupting any moment now. I fear that Azshara's misuse of the Tidestone is causing irreparable damage to the elements within Nazjatar . We have to do what we can to prevent any further destruction. Take this sealant and use it to stave off the next round of eruptions. In the meantime, I will do what I can to stabilize the elements.", ["rewardGold"] = 234000, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1750, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 154247, ["x"] = 0.606, ["y"] = 0.51, ["mapID"] = 1355 } }, ["ends"] = { { ["npcID"] = 154247, ["x"] = 0.606, ["y"] = 0.51, ["mapID"] = 1355 } }, ["coords"] = { ["x"] = 0.606, ["y"] = 0.51, ["source"] = "quest_giver", ["mapID"] = 1355 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56156] = { ["id"] = 56156, ["name"] = "A Tempered Blade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 54975, 55095, 55175, 55361, 55363, 55374, 55400, 55407, 55425, 55497, 55533, 55558, 55561, 55570, 55573, 55574, 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55618, 55694, 55851, 55860, 55861, 55937, 56037, 56038, 56039, 56043, 56156, 56234, 56325, 56350, 56640, 56641, 56642, 56643, 56644, 56741, 57010 }, ["description"] = "These blades that I wield are newly forged. The time has come to temper them in the blood of my enemies. I have heard that you are skilled in the ways of battle. I too am proficient in the business of death and I would be honored to fight at your side. Accompany me, <class>, and together we will spill the blood of our enemies.", ["objectivesText"] = "Slay 15 naga with Bladesman Inowari . Progress: A blade is not worthy of a warrior until it is tempered in the blood of the enemy.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 170512 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154248, ["x"] = 0.394667, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154248, ["x"] = 0.394667, ["y"] = 0.534667 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.394667, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55363 }, ["questLines"] = { { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56157] = { ["id"] = 56157, ["name"] = "Plug the Geysers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["description"] = "There are several geysers nearby that will be erupting soon. Unfortunately, the elements in this area are not stable enough to handle the force of the eruptions. I need someone to plug the geysers while I use the elements to redirect the pressure to a safer area of Nazjatar . Take this sealant and use it to plug the geysers while I work to restore the elemental balance.", ["rewardGold"] = 234000, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1750, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 154246, ["x"] = 0.31, ["y"] = 0.378, ["mapID"] = 1355 } }, ["ends"] = { { ["npcID"] = 154246, ["x"] = 0.31, ["y"] = 0.378, ["mapID"] = 1355 } }, ["coords"] = { ["x"] = 0.31, ["y"] = 0.378, ["source"] = "quest_giver", ["mapID"] = 1355 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56158] = { ["id"] = 56158, ["name"] = "Plug the Geysers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["description"] = "The elements are becoming increasingly unstable due to Azshara's abuse of the Tidestone. Geysers will be erupting nearby at any moment. Each eruption threatens to destroy the delicate balance of life on the surface. Take this sealant and use it to plug the geysers while I work to restore the elemental balance and redistribute the explosive underground pressure to a safer location.", ["rewardGold"] = 234000, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1750, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 154245, ["x"] = 0.458, ["y"] = 0.766, ["mapID"] = 1355 } }, ["ends"] = { { ["npcID"] = 154245, ["x"] = 0.458, ["y"] = 0.766, ["mapID"] = 1355 } }, ["coords"] = { ["x"] = 0.458, ["y"] = 0.766, ["source"] = "quest_giver", ["mapID"] = 1355 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56159] = { ["id"] = 56159, ["name"] = "Plug the Geysers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["description"] = "The geysers are dangerously unstable and will be erupting any moment now. I fear that Azshara's misuse of the Tidestone is causing irreparable damage to the elements within Nazjatar . We have to do what we can to prevent any further destruction. Take this sealant and use it to stave off the next round of eruptions. In the meantime, I will do what I can to stabilize the elements.", ["rewardGold"] = 341600, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1750, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 154244, ["x"] = 0.446, ["y"] = 0.452, ["mapID"] = 1355 } }, ["ends"] = { { ["npcID"] = 154244, ["x"] = 0.446, ["y"] = 0.452, ["mapID"] = 1355 } }, ["coords"] = { ["x"] = 0.446, ["y"] = 0.452, ["source"] = "quest_giver", ["mapID"] = 1355 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
