[56161] = { ["id"] = 56161, ["name"] = "Back Out to Sea", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56161 }, ["description"] = "Now that things're under control here, I'm sure they could use your help back in Nazjatar ! Why don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?", ["objectivesText"] = "Return to Newhome in Nazjatar .", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.5, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 9667 } }, ["questGiverID"] = 152206, ["questType"] = "standard", ["sourceQuests"] = { 57010 } },
