[56165] = { ["id"] = 56165, ["name"] = "Blueprint: Extraordinary Adventurer Augment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56165 }, ["description"] = "<This blueprint details how to condense an extraordinary amount of power into a ring or trinket! You should be able to upload the blueprint to Pascal-K1N6 's database in Rustbolt.>", ["objectivesText"] = "Upload the blueprint to Pascal-K1N6 's database. Provided item:", ["rewardGold"] = 257400, ["rewardItems"] = { 161374, 161375, 169007, 169112, 169134 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150359, ["x"] = 0.714, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169134 } },
[56166] = { ["id"] = 56166, ["name"] = "The Needs of the People", ["level"] = 26, ["requiredLevel"] = 26, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56166 }, ["description"] = "There are others in the camp that may be in need of aid. Ask around and see if there are any duties that you could take up. Be sure to report what you find to Speaker Utia.", ["objectivesText"] = "Speak to people in Mezzamere about things they need.", ["rewardGold"] = 234000, ["rewardXP"] = 3575, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56167] = { ["id"] = 56167, ["name"] = "Investigating the Highlands", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 114, ["storyline"] = { 55657, 56167 }, ["description"] = "When I first sensed these essences, I did not anticipate the importance of the role they would play. It is only a matter of time before all of the dragonflights are brought into the fold. Though I have reached out to the other Aspects, I have yet to hear from Alexstrasza. It is odd that she would be silent while these powers manifest. She was last seen in the Vermillion Redoubt in Twilight Highlands. I fear she may be in trouble. We must hurry.", ["objectivesText"] = "Meet Kalecgos in the Twilight Highlands.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.531, ["y"] = 0.709, ["mapID"] = 1473, ["npcID"] = 152365 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 152720, ["x"] = 0.28, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 9667 } }, ["questGiverID"] = 152365, ["questType"] = "standard", ["sourceQuests"] = { 55398 }, ["questLines"] = { { ["id"] = 958, ["name"] = "In the Shadow of Crimson Wings", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 241 },
