[56181] = { ["id"] = 56181, ["name"] = "This One's on Me", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55101, 55103, 56181 }, ["description"] = "I'm sure you agree that Pascal -K1N6 is the greatest invention you've ever seen! If you're not convinced yet, try to push him to his limits. I don't mind! Bring him more resources and blueprints -- he'll craft anything you need!", ["objectivesText"] = "Speak to Pascal at Rustbolt in Mechagon .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.712, ["y"] = 0.325, ["mapID"] = 1462, ["npcID"] = 152295 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152295, ["x"] = 0.712, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questGiverID"] = 152295, ["questType"] = "standard", ["questLines"] = { { ["id"] = 954, ["name"] = "Junkyard Tinkering", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56184] = { ["id"] = 56184, ["name"] = "Pirates, Sea Monsters, Robots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56184 }, ["description"] = "I finally found it! This is the resting place of my father, after his crew mutinied and left him here to die. I've scouted the island, and found the locations of three chests that contain mementoes of my father. Do this for me and my family. Recover my father's sword , clothing, and bones from the three chests I've marked.", ["objectivesText"] = "Recover DeMeza's father's Sword , Clothing and Bones. Progress: Help my recover the remains of my father.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 169164, 169165, 169166, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154335, ["x"] = 0.716, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154335, ["x"] = 0.716, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 970, ["name"] = "Visit from Dread Captain Demeza", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56185] = { ["id"] = 56185, ["name"] = "Whispers of N'Zoth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 1161, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56504 }, ["series"] = { 56186, 56187, 56188, 56189, 56267 }, ["description"] = "Are you curious how I came to be here, in the Chamber of Heart? Of course I arrived of my own volition, but there was quite a search for me, for a time. Kalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.", ["objectivesText"] = "Speak to Kalecgos in the Chamber of Heart.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 }, { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.153 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 9667 } }, ["questTurnInID"] = 154464, ["questType"] = "standard", ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[56186] = { ["id"] = 56186, ["name"] = "Spies to the Left and Right", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 433, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56185, 56187, 56188, 56189, 56267 }, ["description"] = "Ebonhorn cannot resist the whispers for long. The dark forces that once corrupted the black dragonflight seek to overwhelm the world once again. We need a way to fight back. While I am loathe to mention him, I do know of someone who has been studying the Old Gods in order to better combat their insidious power: Wrathion. The Black Prince has associates in Pandaria, in the Tavern of the Mists at the Veiled Stair. I suggest you begin your search there. Please hurry, $p.", ["objectivesText"] = "Seek out Wrathion at the Tavern in the Mists. Progress: The Black Prince isn't here. But we might be able to help you find him.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 170471 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 750 } }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.689, ["mapID"] = 1473, ["npcID"] = 152365 } }, ["ends"] = { { ["mapID"] = 433, ["npcID"] = 154500, ["x"] = 0.545, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 433, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 433 }, ["zone"] = { 9667 } }, ["questGiverID"] = 152365, ["questType"] = "standard", ["sourceQuests"] = { 56185, 56267 }, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 433 },
[56187] = { ["id"] = 56187, ["name"] = "Black Winged Shadow", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 6006, ["mapID"] = 433, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56185, 56186, 56188, 56189, 56267 }, ["description"] = "Obviously, the Black Prince isn't here. Trust me when I say he's not an easy one to find. If I were you, I'd make my way to Blackrock Mountain. There's a terrace carved into its slopes, where Nefarian once made his lair. Wrathion has been monitoring that place for a long time. Even if he's not there himself, you might find someone who knows where to look. And <class>... it's clear you're not the only one searching for him. Watch your back.", ["objectivesText"] = "Seek out Wrathion outside the entrance to Blackwing Descent. Progress: My head is still spinning... they showed me... such terrible... tempting things...", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 37863, 170483 }, ["starts"] = { { ["mapID"] = 433, ["npcID"] = 154500, ["x"] = 0.545, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 154874, ["x"] = 0.264, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 433, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 36, 433 }, ["zone"] = { 6006 } }, ["questType"] = "standard", ["sourceQuests"] = { 56186 }, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 36 },
[56188] = { ["id"] = 56188, ["name"] = "To the Catacombs!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 46, ["mapID"] = 13, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56185, 56186, 56187, 56189, 56267 }, ["description"] = "I held out as long as I could, but... the whispers were too strong. You must hurry to Karazhan. The Black Prince said he intended to study the artifacts stored within its catacombs. Please, do not allow my failure to bring about his doom!", ["objectivesText"] = "Seek out Wrathion outside the Karazhan Catacombs. Progress: <It seems the lookout gave his life in service to the Black Prince.>", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 23412, 23413, 23414, 131248, 142469, 170486 }, ["starts"] = { { ["mapID"] = 13, ["npcID"] = 154874, ["x"] = 0.482, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 154870, ["x"] = 0.47, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 13, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 13, 42 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 56187 }, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 42 },
[56189] = { ["id"] = 56189, ["name"] = "On the Trail of the Black Prince", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56185, 56186, 56187, 56188, 56267 }, ["description"] = "<It looks like a fight took place here. N'Zoth's agents must have already entered the catacombs beneath Karazhan. The dead lookout still has a set of keys on him. Perhaps they will unlock the door. With any luck, you can find Wrathion before N'Zoth's agents and gain something that can help Ebonhorn.>", ["objectivesText"] = "Enter the Karazhan Catacombs and search for a cure for Ebonhorn. Progress: <The note appears to have been left behind in a hurry, and deliberately placed where you would find it.>", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 170490 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 154870, ["x"] = 0.47, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 154870, ["x"] = 0.47, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questTurnInID"] = 154870, ["questType"] = "standard", ["sourceQuests"] = { 56188 }, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2232, ["db2PoiUiMapID"] = 1521, ["db2QuestSortName"] = "Day of the Dead" },
[56190] = { ["id"] = 56190, ["name"] = "Save Ebonhorn", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10638, ["mapID"] = 1473, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56504 }, ["description"] = "<The potion appears to be powerful and chaotic. It changes color seemingly at random. This must be the concoction Wrathion wrote about in his journal. Just standing near it grants you a sense of peace and clarity. You may not have found the Black Prince himself, but perhaps what he left behind for you can help Ebonhorn.>", ["objectivesText"] = "Return to the Chamber of Heart and treat Ebonhorn with the Potion of Mental Clarity .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169653 }, ["starts"] = { { ["x"] = 0.694, ["y"] = 0.166, ["mapID"] = 46, ["npcID"] = 155191 } }, ["ends"] = { { ["x"] = 0.694, ["y"] = 0.166, ["mapID"] = 46, ["npcID"] = 155191 } }, ["coords"] = { ["mapID"] = 46, ["x"] = 0.694, ["y"] = 0.166 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10638 } }, ["questGiverID"] = 155191, ["questTurnInID"] = 155191, ["questType"] = "standard", ["sourceQuests"] = { 56189 }, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[56205] = { ["id"] = 56205, ["name"] = "Just Ptrust Me On This", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 56205 }, ["description"] = "Ahhh, it is good to see you, <name>. How is de defective one? Still pleased to be at your side? I have given this some thought. Fear may still be what holds your not-so-little one back, but your love is what enables him to thrive without his wings. Perhaps that love will be what restores him to de skies. I am asking you to trust me. I wish to try something. If I am correct then de two of you will find yourselves airborne as nature intended!", ["objectivesText"] = "Place your faith in Pa'ku and Kua'fon.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 157782 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 127377, ["x"] = 0.711, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 127377, ["x"] = 0.711, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.711, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 50944 }, ["questLines"] = { { ["id"] = 945, ["name"] = "Wingless Redemption", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[56206] = { ["id"] = 56206, ["name"] = "Heroic: Battle for Stromgarde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 56206 }, ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 169196, 169197 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[56209] = { ["id"] = 56209, ["name"] = "The Halls of Origination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 84, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472 }, ["description"] = "It looks like the Halls of Origination have been claimed by a group o' tol'vir calling themselves the Amathet. I don't know much about them other than they're new in town and not the friendliest of types. We'll need tae get in there and re-activate the forge, or else Azeroth will be done for!", ["objectivesText"] = "Defeat the Amathet forces and reactivate the forge in the Halls of Origination. Progress: Azeroth's gonna be done for if we dun get this thing back online!", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 132514 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56374 }, ["questLines"] = { { ["id"] = 950, ["name"] = "The Forge of Origination", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2187, ["db2PoiUiMapID"] = 1542 },
[56210] = { ["id"] = 56210, ["name"] = "Scrying Stones", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56210 }, ["description"] = "I have a gift for you, <name>. It's a stone unlike anything you've seen before. To the uninformed, it may seem to be a simple rock, but it's far more precious than that. This is a scrying stone . It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. Use the stone to reveal treasure hidden away by ancient magic.", ["objectivesText"] = "Find treasures hidden away by magic within Nazjatar .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 167077, 169817 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153512, ["x"] = 0.49, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153512, ["x"] = 0.49, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56211] = { ["id"] = 56211, ["name"] = "Scrying Stones", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56211 }, ["description"] = "I have a gift for you, <name>. This stone is unlike anything you may have seen before. To the uninformed, it appears to be a simple rock, but it is far more precious than that. This is a scrying stone . It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. Use the stone to reveal treasure hidden away by ancient magic.", ["objectivesText"] = "Find treasures hidden away by magic within Nazjatar . Progress: Have you found any treasure?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 167077, 169817 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56214] = { ["id"] = 56214, ["name"] = "Good Girl", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56214 }, ["description"] = "I have learned so much by your side, I can't believe how many naga we've taken down! When you first arrived, I was skeptical that you'd make a difference. We've been down here, fighting, for so long. I had almost lost hope. But now, we see a way out of the darkness of the depths, finally! I took in a snapdragon pup when we formed Newhome, been training her ever since. I think... I think I'd like you to have her. She'll make a great mount... and loyal friend.", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 169199 }, ["starts"] = { { ["npcID"] = 151300 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 151300, ["questType"] = "standard" },
[56215] = { ["id"] = 56215, ["name"] = "Glittering Shell", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56215 }, ["description"] = "Hi, friend. I just wanted you to know that traveling with you has been the best ever! I never thought I could learn so much about fighting, but now I feel like I can actually hold my own. I will protect all of the wee ones that can't protect themselves! <Poen produces a crab from somewhere, it has a bright shell.> Like this little one. I found him a while back, while we were out. He looked so scared. Hey, why don't you take him?", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 169353 }, ["starts"] = { { ["npcID"] = 151310 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 151310, ["questType"] = "standard" },
[56216] = { ["id"] = 56216, ["name"] = "Last Heirloom", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56216 }, ["description"] = "We have encountered many foes together, and emerged victorious every time. I have you to thank for our safety this day, and my prowess in combat. I will be honest with you, friend. I did not think I would live this long. My people had families, once. Traditions. We would carve symbols into our talismans and pass them down from generation to generation of deep sea hunters. Charms for luck, or prowess, each family had their own. This is mine. I have none to pass it on to. I would like you to have it", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 170155 }, ["starts"] = { { ["npcID"] = 149805 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 149805, ["questType"] = "standard" },
[56217] = { ["id"] = 56217, ["name"] = "Wild Tame", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56217 }, ["description"] = "In our time together, I have learned much. Both about my own abilities, and about your people. You are selfless in the face of challenge, much like our own. I consider us kin. For some time, I have been training a snapdragon I found as a pup. He is a worthy mount, and I have been waiting for a worthy hunter to ride him. I believe I have found that hunter. Here, he is yours.", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 169199, 169200 }, ["starts"] = { { ["npcID"] = 149804 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 149804, ["questType"] = "standard" },
[56218] = { ["id"] = 56218, ["name"] = "Beauty in the Deeps", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56218 }, ["description"] = "We have slain many enemies, spilled much blood on the sand. My skills have improved tenfold fighting at your side. Yet let us not forget that once, this was a place of peace. Once, my people walked amongst the caverns and reefs undisturbed. There is beauty, here, in the depths, all around us. Take a moment, sit, and enjoy your serene surroundings. Look here, a crab with a shell of brilliant colors. You see? There is beauty here, even now.", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 169353, 169354 }, ["starts"] = { { ["npcID"] = 149803 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 149803, ["questType"] = "standard" },
[56219] = { ["id"] = 56219, ["name"] = "Tome of Tears", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56219 }, ["description"] = "We've been fighting side by side for a while now. I didn't think an old salt like me could get any better at killing naga, but here we are. I have something to show you... <Vim produces a book from his pack.> Worst thing we can do is forget. So many names I've written in this book, each and every one of them an Unshackled. All of them gone, now. I will never forget their names. I want you to have it. Tell people. Tell them who they were, and what we have done here.", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 170154, 170155 }, ["starts"] = { { ["npcID"] = 151309 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 151309, ["questType"] = "standard" },
[56222] = { ["id"] = 56222, ["name"] = "WANTED: Lady Naz'jess", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56222 }, ["description"] = "Wanted for attacks against the people of Nazjatar . Lady Naz'jess has been driving the weapon masters to create crueler devices. Last seen skulking about Zanj'ir Terrace. She is vicious, proceed with caution. Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the head of Lady Naz'jess. Progress: Has her command come to an end?", ["rewardGold"] = 619600, ["rewardItems"] = { 168265 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1746, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.48, ["y"] = 0.615, ["mapID"] = 1355, ["objectID"] = 327585 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56223] = { ["id"] = 56223, ["name"] = "WANTED: Commander Sarj'eth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56223 }, ["description"] = "Wanted for attacks against the people of Nazjatar . Commander Sarj'eth has attempted to enslave many Horde survivors. He commands slavers in Zanj'ir Terrace. Extreme caution advised! Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the head of Commander Sarj'eth. Progress: Did the brave commander reach the end of his days?", ["rewardGold"] = 619600, ["rewardItems"] = { 168317 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1745, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.479, ["y"] = 0.613, ["mapID"] = 1355, ["objectID"] = 327585 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56224] = { ["id"] = 56224, ["name"] = "WANTED: Lord Ha'kass", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56224 }, ["description"] = "Wanted for attacks against the people of Nazjatar . Lord Ha'kass has attempted to enslave many Horde survivors. He commands slavers in Zanj'ir Wash. Extreme caution advised! Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the head of Lord Ha'kass. Progress: Was the villain found?", ["rewardGold"] = 468000, ["rewardItems"] = { 168318 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1746, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.48, ["y"] = 0.615, ["mapID"] = 1355, ["objectID"] = 327585 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56225] = { ["id"] = 56225, ["name"] = "WANTED: Lady Narjiss", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56225 }, ["description"] = "Wanted for attacks against the Horde! Lady Narjiss is responsible for leading several raids and ambushes against our soldiers. Last seen on the outskirts of Zanj'ir Terrace. Extreme caution advised! Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the head of Lady Narjiss. Progress: Did you silence her?", ["rewardGold"] = 619600, ["rewardItems"] = { 168319 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1745, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.479, ["y"] = 0.613, ["mapID"] = 1355, ["objectID"] = 327585 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56226] = { ["id"] = 56226, ["name"] = "WANTED: Gler'thogg", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56226 }, ["description"] = "Gler'thogg is responsible for the death and torture of many of the Unshackled. They have shared with us their pain. Bring back his eye. He dwells in the Deepcoil Tunnels. Extreme caution advised! Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the Eye of Gler'thogg . Progress: Is this your first enucleation?", ["rewardGold"] = 468000, ["rewardItems"] = { 168321 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1746, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.48, ["y"] = 0.615, ["mapID"] = 1355, ["objectID"] = 327585 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
