[56234] = { ["id"] = 56234, ["name"] = "Friends In Need", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "I doubt that will be the last we've seen of Priscilla, but at least she is no longer one of our immediate concerns. We must think carefully before making our next move. In the meantime we should continue to build upon our relationship with our new allies, the Ankoan. Work with them to secure the area and hone their skills, we're not out of the woods yet. I fear the biggest battle is still to come. Let's show them that together we can take on Azshara's forces and succeed!", ["objectivesText"] = "Support your allies in Nazjatar by gaining 3000 experience combined between Farseer Ori, Hunter Akana, and Bladesman Inowari.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 168847, 169489, 169910, 170153, 170161 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55937 }, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 38, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56235] = { ["id"] = 56235, ["name"] = "Down Into Nazjatar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54012, 54015, 54018, 54021, 55053, 55054, 55092, 55094, 55374, 55384, 55385, 55400, 55407, 55425, 55469, 55481, 55482, 55485, 55486, 55488, 55489, 55490, 55497, 55500, 55533, 55618, 55799, 55851, 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56044, 56045, 56046, 56047, 56063, 56235, 56236, 56429, 57010 }, ["description"] = "We have much to do <name>. However our troops are weary and need rest. Decisions made when tired are often the wrong ones. These \"Unshackled\" have offered to aid us with what forces they have. If we hope to survive down here against Azshara's forces, we will need to support our new allies. Join one of their hunters and aid them in their tasks, we will remain here and discuss our next move.", ["objectivesText"] = "Support your allies in Nazjatar by getting one to rank 3.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168846 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 }, ["questLines"] = { { ["id"] = 1023, ["name"] = "Azshara's Trap", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56236] = { ["id"] = 56236, ["name"] = "Down But Not Out", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["series"] = { 55869 }, ["description"] = "Ashvane won't trouble us for now, but our situation remains perilous. I must consider our next move, <name>. In the meantime we should continue to build upon our relationship with our new allies, the Unshackled. Test them in combat, train them while you can, we will need their aid in the battles to come. We will show them that through unity there are no obstacles that can stand in our way.", ["objectivesText"] = "Support your allies in Nazjatar by gaining 2400 experience combined between Vim Brineheart, Poen Gillbrack, and Neri Sharpfin.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 29792, 29793, 29794, 30394, 30395, 30396, 30399, 30522, 31312, 31313, 31314, 31315, 33226, 35925, 35926, 35927, 35928, 35932, 35933, 35934, 35935, 37829, 38711, 39015, 39044, 39076, 39777, 39788, 39790, 39836, 52596, 52622, 54213, 59050, 59051, 59052, 63542, 63543, 63544, 63545, 63546, 63547, 63548, 63549, 88704, 88705, 88706, 88707, 88708, 112867, 112868, 112869, 112870, 112871, 112872, 112873, 112874, 131285, 131432, 131433, 131516, 142054, 143740, 143741, 147838, 159146, 159827, 167077, 168053, 168846, 168847, 169489, 170085, 170100, 170103, 170153, 170167, 170171, 170176, 170183, 170184, 181368, 181377, 181569, 181576, 181577, 181589, 181591, 181603, 181612, 181703, 182180, 182484, 182493, 182502, 182511, 183744, 184294, 184363, 184765, 184767, 184768, 184839, 184843, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187329, 187330, 187331, 187467, 242241, 242386, 244846, 244888, 249620, 249627 }, ["starts"] = { { 