[56239] = { ["id"] = 56239, ["name"] = "Strange Silver Knife", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56239 }, ["series"] = { 56241, 56243, 56246, 56247 }, ["description"] = "<This silver knife is small and lightly decorated, you found it inside of a chest. It was more likely used for eating or preparing food than combat. What would the naga need with such a thing? One of the Ankoan may know more...>", ["objectivesText"] = "Ask the Ankoan about the knife. Provided item:", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 167077, 169215 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169215 } },
[56240] = { ["id"] = 56240, ["name"] = "Strange Silver Knife", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56240 }, ["series"] = { 56242, 56244, 56245, 56248 }, ["description"] = "<This silver knife is small and lightly decorated, you found it inside of a chest. It was more likely used for eating or preparing food than combat. What would the naga need with such a thing? One of the Unshackled may know more...>", ["objectivesText"] = "Ask the Unshackled about the knife. Provided item:", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 167077, 169215, 169216 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153514, ["x"] = 0.492, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169216 } },
[56241] = { ["id"] = 56241, ["name"] = "Preserved Clues", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56241 }, ["series"] = { 56239, 56243, 56246, 56247 }, ["description"] = "We have found similar chests, as you describe. We believe they were left behind by one that came before the naga. Some are even locked by odd arcane runes, the naga seem most interested in those. I know little about them, save that we find them most often in the city ruins. If you seek to decipher their history, I would begin there.", ["objectivesText"] = "Search in Zin-Azshari for information about the strange arcane chests.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questTurnInID"] = 153510, ["questType"] = "standard", ["sourceQuests"] = { 56239 } },
[56242] = { ["id"] = 56242, ["name"] = "Preserved Clues", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56242 }, ["series"] = { 56240, 56244, 56245, 56248 }, ["description"] = "If you find anything else in those chests that you don't need, you feel free to bring it on over my way. Found a few of them myself. Don't look like they belong to the naga, probably someone that lived in the city. Some are locked tight by arcane magic, seen the naga taking those back with them. Probably got the good stuff in there. I don't know much more than that. If you want a history lesson, I'd snoop around the city ruins.", ["objectivesText"] = "Search in Zin-Azshari for information about the strange arcane chests.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 169216 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153514, ["x"] = 0.492, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153514, ["x"] = 0.492, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questTurnInID"] = 153514, ["questType"] = "standard", ["sourceQuests"] = { 56240 } },
[56243] = { ["id"] = 56243, ["name"] = "Diaries of the Dead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56243 }, ["series"] = { 56239, 56241, 56246, 56247 }, ["description"] = "<The enchantments preserving this journal are intact, but fading. It appears to be the diary of a citizen of the city. You turn to a random page...> Then he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas. Of course, he was bitten on the leg by a lesser summon, and... <It continues -- not useful, but you surmise there may be more such tomes.>", ["objectivesText"] = "Search Zin-Azshari in Nazjatar for additional diaries. Progress: <A preserved tome.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.814, ["y"] = 0.454, ["mapID"] = 1355, ["objectID"] = 327591 } }, ["ends"] = { { ["x"] = 0.814, ["y"] = 0.454, ["mapID"] = 1355, ["objectID"] = 327591 } }, ["coords"] = { ["mapID"] = 1355, ["x"] = 0.814, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56241 } },
[56244] = { ["id"] = 56244, ["name"] = "Diaries of the Dead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56244 }, ["series"] = { 56240, 56242, 56245, 56248 }, ["description"] = "<The enchantments preserving this journal are intact, but fading. It appears to be the diary of a citizen of the city. You turn to a random page...> Then he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas. Of course, he was bitten on the leg by a lesser summon, and... <It continues -- not useful, but you surmise there may be more such tomes.>", ["objectivesText"] = "Search Zin-Azshari in Nazjatar for additional diaries. Progress: <A preserved tome.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.814, ["y"] = 0.454, ["mapID"] = 1355, ["objectID"] = 327591 } }, ["ends"] = { { ["x"] = 0.814, ["y"] = 0.454, ["mapID"] = 1355, ["objectID"] = 327591 } }, ["coords"] = { ["mapID"] = 1355, ["x"] = 0.814, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56242 } },
[56245] = { ["id"] = 56245, ["name"] = "Enchanted Lock", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56245 }, ["series"] = { 56240, 56242, 56244, 56248 }, ["description"] = "<The lock appears to be secured by a magical mechanism. It is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle. You look around the room, and see something odd in the water.>", ["objectivesText"] = "Solve Mardivas' arcane puzzle to unlock the enchanted lock . Progress: <The lock hums.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.788, ["y"] = 0.411, ["mapID"] = 1355, ["objectID"] = 327592 } }, ["ends"] = { { ["x"] = 0.788, ["y"] = 0.411, ["mapID"] = 1355, ["objectID"] = 327592 } }, ["coords"] = { ["mapID"] = 1355, ["x"] = 0.788, ["y"] = 0.411 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56244 } },
[56246] = { ["id"] = 56246, ["name"] = "Enchanted Lock", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56246 }, ["series"] = { 56239, 56241, 56243, 56247 }, ["description"] = "<The lock appears to be secured by a magical mechanism. It is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle. You look around the room, and see something odd in the water.>", ["objectivesText"] = "Solve Mardivas' arcane puzzle to unlock the enchanted lock . Progress: <The lock hums.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.788, ["y"] = 0.411, ["mapID"] = 1355, ["objectID"] = 327592 } }, ["ends"] = { { ["x"] = 0.788, ["y"] = 0.411, ["mapID"] = 1355, ["objectID"] = 327592 } }, ["coords"] = { ["mapID"] = 1355, ["x"] = 0.788, ["y"] = 0.411 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56243 } },
[56247] = { ["id"] = 56247, ["name"] = "Treasure Tale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56247 }, ["series"] = { 56239, 56241, 56243, 56246 }, ["description"] = "<You discovered the history of Mardivas, a sorcerer that once lived in the city and the crafter of the arcane chests scattered around Nazjatar . From the sounds of it, he was not well-liked, which worked out for him, as he did not much like others. You also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey. Artisan Itanu will surely enjoy hearing the end of this tale.>", ["objectivesText"] = "Return to Artisan Itanu in Nazjatar .", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 167077, 169215 }, ["starts"] = { { ["x"] = 0.788, ["y"] = 0.411, ["mapID"] = 1355, ["objectID"] = 327592 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56246 } },
[56248] = { ["id"] = 56248, ["name"] = "Treasure Tale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56248 }, ["series"] = { 56240, 56242, 56244, 56245 }, ["description"] = "<You discovered the history of Mardivas, a sorcerer that once lived in the city and the crafter of the arcane chests scattered around Nazjatar . From the sounds of it, he was not well-liked, which worked out for him, as he did not much like others. You also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey. Finder Palta will surely enjoy hearing the end of this tale.>", ["objectivesText"] = "Return to Finder Palta in Newhome in Nazjatar .", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 167077, 169215 }, ["starts"] = { { ["x"] = 0.788, ["y"] = 0.411, ["mapID"] = 1355, ["objectID"] = 327592 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153514, ["x"] = 0.492, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56245 } },
[56249] = { ["id"] = 56249, ["name"] = "I Am the Trashmaster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8499, ["mapID"] = 1165, ["storyline"] = { 56249 }, ["description"] = "Whatcha got there, richmon? Ha! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted! So you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. You just give dat ol' thing to me, an Jani will be takin' care o' you...", ["objectivesText"] = "Give Jani the Trashmaster's Mantle .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 168970, 169394 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 126334, ["x"] = 0.355, ["y"] = 0.078 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 126334, ["x"] = 0.355, ["y"] = 0.078 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.078 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[56250] = { ["id"] = 56250, ["name"] = "I Am the Trashmaster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 56250 }, ["description"] = "Whatcha got there, richmon? Ha! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted! So you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. You just give dat ol' thing to me, an Jani will be takin' care o' you...", ["objectivesText"] = "Give Jani the Trashmaster's Mantle .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 168970, 169394 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 136559, ["x"] = 0.362, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 136559, ["x"] = 0.362, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[56256] = { ["id"] = 56256, ["name"] = "The Battle of Alterac", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 2597, ["mapID"] = 25, ["storyline"] = { 56256 }, ["description"] = "The Explorers' League believes there are artifacts in Alterac Valley , but the Frostwolf orcs won't let us explore. We can't allow the Horde to stop our scholarly pursuits! Defeat the Frostwolf general, Drek'Thar . With him dead, the orcs will lose their edge. Drek'Thar is in Frostwolf Keep, in the south of Alterac Valley . Vanquish him, and then return to me.", ["objectivesText"] = "Enter Alterac Valley , defeat the Horde general Drek'thar .", ["rewardGold"] = 938400, ["rewardXP"] = 4150, ["starts"] = { { ["npcID"] = 154478 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 13816, ["x"] = 0.452, ["y"] = 0.452 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 2597 } }, ["questGiverID"] = 154478, ["questType"] = "pvp" },
[56257] = { ["id"] = 56257, ["name"] = "The Battle for Alterac", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 2597, ["mapID"] = 25, ["storyline"] = { 56257 }, ["description"] = "The Stormpike dwarves and their allies have invaded Alterac Valley , and we must drive them out! To win the battle for Alterac, we must defeat their general, Vanndar Stormpike ! You will find Vanndar in Dun Baldar, in the north of Alterac Valley . Destroy him, <name>, and then return to me.", ["objectivesText"] = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike .", ["rewardGold"] = 938400, ["rewardXP"] = 4150, ["rewardCurrencies"] = { { ["id"] = 1602, ["amount"] = 150 } }, ["starts"] = { { ["x"] = 0.55, ["y"] = 0.872, ["mapID"] = 91, ["npcID"] = 154473 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 13817, ["x"] = 0.585, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 10458 } }, ["questGiverID"] = 154473, ["questType"] = "pvp" },
[56258] = { ["id"] = 56258, ["name"] = "Ivus the Forest Lord", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 2597, ["storyline"] = { 56258 }, ["description"] = "The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked. The damage has grown too great for the Circle to control! Ivus must be called to our aid. The Frostwolf soldiers carry elemental charms called storm crystals . We can use the charms to conjure Ivus. Venture forth and claim the crystals, <name>!", ["objectivesText"] = "Slay Horde and loot a Storm Crystal and return it to Archdruid Renferal in Alterac Valley . Progress: Have you brought us some crystals, <name>?", ["rewardItems"] = { 17423 }, ["starts"] = { { ["x"] = 0.439, ["y"] = 0.126, ["mapID"] = 1537, ["npcID"] = 154476 } }, ["ends"] = { { ["x"] = 0.439, ["y"] = 0.126, ["mapID"] = 1537, ["npcID"] = 154476 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.439, ["y"] = 0.126 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 154476, ["questTurnInID"] = 154476, ["questType"] = "pvp" },
[56259] = { ["id"] = 56259, ["name"] = "Lokholar the Ice Lord", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 2597, ["storyline"] = { 56259 }, ["description"] = "I come from Thunder Bluff, <race>. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times. But let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin. Victory will be assured when the elemental lord is loosed upon the Stormpike army.", ["objectivesText"] = "Slay Alliance and loot Stormpike Blood and return it to Primalist Thurloga within Frostwolf Village in Alterac Valley . Progress: Have you come with an offering?", ["rewardItems"] = { 17306 }, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.851, ["mapID"] = 1537, ["npcID"] = 154474 } }, ["ends"] = { { ["x"] = 0.501, ["y"] = 0.851, ["mapID"] = 1537, ["npcID"] = 154474 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.501, ["y"] = 0.851 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 154474, ["questTurnInID"] = 154474, ["questType"] = "pvp" },
[56260] = { ["id"] = 56260, ["name"] = "Unlocking the Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 56260 }, ["description"] = "There's somethin' special waitin' fer ye back in the Chamber of Heart, champion. I won't spoil it, but ye best get back there as quick as ye can.", ["objectivesText"] = "Return to the Chamber of Heart.", ["rewardGold"] = 23400, ["rewardItems"] = { 169768 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 154465, ["x"] = 0.506, ["y"] = 0.6505 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 154465, ["x"] = 0.506, ["y"] = 0.6505 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.6505 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questTurnInID"] = 154465, ["questType"] = "standard", ["nextQuests"] = { 56401 } },
[56261] = { ["id"] = 56261, ["name"] = "Return to the Heart", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56261 }, ["description"] = "Greetings, Champion of Azeroth. MOTHER's been monitorin' yer progress with the Heart of Azeroth, and is mighty pleased with the work you've done tae make it stronger. At least, we think she's pleased. It's difficult tae tell at times. Regardless, come back tae the Chamber of Heart when ye've got a chance. There's more that needs doin'.", ["objectivesText"] = "Return to the Chamber of Heart.", ["rewardGold"] = 23400, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.153 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questTurnInID"] = 154464, ["questType"] = "standard", ["sourceQuests"] = { 57010 }, ["nextQuests"] = { 55519 } },
[56262] = { ["id"] = 56262, ["name"] = "Back to the Chamber", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56262 }, ["description"] = "The Heart o' Azeroth is gettin' stronger every day, and it's makin' a difference. Make yer way tae the Chamber o' Heart, champion. Yer talents are needed.", ["objectivesText"] = "Return to the Chamber of Heart.", ["rewardGold"] = 23400, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.153 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questTurnInID"] = 154464, ["questType"] = "standard", ["nextQuests"] = { 55732 } },
[56263] = { ["id"] = 56263, ["name"] = "Unlocking the Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56263 }, ["description"] = "There's somethin' special waitin' fer ye back in the Chamber of Heart, champion. I won't spoil it, but ye best get back there as quick as ye can.", ["objectivesText"] = "Return to the Chamber of Heart.", ["rewardGold"] = 23400, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.153 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questTurnInID"] = 154464, ["questType"] = "standard", ["nextQuests"] = { 56401 } },
[56264] = { ["id"] = 56264, ["name"] = "We've Got Crabs!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56264 }, ["description"] = "<name>, you're just in time. Everything's ready for the crab hunt! Okay, okay... I know what you're thinking. A founding member of D.E.H.T.A. that condones hunting? I'm going to level with you, <name>. I've got a bar full of hungry murlocs that only eat three things: crabs, fish, and people. If that's not reason enough, crabs are overpopulated in this region and they're decimating the local grub worm population! How many innocent grub worms need to die before we do something, <name>?", ["objectivesText"] = "Collect 12 Crackleclaw Crabs . Progress: How many innocent grub worms need to die before we do something, <name>?", ["rewardGold"] = 234000, ["rewardItems"] = { 168628 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1747, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.254667, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56265] = { ["id"] = 56265, ["name"] = "Drunk Angry Murlocs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56265 }, ["description"] = "Those no-good Bloodfins ran off with all of the beer! I've been experimenting with brews that only use ingredients native to Nazjatar , but it's still a work in progress. For now, I must rely on whatever I can scrounge up from the shipwreck. My supply of beer was already limited, but now it's all gone thanks to those thieving Bloodfin murlocs! We're going to have some very angry customers here if we don't get it back. Please recover the stolen lager from Bloodfin Village before it's too late!", ["objectivesText"] = "Collect 12 Ocean \"Infused\" Lagers . Progress: Please tell me you found the beer.", ["rewardGold"] = 176280, ["rewardItems"] = { 168629, 169280, 170075 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1747, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.254667, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56266] = { ["id"] = 56266, ["name"] = "Mgglurky's Mugglrgl", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56266 }, ["description"] = "My cook, Mgglurky, lost his mugglrgl and he's refusing to work until he gets it back. I've got a bar full of hungry murlocs and nothing to feed them until Mgglurky starts cooking. If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands! I don't know about you, but I definitely don't want to be the main course tonight. There were some Bloodfins lurking around earlier. Search Bloodfin Village for the mugglrgl and bring it back to me once you find it.", ["objectivesText"] = "Retrieve Mgglurky's Mugglrgl from Bloodfin Village. Progress: If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!", ["rewardGold"] = 234000, ["rewardItems"] = { 168647 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1745, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.254667, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56267] = { ["id"] = 56267, ["name"] = "Whispers of N'Zoth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["series"] = { 56185, 56186, 56187, 56188, 56189 }, ["description"] = "Are you curious how I came to be here, in the Chamber of Heart? Of course I arrived of my own volition, but there was quite a search for me, for a time. Kalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["npcID"] = 154465, ["x"] = 0.51, ["y"] = 0.888, ["mapID"] = 1165 }, { ["npcID"] = 155496, ["x"] = 0.852, ["y"] = 0.322, ["mapID"] = 84 }, { ["npcID"] = 155496, ["x"] = 0.466, ["y"] = 0.646, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 152365, ["x"] = 0.524, ["y"] = 0.69, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.51, ["y"] = 0.888, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 84, 1165 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 1, ["flags"] = 0 } } },
[56301] = { ["id"] = 56301, ["name"] = "Go For The Gold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56301 }, ["description"] = "I've heard lot's of stories about dead fathers, mothers, and family treasures. Don't believe any of it. We're all here to get any pirate gold, before these mecha-fools get it first! If there's gold to be had here, it's in that fat chest the murlocs are guarding. Kill their chief, empty out the chest, and we'll split it fifty-fifty, since I'm telling ya about it.", ["objectivesText"] = "Recover the Murloc Treasure Bag. Progress: Go get the gold!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 169221, 169222 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154485, ["x"] = 0.215, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154485, ["x"] = 0.215, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.215, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56304] = { ["id"] = 56304, ["name"] = "The High Life", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56304, 56321, 56422 }, ["description"] = "You there, I require some help. Everyone where I once called home lost their lives to the flood. I still don't know what became of my father, Corin. It pains me to return to the estates, and there are vengeful spirits who haunt the once pristine grounds. Will you help me find out what happened to my father?", ["objectivesText"] = "Accompany Kelya Moonfall into the Highborne Estates to search for the spirit of her father.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154574, ["x"] = 0.742, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154574, ["x"] = 0.742, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questTurnInID"] = 154574, ["questType"] = "standard", ["sourceQuests"] = { 55500, 56156 }, ["questLines"] = { { ["id"] = 948, ["name"] = "Kelya Moonfall", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56305] = { ["id"] = 56305, ["name"] = "Let's Fish!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55055, 55298, 55339, 56305 }, ["description"] = "We may need the help of some friends to land this fish! Use the Hundred-Fathom Lure when you're ready to start.", ["objectivesText"] = "Catch and kill the Deepwater Maw . Progress: Let's fish!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 151462, ["x"] = 0.37, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151462, ["x"] = 0.37, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "group", ["sourceQuests"] = { 55055 }, ["questLines"] = { { ["id"] = 924, ["name"] = "Mechagon Fishing", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56306] = { ["id"] = 56306, ["name"] = "The Family Jewels", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56306 }, ["description"] = "Darn pirates stole my jewels... err, I mean my sister's... uh, mom's jewelry. Yeah, that's the story! Point is, they stole it, and it's all out there strewn around in the mud, and treasure chests. Maybe on a few of the robots and murlocs. My mom's not greedy, she just wants a few of the necklaces with gold and lots of diamonds. I'd pay ya for those.", ["objectivesText"] = "Recover 75 Family Jewels Progress: Go steal those jewels back for my brother!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 169241 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154511, ["x"] = 0.242, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154511, ["x"] = 0.242, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56308] = { ["id"] = 56308, ["name"] = "Assault: Aqir Unearthed", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56308 }, ["description"] = "Our position is being overrun. The aqir are surging in greater numbers than I've ever seen! I'm not sure how long we'll be able to hold the line. We need you to drive them back!", ["objectivesText"] = "Drive back the Aqir Assault in Uldum . Progress: Our men can only hold out so long.", ["rewardXP"] = 10225, ["rewardItems"] = { 169432, 174960 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Drive back the Aqir", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[56309] = { ["id"] = 56309, ["name"] = "City of Drowned Friends", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56309 }, ["series"] = { 56311, 56313, 56315 }, ["description"] = "Champion, I have a personal favor to ask of you that I do not feel I can ask of any of my sentinels. This... this is not on behalf of the Alliance, or the war, or even our battle against Azshara. This is a favor for me. When I was a little girl, my city was attacked by the Legion. Many of the survivors fled here only to drown or worse. I must know their fate. Will you help me search for signs?", ["objectivesText"] = "Help Shandris Feathermoon search the Drowned Market.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154522, ["x"] = 0.76, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154660, ["x"] = 0.74, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56310] = { ["id"] = 56310, ["name"] = "City of Drowned Friends", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56310 }, ["series"] = { 56312, 56314, 56316 }, ["description"] = "Champion, I have a personal favor to ask of you. This is not on behalf of the Horde or the war effort. It has been over ten thousand years since I last walked these streets. I knew many of these people, even trained some of them. Will you walk with me as I learn their fates? The road is dangerous, and I do not trust myself to maintain calm as I try to resurface old grief.", ["objectivesText"] = "Help First Arcanist Thalyssra search the Drowned Market.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154520, ["x"] = 0.735, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154661, ["x"] = 0.74, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56311] = { ["id"] = 56311, ["name"] = "The Ever Drowning", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56311 }, ["series"] = { 56309, 56313, 56315 }, ["description"] = "Stay close, Champion. I have some magical items that might help us defend briefly against magic attacks, but Azshara was the greatest mage our kind has ever known. I do not feel confident that these trinkets will hold back her power for long, or even be usable afterward. Speak with me when you are ready.", ["objectivesText"] = "Escort Shandris Feathermoon through the Drowned Market.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154660, ["x"] = 0.74, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155071, ["x"] = 0.791, ["y"] = 0.447 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56309 } },
[56312] = { ["id"] = 56312, ["name"] = "The Ever Drowning", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56312 }, ["series"] = { 56310, 56314, 56316 }, ["description"] = "Queen Azshara has her eye on us now. We must proceed with caution. I do not know what she may try but stay close to me. Whatever this threat is we must pass through it if we are to find Sivara. Speak with me when you are ready to proceed.", ["objectivesText"] = "Escort First Arcanist Thalyssra through the Drowned Market.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154661, ["x"] = 0.74, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155325, ["x"] = 0.789333, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56310 } },
[56313] = { ["id"] = 56313, ["name"] = "The Warbringer", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56313 }, ["series"] = { 56309, 56311, 56315 }, ["description"] = "We are standing in the center of some very powerful magics. An echo of something Azshara did long ago. If you are feeling brave enough to commune with this echo, I will stand guard as you do.", ["objectivesText"] = "Commune with the Memory of the Pact . Progress: Be ready for anything.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 82589, 82590, 82591, 82592, 82593, 82594, 82595, 82596, 82597, 82598 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 155071, ["x"] = 0.791, ["y"] = 0.447 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155071, ["x"] = 0.791, ["y"] = 0.447 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.791, ["y"] = 0.447 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56311 } },
[56314] = { ["id"] = 56314, ["name"] = "The Warbringer", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56314 }, ["series"] = { 56310, 56312, 56316 }, ["description"] = "We are standing in the center of some very powerful magics. An echo of something Azshara did long ago. If you are feeling brave enough to commune with this echo, I will stand guard as you do.", ["objectivesText"] = "Commune with the Memory of the Pact . Progress: Be ready for anything.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 82589, 82590, 82591, 82592, 82593, 82594, 82595, 82596, 82597, 82598 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 155325, ["x"] = 0.789333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155325, ["x"] = 0.789333, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.789333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56312 } },
[56315] = { ["id"] = 56315, ["name"] = "They Made Their Choice", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56315 }, ["series"] = { 56309, 56311, 56313 }, ["description"] = "It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well! Those who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. I am almost afraid of what we will find if we do find my friend. Wait, did you hear something?", ["objectivesText"] = "Aid Shandris Feathermoon . Progress: Thrice damned Azshara. Her evil knows no bounds.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 155071, ["x"] = 0.791, ["y"] = 0.447 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155071, ["x"] = 0.791, ["y"] = 0.447 }, { ["mapID"] = 1355, ["npcID"] = 155237, ["x"] = 0.798, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.791, ["y"] = 0.447 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56313 } },
[56316] = { ["id"] = 56316, ["name"] = "They Made Their Choice", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56316 }, ["series"] = { 56310, 56312, 56314 }, ["description"] = "It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well! Those who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. I am almost afraid to find Sivara. Wait, did you hear something?", ["objectivesText"] = "Aid First Arcanist Thalyssra . Progress: Thrice damned Azshara. Her evil knows no bounds.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 155325, ["x"] = 0.789333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155325, ["x"] = 0.789333, ["y"] = 0.446667 }, { ["mapID"] = 1355, ["npcID"] = 155342, ["x"] = 0.798, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.789333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56314 } },
[56319] = { ["id"] = 56319, ["name"] = "The Quickcharge Contract", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55210, 55211, 56319, 56320 }, ["description"] = "Wondrous news, dear test subject! My dear brother and I have restored 65% of the functionality of our research laboratory. We are hoping to resume our regular research schedule shortly, but require a fresh batch of brave test subjects to help us push the laws of nature and science to their limits! If you're interested, you'll just need to agree to our standard verbal contract first...", ["objectivesText"] = "Agree to the Quickcharge Contract. Progress: How can I help you, dear test subject?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 959, ["name"] = "Quickcharge Experiments", ["orderIndex"] = 2, ["flags"] = 0 } } },
[56320] = { ["id"] = 56320, ["name"] = "Your First Charge is Free!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55210, 55211, 56319, 56320 }, ["description"] = "Do you feel the energy rippling through the ground here, my dear test subject? <Flip inhales deeply.> Without that constant bristle of electricity, nothing of any meaning would exist. My dear sister and I have tapped into a high-voltage power line buried here, but the real juice is over in Bondo's Yard. He selfishly hoards access to the heftiest power line in Mechagon ! If you want to recharge your empty energy cells, you're going to have to get access to the Charging Station from Flux.", ["objectivesText"] = "Gain access to the Charging Station in Bondo's Yard, then use it to charge an Empty Energy Cell.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150630, ["x"] = 0.721, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.721, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 55210 }, ["questLines"] = { { ["id"] = 953, ["name"] = "Rustbolt Energy", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 959, ["name"] = "Quickcharge Experiments", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56321] = { ["id"] = 56321, ["name"] = "Saving Corin", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56304, 56321, 56422 }, ["description"] = "My father is being tortured by that naga! <name>, I need you to help me save him. We can't let his spirit be a slave to the naga. Hurry, if we don't act now he will end up like the rest of them!", ["objectivesText"] = "Defeat Shadowcaster Vixtris .", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["x"] = 0.8, ["y"] = 0.314, ["mapID"] = 1355, ["npcID"] = 154514 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154601, ["x"] = 0.802, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.802, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questGiverID"] = 154514, ["questType"] = "standard", ["sourceQuests"] = { 56304 }, ["questLines"] = { { ["id"] = 948, ["name"] = "Kelya Moonfall", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56322] = { ["id"] = 56322, ["name"] = "Contained Alemental", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 8, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 56322 }, ["description"] = "<As the brew is returned to its natural, dormant form, a strange keg appears. Perhaps Brewmaster Tsing knows more about such a strange occurrence.>", ["objectivesText"] = "Talk to Brewmaster Tsing in the Brewfest grounds.", ["rewardGold"] = 234000, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["x"] = 0.555, ["y"] = 0.377, ["mapID"] = 27, ["objectID"] = 327669 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 73913, ["x"] = 0.554, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[56324] = { ["id"] = 56324, ["name"] = "Your First Charge Ain't Free!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56324 }, ["description"] = "You lookin' to charge some energy cells off of our tower of power? I ain't surprised - everyone is. And everyone PAYS. You got that or I got ta say it again? < Flux spits behind her.> I can tell you're a first-timer. Bondo's got a special deal for you flashfoots. Small access fee, one charge only. Deal? You ain't gettin' any other offers.", ["objectivesText"] = "Pay Flux 's access fee, then use the Charging Station to charge an Empty Energy Cell. Progress: You lookin' to charge some energy cells off of our tower of power? I ain't surprised - everyone is. And everyone PAYS. You got that or I got ta say it again? < Flux spits over her shoulder.> I can tell you're a first-timer. Bondo's got a special deal for you flashfoots. Small access fee, one charge only. You ain't gettin' any other offers.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846 }, ["starts"] = { { ["x"] = 0.612, ["y"] = 0.374, ["mapID"] = 1462, ["npcID"] = 154534 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154534, ["x"] = 0.612, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questGiverID"] = 154534, ["questType"] = "standard" },
[56325] = { ["id"] = 56325, ["name"] = "Changing Tides", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["series"] = { 55574, 56741 }, ["description"] = "We are out of time. We must gain control the Tidestone of Golganneth and the Javelin is our best shot at piercing the barrier surrounding it. The guardian is formidable, but must be defeated if we are to take the fight to Azshara. What forces we have will be arrayed below, just outside their encampment. I would trust you with the Javelin of Suramar, <name>. We will need your strength in the coming battle.", ["objectivesText"] = "Assault the naga camp and seize control of the Tidestone of Golganneth. Progress: If we do not take the Tidestone, we are finished.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 152813, 175246 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 25 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153193, ["x"] = 0.500857, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56741 }, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 46, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56326] = { ["id"] = 56326, ["name"] = "Ravenous Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56326 }, ["description"] = "A conspiracy of ravens is preying on citizens of Rustbolt! It's most unacceptable! Prince Erazmin has asked me to rescue as many citizens as I can, but I could use your help. I've tracked the ravens to this hill. We blast the ravens out of the sky, and you rescue the mechagnomes. Use my marker gun if you need help bringing the ravens down.", ["objectivesText"] = "Rescue 8 injured mechagnomes . Progress: Let's get to it!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154568, ["x"] = 0.622, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154568, ["x"] = 0.622, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56327] = { ["id"] = 56327, ["name"] = "Chopped Bots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56327 }, ["description"] = "Chopping up bots is my business. Any bots you bring to my scrapper will be broken up into useful parts. It's a win for both of us! Use the Bot-Energizer to bring me dead bots, and we'll break them into spare parts .", ["objectivesText"] = "12 Re-animated bots delivered to Bolten Springspark . Progress: Re-animate dead bots and bring them to me!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150086, ["x"] = 0.63, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150086, ["x"] = 0.63, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 54965 }, ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56328] = { ["id"] = 56328, ["name"] = "Do Not Drink", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56328 }, ["description"] = "These troggs watch everything we do. They see us pouring oil into various machines, so now they're stealing the oil and drinking it. I think they believe it's going to turn them into machines! We need that oil back, before they drink it all!", ["objectivesText"] = "Recover 12 containers of Stolen Oil . Progress: Get that oil back quick!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 4536, 64588, 64598, 64607, 64616, 64622, 64639, 157012, 166846, 166970, 166971, 168608, 181802, 183744, 184843, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 153750, ["x"] = 0.59, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 153750, ["x"] = 0.59, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 55729 }, ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56334] = { ["id"] = 56334, ["name"] = "Bots Gone Wild", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56334 }, ["description"] = "It's loose up there! I told them not to do it, but they didn't listen. Now it's gone out of control and killed everyone up there. It's an experimental Whirlbot. They never should have built it! You need to stop it before it comes down here looking for more victims! Kill the Whirling Zap-O-Matic .", ["objectivesText"] = "Whirling Zap-O-Matic slain Progress: You need to stop it.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154655, ["x"] = 0.6, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154655, ["x"] = 0.6, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
