[56336] = { ["id"] = 56336, ["name"] = "Uncovering the Artifact Fragments", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 56336 }, ["description"] = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran . Go out and kill any you find and bring at least fifty to Ecilam the Mage near the campfire in Stormshield Stronghold.", ["objectivesText"] = "Ecilam in Stormshield Stronghold wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 50 Artifact Fragments . Progress: Are those Artifact Fragments , I see?", ["rewardGold"] = 341600, ["starts"] = { { ["mapID"] = 588, ["npcID"] = 82966, ["x"] = 0.446, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 82966, ["x"] = 0.446, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 8485 } }, ["questType"] = "pvp" },
