[56338] = { ["id"] = 56338, ["name"] = "Volrath Must Die", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 56338 }, ["description"] = "The Horde are getting in our way of completing our mission here in Ashran . Their leader is High Warlord Volrath. He must be put down. Push forth through the center road, enter Warspear and slay Volrath.", ["objectivesText"] = "Slay High Warlord Volrath found in the Horde base Warspear within Ashran .", ["rewardCurrencies"] = { { ["id"] = 1602, ["amount"] = 250 }, { ["id"] = 1602, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 588, ["npcID"] = 84173, ["x"] = 0.445, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 84173, ["x"] = 0.445, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 8485 } }, ["questType"] = "pvp" },
[56339] = { ["id"] = 56339, ["name"] = "Tremblade Must Die", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 56339 }, ["description"] = "This battle in Ashran has waged on long enough. It appears they're being led by Grand Marshal Tremblade. If she falls, the Alliance will crumble. Push forward through the center road, make your way into their keep and take down Tremblade. For the Horde!", ["objectivesText"] = "Slay Grand Marshal Tremblade found in the Alliance base Stormshield Keep within Ashran .", ["rewardCurrencies"] = { { ["id"] = 1602, ["amount"] = 250 }, { ["id"] = 1602, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 588, ["npcID"] = 84473, ["x"] = 0.45, ["y"] = 0.278 } }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 84473, ["x"] = 0.45, ["y"] = 0.278 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.278 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 8485 } }, ["questType"] = "pvp" },
