[56344] = { ["id"] = 56344, ["name"] = "To Darkmaul Citadel", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 60168, 85678 }, ["description"] = "We've rescued everyone except for the expedition's captain. Lindie's Scout-o-Matic spotted her just outside Darkmaul Citadel. Meredy has come up with an... interesting plan to rescue the captain. It may be our only chance. Come. We'll convene in the shadow of Darkmaul Citadel, and there we will begin our rescue mission.", ["objectivesText"] = "Meet Lady Jaina Proudmoore outside of Darkmaul Citadel.", ["rewardGold"] = 735, ["rewardXP"] = 505, ["rewardItems"] = { 175175, 175188, 175189, 175190, 175207, 175220, 175221, 175222 }, ["starts"] = { { ["x"] = 0.521, ["y"] = 0.553, ["mapID"] = 1409, ["npcID"] = 245394 } }, ["ends"] = { { ["x"] = 0.521, ["y"] = 0.553, ["mapID"] = 1409, ["npcID"] = 245394 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.521, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 245394, ["questTurnInID"] = 245394, ["questType"] = "standard", ["sourceQuests"] = { 55639, 55882, 59349, 59350, 59354, 60168, 85678 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 1083, ["name"] = "To Darkmaul", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 28, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[56346] = { ["id"] = 56346, ["name"] = "Ancient Technology", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56346, 56347, 56348, 56349 }, ["description"] = "<Given the experience you've had with the naga and the power they wield, you wonder if using their own power against them might not garner you a powerful advantage. Perhaps Instructor Ulooaka back at Mezzamere could help you repair this core and put it to use against the naga invasion.>", ["objectivesText"] = "Bring the Broken Power Core to Instructor Ulooaka in Mezzamere. Provided item:", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 169320 }, ["starts"] = { { ["x"] = 0.381, ["y"] = 0.369, ["mapID"] = 1355, ["objectID"] = 327596 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 }, ["questLines"] = { { ["id"] = 955, ["name"] = "8.2 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56347] = { ["id"] = 56347, ["name"] = "An Abyssal Opportunity", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56346, 56347, 56348, 56349 }, ["description"] = "I believe, <name>, we can use this thing to make our armor stronger. By redirecting its power, we can take the strength of our crafts to a new level. But we're getting ahead of ourselves. The first thing we need to do is repair this device. It'll require some powerful materials to fix it, and those are usually carried by the stronger creatures of this region. However, Artisan Okata is great at collecting materials like the ones we need. I'd check with him to see what he's got.", ["objectivesText"] = "Acquire 15 Abyssal Shards from Artisan Okata. Progress: How goes the hunt for the materials?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169326, 171247 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56346 }, ["questLines"] = { { ["id"] = 955, ["name"] = "8.2 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56348] = { ["id"] = 56348, ["name"] = "The Eternal Palace: We Can Make It Stronger...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56346, 56347, 56348, 56349 }, ["description"] = "Now that it's functioning, it occurred to me while repairing it that it has the capability to output even more energy. Of course that will require stronger materials to upgrade and the only place I can think of is in the Eternal Palace. Azshara's army and even herself carry items of extraordinary power. If you could bring some of those back, I could at the very least test my theory and see if it's viable.", ["objectivesText"] = "Collect 20 Eternal Ornaments from the most powerful creatures of the Eternal Palace. Progress: How goes the search for those items?", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 169329 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "raid", ["sourceQuests"] = { 56347 }, ["questLines"] = { { ["id"] = 955, ["name"] = "8.2 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56349] = { ["id"] = 56349, ["name"] = "The Eternal Palace: Pushing the Limits", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56346, 56347, 56348, 56349 }, ["description"] = "Now that we know how to increase the potency of this tool, I think we can push its capabilities even further. Bring me back more of those ornaments. LOTS of them. Let's see just how far we can make this go.", ["objectivesText"] = "Collect 200 Eternal Ornaments from the most powerful creatures of the Eternal Palace. Progress: Any luck on retrieving more of those ornaments?", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 169329 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "raid", ["sourceQuests"] = { 56348 }, ["questLines"] = { { ["id"] = 955, ["name"] = "8.2 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56350] = { ["id"] = 56350, ["name"] = "Scouting the Palace", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 55095, 55175, 56350, 56640, 56641, 56642, 56643, 56644 }, ["description"] = "We cannot hide here forever, <name>. Azshara must be dealt with. It would be an act of folly to assault her palace without knowing what defenses she has in place. I dispatched a scouting team while you were gone, but they have not reported back. I'm getting concerned, <name>. Let me know when you're ready and I'll perform a ritual to see what has happened to our scouts.", ["objectivesText"] = "Speak with Lady Jaina Proudmoore to observe the scouting party. Progress: Are you ready?", ["rewardXP"] = 10225, ["rewardItems"] = { 169482, 169483, 169485 }, ["rewardChoices"] = { 169482, 169483, 169485 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56162, 57010 }, ["questLines"] = { { ["id"] = 949, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 949, ["questLineOrder"] = 21 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
