[56365] = { ["id"] = 56365, ["name"] = "Be Kind, Rewind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56365 }, ["description"] = "You exist here due to a time anomaly, but you must return to your own time and help us there. The Visual Holo Sphere from the Vaultbot nearby contains the data necessary to defeat King Mechagon before he can use the Mechoriginator. Deliver the Visual Holo Sphere to me in your reality. With luck I will be able to rewind history and prevent this existence from ever happening.", ["objectivesText"] = "Deliver the Visual Holo Sphere to Izira Geasworn in Rustbolt. Progress: You will have to return to your time period.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 167062, 169114, 169867, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 153982, ["x"] = 0.728, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 153641, ["x"] = 0.735, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56370] = { ["id"] = 56370, ["name"] = "Break a Few Eggs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56370 }, ["description"] = "The naga are using these caverns as a hatchery for their deadly deepcoil serpents. These deepcoil serpents are especially dangerous because they have been infused with dark void magic. We must put a stop to this operation before it is too late. The naga forces are already quite powerful. I do not wish to imagine what would happen if Azshara also had an army of these deepcoil serpents as well. Our only hope is to destroy the deepcoil eggs before they hatch.", ["objectivesText"] = "Destroy 10 Deepcoil Eggs . Progress: Have you destroyed the deepcoil eggs ?", ["rewardGold"] = 234000, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 3 }, { ["id"] = 1749, ["amount"] = 100 }, { ["id"] = 1721, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154075, ["x"] = 0.668, ["y"] = 0.292 }, { ["mapID"] = 1355, ["npcID"] = 155844, ["x"] = 0.67, ["y"] = 0.262 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155844, ["x"] = 0.67, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56371] = { ["id"] = 56371, ["name"] = "Young Twilight Scale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 56371 }, ["description"] = "<A partially-grown scale from a young twilight whelp. More and more twilight dragons are appearing once again. This seems suspicious. You should show the scale to Eryna above Grim Batol in the Wetlands , perhaps she has seen something recently.>", ["objectivesText"] = "Show the scale to Eryna above Grim Batol in the Wetlands . Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 169346 }, ["starts"] = { { ["npcID"] = 169346 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 132888, ["x"] = 0.202, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.202, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questGiverID"] = 169346, ["questType"] = "standard", ["startItems"] = { 169346 } },
[56372] = { ["id"] = 56372, ["name"] = "Hozen Totem", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 8, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 56372 }, ["description"] = "<The hozen have been successfully chased away, and Brewfest saved once again. The question asks itself, though: How did hozen get to Dun Morogh? Perhaps you should ask somebody who has experience in navigation and travel.>", ["objectivesText"] = "Talk to Arcti in the Brewfest grounds.", ["rewardGold"] = 312800, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["starts"] = { { ["x"] = 0.555, ["y"] = 0.377, ["mapID"] = 27, ["objectID"] = 328413 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 152829, ["x"] = 0.554, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[56373] = { ["id"] = 56373, ["name"] = "A Gulper Ate the Rolly", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56373 }, ["description"] = "The Bubble-eyed Rolly used to be plentiful in the nearby pond. Last week they all started to vanish! A large water elemental has been swallowing all the fish! They are still alive, just swimming around inside the elemental now. I need you to kill that elemental, and catch three Bubbly-eyed Rolly so I can examine their condition.", ["objectivesText"] = "Kill the Rolly Gulper and catch 3 Bubble-eyed Rolly . Progress: Did you kill that elemental?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 169391, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 151462, ["x"] = 0.37, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151462, ["x"] = 0.37, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56374] = { ["id"] = 56374, ["name"] = "A Titanic Problem", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472 }, ["description"] = "We've no time tae waste. Without the Forge of Origination, Azeroth is left vulnerable tae N'Zoth's corruption. Not tae mention it holds a weapon capable of wipin' out all life on Azeroth! We'll need tae head over tae the forge right away. MOTHER can hold down the fort here. Hurry on, I'll meet ye there.", ["objectivesText"] = "Meet Magni Bronzebeard at the Halls of Origination in Uldum.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questGiverID"] = 152206, ["questType"] = "standard", ["sourceQuests"] = { 58506 }, ["questLines"] = { { ["id"] = 950, ["name"] = "The Forge of Origination", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[56375] = { ["id"] = 56375, ["name"] = "To Ramkahen", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 84, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472 }, ["description"] = "It looks like we're gonna have tae wait a spell while MOTHER figures out what tae do with the forge. In the meantime we'll want tae try to make sure nobody tries tae do any more damage here. Ye should check in on the tol'vir in Ramkahen. I know ye've helped them in the past, so they might be able tae help us keep the forge out o' the wrong hands.", ["objectivesText"] = "Meet King Phaoris in Ramkahen.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84, 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56209 }, ["questLines"] = { { ["id"] = 950, ["name"] = "The Forge of Origination", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[56376] = { ["id"] = 56376, ["name"] = "Surfacing Threats", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472 }, ["description"] = "The tol'vir take the protection of the titans' constructs here in Uldum as a sacred duty. However, our numbers have dwindled, and we face greater threats with each day. Even with the strength of our new allies, we will only be able to hold these enemies back for so long. Should any of them surge in power, they may still be able to overwhelm us and endanger the forge. This is where your assistance is needed. Speak to High Commander Kamses to assess our current situation.", ["objectivesText"] = "Complete an Assault in Uldum.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 173280, 174953 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["questLines"] = { { ["id"] = 950, ["name"] = "The Forge of Origination", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[56377] = { ["id"] = 56377, ["name"] = "Forging Onward", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472 }, ["description"] = "Thanks fer helpin' me back there at the forge. It's vexin' that N'Zoth was able to infiltrate it so quickly, but at least we arrived in time tae keep it from bein' completely wrecked! Now comes the task of gettin' her back tae a hundred percent. MOTHER has been workin' on a solution, and we think we've got a plan.", ["objectivesText"] = "Return to Magni Bronzebeard at the Chamber of Heart and learn about the fate of the Forge of Origination. Progress: Aye?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.549, ["y"] = 0.331, ["mapID"] = 1527 } }, ["ends"] = { { ["x"] = 0.549, ["y"] = 0.331, ["mapID"] = 1527 } }, ["coords"] = { ["mapID"] = 1527, ["x"] = 0.549, ["y"] = 0.331 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 56376 }, ["questLines"] = { { ["id"] = 950, ["name"] = "The Forge of Origination", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[56378] = { ["id"] = 56378, ["name"] = "The Missing Crew", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1161, ["storyline"] = { 56378 }, ["description"] = "I can't believe it. Almost the entire fleet.. lost! We need to have ships out there on missions supporting our efforts, but how am I supposed to do that now? If we are going to recover from this, I'm going to need my top people. I know the chances are low, but I need you to get out there and try to find them. Alive if possible.", ["objectivesText"] = "Find and rescue the missing crew members.", ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135681, ["x"] = 0.68, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135681, ["x"] = 0.68, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
