[56380] = { ["id"] = 56380, ["name"] = "Grounded", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56380 }, ["description"] = "One of King Mechagon 's older Aerial units is having mechanical problems and is grounded nearby. They're trying to get it repaired, so we need to act fast while it's vulnerable. Destroy the Aerial Patroller XZ-2 before they can get it repaired.", ["objectivesText"] = "Destroy the Aerial Patroller XZ-2 Progress: Did you kill the Aerial Patroller XZ-2 ?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 84596, 84597, 84598, 84599, 84600, 84601, 84602, 84603, 84604, 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154906, ["x"] = 0.428, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154906, ["x"] = 0.428, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
