[56401] = { ["id"] = 56401, ["name"] = "A Bolt from the Blue", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 114, ["storyline"] = { 56401 }, ["description"] = "You have done much to empower the Heart of Azeroth, and I am proud that the dragonflights have lent their strength to your cause. It is now time for the blue dragonflight to do the same. When I first learned of the essences, I knew that some remnant of my dragonflight's power must be out there, coalescing where we were once strong. That is exactly what I have found. The Kirin Tor have isolated its signature at the Nexus, but only the wielder of the Heart of Azeroth can claim it.", ["objectivesText"] = "Meet Kalecgos at the Nexus and claim the Charged Scale of the Blue Aspect . Progress: The power of the Heart of Azeroth never ceases to amaze me.", ["rewardGold"] = 23400, ["rewardItems"] = { 137642, 168612, 168613, 168614, 169292, 169768 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.531, ["y"] = 0.709, ["mapID"] = 1473, ["npcID"] = 152365 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 152720, ["x"] = 0.28, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 9667 } }, ["questGiverID"] = 152365, ["questType"] = "standard", ["sourceQuests"] = { 56260, 56263 }, ["questLines"] = { { ["id"] = 961, ["name"] = "A Bolt From the Blue", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[56402] = { ["id"] = 56402, ["name"] = "Wastewander Coins", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56402 }, ["description"] = "It may be too late for some of our fallen brothers and sisters, but it is not too late to give solace to their families. Every Wastewander carries with them a unique coin, signifying their status as a member of our group. If you find any of these coins, please bring them to me and I will make sure they are properly returned to their next of kin.", ["objectivesText"] = "Collect 6 Wastewander Coins . Progress: Do you have coins to return?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169432 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 418 }, { ["id"] = 1553, ["amount"] = 496 }, { ["id"] = 1560, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159560, ["x"] = 0.4, ["y"] = 0.452 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159560, ["x"] = 0.4, ["y"] = 0.452 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57915 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[56405] = { ["id"] = 56405, ["name"] = "Cogfrenzy's Construction Frenzy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56405 }, ["description"] = "You Rustbolt resisters inspire me. Tinkering, building, exploring. Letting your imagination run wild and then chasing after it, wherever it leads, with reckless abandon! <Walton releases a deep sigh.> I miss those days. I hope, someday, my conscience will allow me to stay on the surface with you all permanently... Before I return to Mechagon , we must build something incredible. Waren and I have identified a large number of extra construction project sites for today. Build with boldness!", ["objectivesText"] = "Help build construction projects. Progress: Even the greatest builders are eventually forgotten, but their creations are not.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 167844, 169470, 169471, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154967, ["x"] = 0.734, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154967, ["x"] = 0.734, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.734, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 967, ["name"] = "Visit from Walton Cogfrenzy", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
