[56429] = { ["id"] = 56429, ["name"] = "Up Against It", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54012, 54015, 54018, 54021, 55053, 55054, 55092, 55094, 55481, 56063, 56429 }, ["description"] = "I don't like the sound of that... It sounds like an army! We need to investigate. Try not to draw too much attention as we take a look. If there's an army down there, we'll need to move quickly to find refuge.", ["objectivesText"] = "Move deeper into Nazjatar with Lor'themar and Thalyssra. Progress: These naga move with a single purpose!", ["rewardGold"] = 283700, ["rewardXP"] = 6815, ["rewardItems"] = { 29333, 29334, 29335, 29336, 52593, 52617, 52640, 52644, 52673, 62210, 62211, 62212, 62213, 131283, 131655, 140255, 142054 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150196, ["x"] = 0.396667, ["y"] = 0.775333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150196, ["x"] = 0.396667, ["y"] = 0.775333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.396667, ["y"] = 0.775333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questTurnInID"] = 150196, ["questType"] = "standard", ["sourceQuests"] = { 54015 }, ["questLines"] = { { ["id"] = 886, ["name"] = "Azshara's Trap", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 886, ["questLineOrder"] = 23 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
[56430] = { ["id"] = 56430, ["name"] = "Defensive in Death", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56430 }, ["description"] = "<Having handled zin'anthid for a while now, you pluck one of its tentacles from the main body. As you do, the tentacle retracts, spiraling in on itself preventing you from getting to the blooms that reside along it. Perhaps Rolm will have more insight on how to keep this herb from defending itself.>", ["objectivesText"] = "Ask Rolm about the tentacles of the Zin'anthid. Provided item:", ["rewardItems"] = { 169596 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154408, ["x"] = 0.492, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169596 } },
[56431] = { ["id"] = 56431, ["name"] = "Ounces of Osmenite", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56431 }, ["description"] = "<Picking away at the ore, you pick up some shards that have fallen to the ground. There ought to be a way to mine these deposits without wasting any of it. Perhaps Rolm knows of still a better way to mine this ore.>", ["objectivesText"] = "Ask Rolm about the Osmenite Shards . Provided item:", ["rewardItems"] = { 169597 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154408, ["x"] = 0.492, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169597 } },
[56432] = { ["id"] = 56432, ["name"] = "Seams to be a Problem", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56432 }, ["description"] = "<Picking away at the ore, you notice that much of it seems to turn to dust and fall to the floor at your feet. Enough even, that had it held its shape, would be enough to craft something with. It may be worth talking to Rolm to see if there's a way to prevent this loss from happening.>", ["objectivesText"] = "Ask Rolm about the Osmenite Dust . Provided item:", ["rewardItems"] = { 169598 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154408, ["x"] = 0.492, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169598 } },
[56433] = { ["id"] = 56433, ["name"] = "Drowning the Alliance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56433 }, ["description"] = "The Alliance continue to pursue us, they will not disrupt our plans any further. Drive their champions into a watery grave.", ["objectivesText"] = "Kill 25 Alliance players in Nazjatar while in War Mode.", ["rewardItems"] = { 168850 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154652, ["x"] = 0.488, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154652, ["x"] = 0.488, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55481 } },
[56434] = { ["id"] = 56434, ["name"] = "WANTED: Junkbrat and Roadtrogg", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56434 }, ["description"] = "Responsible for a spree of mayhem and chaos throughout the Heaps, resulting in the theft of energy cells , spare parts , and the consumption of Improbable Mechano-Chicken Wings without payment. Special caution around Roadtrogg , who has demonstrated a violent attitude towards living things. Elimination of these two felons is of the highest priority.", ["objectivesText"] = "Eliminate Junkbrat and Roadtrogg .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["x"] = 0.673, ["y"] = 0.352, ["mapID"] = 1462, ["objectID"] = 329641 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 153641, ["x"] = 0.735, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "group", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[56436] = { ["id"] = 56436, ["name"] = "Small Skull", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56436 }, ["description"] = "<Inside of the gelatinous remains of the slime you find a small skeleton. Someone in Rustbolt might be missing. You pick up the skull, it might still be able to be identified.>", ["objectivesText"] = "Show the Small Skull to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 169615 }, ["starts"] = { { ["x"] = 0.647, ["y"] = 0.646, ["mapID"] = 1462 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150629, ["x"] = 0.693333, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.693333, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169615 } },
[56437] = { ["id"] = 56437, ["name"] = "Rusty Tube", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56437 }, ["description"] = "<The malfunctioning junkbot is now a mere heap of metal, its signature tube poking out of the remains. You remove the tube. The citizens of Rustbolt seem to trade in junk, maybe someone will want it.>", ["objectivesText"] = "Show the Rusty Tube to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 169610, 169616 }, ["starts"] = { { ["x"] = 0.607, ["y"] = 0.465, ["mapID"] = 1462 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150629, ["x"] = 0.693333, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.693333, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169616 } },
[56438] = { ["id"] = 56438, ["name"] = "Flashing Siren", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56438 }, ["description"] = "<Despite the robot being destroyed, the siren continues flashing. Clearly this was a key sentry of King Mechagon . The citizens of Rustbolt will want to know of its demise.>", ["objectivesText"] = "Show the Flashing Siren to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 169617 }, ["starts"] = { { ["x"] = 0.606, ["y"] = 0.569, ["mapID"] = 1462 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150629, ["x"] = 0.693333, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.693333, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169617 } },
[56439] = { ["id"] = 56439, ["name"] = "Mechanical Egg Sac", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56439 }, ["description"] = "<You find a mechanical egg sac inside of the defunct spiderbot. This doesn't make any sense, robots don't reproduce this way. Or do they? Someone in Rustbolt might have the answers.>", ["objectivesText"] = "Show the Mechanical Egg Sac to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 166846, 168327, 169618 }, ["starts"] = { { ["x"] = 0.592, ["y"] = 0.509, ["mapID"] = 1462 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150629, ["x"] = 0.693333, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.693333, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169618 } },
[56440] = { ["id"] = 56440, ["name"] = "Can of Critter Spray", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56440 }, ["description"] = "<Inside the wreckage of the robot, you find a sealed can of anti-critter spray. Destroying all life, down to the rats, seems cruel but on par for King Mechagon . Someone in Rustbolt might be able to provide additional insight.>", ["objectivesText"] = "Show the Can of Critter Spray to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 168832, 169619 }, ["starts"] = { { ["x"] = 0.654, ["y"] = 0.576, ["mapID"] = 1462 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150629, ["x"] = 0.693333, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.693333, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169619 } },
[56441] = { ["id"] = 56441, ["name"] = "Cluckbox", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56441 }, ["description"] = "<In the sparking, smoldering wreckage of Unit 35, you find a small, black cube. It looks to be made of a metallic substance and appears unharmed. Looking closely, you see a single word imprinted in the metal -- \" Cluckbox .\" This particular mechanical fowl was operating quite strangely. Someone in Rustbolt will probably want to investigate.>", ["objectivesText"] = "Show the Cluckbox to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 169610, 169620 }, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.454, ["mapID"] = 1462 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150629, ["x"] = 0.693333, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.693333, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169620 } },
[56442] = { ["id"] = 56442, ["name"] = "Broken Unit 6", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56442 }, ["description"] = "<Unit 6 sits here, nonfunctional following your attack. There is something different and unsettling about this mechanical frog. It appeared to be mimicking frog behavior, but in a way that seemed wrong somehow. None of the other mechanical frogs in the area behave similarly. Instead of taking back only part of the unit for inspection, you pocket the entire frog. It's pretty small, after all.>", ["objectivesText"] = "Show the Broken Unit 6 to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166971, 169621 }, ["starts"] = { { ["x"] = 0.395, ["y"] = 0.402, ["mapID"] = 1462 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150629, ["x"] = 0.693333, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.693333, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169621 } },
[56443] = { ["id"] = 56443, ["name"] = "Mechanical Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56443 }, ["description"] = "<As the mechanical body of Unit 17 crumples into a heap, one eye lights up. You hear a popping noise, and the eye flies from the head, aided by a small explosion. You pick up the eye and notice it twitch a few times, then power down. The citizens of Rustbolt seem to like junk, maybe they'll be interested in this.>", ["objectivesText"] = "Show the Mechanical Eye to Vera Lonelycog in Rustbolt on Mechagon Island. Provided item:", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 168327, 169622 }, ["starts"] = { { ["x"] = 0.721, ["y"] = 0.729, ["mapID"] = 1462 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150629, ["x"] = 0.693333, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.693333, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169622 } },
[56444] = { ["id"] = 56444, ["name"] = "Wiggletail's Poking Fork", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56444 }, ["description"] = "<The tenacious tine of the vanquished prince. It does not thrum with any power whatsoever. In fact, it appears quite plain, and a bit rusted. You pocket it anyway. Perhaps Artisan Itanu would be interested?>", ["objectivesText"] = "Show Wiggletail's Poking Fork to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169623 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169623 } },
[56445] = { ["id"] = 56445, ["name"] = "Wiggletail's Poking Fork", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56445 }, ["description"] = "<The tenacious tine of the vanquished prince. It does not thrum with any power whatsoever. In fact, it appears quite plain, and a bit rusted. You pocket it anyway. Perhaps Finder Palta would be interested?>", ["objectivesText"] = "Show Wiggletail's Poking Fork to Finder Palta in Newhome in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169646 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153514, ["x"] = 0.492, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169646 } },
[56446] = { ["id"] = 56446, ["name"] = "Leathery Venom Gland", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56446 }, ["description"] = "<You pry a leathery gland from the snapdragon corpse. Drops of venom spill from an opening on one end and sizzle as they touch the ground, leaving small holes behind. This toxin appears to be very potent. It would be best to bring it back to Mezzamere.>", ["objectivesText"] = "Show the Leathery Venom Gland to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169624 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169624 } },
[56447] = { ["id"] = 56447, ["name"] = "Half-Digested Deepcoral Pod", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56447 }, ["description"] = "<Upon inspection of this oddly-aggressive fathom ray, you find several halfway-digested pods. You've seen similar pods on the coral of this region, it appears to be one of the foods of the fathom rays. This may explain their strange ability to fly. Artisan Itanu might know more.>", ["objectivesText"] = "Show the Half-Digested Deepcoral Pod to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169625 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169625 } },
[56448] = { ["id"] = 56448, ["name"] = "Molted Spineshell", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56448 }, ["description"] = "<The molted shell of a defeated spine crab, a vicious species of crab first encountered in Nazjatar . The spines that stick out from it are quite sharp. Artisan Itanu may have some use for this.>", ["objectivesText"] = "Show the Molted Spineshell to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169626 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169626 } },
[56449] = { ["id"] = 56449, ["name"] = "Pearlescent Shell", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56449 }, ["description"] = "<A large, hardened shell of a vanquished hermit crab. The shell itself was much larger than the crab, and shines in different colors when you look at it at different angles. Surely someone back at Mezzamere would be interested in this beautiful shell.>", ["objectivesText"] = "Show the Pearlescent Shell to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169627 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169627 } },
[56450] = { ["id"] = 56450, ["name"] = "Eel Jelly", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56450 }, ["description"] = "<You examine the corpse of the abyssal eel, only to find it bathed in a strange slime. The slime coats your hands and arms, and seems quite difficult to remove. One of your deep sea allies may know more about it.>", ["objectivesText"] = "Show the Eel Jelly to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169628 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169628 } },
[56451] = { ["id"] = 56451, ["name"] = "Mottled Hydra Scale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56451 }, ["description"] = "<The scale of a recently-defeated hydra hatchling, it appears to be a mixture of several colors. There appears to be a battle for dominance between the hydra of the region, one of your new allies may know more.>", ["objectivesText"] = "Show the Mottled Hydra Scale to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169629 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169629 } },
[56452] = { ["id"] = 56452, ["name"] = "Strange Organ", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56452 }, ["description"] = "<You find a strange organ in the corpse of the mindbender. Upon picking it up, your head begins to throb. The octopus-like creatures have long been one of Azeroth's mysteries, this organ may shed some light on them. Someone in Mezzamere may know more.>", ["objectivesText"] = "Show the Strange Organ to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169630 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169630 } },
[56453] = { ["id"] = 56453, ["name"] = "Overgrown Stone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56453 }, ["description"] = "<A stone taken from the earthy elemental you recently defeated, covered in kelp and various other underwater plants. You have not seen many such creatures in the deeps. Perhaps there is a story to them. One of your new undersea allies may know more.>", ["objectivesText"] = "Show the Overgrown Stone to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169631 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169631 } },
[56454] = { ["id"] = 56454, ["name"] = "Crackling Mandible", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56454 }, ["description"] = "<The mandible of a tidal guardian, still crackling with electricity. One of your new allies might have a use for this.>", ["objectivesText"] = "Show the Crackling Mandible to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169632 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169632 } },
[56455] = { ["id"] = 56455, ["name"] = "Frenzy Fang", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56455 }, ["description"] = "<You remove a fully-grown fang from the fallen frenzy. You have heard of some seafaring groups that made weapons or decorations out of fangs found in the deeps, perhaps your new allies could find use for this?>", ["objectivesText"] = "Show the Frenzy Fang to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169633 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169633 } },
[56456] = { ["id"] = 56456, ["name"] = "Opaline Conch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56456 }, ["description"] = "<The conch slumps following your assault -- the battle appears to be over. It doesn't move. You bend over and pick it up, instinctively turning it over, wary of any attack. It appears to be dead, but intact. You consider bringing the entire conch back to your allies in Mezzamere.>", ["objectivesText"] = "Show the Opaline Conch to Artisan Itanu in Mezzamere in Nazjatar . Provided item:", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169634 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169634 } },
