[56504] = { ["id"] = 56504, ["name"] = "Wrathion's Journal", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56190 }, ["description"] = "The whispers ceased as soon as I drank the potion. Thank you, $p. Still, it is gravely concerning that N'Zoth's influence could reach me even within the Chamber of Heart. If Wrathion has found a way to resist the power of the Old Gods, then we can use it to reinforce the Chamber's defenses. Perhaps MOTHER can glean more information from Wrathion's journal .", ["objectivesText"] = "Deliver Wrathion's incomplete journal to MOTHER . Progress: Awaiting information interface.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 170493 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.463, ["y"] = 0.672, ["mapID"] = 1473, ["npcID"] = 151964 } }, ["ends"] = { { ["x"] = 0.463, ["y"] = 0.672, ["mapID"] = 1473, ["npcID"] = 151964 } }, ["coords"] = { ["mapID"] = 1473, ["x"] = 0.463, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questGiverID"] = 151964, ["questTurnInID"] = 151964, ["questType"] = "standard", ["sourceQuests"] = { 56190 }, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[56508] = { ["id"] = 56508, ["name"] = "Waste Not", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56508 }, ["description"] = "<There's a variety of parts around this area that might be useful to Rustbolt. You should collect them before Venture Co takes them.>", ["objectivesText"] = "Collect 20 Useful Bits and Pieces Progress: Grab what things you can!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 169682, 169686 }, ["starts"] = { { ["x"] = 0.43, ["y"] = 0.411, ["mapID"] = 1462, ["objectID"] = 329715 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152747, ["x"] = 0.698, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
