[56536] = { ["id"] = 56536, ["name"] = "It's Never Easy", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 58737 }, ["description"] = "The last I heard, Mogu'shan Vaults was still abandoned. We shouldn't have too tough of a time reachin' the engine, since we've already defeated the mogu guardians in that place. Well, what are ye waitin' for? Let's get that engine turned on!", ["objectivesText"] = "Meet Magni Bronzebeard outside Mogu'shan Vaults in Kun-Lai Summit. Progress: It's never easy, is it?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questGiverID"] = 152206, ["questType"] = "standard", ["sourceQuests"] = { 56377 }, ["questLines"] = { { ["id"] = 983, ["name"] = "The Engine of Nalak'sha", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[56537] = { ["id"] = 56537, ["name"] = "The Mysterious Sigil", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 58737 }, ["description"] = "<The slain mogu clutches a sigil in his hand -- a symbol of the mysterious clan he belongs to. Perhaps if you could track down his clan, they may know more about the mantid's invasion of Mogu'shan Vaults and how they can be overcome. Lorewalker Cho is well known as font of lore for Pandaria. He may be able to track down the origins of the mogu's sigil.>", ["objectivesText"] = "Bring the Mysterious Mogu Sigil to Lorewalker Cho at the Seat of Knowledge in Vale of Eternal Blossoms.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 155336, ["x"] = 0.596, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 379, 1530 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 56536 }, ["questLines"] = { { ["id"] = 983, ["name"] = "The Engine of Nalak'sha", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[56538] = { ["id"] = 56538, ["name"] = "Clans of the Mogu", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 58737 }, ["description"] = "You say a mogu asked for your help? This is quite uncharacteristic. I'd be happy to help you uncover the origins of this sigil. To be honest, the prospect of a mogu clan that isn't openly hostile interests me greatly. Just think of the possibilities! Let's get down to business. We'll need to consult the volumes on the various mogu clans in the vale to narrow it down.", ["objectivesText"] = "Help Lorewalker Cho discover the origin of the Mysterious Mogu Sigil at the Seat of Knowledge. Progress: Why are you talking to me? The knowledge you seek is in the tomes.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.836, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56537 }, ["questLines"] = { { ["id"] = 983, ["name"] = "The Engine of Nalak'sha", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[56539] = { ["id"] = 56539, ["name"] = "Finding the Rajani", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 58737 }, ["description"] = "Now that we have an idea of who we're looking for, the next question is, where can we find them? With the constant infighting of the mogu, it is likely that each clan would keep tabs on the whereabouts of their competitors. If we can find such information, it may just lead us to the Rajani. Seek out the champions of the mogu. They would be the most likely to carry reports on their enemies' whereabouts.", ["objectivesText"] = "Collect a Mogu Scouting Report from mogu in the Vale of Eternal Blossoms. Progress: Have you found a scouting report?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 170384 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.836, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56538 }, ["questLines"] = { { ["id"] = 983, ["name"] = "The Engine of Nalak'sha", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[56540] = { ["id"] = 56540, ["name"] = "Proof of Tenacity", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 58737 }, ["description"] = "If the Highkeeper is so convinced that we don't stand a chance against our enemies, perhaps a show of force would sway him. I am not sure how you would manage, but if you could bring proof of a victory against those who threaten the Vale, it may convince him that action should be taken.", ["objectivesText"] = "Obtain a Conqueror's Trophy from the commander of an Assault in the Vale of Eternal Blossoms. Progress: What is it this time?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 170385, 173835, 173836, 173837, 173838, 173839, 173840, 173841, 173842, 173843, 173844, 173845, 173846 }, ["rewardChoices"] = { 173835, 173836, 173837, 173838, 173839, 173840, 173841, 173842, 173843, 173844, 173845, 173846 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154418, ["x"] = 0.45, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["questLines"] = { { ["id"] = 983, ["name"] = "The Engine of Nalak'sha", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[56541] = { ["id"] = 56541, ["name"] = "The Engine of Nalak'sha", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 58737 }, ["description"] = "Your kind have proved me wrong in the past, so I will give you a chance to do so again. The titan structure which houses the Engine of Nalak'sha spans the entirety of Pandaria. There are more ways to reach it than just the Mogu'shan Vaults. There are many such routes, but the closest would be through Mogu'shan Palace. The chambers beneath the palace are interconnected with the vaults. Seek your fate there, champion.", ["objectivesText"] = "Follow the secret passage within Mogu'shan Palace and re-activate the Engine of Nalak'sha. Progress: Your courage is impressive. I only hope it is not wasted.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154418, ["x"] = 0.45, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154418, ["x"] = 0.45, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56540 }, ["questLines"] = { { ["id"] = 983, ["name"] = "The Engine of Nalak'sha", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[56542] = { ["id"] = 56542, ["name"] = "Restored Hope", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 58737 }, ["description"] = "Your persistence fills me with hope for this world. Let us return to your \"Chamber of Heart.\" As the caretaker of the Forge of Origination, I believe I can help your efforts to restore it. Speak to me when you are ready, and I will bring us there.", ["objectivesText"] = "Speak with Ra-den to return to the Chamber of Heart.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 168436, 168573 }, ["rewardChoices"] = { 168573, 168436 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154418, ["x"] = 0.45, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154418, ["x"] = 0.45, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questTurnInID"] = 154418, ["questType"] = "standard", ["sourceQuests"] = { 56541 }, ["questLines"] = { { ["id"] = 983, ["name"] = "The Engine of Nalak'sha", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[56550] = { ["id"] = 56550, ["name"] = "Corpse Cleanup", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56550 }, ["description"] = "Our friends continue to fall as these terrible insects pour of their nests and attack our camps. It's a terrible job to ask of anyone, but we have to dispose of the corpses as quickly as possible. We can't allow our dead to be used as fertilizer for growing their disgusting eggs.", ["objectivesText"] = "Burn 8 Egg-bearing corpses. Progress: We need to complete this task quickly and without delay.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174323 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 336 }, { ["id"] = 1553, ["amount"] = 354 }, { ["id"] = 1553, ["amount"] = 363 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[56552] = { ["id"] = 56552, ["name"] = "Off-the-Books Brawlin'", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56552 }, ["description"] = "Gazlowe hired you for protection too? I guess it's true that he only hires the best, eh? Ha! Pay's great, but the rules are dung: no fightin' in town, no exceptions. Bah! <Usha takes a big gulp of her drink.> That tiny tender prince won't give us his tech unless he thinks we're good little angels... Ha! But Gazlowe didn't say nothin' about fightin' outside of town. I got my own squad on the outskirts, ready to brawl with Grumbol's guzzlers if they show their bearded faces. You want in?", ["objectivesText"] = "Brawl with Grumbol Grimhammer's forces on Mechagon .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 155355, ["x"] = 0.702, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 155355, ["x"] = 0.702, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 982, ["name"] = "Conflict comes to Mechagon", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56557] = { ["id"] = 56557, ["name"] = "A Little Side Action", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56557 }, ["description"] = "There are only two things more fun than fighting, and the first is talking trash! <Usha shouts an insult at Grumbol Grimhammer.> That boar-beard runt over there's been a thorn in my backside since Alterac... Can't seem to shake him. We got a bet going about who's the best fighter on the island. You want to help me win this wager?", ["objectivesText"] = "Slay 5 Alliance players in Mechagon .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 155355, ["x"] = 0.702, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 155355, ["x"] = 0.702, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56558] = { ["id"] = 56558, ["name"] = "Off-the-Books Brawlin'", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56558 }, ["description"] = "*buuuurrp* Arrrright, listen 'ere. We got ourselves a bit o' a predicament. Besides this dump's ale tastin' like oil, that pigheaded Usha here been sayin' some unfortunate stuff about our troops. Unfortunate FOR HER, 'cuz now *uuuuurp* gonna needya ta rough up any Horde swine ya end up runnin' into out there. Loosely speakin' we ain't supposed to be brawlin' out 'ere, so this ain't a formal order or nothin'...", ["objectivesText"] = "Brawl with Usha Eyegouge's forces on Mechagon .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 155357, ["x"] = 0.702, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 155357, ["x"] = 0.702, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 980, ["name"] = "Conflict comes to Mechagon", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56559] = { ["id"] = 56559, ["name"] = "A Little Side Action", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56559 }, ["description"] = "'Ey, <name>, I could be usin' yer talents fer a little bet I got goin' on with Usha. I'm wagerin' you can beat up five 'o her pals around the island before her dog can beat up five o' ours. Ye up fer it me $ulad:lass;? 'O course ya are, ahahaha!", ["objectivesText"] = "Slay 5 Horde players in Mechagon .", ["rewardGold"] = 238680, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 168329 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 155357, ["x"] = 0.702, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 155357, ["x"] = 0.702, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56560] = { ["id"] = 56560, ["name"] = "A Curious Discovery", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56560 }, ["description"] = "<This crystal shines with a mesmerizing light that you find difficult to avert your gaze from. Perhaps the Unshackled would be able to tell you more about it.>", ["objectivesText"] = "Bring the Enchanting Crystal to Narv in Newhome. Provided item:", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 167893, 169778 }, ["starts"] = { { ["x"] = 0.328, ["y"] = 0.395, ["mapID"] = 1355, ["objectID"] = 329805 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154393, ["x"] = 0.492, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56561] = { ["id"] = 56561, ["name"] = "A Curious Discovery", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56561 }, ["description"] = "<This crystal shines with a mesmerizing light that you find difficult to avert your gaze from. Perhaps the Ankoan would be able to tell you more about it.>", ["objectivesText"] = "Bring the Enchanting Crystal to Instructor Okanu in Mezzamere. Provided item:", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 167893, 169778 }, ["starts"] = { { ["x"] = 0.328, ["y"] = 0.395, ["mapID"] = 1355, ["objectID"] = 329805 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153811, ["x"] = 0.38, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56562] = { ["id"] = 56562, ["name"] = "The Problem with Shrinkage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56562 }, ["description"] = "<Having skinned countless creatures, you can't help but notice how much usable leather is lost when the skin is dried and tanned. The Ankoan seem to have mastered using the material, perhaps Instructor Ulooaka could share some of his insights.>", ["objectivesText"] = "Ask Instructor Ulooaka about the shriveled leather hide . Provided item:", ["rewardItems"] = { 169775 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169775 } },
[56563] = { ["id"] = 56563, ["name"] = "The Problem with Shrinkage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56563 }, ["description"] = "<Having skinned countless creatures, you can't help but notice how much usable leather is lost when the skin is dried and tanned. The Unshackled seem to have a solid understanding of using the material, perhaps Rolm could share some of his insights.>", ["objectivesText"] = "Ask Rolm about the shriveled leather hide . Provided item:", ["rewardItems"] = { 169772 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154408, ["x"] = 0.492, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169772 } },
[56565] = { ["id"] = 56565, ["name"] = "Hanging by a Thread", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56565 }, ["description"] = "<As you peel the hide from the creature's body, you notice numerous scales break off the skin, tearing holes that render portions of the hide useless. The Ankoan seem to have mastered using the material, perhaps Instructor Ulooaka could share some of his insights.>", ["objectivesText"] = "Ask Instructor Ulooaka about the deteriorating cragscales . Provided item:", ["rewardItems"] = { 169767 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169767 } },
