[56719] = { ["id"] = 56719, ["name"] = "This Ain't Mine", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "Your arrival is timely, <name>. Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. We are cut off from our vanguard and I fear that they will be destroyed if we cannot reinforce them quickly. Our forces are few in number. We cannot afford to leave them stranded for long. Tinkmaster Overspark and Gazlowe believe they have a solution. Hurry and aid them however you can.", ["objectivesText"] = "Clear the pass of boulders , mines, and other obstructions between Razor Hill and Orgrimmar. Progress: Thank the Light you were able to open the pass.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 56494 }, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[56739] = { ["id"] = 56739, ["name"] = "The Power of Worship", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 56739 }, ["series"] = { 55571 }, ["description"] = "I was once like them, stuck in a loop and waiting for Azshara to come and save me. Our spirits are locked to this place. There are naga in the other parts of these ruins. They have these magical orbs... I think they are using us to fuel their arcane experiments. They draw power from our spirits and our worship of Azshara. This keeps us weakened and unable to break free. Destroy the orbs. Breaking the connection will allow us to gain strength and move on.", ["objectivesText"] = "Destroy 3 Arcane Energy Transmuters . Progress: Have you found them all?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.542, ["y"] = 0.208, ["mapID"] = 1499, ["npcID"] = 152238 } }, ["ends"] = { { ["x"] = 0.542, ["y"] = 0.208, ["mapID"] = 1499, ["npcID"] = 152238 } }, ["coords"] = { ["mapID"] = 1499, ["x"] = 0.542, ["y"] = 0.208 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 152238, ["questTurnInID"] = 152238, ["questType"] = "standard", ["sourceQuests"] = { 55571 } },
