[56741] = { ["id"] = 56741, ["name"] = "The Spear of Destiny", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["series"] = { 55574, 56325 }, ["description"] = "The Javelins are some of the most powerful magical creations of Suramar, before the Sundering. This is just what we need to bring down the wards on the protector and the Tidestone. We must hurry back to Mezzamere, Lady Proudmoore needs to know of our success. This will change the entire course of our campaign here in Nazjatar , <name>.", ["objectivesText"] = "Return to Jaina Proudmoore in Mezzamere.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55574 }, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 45, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355 },
