[56775] = { ["id"] = 56775, ["name"] = "Warming Up", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1156, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "Prepare yourself, <name>. We're nearing the island where the previous expedition was lost. Warm up on these combat dummies. We need everyone ready for whatever we find on that island.", ["objectivesText"] = "Warm up by fighting a Combat Dummy . Progress: Don't be shy. Just walk up to the target dummies, select them, and use your main attack.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["starts"] = { { ["npcID"] = 156280 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 156280, ["questType"] = "standard", ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1954, ["db2PoiUiMapID"] = 1156 },
[56777] = { ["id"] = 56777, ["name"] = "A Gift From The Clan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56777 }, ["description"] = "Speaker Utia has requested that I direct you back to Mezzamere when you have a chance, <name>. Our clan has prepared a gift for you to show our appreciation for the courage and valor you have shown in battle against the naga. I am sure that you will find the gift of supplies to be a valuable addition to your arsenal as you continue your campaign against Azshara.", ["objectivesText"] = "Meet with Speaker Utia .", ["rewardItems"] = { 168650, 169477, 169903 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 149804, ["x"] = 0.394667, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.394667, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56778] = { ["id"] = 56778, ["name"] = "A Glint in the Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56778 }, ["description"] = "There are many treasures hidden throughout Nazjatar . Recently, I spotted an object glinting from within a cave not far from here. It appeared to be some sort of lockbox. I suggest we head back and investigate. There may be valuable items inside that will help us in our battle against the naga.", ["objectivesText"] = "Loot the Lambent Lockbox.", ["rewardItems"] = { 169905 }, ["starts"] = { { ["npcID"] = 150202 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 150202, ["questType"] = "standard" },
[56779] = { ["id"] = 56779, ["name"] = "A Valorous Reward", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56779 }, ["description"] = "Your deeds on the battlefield have brought honor upon your Alliance, <class>. Speaker Utia has requested your presence in Mezzamere to accept a reward on behalf of our clan. You should return to Mezzamere at your soonest convenience. It is an honor to fight at your side.", ["objectivesText"] = "Meet with Speaker Utia .", ["rewardItems"] = { 169904 }, ["starts"] = { { ["npcID"] = 150202 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questGiverID"] = 150202, ["questType"] = "standard" },
[56780] = { ["id"] = 56780, ["name"] = "Hidden, But Dangerous", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56780 }, ["description"] = "The naga have hidden many useful treasures throughout Nazjatar . I have heard tell that there is a treasure hoard not far from here. It will be dangerous, but it may be worth investigating. There may be untold valuables inside the cache that could aid us in our fight against the naga.", ["objectivesText"] = "Loot the Mystic Chest.", ["rewardItems"] = { 169911 }, ["starts"] = { { ["npcID"] = 150202 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 150202, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56781] = { ["id"] = 56781, ["name"] = "Treasure In The Deep", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56781 }, ["description"] = "There are many treasures to be found throughout the naga stronghold of Nazjatar . Some time ago, I noticed a mysterious looking chest. The area was heavily fortified with naga troops, so whatever it contains must be valuable. We should go back and investigate the chest. Whatever is inside is better used in our hands than the hands of the enemy.", ["objectivesText"] = "Loot the Mysterious Cache.", ["rewardItems"] = { 169917 }, ["starts"] = { { ["npcID"] = 150202 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 150202, ["questType"] = "standard" },
[56782] = { ["id"] = 56782, ["name"] = "The Speaker's Gift", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56782 }, ["description"] = "Speaker Utia has requested your presence in Mezzamere, <name>. I believe that the Speaker has prepared a collection of items to aid you in your journey. You should return to Mezzamere at your soonest convenience and accept the Speaker's gift.", ["objectivesText"] = "Meet with Speaker Utia .", ["rewardItems"] = { 169903 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 149805, ["x"] = 0.394, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56783] = { ["id"] = 56783, ["name"] = "The Lambent Lockbox", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56783 }, ["description"] = "There are many treasures to find throughout these ancient ruins. Sometime ago, I noticed a strange looking chest in a cave not far from here. There may be valuable items inside that can help us in our fight against Queen Azshara. We should go back and investigate the chest.", ["objectivesText"] = "Loot the Lambent Lockbox.", ["rewardItems"] = { 169905, 169941 }, ["starts"] = { { ["npcID"] = 154304 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 154304, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56784] = { ["id"] = 56784, ["name"] = "Helpful Provisions", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56784 }, ["description"] = "Speaker Utia is awaiting your return to Mezzamere. The Speaker has bundled together some helpful provisions to aid you in your journey. Please accept this gift with the thanks of our clan.", ["objectivesText"] = "Meet with Speaker Utia .", ["rewardItems"] = { 168487, 169200, 169354, 169485, 169904, 170155 }, ["starts"] = { { ["npcID"] = 154304 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questGiverID"] = 154304, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56785] = { ["id"] = 56785, ["name"] = "The Mystic Chest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56785 }, ["description"] = "We have uncovered many rare treasures while exploring Nazjatar . I believe that I have found yet another cache of valuable artifacts to retrieve. Some time ago, I noticed a strangely glowing object in the distance. I believe that it may have been a treasure chest. We should go and investigate the object. If it is a treasure chest, its contents may prove valuable in our quest to defeat the naga!", ["objectivesText"] = "Loot the Mystic Chest.", ["rewardItems"] = { 169911 }, ["starts"] = { { ["npcID"] = 154304 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 154304, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56786] = { ["id"] = 56786, ["name"] = "Naga Treasure", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56786 }, ["description"] = "The naga have stashed away the spoils of their wars throughout Nazjatar . Earlier while we were adventuring, I noticed a mysterious looking cache. The chest is located deep within naga territory, so I imagine that whatever is inside is most likely extremely valuable. We should retrieve the contents of the cache. Whatever is inside is better used in our hands than the hands of the enemy.", ["objectivesText"] = "Loot the Mysterious Cache.", ["rewardItems"] = { 169917 }, ["starts"] = { { ["npcID"] = 154304 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 154304, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56787] = { ["id"] = 56787, ["name"] = "Additional Supplies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56787 }, ["description"] = "Speaker Utia has asked me to send you back to Mezzamere when you have a moment, <name>. The Speaker has some additional supplies that might aid you in your fight against the naga. Please return to Mezzamere at your soonest convenience and accept the Speaker's gift with the thanks of our entire clan.", ["objectivesText"] = "Meet with Speaker Utia .", ["rewardItems"] = { 169200, 169354, 169903, 170155 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 149803, ["x"] = 0.395, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56788] = { ["id"] = 56788, ["name"] = "Reclaimed Treasure", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56788 }, ["description"] = "The naga have filled Nazjatar with the ill-gotten spoils of war. We should reclaim whatever we come across in our effort to put an end to their tyranny once and for all. I noticed a strange looking chest in a cave nearby. It appeared to be of naga make. We should claim the contents of the cache. There may be valuable items inside that will help us in our battle against the naga.", ["objectivesText"] = "Loot the Lambent Lockbox.", ["rewardItems"] = { 168302, 169200, 169332, 169354, 169905, 169941, 170155 }, ["starts"] = { { ["npcID"] = 154297 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 154297, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[56789] = { ["id"] = 56789, ["name"] = "A Gift of Supplies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56789 }, ["description"] = "Speaker Utia has asked that I send you back to Mezzamere at your soonest convenience. The Speaker has gathered together a gift of supplies to further aid you in your fight against the naga. You should return to Mezzamere at your soonest convenience. Please accept this gift with the thanks of our clan.", ["objectivesText"] = "Meet with Speaker Utia .", ["rewardItems"] = { 169904 }, ["starts"] = { { ["npcID"] = 154297 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questGiverID"] = 154297, ["questType"] = "standard" },
[56790] = { ["id"] = 56790, ["name"] = "Treasure To Find", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56790 }, ["description"] = "The naga have stashed away treasures all over Nazjatar . Not long ago, I noticed an ornately crafted treasure chest hidden in plain view. The area is heavily fortified, but such minor inconveniences have not stopped us yet. We should head back there and liberate the contents of the cache.", ["objectivesText"] = "Loot the Mystic Chest.", ["rewardItems"] = { 168185, 169911 }, ["starts"] = { { ["npcID"] = 154297 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 154297, ["questType"] = "standard" },
[56791] = { ["id"] = 56791, ["name"] = "Mysterious Treasure", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56791 }, ["description"] = "We have located many treasure hoards while exploring Nazjatar . I believe that I have found yet another cache for us to liberate. Some time ago, I noticed a mysterious looking chest. It is held in an extremely dangerous area, so whatever it contains must be valuable. We should embark on a mission to liberate the contents of the cache. Whatever is inside is better used in our hands than the hands of the enemy.", ["objectivesText"] = "Loot the Mysterious Cache.", ["rewardItems"] = { 169917 }, ["starts"] = { { ["npcID"] = 154297 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 154297, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
