[56803] = { ["id"] = 56803, ["name"] = "Just A Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56803 }, ["description"] = "Look, mudfoot, I need to make sure a slight current isn't going to knock you over. I asked Atolia to see if she could pull together some things to make you a little less useless here. After what I saw in that last fight, we should probably head back sooner rather than later.", ["objectivesText"] = "Visit Atolia Seapearl in Newhome.", ["rewardItems"] = { 169903 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 149906, ["x"] = 0.495, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56804] = { ["id"] = 56804, ["name"] = "With Friends Like You, Who Needs Anemones?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56804 }, ["description"] = "I sometimes amuse myself with excursions into Zanj'ir Terrace, where the naga tough guys hang out. I grab things that could be useful and stash them somewhere I can pick them up later. I haven't been down there in a while. I could have something in there you may find useful.", ["objectivesText"] = "See what is in Vim's Cache .", ["rewardItems"] = { 169910 }, ["starts"] = { { ["npcID"] = 151309 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 151309, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56805] = { ["id"] = 56805, ["name"] = "That's What Friends Are For", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56805 }, ["description"] = "Hmm. I am not admitting to anything, but there is a very small chance that I could have possibly, but not definitely, been mistaken about your whole... thing. On the off chance we were still tolerating each other, Atolia mentioned she had another delivery for you. We should swing through Newhome.", ["objectivesText"] = "Visit Atolia Seapearl in Newhome.", ["rewardXP"] = 2765, ["rewardItems"] = { 39816, 39886, 39889, 39890, 169919 }, ["starts"] = { { ["npcID"] = 149906 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questGiverID"] = 149906, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56806] = { ["id"] = 56806, ["name"] = "Friends Through Eternity", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56806 }, ["description"] = "You may have noticed by now that me and the sea giants get along great. They mostly just want to be left alone. They want to laugh, and they want to tell you stories that make no sense. A simple life. We do share one interest, aside from killing naga, that is sampling interesting brews. Maedin recently brought in a lovely new keg, I hid it away. When it is ready to be opened, that round will be on me! Come, take a look!", ["objectivesText"] = "Visit Vim's Round .", ["rewardItems"] = { 169916 }, ["starts"] = { { ["npcID"] = 149906 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 149906, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56807] = { ["id"] = 56807, ["name"] = "Real Friends Help Hide Bodies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56807 }, ["description"] = "Bodies... treasures... I've seen it all, but it was a long time before I found someone worth calling friend. I am glad I added you to that list. So, back to those friends... I have one more place I would like you to see.", ["objectivesText"] = "Find Gorm's Lantern .", ["rewardItems"] = { 169922 }, ["starts"] = { { ["npcID"] = 149906 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 149906, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56808] = { ["id"] = 56808, ["name"] = "We're Going To Be Friends", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56808 }, ["description"] = "It is going to be fun getting to know you. You're not half bad! We kinda got a little gift for you, to welcome you to the neighborhood. I hope Atolia was able to put together something neat, she didn't have much time.", ["objectivesText"] = "Visit Atolia Seapearl , in Newhome, for your gift.", ["rewardItems"] = { 169903 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 149902, ["x"] = 0.5, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56809] = { ["id"] = 56809, ["name"] = "Super Friends", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56809 }, ["description"] = "You are a super trooper duper friend! There is a place I go to visit some of my smaller buddies. I keep some neat things I find in a bag there. Would you like to see it? What am I asking? Of course you would, let's go!", ["objectivesText"] = "See what's in Poen's Bag .", ["rewardItems"] = { 169909 }, ["starts"] = { { ["npcID"] = 151310 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 151310, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56810] = { ["id"] = 56810, ["name"] = "A Friend Indeed", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56810 }, ["description"] = "My friend, every day with you is a new adventure. I am sorry your ships crashed, but I am so happy we met! I heard a rumor, that Atolia found some more goods! We should swing by and see what she has this time!", ["objectivesText"] = "Visit Atolia Seapearl , in Newhome, for your gift.", ["rewardItems"] = { 169919 }, ["starts"] = { { ["npcID"] = 151310 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questGiverID"] = 151310, ["questType"] = "standard" },
[56811] = { ["id"] = 56811, ["name"] = "You've Got A Friend In Me", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56811 }, ["description"] = "There are a few spots I enjoy checking out with my friends. I actually found this amazing... well, I don't know what it is. Think you could check it out with me?", ["objectivesText"] = "Examine Poen's Hidey Hole .", ["rewardItems"] = { 168185, 169915 }, ["starts"] = { { ["npcID"] = 151310 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 151310, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56812] = { ["id"] = 56812, ["name"] = "Friendship Is Magic", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56812 }, ["description"] = "Every day with you, I feel like I am a better kelfin than I was the day before. You have no idea how much that means to me. I felt like I wanted to do more, be more... help more. Now, I'm starting to be a real contributing member of the Unshackled. It's all thanks to you.", ["objectivesText"] = "Seek out Poen's Wonder .", ["rewardItems"] = { 169921 }, ["starts"] = { { ["npcID"] = 151310 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 151310, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[56813] = { ["id"] = 56813, ["name"] = "An Unexpected Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56813 }, ["description"] = "Oh, <name>, I nearly forgot! To help you with your mission here in Nazjatar , Atolia and I put together some items you may need. We should swing by and grab them when we have the time!", ["objectivesText"] = "Visit Atolia Seapearl , in Newhome, for your gift.", ["rewardItems"] = { 169903 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 149904, ["x"] = 0.496, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56814] = { ["id"] = 56814, ["name"] = "Anytime You Need A Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56814 }, ["description"] = "You're not that bad for a... what was it? <race>? I like when I am reminded to look past appearances. Ha! But, really, speaking of hiding things in plain sight, I put some things in a naga crate. It is close to one of their camps in the Spears of Azshara, so they will never suspect it belongs to me! Let's go see if it is still there.", ["objectivesText"] = "Find Neri's Ruse .", ["rewardItems"] = { 169908 }, ["starts"] = { { ["npcID"] = 149904 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 149904, ["questType"] = "standard" },
[56815] = { ["id"] = 56815, ["name"] = "With A Little Help From My Friends", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56815 }, ["description"] = "It has been so long since we have been able to trust anyone not in our little pack of survivors. I forgot how good it feels. Thank you for reminding me. Atolia should have the rest of your gift together by now. We should go check in with her!", ["objectivesText"] = "Visit Atolia Seapearl , in Newhome, for your gift.", ["rewardItems"] = { 169919 }, ["starts"] = { { ["npcID"] = 151300 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questGiverID"] = 151300, ["questType"] = "standard" },
[56816] = { ["id"] = 56816, ["name"] = "A Kelfin's Best Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56816 }, ["description"] = "There is no better weapon in our fight than knowledge. Knowing you is proof of that! I found this thing, it lets me see better than my eyes could ever do before. With the water gone, I can see far, too! I have been using it sometimes to see what is happening in Nazjatar . Let me show you!", ["objectivesText"] = "Examine Neri's Find .", ["rewardItems"] = { 169914 }, ["starts"] = { { ["x"] = 0.45, ["y"] = 0.609, ["mapID"] = 1355, ["npcID"] = 151300 } }, ["ends"] = { { ["x"] = 0.45, ["y"] = 0.609, ["mapID"] = 1355, ["npcID"] = 151300 } }, ["coords"] = { ["mapID"] = 1355, ["x"] = 0.45, ["y"] = 0.609 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 151300, ["questTurnInID"] = 151300, ["questType"] = "standard" },
[56817] = { ["id"] = 56817, ["name"] = "Thank You For Being A Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 56817 }, ["description"] = "Since the waterwall appeared, so much has changed here. There is a little spot I found, where you can feel the sea spray on your face. Sometimes I just ride over there and relax. I will show it to you, if you'd like.", ["objectivesText"] = "Enjoy Neri's Spot .", ["rewardItems"] = { 169920 }, ["starts"] = { { ["npcID"] = 151300 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 151300, ["questType"] = "standard" },
