[56829] = { ["id"] = 56829, ["name"] = "Bottom Feeders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 56942, 56955, 57007, 57025, 57026, 58723, 58724 }, ["description"] = "Oh this is bad. This is really bad. Every time one of the lads makes it down here they don't come back. Things that come down here... they sort of stay down here one way or another. Let's make a deal. You're a Maw Walker. You go find Cudgelface and the Chamberlain while I get this here carriage back in service and then we all get out of here before somethin' tries to eat us and THEN go to work on us.", ["objectivesText"] = "Find Cudgelface and the Lord Chamberlain .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174102 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155668, ["x"] = 0.652, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155668, ["x"] = 0.652, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57007 }, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
