[56833] = { ["id"] = 56833, ["name"] = "Leaders of the Horde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 1534, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Saurfang has shown his true colors and now enlists the aid of the Alliance. Meet with those who have remained loyal to the Horde. They are to ready themselves for the battle against our enemies. And as for Eitrigg ... bring him to Nathanos. A quick death is too lenient a punishment for his treachery. Go, <name>. Let us end this.", ["objectivesText"] = "Order the Horde leaders in Orgrimmar to prepare for battle. Progress: There is no honor in this battle, <name>.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["x"] = 0.485, ["y"] = 0.708, ["mapID"] = 1534, ["npcID"] = 156423 } }, ["ends"] = { { ["x"] = 0.485, ["y"] = 0.708, ["mapID"] = 1534, ["npcID"] = 156423 } }, ["coords"] = { ["mapID"] = 1534, ["x"] = 0.485, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11402 } }, ["questGiverID"] = 156423, ["questTurnInID"] = 156423, ["questType"] = "standard", ["sourceQuests"] = { 56495 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534 },
[56839] = { ["id"] = 56839, ["name"] = "Killclaw the Terrible", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "<You see a crude sign made by the ogres. It contains a warning.> BIG bear! Bad! Big bear guard big ogre treasure! Kill after ritual! Get treasure, make more power!", ["objectivesText"] = "Defeat Killclaw the Terrible .", ["rewardGold"] = 6000, ["rewardXP"] = 1515, ["rewardItems"] = { 175195, 175196, 175197, 175198, 175227, 175228, 175229, 175230, 175241 }, ["rewardChoices"] = { 175197, 175229, 175195, 175227, 175198, 175230, 175196, 175228 }, ["starts"] = { { ["x"] = 0.487, ["y"] = 0.542, ["mapID"] = 1409, ["objectID"] = 330627 } }, ["ends"] = { { ["x"] = 0.487, ["y"] = 0.542, ["mapID"] = 1409, ["objectID"] = 330627 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.487, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "group", ["sourceQuests"] = { 55879, 59942 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 65, ["flags"] = 0 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[56842] = { ["id"] = 56842, ["name"] = "Lunar Preservation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Lunar Festival", ["expansion"] = 8, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 56842 }, ["description"] = "My staff has served me well for many years. It has stood by my side, been through many trials... and as I grow older I find myself leaning on it more and more. Its flowers bloom every Lunar Festival, basking in the Elune's might. They bring me so much joy, I wish for them to stay all year long. I know a way... but my bones are too old to make the trip. Perhaps you would take the journey for me? Empower my staff in the light of the moon at the moonwells around the world. Then my flowers can stay.", ["objectivesText"] = "Perform the Rite of the Moon at the moonwells scattered around the world. You can find them in Ashenvale, Felwood, Feralas, Moonglade, Stonetalon Mountains, Duskwood, and Mount Hyjal. If you let the Blessing of the Moon expire, you will have to start over. Progress: Flowers flourish under Elune's light. She was always known to cherish them.", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 21100, 71086, 151355, 170083, 170084, 170205, 187897 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 155759, ["x"] = 0.532, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 155759, ["x"] = 0.532, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard" },
[56877] = { ["id"] = 56877, ["name"] = "An Extra Sticky Situation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56877 }, ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2VignetteID"] = 3758, ["db2VignetteName"] = "Trapped Dredger" },
[56889] = { ["id"] = 56889, ["name"] = "Wounded Wastewanderers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56889 }, ["description"] = "Ahh, my friend, have you returned to render additional aid? As you can see, we are still locked in battle with these creatures, with no end to their numbers in sight. This is a war of attrition and we find ourselves at a clear disadvantage as injuries continue to mount. Please, assist any of our wounded that you find within the ruins.", ["objectivesText"] = "Heal 6 Wastewander Laborers . Progress: Do you require additional bandages?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174326 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 324 }, { ["id"] = 1553, ["amount"] = 417 }, { ["id"] = 1553, ["amount"] = 462 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[56903] = { ["id"] = 56903, ["name"] = "Crown of Courage", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Lunar Festival", ["expansion"] = 8, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 56903 }, ["description"] = "I see you are a fan of pink flowers. It is a shame those that make up your crown will one day come to perish. Perhaps I can help with that. Though those are ordinary blossoms, I know similar flowers that bloom only during Lunar Festival. If you retrieve them for me, I can imbue them with Elune's power so that you may enjoy them throughout the year.", ["objectivesText"] = "Gather blooms from Eversong Woods, the Hinterlands, and Mulgore. Progress: Not all flowers are equal. Those that bloom during Lunar Festival have a special bond with Elune.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 21100, 151355, 170205, 170278, 170279, 170280, 187897 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 155759, ["x"] = 0.532, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 155759, ["x"] = 0.532, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["sourceQuests"] = { 56842 } },
[56904] = { ["id"] = 56904, ["name"] = "Crown of Prosperity", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Lunar Festival", ["expansion"] = 8, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 56904 }, ["description"] = "Your crown is so colorful! Such beautiful pinks and yellows and blues... if only it could last. Although those particular flowers cannot, I know some that can! Similar flowers to those bloom every Lunar Festival. They hold a special connection to Elune that I can empower, thanks to you. Retrieve them for me, and we can fashion a crown that you can enjoy year round!", ["objectivesText"] = "Gather blooms from Un'goro Crater, Stranglethorn Vale, and Northern Barrens. Progress: Elune has a soft spot for flowers. Those that bloom during Lunar Festival are quite special.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 21100, 151354, 170206, 170281, 170282, 170283, 187897 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 155759, ["x"] = 0.532, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 155759, ["x"] = 0.532, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["sourceQuests"] = { 56842 } },
[56905] = { ["id"] = 56905, ["name"] = "Crown of Dark Blossoms", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Lunar Festival", ["expansion"] = 8, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 56905 }, ["description"] = "Such somber flowers... but they hold a beauty of their own, don't you think? If only they could last. Allow me to lend my aid. Every Lunar Festival, similar flowers to yours bloom around the world. They hold a special connection to Elune... one that I can empower. If you bring them to me, I can preserve them so you may enjoy them long after an ordinary flower would die.", ["objectivesText"] = "Gather blooms from Duskwood, Silverpine Forest, and Desolace. Progress: The flowers that bloom during Lunar Festival have special properties. I believe it is Elune's light watching over them.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 21100, 151353, 170207, 170296, 170298, 170308, 187897 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 155759, ["x"] = 0.532, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 155759, ["x"] = 0.532, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["sourceQuests"] = { 56842 } },
[56906] = { ["id"] = 56906, ["name"] = "Crown of Good Fortune", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Lunar Festival", ["expansion"] = 8, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 56906 }, ["description"] = "Those flowers remind me of Elune herself! I wear similar ones year round, to remind me of her watchful grace. Perhaps you would like to as well? Your crown is made of ordinary blossoms that will one day wilt and die. It is an unfortunate fate for such delicate beauties, but my crown is made of similar flowers that I made to last year round! If you bring me specific flowers that bloom only during Lunar Festival, I can bless them so that you too can enjoy your crown all year long.", ["objectivesText"] = "Gather blooms from Winterspring, Dun Morogh, and Hillsbrad Foothills. Progress: Between you and me, I believe these flowers are Elune's favorite. They mirror her lunar radiance so splendidly!", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 21100, 151352, 169208, 170319, 170321, 170322, 187897 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 155759, ["x"] = 0.532, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 155759, ["x"] = 0.532, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["sourceQuests"] = { 56842 } },
