[56955] = { ["id"] = 56955, ["name"] = "Rebels on the Road", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 56829, 56942, 57007, 57025, 57026, 58723, 58724 }, ["description"] = "This is unacceptable. The stoneborn rebels have ambushed a convoy intended for the Tithelord. He is the local Harvester who rules this ward. We need to get through this mess. The bridge on the far side of this conflict leads to Darkhaven. The Master typically keeps some of his own Stone Legion forces there. Carve us a way through, Maw Walker. Destroy any who would delay us. We must not keep Sire Denathrius waiting.", ["objectivesText"] = "Slay 5 Stoneborn Rebels .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174102, 175438, 175439, 175440, 175441 }, ["rewardChoices"] = { 175439, 175441, 175440, 175438 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6764, ["y"] = 0.7036 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 56942 }, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
