[56978] = { ["id"] = 56978, ["name"] = "To Darkhaven", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 58272 }, ["description"] = "Across this bridge is the hamlet of Darkhaven. It is fortified by those loyal to Sire Denathrius. These pitiful rebels would not dare approach it. However, getting to it may prove challenging. Here, I shall carry the anima, you make sure no one throws us back into the Endmire.", ["objectivesText"] = "Escort Lord Chamberlain to Darkhaven.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174102 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156374, ["x"] = 0.5935, ["y"] = 0.5645 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6764, ["y"] = 0.7036 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 56955, 58433 }, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[56979] = { ["id"] = 56979, ["name"] = "Saving the Siege", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "In the chaos of the rockslides, Sylvanas dispatched her saboteurs to sneak past our sentries and plant bombs on our siege weaponry. Several of them have already been lost. We cannot afford to lose more.", ["objectivesText"] = "Remove 8 Suspicious Crates.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 56719 }, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[56980] = { ["id"] = 56980, ["name"] = "Already Among Us", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "While some of the Horde have joined forces with us, many within Orgrimmar remain loyal to Sylvanas. Her saboteurs have infiltrated our ranks and are posing as our technicians. Her assassins are lurking in the shadows. Stop any loyalists you encounter, before they can cause any harm.", ["objectivesText"] = "Slay 10 Suspicious Technicians or Loyalist Assassins .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 56719 }, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[56981] = { ["id"] = 56981, ["name"] = "Strategic Deployment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "Saurfang maintains that the key to taking Orgrimmar is to exploit its multiple points of entry. He led the city's defenses for years, and knows its vulnerabilities better than anyone. We are spread thin as it is, but I trust his judgment in this matter. We must also fortify Thunder Bluff in case Sylvanas plans to assault it while our forces are committed here. Deliver these deployment orders to our officers. We will assail all of Orgrimmar's gates at once while also defending Thunder Bluff.", ["objectivesText"] = "Deliver Anduin's deployment orders.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 56719 }, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[56982] = { ["id"] = 56982, ["name"] = "Before the Gates of Orgrimmar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9663, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "We have prepared for this battle as best we can, $p. I pray that we all survive what is to come.", ["objectivesText"] = "Begin the battle at the gates of Orgrimmar.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155785, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 56979, 56980, 56981 }, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[56993] = { ["id"] = 56993, ["name"] = "The Price of Victory", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9663, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "Saurfang... how could this have happened.... <Jaina takes a moment to compose herself.> The Alliance has known High Overlord Saurfang as both a sworn enemy and an invaluable ally. Anduin will want to honor his memory. Recall our forces and inform them of what has happened. Genn's soldiers were dispatched to the western gate. You should be able to find him there.", ["objectivesText"] = "Recall the Alliance forces and inform them of what has transpired. Progress: He died a warrior's death, as he always wanted. I suppose there is some comfort in that.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155785, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155785, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 56982 }, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[57002] = { ["id"] = 57002, ["name"] = "Old Soldier", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "No matter what doubts he harbored, Saurfang was an honorable soldier. He prevented both a civil war within the Horde and the potential destruction of the Alliance. He brought an end to Sylvanas's reign and saved many lives at the cost of his own. We shall honor his sacrifice.", ["objectivesText"] = "Speak with Jaina in front of the gates of Orgrimmar. Progress: Thank you for coming.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155785, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155785, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 56993 }, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161 },
[57003] = { ["id"] = 57003, ["name"] = "Create Your Own Strength", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 57003 }, ["description"] = "For something that has been sitting on the ocean floor, there is still power to be found in this item. Take your piece of Benthic armor to Voidbinder Zorlan. He has been eyeing it with great curiosity. Go ahead and humor the ethereal and let him have a look. Maybe he has something to offer.", ["objectivesText"] = "Upgrade a piece of Benthic armor through Voidbinder Zorlan.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55481 } },
[57004] = { ["id"] = 57004, ["name"] = "Create Your Own Strength", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 57004 }, ["description"] = "That Benthic armor you carry has been lost beneath the tides for too long. There is still power within it. Voidbinder Sturzah may be able to provide insight. Take your find to our intrepid ethereal friend, and see what he can do with it.", ["objectivesText"] = "Upgrade a piece of Benthic armor through Voidbinder Sturzah. Progress: Were you successful?", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 169482 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56350 } },
[57005] = { ["id"] = 57005, ["name"] = "Becoming a Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 57005 }, ["description"] = "Some of our bravest kelfin have volunteered to join you on your adventures, should you ever need a friend. You will find they each have their own special interests and they will mark your map with different opportunities every day. Use the conch when you're ready, choose who you would like to join you, and explore Nazjatar ! Choose wisely! You may only select one friend per day.", ["objectivesText"] = "Use the Calling Conch , choose an ally, and complete 3 ally quests.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 12 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 } },
[57006] = { ["id"] = 57006, ["name"] = "A Worthy Ally", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 57006 }, ["description"] = "Some of our bravest ankoan have volunteered to join you on your expedition. You will find each have their own special interests and they will mark your map with different opportunities every day. Use the Deepflame Campfire when you are ready. Choose a noble ally to join you, and explore what remains of Nazjatar . Choose wisely! You may only select one friend per day.", ["objectivesText"] = "Use the Deepflame Campfire , choose an ally, and complete 3 ally quests.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 205983, 205985, 210421, 210872 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 12 } }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 56156 } },
[57007] = { ["id"] = 57007, ["name"] = "Invitation of the Master", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 56829, 56942, 56955, 57025, 57026, 58723, 58724 }, ["description"] = "The great Sire Denathrius, Master of Revendreth , and King of the venthyr, has asked me, his loyal Chamberlain, to escort you safely to his personal gardens. This is an honor never before bestowed upon a living mortal. You should feel honored. Come, join me in the carriage and we shall ride to the castle in style.", ["objectivesText"] = "Ride the Darkhaven Carriage .", ["rewardGold"] = 64350, ["rewardXP"] = 355, ["rewardItems"] = { 174102 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155668, ["x"] = 0.652, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6764, ["y"] = 0.7036 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57026 }, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57008] = { ["id"] = 57008, ["name"] = "Assault: The Warring Clans", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 57008 }, ["description"] = "The opportunistic mogu clans seek to take the Vale while its defenders are recovering from N'Zoth's attack. They are both cowardly and foolish. Show them the error of their ways.", ["objectivesText"] = "Drive back the Mogu Assault in the Vale of Eternal Blossoms . Progress: Yes?", ["rewardXP"] = 10225, ["rewardItems"] = { 170497, 174958 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Push back the mogu forces", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
