[57024] = { ["id"] = 57024, ["name"] = "Rumors of Mechagon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1355, ["storyline"] = { 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 57024 }, ["description"] = "I knew I should've taken that gig with the Greasemonkeys... Gazlowe 's crew always get paid, and no dumb risks. I heard they got somethin' big comin' up too...", ["objectivesText"] = "Meet Gazlowe outside the Great Seal in Dazar'alor.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 156187, ["x"] = 0.484, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 152522, ["x"] = 0.53, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 1165, 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["sourceQuests"] = { 55500 }, ["nextQuests"] = { 55646 }, ["questLines"] = { { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 10, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165 },
[57025] = { ["id"] = 57025, ["name"] = "A Plea to Revendreth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 56829, 56942, 56955, 57007, 57026, 58723, 58724 }, ["description"] = "Revendreth is quite possibly the most... efficient... realm at extracting anima. Perhaps they can lend aid where others cannot. Know that while souls sometimes return from Revendreth , they are never the same when they do. It is a dark realm, where those the Arbiter deems worthy of a chance of redemption are sent. Their path, however, is not an easy one. Kah-Sher will assist you in opening the gateway to Revendreth . Meet him in the Ring of Transference.", ["objectivesText"] = "Journey to Revendreth .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174102 }, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.702, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155537, ["x"] = 0.7, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 58724 }, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57026] = { ["id"] = 57026, ["name"] = "The Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["series"] = { 56829, 56942, 56955, 57007, 57025, 58723, 58724 }, ["description"] = "Well, you ain't like the others. Usually you're supposed to be dead before you come here. Ah well. A sin is a sin and a stone is a stone, as it goes. Let's get you sorted out with your sinstone . This way, if you please.", ["objectivesText"] = "Take the tour.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 173793, 173794, 173795, 174102, 181175, 181177, 181178, 181179, 181180, 181183, 181185, 181191, 181195, 181196, 181197, 181199, 181200, 181202, 181211, 181217, 181218, 181334, 181545, 181546, 181547, 181548, 181550, 181708, 182724, 184147, 184150, 184777, 185942 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155537, ["x"] = 0.7, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57025 }, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57037] = { ["id"] = 57037, ["name"] = "A Once Sweet Sound", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "The bells! That sound! Their song has been twisted! If their dire toll continues, we will all succumb. < Eridia presses her hammer into your hands.> Find the great vespers within the temple and strike them with my hammer. May the mallet's tonal purity restore their true voices! I will listen for their clarion call and meet you near the bridge. Go swiftly!", ["objectivesText"] = "Cleanse the Vesper of Purity and the Vesper of Harmony . Progress: Such a bitter sound!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171215, 176333, 176335 }, ["rewardChoices"] = { 176335, 176333 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57717 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57043] = { ["id"] = 57043, ["name"] = "Old Friends, New Opportunities", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "Greetings, <name>. I have a... strange message for you from a group of goblins. Someone named Sassy Hardwrench is asking for your help for what was described as a, \"big job\". The word \"big\" was mentioned several times, followed by murmuring about time and money. Sassy is waiting for you over in Stranglethorn Vale.", ["objectivesText"] = "Speak with Sassy Hardwrench in Stranglethorn Vale.", ["rewardGold"] = 31200, ["rewardXP"] = 850, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 156358, ["x"] = 0.395, ["y"] = 0.801 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.801 }, ["mapCandidates"] = { ["npc"] = { 85, 210 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 210 },
[57045] = { ["id"] = 57045, ["name"] = "A Special Delivery", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "I'm glad you're finally here, <name>. I've got an important delivery to make and you're the goblin I trust most. Yeah, yeah. I know that's not sayin' much, but it's hard to find good help these days! This package is for Hobart Grapplehammer . He's got a workshop in Crapopolis and I need you to deliver it to him. He's been working on somethin' big lately! Deliver the package and for the love of money... DON'T DROP IT! You have no idea how long it took me to locate this thing!", ["objectivesText"] = "Deliver the package to Hobart Grapplehammer . Progress: Gallywix sure has some nerve threatening me in my own laboratory! He thinks he can just do whatever he wants to whoever he wants...", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 30256, 30257, 30258, 142054, 170538 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questTurnInID"] = 156396, ["questType"] = "standard", ["sourceQuests"] = { 57043 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532 },
[57047] = { ["id"] = 57047, ["name"] = "A Simple Experiment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "Now that you've delivered the necessary parts, I can begin testing my latest prototype! I call it the X-52 Personnel Armor! It will be nearly indestructible! Gallywix has always coveted my inventions and now that he knows about the X-52 I'm sure he'll be up to no good. I've gotta complete the prototype before Gallywix comes up with a way to steal it out from under me! I could really use an extra set of hands with the experiments. Can I count on you, <name>?", ["objectivesText"] = "Assist Hobart Grapplehammer . Progress: We need to complete the X-52 Personnel Armor before Gallywix finds a way to steal the prototype!", ["rewardGold"] = 312800, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.535, ["y"] = 0.619, ["mapID"] = 1532, ["npcID"] = 156520 } }, ["ends"] = { { ["x"] = 0.535, ["y"] = 0.619, ["mapID"] = 1532, ["npcID"] = 156520 } }, ["coords"] = { ["mapID"] = 1532, ["x"] = 0.535, ["y"] = 0.619 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questGiverID"] = 156520, ["questTurnInID"] = 156520, ["questType"] = "standard", ["sourceQuests"] = { 57045 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532 },
[57048] = { ["id"] = 57048, ["name"] = "Shopping For Parts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "I'm going to need some additional components in order to complete the next phase of testing. Right now, what we need most are thermoplugs and thermoplug adaptors! I'll explain what they're for later... Crank Greasefuse runs a shop near the entrance of the town. Go speak with Crank and get him to fork over the necessary parts. I don't care what they cost, just tell him to bill me later! I can't be bothered to negotiate right now. I need to prepare the modifications to the X-52 Personnel Armor!", ["objectivesText"] = "Speak with Crank Greasefuse .", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.529, ["y"] = 0.586, ["mapID"] = 1532, ["npcID"] = 156520 } }, ["ends"] = { { ["x"] = 0.529, ["y"] = 0.586, ["mapID"] = 1532, ["npcID"] = 156520 } }, ["coords"] = { ["mapID"] = 1532, ["x"] = 0.529, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questGiverID"] = 156520, ["questTurnInID"] = 156520, ["questType"] = "standard", ["sourceQuests"] = { 57047 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532 },
[57049] = { ["id"] = 57049, ["name"] = "Vault of Souls", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["starts"] = { { ["x"] = 0.1696, ["y"] = 0.4567, ["mapID"] = 1530 } }, ["ends"] = { { ["x"] = 0.1696, ["y"] = 0.4567, ["mapID"] = 1530 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9105 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 156271 } } },
[57051] = { ["id"] = 57051, ["name"] = "Debt Collection!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "You need thermoplugs? Well, you came to the right place, kid. But I ain't giving 'em to you on credit. There's way too many shlubs who haven't paid me back the money they owe. I'm in over my head here, if I don't get paid fast, I'll be out of business in no time. < Crank Greasefuse thinks for a moment.> Look, I tell you what... If you can muscle those no-good goons into paying me my money, I'll give you the thermoplugs as payment. You won't find a better deal than that!", ["objectivesText"] = "Collect 8 Unpaid Debts . Progress: You got my money?", ["rewardGold"] = 312800, ["rewardXP"] = 6815, ["rewardItems"] = { 171089 }, ["starts"] = { { ["x"] = 0.56, ["y"] = 0.782, ["mapID"] = 1532, ["npcID"] = 156542 } }, ["ends"] = { { ["x"] = 0.56, ["y"] = 0.782, ["mapID"] = 1532, ["npcID"] = 156542 } }, ["coords"] = { ["mapID"] = 1532, ["x"] = 0.56, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questGiverID"] = 156542, ["questTurnInID"] = 156542, ["questType"] = "standard", ["sourceQuests"] = { 57048 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532 },
[57052] = { ["id"] = 57052, ["name"] = "I've Got What You Need", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "A deal's a deal, <name>. Here's the thermoplugs you ordered! Be sure to let that ol' grouch Grapplehammer know that I won't be giving out anymore handouts. If he needs more thermoplugs he'd better be ready to pay up. Anyway, it was a pleasure doing business with you... Now get lost!", ["objectivesText"] = "Deliver the package to Hobart Grapplehammer .", ["rewardGold"] = 31200, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.56, ["y"] = 0.782, ["mapID"] = 1532, ["npcID"] = 156542 } }, ["ends"] = { { ["x"] = 0.56, ["y"] = 0.782, ["mapID"] = 1532, ["npcID"] = 156542 } }, ["coords"] = { ["mapID"] = 1532, ["x"] = 0.56, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questGiverID"] = 156542, ["questTurnInID"] = 156542, ["questType"] = "standard", ["sourceQuests"] = { 57051 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532 },
[57058] = { ["id"] = 57058, ["name"] = "Fun With Landmines", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "The prototype X-52 Personnel Armor is ready for the final test! How are you with loud noises and sudden bursts of concussive energy, <name>? For the final test, we're going to strap you into the X-52 Personnel Armor and have you traverse a minefield! I have placed a refreshing coconut beverage in the center of the minefield. Consider the drink a fitting reward for reaching the oasis and surviving the inevitable explosions in the process!", ["objectivesText"] = "Retrieve the refreshing coconut beverage from the minefield. Progress: Ballistic testing... IS MY FAVORITE!", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 174059 }, ["starts"] = { { ["x"] = 0.587, ["y"] = 0.608, ["mapID"] = 1532, ["npcID"] = 156520 } }, ["ends"] = { { ["x"] = 0.587, ["y"] = 0.608, ["mapID"] = 1532, ["npcID"] = 156520 } }, ["coords"] = { ["mapID"] = 1532, ["x"] = 0.587, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questGiverID"] = 156520, ["questTurnInID"] = 156520, ["questType"] = "standard", ["sourceQuests"] = { 57053 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532 },
[57059] = { ["id"] = 57059, ["name"] = "Let's Rumble!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "This is bad, <name>! Real bad! Gallywix and his goons are destroying my workshop, but he's got another thing coming if he thinks I'm gonna hand over the X-52 Personnel Armor! You've gotta get down there and clear out his goon squad before this place--AND ALL MY INVENTIONS--go up in flames!", ["objectivesText"] = "Defeat 8 Hired Scoundrels . Progress: Hurry, <name>! Gallywix and his goons are destroying my worskshop!", ["rewardGold"] = 238680, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.52, ["y"] = 0.593, ["mapID"] = 1532, ["npcID"] = 156520 } }, ["ends"] = { { ["x"] = 0.52, ["y"] = 0.593, ["mapID"] = 1532, ["npcID"] = 156520 } }, ["coords"] = { ["mapID"] = 1532, ["x"] = 0.52, ["y"] = 0.593 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questGiverID"] = 156520, ["questTurnInID"] = 156520, ["questType"] = "standard", ["sourceQuests"] = { 57058 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532 },
[57067] = { ["id"] = 57067, ["name"] = "Mogu at the Gates", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57068, 57069 }, ["description"] = "The time has come. The other mogu clans have set their sights on the Vale of Eternal Blossoms . They will not conquer it. Some of your kind have already gone to the gate to scout out the size of their force. If you think yourself worthy for such a mission, meet them there.", ["objectivesText"] = "Meet Chen and Li Li Stormstout at the Gate of the August Celestials.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156297, ["x"] = 0.555, ["y"] = 0.911 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 379, 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1795, ["db2PoiUiMapID"] = 1530 },
[57068] = { ["id"] = 57068, ["name"] = "Kite Surveillance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57067, 57069 }, ["description"] = "We heard for ourselves that there were mogu attacking, but I had no idea it would be this many! There must be a way to stop them before they completely overrun the Vale. Quickly, let us fly over and scout out their numbers. We just so happen to have a kite that can carry three people. Usually it's more, but I had a big lunch.", ["objectivesText"] = "Ride Chen's Kite to scout the Mogu armies.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156297, ["x"] = 0.555, ["y"] = 0.911 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156391, ["x"] = 0.6, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.911 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 57067 }, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[57069] = { ["id"] = 57069, ["name"] = "Cut Off the Heads", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57067, 57068 }, ["description"] = "Okay. We're stuck in the middle of three mogu armies, and Uncle Chen is too hurt to move yet. It's not hopeless though. We have the chance to take out the leaders of these armies. Maybe that will slow them down or distract them long enough for us to get back to the gate! See if you can get out there and take down the biggest, baddest mogu you can find. Those will be the commanders.", ["objectivesText"] = "Slay mogu commanders.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156391, ["x"] = 0.6, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156391, ["x"] = 0.6, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 57068 }, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[57070] = { ["id"] = 57070, ["name"] = "Mogu Massacre", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["description"] = "I think this is what my friends would call a \"target rich environment.\" As a nicer way of saying \"we're surrounded and probably doomed.\" You know what this means. We have to kill as many of these mogu as possible! It doesn't matter how you do it, just take them out!", ["objectivesText"] = "Slay mogu in Kun-Lai Summit .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156391, ["x"] = 0.6, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156391, ["x"] = 0.6, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 57068 }, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[57071] = { ["id"] = 57071, ["name"] = "No Brew Left Behind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["description"] = "My head is... hurting. There can be only one solution. We flew over an abandoned brew caravan. You must go find it, and save that brew! That should help bring me back to full strength. Plus, it would do wonders for the morale of those fighting in the Vale, if we can recover it.", ["objectivesText"] = "Locate the abandoned brew barrels in Kun-Lai Summit .", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156390, ["x"] = 0.6, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 157180, ["x"] = 0.585, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 57068 }, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[57072] = { ["id"] = 57072, ["name"] = "Yak of All Trades", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["description"] = "<The brew barrels are too heavy and numerous to carry alone. Perhaps you can find something, or someone, to help you.>", ["objectivesText"] = "Find something to help you carry the brew back to Chen in Mogujia.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 157180, ["x"] = 0.585, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156390, ["x"] = 0.6, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 57071 }, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[57074] = { ["id"] = 57074, ["name"] = "Our Backs to the Gate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57075, 57076 }, ["description"] = "It is most fortuitous that you found this brew, and a yak to carry it on! But we cannot remain here. Li Li has healed me up enough to travel. We can ride the yak back to the gate and hope that the mogu do not notice our passing. Let me know when you are ready to leave.", ["objectivesText"] = "Ride Mobi with Chen and Li Li to the Gate of August Celestials.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156390, ["x"] = 0.6, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156938, ["x"] = 0.555, ["y"] = 0.912 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 57069, 57070, 57072 }, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[57075] = { ["id"] = 57075, ["name"] = "Liquid Courage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57074, 57076 }, ["description"] = "We have to do something about all these mogu. At least to thin their ranks before they invade the Vale! As much as Uncle Chen loves his brew, I think we can put it to better use. Let's hop onto that yak and give the mogu something to fear!", ["objectivesText"] = "Mount Mobi and defeat the mogu armies with the power of brew. Progress: Something must be done about all these mogu, or we will lose the Vale.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156938, ["x"] = 0.555, ["y"] = 0.912 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156937, ["x"] = 0.554, ["y"] = 0.91 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.912 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 57074 }, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[57076] = { ["id"] = 57076, ["name"] = "Return to Mistfall", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57074, 57075 }, ["description"] = "We have done all we can here. We know how much the mogu are a clear threat. The forge is in great danger of falling into their hands if we lose our hold on the Vale. Let us return to Mistfall and report to the Rajani. They will want to know what we are up against.", ["objectivesText"] = "Return to Stormspeaker Qian in the Silent Sanctuary in the Vale of Eternal Blossoms.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156937, ["x"] = 0.554, ["y"] = 0.91 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.91 }, ["mapCandidates"] = { ["npc"] = { 379, 1530 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 57075 }, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[57077] = { ["id"] = 57077, ["name"] = "Buyers Wanted!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11455, ["mapID"] = 210, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "The X-52 Personnel Armor is finally complete and Gallywix has been sent packing with his tail between his legs! I've got you to thank for this, <name>! But we're still not done... the best part is yet to come. We're going to hold an auction and sell the X-52 Personnel Armor to the highest bidder! Sassy Hardwrench should have a list of interested buyers ready to go. Head over to Hardwrench Hideaway and let her know we're ready for the auction!", ["objectivesText"] = "Speak with Sassy Hardwrench in Stranglethorn Vale.", ["rewardGold"] = 31200, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.52, ["y"] = 0.593, ["mapID"] = 1532, ["npcID"] = 156520 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 11455 } }, ["questGiverID"] = 156520, ["questType"] = "standard", ["sourceQuests"] = { 57059 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 210 },
[57078] = { ["id"] = 57078, ["name"] = "The VIP List", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "While you've been assisting Grapplehammer with his newest invention, I've been hard at work finding potential buyers! This is going to be a private auction, so we're only inviting the best and the brightest, the cream of the crop, the creme de la creme... got it? I've narrowed the potential buyers down to an 'A' list of only the wealthiest, classiest, most connected goblins around... minus Gallywix, of course! Head out and deliver these invitations while I finish up preparations for the auction!", ["objectivesText"] = "Deliver the invitations to Grapplehammer's private auction. Progress: This will be an 'A' list event. Only Kezan's finest will be in attendance!", ["rewardGold"] = 312800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["sourceQuests"] = { 57077 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 210 },
[57079] = { ["id"] = 57079, ["name"] = "Beat The Crapopolis Outta Him!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "Boy am I glad to see you! We've got a bad situation on our hands... While you were away delivering the invitations, Gallywix and his goons took over Crapopolis! They're holding Hobart Grapplehammer hostage until he hands over the X-52 Personnel Armor! You have to stop Gallywix before it's too late!", ["objectivesText"] = "Complete the Crapopolis scenario.", ["rewardGold"] = 683200, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questTurnInID"] = 156396, ["questType"] = "standard", ["sourceQuests"] = { 57078 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2258, ["db2PoiUiMapID"] = 1531 },
[57080] = { ["id"] = 57080, ["name"] = "A Fitting Reward", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1531, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "Although the X-52 Personnel Armor's power-core was destroyed during the battle with Gallywix, the invention was a success! I doubt anyone will be interested in purchasing the rights to the X-52 without a working power-core, so why don't you hang onto the armor instead? It is quite stylish after all! Now that Crapopolis is saved and Gallywix is conveniently trapped inside of his own mechanical pummeler, I think I'm going to renegotiate that \"contract\" of his. He is a \"captive audience\" after all!", ["rewardGold"] = 573000, ["rewardXP"] = 8520, ["rewardItems"] = { 173978, 174077 }, ["starts"] = { { ["x"] = 0.478, ["y"] = 0.505, ["mapID"] = 1531, ["npcID"] = 157491 } }, ["ends"] = { { ["x"] = 0.478, ["y"] = 0.505, ["mapID"] = 1531, ["npcID"] = 157491 } }, ["coords"] = { ["mapID"] = 1531, ["x"] = 0.478, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 157491, ["questTurnInID"] = 157491, ["questType"] = "standard", ["sourceQuests"] = { 57079 }, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2258, ["db2PoiUiMapID"] = 1531 },
[57086] = { ["id"] = 57086, ["name"] = "Legacy of the Mad Mage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10052, ["storyline"] = { 57086 }, ["description"] = "<This rather large jewel has an inscription etched on its base: Property of Mardivas. If found please return to my laboratory. Perhaps this laboratory can still be found somewhere?>", ["objectivesText"] = "Investigate Mardivas's Laboratory. Progress: <The chest appears to be simply constructed, but the locking mechanism hums with arcane energy.>", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 170489, 170512, 170547 }, ["rewardCurrencies"] = { { ["id"] = 1721, ["amount"] = 10 }, { ["id"] = 1721, ["amount"] = 7 } }, ["starts"] = { { ["x"] = 0.794, ["y"] = 0.272, ["mapID"] = 1355 } }, ["ends"] = { { ["x"] = 0.794, ["y"] = 0.272, ["mapID"] = 1355 } }, ["coords"] = { ["mapID"] = 1355, ["x"] = 0.794, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 170512 } },
[57087] = { ["id"] = 57087, ["name"] = "Baruk Obliterator", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["starts"] = { { ["x"] = 0.313, ["y"] = 0.289, ["mapID"] = 1530 } }, ["ends"] = { { ["x"] = 0.313, ["y"] = 0.289, ["mapID"] = 1530 } }, ["coords"] = { ["mapID"] = 1530, ["x"] = 0.313, ["y"] = 0.289 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9105 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 2, ["amount"] = 1, ["objectID"] = 333422 }, { ["orderIndex"] = 1, ["type"] = 2, ["amount"] = 1, ["objectID"] = 333424 }, { ["orderIndex"] = 2, ["type"] = 2, ["amount"] = 1, ["objectID"] = 333425 }, { ["orderIndex"] = 3, ["type"] = 2, ["amount"] = 1, ["objectID"] = 333478 } } },
[57088] = { ["id"] = 57088, ["name"] = "This Ain't Mine", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. Our forces are now cut off from each other. We need to reinforce our front line or the Banshee will pick us off at her leisure. We have come too far to be slain by a thousand cuts. Gazlowe and one of the Alliance's gnomes believe they have an answer. You'd best ensure that their plan does not backfire.", ["objectivesText"] = "Clear the pass of boulders , mines, and other obstructions between Razor Hill and Orgrimmar. Progress: Hmm. Maybe that goblin's gadgets have some use.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 56496 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[57090] = { ["id"] = 57090, ["name"] = "Saving the Siege", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "The Banshee's spies were able to sneak past our guards in the chaos of the rockslides. They've been planting bombs on our siege weaponry. Get rid of those bombs.", ["objectivesText"] = "Remove 8 Suspicious Crates.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 57088 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[57091] = { ["id"] = 57091, ["name"] = "Already Among Us", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Sylvanas still commands the loyalty of many within the Horde. The war she started has blinded them with rage and hatred. She exploits that to maintain her support. <Saurfang scowls.> They do not yet see she will lead us to ruin, that her so-called victories are all hollow. Some of her agents have been spotted lurking within our ranks. Kill them. They will show us no mercy, and will have none in return.", ["objectivesText"] = "Slay 10 Suspicious Technicians or Loyalist Assassins .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 57088 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[57092] = { ["id"] = 57092, ["name"] = "Strategic Deployment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "For years, I guarded the gates of Orgrimmar. The city's greatest weakness has always been its multiple entrances. We should strike at all of them to seize victory. Wrynn and I have drawn up orders for deployment. The mages will cover our flank. Greymane will close in from the west, and the elves will take the north. We will send Mayla to reinforce Thunder Bluff's defenses in case Sylvanas launches a counterattack. Bring the orders to our commanders.", ["objectivesText"] = "Deliver Saurfang's deployment orders.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 57088 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[57093] = { ["id"] = 57093, ["name"] = "Before the Gates of Orgrimmar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "It is time. We have done all that we can to prepare. All that remains is the battle itself. I am not one for speeches. So I will say only this. Lok-tar ogar, <name>. Victory. Or death.", ["objectivesText"] = "Begin the battle at the gates of Orgrimmar.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 155789, ["x"] = 0.5, ["y"] = 0.96 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1, 1165 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 57090, 57091, 57092 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[57094] = { ["id"] = 57094, ["name"] = "The Price of Victory", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 1165, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Saurfang... I... <Lor'themar takes a moment to compose himself.> ...Thrall will wish to honor Saurfang's sacrifice. And so shall the rest of us. Recall our forces. Let them know what has transpired. Tell them that the great warrior Varok Saurfang is dead and that the warchief has abandoned us. Speak to Baine when you arrive in Thunder Bluff. You will find him on the Elder Rise. I am certain he will want to pay his respects to Saurfang as well. Let us stand as a united Horde once more.", ["objectivesText"] = "Inform Baine Bloodhoof of what has transpired. Progress: He earned the warrior's death he always sought. There is honor in that.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 155789, ["x"] = 0.5, ["y"] = 0.96 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 155789, ["x"] = 0.5, ["y"] = 0.96 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.96 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["sourceQuests"] = { 57093 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535 },
[57095] = { ["id"] = 57095, ["name"] = "Old Soldier", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 1165, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "No matter what anyone says, he was an honorable orc. A legend in his own right, the ideal to which all warriors of the Horde aspired. He gave his life to heal the rift in the Horde and give us the chance to forge a new path forward. His was more than a death befitting a warrior. It was the death of a hero. We shall honor his sacrifice.", ["objectivesText"] = "Honor High Overlord Saurfang.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 165791 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 155789, ["x"] = 0.5, ["y"] = 0.96 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155787, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.96 }, ["mapCandidates"] = { ["npc"] = { 1, 1165 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 57094 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[57098] = { ["id"] = 57098, ["name"] = "The Grove of Terror", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Ah, yes. You've done me a great favor in delivering the Accuser, Maw Walker. To celebrate, I must insist that you take part in a sacred tradition of Revendreth : The Penitent Hunt. It is a duty we undertake to strike a humbling fear into the hearts of the most... stubborn souls. Fear can be a very powerful motivator for change. Meet the Fearstalker in the Grove of Terror below. There you will prepare.", ["objectivesText"] = "Meet the Fearstalker in the Grove of Terror.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156381, ["x"] = 0.534, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 169087, ["x"] = 0.505, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59232 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57099] = { ["id"] = 57099, ["name"] = "A Dreadful Roundup", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57099 }, ["description"] = "Welcome to The Banewood, Maw Walker. As Huntmaster it is my duty to lead the Fearstalk. Our first order of business is to collect the souls selected for the hunt. In the woods behind me we have souls who have been ripening for several hundred years now. Go choose the souls who will be hunted today.", ["objectivesText"] = "Collect 6 Condemned Souls .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[57100] = { ["id"] = 57100, ["name"] = "Feeding Time is Over", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57100 }, ["description"] = "A crucial element to a successful Fearstalk is our tool: the fangs of a terrorbeast. Their fangs are perfect for revealing the scent of their prey once bound to a soul. There's plenty of them in the forest surrounding the ripening souls. Go and collect some from their corpses. Their population is a bit large right now anyhow.", ["objectivesText"] = "Kill Winged Terrorbeasts and collect 6 of their fangs.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 170513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[57101] = { ["id"] = 57101, ["name"] = "Zan-Tien Serpent Cage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["starts"] = { { ["x"] = 0.477, ["y"] = 0.215, ["mapID"] = 1530 } }, ["ends"] = { { ["x"] = 0.477, ["y"] = 0.215, ["mapID"] = 1530 } }, ["coords"] = { ["mapID"] = 1530, ["x"] = 0.477, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9105 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 2, ["amount"] = 1, ["objectID"] = 333507 }, { ["orderIndex"] = 1, ["type"] = 2, ["amount"] = 1, ["objectID"] = 333506 }, { ["orderIndex"] = 2, ["type"] = 2, ["amount"] = 1, ["objectID"] = 333505 }, { ["orderIndex"] = 3, ["type"] = 2, ["amount"] = 1, ["objectID"] = 333504 } } },
[57102] = { ["id"] = 57102, ["name"] = "Pardon Our Dust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["series"] = { 59774 }, ["description"] = "Ah yes, the Greeter. It seems this Mnemis unit has been deactivated. Anima has been so scarce of late, and with no new souls entering our gates... I suppose it was a prudent measure. Anima is our most precious resource, after all. There are some centurions nearby. A portion of their Anima could serve our needs. Ah! One of our most helpful stewards is here to lend her aid. She will guide you in the collection effort. Return when you have sufficient Anima and we will power the Greeter once more.", ["objectivesText"] = "Collect anima from nearby centurions. Progress: <The centurion is unresponsive.>", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158281, ["x"] = 0.422, ["y"] = 0.782 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.461333, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 59774 }, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57112] = { ["id"] = 57112, ["name"] = "Test Shared Quest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 57112 }, ["description"] = "None See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(57112)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(57112))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57113] = { ["id"] = 57113, ["name"] = "On Lysonia's Trail", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["series"] = { 57114 }, ["description"] = "Our scouts have reported spotting Lysonia and Uther en route to the Temple of Humility. As the de facto leader of the Forsworn, we must not allow her to stand free, twisting the minds of those around her. The disciples of Humility have not answered our beckons. I have sent Kleia ahead to reconnoiter. Meet her outside the temple.", ["objectivesText"] = "Meet Kleia outside the Temple of Humility.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 61697 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57114] = { ["id"] = 57114, ["name"] = "Aerial Reconnaissance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["series"] = { 57113 }, ["description"] = "The temple grounds are crawling with those loyal to the Forsworn. If I were still an aspirant, this task would be monumental. Luckily, that is no longer the case. Let us survey the situation from the sky. We can both take stock of the challenges ahead and find any survivors we can.", ["objectivesText"] = "Fly with Kleia to find the survivors.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.653333, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57113 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57115] = { ["id"] = 57115, ["name"] = "Sacred Scrolls of Humility", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "The Forsworn are ransacking the library, looking for specific texts amongst our archives. We cannot allow them to uncover the scrolls they are searching for. Find any set aside scrolls and return them to me for safekeeping.", ["objectivesText"] = "Collect 5 Sacred Scrolls . Progress: The scrolls throughout these temples cover many topics, from information on different worlds, to training pillars, to ancient rituals.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57114 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57116] = { ["id"] = 57116, ["name"] = "Succumbing to Pride", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "The aspirants that spend the most time at this temple are those who must face their pride. I was one of them, once. During our surveillance, I saw Forsworn forcing these aspirants to fall to their vices then toss them aside as if they meant nothing. You must stop the Forsworn. Free the aspirants from a terrible fate.", ["objectivesText"] = "Free 5 Burdened Aspirants by stopping Forsworn rituals.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.653333, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57114 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57117] = { ["id"] = 57117, ["name"] = "Fallen to Their Vices", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "Lysonia's forces ransack our sacred temple... they are long gone from the Archon's embrace. It pains me to say, but you must defeat them so they can no longer abuse our people. Take Compassion with you. You will find it more than helpful, now that its power has returned.", ["objectivesText"] = "Defeat 15 Forsworn forces in the Terrace of Inner Grace.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550, 181291 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57115, 57116, 57120 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57118] = { ["id"] = 57118, ["name"] = "Distorted by the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "Lysonia's forces are rerouting the anima collectors to spew Maw energy across the temple. They hamper our forces while strengthening their own. The collectors have been tainted. Take Compassion and destroy them to halt Lysonia's boon.", ["objectivesText"] = "Destroy 3 Anima Collectors in the Terrace of Inner Grace.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57115, 57116, 57120 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57120] = { ["id"] = 57120, ["name"] = "Compassion, Blade of Humility", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "<You find a familiar sword impaled into one of the Forsworn corpses. The Paragon of Humility must have left it behind in pursuit of Lysonia. It seems inert, as if all its anima has been used. Perhaps you could restore it to its usual glory.>", ["objectivesText"] = "Charge Compassion, Blade of Humility by killing manifestations. Progress: The Paragon rarely uses his weapon. He prefers debate and reason over the use of force.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["starts"] = { { ["x"] = 0.647, ["y"] = 0.456, ["mapID"] = 1533, ["objectID"] = 353472 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156327, ["x"] = 0.66, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57114 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57121] = { ["id"] = 57121, ["name"] = "The Power of the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "Lysonia flees to the Maw to enact her dark rituals. As the Maw Walker, you are the only one who can pursue her. Take Kleia and my blade. She must be stopped.", ["objectivesText"] = "Enter the Maw with Kleia , then meet her outside Perdition Hold.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156474, ["x"] = 0.69, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57207 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[57122] = { ["id"] = 57122, ["name"] = "A Step Too Far", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "My initial scouting revealed things I did not believe at first. The Mawsworn hold Forsworn captive here, transforming them against their will. Though the Forsworn stand against the Archon, they are still kyrian. It is our duty to free them.", ["objectivesText"] = "Free 5 Captive Forsworn. Progress: I cannot stand idly by while my brothers and sisters are tormented.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["starts"] = { { ["x"] = 0.338, ["y"] = 0.557, ["mapID"] = 1543, ["npcID"] = 170375 } }, ["ends"] = { { ["x"] = 0.338, ["y"] = 0.557, ["mapID"] = 1543, ["npcID"] = 170375 } }, ["coords"] = { ["mapID"] = 1543, ["x"] = 0.338, ["y"] = 0.557 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questGiverID"] = 170375, ["questTurnInID"] = 170375, ["questType"] = "standard", ["sourceQuests"] = { 57121 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[57123] = { ["id"] = 57123, ["name"] = "Kyrian No More", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "Mawsworn kyrian... I have not seen one since that vision when we first met. I am not intimidated. They are enemies of Bastion , of the Archon, and it is our duty to defeat them.", ["objectivesText"] = "Kill 15 Mawsworn forces.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 170550 }, ["starts"] = { { ["x"] = 0.338, ["y"] = 0.557, ["mapID"] = 1543, ["npcID"] = 170375 } }, ["ends"] = { { ["x"] = 0.338, ["y"] = 0.557, ["mapID"] = 1543, ["npcID"] = 170375 } }, ["coords"] = { ["mapID"] = 1543, ["x"] = 0.338, ["y"] = 0.557 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questGiverID"] = 170375, ["questTurnInID"] = 170375, ["questType"] = "standard", ["sourceQuests"] = { 57121 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[57124] = { ["id"] = 57124, ["name"] = "Her Will, Inflicted", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1543, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["series"] = { 57125, 62555 }, ["description"] = "I feel myself drawn across the double bridges to the west... Lysonia must be there. Come, <name>. We must confront her before she can escape again. Who knows what she plans.", ["objectivesText"] = "Confront Lysonia in the Altar of Domination.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 170550, 174290, 177051, 178154, 179940 }, ["rewardChoices"] = { 178154, 177051, 179940, 174290 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.335, ["y"] = 0.564, ["mapID"] = 1543, ["npcID"] = 170375 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 169850, ["x"] = 0.253, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.253, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questGiverID"] = 170375, ["questType"] = "standard", ["sourceQuests"] = { 57122, 57123 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[57125] = { ["id"] = 57125, ["name"] = "Time to Reflect", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1543, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["series"] = { 57124, 62555 }, ["description"] = "I knew that Devos had powerful allies. I turned a blind eye. When Lysonia took her place... I was blinded by my loyalty. I have much to reflect on. We may not be allies, but I have one request. Please, escort me from this wretched place. I will leave you be... but do not leave me here in the Maw.", ["objectivesText"] = "Speak to Kleia to exit the Maw, then return to Polemarch Adrestes in Elysian Hold.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 170550, 184312 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 169850, ["x"] = 0.253, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.253, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1533, 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 57124 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57126] = { ["id"] = 57126, ["name"] = "...And Following Seas", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9042, ["mapID"] = 1161, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002, 57126, 57324, 58674, 58675 }, ["description"] = "My brother Derek died in the Second War, only to be raised against his will by the Banshee Queen. If not for Baine Bloodhoof's courageous act of defiance, Derek would have been turned into a weapon against my family. He's lived in torment since his awakening. I feared he would be lost to us, but he has received help from an old friend of mine who has also been recently raised-- Calia Menethil . She has guided him back from the brink of despair. I am on my way to pay them a visit. Care to join me?", ["objectivesText"] = "Visit Derek Proudmoore and Calia Menethil .", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 150633, ["x"] = 0.5735, ["y"] = 0.4475 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 156513, ["x"] = 0.6295, ["y"] = 0.5985 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.5735, ["y"] = 0.4475 }, ["mapCandidates"] = { ["npc"] = { 18, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["sourceQuests"] = { 57002 }, ["questLines"] = { { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942 },
[57130] = { ["id"] = 57130, ["name"] = "Traitors In Our Midst", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "There is a difference between loyalty and blind obedience. I am done following the Banshee's orders!", ["objectivesText"] = "Deal with this traitor.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.741, ["y"] = 0.461, ["mapID"] = 1534, ["npcID"] = 156124 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 11402 } }, ["questGiverID"] = 156124, ["questType"] = "standard", ["sourceQuests"] = { 56833 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534 },
[57131] = { ["id"] = 57131, ["name"] = "Let the Hunt Begin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "One step remains until we may begin the Penitent Hunt. You and the other hunters will first siphon a small amount of anima from the souls. It will come with ease. The soul's time in the Grove of Terror causes trace anima to release. This anima helps us venthyr in tracking the prey's fear. I also ask that you do us the honor of signaling the hunt. < The Fearstalker hands you an anima stake and a hollowed dredbat fang .> Use these to complete the task.", ["objectivesText"] = "Complete the hunting ritual at Wanecrypt Hill. Progress: The ceremony must continue.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59014 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57136] = { ["id"] = 57136, ["name"] = "The Penitent Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "You will descend upon these poor souls. Remember, you are helping them and Revendreth through the terror you bring. When a soul is filled with fear, their resistances to our methods falter. The Master has requested that you hunt the Accuser yourself. But we must prey upon some of the others first. I will be able to guide you through your first hunt.", ["objectivesText"] = "Speak to the Fearstalker in Wanecrypt Hill and participate in the Penitent Hunt. Progress: The souls must be hunted.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175715, 175770, 178873, 178994 }, ["rewardChoices"] = { 175715 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 168664, ["questType"] = "standard", ["sourceQuests"] = { 57131 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57146] = { ["id"] = 57146, ["name"] = "Corruption Tear", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 390, ["starts"] = { { ["x"] = 0.742, ["y"] = 0.4, ["mapID"] = 1530 } }, ["ends"] = { { ["x"] = 0.742, ["y"] = 0.4, ["mapID"] = 1530 } }, ["coords"] = { ["mapID"] = 1530, ["x"] = 0.742, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 156472 } } },
[57147] = { ["id"] = 57147, ["name"] = "Not My Warchief", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "There is little time. Sylvanas likely knows of my intentions and sent you to deal with me accordingly. I doubt she will be pleased with your decision. We must make our way to the wyverns and take to the skies.", ["objectivesText"] = "Escape with Eitrigg and meet up with Saurfang in Razor Hill.", ["rewardGold"] = 48350, ["rewardXP"] = 6815, ["rewardItems"] = { 25808, 25809, 25810, 25811, 52901, 52947, 98133 }, ["starts"] = { { ["x"] = 0.74, ["y"] = 0.46, ["mapID"] = 1534, ["npcID"] = 156124 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11402 } }, ["questGiverID"] = 156124, ["questType"] = "standard", ["sourceQuests"] = { 57152 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[57148] = { ["id"] = 57148, ["name"] = "Siegebreakers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "The fools who follow Saurfang have grown bold enough to launch a direct assault. We cannot allow these pests to swarm before our gates. Our operatives are collapsing the pass between Razor Hill and Orgrimmar as we speak. Saurfang's treasonous forces will be cut in half. Your task is to sneak into their ranks and sabotage their siege engines. Wear this disguise, but know that it will not hold up under close examination. Slay anyone who discovers you.", ["objectivesText"] = "Covertly place Suspicious Crates and slay guards.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 171365 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 11402 } }, ["questType"] = "standard", ["sourceQuests"] = { 57130 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534 },
[57149] = { ["id"] = 57149, ["name"] = "Propaganda Takedown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Recently, dissidents have been posting propaganda around the city and spreading all manner of lies. This is no time to entertain delusion. An army of traitors and sworn enemies assembles at our gates. These ingrates would see us become pin cushions for the Alliance's archers. <Nathanos rolls his eyes.> Tear down the rubbish. It can only lead to panic in the streets. And should you encounter any... resistance... you are hereby authorized to respond with force.", ["objectivesText"] = "Burn Dissident Propaganda in Orgrimmar.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 11402 } }, ["questType"] = "standard", ["sourceQuests"] = { 57130 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534 },
[57150] = { ["id"] = 57150, ["name"] = "Militia", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "The war has proven costly and our ranks have been steadily depleted. But the Horde is nothing if not strong. Each and every citizen of Orgrimmar is worth ten Alliance weaklings on the battlefield. Rally the citizens and form a militia! Remind them of their slain brothers and sisters!", ["objectivesText"] = "Rally the citizens of Orgrimmar.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 11402 } }, ["questType"] = "standard", ["sourceQuests"] = { 57130 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534 },
[57151] = { ["id"] = 57151, ["name"] = "A Line in the Sand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Now that we have put our house in order, it is time to purge the filth before our gates. How thoughtful of those traitors to gather themselves in one place, so that we may slay them all in one fell swoop. Let us end this pitiful rebellion.", ["objectivesText"] = "Speak with Nathanos.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156425, ["x"] = 0.186, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 11402 } }, ["questType"] = "standard", ["sourceQuests"] = { 57148, 57149, 57150 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534 },
[57152] = { ["id"] = 57152, ["name"] = "Most Loyal", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9664, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "The Dark Lady anticipated this as a possible outcome. She has prepared a contingency plan to deal with it accordingly. You are to rendezvous with her in the Ghostlands. Take this hearthstone. It is good for one more use. She will meet you near Windrunner Spire.", ["objectivesText"] = "Speak with Sylvanas Windrunner.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 172203 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 156425, ["x"] = 0.186, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156425, ["x"] = 0.186, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["sourceQuests"] = { 57151 }, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95 },
[57155] = { ["id"] = 57155, ["name"] = "Blinding the Eye", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10266, ["storyline"] = { 57155 }, ["description"] = "Ah yes, just the I wanted to see. I can still sense his touch lingering upon you. Our victory over the god of the deep will not be complete until we remove all traces of his infection. Through my research I have learned a less painful way of removing the infection. Speak with me, and let's put an end to this nightmare.", ["objectivesText"] = "Speak with Brother Pike to cleanse your \"gift\".", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10266 } }, ["questType"] = "standard" },
[57156] = { ["id"] = 57156, ["name"] = "Blinding the Eye", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10266, ["storyline"] = { 57156 }, ["description"] = "You finally arrived . Dat dark mojo on you has lingered for too long. N'Zoth be defeated and we need to cleanse all de traces of his infection from you. Dis won't hurt. Much. Tell me when you are ready to begin.", ["objectivesText"] = "Speak with Nailok to cleanse your \"gift\".", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10266 } }, ["questType"] = "standard" },
[57157] = { ["id"] = 57157, ["name"] = "Assault: The Black Empire", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 57157 }, ["description"] = "It is just as the visions fortold. Dark forces have come to claim the Forge of Origination. They must be stopped, or all of Azeroth will meet its end!", ["objectivesText"] = "Drive back the N'Zoth Assault in Uldum . Progress: The madness... it consumes!", ["rewardXP"] = 10225, ["rewardItems"] = { 173372 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 750 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Drive back N'Zoth's Forces", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[57158] = { ["id"] = 57158, ["name"] = "Electric Empowerment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["starts"] = { { ["x"] = 0.15, ["y"] = 0.23, ["mapID"] = 1530 } }, ["ends"] = { { ["x"] = 0.15, ["y"] = 0.23, ["mapID"] = 1530 } }, ["coords"] = { ["mapID"] = 1530, ["x"] = 0.15, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9105 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 156549 } } },
[57159] = { ["id"] = 57159, ["name"] = "A Reflection of Truth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "I sent the Fearstalker far from here with that trap--buying us some time. On the other side of this mirror lies the depths of Castle Nathria, the fortress of Denathrius himself. There, a meeting between Denathrius and one of his lackeys is about to take place. Join me through the mirror, <name>. You shall see the truth of this \"drought\" first hand.", ["objectivesText"] = "Follow the Accuser through the mirror and witness the truth of Revendreth .", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156554, ["x"] = 0.515, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156554, ["x"] = 0.515, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60506 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57161] = { ["id"] = 57161, ["name"] = "I Don't Get My Hands Dirty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "You heard Sire Denathrius. Today, I ascend to the Court of Harvesters. You are fortunate to have the honor of witnessing my rise to power. The traitors have barricaded the bridge ahead. Clear a path for me, so that I might cross it undisturbed. Nothing can stand against me now that I have a Harvester's medallion. But I will not waste my power on this rabble.", ["objectivesText"] = "Clear the bridge for Lord Chamberlain . Progress: Clear the way for Lord Chamberlain !", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175714 }, ["rewardChoices"] = { 175714 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156605, ["x"] = 0.58, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156842, ["x"] = 0.646, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57179 }, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57164] = { ["id"] = 57164, ["name"] = "Devour This", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Though the souls are our primary target, another challenge has arisen. The Banewood has seen an infestation of devourers: disgusting vermin who gorge themselves on the anima we need to survive. A fitting challenge for any true hunter, no? I should only thank the Master that they have remained in a few secluded pockets. I loathe to think that their numbers could multiply. Let us exterminate them before they pose a true threat.", ["objectivesText"] = "Eliminate the devourers in the Banewood. Progress: Are the devourers finished?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168664, ["x"] = 0.478, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 168664, ["questType"] = "standard", ["sourceQuests"] = { 57131 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57171] = { ["id"] = 57171, ["name"] = "Goldbough Guardian", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["starts"] = { { ["x"] = 0.204, ["y"] = 0.126, ["mapID"] = 1530 } }, ["ends"] = { { ["x"] = 0.204, ["y"] = 0.126, ["mapID"] = 1530 } }, ["coords"] = { ["mapID"] = 1530, ["x"] = 0.204, ["y"] = 0.126 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9105 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 156674 }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 156623 } } },
[57173] = { ["id"] = 57173, ["name"] = "The Accuser's Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Lord Chamberlain will cross the bridge when it pleases him. Before he arrives, you will seize the Accuser's sinstone. Wise venthyr like Lord Chamberlain hide their sinstone, so that it can never be used against them. The Accuser is too proud to hide her sinstone. Instead, she puts it on display for all to see. Boasting of the many, many sins she's overcome. Proud. Arrogant. Most importantly, foolish. Her sinstone lies on the altar before us, seemingly unguarded. Retrieve it.", ["objectivesText"] = "Investigate the Accuser's sinstone.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156842, ["x"] = 0.646, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156823, ["x"] = 0.645, ["y"] = 0.497 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57161 }, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57174] = { ["id"] = 57174, ["name"] = "The Stoneborn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57174, 57178, 57179, 58654 }, ["description"] = "The Stone Legion is not even here yet? This is an outrage. If we do not do something quickly, the rebels will overrun this filthy hamlet. Here, take the anima and go activate a few of the stoneborn along the periphery of Darkhaven. Take whatever is left over to the Quartermaster and tell her to do her job. I will try to commune with the Master and see if he can send reinforcements.", ["objectivesText"] = "Collect the Anima Cage and then awaken 6 Stoneborn Guardians . Progress: Darkhaven. Such a pitiful hamlet filled with unworthy supplicants.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 176139 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156374, ["x"] = 0.5935, ["y"] = 0.5645 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5935, ["y"] = 0.5645 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 56978 }, ["questLines"] = { { ["id"] = 994, ["name"] = "The Master", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 994, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57175] = { ["id"] = 57175, ["name"] = "Inquisitor Vilhelm's Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Inquisitor Vilhelm has taken exceptional precautions to protect his sinstone. Broken into several pieces and hidden from sight, he believed his sinstone would be safe from us. But his plan had the same weakness as most: he trusted weak-willed underlings. I \"interrogated\" several dredgers to learn where they helped the inquisitor hide the broken fragments of his sinstone. Find all the fragments and bring them to me.", ["objectivesText"] = "Collect the 3 Hidden Sinstone Fragments .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 171103, 174930, 174998 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163576, ["x"] = 0.674, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164166, ["x"] = 0.66, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59021 }, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57176] = { ["id"] = 57176, ["name"] = "Sinstone Delivery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Lord Chamberlain has held off the Accuser to buy us the time we needed to break the ward on her sinstone. But, thanks to your delays, our reinforcement of his position is overdue. I will collect the Accuser's sinstone and carry us to the battle.", ["objectivesText"] = "Fly with Echelon and deliver the Accuser's Sinstone to Lord Chamberlain .", ["rewardGold"] = 64350, ["rewardXP"] = 355, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164166, ["x"] = 0.66, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157069, ["x"] = 0.656, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59023 }, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
