[57178] = { ["id"] = 57178, ["name"] = "The Master Awaits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57174, 57178, 57179, 58654 }, ["description"] = "Maw Walker, I am General Kaal . Those stoneborn who remember their oaths to the Master are under my command. The path between here and Sire Denathrius is no longer secured by my forces. I am pulling my troops from this ward to support the Master's will elsewhere. Sire Denathrius has dispatched me to bring you directly to him. Myskia can carry you.", ["objectivesText"] = "Meet Sire Denathrius. Progress: Mind your manners when speaking to Sire Denathrius. He is a being older than your world.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155541, ["x"] = 0.5885, ["y"] = 0.5765 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156374, ["x"] = 0.5935, ["y"] = 0.5645 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5885, ["y"] = 0.5765 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58654 }, ["questLines"] = { { ["id"] = 994, ["name"] = "The Master", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 994, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57179] = { ["id"] = 57179, ["name"] = "The Authority of Revendreth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57174, 57178, 57179, 58654 }, ["description"] = "$p, a proud <race> <class>. I know your name and your deeds. I can taste your regrets and your shame. More importantly, I know what you might become. You can be the beacon for the Shadowlands to rally behind. The symbol my people need to set aside these petty squabbles and help fix the problems that afflict all reality. Before you stands the Court of Harvesters, my most loyal and trusted venthyr. Where once there were seven, only four remain. Introduce yourself to them, for where they go, my power follows", ["objectivesText"] = "Accept the Master's Boon. Progress: My eyes are everywhere.", ["rewardGold"] = 193050, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156644, ["x"] = 0.575, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156644, ["x"] = 0.575, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57178 }, ["questLines"] = { { ["id"] = 994, ["name"] = "The Master", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 994, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57180] = { ["id"] = 57180, ["name"] = "The Accuser's Secret", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Now that I possess the Accuser's sinstone, I can finally end her treasonous charade once and for all! Protect me while I study this sinstone, and you will be rewarded as first among my retainers. After I crush her with my incredible power, I will seize control of the Halls of Atonement and receive the Master's reward. This feat heralds my own ascension to the Court of Harvesters!", ["objectivesText"] = "Help Lord Chamberlain defeat the Accuser.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175732 }, ["rewardChoices"] = { 175732 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157069, ["x"] = 0.656, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157084, ["x"] = 0.662, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57176 }, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57182] = { ["id"] = 57182, ["name"] = "The Accuser's Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "You now stand in the presence of a Harvester, Maw Walker. < Lord Chamberlain breathes in deeply and smiles.> I will use the Accuser's medallion to solidify my foothold over the Halls of Atonement. Meanwhile, the Master has requested that you deliver both the Accuser and the medallion that he loaned to me. Myskia will be along shortly to retrieve you. Do not keep the Master waiting.", ["objectivesText"] = "Ride Myskia and deliver the Accuser to Sire Denathrius . Progress: I trust you have the medallion that I loaned to the Lord Chamberlain ?", ["rewardGold"] = 64350, ["rewardXP"] = 355, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175756 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157084, ["x"] = 0.662, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156381, ["x"] = 0.534, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57180 }, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57185] = { ["id"] = 57185, ["name"] = "Dutybound", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57185 }, ["description"] = "Welcome to the fight, . You're with us now. Take a moment and introduce yourself. I will meet you by Draven at the lodge.", ["objectivesText"] = "Introduce yourself to General Draven , Nadjia the Mistblade , and Rendle .", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[57189] = { ["id"] = 57189, ["name"] = "Breaking the Hopebreakers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "The Fearstalker has surely sent her hunters across the entirety of the Banewood in search of us, <name>. Draven informed me that some of her top hunters are scouring Dredhollow as we speak. We can use this to our advantage. Slaying them should get her attention. < The Accuser hands you a collection of bright red vials.> Throw these on her hunters. It should draw the attention of the devourers infesting this place.", ["objectivesText"] = "Use the Concentrated Anima Vial to defeat the hopebreakers in Dredhollow.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 175770, 177633, 177634, 177646, 177648, 177650, 177651, 177652, 178873, 178994 }, ["rewardChoices"] = { 177646, 177651, 177650, 177648, 177652, 177634, 177633 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168217, ["x"] = 0.432, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168468, ["x"] = 0.396, ["y"] = 0.812 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60313 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57190] = { ["id"] = 57190, ["name"] = "They Won't Know What Hit Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Luring the Fearstalker here will prove pointless unless we can tilt the odds. She will surely show up with a small army. Plant these anima containers. When the time comes, we will release their contents into the air, dousing her and her forces in a thick layer of anima. That should get the devourers infesting this place to flock to them like moths to a flame.", ["objectivesText"] = "Plant 8 Rigged Anima Containers.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168217, ["x"] = 0.432, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168468, ["x"] = 0.396, ["y"] = 0.812 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60313 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57198] = { ["id"] = 57198, ["name"] = "Sense of Obligation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9042, ["mapID"] = 862, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152, 57198, 57376, 58672, 58673 }, ["description"] = "Derek is free. I have to atone for much with him. There is a rumor of a meeting with Jaina and her brother. Head to Seabreeze Village in Stormsong Valley . I hope there you will be able to find out... well, let's just say I am trying to keep the bigger picture in focus. If you find out anything of interest, I would be most appreciative. For now, let's keep this between the two of us.", ["objectivesText"] = "Eavesdrop on Jaina Proudmoore's meeting.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 141961, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 141961, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["sourceQuests"] = { 57095, 57152 }, ["questLines"] = { { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[57205] = { ["id"] = 57205, ["name"] = "A Few Bumps Along the Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57205 }, ["description"] = "This territory is strategic to our defense, we can not allow these abominations to force our retreat! Seize control of two of the locations marked on your map. Defend them from enemy attack till the flag is planted and the location captured.", ["objectivesText"] = "Defend and capture two locations", ["rewardXP"] = 8165, ["rewardItems"] = { 6948, 168583, 171275, 172054, 180273, 180771, 181164, 182163 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Artillery defended", ["amount"] = 2, ["type"] = 0, ["objectID"] = 156797, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[57207] = { ["id"] = 57207, ["name"] = "Lysonia's Plan", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["description"] = "Lysonia has brought the Paragon to his knees! The Maw powers she wields are far too potent. We must stop her.", ["objectivesText"] = "Confront Lysonia. Progress: <The Paragon of Humility clutches his body in pain.>", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 170550 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156361, ["x"] = 0.653333, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156474, ["x"] = 0.69, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.653333, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57117, 57118 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57220] = { ["id"] = 57220, ["name"] = "Power Protocol Initiation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57221, 57222, 57290 }, ["description"] = "We've come a long way, <name>. Once the power from the auxiliary systems are brought online MOTHER will be able tae run diagnostics. All that's left is settin' the final pieces in place.", ["objectivesText"] = "Relay power from the Chamber of Heart, Engine of Nalak'sha and Forge of Origination auxiliary systems, then speak with MOTHER to power up the Forge of Origination. Progress: Quite the journey so far.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["ends"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["coords"] = { ["mapID"] = 1473, ["x"] = 0.501, ["y"] = 0.591 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questGiverID"] = 152206, ["questTurnInID"] = 152206, ["questType"] = "standard", ["sourceQuests"] = { 58737 }, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[57221] = { ["id"] = 57221, ["name"] = "Re-Origination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57220, 57222, 57290 }, ["description"] = "If the Ramkahen haven't reached out tae sound any alarms then the anomaly must be contained within the Halls of Origination. We best get back tae investigate, <name>.", ["objectivesText"] = "Meet Magni Bronzebeard outside the Halls of Origination in Uldum.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questGiverID"] = 152206, ["questType"] = "standard", ["sourceQuests"] = { 57220 }, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57222] = { ["id"] = 57222, ["name"] = "Investigating the Halls", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57220, 57221, 57290 }, ["description"] = "Whatever's happenin' has tae be comin' from deep within the inner chamber. If we can get tae the forge maybe we'll find some answers. Best check yer gear 'fore headin' in, <name>. Who knows what's waitin' fer us in there.", ["objectivesText"] = "Investigate the anomaly in the Halls of Origination.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 57221 }, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
