[57228] = { ["id"] = 57228, ["name"] = "The Assault on Dredhollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57228 }, ["description"] = "The time is upon us, Maw Walker. The Fearstalker's hunters are descending upon us. We have done all we can do to prepare for their assault. Here. I fashioned this out of the supplies you brought me. Use it to destroy the Fearstalker's forces . The fight begins.", ["objectivesText"] = "Defeat 12 of the Fearstalker's Forces .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171146 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[57240] = { ["id"] = 57240, ["name"] = "Where is Prince Renathal?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["series"] = { 57380 }, ["description"] = "This is not victory, $p. If Prince Renathal does not return, we've merely delayed defeat. The Prince was last seen during an assault on the Master's keep alongside Duke Theotar. We don't know the Prince's fate, but we've learned that Duke Theotar was banished to the Ember Ward. The Ember Ward is a land of madness and torture. Blighted by the Light, the Master sends his most hated enemies there to suffer unending agony. Enter the Ember Ward, find Theotar, and discover the Prince's fate.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 168217, ["x"] = 0.432, ["y"] = 0.738, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 157199, ["x"] = 0.39, ["y"] = 0.66, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.432, ["y"] = 0.738, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59256 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[57245] = { ["id"] = 57245, ["name"] = "Ani-Matter Animator", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57245 }, ["description"] = "This area is rich with the remains of fallen soldiers... some of which still carry a spark of potential. I've created what I call the \" Ani-Matter Orb ,\" with which you can reanimate the skeletal matter littered throughout the foundry. Let us see how many of the new animates would join our cause. As for those who don't... well, they should be quite accustomed to being slain by now.", ["objectivesText"] = "Recruit 15 animates. Progress: Do we have enough animates?", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 175827, 181804 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157076, ["x"] = 0.262, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157076, ["x"] = 0.262, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1176, ["name"] = "Ani-Matter Animator", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
