[57249] = { ["id"] = 57249, ["name"] = "A Timely Invitation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 440, ["storyline"] = { 57249 }, ["description"] = "The time has arrived to remember the past and celebrate our adventures across Azeroth and Beyond. To commemorate the occasion the Bronze Dragonflight is throwing a celebration and you are invited! Come to the Caverns of Time and present this ticket to gain entry to the party!", ["objectivesText"] = "Bring the Invitation from the Timewalkers to Chromie within the Caverns of Time.", ["rewardGold"] = 26210, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.536, ["y"] = 0.548, ["mapID"] = 75 } }, ["ends"] = { { ["x"] = 0.536, ["y"] = 0.548, ["mapID"] = 75 } }, ["coords"] = { ["mapID"] = 75, ["x"] = 0.536, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne", ["startItems"] = { 171177 } },
[57256] = { ["id"] = 57256, ["name"] = "Stormchosen Arena", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["starts"] = { { ["x"] = 0.17, ["y"] = 0.457, ["mapID"] = 1530 } }, ["ends"] = { { ["x"] = 0.17, ["y"] = 0.457, ["mapID"] = 1530 } }, ["coords"] = { ["mapID"] = 1530, ["x"] = 0.17, ["y"] = 0.457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9105 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 157100 } } },
[57261] = { ["id"] = 57261, ["name"] = "Walk the Path, Aspirant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["series"] = { 57584, 60735 }, ["description"] = "If you wish to stand before the Archon, there is a path you must walk. Thankfully, it is well worn and serviceable even in these dire times. Though you are not destined to become kyrian, our ways may be of interest to you. Learn well, learn fast, and perhaps the Archon will take notice and grant you this audience you seek. Aspirant Kleia will show you the way. Archon's eyes upon you.", ["objectivesText"] = "Travel with Kleia .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 124640 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166306, ["x"] = 0.422, ["y"] = 0.782 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60735 }, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57263] = { ["id"] = 57263, ["name"] = "The Cycle of Anima: Etherwyrms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "Forge is cold, yes? Need LOTS of anima to light. < Sika references her scroll.> Times before now, anima is everywhere, yes? Now it hides. Small bits, weird places. We know that etherwyrms -- flappy scale-things that are blue -- eat anima. They are not dead, so they are finding anima to eat still, yes? Maybe if we take what they have eaten, we can use it to light the forge. This will probably kill them. Sad, yes. But! We will not take too much. Just a little.", ["objectivesText"] = "Slay Etherwyrms to collect 25 Glowing Viscera . Progress: Did you find anima? Small pieces, even?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57711 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57264] = { ["id"] = 57264, ["name"] = "On the Edge of a Revelation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "Ah! Good. You answered the call. As you can see, there are many aspirants who require our aid. Myself and the other disciples are hard pressed to deal with all of them. Some are in greater need than others. Aspirants are most at risk when they are on the precipice of a revelation. It is a critical moment that we cannot allow to pass without intervention. You must push them, one way or another. Find the most vulnerable among your peers and do what you can to help them find the path forward.", ["objectivesText"] = "Inspire 11 Vulnerable Aspirants to action. Progress: My disciples will be grateful for your aid, <name>.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157673, ["x"] = 0.583, ["y"] = 0.7255 }, { ["mapID"] = 1533, ["npcID"] = 160637, ["x"] = 0.6005, ["y"] = 0.7355 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.7255 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57270 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57265] = { ["id"] = 57265, ["name"] = "The Cycle of Anima: Drought Conditions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "In days past, keeping a forge burning was a trivial task. The anima extractors could run constantly without ever running dry. Now, even turning an extractor on is a risk. Etherwyrms, without the anima streams to feed on, are attracted to any source of anima. They are a frequent nuisance. I am going to ask that you risk their attentions. Activate the extractor and guard it until it can accumulate what little anima remains. Bring me the product it collects. Let us hope it is enough.", ["objectivesText"] = "Collect a Condensed Anima Mote from the Anima Extractor . Progress: Is the extractor functional? How much were you able to acquire?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57711 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57266] = { ["id"] = 57266, ["name"] = "The First Cleansing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "This situation may feel familiar, <name>. When you found Pelagos, he was undergoing a similar rite. As you saw, it can end in violence. This will be the first time you are asked to draw out the burdens that held you to a mortal life. It may be a painful process. It is for many. For you, this is the path you must walk to attain your goals. To earn the right to stand among us, to be heard. So we may carry your message to the Archon herself. Center yourself. When you are prepared, we will begin.", ["objectivesText"] = "Undergo your first cleansing.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 173317, 173321, 173322, 173323, 173324, 177954 }, ["rewardChoices"] = { 173321, 173322, 173323, 173324 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159583, ["x"] = 0.577, ["y"] = 0.872 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.577, ["y"] = 0.872 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57291 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57267] = { ["id"] = 57267, ["name"] = "The Cycle of Anima: Flower Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "For forge to light, need more anima. Always more. Never too much, for forge! < Sika consults her scroll and nods vigorously as she reads.> Out in fields, there is a glowy flower. The round thing inside. Bulb? It glows. So, has anima. From the ground, we think. According to scrolls, it is called Adrima's Lily . We do not know who Adrima is. But the lily is good. Get flowers, too. Not just bulbs. Petals make stewards happy, too. Thank you!", ["objectivesText"] = "Collect 6 Adrima's Lily . Progress: Do you have flower bulb things?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 172518, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57711 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57269] = { ["id"] = 57269, ["name"] = "The Hand of Doubt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57446 }, ["description"] = "Quickly! We have no time to lose. Lysonia has weakened Eridia to the point that she may fall. Our Paragon will do what she can, but we must intervene. We will challenge Lysonia , and perhaps buy Eridia more time. This so-called Hand of Doubt will make no easy foe. Stand ready, <name>.", ["objectivesText"] = "Defeat Lysonia , Hand of Doubt.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171215, 176330, 176332, 176334, 176336, 176337, 176338, 176339, 176388, 176390 }, ["rewardChoices"] = { 176337, 176388, 176390, 176339, 176330, 176334, 176338, 176336, 176332 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157673, ["x"] = 0.583, ["y"] = 0.7255 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157687, ["x"] = 0.608, ["y"] = 0.7285 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.7255 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57446 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57270] = { ["id"] = 57270, ["name"] = "The Temple of Purity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57977 }, ["description"] = "Greetings. I am Kosmas, Disciple to the Temple of Purity. The temple is a place of cleansing. Its sole purpose is to free aspirants of the burdens they carry with them from life. It is a place of quiet reflection even for those who have shed their burdens. Of late, those who look to us for purification have grown numerous. My fellow disciples are stretched terribly thin. I have come to ask the aid of all able-minded aspirants. Your help is needed. Please report to the Hand of Purity at once.", ["objectivesText"] = "Meet the Hand of Purity at the Temple of Purity.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157673, ["x"] = 0.583, ["y"] = 0.7255 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.7255 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58174 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
