[57274] = { ["id"] = 57274, ["name"] = "Quartermaster's Bounty", ["level"] = 26, ["requiredLevel"] = 26, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 57274 }, ["objectivesText"] = "Progress: To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", ["rewardItems"] = { 171198 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143560, ["x"] = 0.563, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143555, ["x"] = 0.515, ["y"] = 0.582 }, { ["mapID"] = 1161, ["npcID"] = 143560, ["x"] = 0.563, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[57275] = { ["id"] = 57275, ["name"] = "Something in Your Mind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 57275, 57462, 57464 }, ["description"] = "<Looking into the crystal, the light around you is slowly drowned in inky smoke. An imposing presence crushes down on you, whispering unintelligibly in your ear. Looking for the source, you see nothing, but the sensation grows. Your head begins to swim as the darkness deepens and the noise becomes deafening. Summoning all your willpower to steel your resolve... The light has returned, the noise silenced, and you stand with a humble crystal in your hand. Perhaps Wrathion knows more about it...>", ["objectivesText"] = "Bring the Void Focus to Wrathion in the Chamber of Heart. Provided item:", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 169223, 170553, 171176, 171312, 171320 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1031, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1032, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (H)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["startItems"] = { 171320 } },
[57276] = { ["id"] = 57276, ["name"] = "Maintaining Focus", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57275, 57276, 57462 }, ["series"] = { 57462, 57464 }, ["description"] = "At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him. N'Zoth's influence is everywhere, <name>, and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.", ["objectivesText"] = "Acquire 20 Shred of Insanity . These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills. Progress: We are embarking upon a dangerous gambit, <name>. Caution is of the utmost importance.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 170553, 171176, 171312, 171320 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57275 }, ["questLines"] = { { ["id"] = 1032, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (H)", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[57278] = { ["id"] = 57278, ["name"] = "Bring Me Their Heads", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57278 }, ["description"] = "I swore to the grave of Vistara the Fallen that I would bring him the head of the one who betrayed him. Though that was eons ago, it is an oath I must fulfill. Whatever fate ultimately befell the traitor, it is likely that his head can still be found nearby. Slaughter everyone here. Surely one of them must be the traitor... or be in possession of his head.", ["objectivesText"] = "Collect 10 Traitor's Heads . Progress: Do you have the traitor's head ?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171204, 175827 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157168, ["x"] = 0.271333, ["y"] = 0.492167 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157186, ["x"] = 0.262, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.271333, ["y"] = 0.492167 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57245 } },
[57284] = { ["id"] = 57284, ["name"] = "Blade of Blades", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57284 }, ["description"] = "The finest sword in existence has been lost! Never in your pitiful adventures have you encountered such a blade, mortal. Foe Cleaver was forged to strike down the titans themselves! I have wielded it against countless adversaries. Emissaries of the Light, minions of the Void, meddlers from the Gardens of Life... all have fallen before me! Soon the very planes of reality will kneel to my greatness! Once I find my weapon, that is. I insist you help me reclaim it. I know it's here somewhere!", ["objectivesText"] = "Find Foe Cleaver amongst the forgotten weapons . Progress: Have you found Foe Cleaver ? Well? HAVE YOU?!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 21100, 21746, 27753, 27754, 27756, 31425, 31426, 31427, 31428, 62982, 62983, 62984, 106138, 106148, 106159, 106170, 157547, 171205, 171206, 220507, 220508, 242241, 242386, 244846, 244888 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157168, ["x"] = 0.271333, ["y"] = 0.492167 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157186, ["x"] = 0.262, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.271333, ["y"] = 0.492167 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57245 } },
[57288] = { ["id"] = 57288, ["name"] = "Assessing Your Strength", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "The trial to come will test you in ways you can likely only imagine. I can see both from your past and from your demeanor that you are no stranger to combat. I would like to know where your strengths lie so we may address any weaknesses we find before your trial. You will find three praetorian soldiers created for this purpose, each stronger than the last. Defeat them all and I will consider your strength sufficient to continue at this time.", ["objectivesText"] = "Defeat the 3 Praetorian Sparring Assistants. Progress: How fares the combat?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5335, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57908 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57290] = { ["id"] = 57290, ["name"] = "Beginning the Descent", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57220, 57221, 57222 }, ["description"] = "Protecting one's mind against the old gods requires an object of pure corruption. Unbeknownst to many, one such object exists--dormant beneath the molten pits of Blackwing Descent. Until recently, one of my agents stood watch over the area, keeping detailed records of suspicious activities. Unfortunately, this agent has gone silent. It is now clear we are not the only ones with this knowledge. If we are to find answers, there is one place to look. Our journey continues, <name>. Blackrock awaits.", ["objectivesText"] = "Retrieve the Corrupt Black Dragonscale from Blackwing Descent atop Blackrock Mountain in Burning Steppes. Progress: Have you recovered what we discussed?", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 37863, 63379, 142469, 169223, 171219, 172072 }, ["rewardChoices"] = { 169223 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57222 }, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[57291] = { ["id"] = 57291, ["name"] = "The Chamber of First Reflection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "Ah, Athanos. It remains undefeated, as intended. Still, you have exceeded any expectation I might have had. You are stronger than many that have come before you. You have come here for a purpose, and Kleia has illuminated a path that she believes you can walk. I agree. I have opened the way to the Crucible's final rite. Follow the path to the south and east. There you will find the entrance to the Chamber of First Reflection. Kleia will instruct you further. Go in service, <name>.", ["objectivesText"] = "Speak to Kleia in the Chamber of First Reflection.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159583, ["x"] = 0.577, ["y"] = 0.872 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57714 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57298] = { ["id"] = 57298, ["name"] = "How Things \"Really\" Happened...", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 440, ["storyline"] = { 57298 }, ["description"] = "You've come a long way over the years, <name>. From humble beginnings doing odd jobs to saving Azeroth's very existence, you've done so much to ensure the safety of our world. But why should we just stand around trying to remember things? Let's just go back in time and relive all of the exciting bits again! Don't worry, in all of the millions upon millions of timeways I'm sure I'll find one where you never die.", ["objectivesText"] = "Embark from the Caverns of Time with Chromie to defeat villains of the past. Progress: Hey, did we win yet? Or have we begun? I'm maybe not yet sure. Keeping the timelines straight gets a bit difficult.", ["rewardItems"] = { 172012 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 500 } }, ["starts"] = { { ["x"] = 0.535, ["y"] = 0.547, ["mapID"] = 75, ["npcID"] = 157113 } }, ["ends"] = { { ["x"] = 0.535, ["y"] = 0.547, ["mapID"] = 75, ["npcID"] = 157113 } }, ["coords"] = { ["mapID"] = 75, ["x"] = 0.535, ["y"] = 0.547 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questGiverID"] = 157113, ["questTurnInID"] = 157113, ["questType"] = "standard", ["sourceQuests"] = { 57249 }, ["db2QuestSortName"] = "Nightborne" },
[57299] = { ["id"] = 57299, ["name"] = "Mysterious Sarcophagus", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["starts"] = { { ["x"] = 0.5, ["y"] = 0.634, ["mapID"] = 1530 } }, ["ends"] = { { ["x"] = 0.5, ["y"] = 0.634, ["mapID"] = 1530 } }, ["coords"] = { ["mapID"] = 1530, ["x"] = 0.5, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9105 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 157298 } } },
[57300] = { ["id"] = 57300, ["name"] = "Soldier of Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 57300 }, ["description"] = "Long ago, the land of Alterac Valley was peaceful. However, when the Frostwolves moved in it became highly contested real estate between them and the Stormpikes. Battles used to rage for days. Well, actually the battle is still ongoing, the bronze dragons have figured out a way for you to revisit those early days.", ["objectivesText"] = "Earn 500 honor in Korrak's Revenge. Progress: Did you have fun exploring Alterac Valley as it used to be?", ["rewardItems"] = { 3575, 3860, 12359, 17411, 17422, 137642, 169298, 172022, 172023, 172121, 172135, 172136, 172137, 212289, 212292, 212295, 212298, 224556, 232877, 233014 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 400 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223882, ["x"] = 0.622, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223882, ["x"] = 0.622, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
[57301] = { ["id"] = 57301, ["name"] = "Callous Concoctions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57301, 58431, 59430, 59520 }, ["description"] = "I witnessed your success with the Pool of Potions and I think you could be of help. Within this larger pool, we create more dangerous mixtures! There are three different oozing ingredients we mix together in different combinations to create violent creatures. When enough ingredients have been added to the pool, the mixture takes shape and a creature will emerge! Bring any combination of these ingredients, Mephitic Goo, Viscous Oil, or Miscible Ooze to the Pool of Mixed Monstrosities .", ["objectivesText"] = "Deliver any combination of Mephitic Goo, Viscous Oil, or Miscible Ooze to the Pool of Mixed Monstrosities . Progress: Have you completed the mixture?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 182079 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157313, ["x"] = 0.585, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157313, ["x"] = 0.585, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58431 }, ["questLines"] = { { ["id"] = 1158, ["name"] = "Mixing Monstrosities", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57302] = { ["id"] = 57302, ["name"] = "Alterac Valley Graveyards", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57302 }, ["description"] = "The graveyards in Alterac Valley are prized territories. Both the Horde and the Alliance fight savagely for these sacred grounds. Are you, <name>, ready to join that fight? I want you to assault an enemy graveyard. Find a graveyard with a Horde banner in its midst, and pull it from the ground! Do that, and your task will be complete.... But if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.", ["objectivesText"] = "Assault a graveyard, then return to Sergeant Durgen Stormpike in Dun Baldar.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.436, ["y"] = 0.172, ["mapID"] = 1537, ["npcID"] = 159811 } }, ["ends"] = { { ["x"] = 0.436, ["y"] = 0.172, ["mapID"] = 1537, ["npcID"] = 159811 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.436, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 159811, ["questTurnInID"] = 159811, ["questType"] = "pvp" },
[57303] = { ["id"] = 57303, ["name"] = "The Quartermaster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57303 }, ["description"] = "<name>, our quartermaster charged me to direct new recruits to him. He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them. Follow the road. You'll find our quartermaster to the west.", ["objectivesText"] = "Speak with the Stormpike Quartermaster .", ["rewardGold"] = 929400, ["rewardXP"] = 175, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 13797 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 13797, ["questType"] = "pvp" },
[57304] = { ["id"] = 57304, ["name"] = "Capture a Mine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57304 }, ["description"] = "The mines in Alterac Valley hold more than just minerals. Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them! Capture a mine, then return to me. To capture a mine, enter one that we do not control and kill its leader. When you do that, the mine will be ours, and we'll send troops to protect it!", ["objectivesText"] = "Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", ["rewardGold"] = 638000, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.433, ["y"] = 0.17, ["mapID"] = 1537, ["npcID"] = 12096 } }, ["ends"] = { { ["x"] = 0.433, ["y"] = 0.17, ["mapID"] = 1537, ["npcID"] = 12096 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.433, ["y"] = 0.17 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 12096, ["questTurnInID"] = 12096, ["questType"] = "pvp" },
[57305] = { ["id"] = 57305, ["name"] = "Armor Scraps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57305 }, ["description"] = "Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops. If you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!", ["objectivesText"] = "Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar. Progress: Did you bring any armor scraps , <name>?", ["rewardXP"] = 1415, ["rewardItems"] = { 3575, 3860, 12359, 17411, 17422, 169298, 172022, 172023, 172121, 172135, 172136, 172137 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.436, ["y"] = 0.159, ["mapID"] = 1537, ["npcID"] = 13257 } }, ["ends"] = { { ["x"] = 0.436, ["y"] = 0.159, ["mapID"] = 1537, ["npcID"] = 13257 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.436, ["y"] = 0.159 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 13257, ["questTurnInID"] = 13257, ["questType"] = "pvp" },
[57306] = { ["id"] = 57306, ["name"] = "More Armor Scraps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57306 }, ["objectivesText"] = "Progress: <name>, we need more armor scraps to supply our troops!", ["rewardItems"] = { 17422 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.436, ["y"] = 0.159, ["mapID"] = 1537, ["npcID"] = 13257 } }, ["ends"] = { { ["x"] = 0.436, ["y"] = 0.159, ["mapID"] = 1537, ["npcID"] = 13257 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.436, ["y"] = 0.159 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 13257, ["questTurnInID"] = 13257, ["questType"] = "pvp" },
[57307] = { ["id"] = 57307, ["name"] = "Towers and Bunkers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57307 }, ["description"] = "Towers and bunkers are key defensive positions, and so we must hold as many as possible! I want you to attack a tower or a bunker in Alterac Valley. To do that, enter a tower with a Horde banner atop it. You will see another enemy banner inside. Pull out that banner, and a white Alliance banner will appear in its place. Well done! At that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!", ["objectivesText"] = "Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Dun Baldar.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.436, ["y"] = 0.172, ["mapID"] = 1537, ["npcID"] = 159811 } }, ["ends"] = { { ["x"] = 0.436, ["y"] = 0.172, ["mapID"] = 1537, ["npcID"] = 159811 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.436, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 159811, ["questTurnInID"] = 159811, ["questType"] = "pvp" },
[57308] = { ["id"] = 57308, ["name"] = "The Battle of Alterac", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57308 }, ["description"] = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore. We can't allow the Horde to stop our scholarly pursuits! Defeat the Frostwolf general, Drek'Thar. With him dead, the orcs will lose their edge. Drek'Thar is in Frostwolf Keep, in the south of Alterac Valley. Vanquish him, and then return to me.", ["objectivesText"] = "Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Dun Baldar.", ["rewardGold"] = 702000, ["rewardXP"] = 2125, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 25 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp" },
[57309] = { ["id"] = 57309, ["name"] = "Begin the Attack!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57309 }, ["objectivesText"] = "Progress: My troops are supplied and ready to assault. We just need orders from Noreg Stormpike and I'll send them into the fray!", ["rewardItems"] = { 17353 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.44, ["mapID"] = 1537, ["npcID"] = 13446 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.44, ["mapID"] = 1537, ["npcID"] = 13446 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.523, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 13446, ["questTurnInID"] = 13446, ["questType"] = "pvp" },
[57310] = { ["id"] = 57310, ["name"] = "Irondeep Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57310 }, ["description"] = "Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine. The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep. We need the supplies in Irondeep, <name>. Enter the mine and bring me a load of them.", ["objectivesText"] = "Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar. Progress: Do you have the supplies, <name>? We can never have enough!", ["rewardGold"] = 170800, ["rewardItems"] = { 17522 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.433, ["y"] = 0.17, ["mapID"] = 1537, ["npcID"] = 12096 } }, ["ends"] = { { ["x"] = 0.433, ["y"] = 0.17, ["mapID"] = 1537, ["npcID"] = 12096 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.433, ["y"] = 0.17 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 12096, ["questTurnInID"] = 12096, ["questType"] = "pvp" },
[57311] = { ["id"] = 57311, ["name"] = "Coldtooth Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57311 }, ["description"] = "The Coldtooth mine is a storage depot for the Horde. I can't stomach the food they give their troops, and the state of their arms and armor is atrocious! But... in times like these when supplies are so important, we can use what they have. Enter the Coldtooth mine and bring me back their supplies. That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors. Good luck, <name>. The mine is to the distant south, deep in Horde territory.", ["objectivesText"] = "Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar. Progress: Did you enter the Coldtooth mine in Horde territory, <name>? Did you raid their supplies?", ["rewardGold"] = 341600, ["rewardItems"] = { 17542 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.433, ["y"] = 0.17, ["mapID"] = 1537, ["npcID"] = 12096 } }, ["ends"] = { { ["x"] = 0.433, ["y"] = 0.17, ["mapID"] = 1537, ["npcID"] = 12096 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.433, ["y"] = 0.17 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 12096, ["questTurnInID"] = 12096, ["questType"] = "pvp" },
[57312] = { ["id"] = 57312, ["name"] = "The Graveyards of Alterac", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57312 }, ["description"] = "The battle lines of Alterac Valley are ever shifting. Territories swing back and forth as we meet our opponents in deadly combat. And graveyards, <name>, are where battles rage most fierce. I want you to attack an Alliance held graveyard! Find a graveyard with an Alliance banner in its midst and pull it from the ground. Do that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.", ["objectivesText"] = "Assault a graveyard, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.508, ["y"] = 0.823, ["mapID"] = 1537, ["npcID"] = 158579 } }, ["ends"] = { { ["x"] = 0.508, ["y"] = 0.823, ["mapID"] = 1537, ["npcID"] = 158579 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.508, ["y"] = 0.823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 158579, ["questTurnInID"] = 158579, ["questType"] = "pvp" },
[57313] = { ["id"] = 57313, ["name"] = "Speak with our Quartermaster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57313 }, ["description"] = "<name>, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley. Speak with him; he will tell you more. Follow the road west into the bunker, then take the west exit and you'll find our quartermaster.", ["objectivesText"] = "Speak with the Frostwolf Quartermaster .", ["rewardXP"] = 175, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.82, ["mapID"] = 1537, ["npcID"] = 13798 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.82, ["mapID"] = 1537, ["npcID"] = 13798 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.506, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 13798, ["questTurnInID"] = 13798, ["questType"] = "pvp" },
[57314] = { ["id"] = 57314, ["name"] = "Capture a Mine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57314 }, ["description"] = "As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines. Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued! Help our war effort, <name>! Capture one of the mines for the Horde! To capture a mine, enter one that we do not control and kill its leader. When that is done, the mine will be ours and we'll send troops to protect it!", ["objectivesText"] = "Capture a mine, then return to Corporal Teeka Bloodsnarl in Frostwolf Village. Progress: You haven't yet captured a mine, <name>! Find one that we do not control and defeat it's leader!", ["rewardGold"] = 683200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.468, ["y"] = 0.835, ["mapID"] = 1537, ["npcID"] = 12097 } }, ["ends"] = { { ["x"] = 0.468, ["y"] = 0.835, ["mapID"] = 1537, ["npcID"] = 12097 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.468, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 12097, ["questTurnInID"] = 12097, ["questType"] = "pvp" },
[57315] = { ["id"] = 57315, ["name"] = "Towers and Bunkers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57315 }, ["description"] = "Towers and bunkers are important positions, and we must capture and hold them all! So to that end, I want you to attack a bunker that is controlled by the enemy. To do that, enter one with an Alliance banner. You will see another banner inside. Pull out that banner, and a white Horde banner will appear in its place. Well done! At that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!", ["objectivesText"] = "Capture an enemy tower or bunker, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.508, ["y"] = 0.823, ["mapID"] = 1537, ["npcID"] = 158579 } }, ["ends"] = { { ["x"] = 0.508, ["y"] = 0.823, ["mapID"] = 1537, ["npcID"] = 158579 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.508, ["y"] = 0.823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 158579, ["questTurnInID"] = 158579, ["questType"] = "pvp" },
[57316] = { ["id"] = 57316, ["name"] = "The Ladder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "Within the Theater of Pain, <brother/sister>, legends rise like cream to the top. Listen to me, <brother/sister>. If you have the courage to step into that sacred arena, you're going to face the greatest threats in all of existence! The cards will be stacked against you, but only those who can work together will emerge as champions. Gather your team and meet this challenge head on! Enter the Theater of Pain and defeat the opponents within! Prove that you can rise to the top!", ["objectivesText"] = "Defeat 3 opponents within the Theater of Pain. Progress: Greetings, brother. Have you faced the madness of the arena?", ["rewardGold"] = 368550, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 176277, 176278, 176279, 176280, 176281, 176282, 176283, 176284, 176285, 176286, 176444, 177835, 177837, 177877, 177957, 181529, 181531, 181534, 181815, 182083 }, ["rewardChoices"] = { 176277, 181529, 176278, 176280, 181531, 176444, 176282, 176286, 176281, 176279, 181534, 176283, 176285, 176284 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161733, ["x"] = 0.504667, ["y"] = 0.515333 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161733, ["x"] = 0.504667, ["y"] = 0.515333 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.504667, ["y"] = 0.515333 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "group", ["sourceQuests"] = { 58900 }, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57317] = { ["id"] = 57317, ["name"] = "Enemy Booty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57317 }, ["description"] = "When you fight the enemy, gather the scraps of their armor and bring them to me. I'll use those scraps to make armor for our own troops!", ["objectivesText"] = "Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village. Progress: How goes the hunting, <name>. Do you have any armor scraps for me?", ["rewardXP"] = 1415, ["rewardItems"] = { 3575, 3860, 12359, 17411, 17422, 169298, 172022, 172023, 172121, 172135, 172136, 172137 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.499, ["y"] = 0.826, ["mapID"] = 1537, ["npcID"] = 13176 } }, ["ends"] = { { ["x"] = 0.499, ["y"] = 0.826, ["mapID"] = 1537, ["npcID"] = 13176 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.499, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 13176, ["questTurnInID"] = 13176, ["questType"] = "pvp" },
