[57319] = { ["id"] = 57319, ["name"] = "The Battle for Alterac", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57319 }, ["description"] = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out! To win the battle for Alterac, we must defeat their general, Vanndar Stormpike! You will find Vanndar in Dun Baldar, in the north of Alterac Valley. Destroy him, , and then return to me.", ["objectivesText"] = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike. Then, return to Voggah Deathgrip in Frostwolf Village.", ["rewardGold"] = 702000, ["rewardXP"] = 2125, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 25 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp" },
[57320] = { ["id"] = 57320, ["name"] = "Launch the Attack!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57320 }, ["objectivesText"] = "Progress: My warriors are eager to attack! All I need are the assault orders...", ["rewardItems"] = { 17442 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.45, ["y"] = 0.48, ["mapID"] = 1537, ["npcID"] = 13449 } }, ["ends"] = { { ["x"] = 0.45, ["y"] = 0.48, ["mapID"] = 1537, ["npcID"] = 13449 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.45, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 13449, ["questTurnInID"] = 13449, ["questType"] = "pvp" },
[57321] = { ["id"] = 57321, ["name"] = "Coldtooth Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57321 }, ["description"] = "The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it. And so, control of the mine often falls to the Alliance, or to underground denizens... But we still need our supplies, <name>! Go to the Coldtooth mine and bring me a load of them. And be wary of enemies as you go; the tides of battle shift quickly in that place...", ["objectivesText"] = "Bring 10 Coldtooth Supplies to the Horde Quartermaster in Frostwolf Keep. Progress: Have you been to the Coldtooth mine, <name>? Do you have the supplies I asked for?", ["rewardGold"] = 156400, ["rewardItems"] = { 3575, 3860, 12359, 17411, 17422, 17542, 169298, 172022, 172023, 172121, 172135, 172136, 172137 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.468, ["y"] = 0.835, ["mapID"] = 1537, ["npcID"] = 12097 } }, ["ends"] = { { ["x"] = 0.468, ["y"] = 0.835, ["mapID"] = 1537, ["npcID"] = 12097 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.468, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 12097, ["questTurnInID"] = 12097, ["questType"] = "pvp" },
[57322] = { ["id"] = 57322, ["name"] = "Irondeep Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57322 }, ["description"] = "The Stormpike dwarves are using the Irondeep mine as a storage depot. I want you to raid that mine and bring me its supplies. This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment! Be wary, <name>. The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.", ["objectivesText"] = "Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep. Progress: Did you enter the Irondeep mine, <name>? Did you raid its supplies?", ["rewardGold"] = 341600, ["rewardItems"] = { 17522 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.468, ["y"] = 0.835, ["mapID"] = 1537, ["npcID"] = 12097 } }, ["ends"] = { { ["x"] = 0.468, ["y"] = 0.835, ["mapID"] = 1537, ["npcID"] = 12097 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.468, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 12097, ["questTurnInID"] = 12097, ["questType"] = "pvp" },
