[57324] = { ["id"] = 57324, ["name"] = "Sail With the Tide", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9042, ["mapID"] = 1161, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002, 57126, 57324, 58674, 58675 }, ["description"] = "Hello, $p. I have received word from Calia asking that we meet with her once again. She has so much to offer those who feel lost, those seeking a better way. Once she is free of doubt, she will know what must be done. Will you join me?", ["objectivesText"] = "Meet with Calia Menethil and Derek Proudmoore.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 150633, ["x"] = 0.5735, ["y"] = 0.4475 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 156513, ["x"] = 0.6295, ["y"] = 0.5985 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.5735, ["y"] = 0.4475 }, ["mapCandidates"] = { ["npc"] = { 18, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942 },
[57326] = { ["id"] = 57326, ["name"] = "Prototypes for Profit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57326 }, ["description"] = "< Gazlowe pulls you in close and whispers.> Lookit here, <name>. I gotta keep my nose clean here in front of the prince. But I trust you know what's gotta be done outside of town, yeah? Outside of town... where all the tech is... Tech that Alliance grubs are tryin' to get their clumsy mitts on... which we could use for the Horde... to build big weapons... and scary robots... and other lucrative products...? I don't gotta spell this out for you, right?", ["objectivesText"] = "Collect 150 Prototype Implants in Mechagon , while in War Mode. Progress: This place is teemin' with tech. Betcha can find prototypes anywhere.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 168258, 169610, 171248 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150567, ["x"] = 0.74, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150567, ["x"] = 0.74, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[57327] = { ["id"] = 57327, ["name"] = "Prototypes for Inspiration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57327 }, ["description"] = "<Overspark pulls you in close and whispers.> As the leader of this momentous expedition, I must stay with Prince Erazmin to ensure he's not swindled by this Horde hooligan. But I cannot stop my research, or the Horde will gain the advantage! Underlings like yourself must collect the technology samples required to fuel my legendary brainstorms. Bring me prototypes from the island, and I will turn them into groundbreaking new innovations for the Alliance!", ["objectivesText"] = "Collect 150 Prototype Implants in Mechagon , while in War Mode. Progress: I don't care where you get the prototypes from. Take them from Gazlowe's thugs if you have to.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 169114, 169610, 171248 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150282, ["x"] = 0.739, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150282, ["x"] = 0.739, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.739, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
