[57373] = { ["id"] = 57373, ["name"] = "Descending Into Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57362, 57374, 58634 }, ["description"] = "As unfortunate as the spreading corruption may seem, I believe it provides us the opportunity to prepare for what lies ahead. Locate one of these incursions and see what happens when you peer beyond the dark veil.", ["objectivesText"] = "Seek out a Vision of N'Zoth amidst the corruption in Vale of Eternal Blossoms or Uldum to discover what the future holds for Azeroth.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 49623, 169223, 171312, 173431, 173439, 173447, 173455, 173812, 173815, 173818, 173821, 174491 }, ["rewardChoices"] = { 173431, 173439, 173447, 173455, 173812, 173815, 173818, 173821 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57362 }, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 23, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[57374] = { ["id"] = 57374, ["name"] = "Into the Darkest Depths", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57362, 57373, 58634 }, ["description"] = "With our connection secured, it is time for us to breach the veil and discover what lies beyond. What you find may provide us the key to unlocking our success.", ["objectivesText"] = "Enter a Horrific Vision to discover what dark manifestations await in a world ruled by N'Zoth. Progress: Your expertise in these matters are invaluable.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173363 }, ["rewardCurrencies"] = { { ["id"] = 1719, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questTurnInID"] = 155496, ["questType"] = "standard", ["sourceQuests"] = { 58634 }, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 25, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
