[57376] = { ["id"] = 57376, ["name"] = "The Hidden Need", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8044, ["mapID"] = 862, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152, 57198, 57376, 58672, 58673 }, ["description"] = "Because of Sylvanas, some members of the Horde are skeptical of the Forsaken. We must regain their trust. We cannot do that without accepting ourselves. So many feel lost, alone... abandoned. I have arranged a meeting. It could be a big step... or all go horribly wrong. Either way, you should bear witness. Meet me in Tirisfal Glades , at the Calston Estate.", ["objectivesText"] = "Meet Lilian Voss in Tirisfal Glades .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 141961, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 157230, ["x"] = 0.435, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 18, 862 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["sourceQuests"] = { 57198 }, ["questLines"] = { { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiUiMapID"] = 18 },
[57377] = { ["id"] = 57377, ["name"] = "A Hand Offered", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8044, ["storyline"] = { 57377 }, ["description"] = "Here begins the calia intro See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(57377)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(57377))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8044 } }, ["questType"] = "standard" },
[57378] = { ["id"] = 57378, ["name"] = "Remnants of a Shattered World", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57378 }, ["description"] = "The knowledge gained from these visions affords us a unique opportunity to further protect one's mind from corruption. To continue our research, we must investigate the deeper mysteries of these experiences. Seek out those of power within these visions. Should you come across anything of interest do not hesitate to share your findings. In the meantime, MOTHER and I shall continue our research here in the chamber. We await your return, <name>.", ["objectivesText"] = "Recover a copy of \" The Curse of Stone \" from a Horrific Vision for Wrathion in the Chamber of Heart. Progress: Find anything of interest?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 120257, 142406, 171335, 174777 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57374 } },
[57379] = { ["id"] = 57379, ["name"] = "Infested Jade Statue", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 390, ["starts"] = { { ["x"] = 0.764, ["y"] = 0.516, ["mapID"] = 1530 } }, ["ends"] = { { ["x"] = 0.764, ["y"] = 0.516, ["mapID"] = 1530 } }, ["coords"] = { ["mapID"] = 1530, ["x"] = 0.764, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 157532 }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 157545 } } },
[57380] = { ["id"] = 57380, ["name"] = "Sign Your Own Death Warrant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["series"] = { 57240 }, ["description"] = "Ember Ward only for bad buds! Stonehead squints at you and shakes head.> You not look like other bad buds! Bad buds come with bad paper!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 157199, ["x"] = 0.39, ["y"] = 0.66, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 157199, ["x"] = 0.39, ["y"] = 0.66, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.39, ["y"] = 0.66, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57240 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[57381] = { ["id"] = 57381, ["name"] = "The Greatest Duelist", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["description"] = "A mortal in Revendreth . Well, well, well... you are primed to be at the head of high adventure. The name you may call me is Nadjia the Mistblade , and, if I might be so humble as to say, I am the finest duelist that has ever wielded a sword. This trap you found me in was a lesson learned in getting paid in advance. Release me and my blade is yours to command for as long as I find you interesting. Do we have an accord?", ["objectivesText"] = "Release Nadjia the Mistblade . Progress: That consecrated iron really leaves one feeling stiff afterward.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174102, 175730 }, ["rewardChoices"] = { 175730 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157550, ["x"] = 0.656, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157550, ["x"] = 0.656, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 157550, ["questType"] = "standard", ["sourceQuests"] = { 57007 }, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57386] = { ["id"] = 57386, ["name"] = "If You Want Peace...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["series"] = { 61107 }, ["description"] = "Maldraxxus is a land which revels in strife and conflict. But they should also be bound by honor. If their honor has been tossed aside, then they may move their forces beyond just Bastion. Take care, danger lies beyond that gate. It is a realm of heroes as well as a realm of villains.", ["objectivesText"] = "Enter Maldraxxus .", ["rewardGold"] = 28900, ["rewardXP"] = 175, ["rewardItems"] = { 172020, 178496 }, ["starts"] = { { ["x"] = 0.611, ["y"] = 0.369, ["mapID"] = 1670, ["npcID"] = 171338 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 10565 } }, ["questGiverID"] = 171338, ["questType"] = "standard", ["sourceQuests"] = { 61107 }, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57390] = { ["id"] = 57390, ["name"] = "To Die By the Sword", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "What's this? You fly no colors! Where is the pride in your house, gladiator? Bah, this drought has left us with slim pickings indeed, if this is the best Maldraxxus can muster! I remember the old days. The strongest souls arriving, then being divided among the five houses... No matter. The tournament beckons. Enter the arena! Fight for glory! By the look of you, it's likely you won't last long. Try to make a name for yourself in the time you have left.", ["objectivesText"] = "Defeat 30 contenders in the Theater of Pain. Progress: What are you waiting for? Put on a show!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172020, 178496 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57386 }, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57391] = { ["id"] = 57391, ["name"] = "Reconstructing \"The Curse of Stone\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57391 }, ["description"] = "I came across several references to this book in my research of Ny'alotha. Penned by a neophyte cultist, it documents the \"lies of the Titans\" and the \"injustices\" they inflicted upon the denizens of Azeroth. Mad ravings, intended to erode the reader's acceptance of reality. Still, by studying this work, we can gain a better understanding of the Old God's power, and thus tailor the cloak to offer better protection against it. Bring as many pages from this tome as you can find.", ["objectivesText"] = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart. Progress: What have you been able to find?", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 171335, 171353 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57378 } },
[57392] = { ["id"] = 57392, ["name"] = "Reconstructing \"The Curse of Stone\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57392 }, ["description"] = "Thus far, the contents of this book are unsettling to say the least. Nevertheless, I have been able to glean valuable information on the nature of N'Zoth's power, and have made alterations to your cloak accordingly. There remains much to learn, however. Continue your search for additional pages as you delve into the visions.", ["objectivesText"] = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart. Progress: Urgent matters require a great deal of attention. Unless it is of the utmost importance, I must see to my work.", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 169223, 171335, 171353, 173363 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57391 } },
[57393] = { ["id"] = 57393, ["name"] = "Stepping Through the Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57393 }, ["description"] = "By now you've noticed the protection of your cloak wavering the deeper you delve into these visions. To further bolster your resistance to N'Zoth's influence, we will need to gain an even deeper understanding of his nefarious power. Seek out knowledge from manifestations deeper within the visions, and we shall have our answers soon enough.", ["objectivesText"] = "Recover a copy of \" Fear and Flesh \" from the depths of a Horrific Vision for Wrathion in the Chamber of Heart. Progress: Dark and deep are the shadows.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 171354, 174782 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57402 } },
[57394] = { ["id"] = 57394, ["name"] = "Reconstructing \"Fear and Flesh\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57394 }, ["description"] = "Another tome written by one lost to N'Zoth's madness. I dread to think of what vile words await us within it. But if we are to strengthen your cloak, then we must know more of that which it was meant to resist. See if you can find the remaining pages so that we can complete this tome and make use of the knowledge it holds.", ["objectivesText"] = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: The missing pages must reside deeper within these visions. As dark and difficult these times may seem, we mustn't forget the possibility remains of a time of great success and discovery.", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 171354, 173363, 174783 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57393 } },
[57395] = { ["id"] = 57395, ["name"] = "Reconstructing \"Fear and Flesh\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57395 }, ["description"] = "Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing. Naturally, it omits any mention of what occurs when their corruption is allowed to run unfettered. Gather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.", ["objectivesText"] = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Anything to share?", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 171354, 174783 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57394 } },
[57396] = { ["id"] = 57396, ["name"] = "Reconstructing \"Fear and Flesh\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57396 }, ["description"] = "Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing. Naturally, it omits any mention of what occurs when their corruption is allowed to run unfettered. Gather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.", ["objectivesText"] = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Nearly halfway there, <name>. Have you found anything new?", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 171354, 174783 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57395 } },
[57397] = { ["id"] = 57397, ["name"] = "Reconstructing \"Fear and Flesh\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57397 }, ["description"] = "Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair. But you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy. Continue to collect the pages of this book. We have nearly finished piecing it back together.", ["objectivesText"] = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: The darkness lingers. Never hurried. Never sleeping. Patiently waiting...", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 169223, 171354, 173363, 174783 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57403 } },
[57398] = { ["id"] = 57398, ["name"] = "Walking in the Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57398 }, ["description"] = "The end nears. The darkest corners of these visions await. Our work has ensured you are well equipped to seek out the most horrific manifestations these visions have to offer. The final answers lie just beyond. Our preparations for Ny'alotha are nearly complete.", ["objectivesText"] = "Recover a copy of \" The Final Truth \" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: I await your return.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 171355, 174784 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57397 } },
[57399] = { ["id"] = 57399, ["name"] = "Reconstructing \"The Final Truth\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57399 }, ["description"] = "I know of this book. It is a sacred tome to those who worship the Old Gods, containing the deepest secrets and most incomprehensible mysteries of the Void. Only the most devout cultists are allowed to gaze upon its pages. Even incomplete, holding it makes my skin crawl. I must take care not to read too much of it in a single sitting. That being said, we must find its missing pages in order to continue our research. Retrieve them from the darkest corners of N'Zoth's visions.", ["objectivesText"] = "Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: I often find my own thoughts wandering, weary of what lies ahead. How are you faring, <name>? Have you any news?", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 171355, 174785 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57398 } },
[57400] = { ["id"] = 57400, ["name"] = "Reconstructing \"The Final Truth\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57400 }, ["description"] = "I dare not repeat aloud the horrors that are recorded in these pages. The words themselves seem to shift and morph as I read them, as if the book itself is attempting to induce a descent into madness. This is taxing work, but it is necessary if we are to fully prepare you for the dangers of Ny'alotha. For as disturbing as its descriptions might be, setting foot within it will prove more challenging by an order of magnitude. Keep looking for pages from the book, <name>. But... leave the reading to me.", ["objectivesText"] = "Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Your success has brought us this far, <name>. Perhaps you have something to share?", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 171355, 174785 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57399 } },
[57401] = { ["id"] = 57401, ["name"] = "Reconstructing \"The Final Truth\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["description"] = "Long have I studied the secrets of the Old Gods. I have traversed the whole of Azeroth in search of esoteric texts, lost archives, and forbidden knowledge, all in the name of preparing for the horror to come. No amount of research could have prepared me for the depths of the insanity I would find within this book. A madness so absolute that only the Shath'yar language can convey it. Find me the final pages of this accursed tome, . I wish to learn what I need from it and be done with it forever.", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 171355 }, ["starts"] = { { ["npcID"] = 155496, ["x"] = 0.852, ["y"] = 0.322, ["mapID"] = 84 }, { ["npcID"] = 155496, ["x"] = 0.466, ["y"] = 0.646, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 155496, ["x"] = 0.852, ["y"] = 0.322, ["mapID"] = 84 }, { ["npcID"] = 155496, ["x"] = 0.466, ["y"] = 0.646, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.852, ["y"] = 0.322, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57400 } },
[57402] = { ["id"] = 57402, ["name"] = "Reconstructing \"The Curse of Stone\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57402 }, ["description"] = "N'Zoth is nothing if not subtle and insidious. I can see how an impressionable mind could be turned against the Titans by reading these words. Thankfully, we are not so susceptible to such manipulation, are we? The book is nearly complete. Continue retrieving its pages from within the visions.", ["objectivesText"] = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart. Progress: I believe we are on the precipice of a something grand.", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 171335, 171353 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57392 } },
[57403] = { ["id"] = 57403, ["name"] = "Reconstructing \"Fear and Flesh\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57403 }, ["description"] = "Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair. But you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy. Continue to collect the pages of this book. We have nearly finished piecing it back together.", ["objectivesText"] = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Making progress?", ["rewardGold"] = 232300, ["rewardXP"] = 5110, ["rewardItems"] = { 171354, 174783 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57396 } },
[57405] = { ["id"] = 57405, ["name"] = "Chasing Madness", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["description"] = "An adversary with no ferry cannot be merry unless it is wary!", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["starts"] = { { ["npcID"] = 157588, ["x"] = 0.37, ["y"] = 0.632, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 157639, ["x"] = 0.38, ["y"] = 0.606, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.37, ["y"] = 0.632, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57380 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[57425] = { ["id"] = 57425, ["name"] = "Land of Opportunity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "<The grandmaster's voice rings out over the roaring crowd.> This is it! The final event of the tournament! These two Maldraxxi gladiators have cut down challenger after challenger. Now the only thing left... Is for one to slay the other!", ["objectivesText"] = "Defeat High Champion Meskal .", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 172020, 175466, 175467, 175468, 175469, 178496 }, ["rewardChoices"] = { 175468, 175466, 175469, 175467 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162069, ["x"] = 0.484, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60021 }, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57426] = { ["id"] = 57426, ["name"] = "My Terrible Morning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["description"] = "You simply won't believe what happened to me! I was out for my daily stroll when Marquis Pummeler and his band of ruffians assailed me! Amongst the many unfortunate and ungentlemanly behaviors they displayed was destroying my parasol. A tragedy of the highest order! Without it, I'm afraid I'm left quite vulnerable to the oppressive Light that curses this land. The Marquis controls a coveted shaded hideout nearby. Will you avenge my parasol and teach this ruffian some manners?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardChoices"] = { 175425, 175423, 175426, 175424 }, ["starts"] = { { ["npcID"] = 157639, ["x"] = 0.38, ["y"] = 0.606, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 157639, ["x"] = 0.38, ["y"] = 0.606, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.38, ["y"] = 0.606, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 157639, ["questType"] = "standard", ["sourceQuests"] = { 57405 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[57427] = { ["id"] = 57427, ["name"] = "Unbearable Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["description"] = "Have you encountered an ash ghoul yet? Wretches crawling on the ground. Jump on everything. Terrible table manners. That is the unfortunate fate awaiting all venthyr exposed to the Light for too long. The overwhelming pain it causes us breaks our willpower, our mind, and finally our body. With the right skills, it is possible to reverse the Light's desecration if it is treated quickly. But the ash ghouls in this Light-burned crater are beyond redemption. There is only one mercy left.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 157639, ["x"] = 0.38, ["y"] = 0.606, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 157639, ["x"] = 0.38, ["y"] = 0.606, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.38, ["y"] = 0.606, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 157639, ["questType"] = "standard", ["sourceQuests"] = { 57405 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[57428] = { ["id"] = 57428, ["name"] = "Theotar's Mission", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["description"] = "Oh the Accuser sent you? How keen! I do, in fact, know the fate of Prince Renathal... at least part of it. When our assault on the Master's keep failed, we were both captured. I was banished to the Ember Ward, but the Prince was dragged off to Sinfall. I'm cultivating an escape from this Light-blighted land to follow after him, but the Light here... it makes it hard to think. My parasol once protected me, but the ruffians destroyed it. Help me rebuild it, and we'll find the Prince together.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 157639, ["x"] = 0.38, ["y"] = 0.606, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 157639, ["x"] = 0.38, ["y"] = 0.606, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.38, ["y"] = 0.606, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 157639, ["questType"] = "standard", ["sourceQuests"] = { 57405 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[57429] = { ["id"] = 57429, ["name"] = "Pyre of the Amalgamated One", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["starts"] = { { ["x"] = 0.3713, ["y"] = 0.6702, ["mapID"] = 1527, ["npcID"] = 14161 } }, ["ends"] = { { ["x"] = 0.3713, ["y"] = 0.6702, ["mapID"] = 1527, ["npcID"] = 14161 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10833 } }, ["questTurnInID"] = 14161, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 163227, ["text"] = "Pyre of the Amalgamated One examined" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 157641 } } },
[57442] = { ["id"] = 57442, ["name"] = "Lost in the Desiccation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["description"] = "Theotar incapable of forming coherent sentences. Instead of telling you how to get to his hideout, he mumbles incoherently while pointing in random directions.> Lost... Syb... Tubbins ... Late for tea... Theotar 's hideout a different way.>", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 157650 } }, ["ends"] = { { ["npcID"] = 157801, ["x"] = 0.31, ["y"] = 0.576, ["mapID"] = 1525 } }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questGiverID"] = 157650, ["questType"] = "standard", ["sourceQuests"] = { 57426, 57427, 57428 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[57443] = { ["id"] = 57443, ["name"] = "Dirty Job: Demolition Detail", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57443 }, ["objectivesText"] = "Grab a dredger Rubble Wreckage demolished", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Grab a dredger", ["amount"] = 1, ["type"] = 3, ["objectID"] = 157632, ["orderIndex"] = 0 }, { ["text"] = "Rubble Wreckage demolished", ["amount"] = 3, ["type"] = 0, ["objectID"] = 157649, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[57444] = { ["id"] = 57444, ["name"] = "An Inspired Moral Inventory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57444 }, ["description"] = "<name>! You are well! I am glad of it. Many of the ascended who once served this place have betrayed us. To turn so wholly against all that the kyrian stand for is... unimaginable. <The acolyte places a heavy spear in your hands.> This is a tool that has seen little use before today. Its sole purpose is to inspire a moment of reflection in those it touches. It will show them the error of their ways. If they remain unrepentant, then there is no hope for them. They must die.", ["objectivesText"] = "Slay 3 Forsworn ascended . Progress: They betrayed us.", ["rewardGold"] = 289575, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160647, ["x"] = 0.576667, ["y"] = 0.746667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160647, ["x"] = 0.576667, ["y"] = 0.746667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576667, ["y"] = 0.746667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57717 }, ["questLines"] = { { ["id"] = 1186, ["name"] = "An Inspired Moral Inventory", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57446] = { ["id"] = 57446, ["name"] = "The Enemy You Know", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57269 }, ["description"] = "My heart is filled with dread. If it truly is Lysonia who leads them now... No. What is important is that we restore the great vespers. So long as their mighty voices are corrupted, all who hear them will suffer as this temple does. It is only a matter of time before all of Bastion succumbs. They will no doubt try to stop you. I will hold their leader's attention as long as I can. If I do not survive... my disciple will see you safely from this place. Go in service.", ["objectivesText"] = "Confront Lysonia and cleanse the great Vespers.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171215, 204454, 204459, 204620, 204624, 204625, 204626, 204627, 204628, 204629, 204630 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157673, ["x"] = 0.583, ["y"] = 0.7255 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57037, 57719, 59147, 60292 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57447] = { ["id"] = 57447, ["name"] = "Purity's Prerogative", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "Do you feel it, <name>? That cold hand that grips your throat? That chill settled in the pit of your stomach? That is the touch of the Maw, as certain as the Archon's will. I do not know how Lysonia came to possess this power, but we must act quickly. I will inform the Archon of what transpired here. You will act where my Hand could not. I will explain as we fly. Speak to me when you are prepared to leave the temple.", ["objectivesText"] = "Fly with Vesiphone to Purity's Reflection.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157687, ["x"] = 0.608, ["y"] = 0.7285 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156238, ["x"] = 0.538, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.7285 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57269 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57448] = { ["id"] = 57448, ["name"] = "New Allies Among Us", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Even in times of peace, the Horde is not without its problems. Although they can be overwhelming at times, our struggles should never stop us from remembering what it means to be a part of the Horde. We don't turn people away when times get tough; we band together and endure. For a moment I forgot this. Burdened by the troubles facing our new allies, I hastily dismissed the vulpera. My only hope is that they still see as much value in the Horde as I see in them.", ["objectivesText"] = "Witness Baine welcome the vulpera into the Horde.", ["rewardGold"] = 1024800, ["rewardXP"] = 8200, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 145424, ["x"] = 0.485, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 157693, ["x"] = 0.4848, ["y"] = 0.7172 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 53908 }, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[57454] = { ["id"] = 57454, ["name"] = "Silence in the Stalks", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["series"] = { 63073 }, ["description"] = "Hmm. Well that's not... great. But no cause for alarm, yet! It has been a long time since our ring withdrew from here, and we probably need to go to its source to get it to return! Unfortunately, I haven't heard from the Chief Mushroomancer, Cortinarius , since the crisis began. Please, find him and help us rejoin the rings! Head west of Dreamsong Fenn to the Stalks. You can't miss them... just follow the mushrooms!", ["objectivesText"] = "Speak to Cortinarius outside the Stalks.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.532, ["y"] = 0.332, ["mapID"] = 1702, ["npcID"] = 174609 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.307333, ["y"] = 0.353333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questGiverID"] = 174609, ["questType"] = "standard", ["sourceQuests"] = { 63073 }, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57455] = { ["id"] = 57455, ["name"] = "Mushroom For Improvement", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["description"] = "The mushrooms are under attack! I need your help, or we risk losing it all! Some fae wearing strange masks came in and demanded to gain access to the rings. When I told them they were closed due to the drought, they attacked me! I'm too weak to fight back now, and I'm cut off from the center ring. These fae have destroyed so much, but there is something we can do. Sprinkle some of these spores on their corpses so we can regrow the rings. Even when slain, our enemies can still serve Ardenweald .", ["objectivesText"] = "Use the Pouch of Spores to plant mushrooms on 15 masked fae in the Stalks. Progress: They'd be feeding the mushrooms anyway, so you might as well accelerate the process.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171989 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.307333, ["y"] = 0.353333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57454 }, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57457] = { ["id"] = 57457, ["name"] = "Shaking 'Shrooms", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57457 }, ["description"] = "The mushrooms in there need your help, ! Some of the larger mushrooms become laden with spores. It is one of my duties to help disperse them and grow the grove, but it is too dangerous for me in there. If you're going to go in, do you mind giving any particularly full mushrooms a good shake for me? That should get most of the spores loose until we can secure the grove.", ["objectivesText"] = "Shake 8 Swollen Mushroom Stalks.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[57458] = { ["id"] = 57458, ["name"] = "Ring Repairs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["description"] = "The damage wrought here is severe, but it can be reversed. My master is weakened by all this destruction, but mushrooms are difficult to completely eradicate. By restoring power to the rings throughout the grove, we can strengthen them once again. Take this beacon. Use it near a damaged mushroom in a ring, and watch how quickly nature can heal its wounds.", ["objectivesText"] = "Use the Fungal Beacon to repair 6 Damaged Mushrooms .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172084 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.307333, ["y"] = 0.353333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57454 }, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57459] = { ["id"] = 57459, ["name"] = "Fighting For Fungus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["description"] = "Behold, Marasmius ! This is his home, his heart. Every mushroom in Ardenweald , maybe even all of the Shadowlands, stems from here. And the masked fae want to take him for their own purposes. As chief mushroomancer, I cannot abide this. Our foes may look mindless, but they are clever. They will have tracked my position by now. I shall make my final stand here, and hope that Marasmius is strong enough to lend his aid. Will you stand with me, <class>?", ["objectivesText"] = "Help Cortinarius defend Marasmius .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 157710, ["x"] = 0.307333, ["y"] = 0.353333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.307333, ["y"] = 0.353333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 157710, ["questType"] = "standard", ["sourceQuests"] = { 57455, 57458 }, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57460] = { ["id"] = 57460, ["name"] = "Tubbins's Tea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["description"] = "Theotar teach Tubbins special tea that make Light go away! Tubbins good tea maker! Watch Tubbins make Theotar feel good! Then Tubbins feel good!", ["rewardGold"] = 193050, ["rewardXP"] = 1060, ["starts"] = { { ["npcID"] = 157801, ["x"] = 0.31, ["y"] = 0.576, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 157801, ["x"] = 0.31, ["y"] = 0.576, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.31, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57442 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[57461] = { ["id"] = 57461, ["name"] = "An Uneventful Stroll", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["description"] = "I hope I wasn't too unpleasant while under the Light's influence. I do try to restrain myself, but the pain it causes is... maddening. Anyway, that tea picked me right up! When I last saw Prince Renathal, the Master was dragging him off to that big tower looming over the Ember Ward. Myself and a few others have been working to gain access to that tower from below, but there are... obstacles. When you're ready to depart, I will lead you to our headquarters of sorts, the Sanctuary of the Mad.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardChoices"] = { 179988, 179991, 179990, 179989 }, ["starts"] = { { ["npcID"] = 158542, ["x"] = 0.312, ["y"] = 0.574, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 158694, ["x"] = 0.32, ["y"] = 0.476, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.312, ["y"] = 0.574, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57460 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[57462] = { ["id"] = 57462, ["name"] = "Dream Catcher", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57275, 57462, 57464 }, ["series"] = { 57276, 57464 }, ["description"] = "It appears that the focus remains stable, and its containment field remains intact. I daresay we can empower it even further. Hunt down and defeat formidable enemies to acquire additional remnants of N'Zoth's influence. This time, we will infuse the focus with even greater amounts of the Old God's power. I am confident that the containment field will continue to hold.", ["objectivesText"] = "Acquire 200 Shred of Insanity . These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills. Progress: Fortune favors the bold, <name>. And few acts are as bold as wielding the power of an Old God.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 169223, 170553, 171176, 171312, 171320 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57276, 57464 }, ["questLines"] = { { ["id"] = 1031, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1032, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (H)", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[57463] = { ["id"] = 57463, ["name"] = "My Way or the Hyphae", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["description"] = "<An old, booming voice fills your mind.> Hmph. More are coming. I would rather not lose more of myself, and I don't want you to think I'm not appreciative of the work you and Cort here have done. How about you take a ride on the rings and give those oafs a good thrashing? We'll teach them not to mess with Marasmius and his fae rings!", ["objectivesText"] = "Ride the fae rings with Marasmius and defeat 30 invaders.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.295, ["y"] = 0.346, ["mapID"] = 1565, ["npcID"] = 166982 } }, ["ends"] = { { ["x"] = 0.295, ["y"] = 0.346, ["mapID"] = 1565, ["npcID"] = 166982 } }, ["coords"] = { ["mapID"] = 1565, ["x"] = 0.295, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questGiverID"] = 166982, ["questTurnInID"] = 166982, ["questType"] = "standard", ["sourceQuests"] = { 57459 }, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57464] = { ["id"] = 57464, ["name"] = "Maintaining Focus", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57275, 57462, 57464 }, ["series"] = { 57276, 57462 }, ["description"] = "At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him. N'Zoth's influence is everywhere, <name>, and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.", ["objectivesText"] = "Acquire 20 Shred of Insanity . These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills. Progress: We are embarking on a dangerous gambit, <name>. Caution is of the utmost importance.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 171176 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57275 }, ["questLines"] = { { ["id"] = 1031, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[57465] = { ["id"] = 57465, ["name"] = "Dirty Job: Wood Work", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57465 }, ["objectivesText"] = "Grab a dredger Infested Horror Sap destroyed", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Grab a dredger", ["amount"] = 1, ["type"] = 3, ["objectID"] = 172929, ["orderIndex"] = 0 }, { ["text"] = "Infested Horror Sap destroyed", ["amount"] = 3, ["type"] = 0, ["objectID"] = 157831, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[57470] = { ["id"] = 57470, ["name"] = "An Abominable Discovery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "$p. Come with me. I could explain, but it's easier to understand if you see it for yourself.", ["objectivesText"] = "Follow Draka to Gharmal's Tower.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173308, ["x"] = 0.31, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60067 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57471] = { ["id"] = 57471, ["name"] = "It's a Dirty Job", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57471, 57474, 57477, 57481 }, ["series"] = { 60509 }, ["description"] = "This muck pool is all out of order. The anima shortage has taken its toll here for sure. You see, the pools require filth and fiber to grow dredgers effectively. The problem is every time I try to treat the pool, the dang devourers are on my back! Now the untreated muck is starting to coagulate into these elementals! Can you go and toss some of the filthy rubble into the pool to restore it?", ["objectivesText"] = "Throw Filthy Rubble into the muck pool.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171966 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60509 }, ["questLines"] = { { ["id"] = 1141, ["name"] = "Dirty Jobs", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57473] = { ["id"] = 57473, ["name"] = "Prized Possession", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 57475, 57636 }, ["description"] = "This chest is different. It's larger than the others... but more importantly, it's locked. <Mograine bashes the lock apart.> Now, let's see what's inside.", ["objectivesText"] = "Open the ornate chest. Progress: How did they acquire that?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 182658 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.292, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57530 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57474] = { ["id"] = 57474, ["name"] = "Dredger Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57471, 57474, 57477, 57481 }, ["description"] = "You fixed up the muck pool so we can make some dredgers, but them devourers are gonna keep causin' trouble. We're gonna need a Gem of Binding so we can dredge up a biggun to protect the pool. I'll show you how to dredge up some disposable dredgers to work with for now. Get 'em digging in the rubble to find us a Gem of Binding , and then we'll reshape 'em all into a biggun to kick them devourers outta here!", ["objectivesText"] = "Dredge a dredger and bring it to the pile of rubble . Wait for it to dig through the pile and collect the Gem of Binding . Progress: You got the gem?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171966 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57471 }, ["questLines"] = { { ["id"] = 1141, ["name"] = "Dirty Jobs", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57475] = { ["id"] = 57475, ["name"] = "The Mantle Returned", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 57473, 57636 }, ["description"] = "The Mantle of the Primus... I can hardly believe it. That Gharmal possessed it. That they did not use it against us. That we reclaimed it. This could prove vital toward our efforts to restore Maldraxxus . We must return it to Baroness Draka at the Seat of the Primus immediately.", ["objectivesText"] = "Return to Draka at the Seat of the Primus.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.292, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 173194, ["questType"] = "standard", ["sourceQuests"] = { 57473 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[57477] = { ["id"] = 57477, ["name"] = "We're Gonna Need a Bigger Dredger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57471, 57474, 57477, 57481 }, ["description"] = "Thanks for getting the stone, <name>. While you were out I went ahead and dredged up a few more folks. Now we just need to re-shape these dredgers into a biggun.", ["objectivesText"] = "Witness the ritual. Progress: What do you want?", ["rewardGold"] = 64350, ["rewardXP"] = 355, ["rewardItems"] = { 171966 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158001, ["x"] = 0.728, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57474 }, ["questLines"] = { { ["id"] = 1141, ["name"] = "Dirty Jobs", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57481] = { ["id"] = 57481, ["name"] = "Running a Muck", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57471, 57474, 57477, 57481 }, ["description"] = "Bootus ready to smash devourer skulls. Hop on.", ["objectivesText"] = "Board Bootus and quell the devourer incursion. Progress: Enders smashed?", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 171966, 177653, 177654, 177655, 177656, 180993 }, ["rewardChoices"] = { 177656, 177655, 177654, 177653 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158001, ["x"] = 0.728, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57477 }, ["questLines"] = { { ["id"] = 1141, ["name"] = "Dirty Jobs", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57486] = { ["id"] = 57486, ["name"] = "Waning Energy", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["series"] = { 57487, 58214 }, ["description"] = "Mekkatorque's pod is powering down. We are no longer able to hear him speak. His pulse has slowed, in spite of the best efforts of Kul Tiran healers. I have an idea, but I am going to need your help. Meet me at Proudmoore Keep. We must go soon.", ["objectivesText"] = "Meet Kelsey Steelspark at Proudmoore Keep.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 160101, ["x"] = 0.73, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 157997, ["x"] = 0.37, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["sourceQuests"] = { 58214 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161 },
[57487] = { ["id"] = 57487, ["name"] = "Someone Who Can Help", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1161, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["series"] = { 57486, 58214 }, ["description"] = "I believe there is a way to help Mekkatorque, but some may not be a hundred percent on board... The mechagnomes have advanced techniques in biomechanical repair and improvements. If there is even a chance they can help him, we have to try! There are some mechagnomes sending supplies out to the island from a dock in Hook Point. No one will notice one more piece of cargo. We need to reroute one of their homing copters . Will you please help me get Mekkatorque's Pod to Mechagon?", ["objectivesText"] = "Help Kelsey move Mekkatorque's Escape Pod to Mechagon. Progress: How can I help?", ["rewardGold"] = 170800, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 157997, ["x"] = 0.37, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 149816, ["x"] = 0.72, ["y"] = 0.3495 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 1161, 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 57486 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[57488] = { ["id"] = 57488, ["name"] = "The Current Schematic", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "I think I can modify one of our existing devices to give us access to Gelbin Mekkatorque without disturbing his life preserving functions. There are some items I will need you to procure. From the nearby vector of the Heaps, you will find scrapbots and scraphounds. These would be a fine source of spare parts for my construction project. The Outflow is home to some particularly slimy friends. From them, you will find excellent ingredients for the heat resistant lubricant we need.", ["objectivesText"] = "Collect 4 Heat Tolerant Ooze and 6 Acquisitioned Machine Parts . Progress: Were all assets found?", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 172521, 172522 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150555, ["x"] = 0.73, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150555, ["x"] = 0.73, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 57487 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[57490] = { ["id"] = 57490, ["name"] = "Voyage to Safety", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "One of our defenders saw the troggs take out the homing copter carrying Mekkatorque's pod. Since we started bringing goods in from Tiragarde, they have been a real thorn in our side. Piston, a very promising young inventor, has a vehicle able to handle this task. Meet his crew down in Bondo's yard. Please hurry and retrieve the pod! I am not sure what will happen to Gelbin, if they break it open. Ahem, we would not be upset if you did a little beach clean-up while you were there...", ["objectivesText"] = "Defeat the scavenging troggs and retrieve Mekkatorque's Escape Pod . Progress: Did everyone make it back in one piece?", ["rewardGold"] = 683200, ["rewardXP"] = 6830, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 158145, ["x"] = 0.733333, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150555, ["x"] = 0.73, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.733333, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 57488 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[57491] = { ["id"] = 57491, ["name"] = "Better... Stronger... Less Dead", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "King Mechagon may have been crazy, but his minions did have exemplary robotic creation capabilities. There are a few residual creations wandering Mechagon. Refusing to accept King Mechagon's dethroning. The logical conclusion to defeat is withdrawal, if one remains operational. Some do not excel at logic. They currently bear the latest in technical advancement. I believe retrieving specific pieces from these units would greatly benefit our recovery endeavor.", ["objectivesText"] = "Collect the Neural Accelerator , Omni Electromagnetic Amplifier , and Flux Energized Servos from the erratic units. Progress: Did you acquire the parts we need?", ["rewardGold"] = 455280, ["rewardXP"] = 6830, ["rewardItems"] = { 172511, 173026, 173028 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 160232, ["x"] = 0.7325, ["y"] = 0.3275 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 160232, ["x"] = 0.7325, ["y"] = 0.3275 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.3275 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 57490 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[57492] = { ["id"] = 57492, ["name"] = "Him?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "Speak to some of the gnomes in Mechagon, enhanced or otherwise. Of my people, ask what they hope for in a leader of our kind. Of our new friends, ask what they appreciate most about their current leader. From what I have learned thus far, the High Tinker has always led his people by necessity, he never sought or desired the crown. I believe the gnomes should be united once again. I seek a solution that will be most amenable to all. Will you gather the information I need?", ["objectivesText"] = "Gather data from gnomes and mechagnomes in Mechagon. Progress: Have your communications been productive?", ["rewardGold"] = 170800, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 158145, ["x"] = 0.733333, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 158145, ["x"] = 0.733333, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.733333, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 57491 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[57493] = { ["id"] = 57493, ["name"] = "Mental Attunement", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "We now have a baseline of who Mekkatorque is, looks like there could be some room for improvement. Your assistance is needed to get him stabilized and synchronized before removing him from his pod. Please position yourself by the Synchroscope . I will make adjustments, you will need to fire the machine when I call.", ["objectivesText"] = "Activate the Synchroscope when Christy tells you to fire. Progress: Did you successfully push the button?", ["rewardGold"] = 170800, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 160232, ["x"] = 0.7325, ["y"] = 0.3275 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 160232, ["x"] = 0.7325, ["y"] = 0.3275 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.3275 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 57492 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[57494] = { ["id"] = 57494, ["name"] = "A Strong Heart", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "We saw a flare near Junkwatt Depot. The retrieval team has made it out with the power source. We are now forever safe from King Mechagon's Annihilo-tron, its heart will serve a new purpose. This is great news! However, the flare means they have company. Your help will be needed to extricate the team and retrieve the Spark Reactor . Please move with haste, we are so close to completion.", ["objectivesText"] = "Retrieve the Spark Reactor and complete Mekkatorque's procedure. Progress: Are you ready?", ["rewardGold"] = 567400, ["rewardXP"] = 6830, ["rewardItems"] = { 173302 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 160232, ["x"] = 0.7325, ["y"] = 0.3275 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 158145, ["x"] = 0.733333, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.3275 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 57493 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[57495] = { ["id"] = 57495, ["name"] = "The Future of Mechagon", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "Now that Mechagon City has been cleared of its remaining dangers, it may once again be a place of peace and prosperity for gnomes and mechagnomes alike. It is time for me to speak with Prince Erazmin regarding the future of our peoples. It is my sincere hope that we will forge an alliance that will last for generations to come! When you are ready, please join us at the High Tinkertory for a special address.", ["objectivesText"] = "Travel to the High Tinkertory in Mechagon City. Progress: When you are ready, please join us at the High Tinkertory for a special address.", ["rewardGold"] = 34100, ["rewardXP"] = 685, ["starts"] = { { ["x"] = 0.581, ["y"] = 0.411, ["mapID"] = 1573, ["npcID"] = 162806 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 159587, ["x"] = 0.7325, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questGiverID"] = 162806, ["questType"] = "standard", ["sourceQuests"] = { 57496 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2268, ["db2PoiUiMapID"] = 1573 },
[57496] = { ["id"] = 57496, ["name"] = "Ascension", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "After everything the mechagnomes have done for us today, it is our duty to return the favor. Let us clear out the rogue creations that remain in Mechagon. With their home returned, Prince Erazmin and his people will have a brilliant path forward. With this team, we will make short work of the remaining King Mechagon loyalists. Let me know when you are ready to roll out!", ["objectivesText"] = "Clear the remaining Mechagon defenders.", ["rewardGold"] = 625600, ["rewardXP"] = 6830, ["rewardItems"] = { 1804, 1805, 1806, 1807, 35900, 35901, 35902, 35903, 124557, 170468, 181743, 184374, 184811, 184812 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 159587, ["x"] = 0.7325, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 159587, ["x"] = 0.7325, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questTurnInID"] = 159587, ["questType"] = "standard", ["sourceQuests"] = { 57494 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2268, ["db2PoiUiMapID"] = 1573 },
[57497] = { ["id"] = 57497, ["name"] = "Propagate the News", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1161, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "We wanted to save a life and we have accomplished so much more! We really couldn't have done it without you, <name>. I am so excited about the future of all gnomekind. Head back to Stormwind and share the good news!", ["objectivesText"] = "Update Aysa Cloudsinger in Stormwind.", ["rewardGold"] = 1024800, ["rewardXP"] = 8200, ["rewardItems"] = { 174067 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 157997, ["x"] = 0.37, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 126332, ["x"] = 0.5235, ["y"] = 0.1355 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 57495 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[57506] = { ["id"] = 57506, ["name"] = "Light Lost", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57506 }, ["description"] = "Some of our aspirants foolishly believed they could enter the Maw and make a difference in that dark abyss. Sadly, they are mistaken. To enter the Maw is to invite eternal damnation. But not for you. Please investigate their fate. If you can find them, their souls might once again be free. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(57506)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(57506))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Find Kyrian Aspirants within the Maw and return with their souls to Elysian Hold.", ["rewardGold"] = 631800, ["rewardXP"] = 14705, ["rewardItems"] = { 263198 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[57510] = { ["id"] = 57510, ["name"] = "Darklord Taraxis", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57510 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 158025 } } },
[57511] = { ["id"] = 57511, ["name"] = "Arms for the Poor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "This trench is strewn with the remnants of countless attacks upon the Seat of the Primus by forces which threatened the Shadowlands. Each time, Maldraxxus claimed victory. Now scavengers pick at scraps in hopes of buying their way into one of the three remaining houses. In these desperate times, we must gain every advantage possible over our rivals. If we arm these scavengers and offer them a second chance at glory, we can bolster the ranks of the Chosen.", ["objectivesText"] = "Arm 8 Displaced Scavengers with weaponry scattered around the Iron Trench. Progress: There should be plenty of weapons found on this old battlefield.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172020, 178496 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162069, ["x"] = 0.484, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162069, ["x"] = 0.484, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 162069, ["questType"] = "standard", ["sourceQuests"] = { 57425 }, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57512] = { ["id"] = 57512, ["name"] = "Walk Among Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "This trench echoes with necromantic energies unleashed in the countless battles waged here. That power has coalesced into chaotic entities we call deathwalkers. In simpler times, we would have sent troops out to subdue them to serve the House of the Chosen. But with war brewing, there is no time for that. Eliminate this potential threat, before our enemies turn them against us.", ["objectivesText"] = "Kill 8 Unbound Deathwalkers .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172020, 178496 }, ["starts"] = { { ["x"] = 0.483, ["y"] = 0.571, ["mapID"] = 1536, ["npcID"] = 162069 } }, ["ends"] = { { ["x"] = 0.483, ["y"] = 0.571, ["mapID"] = 1536, ["npcID"] = 162069 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.483, ["y"] = 0.571 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questGiverID"] = 162069, ["questTurnInID"] = 162069, ["questType"] = "standard", ["sourceQuests"] = { 57425 }, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57513] = { ["id"] = 57513, ["name"] = "Enemy of My Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57513 }, ["description"] = "I have no doubt you have questions. Know that we share enemies in this land. For now, we must move. I will get you to a safer location and then we can speak.", ["objectivesText"] = "Escape from the Theater of Pain.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 38134, 38135, 38176, 38177, 38178, 38732, 38759, 39030, 39058, 39096, 44987, 45724, 46114, 52879, 52884, 52887, 52902, 52931, 52948, 60260, 65290, 65309, 65328, 65341, 119139, 131828, 131840, 158666, 159123, 159147, 159148, 159149, 159150, 160083, 160084, 160085, 160086, 160093, 160094, 160095, 160096, 182077, 198611, 204454, 204459, 204620, 204624, 204625, 204626, 204627, 204628, 204629, 204630, 249699, 253178 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[57514] = { ["id"] = 57514, ["name"] = "The First Act of War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["series"] = { 57515 }, ["description"] = "Look around you, $p. This army is all that remains to defy the treachery of the other two houses. I must regroup with the margrave and discuss strategy. War will soon be upon us. I would ask that you prepare for the coming battle alongside the rest of our forces. We cannot afford for a single soldier to falter. Seek out Baron Vyraz . He has earned countless victories for Maldraxxus . I fear his blades must soon be turned upon our former allies.", ["objectivesText"] = "Report to Baron Vyraz . Progress: What are you waiting for?", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.660667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57515 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57515] = { ["id"] = 57515, ["name"] = "The House of the Chosen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["series"] = { 57514 }, ["description"] = "<Draka gestures to the sky.> Look there, mortal. That is the necropolis of Margrave Krexus, who leads the House of the Chosen. It is my honor to serve as his baroness. Let us ride to our fortress. There we can gather our strength and make ready for the battle to come.", ["objectivesText"] = "Head to the House of the Chosen with Draka. Progress: Yes?", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 172020, 178496 }, ["starts"] = { { ["x"] = 0.45, ["y"] = 0.616, ["mapID"] = 1536, ["npcID"] = 167535 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.660667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questGiverID"] = 167535, ["questType"] = "standard", ["sourceQuests"] = { 60179, 60181 }, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57516] = { ["id"] = 57516, ["name"] = "Through the Fire and Flames", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "Margrave Krexus was pleased to hear of your service to our house. He senses great potential within you. Potential that must be tested. A stone stands at the center of our citadel, surrounded by magma. Reaching the stone is a challenge of endurance and fortitude. This trial is usually attempted only by our most renowned soldiers, but Margrave Krexus commands you to attempt the rite at once. Go on, then. Prove your worth.", ["objectivesText"] = "Reach the Standing Stone. Progress: What happened?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 59529, 59530, 131310, 172061, 174499, 175470, 175471, 175472, 175473, 178662, 178676 }, ["rewardChoices"] = { 175471, 175473, 175472, 175470 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.660667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60451 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57522] = { ["id"] = 57522, ["name"] = "Call of the Void", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["starts"] = { { ["x"] = 0.3439, ["y"] = 0.2928, ["mapID"] = 1527, ["npcID"] = 14161 } }, ["ends"] = { { ["x"] = 0.3439, ["y"] = 0.2928, ["mapID"] = 1527, ["npcID"] = 14161 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10833 } }, ["questTurnInID"] = 14161, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 158049 } } },
[57524] = { ["id"] = 57524, ["name"] = "Accessing the Archives", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["description"] = "The information you've gathered has allowed us to better understand these manifestations. I believe MOTHER is waiting to share some of her findings with you.", ["objectivesText"] = "Speak with MOTHER to activate the Titanic Research Archive, then examine the archives. Progress: Do you require assistance?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 171212 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 10000 } }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questTurnInID"] = 155496, ["questType"] = "standard", ["sourceQuests"] = { 57374 }, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[57529] = { ["id"] = 57529, ["name"] = "Garden in Turmoil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57529 }, ["description"] = "Please excuse me for not standing. I would rather not disturb these creatures. If you have a desire to help the creatures of Bastion , Zosime needs aid to regain control of our garden. You will find her just down this path. Go in service.", ["objectivesText"] = "Speak with Zosime downhill in the Garden of Respite.", ["rewardGold"] = 23635, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158005, ["x"] = 0.522, ["y"] = 0.614 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.614 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60735 }, ["nextQuests"] = { 57538, 57545 } },
[57530] = { ["id"] = 57530, ["name"] = "Gharmal's Tower", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "Gharmal collected anything they believed to be an item of power. We'll need to search the tower. There is almost certainly something here of value to us.", ["objectivesText"] = "Search Gharmal's Tower.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173194, ["x"] = 0.292, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.292, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57470 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57531] = { ["id"] = 57531, ["name"] = "An Unfortunate Situation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["series"] = { 60051, 63056 }, ["description"] = "Laurent , mirror maker to the Master. Pleasure to meet you. Excuse my disheveled appearance. It appears I've found myself in a most unfortunate situation. I was attempting to travel on royal business when my mirror sent me to this wasteland instead. Not a moment after I arrived, a band of exiles ripped the clothes right from my back, making it impossible for me to traverse this unforgiving terrain. Assist me and I will endeavor to create a mirror which will allow us to escape this wretched place.", ["objectivesText"] = "Defeat Costel and recover Laurent's belongings . Progress: Have you recovered my belongings?", ["rewardGold"] = 382590, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172220, 175503, 175504, 175505, 175506 }, ["rewardChoices"] = { 175504, 175506, 175505, 175503 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158038, ["x"] = 0.264, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158038, ["x"] = 0.264, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60051 }, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57532] = { ["id"] = 57532, ["name"] = "Foraging for Fragments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "Forgive me. I don't mean to appear ungrateful, but my mirror fragments are missing. I shouldn't be surprised, really. They're quite powerful and I'm sure the miscreants out here would be happy to get their hands on them. Nonetheless, I will not let this deter me. The Master sends his stone servants to smash any mirrors erected in this ward, so we should have no trouble finding fragments nearby.", ["objectivesText"] = "Follow Laurent and collect Mirror Fragments . Progress: Simone shouldn't be here!", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172086, 172087, 172220 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158038, ["x"] = 0.264, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57531 }, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57533] = { ["id"] = 57533, ["name"] = "Light Punishment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "The reasons we were banished here differ, but our goal once we arrive is always the same--to avoid becoming ash. The Shrouded control the areas shaded from Light. Those that trespass within their stronghold are made to suffer. Our flesh blisters and burns, yet we do not die. Instead, our minds descend into madness from the pain. I do not claim to know the crimes of those trapped within the Light, but I know this is not the Maw. It is not our role to punish. Free the others as you have freed me.", ["objectivesText"] = "Free 5 Blistering Outcasts . Progress: Penance, not punishment. It seems the Master has forgotten the difference.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172220 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158088, ["x"] = 0.244, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158088, ["x"] = 0.244, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57571 }, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57534] = { ["id"] = 57534, ["name"] = "When Only Ash Remains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "Is this really what becomes of the exiled? Are they left here to burn to ash? How could the Master allow such a thing? It is cruel. Heartless, even. No venthyr would want to continue on like this. You must end their suffering.", ["objectivesText"] = "Kill 10 Ashen Ravagers .", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172220, 175507, 175508, 175509, 175510, 175716 }, ["rewardChoices"] = { 175507, 175510, 175509, 175508, 175716 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57571 }, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57535] = { ["id"] = 57535, ["name"] = "Escaping the Master", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "Now more than ever I wish to escape this place, but I cannot go back to serve the Master. Not after seeing what goes on here. Simone and I are in agreement. With your assistance, I will craft a mirror that connects to a sanctuary controlled by the prince. We will leave this place and pledge our support to Renathal. But first, I'll need fragments of glass. The Shrouded seem to have plenty, and the fewer they have to make traps, the better.", ["objectivesText"] = "Collect 10 Mirror Fragments . Progress: Have you collected the fragments?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172220 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57533, 57534 }, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57536] = { ["id"] = 57536, ["name"] = "Mirror Making, Not Breaking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "Denathrius does not allow mirrors to be erected within the ember ward. His stone servants shatter anything that so much as glints. I need you to remain vigilant as I make this mirror. I have no doubt that the Master's minions will try to stop us. Are you ready?", ["objectivesText"] = "Defend Laurent and Simone from Stone Legion attackers.", ["rewardGold"] = 772200, ["rewardXP"] = 1770, ["rewardItems"] = { 172074, 172085, 172220, 175733, 177657 }, ["rewardChoices"] = { 175733, 177657 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158505, ["x"] = 0.248, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57535, 59427 }, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57537] = { ["id"] = 57537, ["name"] = "Covering our Tracks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57537 }, ["description"] = "I belong to the House of the Chosen. We have a stronghold to the south, it should be safe there. We'll fly the rest of the way. Approach my flayedwing when you are prepared.", ["objectivesText"] = "Ride with Draka to the House of the Chosen.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[57538] = { ["id"] = 57538, ["name"] = "Disturbing the Peace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57538, 57545, 57547, 57568 }, ["description"] = "This anima drought isn't hard on just the kyrian. The wildlife of Bastion are suffering too! Many creatures are becoming aggressive and menacing, wyrms and cloudfeathers especially. They are hurting the other wildlife and long beyond saving. If someone doesn't clear this garden of these starved creatures, we can no longer meditate here. And if we can no longer meditate, that will make the anima shortage even worse!", ["objectivesText"] = "Kill 10 Anima-Starved creatures. Progress: We must deal with the anima-starved creatures so this place can return to a state of tranquility.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172036, 172037, 172039, 172141 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57529 }, ["questLines"] = { { ["id"] = 1149, ["name"] = "The Spear of Kalliope", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57545] = { ["id"] = 57545, ["name"] = "Distractions for Kala", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57538, 57545, 57547, 57568 }, ["description"] = "When the animals became aggravated, we left in a hurry. However, all of Kala's toys are still inside the garden. Since you are going to be there, would you please collect them? Kala may be very large, but she is still young. She can be a bit of a troublemaker as well. Hopefully the return of her toys will help keep her distracted.", ["objectivesText"] = "Collect Kala's playthings. Progress: Do you have her playthings? She's becoming quite the handful!", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172036, 172037, 172039, 172141 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57529 }, ["questLines"] = { { ["id"] = 1149, ["name"] = "The Spear of Kalliope", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57547] = { ["id"] = 57547, ["name"] = "A Test of Courage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57538, 57545, 57547, 57568 }, ["description"] = "I'm still new and haven't passed all of my Aspirant tests. But, I have an idea. There is an artifact called Korinna's Allaying Crook. Korinna was a powerful Ascended who tamed the creatures of Bastion eons ago. Her staff has the power to prevent more creatures from succumbing to a savage, anima-starved state. However, the artifact is protected and only one with great courage can retrieve it. I bet you could, <name>. Go on ahead. The staff is in the reliquary to the north. I'll join you there shortly.", ["objectivesText"] = "Help Zosime retrieve Korinna's Allaying Crook. Progress: Were you able to retrieve the crook?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172036, 172037, 172039, 172141, 174655, 183045 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57538, 57545 }, ["questLines"] = { { ["id"] = 1149, ["name"] = "The Spear of Kalliope", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57549] = { ["id"] = 57549, ["name"] = "In Agthia's Memory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["series"] = { 57551 }, ["description"] = "Greetings, mortal! Are you here to learn about the legacy of Agthia, Paragon of Courage? I welcome you to walk the grounds of this ancient battleground to learn of the battle that occurred here, and the heroic Paragon who saved all of Bastion and the Shadowlands.", ["objectivesText"] = "Read the Scrolls of Remembrance around Agthia's Repose. Progress: Agthia did not only live a life of courage, but one of service to all of the Shadowlands.", ["rewardGold"] = 365040, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158078, ["x"] = 0.47, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158078, ["x"] = 0.47, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 59554 }, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57551] = { ["id"] = 57551, ["name"] = "Agthia's Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["series"] = { 57549 }, ["description"] = "Now that you have familiarized yourself with the events leading to the battle that took place here eons ago, it is time to experience it for yourself. Ring the bell, take a deep breath, and walk in Agthia 's steps.", ["objectivesText"] = "Ring the Vesper of History.", ["rewardGold"] = 89505, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158078, ["x"] = 0.47, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57549 }, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57552] = { ["id"] = 57552, ["name"] = "Warriors of the Void", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["description"] = "These Void invaders are wiping our forces from existence! My disciples fall, returning their anima to the lands. If we fail to drive them from our lands, more than kyrian will be lost. First Bastion , then the Shadowlands as a whole.", ["objectivesText"] = "Kill 15 Void forces.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.634667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57551 }, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57553] = { ["id"] = 57553, ["name"] = "On Wounded Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["description"] = "I see my peers fall in pain, their wounds from the Void overtaking them. We cannot allow ourselves, or each other, to give up hope. Share your anima with our wounded brothers and sisters. Help them stand tall for another fight!", ["objectivesText"] = "Heal 5 Wounded Defenders .", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158178, ["x"] = 0.461429, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.461429, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57551 }, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57554] = { ["id"] = 57554, ["name"] = "Wicked Gateways", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["description"] = "The forces of the Void are infinite. They travel through the Great Beyond by creating portals, twisting gateways between our planes. Quickly, move to close these portals. Cripple the swell of their forces for as long as we can hold.", ["objectivesText"] = "Destroy 3 Void Portals . Progress: New portals shall open, but we can prevent the swell for a time.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.634667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57551 }, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57555] = { ["id"] = 57555, ["name"] = "Shadow's Fall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57549, 57551, 57552, 57553, 57554, 57555 }, ["description"] = "Despite our efforts, the Void stands strong. All of the forces of Bastion fight, and fall one by one... The Void cannot destroy us! They are led by Tezulat the Annihilator , scourge of a thousand realms. This day, his reign of terror will end!", ["objectivesText"] = "Kill Tezulat the Annihilator . Progress: We shall sing the songs of Agthia , hero of Bastion , for eternities to come.", ["rewardGold"] = 772200, ["rewardXP"] = 1770, ["rewardItems"] = { 175719 }, ["rewardChoices"] = { 175719 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158181, ["x"] = 0.465333, ["y"] = 0.634667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158078, ["x"] = 0.47, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.634667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57552, 57553, 57554 }, ["questLines"] = { { ["id"] = 1148, ["name"] = "In Agthia's Memory", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57568] = { ["id"] = 57568, ["name"] = "Tough Love", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57538, 57545, 57547, 57568 }, ["description"] = "Heavens! Kala has flown off with Korinna's Allaying Crook ! I saw her fly into her den to the west. I must warn you, she can become very protective when she's in there. Please be careful, but do not be afraid to give her some tough love. She is exceptionally resilient. Here, take her slobber ball. It's her favorite and may help to distract her.", ["objectivesText"] = "Retrieve Korinna's Allaying Crook from Kala inside her den. Progress: Do you have the crook?", ["rewardGold"] = 772200, ["rewardXP"] = 1770, ["rewardItems"] = { 172036, 172037, 172039, 172141, 175616, 175617, 175618, 175619, 183045 }, ["rewardChoices"] = { 175618, 175616, 175619, 175617 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158004, ["x"] = 0.512, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57547 }, ["questLines"] = { { ["id"] = 1149, ["name"] = "The Spear of Kalliope", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57571] = { ["id"] = 57571, ["name"] = "Moving Mirrors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427 }, ["description"] = "What sort of horrific trap is this? The Light is being reflected directly on her! Simone 's a dear friend of mine! Free her from that thing, please!", ["objectivesText"] = "Redirect the mirror fragments to free Simone .", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172074, 172085, 172220 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158205, ["x"] = 0.246, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 158088, ["x"] = 0.244, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57532 }, ["questLines"] = { { ["id"] = 1146, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57581] = { ["id"] = 57581, ["name"] = "Plucking Plumes", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 57581 }, ["objectivesText"] = "Progress: Skettis's lapdogs still keeps a close watch over us, outcasts. The moment any of us sets foot outside Shattrath we'll be as good as dead. Continue to bring me more feathers as proof of your victory over them.", ["rewardItems"] = { 25719, 28491, 28492, 28493, 28494, 31800 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 22429, ["x"] = 0.467641, ["y"] = 0.197897 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 22429, ["x"] = 0.467641, ["y"] = 0.197897 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.467641, ["y"] = 0.197897 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[57583] = { ["id"] = 57583, ["name"] = "Through the Veil", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57454, 57455, 57458, 57459, 57463, 57583 }, ["description"] = "I like you, youngling. You put in the work while the others sit in their fancy court, leaving old Marasmius to keep the fae rings thriving. Here, take one of my spores back with you to the Heart of the Forest. Find somewhere nice and cozy for me to rest, will you? Come back and visit me whenever you like. Cort and I can keep an eye on things for now, but there will always be plenty for you to do here. Might even be something special in it for you.", ["objectivesText"] = "Find somewhere to plant Marasmius in the Heart of the Forest.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 178033 }, ["starts"] = { { ["x"] = 0.295, ["y"] = 0.346, ["mapID"] = 1565, ["npcID"] = 166982 } }, ["ends"] = { { ["x"] = 0.295, ["y"] = 0.346, ["mapID"] = 1565, ["npcID"] = 166982 } }, ["coords"] = { ["mapID"] = 1565, ["x"] = 0.295, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questGiverID"] = 166982, ["questTurnInID"] = 166982, ["questType"] = "standard", ["sourceQuests"] = { 57463 }, ["questLines"] = { { ["id"] = 1006, ["name"] = "Saving the Stalks", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57584] = { ["id"] = 57584, ["name"] = "A Fate Most Noble", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["series"] = { 57261, 60735 }, ["description"] = "Welcome, Worthy One! I am Greeter Mnemis . It is my duty and pleasure to assist you on this, your first day among the kyrian. Allow me to congratulate you. Your fate is reserved for the most noble of souls. Only those who lived a life of service may call Bastion home. I am certain you have many questions- all new aspirants do! Please allow me the honor of introducing you to the next chapter of your existence. We will begin when you are ready.", ["objectivesText"] = "Learn more about the kyrian. Progress: Please alert me to your needs and concerns, Worthy One.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158281, ["x"] = 0.422, ["y"] = 0.782 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57102 }, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
