[57634] = { ["id"] = 57634, ["name"] = "Bring Your Own", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57634 }, ["description"] = "Scunner , a roiling mass of flesh and slime, has crawled out of the ruins of the House of Plagues. He emits a toxic vapor that impairs the functions of those who attempt to fight him. You can try it, Maw Walker, but it's doubtful you could hurt him on your own. Constructs are built to fight creatures like Scunner . So gather a force of them and eliminate the threat.", ["objectivesText"] = "Defeat Scunner .", ["rewardXP"] = 8165, ["rewardItems"] = { 178658, 181806, 182382, 182959, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159199, ["x"] = 0.554, ["y"] = 0.684 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58411 } },
[57636] = { ["id"] = 57636, ["name"] = "Pride of Place", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1698, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 57473, 57475 }, ["description"] = "The Mantle of the Primus. It belongs on his statue. You were the one to recover it, so you will have the honor of returning it to its proper place.", ["objectivesText"] = "Place the Mantle of the Primus. Progress: Each answer leads to another question. Each enemy defeated reveals another secret.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 182258, 182267, 182276, 182285 }, ["rewardChoices"] = { 182276, 182267, 182285, 182258 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.498, ["y"] = 0.506, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["ends"] = { { ["x"] = 0.498, ["y"] = 0.506, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.498, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161907, ["questTurnInID"] = 161907, ["questType"] = "standard", ["sourceQuests"] = { 57475 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[57637] = { ["id"] = 57637, ["name"] = "Disturbance Detected: Firelands", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5723, ["mapID"] = 84, ["storyline"] = { 57637 }, ["description"] = "You're early <name>, I hadn't even sent for you yet. Another temporal disturbance has flared up, this time in the Firelands . If Ragnaros hadn't been dealt with when he was, well, you've already seen one way the end time could turn out. Some intricate time weaving is required to be sure you catch Ragnaros early, but still after whatever is causing the disturbance. Whoever is doing this isn't messing around any more.", ["objectivesText"] = "Relive the siege of the Firelands . Progress: Bring me the temporal anomaly as soon as you can, so we can get back to yesterday's problems tomorrow.", ["rewardGold"] = 341600, ["rewardXP"] = 4790, ["rewardItems"] = { 77067, 77069, 152978, 171721, 172506, 208095 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 300 }, { ["id"] = 1166, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 158276, ["x"] = 0.746667, ["y"] = 0.183333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 158276, ["x"] = 0.746667, ["y"] = 0.183333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.746667, ["y"] = 0.183333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 5723 } }, ["questType"] = "standard" },
[57638] = { ["id"] = 57638, ["name"] = "Korrak the Bloodrager", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57638 }, ["description"] = "The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew. We must show them our might! We have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager , tends to remain hidden until given a reason to make his presence known. Death to Korrak would mean death to Winterax Clan! Slay him and return.", ["objectivesText"] = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley. Should Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Dun Baldar. Progress: Be warned, soldier: The Frostwolf also hunt for Korrak.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 18150, 172119, 172121, 172122, 172123, 172125, 172135, 172139 }, ["rewardChoices"] = { 172121, 172122, 172123, 172125, 172139 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.436, ["y"] = 0.16, ["mapID"] = 1537, ["npcID"] = 158515 } }, ["ends"] = { { ["x"] = 0.436, ["y"] = 0.16, ["mapID"] = 1537, ["npcID"] = 158515 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.436, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 158515, ["questTurnInID"] = 158515, ["questType"] = "raid" },
[57639] = { ["id"] = 57639, ["name"] = "The Legend of Korrak", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57639 }, ["description"] = "The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power. They are lead by Korrak the Bloodrager - a cruel and cunning beast. A strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!", ["objectivesText"] = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley. Should Korrak make himself known, destroy him and return to Warmaster Laggrond . Progress: Be warned, soldier, the Stormpike also hunt for Korrak.", ["rewardXP"] = 2125, ["rewardItems"] = { 18149, 172121, 172122, 172123, 172125, 172139 }, ["rewardChoices"] = { 172121, 172122, 172123, 172125, 172139 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.825, ["mapID"] = 1537, ["npcID"] = 158501 } }, ["ends"] = { { ["x"] = 0.501, ["y"] = 0.825, ["mapID"] = 1537, ["npcID"] = 158501 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.501, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 158501, ["questTurnInID"] = 158501, ["questType"] = "raid" },
[57640] = { ["id"] = 57640, ["name"] = "Master Ryson's All Seeing Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57640 }, ["description"] = "Your war in the heart of Alterac means nothing to the Syndicate, <class>. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you. <Master Ryson grins.>", ["objectivesText"] = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson. Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 13151 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 13151, ["questType"] = "pvp" },
[57641] = { ["id"] = 57641, ["name"] = "Master Ryson's All Seeing Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["mapID"] = 25, ["storyline"] = { 57641 }, ["description"] = "Your war in the heart of Alterac means nothing to the Syndicate, . We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you.", ["objectivesText"] = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson. Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", ["rewardItems"] = { 17224, 17363, 17364 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 13151, ["mapID"] = 25 } }, ["ends"] = { { ["npcID"] = 13151, ["mapID"] = 25 } }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
