[57643] = { ["id"] = 57643, ["name"] = "A Gently Shaken Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Feast of Winter Veil", ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 57643 }, ["rewardItems"] = { 21270, 21271, 128652, 128768, 139343, 151345, 162974, 172219, 172225, 178529, 187520, 192093, 210657, 218309, 244906 }, ["starts"] = { { ["objectID"] = 180746 }, { ["npcID"] = 180746, ["x"] = 0.334, ["y"] = 0.659, ["mapID"] = 87 }, { ["npcID"] = 180746, ["x"] = 0.491, ["y"] = 0.782, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 180746, ["x"] = 0.334, ["y"] = 0.659, ["mapID"] = 87 }, { ["npcID"] = 180746, ["x"] = 0.491, ["y"] = 0.782, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.334, ["y"] = 0.659, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85, 87 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[57644] = { ["id"] = 57644, ["name"] = "No Friend Left Behind", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "I would care for nothing more than to serve as navigator again, but my dearest friend suffers. I cannot stand to abandon him. I can feel Twigin now. He struggles against the binding web of the spiders who once served us. More victims of this senseless conflict... Though it pains me to say it, you must slay our spiders and gather their caustic venom. You can then use it to free Twigin . If not out of empathy, rescue him for the sake of your plans. My skills will be useless without his direction.", ["objectivesText"] = "Rescue Twigin . Progress: Please spare him this pain.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181237, 183118 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158604, ["x"] = 0.509333, ["y"] = 0.166667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 158604, ["x"] = 0.509333, ["y"] = 0.166667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.509333, ["y"] = 0.166667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61226 }, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57646] = { ["id"] = 57646, ["name"] = "The Tithelord", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "With his army defeated, the Tithelord is vulnerable. Now, he has but a small contingent to protect him. Let us strike him down decisively. He draws power from these anima wells, keeping it all for himself. If you can hold his attention, I can not only empower you to defeat him but also disable the wells. Speak to me when you are ready to begin. When the time is right, the baroness will lead our new recruits into battle.", ["objectivesText"] = "Slay The Tithelord and collect the Medallion of Envy . Progress: An Archlich? This complicates things.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 173976, 180920, 180921, 180922, 180923 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167689, ["x"] = 0.6864, ["y"] = 0.6896 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167689, ["x"] = 0.6864, ["y"] = 0.6896 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6864, ["y"] = 0.6896 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 167689, ["questType"] = "standard", ["sourceQuests"] = { 57729 }, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57648] = { ["id"] = 57648, ["name"] = "The Impossible Plan", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["series"] = { 62169 }, ["description"] = "Everything is in place for us to seize a necropolis. I will coordinate our efforts and meet you at the Seat of the Primus. Draka will undoubtedly commend you on your success. I, however, will do so once our mission is complete.", ["objectivesText"] = "Report back to Draka at the Seat of the Primus.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.167 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 160518, ["questType"] = "standard", ["sourceQuests"] = { 61323 }, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57649] = { ["id"] = 57649, ["name"] = "Whisper of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "Akarek's demise has cast a dark shadow upon our house... but it is in the shadows where we thrive. I know that not all the Eyes have perished. They could lie in wait, hidden for eternity, if such was demanded of them. But it is time to reclaim our destiny. Take my sigil through the wreckage and awaken any Eyes who remain. We will seize our victory.", ["objectivesText"] = "Use Vashj's Sigil to rally survivors of the House of Eyes.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172371 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164619, ["x"] = 0.505, ["y"] = 0.2005 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.2005 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58007 }, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57650] = { ["id"] = 57650, ["name"] = "Better Off Dead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57650 }, ["description"] = "Our defense is tenuous at best, but the enemy is still hesitant to attack. As long as they fear us, they won't be probing our defenses. You must keep the pressure on the enemy. Attack their positions all along our line.", ["objectivesText"] = "Eliminate Enemy forces and positions.", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Enemy Troops slain", ["amount"] = 15, ["type"] = 0, ["objectID"] = 161376, ["orderIndex"] = 0 }, { ["text"] = "Siege Artillery destroyed", ["amount"] = 5, ["type"] = 0, ["objectID"] = 165828, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[57651] = { ["id"] = 57651, ["name"] = "Trouble in the Banks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "Ah, be welcome in my glade, Maw Walker. You are safe here. While it is regrettable that Sorcha must wait for her weapons, it is of paramount importance that I keep my charges safe. I will do anything to prevent them from suffering as the rest of Ardenweald . Perhaps I could ask a small favor of you. I have not heard from the gatherers at the Banks of Life in some time. Would you mind checking on them to make sure they are well? I would go myself, but I must deal with Sorcha. Seek out Foreman Thorodir .", ["objectivesText"] = "Find Foreman Thorodir near the Banks of Life.", ["rewardGold"] = 24805, ["rewardXP"] = 175, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57660 }, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57652] = { ["id"] = 57652, ["name"] = "Supplies Needed: Amber Grease", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57652, 57655, 59623 }, ["description"] = "Foreman, Our supply of gris is running low. You know as well as I do that there is no end to Glitterfall Basin's need of it. I've overheard from some of the other workers that you have a bit of a gorm problem. But the bigger the gorm, the bigger the gris, right? If you happen to harvest some more, we can certainly put it to good use. <The work order is signed: \"Cavina.\">", ["objectivesText"] = "Collect 6 Giant Gorm Gris . Progress: Do you have something for me?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172221 }, ["starts"] = { { ["x"] = 0.469, ["y"] = 0.276, ["mapID"] = 1565, ["objectID"] = 348747 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165382, ["x"] = 0.515, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1167, ["name"] = "Supplies Needed", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57653] = { ["id"] = 57653, ["name"] = "Unsafe Workplace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "You've returned just in time! Fae are in danger! It seems our actions have enraged the gorm. They are even more aggressive than they were before! While some fae were able to evacuate, there are still many who are trapped down there. Take this jar and slather anyone you find with a generous helping. That should heal their wounds and give them a chance to escape.", ["objectivesText"] = "Heal 10 wounded sylvar in the Banks of Life.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172950, 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59621, 59622 }, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57655] = { ["id"] = 57655, ["name"] = "Supplies Needed: More Husks!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57652, 57655, 59623 }, ["description"] = "I need more husks, Thorodir! The Lady herself wants to make sure we are outfitted with the finest armor. They've been soaking in the waters long enough to be workable. Find some time to retrieve them before our hunters find themselves without adequate protection. <The work order is signed: \"Cavina.\">", ["objectivesText"] = "Collect 6 Treated Gorm Husks . Progress: What's that you have there?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172218 }, ["starts"] = { { ["x"] = 0.475, ["y"] = 0.262, ["mapID"] = 1565, ["objectID"] = 336415 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165382, ["x"] = 0.515, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1167, ["name"] = "Supplies Needed", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57656] = { ["id"] = 57656, ["name"] = "Gifts of the Forest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "These gorm have gone out of control! We need to stop them. I have a plan, but I cannot do it on my own. We lure the gormlings to the Banks of Life by using special totems that are drained of their anima. If you can retrieve the wood required for the totem, I can prepare the ritual. Take these pipes. Find the Culex trees growing on the banks and play a song for them. You will recognize them by their pale green leaves. The wood must be given freely for the ritual to work.", ["objectivesText"] = "Collect 3 Culexwood Branches. Progress: We need that lure for my clever plan. It's very clever, you're going to love it.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172512, 172517, 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158489, ["x"] = 0.48, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158489, ["x"] = 0.48, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59621, 59622 }, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57657] = { ["id"] = 57657, ["name"] = "Tied Totem Toter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57651, 57653, 57656, 57657, 59621, 59622, 59656 }, ["description"] = "Hope you've caught your breath. The totem is now a big, tasty beacon to all the nearby gorm. They're going to want to eat it and you're going to be carrying it! We need to rehome the smaller ones. If they stay here they're just going to get big and angry again. If you can drop off a few groups of them outside the Banks of Life we can make sure they find their way to more balanced feeding grounds. Let Thorodir know when you're done. I will let him know the plan.", ["objectivesText"] = "Lure 30 gormlings to the wrangler in the Banks of Life.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158489, ["x"] = 0.48, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158422, ["x"] = 0.466, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57656 }, ["questLines"] = { { ["id"] = 1162, ["name"] = "Trouble at the Gormling Corral", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57658] = { ["id"] = 57658, ["name"] = "The Final Leg", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57658 }, ["description"] = "Please, I must get to Glitterfall Basin. I thought I was being careful. I did not realize I was being hunted until it was too late. Such is the nature of the forest. I am too close to fall here. The Lady herself invited me to come join her. She said I would be safe. Can you take me to her?", ["objectivesText"] = "Deliver Windchaser to Glitterfall Basin.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[57660] = { ["id"] = 57660, ["name"] = "The Grove of Creation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57660 }, ["description"] = "I probably would have been digested if not for you. And while that sounds like a fascinating phenomenon, I am glad I did not experience it... firsthand. You have a knack for solving problems and you're not afraid to get your hands dirty with our tools. Might I suggest paying a visit to Glitterfall Basin, to the west? It is home to our finest minds and workshops, and I am sure they could use your help in this drought. The Lady of the Falls is droman there. She will know where you can best help!", ["objectivesText"] = "Speak with the Lady of the Falls in Glitterfall Basin.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160121, ["x"] = 0.628, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58026 }, ["nextQuests"] = { 57651 } },
[57661] = { ["id"] = 57661, ["name"] = "Silk Shortage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57661 }, ["series"] = { 60061 }, ["description"] = "We are running short on silk! We use it for so many things, like instruments, weapons, and tools. But our supply has dried up! We are in desperate need for fresh silk. Our main hub of silk production is in the Gossamer Cliffs. If you could, seek out Caretaker Lillythistle , and see what the holdup is!", ["objectivesText"] = "Find Lillythistle in the Gossamer Cliffs.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 178138, 178143, 178144 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158556, ["x"] = 0.484, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159270, ["x"] = 0.39, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[57670] = { ["id"] = 57670, ["name"] = "Unbeelievable Quality", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 57670 }, ["description"] = "<Now that your harvester has matured, the Honeyback hive is creating additional honey. Someone in Brennadam could certainly find a use for this honey.>", ["objectivesText"] = "Take the Collected Tidebloom Honey to \"Nasty\" Buck in Brennadam. Provided item:", ["rewardGold"] = 234000, ["rewardItems"] = { 159847, 168825, 168828, 169106, 172383 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138221, ["x"] = 0.586, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["startItems"] = { 172383, 173533 } },
[57676] = { ["id"] = 57676, ["name"] = "The Things That Haunt Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["description"] = "As you will soon learn, a ritual cleansing can be a... painful process. In most cases, the upwelling of emotion is harmless. It can even generate anima under the right circumstances. However... sometimes the result is far less pleasant. Negative memories can take a form of their own and manifest in a violent fashion. I fear Pelagos' attempt at cleansing has brought forth such monsters. You must destroy them, and quickly.", ["objectivesText"] = "Slay 12 memories. Progress: Is it done?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.461333, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57261 }, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57677] = { ["id"] = 57677, ["name"] = "A Soulbind In Need", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["description"] = "Pelagos is my Soulbind. He is my brother, my closest friend, my mentor, and my student. He knows me completely, and I him. It is a bond stronger than any other. That he now struggles is a torment to me, but I am forbidden from intervening. An aspirant must succeed or fail on their own merits, or the trial is forfeit. I am bound by this law... but you are not. Please bring Pelagos back to me. This will not be his last trial. Not when he may finally have a chance.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardChoices"] = { 175624, 175626, 175625, 175623 }, ["starts"] = { { ["npcID"] = 165107, ["x"] = 0.482, ["y"] = 0.726, ["mapID"] = 1533 } }, ["ends"] = { { ["npcID"] = 165112, ["x"] = 0.482, ["y"] = 0.724, ["mapID"] = 1533 } }, ["coords"] = { ["x"] = 0.482, ["y"] = 0.726, ["source"] = "quest_giver", ["mapID"] = 1533 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57261 }, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } } },
[57686] = { ["id"] = 57686, ["name"] = "The Eternal Traveler", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 47, ["storyline"] = { 57686 }, ["description"] = "Hail, mortal. For untold ages, my kind has traversed the myriad realms of reality. We have beheld phenomena that you cannot begin to comprehend. But there is much you must learn of what awaits you on the horizon. The power of Death is on the rise. The veil weakens between your world and the Shadowlands. When a mortal life expires, an echo of it remains behind. The most powerful mortals leave the most resonant echoes. Bring these to me, that I might study them... to both our benefits.", ["objectivesText"] = "Gather Echoes of Mortality from living creatures. Progress: One can glean so much knowledge from the mortal realm.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 46016, 172954 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 158635, ["x"] = 0.6937, ["y"] = 0.3752 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 158635, ["x"] = 0.475625, ["y"] = 0.234687 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.6937, ["y"] = 0.3752 }, ["mapCandidates"] = { ["npc"] = { 1, 47 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[57689] = { ["id"] = 57689, ["name"] = "Prince Renathal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1960, ["storyline"] = { 57689, 57690, 57691, 57693, 57694, 59327 }, ["series"] = { 57690, 57691, 57693, 57694, 59327, 60568 }, ["description"] = "You! They say you are a Maw Walker. Well, time to put that to the test. My master, Prince Renathal, was the one who started the rebellion. He knew Denathrius was working towards something truly nefarious, and attempted to stop him. The rebellion failed, and Renathal was flung into the Maw . I propose you and I venture into the Maw . There is an old device here that only you will be able to use. Together, we can recover my Prince. You need him, if you are to have any hope of success.", ["objectivesText"] = "Enter the Maw to find Prince Renathal. Progress: Your fighting style lacks... finesse.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 172446 }, ["starts"] = { { ["x"] = 0.428, ["y"] = 0.435, ["mapID"] = 1525, ["npcID"] = 158615 } }, ["ends"] = { { ["x"] = 0.428, ["y"] = 0.435, ["mapID"] = 1525, ["npcID"] = 158615 } }, ["coords"] = { ["mapID"] = 1525, ["x"] = 0.428, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 158615, ["questTurnInID"] = 158615, ["questType"] = "standard", ["sourceQuests"] = { 59327 }, ["questLines"] = { { ["id"] = 1005, ["name"] = "Prince Renathal", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1005, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960 },
[57690] = { ["id"] = 57690, ["name"] = "Cages For All Occasions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57689, 57690, 57691, 57693, 57694, 59327 }, ["series"] = { 57689, 57691, 57693, 57694, 59327, 60568 }, ["description"] = "Okay, do not lose focus. I can feel Renathal's presence. It is faint but I can sense he is outside of the tower, at least. Come, let's find him and get out of here.", ["objectivesText"] = "Find Prince Renathal .", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 172446 }, ["starts"] = { { ["x"] = 0.387, ["y"] = 0.283, ["mapID"] = 1543, ["npcID"] = 158649 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 158645, ["x"] = 0.346, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questGiverID"] = 158649, ["questType"] = "standard", ["sourceQuests"] = { 57689 }, ["questLines"] = { { ["id"] = 1005, ["name"] = "Prince Renathal", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1005, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960 },
[57691] = { ["id"] = 57691, ["name"] = "A Royal Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57689, 57690, 57691, 57693, 57694, 59327 }, ["series"] = { 57689, 57690, 57693, 57694, 59327, 60568 }, ["description"] = "I am not about to question whatever twist of fate led you to me. Your timing could not be better. This cage was custom built to contain me. There is one key, and of course it is on the armor of that large brute over there. Vanquish him and take the key. Be swift, the Jailer's eyes are always on this area.", ["objectivesText"] = "Recover Renathal's Cage Key . Progress: There was an age when I knew how to pick a lock even this elaborate. Sadly that was so long ago I seem to have fallen out of practice.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 172446 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 158645, ["x"] = 0.346, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 158645, ["x"] = 0.346, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["sourceQuests"] = { 57690 }, ["questLines"] = { { ["id"] = 1005, ["name"] = "Prince Renathal", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1005, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960 },
[57693] = { ["id"] = 57693, ["name"] = "Torghast, Tower of the Damned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57689, 57690, 57691, 57693, 57694, 59327 }, ["series"] = { 57689, 57690, 57691, 57694, 59327, 60568 }, ["description"] = "My allies were taken into the Tower of the Damned, and so we must follow. I do not think we must venture deep into those halls, which is good as I do not believe either of us is in shape for a fight like that. Come, let us find our way to one of the most dangerous towers in all of existence.", ["objectivesText"] = "Recover Renathal's Allies from Torghast, Tower of the Damned.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 172446, 175731 }, ["rewardChoices"] = { 175731 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 158645, ["x"] = 0.346, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 158645, ["x"] = 0.346, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questTurnInID"] = 158645, ["questType"] = "standard", ["sourceQuests"] = { 57691 }, ["questLines"] = { { ["id"] = 1005, ["name"] = "Prince Renathal", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1005, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
[57694] = { ["id"] = 57694, ["name"] = "Refuge of Revendreth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1699, ["storyline"] = { 57689, 57690, 57691, 57693, 57694, 59327 }, ["series"] = { 57689, 57690, 57691, 57693, 59327, 60568 }, ["description"] = "Sinfall is more than a ruin. It was once a place of dark magic and experimentation. When the Light retaliated and scorched the Ember Ward, the walls of this place stood. It is fortified, supplied, and filled with secrets. A perfect staging ground for our upcoming conflict. But first, take me to meet these allies who led you to Vorpalia. We must take stock of what resources we have to work with.", ["objectivesText"] = "Gather your allies.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 172446 }, ["starts"] = { { ["x"] = 0.258, ["y"] = 0.571, ["mapID"] = 1699, ["npcID"] = 162688 } }, ["ends"] = { { ["x"] = 0.258, ["y"] = 0.571, ["mapID"] = 1699, ["npcID"] = 162688 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.258, ["y"] = 0.571 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 162688, ["questTurnInID"] = 162688, ["questType"] = "standard", ["sourceQuests"] = { 57693 }, ["questLines"] = { { ["id"] = 1005, ["name"] = "Prince Renathal", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1005, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1005, ["questLineOrder"] = 30 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
[57709] = { ["id"] = 57709, ["name"] = "The Aspirant's Crucible", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57710, 57711 }, ["description"] = "I have given Kalisthene's words some thought. If you are to learn our ways, we should proceed as if you were an aspirant yourself. The next step is to journey through the Aspirant's Crucible. It is a place of reflection, training, and cleansing. For an aspirant, it is where they prepare for the long journey ahead. For you... I hope you will learn how you might help us in this time of crisis. Word of your arrival has likely spread. We will not keep them waiting. Take my steed, and go in service.", ["objectivesText"] = "Ride Theonara to Aspirant's Crucible.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.461333, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57676, 57677 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57710] = { ["id"] = 57710, ["name"] = "A Life of Service", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57709, 57711 }, ["description"] = "Curious. You are unlike any aspirant that has come before, that much is certain. You will notice that we have an audience. It has been a long time indeed since we welcomed another to the path. We are all eager to see what deeds brought you to us. Simply approach the dais before you and gaze into the flame. The Watcher will pull forth your memories of those you served in life, and you will be transported back to those moments to aid them once more.", ["objectivesText"] = "Witness memories of your past life. Progress: Such a display is certain to raise our spirits.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 173344, 177954 }, ["rewardChoices"] = { 173344 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57709 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57711] = { ["id"] = 57711, ["name"] = "A Forge Gone Cold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57709, 57710 }, ["description"] = "I have seen firsthand that you are a most capable soul. Kleia has told me of your purpose here. She has spoken of the hopes she places in you. I am not yet certain if I am ready to do the same. There is one small task that I would set before you, however. My forge has grown cold without anima to keep it burning bright. I long to practice my craft again. My helper, whom you have met before, can elaborate on our needs. You will find Sika near the forge. I will follow shortly.", ["objectivesText"] = "Speak to Sika .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57710 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57712] = { ["id"] = 57712, ["name"] = "Suggested Reading", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57712 }, ["description"] = "Greetings. You must be the new aspirant everyone is talking about. I thought you might like to learn more about us. There are three tomes that would serve you well as a starting point, but they are not currently in the library. Aspirant Leda was the last to hold \" Worlds Beyond Counting .\" Aspirant Ikaran has yet to return \" The Infinite Treatises .\" It seems \" Bear Witness: The Watcher's Code \" went missing some time ago. I would search the village. Once returned, you can read them at your leisure.", ["objectivesText"] = "Retrieve \" The Infinite Treatises \", \" Worlds Beyond Counting \", and \" Bear Witness: The Watcher's Code .\" Progress: Did you find the scrolls I suggested?", ["rewardGold"] = 289575, ["rewardXP"] = 1060, ["rewardItems"] = { 173023, 173024, 173025, 173973 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157138, ["x"] = 0.554, ["y"] = 0.834 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157138, ["x"] = 0.554, ["y"] = 0.834 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.834 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57711 }, ["questLines"] = { { ["id"] = 1195, ["name"] = "Suggested Reading", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57713] = { ["id"] = 57713, ["name"] = "The Work of One's Hands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57908, 59920 }, ["description"] = "Too long have my hands been idle! < Forgelite Sophone smiles warmly at you.> You cannot know what this means to me, but I might be able to show you. For your aid in restoring my forge, please allow me to craft you a piece of armor. It will not be an extravagant affair, but through good works we grow to know ourselves better. I will need your aid once more. Sika and I will guide you on the specifics. All you need to do is listen and do as instructed. What do you say?", ["objectivesText"] = "Assist Forgelite Sophone in crafting a piece of armor. Progress: There is no greater pleasure than creating something from nothing.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 90899, 172516, 173317, 173318, 173319, 173320, 177954 }, ["rewardChoices"] = { 173317, 173318, 173319, 173320 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 59920 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57714] = { ["id"] = 57714, ["name"] = "Assessing Your Spirit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "It is clear to all that you are indeed a skilled combatant. There is one challenge here that continues to test even the strongest among us. I would have you attempt to best a well-known centurion, beloved by all aspirants. It is called Athanos . Consider this a test of your spirit. If you can withstand this trial, then I will deem you ready for what lies ahead.", ["objectivesText"] = "Challenge Athanos . Progress: < Kleia watches you impassively.>", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 173325, 173326, 173327, 173328, 177954 }, ["rewardChoices"] = { 173327, 173325, 173328, 173326 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5335, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57288, 57909 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57715] = { ["id"] = 57715, ["name"] = "The Archon's Answer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920 }, ["description"] = "Your cleansing is complete, and you are whole. Our plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene 's attention once more. Now is our opportunity to request an audience with the Archon. Stand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", ["objectivesText"] = "Speak to Kalisthene .", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156217, ["x"] = 0.535, ["y"] = 0.87 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5335, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57266 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57716] = { ["id"] = 57716, ["name"] = "A Wayward Disciple?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57717 }, ["description"] = "While you are here and as yet unaffected by this--rash of doubt, we shall call it--there is one other errand I would ask of you. I sent one of the disciples to investigate reports of the fallen fleeing our temple. For their own safety, they must be taken to the Temple of Loyalty. Disciple Nikolon has yet to return. If he is to be found nearby, it will be near the border of our temple to the north. Please, seek him out and ensure that he is not injured or in peril.", ["objectivesText"] = "Locate Disciple Nikolon . Progress: Have you located Disciple Nikolon ?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171215, 173340, 173341, 173342, 173343 }, ["rewardChoices"] = { 173341, 173343, 173342, 173340 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57264, 57977 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57717] = { ["id"] = 57717, ["name"] = "Step Back From That Ledge, My Friend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57716 }, ["description"] = "This disciple... such emotion... < Eridia stares at Nikolon for a long moment.> Rarely do ascended require such rigorous cleansing, but I cannot deny what is readily apparent. This disciple will fall if I do not intervene. There is no time to lose. Come. I will instruct you. ... I only hope we are not too late.", ["objectivesText"] = "Assist Eridia in cleansing Disciple Nikolon.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57716 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57718] = { ["id"] = 57718, ["name"] = "Bound in Stone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 57718 }, ["description"] = "Some of our warriors were camped in the small settlement near Guo-Lai when the Baruk invaded the area. Some managed to escape, but they returned with tales of their brothers and sisters in arms being petrified by the mogu stoneshapers into living statues! We can't leave our warriors behind! The stoneshapers must carry some means to reverse the spell and free them from their stone prisons. Bring our soldiers back!", ["objectivesText"] = "Collect Stoneshaper Rods from Baruk Stoneshapers and use them to free 5 Petrified Warriors in the Ruins of Guo-Lai.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 170497 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 307 }, { ["id"] = 1553, ["amount"] = 330 }, { ["id"] = 1553, ["amount"] = 359 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[57719] = { ["id"] = 57719, ["name"] = "Dangerous Discourse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "<The scroll's runes shift and change as you attempt to read it. At first glance, it appears illegible. Similar scrolls have appeared all over the Temple of Purity. Eridia will be interested in these.>", ["objectivesText"] = "Collect 6 Dark Sermons . Progress: We must defend the temple, <name>.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171215 }, ["starts"] = { { ["x"] = 0.572, ["y"] = 0.718, ["mapID"] = 1533, ["objectID"] = 344726 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57717 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57720] = { ["id"] = 57720, ["name"] = "Champions of the Mogu", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 57720 }, ["description"] = "These lesser clans warring with each other in the Vale need to be taught their place. Seek out their champions and eliminate them. Show them that only the Rajani have rightful claim here!", ["objectivesText"] = "Defeat 3 rare enemies while the Mogu are invading the Vale of Eternal Blossoms .", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 303 }, { ["id"] = 1553, ["amount"] = 321 }, { ["id"] = 1553, ["amount"] = 339 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[57721] = { ["id"] = 57721, ["name"] = "Spoils of War", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 57721 }, ["description"] = "The warring clans are relentless and our warriors are going through armor faster than I can keep it repaired. If you find yourself in battle with the other clans, see if you can salvage any undamaged armor pieces from their soldiers. We should not let good resources go to waste.", ["objectivesText"] = "Collect 12 pieces of Salvaged Mogu Armor from mogu enemies in the Vale of Eternal Blossoms . Progress: What have you managed to salvage, outsider?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 64569, 64570, 64571, 64572, 64573, 64574, 64575, 64576, 64577, 64578, 64579, 64580, 172463 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 371 }, { ["id"] = 1553, ["amount"] = 384 }, { ["id"] = 1553, ["amount"] = 461 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[57722] = { ["id"] = 57722, ["name"] = "Empty Stables", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57722 }, ["description"] = "Just look at the stables, <name>! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct. You must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable. When we have enough rams, the ram rider commander will be notified. With your help, the cavalry will be reborn!", ["objectivesText"] = "Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture. Progress: Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!", ["rewardItems"] = { 17689 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 2 }, { ["id"] = 1166, ["amount"] = 5 } }, ["starts"] = { { ["x"] = 0.426, ["y"] = 0.169, ["mapID"] = 1537, ["npcID"] = 158863 } }, ["ends"] = { { ["x"] = 0.426, ["y"] = 0.169, ["mapID"] = 1537, ["npcID"] = 158863 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.426, ["y"] = 0.169 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 158863, ["questTurnInID"] = 158863, ["questType"] = "standard" },
[57723] = { ["id"] = 57723, ["name"] = "Empty Stables", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57723 }, ["description"] = "The war in the valley has taken its toll on our soldiers. We must revitalize our forces! If we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle. Take this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable. When we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.", ["objectivesText"] = "Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master . Speak with the Frostwolf Stable Master to earn credit for the capture. Progress: Without your help, the Frostwolf Wolf Riders would not have mounts to ride into battle. You do us a great service!", ["rewardItems"] = { 17626 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 2 }, { ["id"] = 1166, ["amount"] = 5 } }, ["starts"] = { { ["x"] = 0.571, ["y"] = 0.825, ["mapID"] = 1537, ["npcID"] = 158864 } }, ["ends"] = { { ["x"] = 0.571, ["y"] = 0.825, ["mapID"] = 1537, ["npcID"] = 158864 } }, ["coords"] = { ["mapID"] = 1537, ["x"] = 0.571, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 158864, ["questTurnInID"] = 158864, ["questType"] = "standard" },
[57724] = { ["id"] = 57724, ["name"] = "Securing Sinfall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["description"] = "They're all still active... The stoneborn, the gargon, the stone fiends... All of 'em! Don't got much time. They're always watching. Breakfist points up.> Vulca told me to follow that big beam of Light in the sky. Goes to a tower guarded by a big old brute, though. Couldn't get in.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardChoices"] = { 177642, 177641, 177643, 177639, 177644, 177638, 177637, 177635, 177636, 184326, 184320 }, ["starts"] = { { ["npcID"] = 169105, ["x"] = 0.304, ["y"] = 0.456, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 158716, ["x"] = 0.298, ["y"] = 0.422, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.304, ["y"] = 0.456, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60566 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[57727] = { ["id"] = 57727, ["name"] = "Stonevigil Unrest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "Greetings, <name>. I'm sure you've met my associate, Baroness Draka. I have recruited her to help us with the growing threat of the Tithelord. His involvement with the Maldraxxi renegades is troubling. One conspiracy begets another. So I recruited Draka to help us end it. We must not treat this situation lightly. We first need to put an end to his oppression of Stonevigil Overlook. That way we can we win over the hearts and minds of his subjects.", ["objectivesText"] = "Meet Prince Renathal and Baroness Draka at Stonevigil Overlook.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.518, ["y"] = 0.375, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167380, ["x"] = 0.562, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questGiverID"] = 158653, ["questType"] = "standard", ["sourceQuests"] = { 58395 }, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57728] = { ["id"] = 57728, ["name"] = "Assault: The Endless Swarm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 57728 }, ["description"] = "The mantid swarm is surging! There's no way the Golden Lotus will be able to handle this many of them. We must do something to drive them back!", ["objectivesText"] = "Drive back the Mantid Assault in the Vale of Eternal Blossoms . Progress: Are you with me?", ["rewardXP"] = 10225, ["rewardItems"] = { 174959 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Cull the mantid swarm", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[57729] = { ["id"] = 57729, ["name"] = "To the Estate", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "A window of opportunity has presented itself to us, <name>. With his supply line cut off, Vartox dead, and people turned against him, the Tithelord should be no match for us. However, I must admit I do fear what tools he may have acquired from his Maldraxxi cohorts. His base of operations is just down the road: the Caretaker's Manor, named for the Harvester whom he replaced. We will meet you there.", ["objectivesText"] = "Meet Prince Renathal at The Caretaker's Manor.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 140247 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167620, ["x"] = 0.615333, ["y"] = 0.695333 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167689, ["x"] = 0.6864, ["y"] = 0.6896 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.615333, ["y"] = 0.695333 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60183 }, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57730] = { ["id"] = 57730, ["name"] = "Zinfizzlex's Portable Shredder Unit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57730 }, ["description"] = "I'm as anxious as you are to try out my portable shredder unit, <race>, but before I can make the kit, I'm going to need materials - lots of materials! To be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill. When I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.", ["objectivesText"] = "Master Engineer Zinfizzlex wants you to bring him the following: *30 Thorium Bars . *50 Mithril Bars . *75 Iron bars . *1 Steamsaw . Progress: Mountain is a technical term. It's a goblin engineer thing...", ["rewardItems"] = { 3575, 3860, 12359, 17384, 17410, 17411 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 13377 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 13377, ["questType"] = "pvp" },
[57731] = { ["id"] = 57731, ["name"] = "Zinfizzlex's Portable Shredder Unit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10458, ["storyline"] = { 57731 }, ["description"] = "I'm as anxious as you are to try out my portable shredder unit, <race>, but before I can make the kit, I'm going to need materials - lots of materials! To be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill. When I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.", ["objectivesText"] = "Master Engineer Zinfizzlex wants you to bring him the following: *30 Thorium Bars . *50 Mithril Bars . *75 Iron bars . *1 Steamsaw . Progress: Mountain is a technical term. It's a goblin engineer thing...", ["rewardItems"] = { 3575, 3860, 12359, 17384, 17410, 17411 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 13377 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questGiverID"] = 13377, ["questType"] = "pvp" },
[57737] = { ["id"] = 57737, ["name"] = "Ramkahen Rescue", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 57737 }, ["description"] = "Mar'at was overrun by those foul K'thir before we could safely evacuate our citizens. I fear the worst has happened to them. Please, if anyone is left alive within the city, tell them to come to Ramkahen.", ["objectivesText"] = "Rescue 6 Mar'at Villagers .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1560, ["amount"] = 55 }, { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 315 }, { ["id"] = 1553, ["amount"] = 343 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57766] = { ["id"] = 57766, ["name"] = "War with the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 57766 }, ["series"] = { 46727, 46728, 46729, 47098, 47099, 51341, 58983, 59641, 60362 }, ["description"] = "Good to see you've received proper training as a . We'll need it for what's next. The Alliance's war with the Horde has reached a fevered pitch... and we've lost a lot of good soldiers. King Anduin is looking for aid in an operation to bolster our forces. I told him you'd be a good fit for the job. Before you meet him, let me get get you caught up on what has been happening so far.", ["objectivesText"] = "Speak with Captain Garrick to find out what is happening between the Horde and Alliance.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[57771] = { ["id"] = 57771, ["name"] = "An Unwelcome Incursion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "The Tithelord sent his stoneborn to further reap the anima from these citizens. How long has this been going on? These acts reek of unfathomable greed. There is but one answer to this dilemma: to send a message. Crush these oppressors. Drain their anima and return it to Stonevigil's anima well. The incursion will be dealt with and the downtrodden's spirits lifted. Two birds, one stone. <Draka hands you an anima container.> Take this. I stole it from one of the guards earlier.", ["objectivesText"] = "Drain anima from 12 Stonevigil stoneborn. Then, refuel the anima well in the town center.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180947 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167381, ["x"] = 0.562, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167381, ["x"] = 0.562, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57727 }, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57772] = { ["id"] = 57772, ["name"] = "Fangs and Minds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "The denizens of Stonevigil have been wrung dry by the Tithelord's greed. While some have taken up arms against these injustices, most are too downtrodden to act. We need them on our side to take him down. < Prince Renathal hands you a heavy scroll dripping with anima.> Go, show them the hypocrisy of their oppressor! Send them to me with the promise of sanctuary.", ["objectivesText"] = "Use Renathal's Decree to inspire 8 Stonevigil Citizens .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178213 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167380, ["x"] = 0.562, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167380, ["x"] = 0.562, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57727 }, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57773] = { ["id"] = 57773, ["name"] = "Close to Tears", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 57773 }, ["description"] = "Our warriors have observed foul manifestations coming forth from numerous void tears within the surrounding jungle. They have been but mere weaklings, clearly intended to test our defenses before the real forces arrive. If we do not deal with this threat now, however, it will only be a matter of time until we are overrun by their fodder. Find a way to close those portals!", ["objectivesText"] = "Find and close 3 Void Tears in Uldum . Progress: Have you had any luck with the portals yet?", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 312 }, { ["id"] = 1553, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 364 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57774] = { ["id"] = 57774, ["name"] = "Nine Lives", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 57774 }, ["description"] = "Scouts have returned recently, nearly on the verge of death, with reports that I find... disconcerting. Neferset have been spotted wandering the streets of their city to the south. This would normally be no cause for alarm, except the Neferset were completely wiped out. I must ask you to investigate further... and if by some foul magic these reports turn out to be true, you must do whatever you can to contain this threat!", ["objectivesText"] = "Destroy 8 Neferset Denizens . Progress: Have you news of Neferset City?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1560, ["amount"] = 60 }, { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 328 }, { ["id"] = 1553, ["amount"] = 332 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57778] = { ["id"] = 57778, ["name"] = "The Maldraxxian Job", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["series"] = { 61485 }, ["description"] = "We cannot hope to hold the Seat without a necropolis. Khaliiq reports that Vashj is ready to set her plan in motion. Meet with her and the other Eyes at Nurakkir. Do what must be done.", ["objectivesText"] = "Meet with Whisperer Vyn at Nurakkir.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.506, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.167 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12876 } }, ["questGiverID"] = 161907, ["questType"] = "standard", ["sourceQuests"] = { 62169 }, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57787] = { ["id"] = 57787, ["name"] = "Keep to the Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["series"] = { 60859 }, ["description"] = "That's everything on the list for this part of the forest. Lady Moonberry said to meet her in Tirna Vaal. It's just down the road; I'm going to fly ahead so everyone knows to expect you. Just stay on the path and you won't be eaten. Probably. See you soon!", ["objectivesText"] = "Continue down the road toward Tirna Vaal. Progress: Hey! You survived!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170533, ["x"] = 0.667, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169031, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.667, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60859 }, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57816] = { ["id"] = 57816, ["name"] = "Dreamweaver", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "Troubled winds sweep across Tirna Vaal. The boughs tremble in concern over the Queen's arrival. All must be as it should be. Dreamweaver 's wings droop with the weight of worry. Chaos swirls around the wildseeds under his care. Calm the churning waters of the grove. Bring harmony to discord and let Dreamweaver flutter once more.", ["objectivesText"] = "Speak with Dreamweaver in the Tranquil Pools.", ["rewardGold"] = 24805, ["rewardXP"] = 175, ["rewardItems"] = { 152103, 157822, 176445, 179921, 179922, 179978, 249786, 254267 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169116, ["x"] = 0.642, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57787 }, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57818] = { ["id"] = 57818, ["name"] = "Nothing Goes to Waste", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57818, 57824, 57825, 57952 }, ["series"] = { 57824, 57825, 57952, 61051 }, ["description"] = "The gormlings are industrious creatures. Naturally, they are our source of gorm gris. Gormlings are cute, small, and hungry, like Gloober here! Except he is not hungry right now, because I just fed him. Look at that little belly... <Ahem>. I digress. Gormlings will be drawn to consume anything that is not brimming with anima. They find it simply delicious. Take that wildseed there, and bring it into their pen. Then, see if you can get the gormlings to feast upon it!", ["objectivesText"] = "Collect the Depleted Wildseed , place it in the gormling pen, and coax gormlings to eat it. Progress: Have you fed the gormlings?", ["rewardGold"] = 96525, ["rewardXP"] = 355, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57952 }, ["questLines"] = { { ["id"] = 1194, ["name"] = "Tranquil Pools", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57824] = { ["id"] = 57824, ["name"] = "Collection Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57818, 57824, 57825, 57952 }, ["series"] = { 57818, 57825, 57952, 61051 }, ["description"] = "Now, we can collect the gorm gris for Guardian Kota! Once the gormlings have eaten something, we can 'encourage' them to give it back up. What they produce, we call gorm gris! My Gormherd Branch should encourage them to do this safely. Go on, give it a try on good ol' Gloober first. What has me worried is how the other gormlings might behave. They have been acting so strangely lately!", ["objectivesText"] = "Use the Gormherd Branch on Gloober , then collect gorm gris from the Gorged Gormlings . Progress: I wonder what would happen if I overcharged the Gormherd Branch ... would that be more efficient? Or would it make things explode? ... probably explode.", ["rewardGold"] = 96525, ["rewardXP"] = 355, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57818 }, ["questLines"] = { { ["id"] = 1194, ["name"] = "Tranquil Pools", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57825] = { ["id"] = 57825, ["name"] = "Delivery for Guardian Kota", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57818, 57824, 57825, 57952 }, ["series"] = { 57818, 57824, 57952, 61051 }, ["description"] = "This is most disturbing, indeed. The gorm are just too... wild, now! I wonder if the drought is making everything delicious to them, and that is why. This isn't enough gorm gris, either. And I do not want to disappoint Kota.. But, I also don't want to put you through more trouble collecting it. I will go myself into the burrows nearby, to see if I can find any more for her. Would you take this gorm gris to her for me, please?", ["objectivesText"] = "Deliver the gorm gris to Guardian Kota in Tirna Vaal. Provided item:", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 172953, 172955, 173268, 173534, 175741, 180543 }, ["rewardChoices"] = { 175741 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158921, ["x"] = 0.626, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57824 }, ["questLines"] = { { ["id"] = 1194, ["name"] = "Tranquil Pools", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57850] = { ["id"] = 57850, ["name"] = "Storied Partnerships", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57850 }, ["rewardItems"] = { 137642 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 200 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
