[57853] = { ["id"] = 57853, ["name"] = "Battleforged Team", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 57853 }, ["rewardItems"] = { 137642 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57860] = { ["id"] = 57860, ["name"] = "How to Become Forsworn", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57860 }, ["description"] = "The Forsworn have taken control of Kalliope's Rest and are looting its antiquities. They must be looking for the Spear of Kalliope, a relic of great power. Their numbers are far too great and we are no match. Perhaps there is another way? A small group of aspirants is removing artifacts from the shrine. If you gather uniform pieces and an insignia from them, we can get you inside the shrine unnoticed.", ["objectivesText"] = "Collect 3 Forsworn Uniform Pieces and a Quartermaster's Insignia from within Kalliope's Rest. Progress: Do you have everything we need to make a disguise?", ["rewardGold"] = 386100, ["rewardXP"] = 8165, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.399, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[57861] = { ["id"] = 57861, ["name"] = "Just Act Natural", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57861 }, ["description"] = "With this disguise you will blend right in. I... know a Forsworn artificer on the inside who should prove useful. You need to remain convincing, however. The most important thing is to get to Kalliope's spear before the Forsworn manage to do so. The shrine has many defenses, but it's only a matter of time before they find it. I am somewhat ashamed. Many of the aspirants here used to be friends. So much has been lost.", ["objectivesText"] = "Find Artificer Ligiea farther into Kalliope's Rest.", ["rewardGold"] = 96525, ["rewardXP"] = 2040, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.399, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57860, 59207 } },
[57865] = { ["id"] = 57865, ["name"] = "Ages-Echoing Wisdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "Hmph. Even if I wanted to give her weapons, I cannot. My glade is under attack! Most of my people were driven out during the attack on the growthworks but a few of the elders stayed behind. Whether to delay the enemy or see the friends to safety, they are not here where it is safe. Each elder can perform extraordinary works and could make the weapons in no time at all. Rescue the elders and then we'll talk about using their talents for the good of Ardenweald .", ["objectivesText"] = "Locate Elder Gwenna, Elder Finnan, and Groonoomcrooek.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59656 }, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57866] = { ["id"] = 57866, ["name"] = "Idle Hands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "If you want my help then you are going to need to help me first. There is a group of spriggans that have assaulted the growthworks to the northeast. They are causing all manner of havoc and I simply will not abide this trespass into my lands. Go there and teach them a lesson. If they will not flee, then slay them on the spot!", ["objectivesText"] = "Slay 12 Brittlebark invaders in the Growthworks.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59656 }, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57867] = { ["id"] = 57867, ["name"] = "The Sweat of Our Brow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "Ah, an outsider! You are perfect for this task. The spriggans are known for their mischief. They have been cursing our tools and supplies and trapping unsuspecting workers! Like our curses, they must obey the rules. You'll need shimmerdust for baskets, thread made of gossamer for harps, and minty fresh breath for the soulwebs. How odd. Good luck and let the Lady of the Falls know when you're done. She'll be delighted to hear it!", ["objectivesText"] = "Disarm 6 trapped tools.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 177161, 177162, 177163, 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160045, ["x"] = 0.547, ["y"] = 0.2705 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.547, ["y"] = 0.2705 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59656 }, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57868] = { ["id"] = 57868, ["name"] = "Craftsman Needs No Tools", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "Oh, I am quite all right! There's just one little thing.... One of these fiends made off with my lucky mallet! I simply cannot leave my mallet behind. I do not even use it much any more, but it is quite lucky and I always keep it with me. Please, I cannot even think about building anything without it. Do keep an eye out for it, will you?", ["objectivesText"] = "Find Finnan's Lucky Mallet . Progress: It is small, and quite lucky. I am sure you will know it when you see it.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173150, 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159427, ["x"] = 0.558, ["y"] = 0.235 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159427, ["x"] = 0.558, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59656 }, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57869] = { ["id"] = 57869, ["name"] = "Spirit-Gathering Labor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "You are not like the others. The waters here carry deep power. Power most have forgotten. But the tirnenn forget very little. Power flows through the earth just as water flows with power. Flows can be trapped for a time, dripping. Drop by drop they drip into vessels. Search for the vessels beneath the falls. Collect the power.", ["objectivesText"] = "Collect 6 River Sediment . Progress: Drip, drip, go the falls. Drop, drop, goes the power. Power of the earth.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173187, 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159428, ["x"] = 0.564, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159428, ["x"] = 0.564, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59656 }, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57870] = { ["id"] = 57870, ["name"] = "The Games We Play", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "Do not worry about me. We have a bigger problem. I heard their leader around here somewhere during the attack. I have been keeping watch from here but I have not been able to see them. They must be using some sort of glamour to hide themselves. I have yet to meet a spriggan who can resist a game. If you find one eager to play and can win, then perhaps you can learn something about their leader.", ["objectivesText"] = "Win the game of wits by using emotes to correctly answer the Playful Trickster's riddles.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 180728 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159465, ["x"] = 0.59, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159465, ["x"] = 0.59, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59656 }, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57871] = { ["id"] = 57871, ["name"] = "Outplayed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57865, 57866, 57867, 57868, 57869, 57870, 57871 }, ["description"] = "Now we can strike down their leader, friend. It just so happens that I have a large pouch of puffpetal powder right here. Why don't you take it and toss a few handfuls around the workshop floor at the top of the falls? If they are still there, I imagine they will have an... unfortunate reaction. While you do that I will gather the other elders and make our way to Glitterfall Basin. Speak with the Lady when your task is done.", ["objectivesText"] = "Defeat Wicked Wort .", ["rewardGold"] = 772200, ["rewardXP"] = 1770, ["rewardItems"] = { 173355, 180728, 183849, 183850 }, ["rewardChoices"] = { 183850, 183849 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159465, ["x"] = 0.59, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158345, ["x"] = 0.51, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57870 }, ["questLines"] = { { ["id"] = 1163, ["name"] = "Tricky Spriggans", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57872] = { ["id"] = 57872, ["name"] = "Bring More Friends!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57872 }, ["description"] = "This is only the beginning, friend. I must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here. I have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place. She was last seen near Tirna Fein to the west. Please let her know the way is clear.", ["objectivesText"] = "Locate Roriel.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[57873] = { ["id"] = 57873, ["name"] = "Word from Orsis", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "As you can see, <name>, we have our hands full here dealing with these disgusting bugs. Our caravans from the south have stopped arriving and we have received disturbing news from the few who've made it back recently. I've sent a patrol toward Orsis to investigate; they are past due for a report back. Can I ask you to check in on them for me?", ["objectivesText"] = "Investigate the situation in Orsis.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 154958, ["x"] = 0.408, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57875] = { ["id"] = 57875, ["name"] = "Mark of Humility", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57875 }, ["series"] = { 57914, 57966 }, ["description"] = "Quartermaster, you've arrived. Those fools over there still haven't gotten past the first barrier. We need to get into that cave to have any chance at recovering the Spear of Kalliope. Our research discovered the phrase, \"Only the humble find their way. Even heroes kneel before virtue.\" But those fools have been working on that clue for ages. Go figure out the problem and get inside that cave. We need its mark to open the final vault.", ["objectivesText"] = "Obtain the Mark of Humility from within the First Chamber of Kalliope. Progress: Have you acquired the mark?", ["rewardGold"] = 96525, ["rewardXP"] = 2040, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.429, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57861 } },
[57876] = { ["id"] = 57876, ["name"] = "The End of the Beginning", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1525, ["storyline"] = { 57876, 57877, 57878 }, ["series"] = { 57877, 57878, 58086, 59644 }, ["description"] = "<Renathal struggles to speak, his wounds evident.> I knew Denathrius had hoarded anima, but this... this is beyond imagining. The Jailer will surely use this power to shatter his bonds. Should he break free of the Maw, all the realms of Death will fall. We must continue to press the fight against Denathrius. Alas, we cannot hope to succeed alone. Return to Oribos with Draven and speak to the Honored Voice, Tal-Inara . Tell her what you have seen this day and implore her to action.", ["objectivesText"] = "Speak with the Voice of the Arbiter, Tal-Inara , in Oribos .", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 129258, 129259, 129260, 129346, 129347, 129348, 129349, 141393, 175176, 175177, 175178, 175179, 175208, 175209, 175210, 175211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165557, ["x"] = 0.502, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165557, ["x"] = 0.502, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 165557, ["questType"] = "standard", ["sourceQuests"] = { 58086 }, ["questLines"] = { { ["id"] = 1010, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1137, ["name"] = "Choosing Your Covenant", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1257, ["name"] = "Time Skip", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 126, ["title"] = "The Looming Dark", ["questLineID"] = 1137, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1257, ["questLineOrder"] = 32 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[57877] = { ["id"] = 57877, ["name"] = "The Looming Dark", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 57876, 57877, 57878 }, ["series"] = { 57876, 57878, 58086, 59644 }, ["description"] = "It is good you have returned safely from Revendreth, <name>. We sensed a betrayal that has shifted the infinite threads of fate. The Maw surges with power. We must know the cause.", ["objectivesText"] = "Reveal the Jailer's plan. Progress: As the bearer of this news, you must bear this burden as well.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 175713, 175740, 179513, 179517, 179532, 181398, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181459, 181477, 181479, 181541, 182624, 183396, 183473, 183491, 184378, 184381, 184382, 184383, 184384, 184519 }, ["starts"] = { { ["x"] = 0.392, ["y"] = 0.697, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.392, ["y"] = 0.697, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.392, ["y"] = 0.697 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 57876 }, ["questLines"] = { { ["id"] = 1010, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1137, ["name"] = "Choosing Your Covenant", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1257, ["name"] = "Time Skip", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 126, ["title"] = "The Looming Dark", ["questLineID"] = 1137, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1257, ["questLineOrder"] = 32 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[57878] = { ["id"] = 57878, ["name"] = "Choosing Your Purpose", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 57876, 57877, 57878 }, ["series"] = { 57876, 57877, 58086, 59644 }, ["description"] = "Each covenant is vital to the Shadowlands. Though they often seem at odds with one another, this too is part of the Purpose. All the covenants need to grow strong to face the threat of the Jailer. But your efforts cannot be divided. They must be focused upon a single path. Other mortals may make a different choice. The time has come for you to take a side. Speak to your allies. Then make your choice at the map of the Shadowlands before me.", ["objectivesText"] = "Speak to the Covenants. Decide how your path is entwined with the Purpose. Progress: Have you made your decision yet?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.392, ["y"] = 0.697, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.392, ["y"] = 0.697, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.392, ["y"] = 0.697 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 57877 }, ["questLines"] = { { ["id"] = 1010, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1137, ["name"] = "Choosing Your Covenant", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 126, ["title"] = "The Looming Dark", ["questLineID"] = 1137, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[57880] = { ["id"] = 57880, ["name"] = "An Estate Within the Old Gate", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["series"] = { 60904 }, ["description"] = "I believe I know how we can obtain the Countess's medallion and avoid making any new enemies. Before being cast out into the Light, I held a prominent position within the Countess's court. She bestowed upon me an estate with direct access to her private chambers. If the estate still stands, you can use it to sneak into the Countess's manor and steal the medallion without ever drawing your weapon. Take this note to my trusted butler, Bogdan . He will provide whatever assistance you need.", ["objectivesText"] = "Deliver Theotar's Note to Bogdan within the Old Gate. Progress: What is this? A note from the Duke?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 173158 }, ["starts"] = { { ["x"] = 0.502, ["y"] = 0.186, ["mapID"] = 1699, ["npcID"] = 161979 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questGiverID"] = 161979, ["questType"] = "standard", ["sourceQuests"] = { 60904 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 1, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57881] = { ["id"] = 57881, ["name"] = "The Key to Rebuilding", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "If we plan to revive the estate, we'll first need the keys! When Theotar was exiled to the Ember Ward, he lost all titles and property, meaning that the estate fell into the hands of another aristocrat. The new owner is a mystery to me, but household staff almost always carry keys on them as they do their business within the Old Gate. Recover the key and we'll be on our way to rebuilding the manor.", ["objectivesText"] = "Recover an Ornate Key from Redelav house staff within the Old Gate. Progress: Have you recovered the key?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173180 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57880 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57882] = { ["id"] = 57882, ["name"] = "Reestablishing the Household", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "Unfortunately, when ownership of the estate changed hands, the staff were all displaced and forced to find new work. Some of us found suitable roles within favorable households. After all, everyone needs a sommelier! Others were not so lucky. They're still here in the Old Gate, taking odd jobs to survive. I'm sure they'll be eager to work for the Duke again once they learn we're reestablishing the household. Seek them out and present this offer of employment .", ["objectivesText"] = "Deliver offers of employment to Dumitra , Elena , and Florin .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174839 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57880 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57884] = { ["id"] = 57884, ["name"] = "Reclaiming Thornhill Manor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "I've done some digging and discovered that Viscount Nicolae is the new inhabitant of Thornhill Manor. A vile thing, he is. It'll take us weeks to rid the estate of his stench! Hopefully, you can rid us of him in a much timelier fashion. I'll gather the rest of the staff and together we can reclaim Thornhill Manor.", ["objectivesText"] = "Kill Viscount Nicolae and reclaim Thornhill Manor. Progress: I cannot stand the thought of someone else occupying Thornhill Manor.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57881, 57882 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57885] = { ["id"] = 57885, ["name"] = "A Discreet Entrance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "I can assure you--this is not how we left the place. Never would we ever let the manor fall into such a state. At least the mirror is still intact, that's what's important. You can use it to enter the Countess 's private chambers discreetly and recover the medallion. Go, quickly, before word spreads of what we've done. We'll do our best to restore the manor while you're gone.", ["objectivesText"] = "Enter the Countess 's chambers by using the ornate mirror.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159513, ["x"] = 0.596, ["y"] = 0.349 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57884 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57886] = { ["id"] = 57886, ["name"] = "A Meal and A Deal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "Even though you arrived here uninvited, you weren't unexpected. I know all that goes on within my district. As such, let us share a meal and speak of the matters at hand. I believe there's a way in which we can both get what we want.", ["objectivesText"] = "Enjoy The Countess 's hospitality while listening to her proposal. Progress: Please, enjoy my hospitality.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57885 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57887] = { ["id"] = 57887, ["name"] = "Killing the Messenger", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "I make it my business to know what is going on within my district. Traditionally we use stone fiends to relay messages, but my informants have alerted me to some suspicious communications going on within the Old Gate. A venthyr has been hired to run missives between two undisclosed parties. When someone puts that much effort into concealing their identity, it can never be good. Find this courier and recover whatever missives they might be carrying.", ["objectivesText"] = "Recover a Treasonous Missive from a Redelav Courier. Progress: Has it been done?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 173285 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57886 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57888] = { ["id"] = 57888, ["name"] = "An Invitation to Treachery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "While the missive made it clear that Andrei is displeased with my position, nothing in the letter identifies his co-conspirator. All we really know is that they are trying to gain access to my soiree this evening so they can carry out their plans. Let's make it easy for them, shall we? Head into the Redelav District and deliver an invite to the prominent houses. This way, we'll be sure the traitors show up.", ["objectivesText"] = "Deliver invitations to each of the noble houses within the Redelav District.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173358 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57887 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57889] = { ["id"] = 57889, ["name"] = "\"Accidental\" Arson", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "It's no use trying to get Andrei to tell us who he's working with. He won't talk, and we can't risk alerting his accomplice. We need to get rid of him, and it needs to look like an accident. Once Andrei's been dealt with, set fire to his rug and let the whole estate burn down. Andrei isn't someone you want coming into power. He's as ruthless as he is cruel.", ["objectivesText"] = "Kill Lord Andrei and set fire to his estate.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 180916, 180917, 180918, 180919 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57887 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57890] = { ["id"] = 57890, ["name"] = "Beautiful, But Deadly", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "The Redelav District is home to the most affluent venthyr in all of Revendreth. Its denizens spare no expense on the upkeep of their extravagant gardens. Well worth the effort, I must say. For the Redelav District is the only place where Duskmire mushrooms can grow. They are as beautiful as they are deadly. Would you mind collecting a few? Their uses are varied, and it's always a good idea to have some on hand.", ["objectivesText"] = "Collect 50 Duskmire Mushrooms from gardens within the Redelav District. Progress: Do you have the mushrooms?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173286 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57887 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57891] = { ["id"] = 57891, ["name"] = "Mix, Mingle, and Meddle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "Once the party begins, I will be occupied with a plethora of nobles that wish to cling to my side. This is why I need you to mingle. Speak with the attendees and see if you can determine which house is conspiring against me. Be warned, invited guest or not, these aristocrats can smell an outsider. You won't receive a warm welcome from everyone.", ["objectivesText"] = "Attend the Countess 's soiree and speak with guests to uncover the traitorous house. Progress: One among my guests is the traitor. I need you to find out who.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174923 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159694, ["x"] = 0.58, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159946, ["x"] = 0.568, ["y"] = 0.286 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57888, 57889, 57890 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57892] = { ["id"] = 57892, ["name"] = "Enacting Immediate Justice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "There are likely many in attendance who wish me harm. I trust you have done your job in determining which house has been working with Andrei? Once they are named, I trust you will enact immediate justice.", ["objectivesText"] = "Name the traitorous house and enact justice. Progress: The traitorous house will be uncovered and swiftly dealt with.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159946, ["x"] = 0.568, ["y"] = 0.286 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159946, ["x"] = 0.568, ["y"] = 0.286 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57891 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57893] = { ["id"] = 57893, ["name"] = "Neither Enemy nor Ally", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57880, 57881, 57882, 57884, 57885, 57886, 57887, 57888, 57889, 57890, 57891, 57892, 57893, 60904 }, ["description"] = "I hope you now see the importance of the role I play. My parties serve a greater purpose. Keeping the influential and elite entertained helps quell uprisings. If their minds are consumed by trivial things, they don't have time to plot or plan. Sometimes, battles are best fought before they begin. Giving you my medallion is an example of that. We may not be allies, but we are not enemies, either.", ["objectivesText"] = "Deliver the medallion to Prince Renathal in Sinfall. Progress: Have you secured the medallion?", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 173287 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 159946, ["x"] = 0.568, ["y"] = 0.286 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 159946, ["x"] = 0.568, ["y"] = 0.286 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 159946, ["questType"] = "standard", ["sourceQuests"] = { 57892 }, ["questLines"] = { { ["id"] = 1039, ["name"] = "Desire", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1039, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57895] = { ["id"] = 57895, ["name"] = "Elysian Hold", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57905, 62692, 62698, 62789, 62790, 62791, 62792, 62832 }, ["description"] = "One more step yet remains before your initiation is complete. You must now enter Elysian Hold, entryway to the rest of the Spires of Ascension and the vantage point from which the ascended safeguard Bastion and our aspirants in training. Once there, we shall ensure you are fully acquainted with the hold's offerings. Since you lack wings, I shall escort you there.", ["objectivesText"] = "Travel with Polemarch Adrestes to Elysian Hold.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168906, ["x"] = 0.584, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60492 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[57897] = { ["id"] = 57897, ["name"] = "Dangerous to Go Alone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "There is one last thing you must do before we can act to clean up Denathrius's chaos. You must have a soulbind. All kyrian undergo this sacred ritual--albeit typically many aeons before they stand before the Archon herself. Soulguide Daelia will guide you in this process. Seek her out in the chamber below.", ["objectivesText"] = "Speak with Soulguide Daelia in the Sanctum of Binding.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 62794 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1708 },
[57898] = { ["id"] = 57898, ["name"] = "Soul Meets Body", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly. You will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense. Once complete, your connection will transcend physical space and make you stronger in more than mere brawn.", ["objectivesText"] = "Complete the soulbinding ritual. Progress: Take your time. This is a significant step in your journey to ascension.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57897 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1708 },
[57899] = { ["id"] = 57899, ["name"] = "More Work?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57899, 57900 }, ["series"] = { 57897, 57898, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Your world has a saying that \"you cannot be in two places at once.\" Without a soulbind, that is true. Thankfully we have resolved that matter. Such physical limitations are a mortal construct. Christen our newest addition to the Hold in the ramparts above, then seek out Koros and you will see.", ["objectivesText"] = "Activate the Command Table.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160389, ["x"] = 0.648, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1207, ["name"] = "Adventures", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57900] = { ["id"] = 57900, ["name"] = "Across the Shadowlands", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57899, 57900 }, ["series"] = { 57897, 57898, 57899, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "As kyrian we are responsible for ensuring that every last soul that enters the Shadowlands is sent to their appropriate eternity. However, our eternal charge does not end in Oribos. There are countless matters in the Shadowlands that need attention--far more than any one of us can handle. That, my friend, is where I come in. Consider me your eyes in the field. Allow me to demonstrate with a simple task, so that you may both reap the benefits of my services.", ["objectivesText"] = "Use the Command Table to start an adventure. Progress: Good things are worth waiting for.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160389, ["x"] = 0.648, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160389, ["x"] = 0.648, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57899 }, ["questLines"] = { { ["id"] = 1207, ["name"] = "Adventures", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57901] = { ["id"] = 57901, ["name"] = "All That Remains", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57901, 57903 }, ["description"] = "Just as you must work with your soulbind in an eternal partnership to ensure peace in our realm, so must you work to restore the flow of anima in the sky above. Capheus , one of the great Mikanikos's students, has specialized in the craft of directing what anima we have to the temples that need it most. Given the great drought of anima that plagues us if anyone could use assistance, it would be her.", ["objectivesText"] = "Activate the Anima Conductor. Progress: Yes, yes, you! You can help!", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questTurnInID"] = 167745, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1208, ["name"] = "Anima Conductor", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[57903] = { ["id"] = 57903, ["name"] = "Power in the Sky", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57901, 57903 }, ["description"] = "This device you see here can be used to send anima to our temples and aid our people. As each temple regains its flow of anima, it will begin to function once more. You may find these functions useful in your journeys, or you may even find new challenges that await you. Once you have brought some anima to our sanctum, use the device to direct it to a temple, and see the results for yourself.", ["objectivesText"] = "Use the Anima Conductor to channel anima to a location in Bastion. Progress: Does the anima flow?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.379, ["y"] = 0.675, ["mapID"] = 1707, ["npcID"] = 158773 } }, ["ends"] = { { ["x"] = 0.379, ["y"] = 0.675, ["mapID"] = 1707, ["npcID"] = 158773 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.379, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 158773, ["questTurnInID"] = 158773, ["questType"] = "standard", ["sourceQuests"] = { 57901 }, ["questLines"] = { { ["id"] = 1208, ["name"] = "Anima Conductor", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57904] = { ["id"] = 57904, ["name"] = "Our Eternal Charge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57898, 57899, 57900, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "You have been fully inducted into our sacred covenant, Maw Walker, and may stand tall forevermore as a kyrian. There will be many challenges ahead of us--we shall face them together. For now, return to Polemarch Adrestes and inform him that your training is complete. We are few in number as of late and I am sure he will have need of you. Go in service, <name>.", ["objectivesText"] = "Return to Polemarch Adrestes .", ["rewardGold"] = 25975, ["rewardXP"] = 1020, ["rewardItems"] = { 174292, 177053, 178156, 179942 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 62795 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[57905] = { ["id"] = 57905, ["name"] = "A Unique Opportunity", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57895, 62692, 62698, 62789, 62790, 62791, 62792, 62832 }, ["description"] = "All the anima in the Shadowlands will not restore Elysian Hold to its full glory without willing souls to ensure its many capabilities function properly. Soulguide Daelia is one of our most veteran watchers. She has been tasked with bringing souls to these halls once more. You should pay her a visit within the Sanctum of Binding to see if you might be of aid.", ["objectivesText"] = "Speak to Soulguide Daelia in the Sanctum of Binding.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 62792 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1201, ["name"] = "Among the Kyrian", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 133, ["title"] = "Covenant Tutorials", ["questLineID"] = 1201, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["qu