[57908] = { ["id"] = 57908, ["name"] = "The True Crucible Awaits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57713, 59920 }, ["description"] = "I confess, <name>. I had little hope when you first arrived. Kleia is convinced that your presence here is a sign of things finally improving in Bastion . I was... skeptical. <The Forgelite gestures to her forge.> What you have done for me will not soon be forgotten. There is a path beyond the Crucible. To walk it, you must overcome a trial. It will be difficult. Such a thing takes eons for most. You are not most. Kleia and Pelagos will tell you more. They await you near the sparring grounds.", ["objectivesText"] = "Speak to Kleia and Pelagos in Aspirant's Crucible.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57713 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57909] = { ["id"] = 57909, ["name"] = "Assessing Your Stamina", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "The trial ahead will test you on many levels. I, like Kleia, wish to assess your willingness to endure. Look around you. All the aspirants here train for the very trial you are to attempt. Some have been here, honing their skills, for centuries. Ages. Some grow quickly, some do not. Your task is to engage them in friendly, armed combat. Among the kyrian this is known as a combat meditation. Help them find focus, and they shall help you do the same. Return to me when you feel ready to continue.", ["objectivesText"] = "Participate in 8 combat meditations. Progress: Trust in the process, <name>.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158861, ["x"] = 0.5355, ["y"] = 0.831 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158861, ["x"] = 0.5355, ["y"] = 0.831 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5355, ["y"] = 0.831 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57908 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57912] = { ["id"] = 57912, ["name"] = "Baron of the Chosen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Our forces at the Spearhead are under siege from Margrave Gharmal's vanguard. If Vyraz himself is leading the defense, then the situation must be dire. The House of Constructs shapes flesh to forge bodies for its forces. They were once an indispensable ally, but have become a fearsome enemy. Margrave Krexus trusts your might. No doubt you will have need of it.", ["objectivesText"] = "Meet with Baron Vyraz at the Spearhead.", ["rewardGold"] = 24335, ["rewardXP"] = 175, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159894, ["x"] = 0.392, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60886 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57914] = { ["id"] = 57914, ["name"] = "Mark of Knowledge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57914 }, ["series"] = { 57875, 57966 }, ["description"] = "There is another matter for which I need your assistance. My researchers and interrogators have been tirelessly working on the second chamber. So far they don't have any leads. I need you to speak to them and see if they've made any progress. Tell them, if they have nothing to show, then they will soon find themselves at the end of my sword. Get me that mark, quartermaster!", ["objectivesText"] = "Obtain the Mark of Knowledge . Progress: Did you bring the mark? If not, then why are we speaking?", ["rewardGold"] = 96525, ["rewardXP"] = 2040, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.429, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57861 } },
[57915] = { ["id"] = 57915, ["name"] = "Search for Survivors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "The bugs came from everywhere... There wasn't any time to react. Many of my friends died where they stood, while others tried to fight with our meager tools. I'm a coward. I fled in the commotion instead of trying to help. Now, here I am, out of food and water and too scared to look for survivors. Please, I beg you to help anyone you find left alive in Orsis...", ["objectivesText"] = "Check 8 Wastewanders in Orsis.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 154958, ["x"] = 0.408, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159560, ["x"] = 0.4, ["y"] = 0.452 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57873 }, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57918] = { ["id"] = 57918, ["name"] = "The Absolution of Souls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57918 }, ["series"] = { 57919, 58093 }, ["description"] = "Do you not yet understand the purpose of Revendreth , Maw Walker? The souls under our care teeter on the brink of permanent damnation. Even with perfect attention and careful processing, not every soul can escape the Maw and be elevated to a higher destiny. That is true under the best of circumstances. Currently, due to your installation of the Chamberlain at the Halls of Atonement, we're instead witnessing the worst of circumstances. We must return to the Halls of Atonement and enforce order.", ["objectivesText"] = "Meet the Accuser at Absolution Crypt.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["nextQuests"] = { 57919 } },
[57919] = { ["id"] = 57919, ["name"] = "An Abuse of Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["series"] = { 57918, 58093 }, ["description"] = "The souls have suffered tremendously under the Lord Chamberlain. We venthyr subjugate souls to our will so that we may lead each to the absolution it requires--willing or not. The Lord Chamberlain, however, has been using our relics and rituals to abuse the souls under his authority. He binds the souls to their sinstones, perverting their very essence! Use these ritual chains on the abused soul and subjugate it to your will. We must attempt to absolve it.", ["objectivesText"] = "Subjugate the Abused Soul. Progress: Every lost soul is a tragedy.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57918, 58093 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57920] = { ["id"] = 57920, ["name"] = "The Proper Souls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "We must save as many souls as we can from the fate we have just witnessed. Search the halls for souls who have escaped the Lord Chamberlain's perverse rituals. Subjugate them and bring them to me inside the Halls of Atonement. Together, we will make certain that each soul is appropriately processed and cared for.", ["objectivesText"] = "Subjugate 4 Fugitive Souls and deliver them to the Accuser . Progress: If even one soul can be saved, it is worth it.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160139, ["x"] = 0.706, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57919 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57921] = { ["id"] = 57921, ["name"] = "The Proper Tools", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "There are very specific procedures that we must follow to best tend to the souls under our care. You and I will follow them exactly. I can mask your garish appearance, but you must acquire the necessary ritual tools on your own. Requisition them from the depraved venthyr serving the Lord Chamberlain nearby.", ["objectivesText"] = "Collect Venthyr Ritual Robes , Dagger, and Tome. Progress: We will do this the proper way.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160139, ["x"] = 0.706, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57919 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57922] = { ["id"] = 57922, ["name"] = "The Proper Punishment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "Thankfully, I am not the only one who remembers the high calling of the Halls of Atonement and its servants. These avowed ritualists have been working covertly to preserve the integrity of the halls. They report that the Lord Chamberlain relies on a particularly gifted soulflayer to teach other ritualists how to corrupt the souls. Give him the reward he deserves.", ["objectivesText"] = "Kill Fata the Soulflayer .", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160139, ["x"] = 0.706, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57919 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57923] = { ["id"] = 57923, ["name"] = "Ritual of Absolution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "The ritual of absolution is a sacred rite that forces souls to discard the burdens of their mortal lives. The soul must be a willing participant if the ritual's effect will be meaningful and long-lasting. We often spend ages preparing a soul for a single absolution ritual. The Lord Chamberlain has neglected his duty. These souls are overdue for absolution, practically bursting with anima. We will perform the ritual ourselves, and hurry these souls along their journey.", ["objectivesText"] = "Help the Accuser complete the ritual of absolution. Progress: Absolution is where mercy meets justice.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160139, ["x"] = 0.706, ["y"] = 0.468 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160163, ["x"] = 0.713, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.706, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57920, 57921, 57922 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57924] = { ["id"] = 57924, ["name"] = "Ritual of Judgment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "After all rituals of absolution are complete, each soul must face its final judgment in Revendreth . There are three potential verdicts: If proven unworthy, it is condemned to the Maw for eternity. If fully absolved of its sins, it is either elevated to a venthyr or returned to the Arbiter to be assigned its new destination. Our most sacred ritual, the judgment, determines this fate. One such ritual is happening now. I will disguise you and we will participate to ensure a just verdict.", ["objectivesText"] = "Participate in the ritual of judgment.", ["rewardGold"] = 193050, ["rewardXP"] = 1060, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160163, ["x"] = 0.713, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160294, ["x"] = 0.742, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.713, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57923 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57925] = { ["id"] = 57925, ["name"] = "Archivist Fane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "Well, our disguises are superfluous now. We will not be welcome after disrupting their depraved ritual. Despite what we've observed here, some steadfast venthyr do still remain within these halls. Those who have not forsaken our vocation, and carry on with our calling. Archivist Fane is one such as these. Aid his endeavors however you can. We will need his insight to loosen the Lord Chamberlain's grip over these halls. I must tend to Gresit. He has much to learn.", ["objectivesText"] = "Introduce yourself to Archivist Fane .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160294, ["x"] = 0.742, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57924 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57926] = { ["id"] = 57926, ["name"] = "The Sinstone Archive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "You said Inquisitor Traian oversaw the ritual? < Archivist Fane searches the massive archives in this chamber.> We archivists maintain strict records of every soul that passes through these halls. Or at least we're supposed to. The sinstones of powerful venthyr tend to go \"missing.\" < Archivist Fane rolls his eyes.> I don't see his sinstone here. He might've stolen it, or someone could be hoarding it as blackmail. Help me complete my archives, and I'll get you any sinstone you need.", ["objectivesText"] = "Collect 100 Sinstone Records . Progress: Sinstones are the most powerful weapon in Revendreth .", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57925 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57927] = { ["id"] = 57927, ["name"] = "Rebuilding Temel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "Revendreth demands penance from all, and it would appear that even you are not exempt. < Cryptkeeper Kassir grins.> Do not fear, I have no intention of exacting revenge for the violence you inflicted upon me. But I cannot offer you Temel either. The Lord Chamberlain--who you so wisely chose to install as master of these halls--deemed Temel a threat to his control. His thugs bashed Temel to bits and scattered the pieces among these crypts. It's not the first time I've had to rebuild him.", ["objectivesText"] = "Collect Temel's Head , Body, and Wings. Progress: No matter how broken Temel is, I can rebuild him.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60127 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57928] = { ["id"] = 57928, ["name"] = "Atonement Crypt Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "<This key is marked with a sigil that matches the crypts in the Halls of Atonement. What is the Lord Chamberlain hiding away in there?>", ["objectivesText"] = "Open an Atonement Crypt.", ["rewardGold"] = 193050, ["rewardXP"] = 1060, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57925 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["startItems"] = { 173735 } },
[57929] = { ["id"] = 57929, ["name"] = "Hunting an Inquisitor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "You may have noticed that inquisitors are protected by the Lord Chamberlain's magic. A potent consequence of wielding the Master's medallion. But now that we have access to Inquisitor Traian 's sinstone from the archives, we have the power needed to break through those defenses. Locate the inquisitor, and order Temel to read out from his sinstone. Declaring the true name and sins of the inquisitor will shatter his defenses and make him vulnerable for a short window of time. Be ready to strike.", ["objectivesText"] = "Kill Inquisitor Traian . Progress: Truth, wielded properly, is a potent weapon.", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57926, 60128 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[57931] = { ["id"] = 57931, ["name"] = "Phalynx Malfunction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["series"] = { 58185 }, ["description"] = "As part of their training, I order my phalynx units to march the fields, keeping an eye on the wildlife and any goings-on. Unfortunately, last time they returned they were one fewer in number. Please search the Golden Pasture and search for the missing unit, then return it here.", ["objectivesText"] = "Find Gatamatos in the Golden Pasture and return him to his pedestal in Forgefire Outpost. Progress: My phalynx units require occasional repairs to keep them operational. If one is overlooked, it may malfunction.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58185, 59674, 63068 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57932] = { ["id"] = 57932, ["name"] = "Resource Drain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Usually repairs easy. Anima everywhere! Except drought means we can't just pull it from air. Other sources needed! Take this. Drain anima from cloudstriders. Not ideal, but desperate times.", ["objectivesText"] = "Drain anima from Gilded Cloudstriders 5 times. Progress: Drought has big effects. Feel bad for cloudstriders.", ["rewardGold"] = 358020, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159609, ["x"] = 0.547, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159609, ["x"] = 0.547, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.547, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58185, 59674 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57933] = { ["id"] = 57933, ["name"] = "We Can Rebuild Him", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Gatamatos needs numerous repairs to meet functional standards. Upkeeping phalynx is part of the role. Lend a hand so we may finish the repairs thoroughly and quickly.", ["objectivesText"] = "Aid Pelodis in repairing Gatamatos . Progress: As long as you keep your phalynx in working condition, they will obey without hesitation.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57931, 57932 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57934] = { ["id"] = 57934, ["name"] = "Combat Drills", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Our phalynx units excel in combat. They are thoroughly trained in taking foes down by the legs, as well as hunting down beasts gone awry. I need you to take stock of Gatamatos's fighting routines. Take him into the cavern below and practice his combat against the wyrms there.", ["objectivesText"] = "Kill 8 Agitated Etherwyrms in the Hall of Beasts with Gatamatos.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57933 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57935] = { ["id"] = 57935, ["name"] = "Laser Location", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Phalynx have precise detection mechanisms that allow for excellent scouting. In the cave below we have scattered gems that our units are trained to locate. Escort Gatamatos to run some drills and recalibrate his training.", ["objectivesText"] = "Bring Gatamatos to the Hall of Beasts, then direct him to locate 6 Training Gems . Progress: The technical process behind phalynx tracking and locating their targets is quite fascinating. However... you do not seem the type who is interested in the details.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57933 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57936] = { ["id"] = 57936, ["name"] = "Superior Programming", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Phalynx listen to their orders. Never disobey! Larions are wild beasts. Can attack. Could eat a steward, probably! Untamed larion lives close. Has chased many stewards, very scary! Please take care of it.", ["objectivesText"] = "Kill Leonid in the Hall of Beasts. Progress: Wild beasts. Terrifying! No thank you! I work with very safe phalynx.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702, 175612, 175613, 175614, 175615, 175635, 175636, 175637, 175638 }, ["rewardChoices"] = { 175613, 175615, 175614, 175612, 175635, 175638, 175637, 175636 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159609, ["x"] = 0.547, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159609, ["x"] = 0.547, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.547, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57933 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57937] = { ["id"] = 57937, ["name"] = "Tactical Formation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "The principal step of our training regiment for our phalynx is formational drills. They must recall standard kyrian battle formations, and how to flow from one to the next. Formational training is the final piece of information that Gatamatos is still missing. Please aid in retraining him.", ["objectivesText"] = "Aid Gatamatos in taking the correct position in three formations. Progress: A good soldier marches in order.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57934, 57935, 57936 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57947] = { ["id"] = 57947, ["name"] = "Spirits of the Glen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "Animals of the forest, mortal souls given form, frolic in the glen. Their anima, a boon to the weald, given freely as rain on the leaves. But danger lurks in the shadows. A dark storm of malice and enmity tears at the trees. Creatures seeking shelter find only peril. Rescue them.", ["objectivesText"] = "Find Choofa in the Spirit Glen.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 176445, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159638, ["x"] = 0.67, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57787 }, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57948] = { ["id"] = 57948, ["name"] = "Nothing Left to Give", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "Oh no, oh no! My friends, they gave so much. So much of their anima, they lost their forms! We all take a form when we come here, you see. Something that suits us! But we give our anima, we give! To help the groves. And we give so much... sometimes too much. I still have some anima. I still have my form! Get me to my friends! We can get THEIR forms back!", ["objectivesText"] = "Restore soul shapes to Slanknen , Rury , and Awool in the Spirit Glen. Progress: Oh dear, oh dear. My friends are in trouble!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176445, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159638, ["x"] = 0.67, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159639, ["x"] = 0.6844, ["y"] = 0.3508 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57947 }, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57949] = { ["id"] = 57949, ["name"] = "They Need to Calm Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "Spriggans! Nasty spriggans. They came to the grove. They messed it all up! They took the anima from the soul webs! We were collecting it, yes. Collecting it for the Tall Tree and their grove. The spriggans have to pay! Beat them up! Then use this soulweb to take back the anima. We need it! They don't!", ["objectivesText"] = "Defeat Spriggans and use the Soulweb to drain them of stolen anima in Spirit Glen. Progress: Did you destroy them? Did you make them pay?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176445, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159638, ["x"] = 0.67, ["y"] = 0.322 }, { ["mapID"] = 1565, ["npcID"] = 159639, ["x"] = 0.6844, ["y"] = 0.3508 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159639, ["x"] = 0.6844, ["y"] = 0.3508 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57947 }, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57950] = { ["id"] = 57950, ["name"] = "Mizik the Haughty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["series"] = { 57951 }, ["description"] = "Bad spriggans! Bad! They take our anima. We lose our forms! And one is worst of all. Mizik! He tells the others what to do. And he rides a gorm! Big, nasty gorm! Get him. Get him!", ["objectivesText"] = "Defeat Mizik the Haughty .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 64482, 176445, 176730, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159639, ["x"] = 0.6844, ["y"] = 0.3508 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 159638, ["x"] = 0.67, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6844, ["y"] = 0.3508 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57948, 57949 }, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57951] = { ["id"] = 57951, ["name"] = "Souls Come Home", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["series"] = { 57950 }, ["description"] = "To the tree, to the tree! It is time for us to return to the grove. We have our anima. We have our forms. The Tall Tree needs the anima. The Tall Tree will be happy! I will see you there!", ["objectivesText"] = "Report your success to Droman Tashmur in Tirna Vaal.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 173292, 175656, 175657, 175658, 175659, 176445, 179921, 179922, 179978 }, ["rewardChoices"] = { 175659, 175657, 175658, 175656 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 159638, ["x"] = 0.67, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57950 }, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57952] = { ["id"] = 57952, ["name"] = "In Need of Gorm Gris", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57818, 57824, 57825, 57952 }, ["series"] = { 57818, 57824, 57825, 61051 }, ["description"] = "Our neighboring grove at Glitterfall Basin has sent out a desperate plea for gorm gris. It may have humble origins, but it is an important ingredient for our artisans and crafters. As this drought goes on, it has become increasingly difficult to collect. I would like to help them out, with the resources that we are able to spare. Please, find Master Sha'lor out by the Tranquil Pools, where he keeps our little gormling population. Ask him for more gorm gris.", ["objectivesText"] = "Seek out Master Sha'lor by the Tranquil Pools.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158921, ["x"] = 0.626, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158969, ["x"] = 0.648, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60519 }, ["questLines"] = { { ["id"] = 1194, ["name"] = "Tranquil Pools", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[57954] = { ["id"] = 57954, ["name"] = "Burn the Bodies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "The bugs seem to be indiscriminately laying eggs all over the nearby corpses. They are using them as food to spawn more of those horrible things. Disgusting! We can mourn the dead later, but if any more bugs are allowed to hatch we may not live long enough to do so. Burn the bodies and destroy those eggs!", ["objectivesText"] = "Burn 10 Egg-bearing corpses.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174323 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57955 }, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57955] = { ["id"] = 57955, ["name"] = "To Ankhaten Harbor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "I fear that I don't yet have the strength to ride out into the sands and face those monsters again. Ride to the south and find Tracker Samara in the excavation camp formerly known as Schnottz's Landing. Tell her to halt any caravans that plan to pass this way, lest others are ambushed and met with the same grisly fate. We must get the word out across Uldum before our forces are further divided!", ["objectivesText"] = "Find Tracker Samara in Ankhaten Harbor.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159560, ["x"] = 0.4, ["y"] = 0.452 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57915 }, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57956] = { ["id"] = 57956, ["name"] = "Wastewander Hosts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "The bugs have been laying eggs in the corpses of our soldiers, it's absolutely terrifying! Some of them are rising from the ground as putrid, bloated, hideous monstrosities. We have to stop them before they continue to bolster their ranks with our fallen. It's not a pleasant task... but I have to ask you to help me destroy them. Completely. Grab some bombs behind me, if you'd like.", ["objectivesText"] = "Kill 6 Wastewander Hosts .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174325 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57955 }, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57959] = { ["id"] = 57959, ["name"] = "Heroic Warfront: The Battle for Darkshore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 57959 }, ["description"] = "Darkshore belongs to the Horde! We must hold that ground to maintain our dominance over Kalimdor. Prepare yourselves. Battle awaits!", ["objectivesText"] = "Defeat the Alliance at the Battle for Darkshore.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 166369, 166370 }, ["rewardCurrencies"] = { { ["id"] = 1716, ["amount"] = 50 }, { ["id"] = 1553, ["amount"] = 750 }, { ["id"] = 1803, ["amount"] = 75 }, { ["id"] = 1803, ["amount"] = 375 } }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[57960] = { ["id"] = 57960, ["name"] = "Heroic Warfront: The Battle for Darkshore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 57960 }, ["description"] = "We will not tolerate further Horde aggression in our territories. The night elves will not stand alone this day. Darkshore will be theirs once more. For the Alliance!", ["objectivesText"] = "Defeat the Horde at the Battle for Darkshore.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 158075, 166369, 166370 }, ["rewardCurrencies"] = { { ["id"] = 1717, ["amount"] = 50 }, { ["id"] = 1553, ["amount"] = 750 }, { ["id"] = 1803, ["amount"] = 375 }, { ["id"] = 1803, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
