[57964] = { ["id"] = 57964, ["name"] = "Revenge Is Easy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57964 }, ["description"] = "There's still a lot of us here, trying to survive in these ruins. These constructs have been encroaching on us constantly. They steal what they can, and haul off any of us they capture to be recycled in their labs. The solution here requires an extensive use of violence, by you!", ["objectivesText"] = "Kill 15 bonefused forces. Progress: I still see a lot of abominations walking around.", ["rewardGold"] = 238680, ["rewardXP"] = 8165, ["rewardItems"] = { 181501, 181625, 181626, 181638, 181645, 181646, 181647, 181648, 181649, 181652, 181653, 181660, 181661, 181662, 181663, 181671, 181672, 181673, 181674, 181679, 181680, 181681, 181682, 184195, 184305, 184772, 184773, 184774, 184775, 184776 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 160523, ["x"] = 0.514, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160523, ["x"] = 0.514, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[57966] = { ["id"] = 57966, ["name"] = "You Go First", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["series"] = { 57875, 57914 }, ["description"] = "You've proven useful. So, I am going to require you to disarm the defenses of this hall. Please take care not to die too quickly. I'd like to have the spear before the end of this eon.", ["rewardGold"] = 386100, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 159272, ["x"] = 0.432, ["y"] = 0.384, ["mapID"] = 1533 } }, ["ends"] = { { ["npcID"] = 159272, ["x"] = 0.432, ["y"] = 0.384, ["mapID"] = 1533 } }, ["coords"] = { ["x"] = 0.432, ["y"] = 0.384, ["source"] = "quest_giver", ["mapID"] = 1533 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57875, 57914 } },
[57967] = { ["id"] = 57967, ["name"] = "Rightful Resting Place", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57967 }, ["description"] = "You have truly proven yourself a hero in the eyes of those who are its absolute judge. I thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place. Let us meet at Elysian Hold where you can do the honors.", ["objectivesText"] = "Enshrine the Spear of Kalliope in its rightful place at Elysian Hold. Progress: <The resting place of the spear lies before you.>", ["rewardGold"] = 96525, ["rewardXP"] = 2040, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.399, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questTurnInID"] = 159248, ["questType"] = "standard", ["sourceQuests"] = { 57989 } },
[57968] = { ["id"] = 57968, ["name"] = "The Wastewandering Dead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 57968 }, ["description"] = "Is there no end to these foul monsters!? I cannot abide the desecration of our dead, especially not as fodder for this disgusting insect army. Destroy as many as you can, preferably with fire!", ["objectivesText"] = "Kill 6 Wastewander Hosts . Progress: I hope you've been keeping count of your kills.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 321 }, { ["id"] = 1553, ["amount"] = 365 }, { ["id"] = 1553, ["amount"] = 406 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57969] = { ["id"] = 57969, ["name"] = "Tend the Wounded", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "My friend, as you can see here, we are besieged by these terrible creatures. Many of our comrades have fallen prey to the monsters, but fortunately, we have enough warriors here to keep the threat at bay... for now. If you are able to assist us, please, tend to our wounded and help clear a path for them to escape the ruins.", ["objectivesText"] = "Heal 8 Wastewander Laborers .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174326 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57971 }, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57970] = { ["id"] = 57970, ["name"] = "Ruinator Xok'nixx", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "Ar'kali and a group of our warriors are engaged with a most behemothic creature in the heart of the ruins. She can hold her own against nearly any foe, but I fear it is only a matter of time before this monster is able to wear them down. Although the creature is occupied for now, if our warriors fall, the ruins will be lost to us. Please, make haste, with your help they can surely fell this titanic foe.", ["objectivesText"] = "Kill Ruinator Xok'nixx .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57971 }, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2241, ["db2PoiUiMapID"] = 1527 },
[57971] = { ["id"] = 57971, ["name"] = "Ruins of Ammon", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "These things seem to be everywhere and all at once! Either this was an organized attack, or there are far more of them than we can even comprehend. Regardless, this is bad for us... really, really bad. $p, I need you to travel to the Ruins of Ammon and find out what the situation is like over there. If they need help, please try to lend a hand!", ["objectivesText"] = "Travel to the Ruins of Ammon.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57954, 57956 }, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
