[57976] = { ["id"] = 57976, ["name"] = "Lead By Example", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Margrave Krexus expects much of you, mortal. Show these soldiers how a true champion of the arena vanquishes their foes and claims victory! Meet these traitorous constructs head on. Leave none standing!", ["objectivesText"] = "Kill 12 Steelskin Vanguard or Steelskin Brutalizers . Progress: What?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159894, ["x"] = 0.392, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 169226, ["x"] = 0.394, ["y"] = 0.466 }, { ["mapID"] = 1536, ["npcID"] = 169359, ["x"] = 0.394, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57912 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57977] = { ["id"] = 57977, ["name"] = "A Temple in Need", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["series"] = { 57270 }, ["description"] = "< Eridia peers down at you.> Your face is new to me. < Eridia frowns.> I regret that this shall be your introduction to our temple. As my disciple has informed you, we seek the aid of all available aspirants to tend to those in our care. Do not trouble yourself over the specifics of the work that is needed. Those devoted to this temple will guide you. Seek out the disciples within. You may find me within the temple when you have given your aid.", ["objectivesText"] = "Aid the disciples within the Temple of Purity. Progress: Have you lent my disciples your aid?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57270 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[57979] = { ["id"] = 57979, ["name"] = "Offensive Behavior", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Fine work, $p. We've advanced with minimal casualties. From this new forward position, we can strike directly at the enemy commander. The troops you rallied will join the attack. Together, we will bring this battle to a decisive end. Locate General Alver and sound the horn.", ["objectivesText"] = "Kill General Alver .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175763, 176456, 179923, 180120 }, ["rewardChoices"] = { 175763 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 169226, ["x"] = 0.394, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 169226, ["x"] = 0.394, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57976, 58268, 60557 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57982] = { ["id"] = 57982, ["name"] = "Breaking Down Barriers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "As I suspected, Stitchflesh's assistants are carrying on his work. Whatever they're building, we need to destroy it. They've secured the chamber with a soul barrier and several bile spewers. We must find a way through! Thales said he may have a suggestion.", ["objectivesText"] = "Find a way past the Soul Barrier. Progress: Is the barrier down?", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57985, 57986, 57987 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57983] = { ["id"] = 57983, ["name"] = "Archon Save Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Most of the aspirants were slaughtered and dismembered on arrival. They were the lucky ones. The lead surgeon decided that the only things worth taking from me... were my eyes. I was discarded afterward and left to my rot. Archon save me, the screaming... I think there are other survivors being held nearby. Can you aid me in freeing them?", ["objectivesText"] = "Save the souls in the Holding Pens. Progress: Yes?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 160211, ["x"] = 0.344667, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160211, ["x"] = 0.344667, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.344667, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 160211, ["questType"] = "standard", ["sourceQuests"] = { 59616 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57984] = { ["id"] = 57984, ["name"] = "The Ones in Charge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "They have been collecting kyrian... and our corpses... for some dark purpose. Whatever they are planning, we must put a stop to it. I have overheard mention of three individuals who seem to be in charge. We need to find them and eliminate them.", ["objectivesText"] = "Slay Doctor Hivvil , Tabulator Hymeris , and Leacher Cvan .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175474, 175475, 175476, 175477, 176456, 179923, 180120 }, ["rewardChoices"] = { 175477, 175475, 175476, 175474 }, ["starts"] = { { ["npcID"] = 161060 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questGiverID"] = 161060, ["questType"] = "standard", ["sourceQuests"] = { 57983 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57985] = { ["id"] = 57985, ["name"] = "Give Them a Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "The corpses are brought to this pit for processing. Their flesh is liquified and congealed before being shaped into new constructs. We can hinder their production by extracting the animates from the pool prematurely. Use this hook to do so. Do not let Baron Halis catch you. He has a reputation for cruelty, even within his own house.", ["objectivesText"] = "Destroy 10 Vestigial Animates . Progress: The weak make way for the strong, such is the way of Maldraxxus .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57984 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57986] = { ["id"] = 57986, ["name"] = "A Burden Worth Bearing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Mevix may be here for blood, but what I want is to spare my fallen kin from a terrible fate. Most of my fellow kyrian were either slain in combat or shortly after arriving here. If their corpses were bound for this pit, then perhaps we can recover them before they are thrown into it. Take the stewards with you and gather the bodies of my brethren. I will not allow them to be made into monsters.", ["objectivesText"] = "Help Kou and Koa retrieve 6 Lost Kyrian. Progress: Were there any left?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 160211, ["x"] = 0.344667, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 169949, ["x"] = 0.3, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.344667, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57984 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57987] = { ["id"] = 57987, ["name"] = "A Deadly Distraction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "Vyraz's assault on the House of Constructs may have failed, but we can still make them bleed now that we're inside. Slaughter as many as you can. I will hunt down the masterminds behind these new production efforts.", ["objectivesText"] = "15 Warstitched forces slain.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120, 180127 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57984 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57989] = { ["id"] = 57989, ["name"] = "The Spear of Kalliope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57989 }, ["description"] = "The Spear of Kalliope is finally in my grasp! With it, I will lay waste to all the Forsworn's enemies. Now behold while I take my prize!", ["objectivesText"] = "Defeat Artificer Ligiea and earn the Spear of Kalliope . Progress: Did you find the spear?", ["rewardGold"] = 386100, ["rewardXP"] = 8165, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159272, ["x"] = 0.429, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.429, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57966 } },
[57990] = { ["id"] = 57990, ["name"] = "Obelisk of the Sun", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "I have one more thing I must ask of you, my friend. Completion of this task is critical to our survival here. Our comrade, Zahra, has taken it upon herself to climb the plateau just east of us to secure one of the old bombers left up there. So far, our attempts to get word back to Arik have failed. However, if you can help her get one of those planes working, we might just have a chance. Hopefully they can send aid before we are overrun...", ["objectivesText"] = "Locate Exterminator Zahra at the Obelisk of the Sun.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57969, 57970, 58606 }, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2241, ["db2PoiUiMapID"] = 1527 },
[57993] = { ["id"] = 57993, ["name"] = "Two of Them, Two of Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "A construct made entirely of kyrian flesh... This betrays everything Maldraxxus stands for! We are meant to defend the Shadowlands and all within it, not slaughter and exploit them! Come, $p! We end this now!", ["objectivesText"] = "Defeat Sharrex the Fleshcrafter and First Apprentice Malkrex .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175447, 175448, 175449, 175450, 176456, 179923, 180120, 180127 }, ["rewardChoices"] = { 175449, 175448, 175450, 175447 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165397, ["x"] = 0.311, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165575, ["x"] = 0.288, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57982 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[57994] = { ["id"] = 57994, ["name"] = "In The Flesh", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "The souls of the fallen kyrian... I can sense their pain and confusion. They yet exist within the construct! Please, we must not destroy it. Doing so would consign the souls within it--the souls of my brethren--to oblivion. Perhaps... perhaps they can aid us in escaping to freedom. I will soothe the souls within the construct while you direct its actions.", ["objectivesText"] = "Take control of the Soulfused Construct and escape the House of Constructs. Progress: My fallen kin...", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 30341, 30342, 30352, 30519, 44378, 44379, 44380, 44381, 171354, 176456, 179923, 180120, 182257, 182266, 182275, 182284, 204714, 204728, 204797, 204805, 204810, 204811 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165575, ["x"] = 0.288, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160211, ["x"] = 0.344667, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57993 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58007] = { ["id"] = 58007, ["name"] = "Eyes on the Problem", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "Our enemies rally at our gates. We cannot rely on daring air strikes to hold them at bay. Vashj has a plan to permanently bolster our defenses. With your help, it might actually succeed. Do what you can to assist her. She seems more... agreeable toward you than she is with me.", ["objectivesText"] = "Speak with Vashj and put her plan into action.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.506, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164619, ["x"] = 0.505, ["y"] = 0.2005 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.2005 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12876 } }, ["questGiverID"] = 161907, ["questType"] = "standard", ["sourceQuests"] = { 59555 }, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58008] = { ["id"] = 58008, ["name"] = "All Gassed Up", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "So, I was checkin' all these planes... and you are never gonna believe this, but none of them have any fuel in the tanks! Saw a few canisters scattered around nearby, surely some a' them have some gas left. Was gonna collect 'em myself, but these damned bugs came outta nowhere and started swarmin' the place. Too many here now to deal with on my own, think you'd be able to lend a hand?", ["objectivesText"] = "Collect 6 Fuel Canisters . Progress: Yo, you got them fuel cans yet?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173366 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57990 }, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58009] = { ["id"] = 58009, ["name"] = "To the Moon", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "Alright! It's time to high tail it outta here. We gotta get back to camp and tell Arik what's been going on out here as soon as possible. Head for the bomber and let's fuel 'er up. I'll letcha have the gunner seat, but I'm drivin', so let's try to blow up a few bugs on the way back!", ["objectivesText"] = "Remove the Aqir threat from Obelisk of the Moon.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 6710, 21100, 21746, 24103, 24104, 24105, 27686, 58924, 58925, 58926, 60928, 60929, 60930, 106175, 107307, 107312, 107317, 131274, 131504, 131597, 140847, 141943, 142054, 176112, 245258, 245624 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56576, 58008 }, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58010] = { ["id"] = 58010, ["name"] = "More Bits, More Bits!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58010 }, ["description"] = "We need more Aqir samples, $p. As many as you can get your hands on! I've made some fascinating discoveries already, but there's so much more to learn. With further study and a bit of good luck, perhaps we can slowly begin to uncover some of their weaknesses.", ["objectivesText"] = "Collect 16 Aqir Bits . Progress: Have you obtained any additional samples?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174356 }, ["rewardCurrencies"] = { { ["id"] = 1560, ["amount"] = 60 }, { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 403 }, { ["id"] = 1553, ["amount"] = 428 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58606 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58011] = { ["id"] = 58011, ["name"] = "Bug Bites", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58016, 58027 }, ["description"] = "Margrave Stradama eagerly awaits the completion of our latest potion! However, I seem to have misplaced my stockpile of venom sacs. How embarrassing! I have felt a touch out of sorts lately... Would you please do me a favor and fetch some more? We cannot continue our work without them!", ["objectivesText"] = "Collect 6 Bloated Venom Sacs . Progress: Now where did I put my venom sacs...", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59130 }, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58016] = { ["id"] = 58016, ["name"] = "Spores Galore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58011, 58027 }, ["description"] = "My brightest apprentice, you return to me at last! You worried me--you see, I heard the loudest clatter while working on one of my experiments... Before I knew it, I was here, and you'd disappeared! Wherever you went is no matter. You're back now, and we have much to do! Come, my apprentice--we must fetch our ingredients first. Can you smell the spores germinating around us? We should pull some up to use in our endeavors!", ["objectivesText"] = "Harvest 8 Stringy Spores.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59130 }, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58022] = { ["id"] = 58022, ["name"] = "Finish What He Started", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["description"] = "Finding Sha'lor is our main priority. But there is another opportunity. Take the Gormherd Branch that he dropped. I know he was tinkering with it so that it would work on wild gorm. Use it on the gorm in the burrows, and see if you can collect any of their gorm gris. Don't bother with the little ones; get the really potent stuff from the bigger gorm. Perhaps if we can collect enough, and find that silly sylvar, he will not rush horns-first into the burrows again.", ["objectivesText"] = "Use the Gormherd Branch to collect Wild Gorm Gris from gorm in the Dusty Burrows. Progress: Have you had any luck?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171099, ["x"] = 0.628, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158921, ["x"] = 0.626, ["y"] = 0.36 }, { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61051 }, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1824 },
[58023] = { ["id"] = 58023, ["name"] = "One Big Problem", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["description"] = "We must go after Master Sha'lor. Tirna Vaal needs him! And I... I... I will report to the droman. They must know that Sha'lor is in danger. Then, I will enter the burrows myself from the south and help you defeat it. For now, see what you can find. I refuse to believe that he is gone. That monster will know the fury of a vorkai.", ["objectivesText"] = "Hunt down the Gorm Matriarch . Progress: What's gotten into these gorm?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171099, ["x"] = 0.628, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61051 }, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1824 },
[58024] = { ["id"] = 58024, ["name"] = "Burrows Away", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["description"] = "<The ground has been freshly dug, and there are signs of more tunnels all over the place. Collapsing a few burrows would go a long way toward keeping Tirna Vaal safe from gorm infestation.>", ["objectivesText"] = "Collapse Gorm Burrows in the Dusty Burrows.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171195, ["x"] = 0.622, ["y"] = 0.3 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158921, ["x"] = 0.626, ["y"] = 0.36 }, { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61051 }, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1824 },
[58025] = { ["id"] = 58025, ["name"] = "Queen of the Underground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["description"] = "You tracked the massive gorm here to her den, and we've found Master Sha'lor. Perhaps not entirely unscathed, but he lives. That is enough. One last task remains. Let us end this.", ["objectivesText"] = "Slay the Gorm Matriarch . Progress: Tirna Vaal will not be safe with that monstrosity about.", ["rewardGold"] = 772200, ["rewardXP"] = 1770, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.605333, ["y"] = 0.331333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58023 }, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1824 },
[58026] = { ["id"] = 58026, ["name"] = "When a Gorm Eats a God", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["description"] = "There is nothing more we can do here. I will get Master Sha'lor safely back to Tirna Vaal. When you get there, report to the droman what we found here. If the gorm have started to eat the dead wildseeds, and are absorbing the power of the spirits within, we are all in serious danger.", ["objectivesText"] = "Report back to Droman Tashmur in Tirna Vaal.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 172953, 172955, 173268, 173534, 175663, 175664, 175665, 175666, 180543 }, ["rewardChoices"] = { 175665, 175663, 175664, 175666 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160155, ["x"] = 0.605333, ["y"] = 0.331333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.605333, ["y"] = 0.331333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58025 }, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58027] = { ["id"] = 58027, ["name"] = "Slime, Anyone?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58011, 58016 }, ["description"] = "While I know we're both eager to complete our potion, I believe the best lesson I can share with you is patience. Patience and slimes, of course! With the help of slimes, we'll have our laboratory back in working condition. It's just as I taught you: combine your ingredients in the cauldron. Mix until the viscosity is just right... Oh, listen to me--acting as if you've never concocted your own sentient being! Go on, my apprentice! The slimes are calling!", ["objectivesText"] = "Craft a Plagueborn Slime in Marileth's cauldron. Progress: Go on, now! You can do it!", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58011, 58016 }, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58031] = { ["id"] = 58031, ["name"] = "Applied Science", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58036, 58045, 59223, 59231, 60831 }, ["description"] = "<What appears to be an old journal sits on Marileth's table, now mangled and missing pages. The entries that are legible seem to have been written by Marileth when he was still sane, before the fall of his house. Perhaps if you find the journal's missing pages, you will gain more insight into what befell the House of Plagues.>", ["objectivesText"] = "Collect the lost pages of Marileth's journal from Plague-doused Remnants.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["x"] = 0.565, ["y"] = 0.572, ["mapID"] = 1536, ["objectID"] = 353645 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59130 }, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["startItems"] = { 174643 } },
[58036] = { ["id"] = 58036, ["name"] = "Hazardous Waste Collection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58031, 58045, 59223, 59231, 60831 }, ["description"] = "Ah, slimes: the dearest of friends and infinitely useful! They will help us craft our potion. But it seems our tools have been scattered around, doused in toxic refuse. Margrave Stradama would be so disappointed at my lack of respect for lab safety! Your slime can comb through the refuse, diluting the plague's harmful agents. Simply pull the cleaned equipment from the body of your slime! Slimes... what would we do without them?", ["objectivesText"] = "Collect 6 pieces of Laboratory Equipment . Progress: Has your slime been useful? I'm sure it has!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58027 }, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58037] = { ["id"] = 58037, ["name"] = "Part of the Pride", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["series"] = { 58184 }, ["description"] = "Pelodis insists that phalynx are superior to all autonomous beings, taking orders without fail. But where is the nuance? Where is the reward for your effort? Larions make fantastic companions, but you must build a relationship with them. Introduce yourself to my pride. You will see that each has a personality of their own.", ["objectivesText"] = "Introduce yourself to 5 Tamed Larions . Progress: Larions are free-thinking beings. They will decide whether you are accepted within the pride.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58184, 59674, 63068 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58038] = { ["id"] = 58038, ["name"] = "All Natural Chews", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "A huge part of larion care is providing for them and keeping them happy. Larions need to keep their teeth sharp and healthy, and for that they need to chew. If you do not give them proper things to chew on, they can get destructive. One of their favorite chew toys are the antlers from the cloudstriders in the nearby field. Please, collect some antlers for the pride to enjoy.", ["objectivesText"] = "Collect 5 Cloudstrider Antlers from Gilded Cloudstriders in the Golden Pasture. Progress: Antlers are great for keeping my pack's teeth sharp and clean.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58037 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58039] = { ["id"] = 58039, ["name"] = "Larion at Large", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Some larions are more particular about the people they bond with than others. Lentios is my companion, the larion I trust most with my life. I love the others as well, but he is a part of my soul. One of my pride, Andira , has posed a struggle for me to bond with. She ran off into the pastures once again, and I fear she's gotten into something she shouldn't have. Would you mind finding her and bringing her home?", ["objectivesText"] = "Find Andira in the Golden Pasture and return her to Nemea 's Retreat. Progress: Andira and I do not see eye to eye. I know she will be a loyal companion... but perhaps to somebody else.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702, 182653 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58037 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58040] = { ["id"] = 58040, ["name"] = "With Lance and Larion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Say what you want about phalynx, but Larion will always have one major advantage. Wings! A bonded larion will hunt alongside you whether you are on the ground or in the air. Take my javelin and Andira then go out into the fields to hunt the cloudfeathers there. You'll feel the boon of larion companionship firsthand!", ["objectivesText"] = "Kill 5 Cloudfeather Greatwing in Greatwing Roost.", ["rewardGold"] = 358020, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58038, 58039 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58041] = { ["id"] = 58041, ["name"] = "Providing for the Pack", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "Even beings of the Shadowlands need to eat. They may not do so quite like your world, but it is similar enough. The pride's favorite prey is the juvenile cloudfeathers found nearby. Prove to Andira that you are a contributing member of the pride by taking her out to hunt for their next meal.", ["objectivesText"] = "Collect 10 Cloudfeather Essence . Progress: Larions bond through hunting. Working together with Andira to collect food is vital to your relationship.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58038, 58039 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58042] = { ["id"] = 58042, ["name"] = "On Larion Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "As a flightless being, you will unfortunately never feel the joy of flying alongside your companion. However... you could still fly with Andira . It seems you have earned Andira 's trust more than I've seen her with anybody else. Would you like to try a flight course? Take wing with Andira , then fly through the rings. Don't stray off course or take too much time to get between rings or she will leave you behind!", ["objectivesText"] = "Mount Andira , then complete the flight course. Progress: I set up the flight course to train the larions to listen to aerial commands. They know where to go!", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173332, 173333, 173334, 173335, 173690, 173691, 173692, 173702 }, ["rewardChoices"] = { 173333, 173335, 173334, 173332 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58040, 58041 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58045] = { ["id"] = 58045, ["name"] = "Plague is Thicker Than Water", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58031, 58036, 59223, 59231, 60831 }, ["description"] = "Come closer, my apprentice... I have a mission of dire import! A necromancer came to our house recently, sent by the lich Margrave Sin'dane! He seemed so polite, always eager to lend a hand in my lady's most volatile creations. But I grew wise, my apprentice. The way he skulked around, prodding for our most sensitive experiments... He was trying to steal our slimes! I know it! You should admonish him quite harshly. Show that no harm will come to our friends!", ["objectivesText"] = "Kill Korrim the Cunning . Progress: Have you chided the defiler?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 173368, 173536, 173891, 175410, 175455, 175456, 175457, 175458, 180235, 180236, 180237, 180238, 180271 }, ["rewardChoices"] = { 175457, 175455, 175458, 175456 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58027 }, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58060] = { ["id"] = 58060, ["name"] = "The Night Market", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58060, 58062 }, ["description"] = "<Dracho motions to keep your voice down.> I need some assistance, I promise you will be paid handsomely. At the edge of The Banewood lies some ruins. These ruins are home to a marketplace run by some brokers. They won't let me back there. Let's just say that my goods were deemed to not be up to their authenticity metrics. But you... you're a Maw Walker! Bring them this package and exchange it for some Surberries from Ardenweald. Just don't say I sent you.", ["objectivesText"] = "Bring the Hastily Wrapped Package to Ta'ruca at The Night Market in Revendreth . Provided item:", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 173689 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160100, ["x"] = 0.526, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160091, ["x"] = 0.51, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1185, ["name"] = "The Night Market", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58062] = { ["id"] = 58062, ["name"] = "A Very Special Guest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58060, 58062 }, ["description"] = "Listen. It is obvious you are doing this deal on Dracho's behalf. I believe Ta'xera , the boss around here, would be very interested in striking a deal with someone of your talents. She resides in the manor at the top of the hill. I recommend you don't keep her waiting.", ["objectivesText"] = "Speak to Ta'xera at The Night Market.", ["rewardGold"] = 64350, ["rewardXP"] = 2040, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160091, ["x"] = 0.51, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160081, ["x"] = 0.524, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58060 }, ["questLines"] = { { ["id"] = 1185, ["name"] = "The Night Market", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58068] = { ["id"] = 58068, ["name"] = "...Even The Most Ridiculous Request!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "A fan of the competition, are you? Perhaps you would like to be more than a mere spectator? I will give you a small task... one that not only benefits me, but that also gives you a chance to meet some of the storied competitors here. As you can see, our three remaining houses have sent champions to attend the Contest of Conquest. Talk with them and attend to what needs they might have.", ["objectivesText"] = "See to the needs of the Promenade Champions. Progress: What now?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 62785 }, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58069] = { ["id"] = 58069, ["name"] = "Favor: The Venthyr Diaries", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58069 }, ["description"] = "This item will be of great interest to the brokers. Per your previous deal with The Night Market, you should bring it to Ta'xera . You will be fairly compensated.", ["objectivesText"] = "Bring The Venthyr Diaries to Ta'xera at The Night Market in Revendreth . Provided item:", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["rewardItems"] = { 173705, 184373, 184374 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160081, ["x"] = 0.524, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58062 }, ["startItems"] = { 173705 } },
