[58086] = { ["id"] = 58086, ["name"] = "The Master of Lies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58086, 59644 }, ["series"] = { 57876, 57877, 57878, 59644 }, ["description"] = "Once more unto the fangs of death himself, sword drawn, peace with oblivion made. Let us meet death together and bring him low. Be sure you are prepared for a sustained assault. For once we reveal ourselves, there will be no stopping. When you are ready, direct the Focal Mirror at the gates of Castle Nathria. Let us descend upon our burning enemies with ferocity and swiftness of action.", ["objectivesText"] = "Defeat Sire Denathrius .", ["rewardGold"] = 548280, ["rewardXP"] = 12250, ["rewardItems"] = { 175479, 175480, 175481, 175482, 175483, 175492, 175493, 175494 }, ["rewardChoices"] = { 175480, 175492, 175483, 175494, 175482, 175493, 175481, 175479 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 172673, ["x"] = 0.32, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165557, ["x"] = 0.502, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59644 }, ["questLines"] = { { ["id"] = 1038, ["name"] = "The Master of Lies", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 1038, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1038, ["questLineOrder"] = 31 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1038, ["questLineOrder"] = 31 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58087] = { ["id"] = 58087, ["name"] = "Destroying the Source", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Tidecaller Nezara is running the show. If we take her out, the remaining naga will break rank, but getting to her won't be easy. She's protected by a magical barrier that's drawing power from powercells nearby. If we can destroy the source, we can destroy Nezara.", ["objectivesText"] = "Destroy 3 Nazeshi Powercells within Dreadpearl Shallows.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 145980, ["x"] = 0.748, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 145980, ["x"] = 0.748, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 53899 }, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[58088] = { ["id"] = 58088, ["name"] = "Juicing Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "I've conceived a task befitting of your \"talents\". Have you heard of the House of Plague? Crafters of toxins and potions. They suffered a tragic accident--a true, true shame. Herein lies the problem: I have long used the work of the plague devisers to bolster my arena performance. Without a potion of their creation, I'd find the fight unnecessarily taxing. The brokers do have such potions, but they \"do not like my face.\" Could you obtain such a potion for me?", ["objectivesText"] = "Find someone at the Challenger's Promenade who has enhancement potions.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957, 229365 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159827, ["x"] = 0.538, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159833, ["x"] = 0.536, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58068 }, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58090] = { ["id"] = 58090, ["name"] = "Side Effects", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["series"] = { 58095 }, ["description"] = "Scrapper Minoire's use of enhancers creates unpredictable betting implications. It is quite unhealthy... for our profits! For a nominal fee, Au'larrynar can provide you with a \"special\" enhancer that Minoire will not be able to resist: a potion that turns the one who imbibes it into the ultimate combatant... and teaches them a lesson in restraint, as well. I cannot wait to see Minoire's next match in the arena!", ["objectivesText"] = "Deliver the potion to Scrapper Minoire. Progress: This is an unexpected turn of events.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159833, ["x"] = 0.536, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58088 }, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58092] = { ["id"] = 58092, ["name"] = "Halls of Atonement: Your Absolution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "The depravity outside of these halls is only a whisper of the true horrors being committed under the Lord Chamberlain 's guidance inside the Halls of Atonement. If you truly wish to curb this corruption, you must dethrone the imposter that you installed here. Atone for your own mistake. Kill the Lord Chamberlain , so that we may begin to restore permanent order to this place.", ["objectivesText"] = "Kill the Lord Chamberlain inside the Halls of Atonement.", ["rewardGold"] = 1029600, ["rewardXP"] = 2830, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002, 184717 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167332, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 57929 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58093] = { ["id"] = 58093, ["name"] = "Our Forgotten Purpose", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58093 }, ["series"] = { 57918, 57919 }, ["description"] = "I have no quarrel with you, Maw Walker. The Lord Chamberlain and his abhorrent followers have debased these halls with their perversions of the rituals. Abusing souls and destroying their potential for pathetic mockeries of power. The Accuser would never have allowed this. I have heard rumors that you may still be in contact with her. If so, please inform her of the situation here. She will bring these depraved dogs to heel.", ["objectivesText"] = "Meet the Accuser at Absolution Crypt.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160116, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58086 }, ["nextQuests"] = { 57919 } },
[58095] = { ["id"] = 58095, ["name"] = "Theater of Pain: Help Wanted", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12841, ["mapID"] = 1536, ["storyline"] = { 58095 }, ["series"] = { 58090 }, ["description"] = "Oh, bother--the Lich champion has withdrawn from the contest. Well, then... It appears we have an opening! Would anyone like to enter in her stead? Perhaps to increase the odds for their house? Anyone? Oh, <name>! So kind of you to volunteer. No better way to get experience than to just jump right in unprepared! Remember, we can't all be winners.", ["objectivesText"] = "Enter the Theater of Pain dungeon, and defeat the champions within.", ["rewardGold"] = 1158300, ["rewardXP"] = 12250, ["rewardItems"] = { 181646 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159689, ["x"] = 0.54, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12841 } }, ["questType"] = "dungeon", ["questLines"] = { { ["id"] = 1169, ["name"] = "Theater of Pain: Help Wanted", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58096] = { ["id"] = 58096, ["name"] = "Supplies from the Rajani", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58096 }, ["description"] = "The Rajani appreciates all the help you've given us. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", ["objectivesText"] = "Speak with Zhang Ku in Vale of Eternal Blossoms for your reward.", ["rewardItems"] = { 174483 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 2500 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 160711, ["x"] = 0.444, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2416, ["threshold"] = 10000 } } } },
[58097] = { ["id"] = 58097, ["name"] = "Supplies from the Uldum Accord", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58097 }, ["description"] = "The Uldum Accord appreciates all the help you've given us. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", ["objectivesText"] = "Speak with Provisioner Qorra in Uldum for your reward.", ["rewardItems"] = { 174484 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 2500 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160714, ["x"] = 0.55, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2418, ["threshold"] = 10000 } } } },
[58103] = { ["id"] = 58103, ["name"] = "Pride or Unit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "I hope that working with my phalynx has swayed you, <name>. Let us meet with Nemea . There you can decide whose way of life is superior, and which you would prefer to pursue.", ["objectivesText"] = "Meet with Pelodis and Nemea , then pick a side. Progress: Surely you must agree that the ease of phalynx companionship suits you.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702, 174281, 177040, 182652, 182653 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57937, 58042 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58104] = { ["id"] = 58104, ["name"] = "Show, Don't Tell", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 58157, 58158, 58159, 61554 }, ["description"] = "As a new champion of the Court, you'll need to be properly introduced to the rest of the Night Fae. And that calls for something big. Bold. Memorable. A demonstration of who you are and where you've come from. Something with... flair. Normally, we spend ages crafting a masterpiece presentation. But we don't have time for that! We'll just have to improvise. <Moonberry winks.> Commune with me so I can pick up the highlights! I'll make sure it's a show to remember!", ["objectivesText"] = "Commune with Lady Moonberry .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.495, ["y"] = 0.401, ["mapID"] = 1701, ["npcID"] = 161509 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questGiverID"] = 161509, ["questType"] = "standard", ["sourceQuests"] = { 61479 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58122] = { ["id"] = 58122, ["name"] = "For the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 35 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 58122, 58124 }, ["description"] = "What an adventure, <class>! There is so much to explore... so much to discover. These are such exciting times! We'll show our allies in the Horde the value of having some clever Vulpera around. Please meet with the ambassador at the Orgrimmar embassy. I'll meet you there, <name>!", ["objectivesText"] = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 37956, 37964, 37998, 38006, 38041, 38048, 38081, 38102, 38110, 57509, 57510, 57511, 57512, 65680, 65701, 65719, 65728, 66073, 94220, 111535, 111536, 111537, 111538, 111539, 111540, 111541, 111542, 116202, 118761, 118762, 118763, 118764, 118765, 131486, 131696, 131697, 151557, 155662, 157028, 157757, 157759, 161328, 165001, 165871, 166883, 167169, 168615, 168850, 169765, 174069, 174508, 223907, 241215 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 160452, ["x"] = 0.566, ["y"] = 0.577333 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.577333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1042, ["name"] = "Allies of the Horde", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[58124] = { ["id"] = 58124, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 35 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 58122, 58124 }, ["description"] = "Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.", ["objectivesText"] = "Talk to Chromie . Progress: This city is huge!", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 160452, ["x"] = 0.566, ["y"] = 0.577333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 58122 }, ["questLines"] = { { ["id"] = 1042, ["name"] = "Allies of the Horde", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
