[58146] = { ["id"] = 58146, ["name"] = "For the Alliance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 37 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 58146, 58147 }, ["description"] = "As High Tinker, and leader of both Gnomes and Mechagnomes, I am proud to welcome you to the Alliance! A world of adventure awaits you beyond the walls of Mechagon City. When you are ready, step on the teleporter. Ambassador Moorgard will be awaiting your arrival at the Stormwind Embassy. There will be many potential avenues of advancement available to you. Choose wisely, improve, and remember to share your data.", ["objectivesText"] = "Meet Ambassador Moorgard at the Stormwind Embassy. Progress: Welcome to Stormwind, <race>.", ["rewardGold"] = 31900, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 37500, 42792, 42805, 42817, 42830, 65618, 65625, 65639, 65642, 66073, 94219, 108908, 108909, 108910, 108912, 108913, 108914, 108918, 108919, 116202, 151557, 157022, 157756, 157758, 161329, 165010, 165872, 166883, 168615, 168850, 169764, 174068, 174507, 204616, 204617, 204618, 204619, 223907, 241215 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 159587, ["x"] = 0.7325, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 84, 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5405, ["name"] = "Allies of the Alliance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[58147] = { ["id"] = 58147, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 37 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 58146, 58147 }, ["description"] = "Welcome to Stormwind, <class>. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of the Mechagnomes is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, <name>!", ["objectivesText"] = "Find Chromie in Stormwind City. Progress: So, how does Stormwind suit you?", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 160600, ["x"] = 0.5988, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 58146 }, ["questLines"] = { { ["id"] = 5405, ["name"] = "Allies of the Alliance", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[58151] = { ["id"] = 58151, ["name"] = "Minions of N'Zoth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1530, ["storyline"] = { 58151 }, ["description"] = "The howling winds that surround us may some day be drowned out, masked by these increasingly dark, yet familiar whispers. Something must be done. Enter the darkness, <name>, and strike down the enemy.", ["objectivesText"] = "Defeat 20 minions of N'Zoth within the vision. Progress: The winds envelop us, comforting, calming... but beneath it all lurks a great, ever-present darkness.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169223, 174288 }, ["rewardCurrencies"] = { { ["id"] = 1719, ["amount"] = 50 }, { ["id"] = 1755, ["amount"] = 3000 }, { ["id"] = 1719, ["amount"] = 8 }, { ["id"] = 1719, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 160252, ["x"] = 0.842, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.842, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1527, 1530 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58155] = { ["id"] = 58155, ["name"] = "A Hand in the Dark", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58155 }, ["description"] = "Imagine being trapped in a world you didn't know existed--a reality unbeknownst to even yourself. Thoughts, fears, and dark desires cloud the mind, coupled with irresistible temptation. So many are lost to the darkness, unable to resist these temptations, but not all. Do what you can to preserve those that fight against the darkness. We mustn't allow them to fall.", ["objectivesText"] = "Rescue 8 souls from the vision. Progress: It is best not to linger in darkness.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169223, 174288 }, ["rewardCurrencies"] = { { ["id"] = 1719, ["amount"] = 30 }, { ["id"] = 1719, ["amount"] = 50 }, { ["id"] = 1755, ["amount"] = 1500 }, { ["id"] = 1755, ["amount"] = 3000 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58156] = { ["id"] = 58156, ["name"] = "Vanquishing the Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58156 }, ["description"] = "The darkness grows. The cycle continues. Do what you can to stay N'Zoth's efforts. If we do not stand against the corruption we may some day find ourselves drowning in darkness.", ["objectivesText"] = "Repel N'Zoth's corruption within the vision. Progress: We both know what must be done.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174288 }, ["rewardCurrencies"] = { { ["id"] = 1719, ["amount"] = 30 }, { ["id"] = 1755, ["amount"] = 1500 }, { ["id"] = 1755, ["amount"] = 3000 }, { ["id"] = 1719, ["amount"] = 8 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58157] = { ["id"] = 58157, ["name"] = "Break a Leg", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 58104, 58158, 58159, 61554 }, ["description"] = "The show is about to begin! You... that's what you're going to wear? Well, I suppose it works. For your grand introduction, we will re-enact recent victories and events that took place on Azzinoth. Er, Azeroth. That's where you're from, right? The Starlight Company has graciously volunteered to assist us in this production. We've recruited some special guests as well! Don't worry about the script. This is your story, after all! Just try not to get too much blood on stage. It's hard to clean.", ["objectivesText"] = "Reenact the Third Invasion of the Legion on Azeroth. Progress: Well, that wasn't... terrible.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58104 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58158] = { ["id"] = 58158, ["name"] = "The Fourth Wall, er, War", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 58104, 58157, 58159, 61554 }, ["description"] = "It's time for the next act of your theatrical introduction: the Grand Drama Of Azereth! Azeroth. Right. All these worlds are hard to tell apart. Help set the stage, then come back here. You'll need to play a few other characters before you appear as yourself again. Get a move on! We have a lot to cover!", ["objectivesText"] = "Set the Stage then help the reenactment of events after the Legion's fall. Progress: Come on, come on! We have a crowd to please!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58157 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58159] = { ["id"] = 58159, ["name"] = "What's My Motivation?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 58104, 58157, 58158, 61554 }, ["description"] = "Now for our finale! A thrilling performance of the most recent trials on Azathoth! < Featherlight checks his notes.> Azeroth. Whatever. It features an artificial god, a powerful magic ice princess, an infamous queen, and an eldritch abomination of unspeakable terror! Who doesn't love a good drama with a dash of existential horror? You're back to playing yourself, so just... do whatever heroes are supposed to do!", ["objectivesText"] = "Perform the final acts! Progress: Well! That was exciting.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180263 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160484, ["x"] = 0.406, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160467, ["x"] = 0.41, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58158 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58160] = { ["id"] = 58160, ["name"] = "For Queen and Grove!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["series"] = { 63006, 62883, 63101, 62884, 62697, 62886, 62693, 62890, 62902, 62891, 62903, 62892, 62904, 62893, 62905, 62882, 60287, 61391, 61355, 60289 }, ["description"] = "A stunning performance... in more ways than one. So much has transpired on Azeroth in my absence. But there was one dream I did not see portrayed onstage. I dreamt of Tyrande, engulfed in darkness, twisted by anger and a thirst for vengeance. I witnessed a forbidden ritual, the rise of a new Night Warrior, and a hunt that can end only in tragedy. That too must be real. Ysera shakes her head.> The Winter Queen awaits you in the Heart of the Forest. We had best be on our way.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 160500, ["x"] = 0.424, ["y"] = 0.452, ["mapID"] = 1565 } }, ["ends"] = { { ["npcID"] = 156634, ["x"] = 0.454, ["y"] = 0.656, ["mapID"] = 1565 }, { ["npcID"] = 156634, ["x"] = 0.506, ["y"] = 0.314, ["mapID"] = 1565 } }, ["coords"] = { ["x"] = 0.424, ["y"] = 0.452, ["source"] = "quest_giver", ["mapID"] = 1565 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["sourceQuests"] = { 58159 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 } } },
[58161] = { ["id"] = 58161, ["name"] = "Forest Disappearances", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "A moment of your time, friend? A short while ago a sylvar named Partik came seeking the aid of our grove. He said his village was under attack by the gorm and was in danger of crumbling away altogether. I told him we could not spare any soldiers, but their people were welcome to take refuge with us. However, it has been some time since he left and I have not seen or heard anyone from that region since. Can you go investigate? He came from the northeast.", ["objectivesText"] = "Find Partik .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 155876, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160440, ["x"] = 0.644, ["y"] = 0.352 }, { ["mapID"] = 1565, ["npcID"] = 169153, ["x"] = 0.644, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60519 }, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58162] = { ["id"] = 58162, ["name"] = "Mysterious Masks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "The village, my friends, gone. They are no more. I came back from the nearby grove to find them... like this. Even Lavrash, my best friend! He came at me with only violence in his heart. They are all wearing these masks now, and they are not themselves anymore. Please, deliver them from this fate. Bring me their masks and perhaps we can decipher this mystery.", ["objectivesText"] = "Collect 15 Featureless Masks . Progress: For so many to fall, I did not think I was gone that long....", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 155876, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58161 }, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58163] = { ["id"] = 58163, ["name"] = "A Desperate Solution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "<A well-made, if well-worn, journal catches your eye. Thumbing through the pages, it is clear that this journal once belonged to someone prominent from this group of night fae. The last few pages are torn out of the book. Perhaps if the rest of the pages were located then Partik could help decipher what happened here.>", ["objectivesText"] = "Find the missing journal pages. Progress: What's that you've got there?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 155876, 173798, 173800, 173872, 173873, 177878, 183851 }, ["rewardChoices"] = { 183851 }, ["starts"] = { { ["x"] = 0.722, ["y"] = 0.339, ["mapID"] = 1565, ["objectID"] = 349515 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58161 }, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58164] = { ["id"] = 58164, ["name"] = "Cult of Personality", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "Some of my people are still alive! We must rescue them! The prisoners are kept in cages throughout the ridge, waiting for this horrible fate to befall them. Please, set them free. We cannot let what happened to Lavrash happen to them!", ["objectivesText"] = "Rescue 8 trapped night fae.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 155876, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58161 }, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58165] = { ["id"] = 58165, ["name"] = "Cut the Roots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "It's just as I feared, friend. The entire village is turned, just like Lavrash. Lewor would have transformed the other elders as soon as possible. They are all strong in their own right. Brave Fiona, clever Bitterfly .... It pains me to say this, but they must be destroyed. For the good of Ardenweald and the forest, slay our former leaders before they can infect the rest of the land!", ["objectivesText"] = "Slay Bitterfly , Fiona Bleakthorn , and Wildtwister Lewor. Progress: If they fell, then what hope do we have?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 155876, 173732, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59802 }, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58166] = { ["id"] = 58166, ["name"] = "Unknown Assailants", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "This must be the stone he found. I do not recognize the mark. You should bring this to the nearby droman. They are wise and retain much of the knowledge of the forests and the realms beyond. They will know what to do.", ["objectivesText"] = "Bring the Strange Runestone to Droman Tashmur in Tirna Vaal. Provided item:", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 155876, 173732, 173800, 173872, 173873, 175675, 175676, 175677, 175678, 177878 }, ["rewardChoices"] = { 175677, 175676, 175675, 175678 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58165, 59801 }, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58167] = { ["id"] = 58167, ["name"] = "Preventative Measures", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58167 }, ["description"] = "Waves of darkness continue their assault on the shores of our world. I am afraid the waters at our feet may soon wash over us. Perhaps it is time for a different approach. Make your way into the twisted realm and seek out their dark portals. If we are able to slow their advance it might just buy us the time needed to expose a fatal weakness.", ["objectivesText"] = "Destroy 3 Void Portals within the vision. Progress: Darkness lurks beneath the waters.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169223, 169293, 173363, 174288 }, ["rewardCurrencies"] = { { ["id"] = 1719, ["amount"] = 30 }, { ["id"] = 1719, ["amount"] = 50 }, { ["id"] = 1755, ["amount"] = 1500 }, { ["id"] = 1755, ["amount"] = 3000 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58168] = { ["id"] = 58168, ["name"] = "A Dark, Glaring Reality", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58168 }, ["description"] = "Their eyes are upon us, <name>, watching every move from the shadows. It is no wonder our efforts thus far have felt... lacking. The fault is by no means your own. We should have suspected this was the case long ago. If we are to continue our efforts with meaningful expectations we must go undetected. Our old friend has offered an elixir to aide in exposing our enemy. While there may be a few... unknown side effects, the result provides the imbiber true sight in the darkness.", ["objectivesText"] = "Defeat 6 Darkglare Watchers within the vision. Progress: Seeing things more clearly?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173810, 174288 }, ["rewardCurrencies"] = { { ["id"] = 1719, ["amount"] = 30 }, { ["id"] = 1755, ["amount"] = 1500 }, { ["id"] = 1719, ["amount"] = 50 }, { ["id"] = 1755, ["amount"] = 2000 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58174] = { ["id"] = 58174, ["name"] = "All An Aspirant Can Do", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["description"] = "I think we can agree that such a reply feels... somewhat hollow. I choose to take faith that we have done all we can. All of us. I do not know what comes next, but perhaps the path will reveal itself. In the meantime, Pelagos and I will return to Aspirant's Rest for a moment of respite. We will meet you there, though there is no need to hurry.", ["objectivesText"] = "Return to Aspirant's Rest.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158471, ["x"] = 0.482, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5335, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57715, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 26, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58175] = { ["id"] = 58175, ["name"] = "The Eternal Forge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["description"] = "The Forgelite Prime has taken up the mantle of building our new Crest of Ascension. No ordinary tools or materials will do. He will require Phaestus, Genesis of Aeons, Hammer of the First Forgelite. It sits at the shrine to the First Forgelite in the Eternal Forge. The Forsworn have taken over this forge to create their own endless centurion army. You must meet Mikanikos at the forge, push back the Forsworn, and retrieve Phaestus for our own uses.", ["objectivesText"] = "Meet Mikanikos at the Eternal Forge.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 109076, 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58798 }, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58176] = { ["id"] = 58176, ["name"] = "Stewards of a Feather", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["description"] = "You! Maw Walker! The forge was bustling. Many forgehands, on task! Then Forsworn came. Some followed their demands, turned to their side. But not all! Yes, rescue forgehands so they can aid us. Work to be done!", ["objectivesText"] = "Free 5 Captured Forgehands . Progress: I tried to save, but am no hero. Can only try to organize chaos.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160648, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160648, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58175 }, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58177] = { ["id"] = 58177, ["name"] = "Refining Ego", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["description"] = "I will locate Phaestus. In the meantime, task for you! The Forsworn use my forge to make their centurion army. Their vile intentions warp the metals we use! Destroy their centurions, take their parts. Smelt them down in the forge to purify the metals, then return to me. I need much metal for my plan.", ["objectivesText"] = "Collect 8 Purified Metal by collecting Tainted Centurion Components from centurion units and smelting them down at the Eternal Forge. Progress: I keep my resources here. The Forsworn stole from me! I cannot let this stand.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173879, 173880, 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58175 }, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58178] = { ["id"] = 58178, ["name"] = "A Partner for Eternity", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["series"] = { 58180, 58182, 58183 }, ["description"] = "Before returning to the Hold, one more thing to do. Defeat the Forsworn and their centurion army! This goliath here can help with just that. My finest creation yet! I need an extra pair of hands. Yours will do.", ["objectivesText"] = "Help Mikanikos finish his finest creation. Progress: Trust he is no ordinary goliath. An extension of my hand itself!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 180763 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58180 }, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58179] = { ["id"] = 58179, ["name"] = "Instruments of Perfection", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["description"] = "Mikanikos is no ordinary steward. He is wise! Talented! The smartest of us all! Also very particular! He cannot work without his tools. The Forsworn scattered them around the forge! You need to rebuild Crest? Retrieve his tools!", ["objectivesText"] = "Collect Mikanikos 's Soulsteel Clamps , Sparkling Driftglobe Core , and Gracepetal Incense Burner . Progress: I cannot work in these conditions.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173882, 173909, 173910, 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160648, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58175 }, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58180] = { ["id"] = 58180, ["name"] = "Phaestus, Genesis of Aeons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["series"] = { 58178, 58182, 58183 }, ["description"] = "Sika reports the Forsworn are widespread. They not only took over production, but the rise as well! They organize their armies from the cliffs, send word back to their leaders. They've ransacked our shrine to the First Forgelite and took her hammer. My hammer! Defeat their commander, retrieve Phaestus. You must go now!", ["objectivesText"] = "Collect Phaestus, Genesis of Aeons from Overseer Atticus. Progress: Without Phaestus, we cannot work on the Crest.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174061, 174296, 177057, 178160, 179947, 180763 }, ["rewardChoices"] = { 178160, 177057, 179947, 174296 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58176, 58177, 58179 }, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58181] = { ["id"] = 58181, ["name"] = "Building the Base", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["description"] = "The Crest is almost complete. I give you the honor of the final touch. You have done much. Please, take Phaestus and give the final blow!", ["objectivesText"] = "Complete the Crest of Ascension. Progress: Please care. Phaestus is older than you could dream!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 180763 }, ["rewardChoices"] = { 180763 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58183 }, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58182] = { ["id"] = 58182, ["name"] = "Dismantling the Opposition", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58175, 58176, 58177, 58178, 58179, 58180, 58181, 58182, 58183 }, ["series"] = { 58178, 58180, 58183 }, ["description"] = "The Forsworn mobilize! We cannot allow them to march. Attune to Bron, share your power with him. Between the three of us, we shall destroy this new centurion army!", ["objectivesText"] = "Ride Bron, then defeat 30 Forsworn forces and dismantle 2 Colossus in the Eternal Forge. Progress: Bron was not meant as a tool of destruction, but will excel at it with you!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180763 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58178 }, ["questLines"] = { { ["id"] = 1091, ["name"] = "Phaestus, Genesis of Aeons", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1091, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
