[58184] = { ["id"] = 58184, ["name"] = "Antiquated Methodology", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["series"] = { 58037 }, ["description"] = "You possess the correct mindset for retraining a phalynx. I believe you could find great success here. Before you commit, I implore you to go across the hill and introduce yourself to my rival, Nemea . She believes that her unreasonable, free-willed larions are better partners than my perfect phalynx. Experience her lifestyle so that you may know how much greater my work is.", ["objectivesText"] = "Talk to Nemea at Nemea 's Retreat.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5565, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57937 }, ["nextQuests"] = { 58037 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58185] = { ["id"] = 58185, ["name"] = "Success Without Soul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["series"] = { 57931 }, ["description"] = "The larions seem to truly enjoy your company, Andira most of all. I hope you've come to understand and appreciate the nuance of working with a beast with free will. Now you must spend time with Pelodis , down the hill. His phalynx may be effective, but working with them only brings hollow satisfaction. I am sure working with the phalynx will only strengthen your appreciation of larions.", ["objectivesText"] = "Talk to Pelodis at Forgefire Outpost.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173269, 173307, 173690, 173691, 173692, 173702 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58042 }, ["nextQuests"] = { 57931, 57932 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
