[58208] = { ["id"] = 58208, ["name"] = "Brace for Impact", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1156, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "That's it for warming up. You and the other new recruits are a promising bunch, I'll tell you that much. Hold on... what's that sound? I think something big is headed our way!", ["objectivesText"] = "Find Lady Jaina Proudmoore inside the ship.", ["rewardGold"] = 140, ["rewardXP"] = 25, ["starts"] = { { ["npcID"] = 160664 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 160664, ["questType"] = "standard", ["sourceQuests"] = { 58209 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1954, ["db2PoiUiMapID"] = 1156 },
[58209] = { ["id"] = 58209, ["name"] = "Stand Your Ground", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1156, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "I hope this rain isn't a bad omen... this is supposed to be a simple rescue mission. You'll be sparring with me today. We have to make sure you can handle yourself once we make landfall. Let's see what you've got!", ["objectivesText"] = "Spar with Private Cole . Progress: Having trouble? Happens to the best of us. Just stay calm, select your target, and use one of your abilities on it. Make sure your target is in front of you. We don't want another incident like when Bjorn tried to throw an axe over his shoulder.", ["rewardGold"] = 120, ["rewardXP"] = 200, ["starts"] = { { ["npcID"] = 160664 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 160664, ["questType"] = "standard", ["sourceQuests"] = { 56775 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1070, ["name"] = "The Missing Expedition", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5366, ["name"] = "The Missing Expedition", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5366, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1954, ["db2PoiUiMapID"] = 1156 },
[58211] = { ["id"] = 58211, ["name"] = "Pumped Up", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58211 }, ["description"] = "When this necropolis collapsed, plenty of its parts got submerged in the riverbed flowing just outside. I hope you're really dedicated to fixing this place, because we're gonna dredge those parts back up! Take this pump. If you find any places bubbling in that sludge, that's a good sign parts will be there! Just be careful with whatever you pull up! You could face some resistance.", ["objectivesText"] = "Collect 15 Salvaged Gear by using the Sludge Pump near bubbling sludge. Progress: Have you recovered anything useful?", ["rewardGold"] = 238680, ["rewardItems"] = { 173881, 173892, 181501, 181507, 181625, 181638, 181645, 181646, 181647, 181648, 181649, 181650, 181652, 181653, 181654, 181656, 181657, 181659, 181675, 181676, 181677, 181681, 181689, 184305, 184772, 184773, 184774, 184775, 184776 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[58214] = { ["id"] = 58214, ["name"] = "Urgent Care", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 84, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["series"] = { 57486, 57487 }, ["description"] = "Excellent timing, <name>. Kelsey Steelspark has been sending communications to the capital cities looking for aid. Mekkatorque's condition is quite dire and time is of the essence. Hurry to Boralus Harbor, she will be watching for you.", ["objectivesText"] = "Find Kelsey Steelspark in Boralus Harbor.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 158075 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 126332, ["x"] = 0.5235, ["y"] = 0.1355 }, { ["mapID"] = 1462, ["npcID"] = 149816, ["x"] = 0.72, ["y"] = 0.3495 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 160101, ["x"] = 0.73, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.5235, ["y"] = 0.1355 }, ["mapCandidates"] = { ["npc"] = { 84, 1161, 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["sourceQuests"] = { 50239 }, ["nextQuests"] = { 57486 }, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161 },
[58221] = { ["id"] = 58221, ["name"] = "Gettin' Even", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58221 }, ["objectivesText"] = "Bonefused constructs slain", ["rewardXP"] = 8165, ["rewardItems"] = { 184576 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Bonefused constructs slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 158971, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58229] = { ["id"] = 58229, ["name"] = "A Rallying Cry", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58229 }, ["description"] = "Our lands have been infested by the minions of the Old Gods. They strike at every front, even assailing the very minds of our soldiers. Our forces cannot handle this for long. We must strike a decisive blow to try to salvage some of their morale. Find the biggest, slimiest, tentacle-faced monstrosities that you can and bring them down. My men will rally to your example.", ["objectivesText"] = "Kill 3 rare minions of N'Zoth in Uldum .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 169303, 174478, 175140, 175142 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 301 }, { ["id"] = 1553, ["amount"] = 315 }, { ["id"] = 1553, ["amount"] = 318 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58230] = { ["id"] = 58230, ["name"] = "Blind the Eyes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58230 }, ["description"] = "Strange forces have been interfering with my visions of late. The ever-watching eyes pierce through the veil, shattering my clairvoyance. The eyes of our enemy peer into our very souls and pierce our minds. We must rip them out, if we truly wish to be rid of the curse on this land.", ["objectivesText"] = "Kill 6 Foul Observers in the Akhenet Fields in Uldum . Progress: Is it done?", ["rewardGold"] = 303800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 305 }, { ["id"] = 1553, ["amount"] = 335 }, { ["id"] = 1553, ["amount"] = 343 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58231] = { ["id"] = 58231, ["name"] = "Wisdom From Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58231 }, ["description"] = "In my visions I hear... voices... Their words are nonsense, but over time patterns arise. I believe there is something important behind what these voices say, but I have yet to decipher a word. We will need to learn from the source. Find any writings you can among the cultists who travel with these dark creatures. Their ramblings may be the key to understanding the message beneath this madness.", ["objectivesText"] = "Collect 10 Maddened Writings from Black Empire Cultists in Uldum . Progress: Have you found the writings?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173954 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 469 }, { ["id"] = 1560, ["amount"] = 60 }, { ["id"] = 1560, ["amount"] = 65 }, { ["id"] = 1755, ["amount"] = 325 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58232] = { ["id"] = 58232, ["name"] = "Order Among Chaos", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58232 }, ["description"] = "It has been a long time since the tol'vir have squared off against the forces of an Old God, so our tactical knowledge of their forces is limited. However, one tenet of combat always holds true -- striking down those that issue the orders will weaken the foe much greater than the rank and file. I have observed that the larger faceless minions act as commanders of the Old Gods' forces. Silence them, and perhaps we can sow a different kind of chaos in their ranks.", ["objectivesText"] = "Kill 6 faceless minions of N'Zoth in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 301 }, { ["id"] = 1553, ["amount"] = 314 }, { ["id"] = 1553, ["amount"] = 415 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "group", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58233] = { ["id"] = 58233, ["name"] = "Twisted Corruptors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58233 }, ["description"] = "While the fleshbeasts that accompany the invading forces appear to be no more than a nuisance, they carry within themselves a deep connection to the corrupting powers of the Old Gods. Like a pestilence, they spread the N'Zoth's corruption wherever they tread, slowly twisting the very land to their form. They must be eradicated.", ["objectivesText"] = "Kill 10 fleshbeasts in Uldum .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 307 }, { ["id"] = 1553, ["amount"] = 310 }, { ["id"] = 1553, ["amount"] = 334 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58234] = { ["id"] = 58234, ["name"] = "Questionable Sourcing", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58234 }, ["description"] = "My clairvoyance provides a great strategic asset to the people of Ramkahen. However, the potency of my visions of late has proven taxing to my health. I have devised a tonic that may serve to dull the harm these visions cause, but it will require the coalesced essence of the Old Gods' corruption. If you could retrieve some samples of this for me, it could prove invaluable in our efforts.", ["objectivesText"] = "Collect 8 Coalesced Corruption from slimes in Uldum . Progress: Have you acquired the reagent?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 173956 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 311 }, { ["id"] = 1553, ["amount"] = 317 }, { ["id"] = 1553, ["amount"] = 321 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58235] = { ["id"] = 58235, ["name"] = "Anchors of the Black Empire", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58235 }, ["description"] = "This invasion struck us without warning, with structures reminiscent of the Black Empire materializing out of nothing, pouring out the forces of the Old Gods. We have no idea how they came to be or where they came from. However, whenever a new structure appears, it is preceded by malefic obelisks. We believe these obelisks act as anchors to usher in more of the Old Gods' forces. If we truly wish to stem the tide of this invasion, we must destroy the obelisks.", ["objectivesText"] = "Destroy 6 Black Empire Obelisks in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 303 }, { ["id"] = 1553, ["amount"] = 377 }, { ["id"] = 1553, ["amount"] = 382 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58236] = { ["id"] = 58236, ["name"] = "Symbolic Destruction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58236 }, ["description"] = "The cultists that follow this dark legion befoul our lands with symbols of the tyrants they follow. Their mindless followers flock to these banners, worshipping them as unholy idols. Burn them down, and cleanse their taint from our lands.", ["objectivesText"] = "Destroy 6 Banners of the Black Empire in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 328 }, { ["id"] = 1553, ["amount"] = 345 }, { ["id"] = 1553, ["amount"] = 361 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58237] = { ["id"] = 58237, ["name"] = "Cleansing Uldum", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58237 }, ["description"] = "Every moment that N'Zoth's forces remain in Uldum , his corruption seeps further into the land itself. Even if we were to drive back his minions, the damage he has done to Uldum may be irreversible. We must seek out his corruption where it festers and eliminate it.", ["objectivesText"] = "Destroy 6 Corruption Tumors in Uldum . Progress: We must put a stop to N'Zoth's Corruption.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1560, ["amount"] = 60 }, { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 300 }, { ["id"] = 1553, ["amount"] = 305 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58238] = { ["id"] = 58238, ["name"] = "Lost and Tormented", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58238 }, ["description"] = "Our citizens here in Ramkahen have managed to escape the brunt of N'Zoth's assault. Our brothers in the Lost City were not so fortunate. Those not immediately slain have been held captive only to be tortured by N'Zoth's minions. I know that you will be taking the fight to N'Zoth's forces. If you can free our allies as well, Ramkahen will be in your debt.", ["objectivesText"] = "Free 6 Ramkahen Citizens from Torment Cells within the Lost City of Tol'vir in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 326 }, { ["id"] = 1553, ["amount"] = 329 }, { ["id"] = 1553, ["amount"] = 339 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58239] = { ["id"] = 58239, ["name"] = "Lessons in Brigandry", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58239 }, ["description"] = "The Wastewanders have spent many generations as brigands, whether on land or sea. Though we have decided to hang up that life for a chance at a more peaceful existence, we have not forgotten the lessons we've learned in those days. One such lesson I feel is particularly relevant now -- when faced with a superior opponent, it often helps to use their weapons against them. Find their hidden caches and take whatever you can carry. You may just find something that can turn the tide of this battle.", ["objectivesText"] = "Loot 3 Black Empire Caches in Uldum . Progress: Found anything worthwhile?", ["rewardGold"] = 303800, ["rewardXP"] = 6815, ["rewardItems"] = { 174758, 174768 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 302 }, { ["id"] = 1553, ["amount"] = 310 }, { ["id"] = 1553, ["amount"] = 317 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160957, ["x"] = 0.546, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58260] = { ["id"] = 58260, ["name"] = "Queens And Future Kings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58260 }, ["description"] = "A swarm of marrowbore queens have been laying eggs atop the ruins of our house. We may be able to use this to our advantage. With Twigin's help, eliminate the queens and recover larvae from the eggs. I have a plan for the larvae that may allow us to use the marrowbore to our advantage.", ["objectivesText"] = "Slay 1 marrowbore queens , and collect 5 marrowbore larvae. Progress: It's dirty work, but we need those larvae.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173942, 181501, 181502, 181503, 181507, 181625, 181626, 181645, 181647, 181649, 181650, 181652, 181653, 181654, 181661, 181662, 181663, 181679, 181680, 181682, 181694, 184194, 184305, 184772, 184773, 184774, 184775, 184776 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[58264] = { ["id"] = 58264, ["name"] = "Wake Up, Get Up, Get Out There", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58264, 58265, 58266, 58267 }, ["description"] = "They need your help! Not all of the faeries have been turned yet. Some remain prisoner, but they have these masks on their faces.... You've got to help them! I'm not strong enough to pry off the masks, but you could! You could stop the guards from getting us too!", ["objectivesText"] = "Aid 8 subdued faeries.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174078 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160749, ["x"] = 0.535, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160749, ["x"] = 0.535, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 160749, ["questType"] = "standard", ["sourceQuests"] = { 58265 }, ["questLines"] = { { ["id"] = 1165, ["name"] = "Wicked Plan", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58265] = { ["id"] = 58265, ["name"] = "Blooming Villains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58264, 58265, 58266, 58267 }, ["description"] = "Something stinks, traveler. The air to the west is rotten with malice. Shimmerbough has long been a peaceful way station along the Path of Rebirth. The faeries there delight in revelry and celebration. But now their glade has fallen silent. Scouts bring reports of the strange masked night fae. I know little other than that they are a threat. For the sake of Ardenweald , they must be eliminated. Slay any you encounter.", ["objectivesText"] = "Slay 15 masked night fae in Shimmerbough.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174078 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160929, ["x"] = 0.603, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160929, ["x"] = 0.603, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.603, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60905 }, ["questLines"] = { { ["id"] = 1165, ["name"] = "Wicked Plan", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58266] = { ["id"] = 58266, ["name"] = "Break It Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58264, 58265, 58266, 58267 }, ["description"] = "I've seen the ritual. It's... terrifying. But the altars seem to be the key. If only I had my pyrotechnic powder, I could blast them to bits! < Primrose is silent for a moment, then takes a deep breath.> If you could get the powder and guard me, we could blow up those altars. I stashed as much as I could in our dwellings. They don't seem to care any more. You don't have wings, but a pinch of faerie dust should work for a short time. Let's do this before I change my mind!", ["objectivesText"] = "Use Primrose's Pyrotechnic Powder to destroy 5 Ritual Altars.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 31312, 31313, 31314, 31315, 33226, 142054, 174042, 174078 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160749, ["x"] = 0.535, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160749, ["x"] = 0.535, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 160749, ["questType"] = "standard", ["sourceQuests"] = { 58265 }, ["questLines"] = { { ["id"] = 1165, ["name"] = "Wicked Plan", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58267] = { ["id"] = 58267, ["name"] = "Beneath the Mask", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58264, 58265, 58266, 58267 }, ["description"] = "It's time to end this. When I first hid, I saw a dark shape on the northeast platform. I think that's their leader. Now that they can't perform any more rituals, we should be able to scare them off. <Primrose pauses for a moment.> I... I just wanted to say thank you. I never could have done this without your help. Now, let's drive out this enemy and retake the village!", ["objectivesText"] = "Confront the leader of the possessed fae in Shimmerbough.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174078, 175712 }, ["rewardChoices"] = { 175712 }, ["starts"] = { { ["npcID"] = 160757 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160929, ["x"] = 0.603, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.603, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questGiverID"] = 160757, ["questType"] = "standard", ["sourceQuests"] = { 58264, 58266 }, ["questLines"] = { { ["id"] = 1165, ["name"] = "Wicked Plan", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58268] = { ["id"] = 58268, ["name"] = "Take the High Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "The commander of the constructs, General Alver, is a master tactician. A frontal assault has no chance of victory against him. It will be a bloodbath. His forces have flanked us and secured the high ground. From that position, he can rain destruction upon us unopposed. We will take the ridge from him before that can happen.", ["objectivesText"] = "Destroy the three enemy positions.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 169359, ["x"] = 0.394, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 169226, ["x"] = 0.394, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57912 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58272] = { ["id"] = 58272, ["name"] = "Words Have Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58272 }, ["series"] = { 56978 }, ["description"] = "The Stoneborn Rebels have left behind recruitment pamphlets. Recovering these for the venthyr may earn some much needed favor.", ["objectivesText"] = "Collect 9 Rebellion Pamphlets. Progress: Uncouth and vile documents, but written in a rather elegant hand. The Prince always had better penmanship than sense.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 173945, 177665, 183874, 183875 }, ["starts"] = { { ["x"] = 0.677, ["y"] = 0.676, ["mapID"] = 1525, ["objectID"] = 352490 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 }, { ["mapID"] = 1525, ["npcID"] = 156291, ["x"] = 0.632, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6764, ["y"] = 0.7036 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 56942 }, ["questLines"] = { { ["id"] = 1177, ["name"] = "Words Have Power", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58273] = { ["id"] = 58273, ["name"] = "Servant of N'Zoth", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 58273 }, ["description"] = "... I have watched you... I have felt your bloodlust. But you serve false prophets... the Horde is an illusion... I am a god! Prove to me you are worthy of my gift... kill those who are to betray you... Kill... the Horde! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(58273)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(58273))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Use the N'lyeth, Sliver of N'zoth to change your faction from Horde to become devoted to N'Zoth. Then slay 10 Horde players without dying.", ["rewardItems"] = { 174020, 175246 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[58274] = { ["id"] = 58274, ["name"] = "Servant of N'Zoth", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 58274 }, ["description"] = "... I have watched you... I have felt your bloodlust. But you serve false prophets... the Alliance is an illusion... I am a god! Prove to me you are worthy of my gift... kill those who are to betray you... Kill... the Alliance! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(58274)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(58274))\");", ["objectivesText"] = "Use the N'lyeth, Sliver of N'zoth to change your faction from Alliance to become devoted to N'Zoth. Then slay 10 Alliance players without dying.", ["rewardItems"] = { 174020, 175246 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[58277] = { ["id"] = 58277, ["name"] = "Dark Deceivers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58277 }, ["description"] = "The Old Gods have many faceless minions at their disposal, but none so deceiving as the ones they call k'thir. Though not nearly as imposing as their brethren, the k'thir manipulate in the shadows, bending the wills of men and even reality itself. We must not allow their machinations to go unchecked.", ["objectivesText"] = "Kill 8 K'thir minions in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 303 }, { ["id"] = 1553, ["amount"] = 330 }, { ["id"] = 1553, ["amount"] = 338 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58279] = { ["id"] = 58279, ["name"] = "Quartermaster's Bounty", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 58279 }, ["objectivesText"] = "Progress: To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", ["rewardItems"] = { 172519 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143560, ["x"] = 0.563, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143555, ["x"] = 0.515, ["y"] = 0.582 }, { ["mapID"] = 1161, ["npcID"] = 143560, ["x"] = 0.563, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[58281] = { ["id"] = 58281, ["name"] = "Ancient Armaments", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58281 }, ["description"] = "Fighting a war on several fronts has taken its toll on our supplies. Our blacksmiths cannot repair and replace our soldiers' armor quickly enough, which is leaving us ill-equipped to face so many foes. Though the Amathet's armor is ancient, it is titan-forged and formidable. If we were able to salvage any, it could prove very useful to our defensive efforts. Can you help?", ["objectivesText"] = "Collect 10 pieces of Amathet Armor from armored Amathet tol'vir in Uldum . Progress: Have you returned with the armor?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173985 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 327 }, { ["id"] = 1553, ["amount"] = 332 }, { ["id"] = 1553, ["amount"] = 350 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58282] = { ["id"] = 58282, ["name"] = "Down From the Sky", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58282 }, ["description"] = "The archers of Ramkahen are highly skilled, but the bows of the Amathet have the advantage of range. This makes our incursions into their territory highly dangerous. You have a knack for fighting behind enemy lines. If you could thin out their ranks, it could provide us an opportunity to push their lines back for once. Will you help?", ["objectivesText"] = "Kill 8 Amathet Bowmen in Uldum .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1560, ["amount"] = 60 }, { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 300 }, { ["id"] = 1553, ["amount"] = 301 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58283] = { ["id"] = 58283, ["name"] = "Blind Leading the Blind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58283 }, ["description"] = "The Sun Priests are an ancient order for the tol'vir who have walked among all of the tribes. Those that follow the Amathet, however, have twisted our beliefs and weaponized them to justify their crusade against Ramkahen. Their soldiers follow them blindly, never questioning. They must be stopped.", ["objectivesText"] = "Kill 8 Amathet priests in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 302 }, { ["id"] = 1553, ["amount"] = 317 }, { ["id"] = 1553, ["amount"] = 321 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58284] = { ["id"] = 58284, ["name"] = "Writs of the Sun King", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58284 }, ["description"] = "Very little is known about the Sun King that leads the Amathet. Our observations suggest that those closest to him are the \"Suntouched,\" a unique caste of solar magic practitioners. I would like very much to learn more about this Sun King but, unlike some members of the Explorers' League, I'm not willing to risk the lives of my researchers to do so. You seem to be able to hold your own, though. If you happen upon any records about the Sun King, I'd gladly take them off your hands.", ["objectivesText"] = "Collect 6 Writs of the Sun King from Suntouched Amathet in Uldum . Progress: Have you found anything interesting?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173986 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 317 }, { ["id"] = 1553, ["amount"] = 359 }, { ["id"] = 1553, ["amount"] = 493 }, { ["id"] = 1560, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58285] = { ["id"] = 58285, ["name"] = "Unearthed Artifacts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58285 }, ["description"] = "Ever since the Amathet came out of their tombs, they've been busy unearthing titan relics from the surrounding areas. I'm not sure what they intend to do with them or if they're just hoarding it so we can't have them. Sufficed to say the Explorers' League would love to study some of what they found! Of course, we can't get anywhere close to them without the Amathet trying to stick an axe in us, but that's not a problem for you, is it? Care to help?", ["objectivesText"] = "Collect 6 Titan Artifacts in Uldum . Progress: Any luck with the titan artifacts ?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 168043 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 304 }, { ["id"] = 1553, ["amount"] = 307 }, { ["id"] = 1553, ["amount"] = 320 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58286] = { ["id"] = 58286, ["name"] = "Far From Home", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58286 }, ["description"] = "The Amathet's conquest of eastern Uldum was sudden, and we were unable to reach some of our farthest settlements in time. Fortunately, many of the tol'vir who lived in the conquered territories were not killed, instead being put to work under the Amathet's whip. We must take any opportunity we can to free them and return them to their homes.", ["objectivesText"] = "Free 6 Enslaved Tol'vir in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 310 }, { ["id"] = 1553, ["amount"] = 319 }, { ["id"] = 1553, ["amount"] = 332 }, { ["id"] = 1553, ["amount"] = 334 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58287] = { ["id"] = 58287, ["name"] = "A Smashing Plan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58287 }, ["description"] = "Reports from my scouts mention various idols and monuments that the Amathet use to channel their solar magic. I don't know exactly what they're up to, but we should take away any possible advantage they have. So, I want you to go over there, and break anything that looks remotely magical. Just don't tell the Explorers' League. I'll never hear the end of it.", ["objectivesText"] = "Destroy 4 Amathet Idols and 2 Suntouched Obelisks in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 352 }, { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 310 }, { ["id"] = 1553, ["amount"] = 314 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58288] = { ["id"] = 58288, ["name"] = "The Sun King's Chosen", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58288 }, ["description"] = "On the surface the Amathet appear to be unwavering, but all soldiers have their breaking point. We need to send a message to their forces that we are not to be trifled with. Seek out the strongest of their numbers and bring them down in front of their eyes. We will show them the strength of Uldum !", ["objectivesText"] = "Defeat 3 rare Amathet enemies in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 304 }, { ["id"] = 1553, ["amount"] = 305 }, { ["id"] = 1553, ["amount"] = 306 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58289] = { ["id"] = 58289, ["name"] = "Guarded Secrets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58289 }, ["description"] = "From what we know about the Amathet, they must've been locked away in their tombs for thousands of years. Just think of what we could learn from them! Of course, that would be a lot easier if they weren't trying to kill us. If you happen upon any caches of Amathet relics in your travels, let me know. I'd love to see what sort of mysteries they contain!", ["objectivesText"] = "Loot 3 Amathet Caches in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 335 }, { ["id"] = 1553, ["amount"] = 342 }, { ["id"] = 1553, ["amount"] = 353 }, { ["id"] = 1553, ["amount"] = 394 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58290] = { ["id"] = 58290, ["name"] = "Champions of the Amathet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58290 }, ["description"] = "The soldiers of Ramkahen are hearty and reliable. I would stand them up against any footman of the Amathet, but some of their higher-caste fighters are too much for even our toughest to handle. I don't think they'd be a problem for you, though. It would be a boon to our defense efforts if you could handle them while my soldiers engage the rank and file.", ["objectivesText"] = "Kill 6 elite Amathet enemies in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 301 }, { ["id"] = 1553, ["amount"] = 302 }, { ["id"] = 1553, ["amount"] = 305 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "group", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58291] = { ["id"] = 58291, ["name"] = "Encroaching Poachers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58291 }, ["description"] = "The Wastewanders used the pelts of the local hyenas to construct our armor. Unfortunately since the Amathet arrived, their hunters have overrun our normal hunting grounds. We need those pelts, and will pay handsomely for them. Either take them from the hunters or skin the hyenas yourself, if you have the skill.", ["objectivesText"] = "Collect 6 Rugged Hyena Pelts from Amathet Hunters or by skinning hyenas in Uldum . Progress: Have you brought back the pelts?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174008 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 308 }, { ["id"] = 1553, ["amount"] = 310 }, { ["id"] = 1553, ["amount"] = 346 }, { ["id"] = 1553, ["amount"] = 379 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160957, ["x"] = 0.546, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160957, ["x"] = 0.546, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58297] = { ["id"] = 58297, ["name"] = "Faceless Mask of the Daredevil", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 58297 }, ["description"] = "The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.", ["objectivesText"] = "Return the Faceless Mask of the Daredevil to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Daredevil on the altar.", ["rewardItems"] = { 173955, 174082 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 174082 } },
[58314] = { ["id"] = 58314, ["name"] = "Faceless Mask of the Burned Bridge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 58314 }, ["description"] = "The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.", ["objectivesText"] = "Return the Faceless Mask of the Burned Bridge to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Burned Bridge on the altar.", ["rewardItems"] = { 173363, 174083 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 174083 } },
[58316] = { ["id"] = 58316, ["name"] = "Faceless Mask of the Dark Imagination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 58316 }, ["description"] = "These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the Void's domain. In these pursuits, this magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.", ["objectivesText"] = "Return the Faceless Mask of the Dark Imagination to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Dark Imagination on the altar.", ["rewardItems"] = { 174081 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 174081 } },
[58317] = { ["id"] = 58317, ["name"] = "Faceless Mask of the Pained", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 58317 }, ["description"] = "Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.", ["objectivesText"] = "Return the Faceless Mask of the Pained to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Pained on the altar.", ["rewardItems"] = { 172946, 174079 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 174079 } },
[58318] = { ["id"] = 58318, ["name"] = "Faceless Mask of the Long Night", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 58318 }, ["description"] = "The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.", ["objectivesText"] = "Return the Faceless Mask of the Long Night to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Long Night on the altar.", ["rewardItems"] = { 173363, 174080 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 174080 } },
[58321] = { ["id"] = 58321, ["name"] = "Uncommon Core", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58321 }, ["description"] = "Our scouts have reported that the Amathet are constructing new titanic watchers. We had long thought this art was lost to the sands of time. It would appear we were mistaken. I needn't tell you what a boon it would be to have the aid of watcher constructs in our battles for Uldum . We must unlock the secrets of their construction! The power of a titanic watcher lies in its core. I ask that you bring one to me, so that our artificers might divine its construction.", ["objectivesText"] = "Collect a Titanic Core from an Ivory Watcher in Uldum . Progress: Have you obtained the core?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174009 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 327 }, { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 303 }, { ["id"] = 1553, ["amount"] = 304 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "group", ["sourceQuests"] = { 56472 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58325] = { ["id"] = 58325, ["name"] = "Watcher Emil", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "Watcher Emil is my trusted overseer of the catacombs. Before I was thrown into the Maw, half of the mirror was entrusted to him. I had him stationed at the Catacombs of Regret. But I do not know where in the sprawl he is. There is a guard station near the entrance to the catacombs. Start the search there. There is an officer who can help us, I--I can't remember who. That is, provided they survived this whole mess. You must find Emil at once. We may not have much time.", ["objectivesText"] = "Search for Watcher Emil in the Catacombs of Regret. Progress: A friend of the Curator ?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160956, ["x"] = 0.692, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58842 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58326] = { ["id"] = 58326, ["name"] = "Combing the Catacombs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "When the anima drought began, our defenses began to fail. Our guards, weakened by the lack of anima, became overrun as the sinstones this land is built upon rose up around us. Not to mention the manifestations of the souls who can no longer be tended to are running wild. You may be able to help us, mortal. Please, we can barely hold this position... and I don't know for how much longer.", ["objectivesText"] = "Kill 12 Manifestations and 3 Sinstone Rampagers in the Catacombs of Regret.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161056, ["x"] = 0.658, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161056, ["x"] = 0.658, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58842 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58327] = { ["id"] = 58327, ["name"] = "Snacks for Stonehead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58327 }, ["description"] = "< Stonehead has amassed a wide variety of half-eaten oddities. He'd certainly appreciate you bringing some new, creative snacks for him to try.>", ["objectivesText"] = "Collect a sampling of snacks from across the Ember Ward for Stonehead . Progress: Tummy rumbly...", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 175826, 175828, 175829, 175840 }, ["starts"] = { { ["x"] = 0.392, ["y"] = 0.652, ["mapID"] = 1525 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157199, ["x"] = 0.39, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[58328] = { ["id"] = 58328, ["name"] = "TBD", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58328 }, ["description"] = "Bribe Boulderfoot", ["objectivesText"] = "TBD", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[58337] = { ["id"] = 58337, ["name"] = "Break Out", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "Our reinforcements never came, leaving us unable to tend to the souls here. They have begun to break out of their cells. Many of them are not ready for the next step in the process. Take these iron chains. They can be used to rein them under your control. Once you have a soul bound, you can return them to any intact cage you can find.", ["objectivesText"] = "Use the Chains of Regret on Escaped Captives and bring them to any intact Catacombs Cage.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 31312, 31313, 31314, 31315, 33226, 37959, 38001, 38044, 38105, 38230, 38231, 38232, 38665, 55004, 65277, 65297, 65316, 65335, 65683, 65703, 65721, 112591, 112592, 112593, 112594, 131699, 142054, 143498, 174040, 177633, 177634, 177646, 177648, 177650, 177651, 177652, 202283, 203330, 248563, 248564, 248565, 248566 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161056, ["x"] = 0.658, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161056, ["x"] = 0.658, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58842 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58351] = { ["id"] = 58351, ["name"] = "The Hills Have Eyes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "The other houses have yet to launch a full scale assault, but do not mistake their cowardice for incompetence. Any tactician worth their weight in maldracite knows the value of espionage. I suspect that the agents of our foes skulk within our own ranks as we speak. Take one of my hounds. It will know our enemies by their scent. Once the pests have been discovered, exterminate them.", ["objectivesText"] = "Uncover hidden spies with the Chosen Corpsehound. Progress: Get moving!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57514 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58372] = { ["id"] = 58372, ["name"] = "Lead the Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "We must move now. That won't be the last assassin we face. I can provide some cover of darkness, but mind that the spell is not infallible. Enough talking. The Curator needs us and my mirror shard to get to her as soon as possible.", ["objectivesText"] = "Escort Watcher Emil out of the Catacombs of Regret.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180924, 180925, 180926, 180927 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160956, ["x"] = 0.692, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58325 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58373] = { ["id"] = 58373, ["name"] = "Ny'alotha: MOTHER's Guidance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10522, ["storyline"] = { 58373 }, ["description"] = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage. MOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", ["objectivesText"] = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Normal Difficulty. Progress: Without the items MOTHER cannot guarantee safe passage.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 174063, 174910, 174913 }, ["starts"] = { { ["npcID"] = 160177 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10522 } }, ["questGiverID"] = 160177, ["questType"] = "raid" },
[58374] = { ["id"] = 58374, ["name"] = "Ny'alotha: MOTHER's Guidance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10522, ["storyline"] = { 58374 }, ["description"] = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage. MOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", ["objectivesText"] = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Heroic Difficulty. Progress: Without the items MOTHER cannot guarantee safe passage.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 174064, 174909, 174911 }, ["starts"] = { { ["npcID"] = 160177 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10522 } }, ["questGiverID"] = 160177, ["questType"] = "raid" },
[58375] = { ["id"] = 58375, ["name"] = "Ny'alotha: MOTHER's Guidance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10522, ["storyline"] = { 58375 }, ["description"] = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage. MOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", ["objectivesText"] = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Mythic Difficulty. Progress: Without the items MOTHER cannot guarantee safe passage.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 174065, 174908, 174912 }, ["starts"] = { { ["npcID"] = 160177 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10522 } }, ["questGiverID"] = 160177, ["questType"] = "raid" },
[58376] = { ["id"] = 58376, ["name"] = "Construct Part: Necromantic Oil", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58376 }, ["description"] = "<This could be used to construct a powerful abomination. Perhaps Rathan will know how we can use it.>", ["objectivesText"] = "Deliver this part to Rathan in Butchers Block. Provided item:", ["rewardXP"] = 1020, ["rewardItems"] = { 174076, 183519 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60048 }, ["startItems"] = { 174076 } },
