[58382] = { ["id"] = 58382, ["name"] = "Someone Worth Saving", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["series"] = { 61077 }, ["description"] = "Are you familiar with Kael'thas Sunstrider? He was a powerful leader on your world for a time. The immense anima of that lingering power attracted the Master's attention, to the eternal detriment of Kael'thas's soul. < The Accuser 's lip curls in disgust.> Every soul deserves a chance at redemption, $p. If you do not believe that, believe me when I say that this soul is immensely powerful and still at risk of self-destruction. Release him so that we may walk his path of redemption together.", ["objectivesText"] = "Release Kael'thas Sunstrider in Sinfall.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questTurnInID"] = 165291, ["questType"] = "standard", ["sourceQuests"] = { 61077 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700 },
[58383] = { ["id"] = 58383, ["name"] = "The Many Sins of Kael'thas Sunstrider", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "Kael'thas Sunstrider was on the verge of destruction when we rescued him from Castle Nathria. Denathrius had infused Kael'thas with unimaginable amounts of anima, each bit carrying with it the sins of others. It made his soul strong, but unstable--confused and pushed to the edge of its own existence. Trust me when I tell you that Kael'thas Sunstrider has enough sins of his own. Assist me in identifying which of the many sins heaped on his soul are truly his burden to bear.", ["objectivesText"] = "Help the Accuser identify the sins of Kael'thas Sunstrider. Progress: The ritual of absolution allows me to peer directly into a soul to see every sin weighing it down.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174211 }, ["starts"] = { { ["x"] = 0.464, ["y"] = 0.323, ["mapID"] = 1700, ["npcID"] = 161158 } }, ["ends"] = { { ["x"] = 0.464, ["y"] = 0.323, ["mapID"] = 1700, ["npcID"] = 161158 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.464, ["y"] = 0.323 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 161158, ["questTurnInID"] = 161158, ["questType"] = "standard", ["sourceQuests"] = { 58382 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700 },
[58384] = { ["id"] = 58384, ["name"] = "Dredgers Left Behind", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "When Prince Renathal fled Darkwall Tower, he was forced to leave many people and belongings behind. The powerful relics and weapons were long ago carted off to the Master's lair. But the Prince's dredgers were forced to stay and serve the Master's traitorous lackeys here instead. You will be a welcome sight to them--a sign that the Prince has not forgotten them. If they are willing to fight, help them escape and I will ensure they are brought safely to Sinfall.", ["objectivesText"] = "Help 10 dredgers escape Darkwall Tower.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161208, ["x"] = 0.422, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58426 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58385] = { ["id"] = 58385, ["name"] = "Learning to Sacrifice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "Kael'thas remains unstable in his current state, bursting at the seams with anima. He is also an arrogant, selfish moron. Thankfully, I have a lesson that can address both concerns. True leaders sacrifice of themselves to empower those under their care. Many stoneborn and gargon, including the Prince's own pet, were left dormant in Darkwall by the Master's forces. Order Kael'thas to forfeit portions of the anima trapped inside of him to reanimate those dormant stoneborn to aid us.", ["objectivesText"] = "Help Kael'thas reanimate the Prince's pet, Vrednic, and other dormant stoneborn in Darkwall Tower.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161208, ["x"] = 0.422, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58426 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58386] = { ["id"] = 58386, ["name"] = "Use My Strengths", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "<Kael'thas looks around to make sure the Accuser is out of earshot.> the Accuser is so obsessed with my negative traits that she has failed to see my strengths! Even in death, I am incredibly powerful. the Accuser herself said that Denathrius infused me with anima to make me strong. Let us use that strength for good while I have it! This tower once belonged to the Prince of this realm, correct? Let us find his usurper and gain vengeance! Vengeance is a virtue I have always appreciated.", ["objectivesText"] = "Help Kael'thas confront Usurper Simona. Progress: Yes?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 137663, 174211 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 161261 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.4235, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questGiverID"] = 161261, ["questType"] = "standard", ["sourceQuests"] = { 58426 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58387] = { ["id"] = 58387, ["name"] = "We Each Must Carry Our Own Sins", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "The Master chained Kael'thas's sinstone to his soul via a dark, corruptive process that left Kael'thas scarred and overburdened. He bears the weight of not only his own sins, but the sins of countless other souls on his back. That would be a crushing burden for even the most noble of souls--which Kael'thas is not. Let us hope your time with Kael'thas has prepared his soul for my ritual. I must break that cursed burden by removing the foreign sins from his soul, or else we'll lose him forever.", ["objectivesText"] = "Complete the ritual of extraction on Kael'thas Sunstrider. Progress: This must work.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174211, 180941 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.4235, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58384, 58385, 58386 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58388] = { ["id"] = 58388, ["name"] = "Blackbale Betrayers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "When the Prince made his final stand at Darkwall Tower, he called for aid from the many noble houses here in the Chalice District. None came. Most simply avoided the conflict, out of self-preservation. A shameful, but understandable choice. However, one house took action. Lord Blackbale replied with cruel mockery and sent his stoneborn to aid the Master's armies instead. Prince Renathal has not forgotten that betrayal. Kael'thas seeks vengeance? Let him have some. Start with the stoneborn.", ["objectivesText"] = "Kill 4 Blackbale Overseers . Progress: The Blackbale seem to have grown more influential since the Prince's fall.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161421, ["x"] = 0.458, ["y"] = 0.5145 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161421, ["x"] = 0.458, ["y"] = 0.5145 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.5145 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58443 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58389] = { ["id"] = 58389, ["name"] = "Maldraxxian Weapons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "<The weapon you find seems unlike those wielded by most venthyr, yet the marks it bears are unmistakably familiar... It would be wise to seek out more such weapons and bring them to the Accuser .>", ["objectivesText"] = "Collect 8 Maldraxxian Weapons . Progress: What are you carrying? Those do not belong here...", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174211, 174212 }, ["starts"] = { { ["x"] = 0.483, ["y"] = 0.544, ["mapID"] = 1525 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161421, ["x"] = 0.458, ["y"] = 0.5145 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.5145 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58443 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["startItems"] = { 174212 } },
[58391] = { ["id"] = 58391, ["name"] = "Reconnaissance... for my, uh, Recovery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "It appears I am at your mercy once more, $p. Far be it from me to tell you the best way to absolve my sins as the Accuser insists we do. However... In that note, the Tithelord arranged a meeting with his contact in Darkhaven. Do you know where that is? If you do, we could investigate, gather more information, and present that information to the Accuser and Prince Renathal. I imagine that would be quite useful to them. And a very selfless act of assistance on my part, do you not agree?", ["objectivesText"] = "Spy on the Tithelord's meeting with his Maldraxxian contact.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 109076, 174211 }, ["starts"] = { { ["npcID"] = 161431 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161572, ["x"] = 0.698, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questGiverID"] = 161431, ["questType"] = "standard", ["sourceQuests"] = { 58388, 58389, 58518 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58392] = { ["id"] = 58392, ["name"] = "Death's End Destruction", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "It appears we have discovered a common enemy to pursue, $p. Wherever that necromancer ran off to is no doubt filled with traitors, undead armies from another realm, and at least one lich... It cannot be a sin to kill such as these. To demolish the camp of these invaders and betrayers must be a virtue. A virtue I crave. Let us pursue it with haste.", ["objectivesText"] = "Destroy the Maldraxxian camp in Death's End. Progress: I hope they put up a fight.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174211 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161572, ["x"] = 0.698, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161572, ["x"] = 0.698, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 161572, ["questType"] = "standard", ["sourceQuests"] = { 58391 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58393] = { ["id"] = 58393, ["name"] = "Strategic Executions", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "I confess that I do not comprehend the full array of potential consequences wrought by the Tithelord's anima-sharing arrangement. But I am very aware of the dangers posed by a lich with access to power. I am also very aware that resolving this situation is important to the Accuser, which, given my current situation, makes it important to me. We should eliminate the muscle behind the anima transfer logistics. Without that, the shipments will halt.", ["objectivesText"] = "Kill the dredger giants in Death's End. Progress: They really do grow their monsters big here, do they not?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161572, ["x"] = 0.698, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161572, ["x"] = 0.698, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 161572, ["questType"] = "standard", ["sourceQuests"] = { 58391 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58394] = { ["id"] = 58394, ["name"] = "Lady Ouix'Ara", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "Can you feel it? The chill in your bones... the energy... power... She's here. The lich. Take me to her. I must speak with her, in my own way.", ["objectivesText"] = "Kill Lady Ouix'Ara . Progress: No good has ever come from a lich, <name>.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 174211 }, ["starts"] = { { ["npcID"] = 161436 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questGiverID"] = 161436, ["questType"] = "standard", ["sourceQuests"] = { 58392, 58393 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58395] = { ["id"] = 58395, ["name"] = "Enough Vengeance For One Day", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "After the Sunwell's destruction and the near extermination of my people, I vowed to claim vengeance upon Arthas and Kel'Thuzad. But I needed power to see that happen, and to seize that power I... <Kael'thas grows quiet.> I... am ready to return to Sinfall. I must recover my strength for what lies ahead. As the Accuser is so fond of reminding me, I have... much to ponder. Let us inform our allies of the enemy we have revealed.", ["objectivesText"] = "Deliver Kael'thas to Sinfall and report to Prince Renathal .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174211, 180901, 180902, 180903, 180904 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 161436 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 161436, ["questType"] = "standard", ["sourceQuests"] = { 58394 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
[58406] = { ["id"] = 58406, ["name"] = "Mirror to Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 58406, 58407 }, ["description"] = "I've received word that Laurent 's made substantial progress with his repairs. Once the mirror has been restored, we can realize our efforts to recover the final medallion. Head to the ramparts and see if his work is near completion.", ["objectivesText"] = "Find Laurent on the Sinfall ramparts.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.518, ["y"] = 0.375, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 170532, ["x"] = 0.272, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questGiverID"] = 158653, ["questType"] = "standard", ["sourceQuests"] = { 57646 }, ["questLines"] = { { ["id"] = 1018, ["name"] = "Dominion", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1018, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58407] = { ["id"] = 58407, ["name"] = "The Medallion of Dominion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58406, 58407 }, ["description"] = "Laurent speaks the truth. We must not delay. This mirror is our entryway into the heart of Maldraxxus. Together with Kael'thas, we will find Kel'Thuzad and rip the Medallion of Dominion from his undeserving grasp.", ["objectivesText"] = "Use Laurent's mirror to enter Maldraxxus and recover the Medallion of Dominion from Kel'Thuzad.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 180948, 183888, 183889, 183890, 183891, 183892, 183893 }, ["rewardChoices"] = { 183888, 183889, 183890, 183891, 183892, 183893 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 170543, ["x"] = 0.274, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 170543, ["x"] = 0.274, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.274, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 170543, ["questType"] = "standard", ["sourceQuests"] = { 58406 }, ["questLines"] = { { ["id"] = 1018, ["name"] = "Dominion", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1018, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58420] = { ["id"] = 58420, ["name"] = "A Foul Annoyance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58420 }, ["description"] = "The Hozen are opportunistic and weak. It does not surprise me that some of their kind have thrown their lot in with the Old Gods. We should take care of them before they become more than a nuisance.", ["objectivesText"] = "Kill 7 Squidtail hozen in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 304 }, { ["id"] = 1553, ["amount"] = 305 }, { ["id"] = 1553, ["amount"] = 306 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58421] = { ["id"] = 58421, ["name"] = "Special Access", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "Mateo will have the other mirror shard we need to access the medallion. He is likely in my former manor in Archivam. It is guarded by Nourman , a loyal dredger. Nourman is ever committed to his duties, regardless of the situation. Mateo likely maintained the same rule to access the manor--possess the fangs of those granted access. If you collect the fangs of the commanders of his operation, Nourman will let you pass.", ["objectivesText"] = "Collect the fangs of Examiner Daciana, Examiner Boian, and Examiner Ionata. Progress: Oi, you want to access the manor? Let me see your fangs.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174093, 174094, 174095 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161298, ["x"] = 0.775, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58326, 58337, 58372 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58422] = { ["id"] = 58422, ["name"] = "Mark of the Conquerors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58422 }, ["description"] = "The invading minions of N'Zoth lay claim to lands they are not entitled to. The Vale will not be conquered while even one of the Rajani still draws breath. Burn down their banners as a reminder of this.", ["objectivesText"] = "Burn 6 Banners of the Black Empire in the Vale of Eternal Blossoms . Progress: Have you sent our message?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 313 }, { ["id"] = 1553, ["amount"] = 320 }, { ["id"] = 1553, ["amount"] = 321 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58423] = { ["id"] = 58423, ["name"] = "The Strongest Among Them", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58423 }, ["description"] = "You have shown great strength in your conquests, but new enemies assail the Vale with each day. Seek out the strongest that our foes have sent forth, and bring them down for their allies to see.", ["objectivesText"] = "Defeat 3 rare minions of N'Zoth in the Vale of Eternal Blossoms . Progress: Tell me of your victories.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 311 }, { ["id"] = 1553, ["amount"] = 356 }, { ["id"] = 1553, ["amount"] = 361 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58424] = { ["id"] = 58424, ["name"] = "An Eye for an Amulet", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "Archivam has been overrun by Denathrius's lackeys. We must eliminate these intruders. From the look of things, they have resorted to tearing Archivam down to the core for any evidence of the Curator's medallion. Go, <name>. Stop them before it is too late.", ["objectivesText"] = "Kill 12 Archivam Intruders and 5 Excavation Enforcers in Archivam. Progress: Are they dead?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160956, ["x"] = 0.692, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160956, ["x"] = 0.692, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58326, 58337, 58372 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58426] = { ["id"] = 58426, ["name"] = "In the Shadow of our Failures", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "I will personally tend to the absolution of Kael'thas Sunstrider. His current state and trauma requires nothing short of perfect intervention and instruction to correct. I would welcome your assistance in this. I sense a bond between Kael'thas and yourself. I think your presence may help inspire him down a better path. If you're willing, meet us at Darkwall Tower. Prince Renathal suffered a great defeat there once. Perhaps a better fate will be found this time.", ["objectivesText"] = "Meet the Accuser and Kael'thas at Darkwall Tower.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174211 }, ["starts"] = { { ["x"] = 0.465, ["y"] = 0.322, ["mapID"] = 1700, ["npcID"] = 161158 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161208, ["x"] = 0.422, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questGiverID"] = 161158, ["questType"] = "standard", ["sourceQuests"] = { 58383 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58428] = { ["id"] = 58428, ["name"] = "Crypt Crashers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "There's one more thing I forgot to mention. Apologies, <name>. The mirror, once complete, is inherently cursed by design. You need to locate my Death Lotus Powder . It was in one of the crypts in Archivam... I cannot recall which one. I'm afraid you may have to brute force this one, <name>.", ["objectivesText"] = "Collect Stonebreaker Mallets to destroy crypt doors in search of Death Lotus Powder . Progress: Do you have the powder?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174098, 174100 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58326, 58337, 58372 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58431] = { ["id"] = 58431, ["name"] = "Pool of Potions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57301, 58431, 59430, 59520 }, ["description"] = "I shall teach you about the Pool of Potions . The potions we create here have a variety of beneficial effects. Kill the slimes in the surrounding ruins and collect the Oozing Ingredient: Viscous Oil they may drop. Each slime can produce a great quantity of oil, so you'll only be able to carry one slime's worth at a time. Deliver this oil to the Pool of Potions and toss it in.", ["objectivesText"] = "Deliver three Oozing Ingredient: Viscous Oil to the Pool of Potions . Progress: Have you brought enough oil?", ["rewardGold"] = 365040, ["rewardXP"] = 1415, ["rewardItems"] = { 171267, 171268 }, ["rewardChoices"] = { 171267, 171268 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157945, ["x"] = 0.59, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157945, ["x"] = 0.59, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59430 }, ["questLines"] = { { ["id"] = 1158, ["name"] = "Mixing Monstrosities", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58432] = { ["id"] = 58432, ["name"] = "Something Old, Something Used", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58432 }, ["description"] = "Want new luckydos? Chordy is best at finding luckydos! Want to go look around with Chordy ? < Chordy looks at you pleadingly with his large eye.>", ["objectivesText"] = "Use Chordy to locate and collect 10 valuable salvage in Maldraxxus. Progress: Did we find anything good?", ["rewardXP"] = 8165, ["rewardItems"] = { 158149, 174101, 178554, 182489, 182498, 182507, 182516, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 161270, ["x"] = 0.55, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60041 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58433] = { ["id"] = 58433, ["name"] = "Anima Attrition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 56829, 56942, 56955, 56978, 57007, 57025, 57026, 57381, 58433 }, ["description"] = "This is not some simple raid or protest. These stoneborn mean to steal the anima this convoy was carrying. That anima was destined to be tithed to the Master. There is a drought on and we cannot let these vagabonds and miscreants steal our hard-earned anima. Recover the tithe if you can and I will see to your notoriety.", ["objectivesText"] = "Recover the Anima Canister . Progress: What have you found?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174102 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 155533, ["x"] = 0.6764, ["y"] = 0.7036 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6764, ["y"] = 0.7036 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 56942 }, ["questLines"] = { { ["id"] = 985, ["name"] = "Welcome to Revendreth", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 985, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 985, ["questLineOrder"] = 25 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58435] = { ["id"] = 58435, ["name"] = "Heritage of the Vulpera", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 35 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 58435 }, ["description"] = "The Horde has come to truly value the Vulpera, thanks to your efforts. You are the most... vulperan vulpera that I know! Visit me in the Vulpera Hideaway in Vol'dun. Kiro had me put together a small memento in appreciation of your efforts.", ["objectivesText"] = "Meet Hagashi at the Vulpera Hideaway in Vol'dun.", ["rewardGold"] = 315900, ["rewardXP"] = 6815, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.498, ["mapID"] = 864, ["npcID"] = 124108 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 124108, ["x"] = 0.568, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questGiverID"] = 124108, ["questType"] = "standard" },
[58436] = { ["id"] = 58436, ["name"] = "Heritage of the Mechagnome", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 37 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 58436 }, ["description"] = "<name>, we could not be more pleased with your progress. You represent us well with the Alliance. Return to Mechagon City at your earliest convenience. Waren has created a gift for you.", ["objectivesText"] = "Meet Prince Erazmin in Mechagon City.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["x"] = 0.73, ["y"] = 0.334, ["mapID"] = 1462, ["npcID"] = 158145 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 158145, ["x"] = 0.733333, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.733333, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questGiverID"] = 158145, ["questType"] = "standard" },
[58437] = { ["id"] = 58437, ["name"] = "Parts to a Whole", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58437 }, ["description"] = "Damien has some great dreams, but without more abominations, this training facility will not succeed! I have a plan though! If we can't recruit more abominations, then we shall make them ourselves! I need you to make some corpses, then mark them for harvesting with a flag. I will do the rest.", ["objectivesText"] = "Mark 15 corpses for harvesting", ["rewardXP"] = 8165, ["rewardItems"] = { 174110 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Corpses marked for harvest", ["amount"] = 15, ["type"] = 0, ["objectID"] = 161288, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
