[58440] = { ["id"] = 58440, ["name"] = "Mirror, Mirror...", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "We have what we need to get you through, <name>. My medallion lies on the other side of the mirror. Once through, my medallion will be there... somewhere. Please be careful. My mind may be weakened, but I do remember working with the Accuser to protect the crypt's interior. I should be able to tell you everything about this place, but I am afraid that just is not the case anymore.", ["objectivesText"] = "Enter the Curator 's mirror. Then, collect the Medallion of Avarice . Progress: My medallion? Do you have it?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 79868, 87399, 174111, 174179, 175733, 176127, 177657, 180945, 184373, 184374 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58424, 58428, 60673 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58442] = { ["id"] = 58442, ["name"] = "Consuming Maw", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 390, ["starts"] = { { ["x"] = 0.814, ["y"] = 0.495, ["mapID"] = 1530 } }, ["ends"] = { { ["x"] = 0.814, ["y"] = 0.495, ["mapID"] = 1530 } }, ["coords"] = { ["mapID"] = 1530, ["x"] = 0.814, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 161296 }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 161338 } } },
[58443] = { ["id"] = 58443, ["name"] = "Continued Care of Kael'thas", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "Kael'thas is free from the twisted corruption of the Master, but he is not truly \"free\" yet. He carries more than enough burdens from his own sins to condemn him to the Maw. We must be vigilant in encouraging and forcing him to atone for his mistakes. If he cannot right the many wrongs of his mortal life, he will be doomed forever. You are having a positive effect on him. Please, accompany us down to the Chalice District for his next lesson.", ["objectivesText"] = "Meet the Accuser and Kael'thas in the Chalice District.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161278, ["x"] = 0.4235, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161421, ["x"] = 0.458, ["y"] = 0.5145 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.4235, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58387 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58444] = { ["id"] = 58444, ["name"] = "Return to Sinfall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "<name>, we must get the medallion back to Sinfall as soon as possible. We saw how fierce Mateo's forces were, just imagine what destruction Denathrius will bring if we linger around. I will return to Absolution Crypt in a moment. With all the work you've done, I can begin to resume my duties. My first order of business will be to recruit a new sinkeeper. Oh how I dread interviews...", ["objectivesText"] = "Bring the medallion to Prince Renathal at Sinfall. Progress: Did you retrieve the Medallion of Avarice ?", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 174111 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 160941, ["questType"] = "standard", ["sourceQuests"] = { 58440 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58445] = { ["id"] = 58445, ["name"] = "Containing the Night", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "It is fortunate you are here, <name>. Thiernax believes he may know how to save Tyrande from the fate he himself suffered as the Night Warrior. Let us hear what he has to say.", ["objectivesText"] = "Listen to Thiernax's plan. Progress: It cannot be easy for Thiernax to share his memories of becoming the Night Warrior... or the pain that followed.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.445, ["y"] = 0.391, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["ends"] = { { ["x"] = 0.445, ["y"] = 0.391, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.445, ["y"] = 0.391 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 160262, ["questTurnInID"] = 160262, ["questType"] = "standard", ["sourceQuests"] = { 61171 }, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58446] = { ["id"] = 58446, ["name"] = "Tracker Tracking", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "We will require the aid of an expert tracker if we are to find the other Night Warriors. The Wild Hunt possesses legendary skills in such matters. No quarry can elude them. Speak with Lord Herne. With one of his hunters at your side, your search will surely be successful.", ["objectivesText"] = "Speak with Lord Herne and locate the Wild Hunt tracker.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.445, ["y"] = 0.391, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 164627, ["x"] = 0.352, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questGiverID"] = 160262, ["questType"] = "standard", ["sourceQuests"] = { 58445 }, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58447] = { ["id"] = 58447, ["name"] = "Monster Hunting", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "Make ready, <class>. We hunt a worldeater. They are the largest of devourers, massive beings who can drain anima from an entire region within a matter of moments. With Ardenweald suffering from the drought, a worldeater's presence could prove disastrous. Still, we must not rush into battle without first understanding our prey. Tread the Elder Stand with me. Even creatures such as these leave spoor. Knowing our quarry will be what allows us to slay it.", ["objectivesText"] = "Search for clues and tracks to learn more about the worldeater.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165841, ["x"] = 0.352, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.263333, ["y"] = 0.474667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58706 }, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58449] = { ["id"] = 58449, ["name"] = "Acid Reflux", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "We will need to be properly prepared before we can face Voras. The digestive juices of Ardenweald 's gorm dissipate the anima in their food. Ingesting them causes devourers no small discomfort. For a beast of that size, we will need a lot of it to have any effect. There should be plenty of gorm in the hive to the east. Long ago, an artisan gave me a tool that he said would be useful against the gorm, should I ever need it. You may borrow it.", ["objectivesText"] = "Use the Gormherd Branch on gorm in Gormhive to retrieve 50 Bulging Digestive Sacs . Progress: We will need those digestive sacs if we are to disrupt the worldeater enough to slay it, <name>.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173534, 174467, 174645 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 165841, ["x"] = 0.352, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 164627, ["x"] = 0.352, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58447 }, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58450] = { ["id"] = 58450, ["name"] = "Anima Instincts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "Voras is clearly content to roam the Elder Stand. We will need a way to lure it to us once we are ready to fight. Did you notice the wildseeds in the clearing where we spotted it? Voras must be feasting on the concentrated anima contained within them. There should still be some expended wildseeds from before the drought in the Gormhive. Let us create bait too tempting for Voras to ignore.", ["objectivesText"] = "Collect 8 Life-Hardened Anima . Progress: It may take several wildseeds, but with enough concentrated anima, we should be able to lure out Voras.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175753 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 165841, ["x"] = 0.352, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 164627, ["x"] = 0.352, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58447 }, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58451] = { ["id"] = 58451, ["name"] = "Voras, The Realm Eater", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "We have everything we need, <name>. Now only the kill remains. We set the lure, weaken the beast, and land the final blow. Hunting is a battle of wills. Life or death hangs in the balance for all of us. It has always been this way, on Azeroth as in Ardenweald . Let the hunt begin.", ["objectivesText"] = "Slay Voras . Progress: Voras cannot continue to leech anima from Ardenweald . We must stop it now.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161354, ["x"] = 0.243333, ["y"] = 0.490667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.263333, ["y"] = 0.474667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59721 }, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58452] = { ["id"] = 58452, ["name"] = "Tracking the Shadows", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58445, 58446, 58447, 58449, 58450, 58451, 58452, 58706, 59258, 59721 }, ["description"] = "The quarry has been slain, and my duties fulfilled. The tirnenn are more than capable of defending their home from the lesser devourers. Nature will take its course. I will report back to Lord Herne and meet you at the Heart of the Forest. There we shall see what I will be hunting next.", ["objectivesText"] = "Speak with Ysera in the Heart of the Forest.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 175592, 179769, 179891, 181913 }, ["rewardChoices"] = { 175592, 179769, 181913, 179891 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161353, ["x"] = 0.263333, ["y"] = 0.474667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.263333, ["y"] = 0.474667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 161353, ["questType"] = "standard", ["sourceQuests"] = { 58451 }, ["questLines"] = { { ["id"] = 1100, ["name"] = "The Horned Hunter", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1100, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58454] = { ["id"] = 58454, ["name"] = "Spoiling For A Fight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58454 }, ["description"] = "Your contribution of anima has aided our operation here greatly. Several of our more famous competitors have come here lured by the flow of new anima. Would you like to test yourself versus the famous Sabriel? There could be much profit for everyone, if you were to defeat her. I can add her to the schedule, she will appear soon if you defeat the other challengers.", ["objectivesText"] = "Defeat Sabriel the Bonecleaver in the Theater of Pain.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 181815, 182083 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 159830, ["questType"] = "group" },
[58455] = { ["id"] = 58455, ["name"] = "Shadowy Showdown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 58455 }, ["series"] = { 58456, 58457 }, ["description"] = "This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.", ["objectivesText"] = "Find Burt Macklyn outside of the entrance to Blackrock Depths in Blackrock Mountain.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 37863 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 147645, ["x"] = 0.503, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 147645, ["x"] = 0.503, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questTurnInID"] = 147645, ["questType"] = "standard", ["nextQuests"] = { 58457 } },
[58456] = { ["id"] = 58456, ["name"] = "Shadowy Showdown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 51, ["storyline"] = { 58456 }, ["series"] = { 58455, 58457 }, ["description"] = "This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.", ["objectivesText"] = "Find Burt Macklyn outside of the entrance to Blackrock Depths in Blackrock Mountain.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.563, ["y"] = 0.308, ["mapID"] = 1165, ["npcID"] = 147641 } }, ["ends"] = { { ["x"] = 0.563, ["y"] = 0.308, ["mapID"] = 1165, ["npcID"] = 147641 } }, ["coords"] = { ["mapID"] = 1165, ["x"] = 0.563, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 51 } }, ["questGiverID"] = 147641, ["questTurnInID"] = 147641, ["questType"] = "standard", ["nextQuests"] = { 58457 } },
[58457] = { ["id"] = 58457, ["name"] = "Shadows of Blackrock", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 51, ["storyline"] = { 58457 }, ["series"] = { 58455, 58456 }, ["description"] = "We've finally tracked those pesky Shadowy Figures down, they should all be in there. They seem highly skilled, you're going to need to bring your best teams in there if you have any chance of winning. Let me know when you are ready.", ["objectivesText"] = "Stop the Shadowy Figures. Progress: I can teleport you in, but after that, you're on your own.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 122457 }, ["starts"] = { { ["x"] = 0.331, ["y"] = 0.231, ["mapID"] = 35, ["npcID"] = 161782 } }, ["ends"] = { { ["x"] = 0.331, ["y"] = 0.231, ["mapID"] = 35, ["npcID"] = 161782 } }, ["coords"] = { ["mapID"] = 35, ["x"] = 0.331, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 51 } }, ["questGiverID"] = 161782, ["questTurnInID"] = 161782, ["questType"] = "standard", ["sourceQuests"] = { 58455, 58456 } },
[58458] = { ["id"] = 58458, ["name"] = "Pet Battle Challenge: Blackrock Depths", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 51, ["storyline"] = { 58458 }, ["description"] = "Those Shadowy Figures are up to no good again, are you sure you want to face them? If you really want to go back in there, I'm not going to stop you.", ["objectivesText"] = "Stop the Shadowy Figures. Progress: I can teleport you back in there, but you're on your own once you're inside. Good luck.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174360 }, ["starts"] = { { ["x"] = 0.331, ["y"] = 0.231, ["mapID"] = 35, ["npcID"] = 161782 } }, ["ends"] = { { ["x"] = 0.331, ["y"] = 0.231, ["mapID"] = 35, ["npcID"] = 161782 } }, ["coords"] = { ["mapID"] = 35, ["x"] = 0.331, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 51 } }, ["questGiverID"] = 161782, ["questTurnInID"] = 161782, ["questType"] = "standard", ["sourceQuests"] = { 58457 } },
[58460] = { ["id"] = 58460, ["name"] = "Marshals of Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58460 }, ["description"] = "The n'raqi have long served as the commanders and taskmasters of the Old Gods' forces. Their presence on the field of battle shows that this invasion is a coordinated effort rather than a random outbreak of corruption. Led by these faceless masters, the chaotic forces of the Old Gods transform into capable military. We must make it a priority to fell these creatures. Only then might we take the upper hand against N'Zoth.", ["objectivesText"] = "Kill 6 faceless minions of N'Zoth in the Vale of Eternal Blossoms .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 304 }, { ["id"] = 1553, ["amount"] = 311 }, { ["id"] = 1553, ["amount"] = 313 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "group", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58461] = { ["id"] = 58461, ["name"] = "Tomes of Ancient Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58461 }, ["description"] = "In times like these, it becomes necessary for all of the denizens of the Vale to pitch in and do their part. Unfortunately, I have never been much of a fighter, so my usefulness in times of war is limited. However, I may be able to do some good. You see, we know very little about the invaders we face, and knowledge can be a very powerful weapon. I think I have seen tomes carried by some of the k'thir. If you could bring some to me, I may be able to glean something useful from their writings.", ["objectivesText"] = "Collect 8 Tomes of Ancient Madness from k'thir enemies in the Vale of Eternal Blossoms . Progress: Have you managed to procure the tomes?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174196 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 303 }, { ["id"] = 1553, ["amount"] = 310 }, { ["id"] = 1553, ["amount"] = 311 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.836, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58462] = { ["id"] = 58462, ["name"] = "Windows to the Soul", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58462 }, ["description"] = "Were it not enough for our enemy to apply deadly force against us, their minions also strike into the very heart of our defenders. I speak, of course, of the eyes. They peer into the souls of our warriors and produce their darkest fears against them. If we have any hope to defeat this foe, they must be destroyed.", ["objectivesText"] = "Kill 6 Eyes of the Empire in the Vale of Eternal Blossoms . Progress: Is your task complete?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 304 }, { ["id"] = 1553, ["amount"] = 307 }, { ["id"] = 1553, ["amount"] = 319 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154261, ["x"] = 0.838, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154261, ["x"] = 0.838, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58463] = { ["id"] = 58463, ["name"] = "Spawns of Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58463 }, ["description"] = "To see the Vale of Eternal Blossoms recover from the Sha to its former beauty, only to see it tainted by the Old Gods once more, it makes the blood boil! We must root out the Old God's corruption before it can take hold of this land again. I have seen the fleshbeasts that accompany N'Zoth's forces spreading his corruption where they tread. Make sure they tread no longer.", ["objectivesText"] = "Kill 10 fleshbeasts in the Vale of Eternal Blossoms . Progress: I will not see the Vale fall again!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1560, ["amount"] = 65 }, { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 309 }, { ["id"] = 1553, ["amount"] = 320 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58464] = { ["id"] = 58464, ["name"] = "Deephive Decimation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58464 }, ["description"] = "A sect of the mantid swarm calling themselves the \"Deephive\" have taken hold of the Big Blossom mine. These mantid have fully given themselves up to the Old Gods' corruption, making them especially dangerous. We cannot allow the Deephive to run amok in the Vale. Do what must be done.", ["objectivesText"] = "Kill 10 Deephive mantid within the Big Blossom Mine in Vale of Eternal Blossoms . Progress: Have the Deephive been taken care of?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 303 }, { ["id"] = 1553, ["amount"] = 310 }, { ["id"] = 1553, ["amount"] = 321 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58465] = { ["id"] = 58465, ["name"] = "Corruption Manifest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58465 }, ["description"] = "The corruption of the Old Gods is often so foul it manifests itself in physical form. We have seen this with the Sha. This time is no different. Cull this corruption wherever you see it spread. It must not be left to flourish.", ["objectivesText"] = "Kill 8 Putrid Ichors in Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 314 }, { ["id"] = 1553, ["amount"] = 324 }, { ["id"] = 1553, ["amount"] = 343 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58466] = { ["id"] = 58466, ["name"] = "Torment From Beyond", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58466 }, ["description"] = "As if it were not bad enough that N'Zoth seeks to dominate those living in the Vale, my scouts report they now seek to dominate the dead! The Shado-Pan have their hands full defending the living. Can we rely on you to put an end to this disgrace?", ["objectivesText"] = "Release 6 Ancient Pandaren Spirits in the Vale of Eternal Blossoms . Progress: N'Zoth must be stopped.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 307 }, { ["id"] = 1553, ["amount"] = 310 }, { ["id"] = 1553, ["amount"] = 321 }, { ["id"] = 1553, ["amount"] = 325 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58467] = { ["id"] = 58467, ["name"] = "Prisoners of Mind and Body", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58467 }, ["description"] = "N'Zoth's forces struck the Vale suddenly. By the time I and my Shado-Pan arrived, many of the Golden Lotus had already been taken captive by the Old God's forces. Even with our combined might, we have only been able to hold off the invaders from taking more of our people. Those already taken, however, are still within the clutches of the Old God. I know we have had our differences, <name>, but if you could aid us in their recovery, the Shado-Pan would be in your debt.", ["objectivesText"] = "Rescue 6 captive pandaren in the Vale of Eternal Blossoms . Progress: Any news of the captives?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 300 }, { ["id"] = 1553, ["amount"] = 316 }, { ["id"] = 1553, ["amount"] = 324 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58468] = { ["id"] = 58468, ["name"] = "A Growing Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58468 }, ["description"] = "Shado-Pan scouts have spotted evidence of a new mantid hatchery within the Big Blossom mine. It seems these Deephive mantid are looking to create new corrupted spawn to serve N'Zoth. If these eggs were allowed to hatch, a new swarm empowered by the Old God could blacken the skies of the Vale and plunge Pandaria into darkness. We will not allow that to happen, will we?", ["objectivesText"] = "Destroy 6 Corrupted Incubators in the Big Blossom Mine in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 318 }, { ["id"] = 1553, ["amount"] = 336 }, { ["id"] = 1553, ["amount"] = 344 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58469] = { ["id"] = 58469, ["name"] = "Tears in the Vale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58469 }, ["description"] = "As N'Zoth's influence spreads within the Vale, our very reality begins to break down. The Old God's power has created tears in the fabric our world, acting as doorways for his minions to invade from his dark realm. As long as these tears exist, we will never be free from N'Zoth's grasp. Close them, and stem the tide of his corruption!", ["objectivesText"] = "Close 3 Void Tears within the Vale of Eternal Blossoms . Progress: Our reality weakens with each passing day.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 304 }, { ["id"] = 1553, ["amount"] = 312 }, { ["id"] = 1553, ["amount"] = 326 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154261, ["x"] = 0.838, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154261, ["x"] = 0.838, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58470] = { ["id"] = 58470, ["name"] = "Corrupted Curiosities", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58470 }, ["description"] = "I understand that the Black Empire poses a grave threat to Pandaria, but we may also use this as an opportunity! Though we've faced them several times before, very little is known about the Old Gods or N'Zoth's mysterious realm of Ny'alotha. When studying ancient civilizations, we often rely on artifacts to unlock the deepest mysteries lost to time. I wonder if some such artifacts could be found among the Old God's forces? It can't hurt to check, right?", ["objectivesText"] = "Collect 3 Artifacts of the Black Empire from Black Empire Caches in the Vale of Eternal Blossoms . Progress: Did you find anything interesting?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174744 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 301 }, { ["id"] = 1553, ["amount"] = 304 }, { ["id"] = 1553, ["amount"] = 305 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.836, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58471] = { ["id"] = 58471, ["name"] = "Aggressive Notation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58471 }, ["description"] = "Even given the Sha's origins with the Old Gods, we in Pandaria still know very little of them. I would like to take this opportunity to add whatever information I can about them to the archives of the Lorewalkers. Of course, that becomes a bit problematic when they're trying to kill us. That doesn't seem to be a problem for you, though. Could you do me a favor and jot down some notes about what you encounter out there? It could help a great deal towards understanding what we're fighting.", ["objectivesText"] = "Use the Lorewalker's Notebook to gather notes about the faceless, k'thir, and fleshbeasts in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 154200, 174197 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 309 }, { ["id"] = 1553, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 327 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.836, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58472] = { ["id"] = 58472, ["name"] = "A Farewell to Arms", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["series"] = { 58599, 58608, 58624, 62388 }, ["description"] = "The Maldraxxi toil away just behind us. I care not if you consider them allies or traitors, so long as you remove them from Revendreth. Destroy their encampment. Purge it from our soil, and ensure such an affront never occurs again. The means are not important. All that matters is that these heretics remember the consequences of trifling with true power.", ["objectivesText"] = "Destroy the Maldraxxi encampment at Death's End. Progress: Well?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161694, ["x"] = 0.739, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161694, ["x"] = 0.739, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.739, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 161694, ["questType"] = "standard", ["sourceQuests"] = { 58523 }, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58473] = { ["id"] = 58473, ["name"] = "Echoes of Tirna Noch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["description"] = "It is clear that we need more anima than this grove can provide. I may know of a way we can acquire some. Many of the masked fae have been collecting anima for some unknown purpose. I propose we take it back from them. The Wild Hunt has tracked them to Tirna Noch... my former grove. Long has it been since I walked beneath its boughs. Not since it was left to wither so that other groves might survive. I remember it well...", ["objectivesText"] = "Meet Ara'lon in Tirna Noch.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174219, 174269, 180287 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160963, ["x"] = 0.6, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161378, ["x"] = 0.684, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60905 }, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58476] = { ["id"] = 58476, ["name"] = "Bringing the Thunder", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58476 }, ["description"] = "All of the mogu clans are formidable, to be sure, but it is the Zan-Tien that pose the most direct threat to the Golden Lotus. Even now, their numbers are amassing outside the Golden Pagoda. Many of our warriors are fresh-faced and inexperienced. They would not withstand a mogu assault for long. An experienced <class> like you could serve to slow them down significantly. Care to help?", ["objectivesText"] = "Kill 12 Zan-Tien mogu in the Vale of Eternal Blossoms . Progress: What's the word from the front?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 313 }, { ["id"] = 1553, ["amount"] = 463 }, { ["id"] = 1560, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58477] = { ["id"] = 58477, ["name"] = "Through Blood and Dirt and Bone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58477 }, ["description"] = "The Dokani see themselves fit to wield the ancient magic of anima, but their golems and manifestations are but a fraction of anima's true power. Liberate them of their prized substance, so that the Rajani may put it to better use.", ["objectivesText"] = "Collect 100 Anima Globule from Dokani mogu and their allies in the Vale of Eternal Blossoms . Progress: What do you bring?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174210 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 326 }, { ["id"] = 1553, ["amount"] = 361 }, { ["id"] = 1553, ["amount"] = 365 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58478] = { ["id"] = 58478, ["name"] = "No Stone Unbroken", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58478 }, ["description"] = "When the warring clans came into the Vale, the Baruk deigned themselves worthy to lay claim to the ancient grounds of Guo-Lai. They are not. Show these usurpers their place, and you may earn a modicum of favor with the Rajani.", ["objectivesText"] = "Kill 10 Baruk mogu in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 316 }, { ["id"] = 1553, ["amount"] = 334 }, { ["id"] = 1553, ["amount"] = 347 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58479] = { ["id"] = 58479, ["name"] = "Lightning Crashes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58479 }, ["description"] = "The Zan-Tien like to claim mastery over the power of storms, yet they resort to machines to harness lightning from the sky. Show these pretenders that the true power of storm and thunder comes from within. Break their toys, and see how they fare without.", ["objectivesText"] = "Destroy 6 Lightning Rods in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 419 }, { ["id"] = 1553, ["amount"] = 435 }, { ["id"] = 1553, ["amount"] = 483 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58480] = { ["id"] = 58480, ["name"] = "Read the Roots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["description"] = "When my grove withered, I answered the Queen's call and joined the Wild Hunt. Nothing can be done for Tirna Noch. But it wounds me to see it crawling with foes of the forest. We need a great deal of anima. The masked fae must be keeping a stockpile somewhere within the grove--we just need to find it. They likely used soulwebs to collect and move the anima. If I examine them, I should be able to pick up the trail.", ["objectivesText"] = "Investigate the Depleted Soulwebs in Tirna Noch, to find the greatest concentration of anima in the grove. Progress: I sometimes mourn what was lost. And then I remember what work there is still left to do.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174219, 174269, 180287 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161378, ["x"] = 0.684, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161378, ["x"] = 0.684, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 161378, ["questType"] = "standard", ["sourceQuests"] = { 58473 }, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58481] = { ["id"] = 58481, ["name"] = "Rituals of Blood", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58481 }, ["description"] = "Anji and I have fought in many battles, so we know how to handle a few mogu, but the blood magic used by these Dokani is just unsettling! As if it weren't bad enough for them to kill everyone in their path, but to use their corpses to fuel their unholy rituals? I just can't stomach it! Do me a favor. If you ever come across any of these rituals, put a stop to them! Even our enemies don't deserve to be defiled with their dark magic.", ["objectivesText"] = "Destroy 6 Blood Fonts in the Vale of Eternal Blossoms . Progress: I hope you were able to do something about those rituals.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 327 }, { ["id"] = 1553, ["amount"] = 359 }, { ["id"] = 1553, ["amount"] = 365 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58483] = { ["id"] = 58483, ["name"] = "Mementos", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["description"] = "At Heartwood Grove, I heard tales about the fall of Tirna Noch. I never thought that I would see it with my own eyes. It brings me great sadness. And I wonder... if this is the fate that awaits my old grove as well. I can't believe that everything that was once here is truly gone. Perhaps there are still some mementos that can be recovered. Something to remember the fallen.", ["objectivesText"] = "Collect Stolen Mementos from slain enemies in Tirna Noch. Progress: Is this what lies in store for Heartwood Grove? For my old home?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174219, 174269, 180287 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161379, ["x"] = 0.684, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161379, ["x"] = 0.684, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 161379, ["questType"] = "standard", ["sourceQuests"] = { 58473 }, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58484] = { ["id"] = 58484, ["name"] = "Take What You Can", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["description"] = "We know that these invaders have taken over the remains of the grove. But why? Why are they gathering anima and bringing it all to one place? And how did they enter Ardenweald ? We should stay alert and take as much anima as we can find. Perhaps some good can come out of all this loss.", ["objectivesText"] = "Take Plundered Anima from stores in Tirna Noch. Progress: I sometimes mourn what was lost. And then I remember what work there is still left to do.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174219, 174269, 180287 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161378, ["x"] = 0.684, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161378, ["x"] = 0.684, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 161378, ["questType"] = "standard", ["sourceQuests"] = { 58473 }, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58485] = { ["id"] = 58485, ["name"] = "Built to Fall", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 9105, ["mapID"] = 1530, ["description"] = "The Baruk use the forbidden arts of necromancy to trap souls of fallen mogu into the statues that fight for them. These tactics are a disgrace to our people, and cannot be allowed to continue. Break their precious statues, and give them no vessels with which to contaminate with their stolen spirits.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 308 }, { ["id"] = 1553, ["amount"] = 338 }, { ["id"] = 1553, ["amount"] = 428 } }, ["starts"] = { { ["npcID"] = 154444, ["x"] = 0.446, ["y"] = 0.74, ["mapID"] = 1530 } }, ["ends"] = { { ["npcID"] = 154444, ["x"] = 0.446, ["y"] = 0.74, ["mapID"] = 1530 } }, ["coords"] = { ["x"] = 0.446, ["y"] = 0.74, ["source"] = "quest_giver", ["mapID"] = 1530 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 } },
[58486] = { ["id"] = 58486, ["name"] = "He's Drust in the Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["series"] = { 58488 }, ["description"] = "Only the heart of a grove can hold the sheer massive quantity of anima I'm sensing. When my grove was sacrificed, the anima within its heart was reclaimed. Now it brims with anima once again. Anima that was stolen from other groves. We must secure the heart not just for our own sake, but for the entire forest. I suspect that we will not be allowed to simply trot our way in there. Be prepared for anything.", ["objectivesText"] = "Slay Vroth , Bulwark of Thros, and make your way to the Heart of the Fallen Tree.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174219, 174269, 180287 }, ["starts"] = { { ["npcID"] = 161446 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161492, ["x"] = 0.714, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questGiverID"] = 161446, ["questType"] = "standard", ["sourceQuests"] = { 58480, 58483, 58484 }, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58487] = { ["id"] = 58487, ["name"] = "Plunder the Plunderers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58487 }, ["description"] = "Our raids on Lei Shen's treasuries did much to ensure the Thunder King's downfall. I think we should employ the same strategy here. Seek out the hoarded plunder of the mogu clans and relieve them of it. We must do all we can to disrupt their advance.", ["objectivesText"] = "Loot 3 Mogu Plunder from the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 304 }, { ["id"] = 1553, ["amount"] = 399 }, { ["id"] = 1553, ["amount"] = 407 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58488] = { ["id"] = 58488, ["name"] = "Go for the Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["series"] = { 58486 }, ["description"] = "I was right! A great deal of anima has been stored inside the heart of the grove. The Drust must have collected it from all over Ardenweald . And now, we will take it back. Quickly, destroy that barrier and grab the heart. Niya and I will protect you.", ["objectivesText"] = "Destroy the barrier and collect the Heart of Tirna Noch . Progress: We will reclaim this anima. The Drust will not use it for their own ends.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 6948, 25712, 25713, 25714, 36739, 50375, 50376, 50377, 50378, 50384, 50386, 50387, 50388, 50397, 50398, 50399, 50400, 50401, 50402, 50403, 50404, 52569, 52570, 52571, 52572, 54921, 54922, 57320, 57321, 57322, 58991, 58992, 58993, 60709, 60710, 64507, 64508, 64509, 64510, 64511, 64512, 64513, 64514, 112603, 112604, 112605, 112606, 129250, 129251, 129252, 129253, 129254, 129255, 129256, 129257, 131300, 131417, 131557, 147442, 156932, 159901, 159902, 159903, 159904, 159905, 159906, 159907, 159908, 160906, 160907, 160908, 160909, 160910, 160911, 160912, 160913, 160914, 160915, 160916, 160917, 160918, 160919, 160920, 160921, 174219, 174269, 175648, 175649, 175650, 175651, 175713, 175740, 176832, 176921, 176922, 179500, 179508, 179517, 179537, 179547, 179562, 179584, 179604, 180287, 180944, 181368, 181377, 181407, 181409, 181410, 181418, 181422, 181423, 181424, 181425, 181430, 181457, 181458, 181459, 181477, 181479, 181506, 181541, 181569, 181577, 181587, 181591, 181603, 181605, 181627, 181632, 181633, 181635, 181636, 181637, 181702, 181704, 181738, 181745, 182128, 182203, 182385, 182480, 182649, 182675, 182736, 182743, 183167, 183402, 183468, 183469, 183473, 183481, 183482, 183486, 183489, 184294, 184362, 184373, 184374, 184381, 184382, 184383, 184384, 184587, 184765, 184766, 184767, 184768, 189865, 198002, 198003, 198004, 198006, 198009, 198034, 198105, 198612, 200597, 204581, 204589, 204597, 204605, 219764, 219765, 251547, 253021 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161492, ["x"] = 0.714, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161492, ["x"] = 0.714, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58486 }, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58490] = { ["id"] = 58490, ["name"] = "Deadly Reminder", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58490 }, ["description"] = "Our defense is tenuous at best, but the enemy is still hesitant to attack. As long as they fear us, they won't be probing our defenses. You must keep the pressure on the enemy. Attack their positions all along our line.", ["objectivesText"] = "Eliminate Enemy forces and positions.", ["rewardXP"] = 8165, ["rewardItems"] = { 181811 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Lich Forces Eliminated", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58496] = { ["id"] = 58496, ["name"] = "An Unwelcome Advisor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8568, ["mapID"] = 84, ["storyline"] = { 58496, 58498, 58502, 58506 }, ["description"] = "<The envelope contains a message from King Anduin Wrynn .> <name>, Even with the forces of the Horde and Alliance working together, we still have found no trace of N'Zoth's forces. Ever since his release, the Old God has evaded us at every turn. The Light only knows what ill he has in store for Azeroth. Meet me in Stormwind Keep. We must put a plan together to uncover N'Zoth's schemes before it is too late! Light grant you haste, King Anduin Wrynn", ["objectivesText"] = "Speak with King Anduin Wrynn in Stormwind Keep. Progress: What is it?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.681, ["y"] = 0.224, ["mapID"] = 1161, ["objectID"] = 369893 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.856, ["y"] = 0.316667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 } }, ["db2DetailThemeID"] = 13, ["db2PoiUiMapID"] = 84 },
[58498] = { ["id"] = 58498, ["name"] = "Return of the Warrior King", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 84, ["storyline"] = { 58496, 58498, 58502, 58506 }, ["description"] = "Ye've done a great deal fer Azeroth, hero, but unfortunately I'm gonna have tae ask ye tae do more. N'Zoth is on the loose, an there's no tellin' when or where he'll strike. This battle is one ye can't face alone. When the time comes, ye'll have my hammer at yer side! But first, we'll need tae fetch it.", ["objectivesText"] = "Walk with Magni and retrieve Fearbreaker in Stormwind Keep. Progress: Need something, champion?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 175151 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58496 }, ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[58502] = { ["id"] = 58502, ["name"] = "Where the Heart Is", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 84, ["storyline"] = { 58496, 58498, 58502, 58506 }, ["description"] = "It's time we put Wrathion's plans in tae motion. He'll be headin' back tae the Chamber of Heart, so we should meet him there.", ["objectivesText"] = "Return to the Chamber of Heart.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 6948, 227669 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 10833 } }, ["questTurnInID"] = 154532, ["questType"] = "standard", ["sourceQuests"] = { 58498 }, ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[58504] = { ["id"] = 58504, ["name"] = "Accusatory Missive", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["description"] = "We have received word from Revendreth. It seems that Maldraxxi conspirators have been found skulking within their realm. An emissary from Sinfall wishes to discuss the anima reserves we discovered. Join me. We depart immediately.", ["objectivesText"] = "Meet with the Accuser in the Halls of Atonement in Revendreth.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.498, ["y"] = 0.506, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161461, ["x"] = 0.72, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 12876 } }, ["questGiverID"] = 161907, ["questType"] = "standard", ["sourceQuests"] = { 62161 }, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58505] = { ["id"] = 58505, ["name"] = "Planned Demise", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58505 }, ["description"] = "Our defense is tenuous at best, but the enemy is still hesitant to attack. As long as they fear us, they won't be probing our defenses. You must keep the pressure on the enemy. Attack their positions all along our line.", ["objectivesText"] = "Eliminate Enemy forces and positions.", ["rewardXP"] = 8165, ["rewardItems"] = { 174231, 174232, 174233 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 1, ["amount"] = 1, ["objectID"] = 174231 }, { ["orderIndex"] = 1, ["type"] = 1, ["amount"] = 1, ["objectID"] = 174232 }, { ["orderIndex"] = 2, ["type"] = 1, ["amount"] = 1, ["objectID"] = 174233 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58506] = { ["id"] = 58506, ["name"] = "Network Diagnostics", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 58496, 58498, 58502, 58506, 58582, 58583 }, ["description"] = "Unfortunately, we've got no clue where N'Zoth has been lurking since his escape. We do, however have an idea where he might strike. Back when the keepers were imprisoning the Old Gods, they built defense mechanisms against their corruption into the titan forges. If N'Zoth wants tae corrupt Azeroth, he'll have tae go through them first. Fortunately, we've got ourselves hooked up tae them now, so we can monitor them from here. Go ahead an' take a look.", ["objectivesText"] = "Activate the Titan Consoles in the Chamber of Heart to check the status of the titan forges throughout Azeroth. Progress: The consoles should tell ye how the forges are holdin' up.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["ends"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["coords"] = { ["mapID"] = 1473, ["x"] = 0.501, ["y"] = 0.591 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questGiverID"] = 152206, ["questTurnInID"] = 152206, ["questType"] = "standard", ["sourceQuests"] = { 58502, 58583 }, ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[58515] = { ["id"] = 58515, ["name"] = "Scrounging for Scrolls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58515 }, ["description"] = "The kyrian are known for their collection of scrolls and writings. I'm particularly interested in their texts regarding those who have joined their ranks. Why is it that some of the greatest fighters are sent to Bastion and not to Maldraxxus? Perhaps research can divine the answer.", ["objectivesText"] = "Collect information on the kyrian from the Temple of Humility. Progress: Let's see, where did that paper go?", ["rewardXP"] = 8165, ["rewardItems"] = { 175275, 182486, 182495, 182504, 182513, 183142, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159198, ["x"] = 0.552, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57601 } },
[58518] = { ["id"] = 58518, ["name"] = "There's Always a Paper Trail", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58382, 58383, 58384, 58385, 58386, 58387, 58388, 58389, 58391, 58392, 58393, 58394, 58395, 58426, 58443, 58518, 61077 }, ["description"] = "I noticed that you were surprised to find those strange weapons here. I sense the essence of their power as well. It is strangely familiar... We must discover where the weapons came from and who imbued them with such power. <Kael'thas smiles.> If you and I present the proof to the Accuser together, perhaps she shall allow us to hunt down whoever is behind all of this!", ["objectivesText"] = "Discover proof of who's supplying the venthyr with Maldraxxian weapons. Progress: You found something?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174211, 174278 }, ["starts"] = { { ["npcID"] = 161427 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161421, ["x"] = 0.458, ["y"] = 0.5145 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.5145 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questGiverID"] = 161427, ["questType"] = "standard", ["sourceQuests"] = { 58443 }, ["questLines"] = { { ["id"] = 1017, ["name"] = "Confronting Sin", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1017, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58523] = { ["id"] = 58523, ["name"] = "You're Dead To Me", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["description"] = "Your cooperation is expected, but I await results. Our reconnaissance has revealed a Maldraxxi encampment in the Endmire. We speculate that your kind have been siphoning the Master's stockpiles of anima. I have called for a carriage to take us there. Let us make haste.", ["objectivesText"] = "Follow the Accuser to the Maldraxxi encampment.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 13444, 13446, 21316, 21317, 34119, 56875, 56876, 56877, 56878, 56879, 56880, 56881, 56882, 60924, 60925, 60926, 60927, 61497, 61499, 61501, 65666, 65689, 66067, 79731, 108972, 108975, 108976, 130219, 131587, 131894, 138819, 138820, 138821, 138822, 138823, 138824, 138837, 142273, 143488, 157003, 160000, 160001, 160002, 160003, 161168, 161169, 161170, 161171, 181501, 181502, 181507, 181645, 181647, 181649, 181653, 181659, 181660, 181661, 181662, 181663, 181671, 181672, 181673, 181674, 181675, 181676, 181677, 181678, 181679, 181680, 181681, 181682, 181802, 182610, 182753, 183744, 184305, 184772, 184773, 184774, 184775, 184776, 184843, 197892, 197895, 197900, 237861, 237873, 237878, 237892 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161461, ["x"] = 0.72, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161694, ["x"] = 0.739, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58504 }, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58524] = { ["id"] = 58524, ["name"] = "Sparkles Rain from Above", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58473, 58480, 58483, 58484, 58486, 58488, 58524 }, ["series"] = { 58589 }, ["description"] = "You found the heart of the grove! And it's full of anima! The Drust don't seem to like the idea of you taking it from them. They're massing in great numbers all over the forest! We need to get you and the others out of here safely. I can help. How do you feel about dishing out a little sparkly mayhem?", ["objectivesText"] = "Speak with Lady Moonberry and escape Tirna Noch.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174219, 174269, 175767, 180287 }, ["rewardChoices"] = { 175767 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161494, ["x"] = 0.714, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58488 }, ["questLines"] = { { ["id"] = 1025, ["name"] = "The Fallen Tree", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1025, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1025, ["questLineOrder"] = 22 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58525] = { ["id"] = 58525, ["name"] = "The Two Sides of History", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58525 }, ["description"] = "You mortals always say that history is written by the victors. But in the Shadowlands, I have found that to be untrue. Everyone has their own version of events. I would like to know them all. There was an author of history books who made her abode in Revendreth's Darkfall Tower. She wrote from the venthyr's perspective of various incursions and battles alongside the Primus. If we could find copies of her works...", ["objectivesText"] = "Find copies of \" On Bone and Stone \" and \" The Malice of Maldraxxus .\"", ["rewardXP"] = 8165, ["rewardItems"] = { 182486, 182495, 182504, 182513, 183142, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159198, ["x"] = 0.552, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57601 } },
[58530] = { ["id"] = 58530, ["name"] = "Hidden Mirror", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["series"] = { 61050 }, ["description"] = "If Renathal is going to put the Harvesters' medallions to use, he's going to need a conduit to focus that power. Denathrius's corruption taints the forges of Revendreth. Our best option is in Bastion. As denizens of Revendreth, Bastion will not allow us to enter through Oribos. We will need you to activate a mirror hidden away there long ago. Take this. We concealed it at a rarely used site, the Veiled Enclave. There should be no one there, especially with the drought.", ["objectivesText"] = "Use Laurent's Compact Looking Glass to reveal the Hidden Mirror in Bastion.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 180356 }, ["starts"] = { { ["x"] = 0.438, ["y"] = 0.464, ["mapID"] = 1699, ["npcID"] = 161514 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 162213, ["x"] = 0.501333, ["y"] = 0.306667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.501333, ["y"] = 0.306667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10986 } }, ["questGiverID"] = 161514, ["questType"] = "standard", ["sourceQuests"] = { 61050 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58555] = { ["id"] = 58555, ["name"] = "A Tense Reunion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "We are looking for the forgelite prime, Mikanikos. Only he will be able to craft the device we need. I've seen some of his creations. Truly impressive constructs and weaponry that rival even the mightiest of us stoneborn. When last I encountered him, it was at his workshop. A place of wonders known as the Eternal Forge. We will meet you there. Traveling as a group may draw too much attention.", ["objectivesText"] = "Meet General Draven and Theotar at the Eternal Forge.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 162213, ["x"] = 0.501333, ["y"] = 0.306667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 161526, ["x"] = 0.502667, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.501333, ["y"] = 0.306667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58530 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58557] = { ["id"] = 58557, ["name"] = "Assistance from Sinfall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "In order to defeat the Forsworn, the Crest needs an artifact that embodies repentance, atoning for past mistakes and moving forward. I have an artifact in mind. Long ago, many souls from Revendreth arrived in Bastion . Purer souls than we have ever received from Revendreth. They bore the mark of the Seal of Contrition, a focus that expedited their cleansing. Go to Revendreth and find this seal so that we may harness its power.", ["objectivesText"] = "Meet with The Curator in Darkhaven in Revendreth.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1525, 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 61878 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58558] = { ["id"] = 58558, ["name"] = "Overhead Intelligence", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "The Countess knows the fates and goings-on of every noble in Revendreth. It is the best way to keep them in her debt. However, she has a dark secret. Despite what she may say... she was once mortal. We will need to find where she keeps her sinstone. No easy feat, of course. We will need to gather some intel. The venthyr of the Chalice District are constantly gossiping. Collect their letters from the couriers until you learn something of interest.", ["objectivesText"] = "Collect the Rumors of Favor from Chalice Couriers in the Chalice District.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5655, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58557 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58559] = { ["id"] = 58559, ["name"] = "Eyes of the Master", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "I worry about entering the city. I'm sure you have noticed how well we... stand out here. Denathrius's loyalists have eyes everywhere, and no more dedicated soldiers than the stoneborn. Their eyes and ears watch over the Chalice District. Take out their leaders so none can report our presence here before we acquire the seal.", ["objectivesText"] = "Kill Evaala the All-Seeing , Guardian Mastrus , and Keraal the Ripper in the Chalice District. Progress: The stoneborn forces can never be truly defeated, but they can be quelled for a time.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 130222, 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.538571, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58557 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58560] = { ["id"] = 58560, ["name"] = "Gothic Fashion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "Making my way into the city unseen was not as simple as I thought. I trekked through some mud, where I came across these... small men. Perhaps Kleia is right. I draw far too much attention here to be of much use. Perhaps I can disguise myself? Please, help me by gathering some venthyr clothing as a disguise.", ["objectivesText"] = "Collect 5 articles of venthyr clothing from Chalice Residents and Garment Trunks in the Chalice District.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.521, ["mapID"] = 1525, ["npcID"] = 165011 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161543, ["x"] = 0.599333, ["y"] = 0.438667 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.599333, ["y"] = 0.438667 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questGiverID"] = 165011, ["questType"] = "standard", ["sourceQuests"] = { 58557 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58561] = { ["id"] = 58561, ["name"] = "Shards of the Countess", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "The venthyr travel long distances through enchanted mirrors. The keys we look for are not as we have in Bastion , but rather shards of a mirror that will lead to the sinstone's location. Based on the intel you found, we know which three houses hold these shards. Primrose, Darkvein, and Sinfang. Go to their manors and retrieve the shards. We will find the frame to piece them into.", ["objectivesText"] = "Collect the 3 Shards of the Countess .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174374, 174375, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.538571, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58558, 58559, 58560 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58562] = { ["id"] = 58562, ["name"] = "Collecting Dust", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "If I know the Countess, which I do, her sinstone will have stronger protection than mere keys. She is quite fond of curses to protect her gateways. I am capable of creating a residue that should protect us, but it requires the petals of a specific flower you can find in Redelav gardens. Collect the petals of these flowers so that I may protect us from the dangers to come.", ["objectivesText"] = "Collect 30 Death Lotus Petals from Death Lotuses in the Redelav District. Progress: I will need many petals to protect the four of us.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5655, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58558, 58559, 58560 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58563] = { ["id"] = 58563, ["name"] = "Through Glass", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "The mirror frame rests at the bottom of Redelav Hall. Kleia and Pelagos wait there. With these shards, I can piece it together. We will go through, grab the sinstone, and go face the Countess. Let nothing stand in our way.", ["objectivesText"] = "Go through the mirror, then collect the Countess's Sinstone . Progress: Venthyr carry their pasts as a burden, a weight upon them. The kyrian stand free of ours.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174382, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084, 181286 }, ["rewardChoices"] = { 181286 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5655, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58561, 58562 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58564] = { ["id"] = 58564, ["name"] = "Sins of the Past", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "The Countess built her reputation on being a native venthyr, never a soul. Revealing her sinstone to the world would be catastrophic. This is the leverage we need for the information we seek. She will tell us where Alwin is. Where the seal is. This mirror leads to her estate. I will follow behind you as backup, but the kyrian shall wait here. Don't let her threaten you. You hold the power.", ["objectivesText"] = "Go through the mirror and face the Countess . Progress: You are lucky that the Curator is by your side, Maw Walker. If you dared this stunt on your own, you would never see your precious Bastion again.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161996, ["x"] = 0.58, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5655, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58563 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58565] = { ["id"] = 58565, ["name"] = "Land of Light", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "The Ember Ward is filled with outcasts from Revendreth society, whether they rebelled, crossed a noble, or simply looked at Denathrius wrong. It is a Light-scorched land that drives venthyr mad, unless they manage to stay within the shadows. If Alwin is there, it may be too late. Let us visit Theotar at the Sanctuary of the Mad. I'm sure he will be pleased to see you.", ["objectivesText"] = "Meet Theotar at the Sanctuary of the Mad in the Ember Ward.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161544, ["x"] = 0.5655, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161515, ["x"] = 0.32, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5655, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58564 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58566] = { ["id"] = 58566, ["name"] = "Actions Speak Louder than Words", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "<The ash ghoul inspects you, checking your weapons and armor closely. He shifts his eyes from you to your kyrian companions before checking back in with Theotar, who nods to him. Alwin motions for you to follow him.>", ["objectivesText"] = "Follow Mindscorched Alwin through the Ashen Traverse.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161553, ["x"] = 0.345333, ["y"] = 0.513333 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161553, ["x"] = 0.345333, ["y"] = 0.513333 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.345333, ["y"] = 0.513333 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58565 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58567] = { ["id"] = 58567, ["name"] = "Skulking in the Darkness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "I had only heard tales of the Ember Ward before now. It's breathtaking... yet terrible. The Light burns the venthyr here, scorching their flesh and driving them mad. The only reprieve is darkness, but thugs have taken over every inch of shelter outside of this sanctuary. There is no redemption for them. Only justice.", ["objectivesText"] = "Kill 8 outcast venthyr in the Ashen Traverse.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.538571, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58565 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58568] = { ["id"] = 58568, ["name"] = "Light Respite", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["description"] = "We passed many ash ghouls on the way here, screaming in pain from their Light-dispensed burns. And after meeting Alwin and the others here, my heart aches for them. They have lost much of who they once were, and suffer daily for it. Please, collect some berries from the Ashen Traverse. I believe I could impart anima into them to create a healing salve to soothe their wounds. It is the least I can do.", ["objectivesText"] = "Collect 25 Brushberries from the Ashen Traverse. Progress: The denizens of the Ember Ward have suffered enough for their mistakes. The Light goes too far in its punishment.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.538571, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58565 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58569] = { ["id"] = 58569, ["name"] = "The Folly of Envy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["series"] = { 58570, 58571 }, ["description"] = "<Alwin points at a venthyr on the ledge above. He lets out a slight, low rumble.>", ["objectivesText"] = "Kill Duke Vielle and retrieve the Seal of Contrition . Progress: Alwin has brought us far. We must retrieve the Seal!", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161553, ["x"] = 0.345333, ["y"] = 0.513333 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.345333, ["y"] = 0.513333 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58566, 58567, 58568 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58570] = { ["id"] = 58570, ["name"] = "Parting Words", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1525, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["series"] = { 58569, 58571 }, ["description"] = "With the seal in hand, we must return to Bastion . Alwin has received his justice. He has bequeathed the seal to our care. Let us say our goodbyes at the Sanctuary of the Mad, then head home. I look forward to returning to the blue skies and open fields of Bastion .", ["objectivesText"] = "Speak to the Curator at Sanctuary of the Mad, then return to Elysian Hold. Progress: You return! With good news, I hope?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084, 184353 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161540, ["x"] = 0.538571, ["y"] = 0.464571 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.538571, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 161540, ["questType"] = "standard", ["sourceQuests"] = { 58569 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58571] = { ["id"] = 58571, ["name"] = "The Seal of Contrition", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58557, 58558, 58559, 58560, 58561, 58562, 58563, 58564, 58565, 58566, 58567, 58568, 58569, 58570, 58571 }, ["series"] = { 58569, 58570 }, ["description"] = "Preparations for the Seal are complete. Go, insert it into the Crest. Be delicate, yet firm! Move with purpose, but a steady hand.", ["objectivesText"] = "Place the Seal of Contrition in the Crest of Ascension. Progress: <The orb hangs in front of you. The Seal in your hand pulses quickly.>", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174289, 174333, 174336, 174357, 174359, 174454, 174497, 174498, 176052, 176053, 176054, 176055, 176082, 176083, 176084, 177050, 178153, 179943 }, ["rewardChoices"] = { 178153, 177050, 179943, 174289 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.457, ["y"] = 0.565, ["mapID"] = 1707, ["npcID"] = 162149 } }, ["ends"] = { { ["x"] = 0.457, ["y"] = 0.565, ["mapID"] = 1707, ["npcID"] = 162149 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.457, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 162149, ["questTurnInID"] = 162149, ["questType"] = "standard", ["sourceQuests"] = { 58570 }, ["questLines"] = { { ["id"] = 1092, ["name"] = "The Seal of Contrition", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1092, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58575] = { ["id"] = 58575, ["name"] = "Stuff We All Get", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "A lot of competitors meet their end in the Theater of Pain. But their weapons are still good as new! It can get expensive to equip a fresh recruit, especially if you're not sure they'll survive their first bout. That's why we outfit them with \"slightly used\" armaments. Gather them up for me, would you? Can't let a good weapon go to waste!", ["objectivesText"] = "Collect 12 Weapons of the Fallen . Progress: The weapons you collect could be wielded by a future champion!", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59750, 59781 }, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58582] = { ["id"] = 58582, ["name"] = "Return of the Black Prince", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8499, ["mapID"] = 84, ["storyline"] = { 58506, 58582, 58583 }, ["description"] = "<The envelope contains a message from Valeera Sanguinar .> <name>, I have just returned from a meeting with King Wrynn in Stormwind. We have much to discuss. Meet me at the Great Seal with haste. Al diel shala, Valeera", ["objectivesText"] = "Speak with Valeera Sanguinar at the Great Seal in Dazar'alor. Progress: Yes?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 200710 }, ["starts"] = { { ["x"] = 0.585, ["y"] = 0.626, ["mapID"] = 862, ["objectID"] = 369894 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 161458, ["x"] = 0.850667, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.850667, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2DetailThemeID"] = 5, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165 },
[58583] = { ["id"] = 58583, ["name"] = "Where the Heart Is", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9598, ["mapID"] = 84, ["storyline"] = { 58506, 58582, 58583 }, ["description"] = "The Speaker has requested that I send you to aid him and Wrathion in their efforts. You have proven yourself a great ally to Azeroth, and I suspect you will have a big part to play in the coming battles. Let us hope that the rest of the Horde and Alliance can put aside their squabbles to face a common enemy.", ["objectivesText"] = "Meet Magni Bronzebeard in the Chamber of Heart.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 6948 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 161458, ["x"] = 0.850667, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 161458, ["x"] = 0.850667, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.850667, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9598 } }, ["questTurnInID"] = 161458, ["questType"] = "standard", ["sourceQuests"] = { 58582 }, ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[58584] = { ["id"] = 58584, ["name"] = "Right our Wrongs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "General Kaal was sent here on a mission for Denathrius long ago. On that mission, they concealed anima siphons , making their presence impossible to detect, to limit the amount of anima this workshop could use. That destabilized this area. The Forsworn must have noticed this and exploited the weakness. These previous actions are in opposition to our goal. Take Theotar and destroy those siphons.", ["objectivesText"] = "Speak to Theotar at the Eternal Forge. Then, reveal and destroy 5 Concealed Anima Siphons .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180934, 180936, 180937, 180938 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 161526, ["x"] = 0.502667, ["y"] = 0.218667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 161526, ["x"] = 0.502667, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.218667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58555 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58585] = { ["id"] = 58585, ["name"] = "No Friend of Mine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "Tools. I cannot work without my tools! Famos, my former apprentice, stole them all when she went to the Forsworn. It breaks my heart. She had so much promise. She must be stopped.", ["objectivesText"] = "Kill Famos in the Eternal Forge and collect Mikanikos 's Toolchest. Progress: I need my tools. My work cannot be done without them.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174466 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58555 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58586] = { ["id"] = 58586, ["name"] = "The Right Stuff", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "Building something that can help in your mission will require some metal. The constructs of the Forsworn have metal parts, suitable for what we need. Tainted by the Forsworn, they will need some additional work. Collect their metal and smelt them in the flames of the Eternal Forge to purge the corruption.", ["objectivesText"] = "Kill Forsworn constructs and collect and smelt 5 Tainted Centurion Components . Progress: Do you have the metal?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173880, 174465 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58555 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58589] = { ["id"] = 58589, ["name"] = "The Restless Dreamer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["series"] = { 58524 }, ["description"] = "Now that we have the anima we need, we must attune the heart of Tirna Noch to the shrines of Hibernal Hollow. Then we can bring the wildseed's nightmares into the light and dispel them. Take the heart to the shrines just outside of Hibernal Hollow, in the Dreamshrine basin. Then bring the heart back to the wildseed to complete the preparations for the ritual. But be careful. Minions of the Drust seem to be amassing near the grove.", ["objectivesText"] = "Attune the filled heart of the tree at the shrines in the Dreamshrine Basin. Progress: The spirit dreams.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60572 }, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58590] = { ["id"] = 58590, ["name"] = "Visions of the Dreamer: Origins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["series"] = { 58593, 60578 }, ["description"] = "The spirit within the wildseed dreams of her birth and youth, in the primordial days of her world. Go to the first Dreamshrine outside of Hibernal Hollow. Meditate at the shrine, and soothe this vision of how her life began.", ["objectivesText"] = "Grapple with the spirit's vision of their origin. If you leave the Vision, interact with a Dreamer's Vision portal in Dreamshrine Basin to enter again.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58589, 58591, 58592 }, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58591] = { ["id"] = 58591, ["name"] = "Despoilers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["description"] = "Your efforts at Tirna Noch have enraged the Drust. Those creatures of decay and destruction swell at our borders, and already they pierce our defenses. Now we see their real faces, and know the true nature of our foe. Strike at them. It will buy us time for you to conduct Dreamweaver's ritual.", ["objectivesText"] = "Slay Witherscorn Drust and Blighted, and vanquish Skell the Despoiler .", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58524 }, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58592] = { ["id"] = 58592, ["name"] = "Caring for the Caretakers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["description"] = "The Drust attacked so quickly, they captured some of the spirit tenders of this grove! It's not an easy job to do, between the drought and monsters and everything. I should know. Please, see if you can get them out of whatever terrible magic those invaders have cast on them.", ["objectivesText"] = "Free Spirit Tenders in the Dreamshrine Basin.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 162577 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60572 }, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58593] = { ["id"] = 58593, ["name"] = "End of the Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["series"] = { 58590, 60578 }, ["description"] = "The time has come. The ritual will be complete when you have fully entered into the spirit's dreams. It will be as if you are her, in every aspect. She relives the moment of her death over and over again. It torments her. Something about how she ended... she had no control over her actions. She hurt the ones she loved. Speak to me when you are ready to immerse yourself in her nightmare of the end.", ["objectivesText"] = "Witness the end of the spirit's life. Progress: Have you entered into the spirit's final dream and witnessed her fate?", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 175647, 175660, 175661, 175662 }, ["rewardChoices"] = { 175661, 175647, 175660, 175662 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58590, 60578 }, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58595] = { ["id"] = 58595, ["name"] = "Pillars of Oblivion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58595 }, ["description"] = "In ages past, the black obelisks of the Old Gods would herald the coming of their forces. The dark conjurers among the k'thir and n'raqi would utilize these monuments to establish footholds in our world and usher in more of the Old Gods' minions. Today, we see these very same obelisks littering the battlefields. So long as they stand, N'Zoth's forces will be without end. Make sure they do not.", ["objectivesText"] = "Destroy 6 Black Empire Obelisks in the Vale of Eternal Blossoms . Progress: Is your task complete?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1560, ["amount"] = 60 }, { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 301 }, { ["id"] = 1553, ["amount"] = 302 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
