[58599] = { ["id"] = 58599, ["name"] = "Drive A Dredge Between Them", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["series"] = { 58472, 58608, 58624, 62388 }, ["description"] = "First, we ruin their operation. Questions can come later. I scouted from the overlook as we rode in. Necromancers charge crystals full of siphoned anima. Three dredgers stack them onto carts. Kill those dredgers and everything will grind to a halt.", ["objectivesText"] = "Kill the 3 large dredgers. Progress: Are you ready?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["npcID"] = 161474 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questGiverID"] = 161474, ["questType"] = "standard", ["sourceQuests"] = { 58523 }, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58600] = { ["id"] = 58600, ["name"] = "A Perfect Circle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "I've come up with the perfect design to fit your needs--a crown capable of channeling the powers of the Harvesters. I need one more tool to put it together, a mold. Circular objects difficult to get right. Go up to my old storage. A perfect mold exists there. I'm sure of it. Perhaps in one of my old trunks. Go rummage around for it, will you?", ["objectivesText"] = "Search for the Perfected Circlet Mold . Progress: Crown must be perfect!", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174330, 180448, 180449, 180450 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58584, 58585, 58586 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
