[58603] = { ["id"] = 58603, ["name"] = "Phaestus, Genesis of Aeons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "Missing something sacred. Forsworn ransacked our shrine to the First Forgelite and took her hammer. My hammer! Defeat their commander, retrieve Phaestus. You must go now!", ["objectivesText"] = "Collect Phaestus, Genesis of Aeons from Overseer Atticus. Progress: Without Phaestus, we cannot forge your crown!", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174061, 174296, 177057, 178160, 179947 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58584, 58585, 58586 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
