[58606] = { ["id"] = 58606, ["name"] = "A Bit of Investigation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58606 }, ["description"] = "$p, this may be the discovery of a lifetime! I cannot yet say with absolute certainty, but I have a suspicion that these insects are known as the aqir. The League has few intact records, but the last mention of these creatures describes a great war waged between the C'Thraxxi, aqir, and early troll civilizations. We had assumed they were driven to extinction, but they may have simply been... rebuilding. Could you please collect some samples for me to examine?", ["objectivesText"] = "Collect 16 Aqir Bits . Progress: Have you managed to acquire the samples?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174356 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 164196, ["x"] = 0.28, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 164196, ["x"] = 0.28, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 57971 } },
[58608] = { ["id"] = 58608, ["name"] = "It's Treason, Then", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["series"] = { 58472, 58599, 58624, 62388 }, ["description"] = "We've halted their efforts, but we still have more to do. Sin'dane must have sent someone to oversee the encampment. Find and slay whoever is in charge. Only then can we be sure their work has ended.", ["objectivesText"] = "Kill Lady Ouix'ara . Progress: Still more schemes...", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 182386 }, ["starts"] = { { ["npcID"] = 161474 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161865, ["x"] = 0.78, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questGiverID"] = 161474, ["questType"] = "standard", ["sourceQuests"] = { 58472, 58599 }, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58609] = { ["id"] = 58609, ["name"] = "Taking The Seat", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 63212 }, ["description"] = "A wise choice, <name>. Under your command, we will restore honor and glory to Maldraxxus. Your strength can change the Shadowlands for the better. Only with the Necrolords will you reach your full potential. For now, make your way to the Seat of the Primus. Baroness Draka will meet you there and guide you further.", ["objectivesText"] = "Report to Baroness Draka at the Seat of the Primus in Maldraxxus.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.741, ["mapID"] = 1670, ["npcID"] = 171821 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.741, ["mapID"] = 1670, ["npcID"] = 171821 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.429, ["y"] = 0.741 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 171821, ["questTurnInID"] = 171821, ["questType"] = "standard", ["sourceQuests"] = { 57878, 62000, 63212 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[58610] = { ["id"] = 58610, ["name"] = "The Speaker of Elune", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "Fortune smiles upon us, <name>. We have found a soul in Ardenweald who was once a Night Warrior in life, as Tyrande is now. His name is Thiernax . I am told he assists in tending to the spirits resting in the Garden of Night. Seek him out and petition him for aid. I pray he will have wisdom to share.", ["objectivesText"] = "Find Thiernax near the Queen's Garden. Progress: Oh, dear.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.447, ["y"] = 0.39, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161786, ["x"] = 0.396, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questGiverID"] = 160262, ["questType"] = "standard", ["sourceQuests"] = { 59821 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58615] = { ["id"] = 58615, ["name"] = "Whispers in the Dark", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12905, ["mapID"] = 1473, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472, 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 57220, 57221, 57222, 57290, 57362, 57373, 57374, 58496, 58498, 58502, 58506, 58615, 58631, 58634, 58737 }, ["description"] = "Did ye hear that as well? That cannae be good. If N'Zoth gains access tae this chamber, we'll all be done for! We need tae figure out where he's accessing the chamber and shut it down, before he does more than just whisper at us!", ["objectivesText"] = "Find the source of N'Zoth's whispers in the Chamber of Heart.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 119036 }, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 161805 } }, ["ends"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 161805 } }, ["coords"] = { ["mapID"] = 1473, ["x"] = 0.501, ["y"] = 0.591 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12905 } }, ["questGiverID"] = 161805, ["questTurnInID"] = 161805, ["questType"] = "standard", ["sourceQuests"] = { 57374 }, ["questLines"] = { { ["id"] = 1028, ["name"] = "Whispers in the Dark", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 27, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 26, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[58616] = { ["id"] = 58616, ["name"] = "Forging a Champion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "Of all the souls who have reached that stone, only you discovered its true purpose. I am no zealot, but clearly there is a deeper meaning in this. We would be wise to investigate further. Find Bonesmith Heirmir at her forge. She is the most renowned smith in Maldraxxus , and the last remaining apprentice of the Primus himself. She will know what course to take.", ["objectivesText"] = "Speak with Bonesmith Heirmir about your runeblade. Progress: Something else?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.660667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57516 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58617] = { ["id"] = 58617, ["name"] = "Maintaining Order", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "Communication is the key to victory. The greatest strategists are rendered useless if their orders go unheard. Deliver my orders to Summoner Perex, Drill Sergeant Telice , and Secutor Mevix . And do it quickly. Every moment we waste is one our enemy will have to their advantage!", ["objectivesText"] = "Deliver orders to Summoner Perex, Drill Sergeant Telice , and Secutor Mevix .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57514 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58618] = { ["id"] = 58618, ["name"] = "Ossein Enchantment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "A potent blade requires potent components. I know of something that would suit our needs. Recently a monstrosity trained by the constructs was snared by our soldiers at the eastern side of our stronghold. Vyraz insists we can siphon \"intelligence\" from the beast's mind. Hmph. The will of the Primus trumps the desires of an ambitious baron! The bones of that beast would forge the perfect hilt for this blade. I say you lay claim to them.", ["objectivesText"] = "Slay Marrowjaw and collect an Empowered Bone from its corpse. Progress: Brave enough to manage this?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.418667, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58616 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58619] = { ["id"] = 58619, ["name"] = "Read Between the Lines", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["series"] = { 62605 }, ["description"] = "Ah, mortal, how fortunate that I, humble Ta'eran , happen to be standing here just as you, the outsider everyone is talking about, happens to wander by! In the spirit of cooperation and mutual interests, there is a matter I wish to discuss. A nearby structure called the Sepulcher of Knowledge was built as a repository for military strategy. I fear the knowledge contained within may soon be lost. If you would do me the honor of escorting me to the Sepulcher, I can share what else I know.", ["objectivesText"] = "Follow Ta'eran to the Sepulcher of Knowledge and hear his proposal.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166657, ["x"] = 0.406, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 62605 }, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58620] = { ["id"] = 58620, ["name"] = "Slaylines", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "Gaining entrance to the Sepulcher is no easy feat, <name>! Not only were guardians put in place, but an elaborate magical lock was created to seal the door. To open the way, the two obelisks which control the lock must be fed anima. Fortunately, there are some empowered crystals in the area we can use for this purpose. Locate the focus crystals and redirect their anima flow into the obelisks. Then the secrets of the Sepulcher will soon be ours!", ["objectivesText"] = "Connect the anima flow to the Unlocking Obelisks. Progress: Have you activated the two obelisks?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58621 }, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58621] = { ["id"] = 58621, ["name"] = "Repeat After Me", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "The Primus placed guardians in the area around the Sepulcher to protect the knowledge within. Each embodied the virtues of one of the five houses. To gain entrance, you must prove yourself worthy by besting these protectors. Seek out the rune stones that represent the houses of Maldraxxus . Pay attention to the words inscribed on each stone, then pay deference each house's values. If you honor the stone, its protector will come forth. Defeat each of them.", ["objectivesText"] = "Read the rune stones of the five houses, then honor them by performing the correct /emote at each stone. Progress: The Primus was clever indeed.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 175707, 178020, 182732 }, ["rewardChoices"] = { 175707 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58619 }, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58622] = { ["id"] = 58622, ["name"] = "Secrets Among the Shelves", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "Now that the door to the Sepulcher is unlocked, we can venture inside. And by \"we\", I mean \"you\". Until it's safe, at least. The volumes within contain the collected wisdom of the greatest military minds of Maldraxxus . For the good of the Necrolords, do whatever is needed to gather these precious volumes. It is safe to assume that the books will be protected by traps. The Primus wouldn't want just anyone laying their hands on this knowledge. Once you clear a path, I'll join you.", ["objectivesText"] = "Recover volumes of the tomes kept within the Sepulcher. Progress: Were you successful?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 170667, ["x"] = 0.418, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58620, 59917 }, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58623] = { ["id"] = 58623, ["name"] = "A Complete Set", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "This is only volume one? We can't just take the first volume. A rare item like this is only useful if it's in a complete set! Grab as many of the other volumes as you can, I will have to prepare a larger expedition to remove all of these volumes.", ["objectivesText"] = "Collect Volumes of Victory. Progress: Did we get all the volumes?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178019, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166806, ["x"] = 0.452, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166806, ["x"] = 0.452, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59994 }, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58624] = { ["id"] = 58624, ["name"] = "Pauldrons of Imperium", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58472, 58504, 58523, 58599, 58608, 58624, 62161 }, ["series"] = { 58472, 58599, 58608, 62388 }, ["description"] = "Now we know who is responsible for the unrest in Maldraxxus. If Kel'Thuzad has allied with the Banished One, then he wields greater power than anyone realizes. We must lay siege to the House of Rituals, but we need time to prepare. Attacking without a flawless strategy will only ensure our defeat. For now, return the pauldrons to the Seat of the Primus. I will meet you there.", ["objectivesText"] = "Return to the Seat of the Primus with the Pauldrons of Imperium .", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 182255, 182264, 182273, 182282 }, ["rewardChoices"] = { 182273, 182264, 182282, 182255 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161865, ["x"] = 0.78, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161865, ["x"] = 0.78, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 161865, ["questType"] = "standard", ["sourceQuests"] = { 58608 }, ["questLines"] = { { ["id"] = 1121, ["name"] = "The Wages of Sin", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1121, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58625] = { ["id"] = 58625, ["name"] = "Connecting the Dots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58625 }, ["description"] = "The old baron for the House of the Chosen? Ah, yes! I do think I remember seeing him! An angry soul, but very good at fighting. He went off to meet with some member of the House of Rituals. There were a few of his guards with him. While it's been quite some time since he passed this way, you may be able to find some signs of where he went towards the old footpath up the mountains.", ["objectivesText"] = "Search the Forgotten Wounds for the previous baron.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[58630] = { ["id"] = 58630, ["name"] = "Crown of the Harvesters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "Power you seek to focus is volatile. Need the Eternal Forge's flames to get it done. Without the blessing of the flames, I fear it will overwhelm the wearer. Bring venthyr friend. His magic will prove useful. Need you to absorb impurities. < Mikanikos hands you an elegant container.> Use this to capture imperfections that burn off during the process.", ["objectivesText"] = "Meet Mikanikos at the Eternal Forge. Then, assist him with forging the Crown of the Harvesters. Progress: It is done then?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 174587, ["x"] = 0.51, ["y"] = 0.191333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58600, 58603 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58631] = { ["id"] = 58631, ["name"] = "Into Dreams", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472, 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 57220, 57221, 57222, 57290, 57362, 57373, 57374, 58496, 58498, 58502, 58506, 58615, 58631, 58634, 58737 }, ["description"] = "I cannae believe that Ra-den sacrificed himself to save us. We cannae give up on him! There must be a way tae find out where he went. Let's see if MOTHER can track him down!", ["objectivesText"] = "Speak with MOTHER in the Chamber of Heart to track Ra-den's location. Progress: We're runnin' outta time!", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 173363 }, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["ends"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["coords"] = { ["mapID"] = 1473, ["x"] = 0.501, ["y"] = 0.591 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questGiverID"] = 152206, ["questTurnInID"] = 152206, ["questType"] = "standard", ["sourceQuests"] = { 58615 }, ["questLines"] = { { ["id"] = 1028, ["name"] = "Whispers in the Dark", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 28, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 27, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[58632] = { ["id"] = 58632, ["name"] = "Ny'alotha, the Waking City: The Corruptor's End", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 58615, 58631, 58632 }, ["description"] = "Usin' the mogu's research, MOTHER and Ra-den found a way tae focus the forge's Origination Protocol through the Chamber of Heart. The only problem was findin' out where tae shoot it. That is, until now. Take these anchors and head through that portal. Ye'll need tae find some prominent landmarks tae place 'em so we can focus the weapon. Once they're set, we'll be ready tae fire. Ye'll only get one shot. Make it count!", ["objectivesText"] = "Defeat N'Zoth in Ny'alotha, the Waking City. Progress: It's time tae blast N'Zoth back tae the void he came from!", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 3000 } }, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["ends"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["coords"] = { ["mapID"] = 1473, ["x"] = 0.501, ["y"] = 0.591 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questGiverID"] = 152206, ["questTurnInID"] = 152206, ["questType"] = "raid", ["sourceQuests"] = { 58631 }, ["questLines"] = { { ["id"] = 1028, ["name"] = "Whispers in the Dark", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[58634] = { ["id"] = 58634, ["name"] = "Opening the Gateway", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57362, 57373, 57374 }, ["description"] = "The fabric of reality is torn. But there's no need for me to tell you that, <name>. You've seen it firsthand. It's only a matter of time before these realities become one, veiled in eternal darkness. Instead of hiding, perhaps it's time we embraced the darkness. With the help of our titan friend here we may be able to thread the needle of this reality through the fabric of another, creating a bridge of sorts. After all, the key to understanding an enemy's weakness is to understand their intentions.", ["objectivesText"] = "Speak with MOTHER to establish the Tenebrous Gateway in the Chamber of Heart. Progress: Uncertainty comes before discovery.", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 10000 } }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["sourceQuests"] = { 57373 }, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[58636] = { ["id"] = 58636, ["name"] = "Eyes on the Amathet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "On behalf of the Explorers' League, I'd like tae thank ye for helping establish the Uldum Accord and buying us some cooperation from Ramkahen. In the interest of better understanding our foes, Ramkahen has allowed the exploring of the Amathet tombs. Unfortunately, though, their forces are spread too thin to provide protection. I was hopin' ye could help out with that. Think ye could spare some time tae see what they're all about? We can start with an aerial look.", ["objectivesText"] = "Scout the Amathet territories with High Explorer Dellorah in Uldum . Progress: To the skies!", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questTurnInID"] = 155102, ["questType"] = "standard", ["sourceQuests"] = { 56472 }, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58638] = { ["id"] = 58638, ["name"] = "A Deeper Dive", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "Something just isn't adding up about these Amathet. Why would protectors of titan works attack and damage the Forge of Origination? I think we need tae take a closer look. I think I saw a monument on the terrace over there. Perhaps the writings there could tell us more about these tol'vir.", ["objectivesText"] = "Defend High Explorer Dellorah as she deciphers the Amathet Monument at Sunstone Terrace. Progress: I'm ready when ye are, <class>.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.549, ["y"] = 0.329, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["ends"] = { { ["x"] = 0.549, ["y"] = 0.329, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["coords"] = { ["mapID"] = 1527, ["x"] = 0.549, ["y"] = 0.329 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 155102, ["questTurnInID"] = 155102, ["questType"] = "standard", ["sourceQuests"] = { 58636 }, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58639] = { ["id"] = 58639, ["name"] = "Buried History", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "Since the Amathet came from this region, it would only stand to reason that artifacts from their civilization would be left behind here, hidden beneath the sands . It looks like it's time for a good old-fashioned dig! The dunes near here must have covered up a large swath of the Amathet's former territory. Let's see what we can dig up there!", ["objectivesText"] = "Uncover and collect 6 Amathet Artifacts in Uldum . Progress: What have ye turned up?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174450 }, ["starts"] = { { ["x"] = 0.689, ["y"] = 0.579, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["ends"] = { { ["x"] = 0.689, ["y"] = 0.579, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["coords"] = { ["mapID"] = 1527, ["x"] = 0.689, ["y"] = 0.579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 155102, ["questTurnInID"] = 155102, ["questType"] = "standard", ["sourceQuests"] = { 58638 }, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58640] = { ["id"] = 58640, ["name"] = "A Crack in the Armor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "The artifacts you helped excavate show the Amathet as a tribe who prided themselves on protecting the works of the titans. This confirms our assumptions, and indicates that something drastic must have happened to them to cause them to damage the very works they swore to protect. We should continue to track down their writings. I think I saw a more recent monument outside the Halls of Origination.", ["objectivesText"] = "Defend High Explorer Dellorah as she deciphers the Amathet Monument outside the Halls of Origination. Progress: I cannae wait tae solve this mystery!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.689, ["y"] = 0.579, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["ends"] = { { ["x"] = 0.689, ["y"] = 0.579, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["coords"] = { ["mapID"] = 1527, ["x"] = 0.689, ["y"] = 0.579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 155102, ["questTurnInID"] = 155102, ["questType"] = "standard", ["sourceQuests"] = { 58639, 58646 }, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58641] = { ["id"] = 58641, ["name"] = "Seekers of Corruption", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "If anyone would know more about the \"corruption\" the tablet spoke of, it would be the Suntouched that were put in charge of rooting it out. Of course, I doubt they'll be willing to turn over any information voluntarily. Luckily for me, you're a bit of a specialist at brute force investigation, aren't you?", ["objectivesText"] = "Collect the Sun King's Decree from Suntouched Amathet in Uldum . Progress: Found anything from the Suntouched?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174451 }, ["starts"] = { { ["x"] = 0.729, ["y"] = 0.484, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["ends"] = { { ["x"] = 0.729, ["y"] = 0.484, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["coords"] = { ["mapID"] = 1527, ["x"] = 0.729, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 155102, ["questTurnInID"] = 155102, ["questType"] = "standard", ["sourceQuests"] = { 58640 }, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58642] = { ["id"] = 58642, ["name"] = "Shared Goals", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "The decree you found made mention of a plan to defeat the Old Gods. I know that the Amathet aren't likely to work with us toward that goal, but if they have a plan tae take out N'Zoth, it's worthwhile for us tae look at it. The decree mentions the Engine of Ascension. I think that might be what they call that solar empowering device we saw earlier. We should take a peek underneath and see if we can figure out what they're planning!", ["objectivesText"] = "Defend High Explorer Dellorah as she deciphers the Amathet Tablets within the Chamber of the Stars. Progress: Let's see what we can find in the Chamber of the Stars.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.729, ["y"] = 0.484, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["ends"] = { { ["x"] = 0.729, ["y"] = 0.484, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["coords"] = { ["mapID"] = 1527, ["x"] = 0.729, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 155102, ["questTurnInID"] = 155102, ["questType"] = "standard", ["sourceQuests"] = { 58641 }, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58643] = { ["id"] = 58643, ["name"] = "Mutually Assured Destruction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "The Amathet want tae re-take the Forge of Origination so they can use it tae end all life on Azeroth, Old God or otherwise! They could strike at any moment. We have tae warn the defenders of the Forge!", ["objectivesText"] = "Warn the defenders of the Halls of Origination about the Amathet's plan.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.729, ["y"] = 0.484, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161031, ["x"] = 0.72, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questGiverID"] = 155102, ["questType"] = "standard", ["sourceQuests"] = { 58642 }, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58645] = { ["id"] = 58645, ["name"] = "A World Worth Saving", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "We could not stand against them. Their warriors... wreathed in the sun's flames... They want the forge... to end all... Go... I will... endure...", ["objectivesText"] = "Stop the Amathet from taking the Halls of Origination.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161031, ["x"] = 0.72, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58643 }, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58646] = { ["id"] = 58646, ["name"] = "Chew On This!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "These mangy hyena will gnaw on anything they dig up, including priceless artifacts! We cannae allow the history of Uldum tae go tae the dogs, so tae speak. I'm afraid we're gonna have tae thin out their numbers.", ["objectivesText"] = "Kill 8 Scavenging Dunerunners in Uldum . Progress: Did ye take care of the hyenas?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.689, ["y"] = 0.579, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["ends"] = { { ["x"] = 0.689, ["y"] = 0.579, ["mapID"] = 1527, ["npcID"] = 155102 } }, ["coords"] = { ["mapID"] = 1527, ["x"] = 0.689, ["y"] = 0.579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10833 } }, ["questGiverID"] = 155102, ["questTurnInID"] = 155102, ["questType"] = "standard", ["sourceQuests"] = { 58638 }, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58647] = { ["id"] = 58647, ["name"] = "Broken Webs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "My husband once served our people as the Speaker of Elune--until he became the Night Warrior. His feelings on the matter are... complicated, to say the least. Spriggans have been ripping the garden's soulwebs. Would you please help me repair them? I will recount our story as we work.", ["objectivesText"] = "Help repair soul webs. Progress: Just one more.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161786, ["x"] = 0.396, ["y"] = 0.553 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161786, ["x"] = 0.396, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 161786, ["questType"] = "standard", ["sourceQuests"] = { 58610 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58654] = { ["id"] = 58654, ["name"] = "A Plea to the Harvesters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57174, 57178, 57179, 58654 }, ["description"] = "You come during strange times. Every day the tithes we must pay to the Tithelord increase, and our ability to get anima dwindles. What souls we have to work with here are near their final judgment and we lack the resources to harvest them without endangering the hamlet. If you have the ear of Lord Chamberlain , then you might be able to pass a message to the Master himself. Here, take this letter. Please see that it makes it to the hands of the Chamberlain.", ["objectivesText"] = "Deliver Mihaela's Note to the Lord Chamberlain . Provided item:", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174482 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156374, ["x"] = 0.5935, ["y"] = 0.5645 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57174 }, ["questLines"] = { { ["id"] = 994, ["name"] = "The Master", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 994, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 994, ["questLineOrder"] = 26 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58656] = { ["id"] = 58656, ["name"] = "Heavy is the Head...", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "Crown is unstable due to Sire's lingering influence from the medallions. A test run should solve. Socketed one of your medallions. Witness its power focused into a weapon of destruction. Perfect opportunity. Forsworn finished colossi construction. Destroy them. Bring the Forsworn the end they crave. Careful. Theotar informed me how powerful magic this is. The crown will hunger, must control it.", ["objectivesText"] = "Test the Crown of the Harvesters and defeat the Operational Colossi. Progress: Bring the Forsworn the destruction they crave.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 174587, ["x"] = 0.51, ["y"] = 0.191333 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 161526, ["x"] = 0.502667, ["y"] = 0.218667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.191333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58630 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58660] = { ["id"] = 58660, ["name"] = "Burrowing Terrors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["starts"] = { { ["x"] = 0.316, ["y"] = 0.439, ["mapID"] = 1527 } }, ["ends"] = { { ["x"] = 0.316, ["y"] = 0.439, ["mapID"] = 1527 } }, ["coords"] = { ["mapID"] = 1527, ["x"] = 0.316, ["y"] = 0.439 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10833 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 162032 }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 162033 } } },
[58664] = { ["id"] = 58664, ["name"] = "Ultimate Makeover", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58664 }, ["description"] = "We now control the Apparatus of Abominable Construction! We can use it to create new constructs to contain worthy souls. Emeni is the best choice to be first. Her combat skills are unmatched, and you may need her to help secure the Stitchyard. You will assist me in rebuilding Emeni's construct.", ["objectivesText"] = "Help Rathan rebuild Emeni's Construct.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[58665] = { ["id"] = 58665, ["name"] = "Rebellious Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "Please hear us out, Maw Walker. When Margrave Gharmal launched his attack on Bastion, there were many, such as Emeni and myself, that opposed his actions. Fearing dissent, Gharmal removed many souls from their constructed bodies and imprisoned them. Emeni escaped the prison, but most did not. Help us free the other souls, and we can build you an army of constructs far greater than any that serve Gharmal.", ["objectivesText"] = "Meet Rathan and Emeni at Sixfold Recluse.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.48, ["y"] = 0.502, ["mapID"] = 1698, ["npcID"] = 162222 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162108, ["x"] = 0.26, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12876 } }, ["questGiverID"] = 162222, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58668] = { ["id"] = 58668, ["name"] = "Find The Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "I apprenticed at the Stitchyard for many eons. I even worked in the Body Banks with surgeon Stitchflesh to design Emeni's last construct. If we gain control of the Body Banks, we will have the parts necessary to rebuild Emeni and create new bodies for other souls we rescue. Lead us to there and we'll see if we can get it operational.", ["objectivesText"] = "Lead Rathan and Emeni to the Body Banks.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 2411, 25470, 25474, 25948, 25949, 25951, 31725, 247234, 254878 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162108, ["x"] = 0.26, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58665 }, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58669] = { ["id"] = 58669, ["name"] = "A Little Pruning", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "Spriggans sometimes invade the garden to spread mischief and mayhem. There is no end to the trouble they bring with them. Usually, the Wild Hunt keeps them in check... but their huntsmen and huntresses have had far more pressing concerns as of late. Thiernax and I have been helping to keep the garden clear, but he's run off somewhere to brood. < Qadarin shakes his head.> You would be doing me a favor if you helped me clear the Queen's garden of these vermin.", ["objectivesText"] = "Slay 15 Sicklethorn spriggan. Progress: At least here we only have to worry about spriggans. Other parts of the forest are not so fortunate.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161786, ["x"] = 0.396, ["y"] = 0.553 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161786, ["x"] = 0.396, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 161786, ["questType"] = "standard", ["sourceQuests"] = { 58610 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58670] = { ["id"] = 58670, ["name"] = "The Slaughter Daughter", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "When I was locked up, I made a list of all the constructs that betrayed me... it is a lengthy list! Help me teach these constructs the mistake they made. I want to destroy everyone on my list, along with Yardmaster Pralak , who is number one on the list!", ["objectivesText"] = "Help Emeni slaughter everyone on her list.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.238, ["y"] = 0.391, ["mapID"] = 1536, ["npcID"] = 162174 } }, ["ends"] = { { ["x"] = 0.238, ["y"] = 0.391, ["mapID"] = 1536, ["npcID"] = 162174 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.238, ["y"] = 0.391 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questGiverID"] = 162174, ["questTurnInID"] = 162174, ["questType"] = "standard", ["sourceQuests"] = { 59042 }, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58671] = { ["id"] = 58671, ["name"] = "Bottled Up Inside", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "There were many souls that opposed Margrave Gharmal's attack on Bastion. Those of us that spoke out, were stripped our bodies, imprisoned in the Etheric Vault, till our souls faded away, starved of anima. My friends are still imprisoned in the vaults. We will free them, and build an army of constructs to fight for you!", ["objectivesText"] = "Rescue 10 Imprisoned Souls in the Etheric Vault.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.238, ["y"] = 0.391, ["mapID"] = 1536, ["npcID"] = 162174 } }, ["ends"] = { { ["x"] = 0.238, ["y"] = 0.391, ["mapID"] = 1536, ["npcID"] = 162174 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.238, ["y"] = 0.391 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 162174, ["questTurnInID"] = 162174, ["questType"] = "standard", ["sourceQuests"] = { 59042 }, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58672] = { ["id"] = 58672, ["name"] = "A Gathering of Champions", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8499, ["mapID"] = 84, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152, 57198, 57376, 58672, 58673 }, ["description"] = "The leaders of the Horde are gathering together in Orgrimmar to nominate a new Warchief of the Horde. As a champion of the Horde, your presence at the meeting has been requested. The gathering will be held at the embassy in Orgrimmar. I will be going on ahead. Come speak with me when you arrive in Orgrimmar, I'll be waiting with the others. Make haste, champion. The future of the Horde is about to be decided...", ["objectivesText"] = "Speak with Valeera Sanguinar in Orgrimmar.", ["starts"] = { { ["mapID"] = 84, ["npcID"] = 161458, ["x"] = 0.850667, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 162190, ["x"] = 0.531, ["y"] = 0.143 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.850667, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 58631 }, ["questLines"] = { { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[58673] = { ["id"] = 58673, ["name"] = "Warchief of the Horde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152, 57198, 57376, 58672, 58673 }, ["description"] = "The meeting to decide the next Warchief of the Horde is about to begin. The other leaders of the Horde have already arrived. They are waiting for you inside the embassy. Speak with me when you are ready, and we will greet the others together.", ["objectivesText"] = "Witness the gathering of champions.", ["starts"] = { { ["mapID"] = 84, ["npcID"] = 162190, ["x"] = 0.531, ["y"] = 0.143 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 162190, ["x"] = 0.531, ["y"] = 0.143 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.531, ["y"] = 0.143 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 58672 }, ["questLines"] = { { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[58674] = { ["id"] = 58674, ["name"] = "A Gathering of Champions", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 8717, ["mapID"] = 1161, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002, 57126, 57324, 58674, 58675 }, ["description"] = "King Wrynn has called for an audience with the Alliance leaders in Stormwind. Your presence at the meeting has been specifically requested. The gathering will be held at the embassy. Come speak with me when you arrive in Stormwind, I'll be waiting with the others. Do hurry, <name>. It would be ill-advised to keep the king waiting...", ["objectivesText"] = "Speak with Master Mathias Shaw in Stormwind.", ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 162178, ["x"] = 0.535, ["y"] = 0.149 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["sourceQuests"] = { 58631 }, ["questLines"] = { { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiUiMapID"] = 84 },
[58675] = { ["id"] = 58675, ["name"] = "The Price of Peace", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 4411, ["mapID"] = 84, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002, 57126, 57324, 58674, 58675 }, ["description"] = "The king will be addressing us shortly with news from his diplomatic mission to the Horde. The other leaders of the Alliance have already arrived. I am sure they are eager to hear what King Wrynn has to say. Speak with me when you are ready, and we will greet the king together.", ["objectivesText"] = "Witness King Wrynn's address.", ["rewardItems"] = { 90365 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 162178, ["x"] = 0.535, ["y"] = 0.149 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 162178, ["x"] = 0.535, ["y"] = 0.149 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.149 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 58674 }, ["questLines"] = { { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiUiMapID"] = 84 },
[58677] = { ["id"] = 58677, ["name"] = "Skin in the Game", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "This task is probably above your capabilities, but listen anyway. As a construct I was feared throughout the Shadowlands. The magnificent skin of my construct was impervious to mortal weapons, it was a work of art that took years to perfect. When I was removed from my construct, it was Faldo Iscar who took great delight in stealing that skin. He keeps it on himself as a souvenir. Kill Faldo Iscar, and get my skin back!", ["objectivesText"] = "Emini's Magnificent Skin obtained Progress: When I was alive, you might have been my friend... or maybe my dinner.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174520 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161285, ["x"] = 0.251, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161285, ["x"] = 0.251, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.251, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58668 }, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58680] = { ["id"] = 58680, ["name"] = "Loose Threads", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "We're missing a few tools and parts for sewing a construct. We need these items if we're to rebuild my construct! Search the surrounding area. See if you can find us what we need. Search tables for the Skewering Needles , you can find haulers that carry Razorthread Spools , and look for Clotting Patches on constructs you kill.", ["objectivesText"] = "Locate Skewering Needles , Razorthread Spools and Clotting Patches . Progress: You are good at this.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174524, 174526, 174534 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58668 }, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58686] = { ["id"] = 58686, ["name"] = "Weapon of Mass Construction", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "We are in luck! Surgeon Stitchflesh and his assistant have not returned from Bastion. The entire Stitchyard is lightly guarded. We must work fast. See if you can get the equipment operational. Once it is active, we can begin the construction process.", ["objectivesText"] = "Get the assembly lab operational. Progress: We will control the means of production!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58677, 58680 }, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58704] = { ["id"] = 58704, ["name"] = "The Garden of Night", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "That should take care of things out here. Now we must tend to the inner garden. Once we're done, I'll sort out my recalcitrant husband. Hopefully, any remaining spriggans will have cleared out on their own after hearing us dispatch the others.", ["objectivesText"] = "Slay spriggans in the central garden. Progress: This is my fault... just like before...", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 175581, 179766, 179889, 181910 }, ["rewardChoices"] = { 175581, 179766, 181910, 179889 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 161934 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161785, ["x"] = 0.396, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questGiverID"] = 161934, ["questType"] = "standard", ["sourceQuests"] = { 58647, 58669, 59008 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
