[58708] = { ["id"] = 58708, ["name"] = "Fame Waits for Gnome One", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10290, ["mapID"] = 84, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 57009, 58708 }, ["series"] = { 54088, 57009 }, ["description"] = "Tinkmaster Overspark requests your assistance on an important research expedition. Working with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!", ["objectivesText"] = "Meet with Tinkmaster Overspark in Boralus.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 162393, ["x"] = 0.525, ["y"] = 0.141 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 150208, ["x"] = 0.674, ["y"] = 0.155333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.141 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["nextQuests"] = { 54088 }, ["questLines"] = { { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161 },
[58714] = { ["id"] = 58714, ["name"] = "The Forest Has Eyes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["description"] = "That dream! With the teeth and the claws and the heart... heart-wrenching sacrifice? <Moonberry chokes up for a moment then collects herself.> Sorry! While we were in dreamland, possessed spies have snuck into Hibernal Hollow! They must be hunted down and slain before they can report back on the grove's defenses. Here, borrow a bit of my magic. Seek out the ones hidden in the shadows and smite them!", ["objectivesText"] = "Slay hidden Possessed Spies throughout Hibernal Hollow. Progress: Have you uncovered all those pesky spies yet?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174864, 187591 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161847, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58593 }, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58717] = { ["id"] = 58717, ["name"] = "Bell of Remembrance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58717, 58725 }, ["description"] = "<The bell is scratched and damaged. You remember the Curator being very interested in this item. Maybe someone at the Crypt of the Forgotten will know more.>", ["objectivesText"] = "Find someone who knows more about the bell at the Crypt of the Forgotten.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174674 }, ["starts"] = { { ["x"] = 0.67, ["y"] = 0.336, ["mapID"] = 1525 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161418, ["x"] = 0.732, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1193, ["name"] = "Bell of Remembrance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["startItems"] = { 174674 } },
[58719] = { ["id"] = 58719, ["name"] = "The Droman's Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 58720, 58869, 60621 }, ["description"] = "Our enemies close in swiftly, <name>. We must sound the call to defend the grove! Use this horn to call upon our protectors. Summon the Wild Hunt to slay those who would attack us.", ["objectivesText"] = "Use the Droman's Horn to summon the Wild Hunt at the entrances to the grove. Progress: The Hunt will hear our call and ride to defend the grove!", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58593 }, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58720] = { ["id"] = 58720, ["name"] = "Missing!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 58719, 58869, 60621 }, ["description"] = "The Wild Hunt has answered the call to defend us... except for Hunt-Captain Korayn and her forces. She had led her hunting party to the west, on the trail of a powerful foe. They may have encountered trouble. Find her and provide whatever aid she requires. We need her hunters and her leadership if our defenses are to hold.", ["objectivesText"] = "Find Hunt-Captain Korayn on the Path of Rebirth.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 25631, 25632, 25633, 31666, 73223, 73241, 74583, 74584, 74585, 131912, 158464, 161083, 174864, 199115, 207002, 248051, 248052 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162541, ["x"] = 0.570667, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58714, 58719 }, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58721] = { ["id"] = 58721, ["name"] = "Awaken the Dreamer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 60661 }, ["description"] = "Much of the Queen's focus has centered on the Grove of Awakening, where rejuvenated spirits emerge from their wildseeds and return to their worlds. Perhaps it is fitting you carry a wounded spirit with you. < Lord Herne studies Ysera's wildseed for a moment before a slow grin spreads across his face.> This one fights with all of her being. Even now she clings to existence. Come, stranger, let us see what fate the Queen will decree for this one.", ["objectivesText"] = "Travel to the Grove of Awakening.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169869, ["x"] = 0.466, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162968, ["x"] = 0.452, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60661 }, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58723] = { ["id"] = 58723, ["name"] = "The Court of Winter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 56829, 56942, 56955, 57007, 57025, 57026, 58724 }, ["description"] = "My Court informs me that you bear an important message. You may now deliver it.", ["objectivesText"] = "Give the Primus's message to the Winter Queen . Progress: The ancient enemy has not been idle...", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 174864, 175710 }, ["rewardChoices"] = { 175710 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162968, ["x"] = 0.452, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162968, ["x"] = 0.452, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["sourceQuests"] = { 58721 }, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[58724] = { ["id"] = 58724, ["name"] = "The Queen's Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 56829, 56942, 56955, 57007, 57025, 57026, 58723 }, ["description"] = "Dire portents indeed. I have used what little anima we possess to save our groves and the spirits they nurture. So many were lost... all as the Heart of the Forest grew ever weaker. Keeping the Banished One bound within the Maw will require more anima than Ardenweald can spare. <The Queen considers for a moment.> Sire Denathrius is a master of anima extraction. Journey to Revendreth and inform him of our plight. I know he will lend us his aid. Your allies in Oribos can open the way.", ["objectivesText"] = "Return to Tal-Inara in Oribos.", ["rewardGold"] = 567400, ["rewardXP"] = 1770, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162968, ["x"] = 0.452, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162968, ["x"] = 0.452, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questTurnInID"] = 162968, ["questType"] = "standard", ["sourceQuests"] = { 58723 }, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[58725] = { ["id"] = 58725, ["name"] = "Sinkeeper", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58717, 58725 }, ["description"] = "This is a Bell of Remembrance . Before the recent... \"events\" we used them to beckon souls from the Crypt of the Forgotten to deem their fate. If they are less arrogant than they were before, they may continue in the process. If not, they must spend additional time in the crypt. Let's put this one to use, shall we? It's pretty beat up, let's hope we can get at least one use out of it.", ["objectivesText"] = "Use the Bell of Remembrance to beckon a soul from the Crypt of the Forgotten. Then, deem the soul's fate.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174652, 174674, 174741 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161418, ["x"] = 0.732, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161418, ["x"] = 0.732, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58717 }, ["questLines"] = { { ["id"] = 1193, ["name"] = "Bell of Remembrance", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58726] = { ["id"] = 58726, ["name"] = "Thick Skin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "The Primus forged a fine blade, but it will do you no good in its current state. Fortunately for you, I possess the skill to finish his work! That being said, I will require materials. The other Chosen have been too preoccupied with their combat drills to assist me at the forge, even as they demand more weapons and armor. That's where you come in. You want a new blade? You'll have to earn it.", ["objectivesText"] = "Collect 40 Pulsating Hide Scraps from Overgrown Masses. Progress: Can't be that difficult, can it?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172089, 174499, 175462, 175463, 175464, 175465, 178662, 178676 }, ["rewardChoices"] = { 175463, 175464, 175465, 175462 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.418667, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58616 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58727] = { ["id"] = 58727, ["name"] = "A Place To Call Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "You didn't end up on my list... so, I guess we're friends... for the moment. Rathan took the soul you freed to Butchers Block near the Seat of the Primus. Let us meet him there and plan our next step together.", ["objectivesText"] = "Meet up with Rathan and Emeni at Butchers Block.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.249, ["y"] = 0.317, ["mapID"] = 1536, ["npcID"] = 162174 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questGiverID"] = 162174, ["questType"] = "standard", ["sourceQuests"] = { 58671 }, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58737] = { ["id"] = 58737, ["name"] = "Magni's Findings", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 58737 }, ["description"] = "As if gettin' the Forge back up and runnin' wasn't good enough, I think we may have found the key tae takin' out N'Zoth once and for all in the archives of Mogu'shan Vaults! Ye might want tae be sittin' down for this one, champion.", ["objectivesText"] = "Learn Magni's findings. Progress: Pay attention, champion!", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["ends"] = { { ["x"] = 0.501, ["y"] = 0.591, ["mapID"] = 1473, ["npcID"] = 152206 } }, ["coords"] = { ["mapID"] = 1473, ["x"] = 0.501, ["y"] = 0.591 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questGiverID"] = 152206, ["questTurnInID"] = 152206, ["questType"] = "standard", ["sourceQuests"] = { 56542 }, ["questLines"] = { { ["id"] = 983, ["name"] = "The Engine of Nalak'sha", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473 },
[58740] = { ["id"] = 58740, ["name"] = "Subjugated Serpents", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58740 }, ["description"] = "Where the Zan-Tien march, the warserpents are sure to follow. I cannot stress to you enough how dangerous these beasts are. It is a shame to see them subjugated by the mogu, but we cannot afford to let them run rampant. I need you to put them down before they can wreak havoc on our lines.", ["objectivesText"] = "Kill 4 Onyx Warserpents in the Vale of Eternal Blossoms . Progress: Have you taken care of the serpents?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 313 }, { ["id"] = 1553, ["amount"] = 327 }, { ["id"] = 1553, ["amount"] = 342 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "group", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58741] = { ["id"] = 58741, ["name"] = "Cutting Stone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58741 }, ["description"] = "One problem with waging war against other mogu is that weapons dull and break very quickly when used against foes of stone and metal. Being the sole blacksmith among the Rajani, it is sometimes difficult to keep up with our warriors needs. If you come across any weapons in your battles with the mogu, I'm sure I could put them to good use.", ["objectivesText"] = "Collect 10 Mogu Armaments in the Vale of Eternal Blossoms . Progress: What have you found?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 172463, 174747 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 349 }, { ["id"] = 1553, ["amount"] = 381 }, { ["id"] = 1553, ["amount"] = 393 }, { ["id"] = 1553, ["amount"] = 493 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
