[58750] = { ["id"] = 58750, ["name"] = "Take the Bull by the Horns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58750, 58785, 58794 }, ["description"] = "I've carved out quite the reputation as a tauralus wrangler. Everyone needs a tauralus! You do some work for me, and people will know who you are as well. Take this bone splinter and poke a few juicy nibblers . Use them to lure a tauralus to you, then ride it back to me.", ["objectivesText"] = "Ride 5 Bloodskin Tauraluses back to Dundae . Progress: You want to be famous? Get the tauraluses I wanted?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174749, 174751 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162474, ["x"] = 0.468, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162474, ["x"] = 0.468, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57425 }, ["questLines"] = { { ["id"] = 1159, ["name"] = "Wasteland Work", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58751] = { ["id"] = 58751, ["name"] = "A Common Peril", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["description"] = "Each house in Maldraxxus has two barons. Before the fall of my first house--the House of Eyes--our margrave sent my fellow baroness to investigate suspicious behavior in the House of Rituals. I have not heard from her since. Either she has found something... or has become another casualty of their treachery. Her orders took her to the Decay in the east. If you can find the baroness, give her this summons. We were not friends, she and I, but she is a formidable combatant. We could use her might.", ["objectivesText"] = "Locate the lost baroness in the Renounced Bastille. Progress: Someone new...but someone familiar.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 132516, 174755, 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60886 }, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58754] = { ["id"] = 58754, ["name"] = "Champions of the Swarm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58754 }, ["description"] = "It is clear that Shek'zara is fully committed to this invasion. Our scouts have spotted some of her greatest champions among the battlefield. Any one of these mantid could prove too much for the soldiers of the Golden Lotus to overcome. We must hunt them down and eliminate them ourselves. Are you in?", ["objectivesText"] = "Defeat 3 rare mantid enemies in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 306 }, { ["id"] = 1553, ["amount"] = 327 }, { ["id"] = 1553, ["amount"] = 453 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58755] = { ["id"] = 58755, ["name"] = "Stashed Supplies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58755 }, ["description"] = "The invading mantid have been making off with the Golden Lotus' supplies lately. They're probably hoping they can starve us out. Well, they may be right if we can't get some of our supplies back. While you're taking the fight to the swarm, keep an eye out for anywhere they might have stashed our supplies. You'd be doing the Golden Lotus a big favor if you could recover some.", ["objectivesText"] = "Collect 3 Golden Lotus Supplies from Ambered Caches in the Vale of Eternal Blossoms . Progress: Did you manage to find our supplies?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 174763 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 315 }, { ["id"] = 1553, ["amount"] = 316 }, { ["id"] = 1553, ["amount"] = 336 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58756] = { ["id"] = 58756, ["name"] = "Dread Menders", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58756 }, ["description"] = "The ambercasters are among the highest castes of mantid society. Through their magic, they can mend and form amber to their will, allowing hastened recovery of the mantid's forces after a battle. They are strategic targets, and we should seek them out. Care to join us?", ["objectivesText"] = "Kill 6 Mantid ambercasters in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 310 }, { ["id"] = 1553, ["amount"] = 317 }, { ["id"] = 1553, ["amount"] = 394 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58758] = { ["id"] = 58758, ["name"] = "Rampaging Destroyers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58758 }, ["description"] = "The last mantid swarm is still very fresh in the memory of the Golden Lotus. Prior to the advancement of the swarm, the mantid would send their massive kunchong to soften up the defenders' lines. It would seem their tactics have not changed. We must stop those kunchong if the Golden Lotus hope to mount a defensive against the swarm. I'm counting on you to strike them down.", ["objectivesText"] = "Kill 4 Kunchong Destroyers in the Vale of Eternal Blossoms . Progress: Have the beasts been halted?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 355 }, { ["id"] = 1553, ["amount"] = 411 }, { ["id"] = 1553, ["amount"] = 473 }, { ["id"] = 1553, ["amount"] = 482 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "group", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58759] = { ["id"] = 58759, ["name"] = "The Empress' Guard", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58759 }, ["description"] = "The Zara'thik are the empress' elite guard. Empowered with plundered Azerite , they will stop at nothing short of absolute conquest of all of Pandaria. If we allow them to advance past the Serpent's spine, the Golden Lotus will be no match for them. Stop them at the wall, <class>.", ["objectivesText"] = "Kill 8 Zara'thik mantid in the Vale of Eternal Blossoms . Progress: We must break the Zara'thik advance!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 347 }, { ["id"] = 1553, ["amount"] = 350 }, { ["id"] = 1553, ["amount"] = 379 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "group", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58760] = { ["id"] = 58760, ["name"] = "Blades of Amber", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58760 }, ["description"] = "The mantid are frail and easily broken, but the amber blades they wield are formidable. With a bit of work, they could be reshaped into something suitable for the mogu. Bring them to me, and I can see about repurposing them to service the Rajani.", ["objectivesText"] = "Collect 12 Amber Blades from Vil'thik mantid in the Vale of Eternal Blossoms . Progress: Have you brought me some blades?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 174762 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 413 }, { ["id"] = 1553, ["amount"] = 429 }, { ["id"] = 1553, ["amount"] = 432 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58761] = { ["id"] = 58761, ["name"] = "Crushed Underfoot", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58761 }, ["description"] = "In the past, the mantid would safeguard their hatchlings in incubation chambers until they were ready to be tested in the swarm. These Vil'thik are sloppy, however, allowing their larvae to scurry out in the open. Wouldn't it be a shame if someone crushed them? No, of course it wouldn't.", ["objectivesText"] = "Squash 10 Vil'thik Larvae in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 321 }, { ["id"] = 1553, ["amount"] = 397 }, { ["id"] = 1553, ["amount"] = 409 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58762] = { ["id"] = 58762, ["name"] = "Taken by the Swarm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58762 }, ["description"] = "There's something different about this mantid swarm. Instead of just killing everything in sight like the mantid usually do, they've taken to capturing our defenders and holding them alive. I really don't want to know what they have in store for the captives. Why don't you go rescue them so we don't have to find out?", ["objectivesText"] = "Free 6 Golden Lotus prisoners from Hardened Amber Cages in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 350 }, { ["id"] = 1553, ["amount"] = 379 }, { ["id"] = 1553, ["amount"] = 449 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58763] = { ["id"] = 58763, ["name"] = "Halting Production", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58763 }, ["description"] = "The mantid use amber in nearly all aspects of their lives, from the structures they live in to the weapons they wield. Of course, I'm more interested in the latter. If we can deprive the mantid of their materials, we will deprive them of their means to create implements of war. Find where they keep their amber and make sure they are unable to use it.", ["objectivesText"] = "Destroy 6 Amber Vessels in the Vale of Eternal Blossoms .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 328 }, { ["id"] = 1553, ["amount"] = 355 }, { ["id"] = 1553, ["amount"] = 359 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58764] = { ["id"] = 58764, ["name"] = "Standards of the Swarm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58764 }, ["description"] = "The brazen mantid think they've already won. Even now, they fly banners along the Serpent's Spine, announcing their dominance. They must learn that Pandaria belongs to the pandaren. Burn their banners down.", ["objectivesText"] = "Burn 6 Zara'thik Banners within the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 377 }, { ["id"] = 1553, ["amount"] = 380 }, { ["id"] = 1553, ["amount"] = 392 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58765] = { ["id"] = 58765, ["name"] = "Siege Breaker", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5840, ["mapID"] = 1530, ["storyline"] = { 58765 }, ["description"] = "The Golden Lotus can hold their own against the mantid's warriors, of that I have no doubt. Their war wagons, on the other hand, have the capability of crippling an entire squad of our fighters in a single volley. If we wish to maintain the upper hand in this battle, we will need someone to infiltrate their positions and sabotage their siege engines. I would like you to volunteer.", ["objectivesText"] = "Sabotage 3 Vil'thik War Wagons in the Vale of Eternal Blossoms .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 303 }, { ["id"] = 1553, ["amount"] = 311 }, { ["id"] = 1553, ["amount"] = 313 }, { ["id"] = 1553, ["amount"] = 358 } }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 56771 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58769] = { ["id"] = 58769, ["name"] = "REUSE ME", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58769 }, ["description"] = "Suddenly the lack of fae and souls makes much more sense. These vile creatures must have taken them as they took my husband. But I will get them back. If you are our new champion then you will help me for the good of Ardenweald . Death did not part us. I will not be torn from him now.", ["objectivesText"] = "Ride with Thiernax after the Drust.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[58771] = { ["id"] = 58771, ["name"] = "Directions Not Included", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["description"] = "Look at this place! What a mess. The Locus is inactive and these \"Forsworn\" have taken over. We need to restore the Locus, but I do not know how. This place is not of my design, built long, long ago. Luckily, the previous Forgelite Prime was prolific. Recorded everything! If we can find her designs, I can certainly work it out. Even without Mnemis's help. Look around. Plenty of scrolls strewn about. Meet me near the Locus when you find what I need.", ["objectivesText"] = "Find the Locus Manual among discarded scrolls in the Mnemonic Locus. Progress: You find correct scroll?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178047, 178048, 178049, 178050, 178062, 178063, 178064, 178092, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.602667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58976 }, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58773] = { ["id"] = 58773, ["name"] = "The Thornspeaker Captive", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "Good to know the old bear hasn't forgotten me. Unfortunately, neither have the Drust. I was enjoying a peaceful afterlife before they showed up. Do not bother trying to force open this cage. You can only unlock it with three separate keys, and each one is held by a different Drust commander. They should be somewhere nearby. Find them.", ["objectivesText"] = "Rescue Kivarr from Eventide Grove in Ardenweald . Progress: I would love to help you, but as you can see... I am not exactly free to leave.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180777, 182639, 182641 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171413, ["x"] = 0.448, ["y"] = 0.6912 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173612, ["x"] = 0.465, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.6912 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61701 }, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58775] = { ["id"] = 58775, ["name"] = "Meet the Queen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "<name>, we need only one more piece to complete the Crest of Ascension. Eons ago, our Crest was originally crafted with the assistance of the fae. Deep within Ardenweald lies a portal they maintain to ferry souls back to their worlds. It is a source of great power and the final key to rebuilding the Crest. Seek out the Winter Queen in Ardenweald and plead our case. We've already sent Pelagos ahead as our envoy to arrange for your meeting.", ["objectivesText"] = "Gain an audience with the Winter Queen at the Heart of the Forest in Ardenweald.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533, 1565 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 58571 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58776] = { ["id"] = 58776, ["name"] = "Hatching Problems", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58776 }, ["description"] = "The aqir are multiplying faster than we can put them down. If this pace continues, we will be outnumbered before long. The only way to slow down their assault is to attack their hives directly and destroy their eggs, but we have been unsuccessful in doing so. That's why I wish to conscript your services. Will you help?", ["objectivesText"] = "Destroy 6 Aqir Egg Clusters in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 302 }, { ["id"] = 1553, ["amount"] = 331 }, { ["id"] = 1553, ["amount"] = 354 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 154443, ["x"] = 0.4, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 154443, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58777] = { ["id"] = 58777, ["name"] = "Put Your Foot Down", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58777 }, ["description"] = "<Zahra stomps on a slimy, slug-like creature as you approach.> You see that? Doesn't look like much, but believe it or not, those bugs grow out of these things. They're all over the places the aqir have taken over, feeding off of our dead and growing into these monstrosities. If you happen to see any of them, do the world a favor and take your boot to 'em.", ["objectivesText"] = "Squish 8 Aqir Larvae in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 312 }, { ["id"] = 1553, ["amount"] = 319 }, { ["id"] = 1553, ["amount"] = 364 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58778] = { ["id"] = 58778, ["name"] = "Getting Ahead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58778 }, ["description"] = "Morale's been down at the camp lately. Funny how getting chewed on by some bugs can spoil the mood of a place. I've got an idea to perk the troops back up, though. We need a trophy! See if you can get me the head of one of those big tanky-looking ones so we can put it on display to show these bugs that we mean business! Just try to make sure it's not too mangled, okay?", ["objectivesText"] = "Collect 1 Goliath Trophy from Aqir Goliaths in Uldum . Progress: Show me what ya got!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174776 }, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 315 }, { ["id"] = 1553, ["amount"] = 360 }, { ["id"] = 1553, ["amount"] = 361 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "group", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58779] = { ["id"] = 58779, ["name"] = "Taking the Skies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58779 }, ["description"] = "I'd like to see if we can get some more of these flyers in the air to drive back the aqir, but it's nearly impossible to get back to the Obelisk of the Sun with all these bugs in the air. I think we're going to have to thin them out on the ground before we can hope to gain aerial superiority. Can I count on you to lend a hand?", ["objectivesText"] = "Kill 15 flying Aqir in Uldum . Progress: How fares the bug smashing?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 339 }, { ["id"] = 1553, ["amount"] = 402 }, { ["id"] = 1553, ["amount"] = 445 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58780] = { ["id"] = 58780, ["name"] = "Heralds of the Hive", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58780 }, ["description"] = "The aqir that have assaulted our camp seem to mainly consist of their shock troops. However, our scouts who dare venture behind their lines have spotted a different kind of creature -- tall and thin, wielding dangerous void magic. My instinct tells me that these creatures are the leaders behind this invasion. They should be seen as targets of opportunity, and cut down wherever they're met. Are you up to the task?", ["objectivesText"] = "Kill 5 Aqir Dominators in Uldum . Progress: What do you have to report?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 389 }, { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 321 }, { ["id"] = 1553, ["amount"] = 352 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 154443, ["x"] = 0.4, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 154443, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "group", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58781] = { ["id"] = 58781, ["name"] = "Terrors from the Deep", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58781 }, ["description"] = "The Aqir threaten the livelihood of the Wastewanders with each passing day, but I have heard of greater terrors that have been unearthed with them. Our fighters are able, but I fear what might happen if one of these ancient terrors falls upon us. I know that you have experience putting down great foes. I would like to ask you to do the same for us. After all, we can hardly help protect the forge if we've been decimated by some long-buried monster.", ["objectivesText"] = "Defeat 3 rare Aqir enemies in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1755, ["amount"] = 325 }, { ["id"] = 1553, ["amount"] = 317 }, { ["id"] = 1553, ["amount"] = 434 }, { ["id"] = 1560, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58782] = { ["id"] = 58782, ["name"] = "Things Left Behind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58782 }, ["description"] = "The invading aqir forced the Wastewanders to flee many of our settlements in Uldum . In our haste to escape, much was left behind. I understand you intend to take the fight to the beasts. While you're there, could you keep an eye out for any of the supplies we had to leave behind? You can keep anything of use to you, of course.", ["objectivesText"] = "Collect 3 Wastewander Supplies from Infested Caches in Uldum . Progress: Were you able to find anything?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174774 }, ["rewardCurrencies"] = { { ["id"] = 1553, ["amount"] = 357 }, { ["id"] = 1553, ["amount"] = 413 }, { ["id"] = 1553, ["amount"] = 437 }, { ["id"] = 1553, ["amount"] = 493 } }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58785] = { ["id"] = 58785, ["name"] = "Smack and Grab", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58750, 58785, 58794 }, ["description"] = "Bonetooths are the backbone of Maldraxxus 's armed forces. Those that have been trained well are in demand amongst all of the houses. I always need new bonetooths to train, but they can be rather difficult to collect. Bring me some of the younger ones, and I will reward you greatly. Be advised that you may need to weaken them before you are able to capture them.", ["objectivesText"] = "Capture 10 Neonate Bonetooths. Progress: Bring me back some bonetooths!", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 119083, 174749, 174751 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162615, ["x"] = 0.47, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162615, ["x"] = 0.47, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57425 }, ["questLines"] = { { ["id"] = 1159, ["name"] = "Wasteland Work", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58787] = { ["id"] = 58787, ["name"] = "Trial of Ascension", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58788 }, ["description"] = "The Forsworn threat is ever looming, and our forces are dwindling. Now, more than ever, we need more Ascended. Our generous Archon has blessed us with a portion of our anima stores to ascend our top aspirants to join our forces. Kleia is amongst the chosen, and thus must complete her final trial. As Pelagos is not yet prepared to ascend, I request you be Kleia 's partner for this process. It is arduous and should not be embarked on alone. She must bear her first soul.", ["objectivesText"] = "Meet Kleia at the Court of Elation.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 183741, 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 49, 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58788] = { ["id"] = 58788, ["name"] = "Censers of Guidance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58787 }, ["description"] = "The Forsworn are going to great lengths to prevent us from ascension. They mobilize to stand in our way, to dismantle our chances to partake in our rituals. They have stolen the resources we need to start our trial. Defeat them and retrieve the incense they carry so that we may continue on this path.", ["objectivesText"] = "Collect 10 Incense of Guidance from Forsworn forces. Progress: Each censer will require considerable incense. We must make sure we gather enough.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174821 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58787 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58789] = { ["id"] = 58789, ["name"] = "Misguiding Mentors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["description"] = "These aspirants... we trained together. Learned together. The Forsworn have swayed them from the path, now leading them to their demise. They betray the path. Take out the Ascended that lead these forces against us.", ["objectivesText"] = "Kill Strategist Palladia and Instructor Herus . Progress: For an Ascended to use the trust their aspirants have in them... They do not deserve their wings.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174297, 177058, 178161, 179948 }, ["rewardChoices"] = { 174297, 178161, 177058, 179948 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 162544, ["x"] = 0.326, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 162544, ["x"] = 0.326, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.326, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58787 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58790] = { ["id"] = 58790, ["name"] = "To Cross the Veil", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58791 }, ["description"] = "Pallessa found a scroll detailing the ritual. We will need to take our positions and speak a chant, surrendering some of our anima with every word. Your presence is vital. I ask you to use the censers to burn the incense as we meditate. The rest should unfold on its own.", ["objectivesText"] = "Aid Kleia in the Rite of Guidance.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162558, ["x"] = 0.325, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["sourceQuests"] = { 58788, 58789 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58791] = { ["id"] = 58791, ["name"] = "A Day in the Life", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58790 }, ["description"] = "A Bearer's duty is to carry souls through the veil to Oribos, where they shall be judged and passed along to one of the realms of the Shadowlands. This soul is ready to move on. During this trial, you will experience his final moments before his death. When you are prepared, you shall see how this soul passed.", ["objectivesText"] = "Witness Ben Howell 's final moments.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 20576 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162558, ["x"] = 0.325, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162953, ["x"] = 0.218, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["sourceQuests"] = { 58790 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 49 },
[58792] = { ["id"] = 58792, ["name"] = "Where a Soul Belongs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58793, 58795, 58796, 58797, 58798 }, ["description"] = "This soul is no longer tethered to his world of Azeroth. Kleia must perform her duty and bear him to Oribos to be judged by the Arbiter. Take this vesper. When you are ready, it will call Ascended to ferry you back across the Veil to Oribos. Go in service.", ["objectivesText"] = "Use the Vesper of Veilflight to travel to Oribos, then witness Ben Howell's judgment. Progress: It is the duty of all kyrian to ferry souls to Oribos.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 175011 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162558, ["x"] = 0.325, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["sourceQuests"] = { 58951 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1671 },
[58793] = { ["id"] = 58793, ["name"] = "Faith Through the Darkness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58792, 58795, 58796, 58797, 58798 }, ["description"] = "This drought is... so much larger than I imagined. Why did nobody tell us? The burden of this knowledge weighs heavy... do we bear souls to their eternal torture? We must return home.", ["objectivesText"] = "Return to Adrestes in Elysian Hold.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162542, ["x"] = 0.325, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.325, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 49, 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 58792 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[58794] = { ["id"] = 58794, ["name"] = "Stabbing Wasteward", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58750, 58785, 58794 }, ["description"] = "I've been finding a lot of tauralus corpses lately, and I know it's all because those bonetooths Caleesy loves so much! I spotted the one that's responsible for the slaughter just west of here. Get rid of it! And don't mention this to Caleesy!", ["objectivesText"] = "Slay the Satiated Sawtooth . Progress: I hope you put an end to that creature.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174749, 174751 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162474, ["x"] = 0.468, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162474, ["x"] = 0.468, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58750, 58785 }, ["questLines"] = { { ["id"] = 1159, ["name"] = "Wasteland Work", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58795] = { ["id"] = 58795, ["name"] = "Ascended", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58792, 58793, 58796, 58797, 58798 }, ["description"] = "With success over their trials, our aspirants shall now start the next chapter of their afterlives. They have proven themselves through eons of training and cleansing, and will now earn ascendance. As each aspirant is called, I ask you and Pelagos to please assist by ushering them up. It is a tradition we have practiced for eons, reinforcing the bonds that we share.", ["objectivesText"] = "Assist Pelagos with the ascension ceremony.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174293, 177054, 178157, 179944, 180647 }, ["rewardChoices"] = { 178157, 177054, 179944, 174293 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questTurnInID"] = 160037, ["questType"] = "standard", ["sourceQuests"] = { 58793 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[58796] = { ["id"] = 58796, ["name"] = "The Forsworn Onslaught", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1707, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58792, 58793, 58795, 58797, 58798 }, ["description"] = "Loyalty's betrayal shall not go unnoticed. But while the Paragons defend the city proper, it is up to us to defend Elysian Hold. I am very wounded... but I will hold strong. Pelagos and I will protect the survivors. You must aid in pushing back this assault!", ["objectivesText"] = "Repel the Forsworn invasion. Progress: Devos... she goes too far.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.516, ["y"] = 0.477, ["mapID"] = 1707, ["npcID"] = 163650 } }, ["ends"] = { { ["x"] = 0.516, ["y"] = 0.477, ["mapID"] = 1707, ["npcID"] = 163650 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.516, ["y"] = 0.477 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 163650, ["questTurnInID"] = 163650, ["questType"] = "standard", ["sourceQuests"] = { 58795 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[58797] = { ["id"] = 58797, ["name"] = "Forged by Trial", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1707, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58792, 58793, 58795, 58796, 58798 }, ["description"] = "<name>, my friend. I have thought of you as an ally for some time now. The thrill I felt when you decided to join us in Bastion ... I knew you would be a boon unto our ranks. Our bond has been forged by the trials we face. Without you, I could have fallen to my newfound knowledge as Achillon did. I wish to cement our bond. I would be honored to soulbind with you.", ["objectivesText"] = "Complete the soulbinding ritual with Kleia . Progress: You are an important part in my journey. I respect you greatly, and hope you feel the same.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.516, ["y"] = 0.477, ["mapID"] = 1707, ["npcID"] = 163650 } }, ["ends"] = { { ["x"] = 0.516, ["y"] = 0.477, ["mapID"] = 1707, ["npcID"] = 163650 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.516, ["y"] = 0.477 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 163650, ["questTurnInID"] = 163650, ["questType"] = "standard", ["sourceQuests"] = { 58796 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[58798] = { ["id"] = 58798, ["name"] = "The Spires of Ascension", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["series"] = { 58792, 58793, 58795, 58796, 58797 }, ["description"] = "Our task is not complete yet. We may have pushed back the Forsworn here in Elysian Hold, but it was only a distraction to split our forces. The Archon and the Paragons fight to retake the Spires themselves. We cannot hesitate to aid them in this time of need!", ["objectivesText"] = "Kill Devos, Paragon of Doubt in the Spires of Ascension.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 1804, 1805, 1806, 1807, 181743, 184374 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160390, ["x"] = 0.642, ["y"] = 0.166 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.166 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 58797 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[58799] = { ["id"] = 58799, ["name"] = "The Prime's Directive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["description"] = "All centurion are made to serve the kyrian. That they now work against ME, the Forgelite PRIME, is an insult to all centurions in Bastion . Look at them! Praetors! Goliaths! All... PURPLE! I hereby give you permission and expressly order you to extract their cores. I will repurpose them in a fitting manner. I will reclaim their anima to power the Locus. I can build more. Do not pity.", ["objectivesText"] = "Collect 12 Centurion Cores . Progress: You have the cores?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.602667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58976 }, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58800] = { ["id"] = 58800, ["name"] = "The Mnemonic Locus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58977, 58978 }, ["description"] = "< Mikanikos examines the scroll you retrieved for him.> Right, right. Soul mirrors and Locus are tied together. If we restore anima to mirrors, it should repair the Locus back to full functionality. Thankfully, the cores you brought should be sufficient. All I need to do is enable conduits. Simple! Well? Go on. You know how to use these, yes?", ["objectivesText"] = "Use the Anima Conduits to restore the Mnemonic Locus. Progress: I wait to hear the hum of anima, yes.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 175704, 178046, 178094, 178145, 178146, 183802 }, ["rewardChoices"] = { 175704 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.602667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58771, 58799 }, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58801] = { ["id"] = 58801, ["name"] = "Enter the Void", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58801 }, ["description"] = "My faithful servant. I will grant you but a small taste of my unimaginable power, all I ask in return is that you complete one simple task. Kill any who would oppose me, spare no one. Do not fail me...", ["objectivesText"] = "Without dying or leaving Void Wraith form, sacrifice 10 players to N'Zoth.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["npcID"] = 341831, ["x"] = 0.603, ["y"] = 0.51, ["mapID"] = 1527 } }, ["ends"] = { { ["npcID"] = 341831, ["x"] = 0.603, ["y"] = 0.51, ["mapID"] = 1527 } }, ["coords"] = { ["x"] = 0.603, ["y"] = 0.51, ["source"] = "quest_giver", ["mapID"] = 1527 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questTurnInID"] = 341831, ["questType"] = "standard" },
[58802] = { ["id"] = 58802, ["name"] = "The Incredible Egg", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58802 }, ["description"] = "<The aqir seem to have been in the process of empowering this egg with void magic. It looks to be far from hatching, so it should be safe to study to find out what they were planning to do with it. Someone in the Explorers' League might be interested in taking a look.>", ["objectivesText"] = "Bring the Voidtouched Egg to H'partho Adoros in Ramkahen.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.208, ["y"] = 0.619, ["mapID"] = 1527, ["objectID"] = 343611 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58803] = { ["id"] = 58803, ["name"] = "Match the Hatch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58803 }, ["description"] = "Don't fret, I'm sure no ill will become of hatching this creature. After all, the aqir can't be born evil, can they? Of course, we have no idea how to take care of such an egg. I will need you to do some investigating. Head back to the aqir hives and see if you can find any other, similar eggs. If we can observe how they're being treated, we might be able to apply those learnings here.", ["objectivesText"] = "Investigate 7 Voidtouched Eggs in Uldum . Progress: What have you learned among the aqir?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58802 } },
[58804] = { ["id"] = 58804, ["name"] = "Void Incubation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58804 }, ["description"] = "Well one thing is for certain with this egg, it requires great amounts of void energy in order to thrive. It is fortunate for us that an Old God is attacking Azeroth at this very moment, yes? No? Oh... In any case, there should be an abundance of void energy wherever N'Zoth's minions strike. You should head out and find some.", ["objectivesText"] = "Collect 10 Crystallized Void in areas under assault by N'Zoth's forces. Progress: Have you found a reliable source of void energy?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174993 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58803 } },
[58805] = { ["id"] = 58805, ["name"] = "Continued Incubation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58805 }, ["description"] = "The egg is doing well, but we're going to need more of those void crystals to keep it healthy. Could you go out and gather some?", ["objectivesText"] = "Collect 10 Crystallized Void in areas under assault by N'Zoth's forces. Progress: Did you bring more void crystals?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174771, 174993 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58804 } },
[58806] = { ["id"] = 58806, ["name"] = "Warmth of the Sun", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58806 }, ["description"] = "The desert nights in Uldum can get awfully cold. I fear for our little egg's ability to withstand these temperatures. These Amathet to the East seem to have mastered the harnessing of the sun's energy. If we could borrow some of their expertise, we could use it to keep the egg nice and cozy. Keep your eyes open for something we can use.", ["objectivesText"] = "Collect an Amathet Solar Collector in Uldum . Progress: Did you find anything among the Amathet?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174996 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58804 } },
[58807] = { ["id"] = 58807, ["name"] = "Wrapping Up", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58807 }, ["description"] = "One oddity I have observed about this egg is that it lacks the protective webbing commonly found throughout the aqir hives. I believe this webbing has protective qualities, and could be beneficial to our egg if we can acquire some. While you're out fighting the insects, see if you can't bring back some of their webbing so we can make a proper cocoon for our growing egg.", ["objectivesText"] = "Collect 30 pieces of Aqir Webbing from aqir casters in Uldum . Progress: Did you find some suitable webbing?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175001 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58804 } },
[58808] = { ["id"] = 58808, ["name"] = "Encased in Amber", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58808 }, ["description"] = "You know who would probably know a lot about how to properly incubate this egg? The mantid! Of course, they're too busy trying to kill us to share their expertise, but there might be another way to benefit from their knowledge! Perhaps we could repurpose one of their incubation chambers. That could help speed up this process, I'm sure! If you could find and mark one for me, I could airlift it out of there.", ["objectivesText"] = "Mark an Amber Incubator for H'partho to airlift in the Vale of Eternal Blossoms.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58804 } },
[58809] = { ["id"] = 58809, ["name"] = "A Shocking Technique", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58809 }, ["description"] = "I have heard tales that the mogu use lightning to speed up the growth of their cloud serpents. I wonder if the same principle could be used for our aqir friend? There's only one way to find out! Go to the Vale of Eternal Blossoms and see if you can get the parts together so we can create our own lightning rods. If they work the same as they do for the cloud serpents, it should speed up the hatching process significantly.", ["objectivesText"] = "Collect 8 Lightning Rod Components from the Vale of Eternal Blossoms. Progress: Were you able to collect the proper components?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175003 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58804 } },
[58810] = { ["id"] = 58810, ["name"] = "Coming Out of His Shell", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58810 }, ["description"] = "It looks like our egg is ready to hatch! Isn't this exciting! Come, let us welcome our new little friend to this world.", ["objectivesText"] = "Watch the Aqir Egg hatch in Ramkahen. Progress: Oh, the anticipation!", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 175063 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58805 } },
[58811] = { ["id"] = 58811, ["name"] = "A Balanced Diet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58811 }, ["description"] = "Now that our larva is hatched, we'll need to figure out what we can feed it to keep it healthy. It would seem that the aqir are carnivores, but the only things I've seen them eat are... well... us. Of course, we can't feed our little friend people, so we'll have to find an alternative. Perhaps we could substitute animal meat?", ["objectivesText"] = "Collect 12 Chunks of Meat from beasts in Uldum and the Vale of Eternal Blossoms. Progress: He looks hungry, I hope you brought a snack.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175014 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58810 } },
[58812] = { ["id"] = 58812, ["name"] = "Meat Alternatives", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58812 }, ["description"] = "In the wild it is actually fairly common for insects to eat others of their species. I wonder if this rings true for the aqir as well. Could you bring back some meat from the aqir or mantid? We'll see if that's more palatable for our friend here.", ["objectivesText"] = "Collect 12 pieces of Insectoid Meat from Aqir, Mantid, or other insects in Uldum or the Vale of Eternal Blossoms. Progress: I do hope this works.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175015 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58811 } },
[58813] = { ["id"] = 58813, ["name"] = "Fetid Filets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58813 }, ["description"] = "You know, it occurred to me that since this creature has been imbued with void energy, it may prefer a more... corrupted food source. I speak, of course, of the Minions of N'Zoth. It's a long shot, but it's worth a try.", ["objectivesText"] = "Collect 12 pieces of Corrupted Flesh from creatures in areas under assault by N'Zoth's minions. Progress: Who knew aqir would be such picky eaters?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175016 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58812 } },
[58816] = { ["id"] = 58816, ["name"] = "Getting Backstage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "The next thing we need to prepare the vessel is a set of Night's Veil Flowers. We use these flowers in our ceremonies, but since the drought we've just used them as props in our plays. There are certainly some backstage at the Star Lake Amphitheater. I bet Moonberry is there for the rehearsal of their next play. As a bonus, this will work out quite nicely for me to get revenge on her. < Willowblossom flashes a wicked grin.>", ["objectivesText"] = "Retrieve a Wreath of Night's Veil Flowers from backstage at the Star Lake Amphitheater. Progress: Do you have the flowers?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["npcID"] = 162679 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 162679, ["questType"] = "standard", ["sourceQuests"] = { 58832, 58856 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58817] = { ["id"] = 58817, ["name"] = "Action Figures", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58817 }, ["description"] = "It occurs to me that our larva's current living situation is quite dull. We should try to find something to keep him entertained. After all, a happy larva is a healthy larva! I think the Amathet keep figures for worship of their gods. I'm sure they could also double as toys for our little friend here. See if you can find some!", ["objectivesText"] = "Collect 6 Amathet Figurines from Amathet creatures in Uldum . Progress: Did you find any suitable toys?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175020 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58813 } },
[58818] = { ["id"] = 58818, ["name"] = "Bug Buddies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58818 }, ["description"] = "Is it just me or does our little friend look lonely? It would make sense that aqir are social creatures, coming from a hive and all. It must be difficult for him not being around any of his kind. You know, maybe you could find some friends for him. Nothing big and scary, of course, but perhaps some of the smaller scarabs could be safe enough to keep him company. What do you think?", ["objectivesText"] = "Catch 5 Docile Sandstone Hatchlings in Uldum .", ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58813 } },
[58820] = { ["id"] = 58820, ["name"] = "Bindings of Fleshcrafting", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["description"] = "These are the Bindings of Fleshcrafting ! They empowered the Primus to shape the very flesh and bone of Maldraxxus. We must return them to their rightful place, so their power can bolster us all.", ["objectivesText"] = "Place the Bindings of Fleshcrafting upon the Statue of the Primus.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 182257, 182266, 182275, 182284 }, ["rewardChoices"] = { 182275, 182266, 182284, 182257 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.507, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["ends"] = { { ["x"] = 0.497, ["y"] = 0.507, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.497, ["y"] = 0.507 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161907, ["questTurnInID"] = 161907, ["questType"] = "standard", ["sourceQuests"] = { 59722, 61869 }, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[58821] = { ["id"] = 58821, ["name"] = "Glorious Pursuits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59171, 59172 }, ["description"] = "Perhaps Draka has forgotten her loyalties, but I will fulfill my mission. My enemy--the lich Mor'Bitan--hides within the House of Rituals. For some reason, his underlings skulk in this marsh. We have not learned why they are here, but my devoted have spotted Mor'Bitan's second-in-command, Mephiles the Loyal. He will have our answers. Collect him for me. Once you capture him, slay his kin. Weaken his resolve. I will prime my base for his interrogation.", ["objectivesText"] = "Kidnap Mephiles the Loyal, then kill 6 Morbid Disciples to intimidate him. Progress: Any luck?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58751 }, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58825] = { ["id"] = 58825, ["name"] = "Super Jelly", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58825 }, ["description"] = "My friends in the Golden Lotus have been telling me some interesting things about the new mantid swarm. Apparently they have developed a concentrated royal jelly that accelerates the growth of newly hatched mantid. If this jelly works on mantid, logic would suggest it would work on aqir as well! See if you can find a sufficient sample of this jelly to help with our larva's growth.", ["objectivesText"] = "Collect 8 Concentrated Royal Jelly in the Vale of Eternal Blossoms. Progress: This gets me thinking. After we've raised this one, I wonder if we could hatch a mantid as well?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175022 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58813 } },
[58826] = { ["id"] = 58826, ["name"] = "A Bloody Treat", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58826 }, ["description"] = "I have heard that a clan of the mogu called the Dokani have mastered the harnessing of life force into a substance they call \"anima.\" If this stuff is indeed life condensed into a liquid form, then it could have spectacular properties when applied to our aqir larva. Go see if you can bring back some of this anima in a form that we can use. We'll see if our little friend here likes it!", ["objectivesText"] = "Collect 8 Vials of Purified Anima from Dokani mogu in the Vale of Eternal Blossoms. Progress: Have you returned with the anima?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175023 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["sourceQuests"] = { 58813 } },
[58829] = { ["id"] = 58829, ["name"] = "They Grow So Fast", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58829 }, ["description"] = "Look! Our little larva friend has entered the pupa stage! Wait... it looks like he's ready to emerge. Go on, give him a hand!", ["objectivesText"] = "Help the Aqir Larva emerge from its cocoon in Ramkahen. Progress: Take care, our friend is likely still very fragile.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 13086, 46102, 69986, 175049 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58813 } },
[58830] = { ["id"] = 58830, ["name"] = "Aqir Instincts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58830 }, ["description"] = "In observing the aqir battling the Wastewanders, I have seen the newly hatched immediately join the aqiri assault. It would seem the need for combat is born into these creatures. We should exercise this in our new hatchling, under your supervision of course. Take him out with you and show him how to fight our enemies. He may not be able to fight for long, so don't call him until you're ready for training. With luck, he will come to see us as part of his hive.", ["objectivesText"] = "Use H'partho's Whistle to summon your Aqir Hatchling and battle enemies in Uldum or Vale of Eternal Blossoms. Fighting tougher and rarer enemies will help your hatchling grow faster. Progress: Take care of your hatchling. He will return here if he becomes too injured.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 175055 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58829 } },
[58831] = { ["id"] = 58831, ["name"] = "Honing Instincts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58831 }, ["description"] = "It looks like our little friend is anxious and ready to practice more combat. Would you care to show him the ropes?", ["objectivesText"] = "Use H'partho's Whistle to summon your Aqir Hatchling and battle enemies in Uldum or Vale of Eternal Blossoms. Fighting tougher and rarer enemies will help your hatchling grow faster. Progress: How goes the training?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 174771, 175055, 175140, 175142 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58830 } },
[58832] = { ["id"] = 58832, ["name"] = "Trinkle Trinkle Little Twerp", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "<On the note are the scribblings for a plan to steal silkstrider larvae and cook them. It is signed by someone named Trinkle.>", ["objectivesText"] = "Kill Trinkle the Silk Eater . Progress: Have you taken care of that nasty Trinkle?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.547, ["mapID"] = 1565 } }, ["ends"] = { { ["x"] = 0.404, ["y"] = 0.547, ["mapID"] = 1565 } }, ["coords"] = { ["mapID"] = 1565, ["x"] = 0.404, ["y"] = 0.547 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58775 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["startItems"] = { 175982 } },
[58833] = { ["id"] = 58833, ["name"] = "Calling in All Favors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58833, 59020, 62391, 62406 }, ["series"] = { 61761, 62391 }, ["description"] = "$p, the time has come. We cannot allow Kel'Thuzad to wield the Ritualists' sorcery as a weapon. He must be destroyed. Rally our forces. We march on the House of Rituals!", ["objectivesText"] = "Meet Draka and allies at the House of Rituals.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.496, ["y"] = 0.506, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 174179, ["x"] = 0.62, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 12876 } }, ["questGiverID"] = 161907, ["questType"] = "standard", ["sourceQuests"] = { 62391 }, ["questLines"] = { { ["id"] = 1118, ["name"] = "Assault on the House of Rituals", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1118, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58842] = { ["id"] = 58842, ["name"] = "The Curator", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["series"] = { 60935 }, ["description"] = "I tasked the Curator with reacquiring the Medallion of Avarice. However, since her return from the Maw, her mind has become... a bit chaotic. Do be kind, will you? I ask that you lend her assistance in her search. She is at the Crypt of the Forgotten.", ["objectivesText"] = "Meet the Curator at the Crypt of the Forgotten. Progress: I require your assistance, Maw Walker.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 37378, 37436, 37515, 37521 }, ["starts"] = { { ["x"] = 0.517, ["y"] = 0.376, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questGiverID"] = 158653, ["questType"] = "standard", ["sourceQuests"] = { 60935 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58843] = { ["id"] = 58843, ["name"] = "The Vault of the Archon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58980, 59196, 60013, 60180 }, ["description"] = "Behind me is the entrance to the Vault of the Archon. As you can see, it is warded against all unauthorized intrusion. To make yourself an authorized entrant, place the offerings you collected before the guardians. You may then browse the contents of the vault at your leisure. Do consider that such access is coveted among the Forsworn and is the sole focus of their efforts here. I advise preparing for combat.", ["objectivesText"] = "Gain entrance into the Vault of the Archon. Progress: Please place the offerings, and you may enter.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167035, ["x"] = 0.578, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167504, ["x"] = 0.563333, ["y"] = 0.673333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58980 }, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58844] = { ["id"] = 58844, ["name"] = "Before the Dawn", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["series"] = { 58846, 58847, 58854, 59919 }, ["description"] = "We shall need all we can muster if this day is to be ours. Gather them all. The Watchers, Bearers, Centurions, and Collectors. Tell them that their Archon calls for them. Our Paragons will clear a staging ground at the Court of Elation for the final assault.", ["objectivesText"] = "Gather the Watchers, Bearers, Centurions, and Collectors.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 164473, ["x"] = 0.314, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58854 }, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58846] = { ["id"] = 58846, ["name"] = "The Greater Good", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["series"] = { 58844, 58847, 58854, 59919 }, ["description"] = "The Forsworn are our former brothers and sisters in arms...our former kin. But we must see this through. We will hit them from all sides. Fight well, but do not forget that Lysonia is our ultimate objective. If she does not fall, then she will recruit more to their cause in time. Follow the path, <name>.", ["objectivesText"] = "Defeat Lysonia.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 164473, ["x"] = 0.314, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166693, ["x"] = 0.674, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58844 }, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[58847] = { ["id"] = 58847, ["name"] = "Kyrestia's Grace", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["series"] = { 58844, 58846, 58854, 59919 }, ["description"] = "I remember this particular soul...Uther. Devos brought him before us some time ago. She pleaded her case about his soul having a connection to the Maw. She then took him under wing, ascending him before he was ready. He became her other hand alongside Lysonia, as it were. He may proclaim a change of heart, but we shall see. Place him under guard. He may stay by the Archon's grace, but I will not take any chances with one so...broken.", ["objectivesText"] = "Escort Uther.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 175254, 178973, 183888, 183889, 183890, 183891, 183892, 183893, 184273 }, ["rewardChoices"] = { 183888, 183889, 183890, 183891, 183892 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166693, ["x"] = 0.674, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58846 }, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[58854] = { ["id"] = 58854, ["name"] = "Convene the Paragons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["series"] = { 58844, 58846, 58847, 59919 }, ["description"] = "We have defeated the Forsworn at every turn. Saved those not too far gone. Routed them from our blessed Archon's temples. Now only one remains. The Temple of Loyalty. Lysonia has grown desperate in defeat. Abandoned all we strive to uphold by embracing the Maw. She has rallied her most fervent loyalists to the temple, knowing we will come for her. We shall need the Paragons to finish this. Summon them.", ["objectivesText"] = "Summon the Paragons to call them to action. Progress: Without the Paragons we cannot prevail against Lysonia.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 62555 }, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[58856] = { ["id"] = 58856, ["name"] = "Who Are You Fooling?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "We cannot conduct the ritual without a very special guest. He's a silkstrider larva named Grubby and he's my best friend. Unfortunately, the nasty spriggans took him! What's worse is they cast illusions on what they steal, so no one can take it back! The spriggans often carry trickster powder. If you can take some of that stuff, I can reverse their illusions and rescue Grubby .", ["objectivesText"] = "Loot Sicklethorn Trickster Powder from Sicklethorn spriggans to dispel illusions on Conspicuous Objects and find Grubby . Progress: We need to find Grubby !", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4895, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 162392, ["questType"] = "standard", ["sourceQuests"] = { 58775 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58857] = { ["id"] = 58857, ["name"] = "Seeds Away!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "I think we have a problem. Plucking the seed from this root must have shaken some burrowed gorm awake. This isn't good! Grab on to me. I will fly us out of here, but we must stop the gorm before they overrun the local Vorkai defenses!", ["objectivesText"] = "Stop the gorm from overrunning the Gormhive Defense Wall and then pouring into the rest of Ardenweald! Progress: I can't believe this. Blue seeds, red seeds, flying faeries!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 163328, ["x"] = 0.4925, ["y"] = 0.701 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4895, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58939 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58858] = { ["id"] = 58858, ["name"] = "More Fetid Filets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58858 }, ["description"] = "Our little guy is getting hungry again. Could you pick him up a quick bite to eat?", ["objectivesText"] = "Collect 12 pieces of Corrupted Flesh from creatures in areas under assault by N'Zoth's minions. Progress: My, this thing has an appetite.", ["rewardItems"] = { 175015, 175016, 175049 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58813 } },
[58859] = { ["id"] = 58859, ["name"] = "Someone His Own Size", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58859 }, ["description"] = "While fighting alongside you no doubt provides excellent training for our hatchling, sometimes it is better to have him fight on his own against enemies his own size. I know of one such opponent nearby, observing the Amathet near the Obelisk of the Stars. You should seek it out.", ["objectivesText"] = "Defeat Retinus the Seeker in a pet battle with your Shadowbarb Hatchling in your party.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 33226, 71033, 151269, 172016, 175049 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58830 } },
[58860] = { ["id"] = 58860, ["name"] = "Big Bad Beetle", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58860 }, ["description"] = "It could do our hatchling some good to face off against another aqir, to learn what his kind are capable of. I have found an opponent who could provide a challenging fight.", ["objectivesText"] = "Defeat the Aqir Sandcrawler in a pet battle with your Shadowbarb Hatchling in your party.", ["rewardGold"] = 189240, ["rewardXP"] = 6815, ["rewardItems"] = { 94126, 163819, 167054, 175049, 186549, 188679 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58830 } },
[58861] = { ["id"] = 58861, ["name"] = "The Mantids' Mettle", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58861 }, ["description"] = "Observing the combat techniques of the mantid may prove helpful for our hatchling's training, offering a different way to use the natural weapons of an insect. I have found a mantid opponent that our hatchling could face in the Vale of Eternal Blossoms. Take him there and see how he does.", ["objectivesText"] = "Defeat the Vil'thik Hatchling in a pet battle with your Shadowbarb Hatchling in your party. Progress: How did our hatchling fare against the mantid?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 122457, 175049 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58830 } },
[58862] = { ["id"] = 58862, ["name"] = "The Littlest Defender", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58862 }, ["description"] = "The Baruk mogu are known for animating ancient statues to serve as defenders of their territory. They are a resilient foe, and much can be learned from battling an enemy with such rigid defenses. Fortunately, it seems like one of their Stoneshapers mistakenly animated a small idol. It has been discarded as useless to the mogu who made it, but it could prove a valuable training opportunity for our hatchling. Find this miniature defender in the Vale of Eternal Blossoms.", ["objectivesText"] = "Defeat the Baruk Stone Defender in a pet battle with your Shadowbarb Hatchling in your party.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 71076, 113554, 163684, 163819, 175049 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58830 } },
[58863] = { ["id"] = 58863, ["name"] = "A Custom Order", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58863 }, ["description"] = "I think it's safe to say that our little friend is no long a hatchling, but a fully grown aqir! He's grown so much, in fact, he could even carry you into battle. Wait, that's a marvelous idea! You should speak with Blacksmith Abasi about getting a saddle made.", ["objectivesText"] = "Speak with Blacksmith Abasi in Ramkahen. Progress: What do you need?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 164250, ["x"] = 0.54, ["y"] = 0.334 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58830 } },
[58865] = { ["id"] = 58865, ["name"] = "Otherworldly Armaments", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58865 }, ["description"] = "To craft a saddle for your beast, I'll need some special materials. Mainly, it will require metals much lighter than what we have available. I have noticed that the Black Empire cultists carry with them weapons made from otherworldly materials, which are impossibly light and strong. If you could retrieve some of their weapons for me, I may be able to melt down this metal and shape it into a saddle for the aqir.", ["objectivesText"] = "Collect 12 Black Empire Armaments from Black Empire cultists in Uldum and the Vale of Eternal Blossoms. Progress: Have you found my materials?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175058 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 164250, ["x"] = 0.54, ["y"] = 0.334 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 164250, ["x"] = 0.54, ["y"] = 0.334 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.334 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58863 } },
[58866] = { ["id"] = 58866, ["name"] = "My Own Drone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 58866 }, ["description"] = "The saddle is complete. I can't say I enjoyed working with that corrupted metal, but in the end I can easily say this is the finest saddle I have ever crafted. I know it looks... aggressive, but I assure you that your aqir will find it quite comfortable. I hope it serves you well.", ["objectivesText"] = "Bring the Otherworldly Saddle to H'Partho Adoros in Ramkahen. Progress: Was the blacksmith able to help?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 174771, 175059 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 164250, ["x"] = 0.54, ["y"] = 0.334 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.334 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["sourceQuests"] = { 58865 } },
[58869] = { ["id"] = 58869, ["name"] = "Battle for Hibernal Hollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 58719, 58720, 60621 }, ["description"] = "This is where we make our stand. The Drust and their minions have us nearly overrun. But we will not let them destroy Hibernal Hollow. Nor will they take our anima or our wildseeds. Fight with us. Let us drive them out.", ["objectivesText"] = "Win the Battle for Hibernal Hollow.", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169541, ["x"] = 0.598, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60621 }, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58871] = { ["id"] = 58871, ["name"] = "Broken Harts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "The curse on Qadarin is a powerful one. But I will break it. < Thiernax snorts.> Death did not part us. I will not be torn from him now. < Thiernax studies both you and Shandris with a serious look in his eyes.> Lend me your aid, and in turn I will help you with your world's Night Warrior. I do not promise I can save her... but I will share all that I know. Return to the Heart of the Forest and tell Lord Herne what has happened. We will meet there.", ["objectivesText"] = "Report to Lord Herne at the Heart of the Forest, then speak with Moonberry. Progress: This is even worse than I had thought.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161785, ["x"] = 0.396, ["y"] = 0.553 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 161785, ["x"] = 0.396, ["y"] = 0.553 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 161785, ["questType"] = "standard", ["sourceQuests"] = { 58704 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[58876] = { ["id"] = 58876, ["name"] = "Lost Flight", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10522, ["mapID"] = 84, ["storyline"] = { 58876 }, ["description"] = "<A small dragon emerges from one of the side chambers found within N'Zoth's great carapace. It appears confused. You surmise that such chambers must have been used to corrupt the dragons, exposing them directly to N'Zoth's dark whispers. At a young age, they would be driven mad, moreso than any other members of the twilight dragonflight that you had met before. There would be no turning back from such madness. But maybe it's not too late for this one...>", ["objectivesText"] = "Bring the Spawn of Vexiona to Wrathion in the Chamber of Heart. Provided item:", ["rewardItems"] = { 174862, 174863 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 174863 } },
[58877] = { ["id"] = 58877, ["name"] = "Death's Power Grows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12952, ["mapID"] = 1602, ["storyline"] = { 58877, 58902, 58903, 58989 }, ["description"] = "Listen closely, <name>. A time of great destruction lies on the horizon that will challenge our very existence. Now more than ever, we must rise to the defense of Azeroth. It is for this reason I have expanded the ranks of my champions to include your people. Your sacrifice sets you apart from all others. Hold your head high. Forevermore, you will be a death knight of the Ebon Blade. Now swear your fealty.", ["objectivesText"] = "Swear fealty to the Lich King . Progress: Swear your fealty, <name>.", ["rewardGold"] = 170800, ["rewardXP"] = 710, ["rewardItems"] = { 174485, 174486, 174487, 174488, 174659, 174660, 174661, 174662 }, ["rewardChoices"] = { 174488, 174487, 174486, 174485, 174660, 174661, 174659, 174662 }, ["starts"] = { { ["x"] = 0.495, ["y"] = 0.907, ["mapID"] = 1602, ["npcID"] = 163016 } }, ["ends"] = { { ["x"] = 0.495, ["y"] = 0.907, ["mapID"] = 1602, ["npcID"] = 163016 } }, ["coords"] = { ["mapID"] = 1602, ["x"] = 0.495, ["y"] = 0.907 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12952 } }, ["questGiverID"] = 163016, ["questTurnInID"] = 163016, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1035, ["name"] = "Death's Power Grows", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2297, ["db2PoiUiMapID"] = 1602 },
