[58900] = { ["id"] = 58900, ["name"] = "A Sure Bet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "You've made a name for yourself and earned the respect of everyone here, including Au'narim. You are ready, $p! Anzio is expecting us at the entrance to the Theater of Pain. You're going to be a champion!", ["objectivesText"] = "Meet Anzio at the entrance to the Theater of Pain.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161733, ["x"] = 0.504667, ["y"] = 0.515333 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59837 }, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58902] = { ["id"] = 58902, ["name"] = "Defender of Azeroth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12952, ["mapID"] = 1602, ["storyline"] = { 58877, 58902, 58989 }, ["description"] = "An excellent choice. Troubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor. But also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done. Speak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.", ["objectivesText"] = "Speak with Highlord Darion Mograine . Then, use the highlord's death gate to travel to Stormwind. Once there, visit Chromie .", ["rewardGold"] = 170800, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.495, ["y"] = 0.907, ["mapID"] = 1602, ["npcID"] = 163016 } }, ["ends"] = { { ["x"] = 0.495, ["y"] = 0.907, ["mapID"] = 1602, ["npcID"] = 163016 } }, ["coords"] = { ["mapID"] = 1602, ["x"] = 0.495, ["y"] = 0.907 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12952 } }, ["questGiverID"] = 163016, ["questTurnInID"] = 163016, ["questType"] = "standard", ["sourceQuests"] = { 58877 }, ["questLines"] = { { ["id"] = 1035, ["name"] = "Death's Power Grows", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2297, ["db2PoiUiMapID"] = 1602 },
[58903] = { ["id"] = 58903, ["name"] = "Defender of Azeroth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12952, ["mapID"] = 1602, ["storyline"] = { 58877, 58903, 58989 }, ["description"] = "An excellent choice. Troubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor. But also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done. Speak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.", ["objectivesText"] = "Speak with Highlord Darion Mograine . Then, use the highlord's death gate to travel to Orgrimmar. Once there, talk to Chromie .", ["rewardGold"] = 170800, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.495, ["y"] = 0.907, ["mapID"] = 1602, ["npcID"] = 163016 } }, ["ends"] = { { ["x"] = 0.495, ["y"] = 0.907, ["mapID"] = 1602, ["npcID"] = 163016 } }, ["coords"] = { ["mapID"] = 1602, ["x"] = 0.495, ["y"] = 0.907 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12952 } }, ["questGiverID"] = 163016, ["questTurnInID"] = 163016, ["questType"] = "standard", ["sourceQuests"] = { 58877 }, ["questLines"] = { { ["id"] = 1035, ["name"] = "Death's Power Grows", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2297, ["db2PoiUiMapID"] = 1602 },
[58904] = { ["id"] = 58904, ["name"] = "Shards of Corruption", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58904 }, ["description"] = "<You feel the pull of something dark and inhuman on your mind, it's writhing tendrils digging in, tugging at your sanity. You feel compelled to collect more shards... all of them.>", ["objectivesText"] = "Collect 20 Shards of Corruption . Progress: <The Idol tugs at your very being. Demanding you to touch it.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174867 }, ["ends"] = { { ["npcID"] = 341831, ["x"] = 0.603, ["y"] = 0.51, ["mapID"] = 1527 } }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["startItems"] = { 174867 } },
[58905] = { ["id"] = 58905, ["name"] = "Picking Up Pelagos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "Pelagos should have the seed by now! Can't start the ritual without the seed. He's likely still at Claw's Edge. We'll see you there!", ["objectivesText"] = "Meet up with Pelagos , Willowblossom , and Grubby at Claw's Edge.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["npcID"] = 162679 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 163328, ["x"] = 0.4925, ["y"] = 0.701 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4925, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questGiverID"] = 162679, ["questType"] = "standard", ["sourceQuests"] = { 58816 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58908] = { ["id"] = 58908, ["name"] = "Finding Your Way", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["series"] = { 59583 }, ["description"] = "Stormwind has a lot to offer adventurers like us, but it's far too big to explore on foot. The captain has arranged for you to receive a mount to help you get around. She said to speak with Curly at the stables in Old Town... but I can't seem to remember the way there. Have no worries, <name>! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go. Let's ask a nearby guard for directions to the stable master in Old Town!", ["objectivesText"] = "Speak with Curly at the stables in Old Town. Progress: Welcome to the stables, <class>. I've been expecting you.", ["rewardXP"] = 505, ["rewardItems"] = { 2411, 25470, 25474 }, ["rewardChoices"] = { 2411, 25470 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 163095, ["x"] = 0.713818, ["y"] = 0.739636 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 163007, ["x"] = 0.774, ["y"] = 0.671 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.713818, ["y"] = 0.739636 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 59583 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 49, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[58910] = { ["id"] = 58910, ["name"] = "What's Your Specialty?", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["requiredClasses"] = { 11 }, ["requiredRaces"] = { 4, 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 59254, 59350, 59583, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "Hey, <name>! Have you decided on a combat specialization yet? Since you're a <class>, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Mithlos Falconbriar to learn more about specializations!", ["objectivesText"] = "Speak with Mithlos Falconbriar to learn about combat specializations. Progress: Greetings. Have you come to learn about combat specializations?", ["rewardXP"] = 505, ["rewardItems"] = { 25470, 25474, 175165, 175166, 246462 }, ["starts"] = { { ["x"] = 0.774, ["y"] = 0.672, ["mapID"] = 84, ["npcID"] = 163097 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 164962, ["x"] = 0.792, ["y"] = 0.697 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.697 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questGiverID"] = 163097, ["questType"] = "standard", ["sourceQuests"] = { 58908 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 52, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[58911] = { ["id"] = 58911, ["name"] = "Home Is Where the Hearth Is", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "I don't know about you, but all this running around has got me thirsty! Why don't we head over to the Pig and Whistle Tavern and rest our legs over some cool pints of moonberry juice? While we're there, speak with Meagan the innkeeper to make the Pig and Whistle Tavern your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn. Not only is it faster than a gryphon, but you'll save a few copper in the process!", ["objectivesText"] = "Speak with Meagan Tillman to make the Pig and Whistle Tavern your home. Progress: How can I help you today, <class>? Are you looking for a place to stay?", ["rewardGold"] = 200, ["rewardXP"] = 505, ["rewardItems"] = { 6948 }, ["starts"] = { { ["x"] = 0.79, ["y"] = 0.698, ["mapID"] = 84, ["npcID"] = 163097 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 44237, ["x"] = 0.755333, ["y"] = 0.540667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.755333, ["y"] = 0.540667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questGiverID"] = 163097, ["questType"] = "standard", ["sourceQuests"] = { 58910, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 53, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[58912] = { ["id"] = 58912, ["name"] = "An Urgent Meeting", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 58912 }, ["description"] = "I've been looking for you all over Stormwind, <name>. The captain has delivered her report to the king. It appears that Stormwind requires your service yet again. The leaders of the Alliance have gathered together for a meeting at Stormwind Keep, and your presence has been requested by King Wrynn himself. I was instructed to find you and deliver the message without delay. It has been an honor serving with you, <name>. May the Light bless you on your journey.", ["objectivesText"] = "Speak with Captain Garrick at Stormwind Keep.", ["rewardXP"] = 125, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 163211, ["x"] = 0.754, ["y"] = 0.543333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 163219, ["x"] = 0.85, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.754, ["y"] = 0.543333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 58911 } },
[58914] = { ["id"] = 58914, ["name"] = "A Warrior's End", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 85678 }, ["description"] = "Hey, <name>! You're a <class>, right? Maybe you can deal with this... situation. I was scouting the area with Lindie's device and saw a ghost who was offering power to any \"true\" warriors. I know you're still new at this, but why don't you try going over there? We could use every advantage against these ogres.", ["objectivesText"] = "Speak with the strange ghost at the Darkmaul Bridge.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409, ["npcID"] = 156801 } }, ["ends"] = { { ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409, ["npcID"] = 156801 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.52, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 156801, ["questTurnInID"] = 156801, ["questType"] = "standard", ["sourceQuests"] = { 55194 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 1073, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[58915] = { ["id"] = 58915, ["name"] = "Hjalmar's Final Execution", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58914, 58915, 85678 }, ["description"] = "You now wield my most powerful skill, young warrior. Now use it to finish me! These ogres trapped my spirit here long ago for daring to defy them. Only through a glorious death will I finally be allowed to rest. It is the only way I will see my brothers and sisters in the afterlife.", ["objectivesText"] = "Slay Hjalmar the Undying . You must use Execute in order to truly kill him.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["x"] = 0.515, ["y"] = 0.478, ["mapID"] = 1409, ["npcID"] = 162943 } }, ["ends"] = { { ["x"] = 0.515, ["y"] = 0.478, ["mapID"] = 1409, ["npcID"] = 162943 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.515, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 162943, ["questTurnInID"] = 162943, ["questType"] = "standard", ["sourceQuests"] = { 58914 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 33, ["flags"] = 0 }, { ["id"] = 1073, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[58916] = { ["id"] = 58916, ["name"] = "Dread Priming", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Sire Denathrius has requested I help you prepare for the hunt. Every hunter must help prepare a soul here in the Grove of Terror. I have a stubborn soul here who's been quite uncooperative, Houndmaster Loksey . His time has come to be hunted. < The Fearstalker hands you a set of Hopebreaker Soul Chains .> Demoralize him. We can't let him leave here with any hope. The hunt is meant to break the souls so they become less... resistant to the processes of Revendreth .", ["objectivesText"] = "Prepare Houndmaster Loksey for the Penitent Hunt in the Grove of Terror.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 175770, 178873, 178994, 179388 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 169087, ["x"] = 0.505, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163221, ["x"] = 0.512, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57098 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58917] = { ["id"] = 58917, ["name"] = "A Rogue's End", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58917, 58933, 85678 }, ["description"] = "A rogue from the lost expedition, Coulston Nereus , tried scouting the island for any threats after they made landfall. The last time Henry saw him, he was headed for a cave not far from here. Can you make contact with Coulston? He may be able to help with our rescue mission. Oh, and be careful when heading north. Alaria spotted a vicious bear roaming the area.", ["objectivesText"] = "Use Stealth to sneak around and find the first expedition's rogue. Progress: Did you get the roots? Make sure that bear is far away when you pick them.", ["rewardGold"] = 1600, ["rewardXP"] = 250, ["rewardItems"] = { 174916 }, ["starts"] = { { ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409, ["npcID"] = 156801 } }, ["ends"] = { { ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409, ["npcID"] = 156801 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.52, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 156801, ["questTurnInID"] = 156801, ["questType"] = "standard", ["sourceQuests"] = { 55194 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 1074, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[58918] = { ["id"] = 58918, ["name"] = "Huwerath", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 58918 }, ["objectivesText"] = "Free the Half-Digested Soul", ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.282, ["y"] = 0.445, ["mapID"] = 1543, ["npcID"] = 169102 } }, ["ends"] = { { ["x"] = 0.282, ["y"] = 0.445, ["mapID"] = 1543, ["npcID"] = 169102 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questTurnInID"] = 169102, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Free the Half-Digested Soul", ["amount"] = 1, ["type"] = 0, ["objectID"] = 163156, ["orderIndex"] = 0 } }, ["db2VignetteID"] = 4379, ["db2VignetteName"] = "Huwerath" },
[58923] = { ["id"] = 58923, ["name"] = "A Paladin's Service", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58923, 58946, 85678 }, ["description"] = "I found something strange while using Lindie's Scout-o-Matic that you should probably know about. The ghost of a paladin appeared on the hill nearby. She looked straight at the Scout-o-Matic and asked for you. I don't understand a whole lot about paladins and the Light, but I think you may not want to ignore her.", ["objectivesText"] = "Speak with the paladin's ghost. Progress: Greetings, <name>. It is good to finally see you.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["x"] = 0.52, ["y"] = 0.554, ["mapID"] = 1409, ["npcID"] = 156801 } }, ["ends"] = { { ["x"] = 0.52, ["y"] = 0.554, ["mapID"] = 1409, ["npcID"] = 156801 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.52, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 156801, ["questTurnInID"] = 156801, ["questType"] = "standard", ["sourceQuests"] = { 55194 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 34, ["flags"] = 0 }, { ["id"] = 1077, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[58931] = { ["id"] = 58931, ["name"] = "Inquisitor Stelia's Sinstone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "You never truly escape your past, Maw Walker. Every venthyr once entered Revendreth as a soul, burdened by the immoralities of their mortal lives. Like all souls, they carved their true names and most shameful transgressions into sinstones. Knowledge that intimate can be a potent weapon, if wielded properly. Locate the sinstones of the inquisitors aiding the Accuser so that you may kill them. Start with Stelia. After they're dead, bring me the Accuser's sinstone. I will deal with her myself.", ["objectivesText"] = "Collect Avowed Crypt Keys and open crypts until you locate Inquisitor Stelia's Sinstone . Progress: Inquisitors hide their sinstones to protect themselves.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156823, ["x"] = 0.645, ["y"] = 0.497 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163576, ["x"] = 0.674, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.497 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57173 }, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58932] = { ["id"] = 58932, ["name"] = "Temel, the Sin Herald", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "<Before flying away, Echelon shouted an additional command.> Expropriate Temel as well. He will know how to exploit the sinstone properly.", ["objectivesText"] = "Defeat Cryptkeeper Kassir to earn Temel's obedience. Progress: Temel will not come willingly.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998 }, ["starts"] = { { ["x"] = 0.694, ["y"] = 0.539, ["mapID"] = 1525 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163576, ["x"] = 0.674, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57173 }, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58933] = { ["id"] = 58933, ["name"] = "The Deadliest of Poisons", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58917, 58933, 85678 }, ["description"] = "You've got the poison. Now it's time to take out that ogre. Gutgruk the Tough. He usually patrols around their citadel. Probably looking for your expedition as we speak! Poison your blades, then take that monster down.", ["objectivesText"] = "Kill Gutgruk the Tough.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["x"] = 0.456, ["y"] = 0.561, ["mapID"] = 1409, ["npcID"] = 163024 } }, ["ends"] = { { ["x"] = 0.456, ["y"] = 0.561, ["mapID"] = 1409, ["npcID"] = 163024 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.456, ["y"] = 0.561 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 163024, ["questTurnInID"] = 163024, ["questType"] = "standard", ["sourceQuests"] = { 58917 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 35, ["flags"] = 0 }, { ["id"] = 1074, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[58936] = { ["id"] = 58936, ["name"] = "Beast Control", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58936 }, ["description"] = "The Grove of Terror's dredbats have become aggressive due to the lack of anima caused by the drought. This is a formal request to cull their numbers. We must re-establish dominance over our creations. - Flockmaster Sergio", ["objectivesText"] = "Kill 6 Dredbats in the Grove of Terror.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 179719 }, ["starts"] = { { ["x"] = 0.496, ["y"] = 0.759, ["mapID"] = 1525, ["objectID"] = 355296 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163221, ["x"] = 0.512, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57098 }, ["questLines"] = { { ["id"] = 1192, ["name"] = "Beast Control", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58937] = { ["id"] = 58937, ["name"] = "Evil Grubbies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "Oh no! This place is littered with mites! They are cute like Grubby, but they grow into horrible gorm! If we cleared some of them out, then the Sylvari will have less to fight against later. They can burrow away, so it's best to burn them up with Pelagos' red seeds. They'll be good for something after all.", ["objectivesText"] = "Burn 20 Evolving Mites with Pelagos' Flamelash Seeds. Progress: How many more are there?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174291, 174843, 174845, 174938, 175153, 175982, 176446, 177052, 178155, 179941, 180633, 180766, 180778, 181295 }, ["rewardChoices"] = { 178155, 177052, 179941, 174291 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4895, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 162392, ["questType"] = "standard", ["sourceQuests"] = { 58905 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58938] = { ["id"] = 58938, ["name"] = "Gorm Ruin Everything", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "These red seeds will still prove useful. They come from a very dangerous plant and are quite unstable. If we are going to recover the blue seed we really need, then these might help. Let's clear out some of these gorm and search for the real seed.", ["objectivesText"] = "Kill 10 mature gorm. Progress: We need to clear a path.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4895, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 162392, ["questType"] = "standard", ["sourceQuests"] = { 58905 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58939] = { ["id"] = 58939, ["name"] = "The Blue Seed", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "I remember seeing a blue seed with red leaves nearby, but it was in a cave behind a wall of brambles. I didn't think of it at the time, but maybe you could use the red seeds to get us in? I wish I didn't mix up the instructions or we wouldn't be in this mess. But maybe it's all going to work out anyway. Let's go!", ["objectivesText"] = "Find the cave entrance , get through the blockage of brambles, and obtain the Ripened Anima Seed . Progress: This has been quite the fun adventure. Wouldn't you say?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["npcID"] = 165110 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 162392, ["x"] = 0.4895, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4895, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questGiverID"] = 165110, ["questType"] = "standard", ["sourceQuests"] = { 58937, 58938 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58941] = { ["id"] = 58941, ["name"] = "Alpha Bat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "Dredbats are quite useful to us. We make them just like stoneborn, but they lack their same... intelligence. With very little direction, they strike fear into stubborn souls' hearts. With the anima drought, our dominion over them has waned. One, Duskterror , has wreaked the most havoc. This presents us with an opportunity. Take this soul and draw her in. When she's weak, we can capture her for our own purposes.", ["objectivesText"] = "Hitch Houndmaster Loksey to the stake in the Grove of Terror. Then, weaken Duskterror to capture her. Progress: Is Duskterror captured?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175765, 175770, 178873, 178994 }, ["rewardChoices"] = { 175765 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163221, ["x"] = 0.512, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163221, ["x"] = 0.512, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58916 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58946] = { ["id"] = 58946, ["name"] = "The Divine's Shield", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 3, 4, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58923, 58946, 85678 }, ["description"] = "This island has been cursed by necrotic magic. The Light can only just reach this place. Call upon its Divine Shield to step through the barrier before us unharmed and destroy this vile altar. Show the darkness on this island that you are protected by the Light's embrace.", ["objectivesText"] = "Cross the necrotic barrier with Divine Shield and destroy the Necrotic Altar. You can speak with Yorah if you need to reduce Divine Shield's cooldown. Progress: Do you require aid? Use Divine Shield to safely pass through the necrotic barrier.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["x"] = 0.575, ["y"] = 0.522, ["mapID"] = 1409, ["npcID"] = 162998 } }, ["ends"] = { { ["x"] = 0.575, ["y"] = 0.522, ["mapID"] = 1409, ["npcID"] = 162998 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.575, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 162998, ["questTurnInID"] = 162998, ["questType"] = "standard", ["sourceQuests"] = { 58923 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 36, ["flags"] = 0 }, { ["id"] = 1077, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[58947] = { ["id"] = 58947, ["name"] = "Test Your Mettle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "Many of the greatest Maldraxxi legends earned their fame fighting in the Theater of Pain. If you want to follow in their footsteps, you need to prove you have what it takes to survive in there. Defeat Valuator Malus and Tester Sahaari in combat. Let's see what you can do!", ["objectivesText"] = "Valuator Malus and Tester Sahaari defeated. Progress: Earn the right to proceed!", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58575, 59800 }, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[58948] = { ["id"] = 58948, ["name"] = "Food on the Table", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["description"] = "I'm making a stew for dinner tonight, but it seems we're missing rabbit meat . Would you be able to go out back and collect some for me? Oh and do be careful, I heard howling earlier. The wolves aren't normally out during the day.", ["objectivesText"] = "Collect 4 Rabbit Meat . Progress: Shh shh, Gwendolyn. It's okay, baby girl.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 174935 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162953, ["x"] = 0.218, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162953, ["x"] = 0.218, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.218, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["sourceQuests"] = { 58791 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 49 },
[58949] = { ["id"] = 58949, ["name"] = "Millie's Garden", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["description"] = "Alma came by earlier and gave Millie some flower seeds to plant out in the garden. I love that our daughter is taking an interest in gardening, but I don't have time to wash her dress when she gets it covered in mud again! Would you help her with the digging so that she doesn't get too dirty?", ["objectivesText"] = "Use your shovel to till 3 Untilled Soil. Progress: <Millie giggles.> Hi daddy!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162953, ["x"] = 0.218, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 162962, ["x"] = 0.21, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.218, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["sourceQuests"] = { 58791 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 49 },
[58950] = { ["id"] = 58950, ["name"] = "Lumber for Lakeshire", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 49, ["storyline"] = { 58787, 58788, 58789, 58790, 58791, 58792, 58793, 58795, 58796, 58797, 58798, 58948, 58949, 58950, 58951 }, ["description"] = "Magistrate Solomon requested a bundle of wood for his hearth. However, he's been too busy to come by and retrieve it. If you wouldn't mind running it down to him at the town hall, I'm sure he'd appreciate it.", ["objectivesText"] = "Bring the Bundle of Lumber to Magistrate Solomon at the Lakeshire Town Hall. Progress: The folks are on edge, Ben. It's my job to keep them at ease.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174997 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 162953, ["x"] = 0.218, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 163111, ["x"] = 0.288, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.218, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["sourceQuests"] = { 58948, 58949 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 49 },
[58951] = { ["id"] = 58951, ["name"] = "Lakeshire's Last Stand", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["description"] = "There's no time to evacuate... not if the Scourge are here! Board the windows! Get everybody inside! Our only hope is to hide.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["starts"] = { { ["npcID"] = 163111, ["x"] = 0.288, ["y"] = 0.41, ["mapID"] = 49 } }, ["ends"] = { { ["npcID"] = 162542, ["x"] = 0.326, ["y"] = 0.398, ["mapID"] = 49 }, { ["npcID"] = 162542, ["x"] = 0.32, ["y"] = 0.212, ["mapID"] = 1533 }, { ["npcID"] = 162542, ["x"] = 0.454, ["y"] = 0.576, ["mapID"] = 1533 } }, ["coords"] = { ["x"] = 0.288, ["y"] = 0.41, ["source"] = "quest_giver", ["mapID"] = 1533 }, ["mapCandidates"] = { ["npc"] = { 49, 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 58950 }, ["questLines"] = { { ["id"] = 1090, ["name"] = "Trial of Ascension", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1090, ["questLineOrder"] = 2 } } },
[58952] = { ["id"] = 58952, ["name"] = "Purging Flames", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58952 }, ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.224, ["y"] = 0.641, ["mapID"] = 1527 } }, ["ends"] = { { ["x"] = 0.224, ["y"] = 0.641, ["mapID"] = 1527 } }, ["coords"] = { ["mapID"] = 1527, ["x"] = 0.224, ["y"] = 0.641 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10833 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 163078 }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 1, ["objectID"] = 163103 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58953] = { ["id"] = 58953, ["name"] = "A Priest's End", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58953, 58960, 85678 }, ["description"] = "You're a trained priest, right <name>? This might be up your alley. We've spotted the bodies of other recruits from our expedition. I'm guessing they washed up on a different part of the island. They didn't make it very far. When you have a moment, could you say a few prayers over them? Just to help put their spirits at ease. We'll give them a proper burial once we deal with the ogres.", ["objectivesText"] = "Find the corpses of the first expedition recruits.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409, ["npcID"] = 156801 } }, ["ends"] = { { ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409, ["npcID"] = 156801 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.52, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 156801, ["questTurnInID"] = 156801, ["questType"] = "standard", ["sourceQuests"] = { 55194 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 37, ["flags"] = 0 }, { ["id"] = 1082, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[58960] = { ["id"] = 58960, ["name"] = "Resurrecting the Recruits", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58953, 58960, 85678 }, ["description"] = "The souls of these recruits aren't strong enough tae resist the dark magic bein' practiced on this island. Use Resurrect on the remains of these recruits. Beseech the Light tae give 'em another chance while their souls still linger. I've been stranded on this island for years, watchin' these ogres get away with all of this. It's time tae make a stand.", ["objectivesText"] = "Resurrect the Expedition recruits. Progress: Get goin' and save those recruits with resurrect!", ["rewardGold"] = 2940, ["rewardXP"] = 250, ["starts"] = { { ["x"] = 0.561, ["y"] = 0.536, ["mapID"] = 1409, ["npcID"] = 163108 } }, ["ends"] = { { ["x"] = 0.561, ["y"] = 0.536, ["mapID"] = 1409, ["npcID"] = 163108 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.561, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 163108, ["questTurnInID"] = 163108, ["questType"] = "standard", ["sourceQuests"] = { 58953 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 38, ["flags"] = 0 }, { ["id"] = 1082, ["name"] = "Classical Learning", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[58962] = { ["id"] = 58962, ["name"] = "A Warlock's Bargain", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56344, 58962, 85678 }, ["description"] = "While you were mowing down hordes of undead, I was scouting more of the area with Lindie's device. I saw what looked like a portal out near the bridge, along with the corpse of a warlock we thought was lost in the shipwreck. Think you can go investigate the area and try to close that portal? We have enough problems on this island as it is.", ["objectivesText"] = "Investigate the first expedition warlock's corpse. Progress: I see you have the grimoire that enacted the binding ritual.", ["rewardGold"] = 1600, ["rewardXP"] = 250, ["rewardItems"] = { 174947 }, ["starts"] = { { ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409, ["npcID"] = 156801 } }, ["ends"] = { { ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409, ["npcID"] = 156801 } }, ["coords"] = { ["mapID"] = 1409, ["x"] = 0.52, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questGiverID"] = 156801, ["questTurnInID"] = 156801, ["questType"] = "standard", ["sourceQuests"] = { 55194 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 39, ["flags"] = 0 }, { ["id"] = 1078, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2175, ["db2PoiUiMapID"] = 1409 },
[58975] = { ["id"] = 58975, ["name"] = "Pest Removal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58975 }, ["objectivesText"] = "Burrowing Mite extracted Mature Gorm slain", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Burrowing Mite extracted", ["amount"] = 6, ["type"] = 0, ["objectID"] = 163212, ["orderIndex"] = 0 }, { ["text"] = "Mature Gorm slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 170182, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58976] = { ["id"] = 58976, ["name"] = "Chasing a Memory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["description"] = "The attack on the Temple of Purity is unprecedented in Bastion . At least, to my knowledge. We need to know more. The fragment that the Paragon captured may contain the answers we seek. There is a place nearby called the Mnemonic Locus. There, aspirants and ascended alike can call forth their memories and store them away. If we can look through this fragment's memories, perhaps we can learn more about the so-called Forsworn and, with luck, uncover their plan. I will meet you there. Go in service.", ["objectivesText"] = "Travel to the Mnemonic Locus.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 156238, ["x"] = 0.538, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57447 }, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58977] = { ["id"] = 58977, ["name"] = "What's In a Memory?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58800, 58978 }, ["description"] = "It may be possible to extract memories from fragment, but I worry they will not be useful. This is not whole kyrian, but a tiny piece! A weird, broken piece. It cannot even speak! We will apply extractor and see what comes out. Extractor might explode. It might not. For this? Worth the risk, I think. Do not know what will emerge. Could be memories. Could be nothing. Could be something else. May try to fight you! Stay on your guard, yes? Collect all that look Forsworn. Speak when ready.", ["objectivesText"] = "Collect memories of the Forsworn from the Fragment of Lysonia . Progress: Do you think we will get the information we need, <name>?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167038, ["x"] = 0.56, ["y"] = 0.6295 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.602667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58800 }, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58978] = { ["id"] = 58978, ["name"] = "Lysonia's Truth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58800, 58977 }, ["description"] = "If I had not seen it with my own eyes, I do not know that I would believe such a thing is possible. You carry a significant piece of Lysonia within you, now. Go to the Soul Mirrors and open yourself to them. With luck, they will draw from her essence to draw forth a memory of the Forsworn. If this works, we may know what they are planning within minutes!", ["objectivesText"] = "Stand before a Soul Mirror and witness memories from Lysonia's past.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167038, ["x"] = 0.56, ["y"] = 0.6295 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167034, ["x"] = 0.563333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.6295 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58977 }, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58979] = { ["id"] = 58979, ["name"] = "I MADE You!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["description"] = "I have had it with this insolence! I have an idea to reset this Mnemis's personality, but you will need to keep it busy. It will try to fight you, through whatever means it posseses. I suggest you try not to perish. Kleia can hold her own, so hide behind her if so inclined. Hop to it!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardChoices"] = { 173329, 173331, 173330, 173315 }, ["starts"] = { { ["npcID"] = 167034, ["x"] = 0.572, ["y"] = 0.552, ["mapID"] = 1533 } }, ["ends"] = { { ["npcID"] = 167035, ["x"] = 0.588, ["y"] = 0.652, ["mapID"] = 1533 } }, ["coords"] = { ["x"] = 0.572, ["y"] = 0.552, ["source"] = "quest_giver", ["mapID"] = 1533 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58978 }, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } } },
[58980] = { ["id"] = 58980, ["name"] = "Mnemis, At Your Service", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58843, 59196, 60013, 60180 }, ["description"] = "Greetings, I am Locus-Keeper Mnemis and I would be delighted to assist you. I recall that you are trying to access a particular memory. Due to the contents, that memory can only be viewed within the Vault of the Archon. In order to gain access to the Vault, you must collect offerings for the two guardians who watch over it. I have hidden these offerings from the Forsworn, as they are not authorized to enter. The Forgelite Prime is the only one among you who can grant authorization. How convenient!", ["objectivesText"] = "Locate two offerings within the Walk of Recollection, then proceed to the Vault of the Archon. Progress: Did you find the offerings of which I spoke?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167035, ["x"] = 0.578, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167035, ["x"] = 0.578, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58979 }, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[58983] = { ["id"] = 58983, ["name"] = "Battle for Azeroth: Tides of War", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 58983 }, ["series"] = { 46727, 46728, 46729, 47098, 47099, 51341, 57766, 59641, 60362 }, ["description"] = "King Wrynn has called us together for an urgent war council. It seems that there was some trouble with the Horde while we were away. The king was impressed with the valor and bravery that you demonstrated during our mission to Exile's Reach. Now that you've arrived, the meeting will begin without delay.", ["objectivesText"] = "Attend the War Council in Stormwind Keep. Progress: Thank you for coming.", ["rewardGold"] = 200, ["rewardXP"] = 125, ["rewardItems"] = { 178941, 178942 }, ["rewardChoices"] = { 178941, 178942 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 163219, ["x"] = 0.85, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 165395, ["x"] = 0.856, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.85, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 58912 } },
[58989] = { ["id"] = 58989, ["name"] = "Runeforging 101", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7543, ["mapID"] = 23, ["storyline"] = { 58877, 58902, 58903, 58989 }, ["description"] = "As knights of the Ebon Blade, we must always be prepared for a variety of martial situations. To this end, the dark art of runeforging is yours to command. With it, runes of great power can be engraved upon your weapons. Above us in the Heart of Acherus are runeforges. Visit one and use your power to imbue a weapon with a rune of power.", ["objectivesText"] = "Use the Runeforging ability in your spellbook to engrave a rune upon your weapon. You may freely replace the engraving at any time, so long as you are near a Runeforge. Progress: Have you emblazoned a rune upon your weapon, <name>?", ["rewardGold"] = 170800, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 29246, ["x"] = 0.82, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 29246, ["x"] = 0.82, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1035, ["name"] = "Death's Power Grows", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[58992] = { ["id"] = 58992, ["name"] = "Pie Not?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58992 }, ["description"] = "I want to cook something warm, savory, and gooey! That's right! I want to make a lovely bone marrow pie! When it's done, you'll be as full as a tick. I guarantee it! Now, just any old marrow won't do. I need the very best and rarest marrow. And that's where you come in! I need you to help Mama out and dig that marrow up. Yes... dig. Oh and be ready to knock some heads. Maldraxxus doesn't take kindly to being carved up.", ["objectivesText"] = "Collect 4 Maldraxxi Bone Marrow . Progress: Is there any kind of pie that's not just the best? Blood pie, bone marrow pie, bone marrow jelly...", ["rewardGold"] = 619600, ["rewardXP"] = 8165, ["rewardItems"] = { 177879, 181809, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161678, ["x"] = 0.552, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161678, ["x"] = 0.552, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60216 } },
