[58995] = { ["id"] = 58995, ["name"] = "I Dreamed A Dream", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["description"] = "This is quite a ceremony, everyone is here. This ritual is essential to the recreation of the Crest of Ascension and the preservation of Bastion . We owe the Winter Queen and Willowblossom a great debt. Someday, I hope we can repay them.", ["objectivesText"] = "Witness the ceremony. Progress: Do you have the vessel?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 163328, ["x"] = 0.4925, ["y"] = 0.701 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 163328, ["x"] = 0.4925, ["y"] = 0.701 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4925, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58857 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[58996] = { ["id"] = 58996, ["name"] = "Abel's Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58996 }, ["description"] = "Maw Walker, I have another task for you. Some time ago, I sent Soulwatcher Abel and a few others to slay some troublesome bonemaulers. They have yet to return. Go find them, will you?", ["objectivesText"] = "Investigate Soulwatcher Abel's fate. Progress: What became of Abel?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174957 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156384, ["x"] = 0.485, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156384, ["x"] = 0.485, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57136 }, ["questLines"] = { { ["id"] = 1189, ["name"] = "Abel's Fate", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[58997] = { ["id"] = 58997, ["name"] = "A Bittersweet Prize", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1565, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["series"] = { 61135 }, ["description"] = "I... I don't know what to say. All that is left is to return Willo... the vessel... to Polemarch Adrestes in Bastion . This sacrifice must not be in vain.", ["objectivesText"] = "Deliver the Vessel of Ardenweald to Polemarch Adrestes at Elysian Hold in Bastion .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 163328, ["x"] = 0.4925, ["y"] = 0.701 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4925, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = { 1533, 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58995 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[59000] = { ["id"] = 59000, ["name"] = "Elements of Corruption", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10504, ["mapID"] = 84, ["storyline"] = { 59000 }, ["description"] = "Corruption behaves in mysterious ways. It spreads beyond Azeroth herself, touching our most intimate thoughts and sometimes corrupting various relics, as you've seen firsthand. Though I cannot speak to the effects of these matters directly, I am sure MOTHER has information surrounding these so-called items of corruption.", ["objectivesText"] = "Speak with MOTHER to learn about corrupted items. Progress: What have you discovered?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questTurnInID"] = 155496, ["questType"] = "standard", ["sourceQuests"] = { 56377 } },
[59002] = { ["id"] = 59002, ["name"] = "A Shaman's Duty", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Greetings, young one. Your companions cannot see me. Only you, for you have been trained in the ways of a shaman. The shadow energies of this island have ensnared my pack. I need your aid to free them. Gather veil blossoms from the surrounding area. Burn them on the campfire and breath deep of their smoke. Then you will be able to see my packmates and release them from their bonds.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 163329, ["x"] = 0.522, ["y"] = 0.554, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 163329, ["x"] = 0.522, ["y"] = 0.554, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.554, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 55194 }, ["questLines"] = { { ["id"] = 1079, ["name"] = "Classical Learning", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5367, ["name"] = "A Dark Ritual", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 38, ["flags"] = 0 }, { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 40, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 212, ["title"] = "Exile's Reach", ["questLineID"] = 5367, ["questLineOrder"] = 1 } } },
