[59004] = { ["id"] = 59004, ["name"] = "Splash Damage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59004 }, ["description"] = "The Jailer's troops use anima charged runes to empower their armor. Without those runes, the troops will be significantly weaker! I developed this special formula to remove tough laundry stains, but it should be capable of removing magical runes as well! Splash my Putrification Potion on Rune-hardened troops, the bigger the better! Then collect the runes that fall off, so I can extract their anima.", ["objectivesText"] = "50 Anima Charged Runes collected off Rune-hardened Troops. Progress: Have you cleaned things up?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181625, 181638, 181645, 181647, 181649, 181651, 181662, 181675, 181676, 181677, 181678, 181689, 181693, 181695, 181982, 182657, 182684, 182772, 183202, 183487, 183490, 184305, 184772, 184773, 184774, 184775, 184776, 185485, 185729 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 163295, ["x"] = 0.328, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 }, { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
