[59008] = { ["id"] = 59008, ["name"] = "Spriggan Snares", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "I'm so glad you and Qadarin were passing by! These spriggans are crazy! Get me out of here! I was gathering some herbs from the garden when they nabbed me. I'm sure they've captured other souls, too!", ["objectivesText"] = "Free Cirrik and rescue 8 Captives. Progress: This behavior is unexpectedly bold for the spriggans.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 163385, ["x"] = 0.39, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 163385, ["x"] = 0.39, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 163385, ["questType"] = "standard", ["sourceQuests"] = { 58610 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[59009] = { ["id"] = 59009, ["name"] = "Her Rightful Place", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59025, 59185, 59190, 59210 }, ["description"] = "Mor'Bitan has met his end... and a painful one at that. Your fortitude contributed in no small part to my success. You have earned my allegiance... for the time being. There is much left to do, should you truly desire ownership of this realm. Let us regroup at the Seat.", ["objectivesText"] = "Return to the Seat of the Primus with your runeblade. Progress: Were you successful?", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 174934, 175409, 175451, 175452, 175453, 175454, 178655, 178656, 178657, 178684, 178940 }, ["rewardChoices"] = { 175452, 175454, 175453, 175451 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59025 }, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59011] = { ["id"] = 59011, ["name"] = "In Death We Are Truly Tested", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59011, 59206, 60737, 61715, 61716 }, ["description"] = "Vyraz is the one who trapped me within the Maw. He has long been in league with the House of Rituals and the House of Constructs. No doubt he intended to trap you within that hellish place as well. It is time he be brought to justice for his treason. Stand with me, and we will face him as one.", ["objectivesText"] = "Confront Vyraz about the death of Margrave Krexus.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 180663, 180664, 180665, 180666, 180667, 180668, 180669, 180670, 180671, 180672, 180673, 180790, 180791, 180792 }, ["rewardChoices"] = { 180791, 180663, 180666, 180664, 180792, 180673, 180668, 180672, 180667, 180665, 180790, 180669, 180671, 180670 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162801, ["x"] = 0.412, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 170309, ["x"] = 0.504, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59974 }, ["questLines"] = { { ["id"] = 1063, ["name"] = "The Empty Throne", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1063, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
