[59020] = { ["id"] = 59020, ["name"] = "The Third Fall of Kel'Thuzad", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58833, 59020, 62391, 62406 }, ["description"] = "The time has come to purge Maldraxxus of treachery. Our armies are rallied. Our allies stand ready. The machine of war is in motion. We must win this battle, or all of the Shadowlands will be lost.", ["objectivesText"] = "Remove Kel'Thuzad from Maldraxxus .", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 181822 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 174179, ["x"] = 0.62, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 174179, ["x"] = 0.62, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 174179, ["questType"] = "standard", ["sourceQuests"] = { 58833 }, ["questLines"] = { { ["id"] = 1118, ["name"] = "Assault on the House of Rituals", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1118, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[59021] = { ["id"] = 59021, ["name"] = "Herald Their Demise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Since the dawn of Revendreth , Temel has been charged with proclaiming the sins of souls for all to hear. Every soul here, including venthyr, has been forced to endure his wrathful pronouncements on at least one occasion. He will know how to wield Inquisitor Stelia 's sinstone to break through her defenses. Simply command him to do so after you locate the inquisitor, and eliminate her.", ["objectivesText"] = "Order Temel to read from Inquisitor Stelia 's sinstone, then kill her. Progress: Is the inquisitor dead?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175430, 175431, 175432, 175433 }, ["rewardChoices"] = { 175431, 175433, 175432, 175430 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163576, ["x"] = 0.674, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163576, ["x"] = 0.674, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58931, 58932 }, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59023] = { ["id"] = 59023, ["name"] = "Ending the Inquisitor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57161, 57173, 57175, 57176, 57180, 57182, 58931, 58932, 59021, 59023, 59232 }, ["description"] = "Inquisitor Vilhelm hides smugly in the back of the courtyard, flanked by several gargons and loyal venthyr. We must kill him to break the ward on the Accuser's sinstone, so that Lord Chamberlain can use it in his battle. Temel will once again help you penetrate the inquisitor's defenses. Do not tarry.", ["objectivesText"] = "Order Temel to read from Inquisitor Vilhelm 's sinstone, then kill him. Progress: Once the inquisitor is dead, the warding spell will be broken.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171100, 171101, 171102, 174930, 174998, 175442, 175443, 175444, 175445 }, ["rewardChoices"] = { 175442, 175445, 175444, 175443 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164166, ["x"] = 0.66, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164166, ["x"] = 0.66, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57175 }, ["questLines"] = { { ["id"] = 995, ["name"] = "The Accuser", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 995, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 995, ["questLineOrder"] = 27 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59025] = { ["id"] = 59025, ["name"] = "Straight to the Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59009, 59185, 59190, 59210 }, ["description"] = "The success of Mor'Bitan 's treachery has made him complacent. Let him enjoy the feeling, for it ends here. We will lure him out with this ritual... and we will avenge my margrave. Stand with me now, <name>. Together, we will make an example of this traitor.", ["objectivesText"] = "Kill Mor'Bitan . Progress: He will regret crossing me.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59190 }, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59042] = { ["id"] = 59042, ["name"] = "A Good Heart", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58665, 58668, 58670, 58671, 58677, 58680, 58686, 58727, 59042, 60041, 60042, 60048 }, ["description"] = "Despite the beliefs of most people, Emeni has a kind heart. Err...at least she will have one, once you give it to her! I can think of no one better than you, Maw Walker, to give Emeni a new heart. Perhaps this will warm her blood towards you. You might become friends or even soulbinds! Please select and place a heart in Emeni's construct.", ["objectivesText"] = "Place a heart in Emenis' construct. Progress: I hope you chose well!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162227, ["x"] = 0.242, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58686 }, ["questLines"] = { { ["id"] = 1089, ["name"] = "Soul Survivors", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59043] = { ["id"] = 59043, ["name"] = "Baker's Dozen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59043 }, ["description"] = "Under this very tent, I've prepared delicacies that would make demigods cry tears of joy. I'm always in need of more baking supplies! The brokers usually sell me eggs from parts near and far, but maybe this time you could help me out instead. You familiar with gorm? Big insect-like creatures native to Ardenweald. Well, if you find me some eggs of theirs, I'll bake you up something nice in return! Mama will even send Starchy to help you out.", ["objectivesText"] = "Travel to Ardenweald and collect 13 Hatchready Gorm Eggs .", ["rewardXP"] = 8165, ["rewardItems"] = { 181809, 183744, 184040, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161678, ["x"] = 0.552, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161678, ["x"] = 0.552, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60216 } },
[59063] = { ["id"] = 59063, ["name"] = "Curses!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "Oh, dear me, this is terrible! Just terrible! I know precisely which awful curse afflicts that poor soul! But these damnable spriggans keep stealing my scrolls, scattering them all over and ripping them apart! Now the falls are overrun with all manner of dangerous magic! The spriggans have the pieces of the scroll you need. Gather them along with a binding from one of the major hexes, and you can put it all back together.", ["objectivesText"] = "Retrieve 5 pieces of Shredded Scroll from Rotbriar spriggans and a Tattered Binding from a Major Hex to create a Sealed Scroll of Soul Rot . Progress: Hmm... Yes, this looks like it could be the one.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 175137, 175138, 177280 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 165867, ["x"] = 0.636, ["y"] = 0.226 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165867, ["x"] = 0.636, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 165867, ["questType"] = "standard", ["sourceQuests"] = { 59725 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[59068] = { ["id"] = 59068, ["name"] = "A Secret Never Spoken", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1701, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "The first reagent listed in the scroll is a secret never spoken . Well, that's easy. I know who has tons of secrets! Watcher Vesperbloom , our resident snoop. She keeps the Wild Hunt informed of any nefarious behavior that takes place in the forest. I know she'd be willing to give us a secret to save Qadarin's soul from dissolving in excruciating pain. I'll have Thiernax meet you wherever she's hidden them. It'll keep his mind off what's happening to his husband.", ["objectivesText"] = "Obtain a Secret Never Spoken from Watcher Vesperbloom 's records. Progress: Whew! This page... It's seen sights no one should ever see.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 175152, 175154 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.44, ["y"] = 0.371, ["mapID"] = 1701, ["npcID"] = 161509 } }, ["ends"] = { { ["x"] = 0.44, ["y"] = 0.371, ["mapID"] = 1701, ["npcID"] = 161509 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.44, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 161509, ["questTurnInID"] = 161509, ["questType"] = "standard", ["sourceQuests"] = { 59063 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[59069] = { ["id"] = 59069, ["name"] = "A Token of Lost Love", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "My sister, Alexstrasza, lost her prime consort, Korialstrasz, towards the end of our war with Deathwing. She has loved many in her long life, but none as deeply as he. I know in my heart she loves him still. Find Alexstrasza in the Vermillion Redoubt and ask for a token of her lost love. It will surely prove a powerful reagent for the counter-curse.", ["objectivesText"] = "Speak with Alexstrasza at the Vermillion Redoubt in Twilight Highlands. Progress: My sister loves with all of her heart...", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 6948, 63378, 63379, 175149, 187897 }, ["starts"] = { { ["x"] = 0.447, ["y"] = 0.39, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["ends"] = { { ["x"] = 0.447, ["y"] = 0.39, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.447, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 160262, ["questTurnInID"] = 160262, ["questType"] = "standard", ["sourceQuests"] = { 59063 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[59070] = { ["id"] = 59070, ["name"] = "A Sacrifice of Anima", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "The last thing we need for this counter-curse is some attuned anima. Of course, we don't have much to spare. That means this is more of a sacrifice than it normally would be. But you know what? The spriggans made this mess, so they should help clean it up. Some really nasty ones have been causing mischief in Tirna Scithe. They should have the anima we need. Thiernax looks like he could use some nice, vengeful, therapeutic spriggan stomping. I'll have him meet you there.", ["objectivesText"] = "Slay Spriggans in Tirna Scithe to collect Mischief-touched Anima . Progress: Have you handled those spriggans yet?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175139 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.44, ["y"] = 0.371, ["mapID"] = 1701, ["npcID"] = 161509 } }, ["ends"] = { { ["x"] = 0.44, ["y"] = 0.371, ["mapID"] = 1701, ["npcID"] = 161509 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.44, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questGiverID"] = 161509, ["questTurnInID"] = 161509, ["questType"] = "standard", ["sourceQuests"] = { 59063 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[59071] = { ["id"] = 59071, ["name"] = "Mending a Broken Hart", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1701, ["storyline"] = { 58610, 58647, 58669, 58704, 58871, 59008, 59063, 59068, 59069, 59070, 59071, 59725 }, ["description"] = "We have all the reagents for the counter-curse! Hurry up and cast it before Qadarin 's soul is lost, and Thiernax refuses to help you, and Tyrande is doomed to die horribly in the Maw, and everyone is sad! But no pressure.", ["objectivesText"] = "Perform the counter curse. Progress: I... I cannot thank you enough.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181301, 182172 }, ["rewardChoices"] = { 181301 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.44, ["y"] = 0.371, ["mapID"] = 1701, ["npcID"] = 161509 } }, ["ends"] = { { ["x"] = 0.44, ["y"] = 0.371, ["mapID"] = 1701, ["npcID"] = 161509 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.44, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 161509, ["questTurnInID"] = 161509, ["questType"] = "standard", ["sourceQuests"] = { 59068, 59069, 59070 }, ["questLines"] = { { ["id"] = 1099, ["name"] = "Night Warrior's Curse", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1099, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[59076] = { ["id"] = 59076, ["name"] = "The Minions of Mayhem", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 59076 }, ["description"] = "To all downtrodden and unappreciated hard workers of the Shadowlands: the time has come to rise up. Rise up and stick it to the fangs and the wings and the bonemen! Stick it to the brokers and the bossmons! I says we go into business for ourselves! Come to our secret meeting at the Ledge of Destiny. To all not-downtrodden warlords, Maw Walkers, and morally flexible powerful denizens: We are currently hiring muscle. If interested, please attend. Don't tell the fuzz.", ["objectivesText"] = "Attend the publicly posted \"Secret Meeting.\"", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[59087] = { ["id"] = 59087, ["name"] = "That Darn Fox!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 59087 }, ["description"] = "You! You there! I, Clarion Song , need your assistance. Yes, yes, give yourself a moment to bask in my glory. < Clarion Song gives you a moment.> Done? Good. I need you to catch a troublesome vulpin kit. He is positively barbaric! Running amok, causing havoc, ruining my beauty rest! He's using a concealing charm to make himself invisible, but I know it's him! Make yourself useful and catch that kit!", ["objectivesText"] = "Find and Catch Renny the Vulpin kit. Progress: Well? Did you catch it?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175114, 184396 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 163774, ["x"] = 0.508, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 163774, ["x"] = 0.508, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[59120] = { ["id"] = 59120, ["name"] = "Renny the Vulpin", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 59120 }, ["description"] = "<The small vulpin kit runs up to you with a cheerful bounce and an air of mischief. You, it seems, are interesting. Interesting enough that this child of Lord Renard of the Court of Winter has decided to tag along with you. What could possibly go wrong?>", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 175114, 180644, 180645, 180814, 180857, 180859, 180860, 180861 }, ["starts"] = { { ["x"] = 0.492, ["y"] = 0.519, ["mapID"] = 1565, ["npcID"] = 163903 } }, ["ends"] = { { ["x"] = 0.492, ["y"] = 0.519, ["mapID"] = 1565, ["npcID"] = 163903 } }, ["coords"] = { ["mapID"] = 1565, ["x"] = 0.492, ["y"] = 0.519 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 163903, ["questTurnInID"] = 163903, ["questType"] = "standard", ["sourceQuests"] = { 59087 } },
[59126] = { ["id"] = 59126, ["name"] = "Supply Chain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "My friend! I could sure use your expertise right now. One of our wagon convoys was attacked nearby! It was transporting critical supplies... and new goods for me to sell! It's important--no--vital, that we recover as much of that equipment as possible. So, you ready to go? Let's head out and salvage what we can!", ["rewardXP"] = 8165, ["rewardItems"] = { 183744, 184843 }, ["starts"] = { { ["npcID"] = 159238, ["x"] = 0.552, ["y"] = 0.682, ["mapID"] = 1536 } }, ["ends"] = { { ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686, ["mapID"] = 1536 } }, ["coords"] = { ["x"] = 0.552, ["y"] = 0.682, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 58410 } },
[59130] = { ["id"] = 59130, ["name"] = "The House of Plagues", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["description"] = "The House of Plagues was the first to fall in this conflict. We believed its demise was the result of a careless accident. If only we had known the truth sooner... But perhaps not all their knowledge was lost. Before you arrived, our scouts reported signs of movement near the wreckage of their necropolis. If any survivors remain, we'd be wise to add them to our ranks. But approach with caution. The toxic fallout may have left them mad... or worse.", ["objectivesText"] = "Search for survivors near the House of Plagues.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 173368, 173536, 173891, 175410, 180235, 180236, 180237, 180238, 180271 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60886 }, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59147] = { ["id"] = 59147, ["name"] = "The Hand of Purification", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "Nikolon was not alone. < Eridia stares grimly out over the temple grounds.> Long have I toiled over the aspirants in my care. Long have I tended to this temple under my Paragon. To know that so many have fallen, alone, is a blow. But this... wanton destruction! It will not stand. You will be my hand, <name>. Go forth. End them. All of them. My duty demands that I tend to those that remain. I will find you near the bridge when the way is clear.", ["objectivesText"] = "\"Cleanse\" the Temple of Purity by slaying enemies.", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57717 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[59171] = { ["id"] = 59171, ["name"] = "Prey Upon Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 58821, 59172 }, ["description"] = "My mission cannot progress without a supply of anima. Fortunately, the necromancers nearby have been kind enough to gather some into their maldracite crystals. You will relieve them of those crystals. They may be reluctant to part with them, but I trust you can be... persuasive.", ["objectivesText"] = "Collect 3 Anima-charged Maldracite . Progress: Do not fail me.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58751 }, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59172] = { ["id"] = 59172, ["name"] = "War is Deception", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 58821, 59171 }, ["description"] = "You have proven a useful ally, <name>. Mephiles undoubtedly possesses a wealth of information for us. However, the House of Rituals is unforgiving when it comes to betrayal. He will not talk. Not that it matters. The House of Eyes has ways to... extract a prisoner's knowledge without the use of words. Place the charged crystals around me. They will facilitate the interrogation.", ["objectivesText"] = "Prepare to interrogate Mephiles the Loyal. Progress: Let us reveal the truth.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174934, 175409, 175706, 178655, 178656, 178657, 178684, 178940 }, ["rewardChoices"] = { 175706 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58821, 59171 }, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59175] = { ["id"] = 59175, ["name"] = "The Eternal Revenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59175 }, ["description"] = "<On the shelves there are hundreds of other phylacteries of varying shapes and sizes. Many bear names - this one specifically has a etching with the name Mor'Bitan. Lady Vashj would be interested in this phylactery.>", ["objectivesText"] = "Take the phylactery of Mor'Bitan back to Lady Vashj.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[59179] = { ["id"] = 59179, ["name"] = "Daughter of the Night Warrior", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1670, ["storyline"] = { 59179, 59181, 59189, 59242, 60508, 60530 }, ["description"] = "In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance. And... Ardenweald 's destruction. These visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm. Shandris Feathermoon , Tyrande's daughter, is touched by dreams as well. Even now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.", ["objectivesText"] = "Find Shandris Feathermoon within Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.449, ["y"] = 0.388, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["ends"] = { { ["x"] = 0.449, ["y"] = 0.388, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.449, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 160262, ["questTurnInID"] = 160262, ["questType"] = "standard", ["sourceQuests"] = { 60272 }, ["questLines"] = { { ["id"] = 1064, ["name"] = "Daughter of the Night Warrior", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1064, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[59181] = { ["id"] = 59181, ["name"] = "Into the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1543, ["storyline"] = { 59179, 59181, 59189, 59242, 59246, 60508, 60530 }, ["description"] = "I have not seen Tyrande since she departed for Icecrown... but I see her in my dreams. She stalks a nightmarish landscape, brimming with the might of the Night Warrior. Such power is too much for any mortal to bear for long. I shudder to think of the toll it has taken on my minn'do. Highlord Fordragon has told me of the Maw. If you truly have braved its horrors before, then I ask that you guide me through them as well. We must find Tyrande and convince her to let go of the Night Warrior's rage.", ["objectivesText"] = "Take Shandris Feathermoon into the Maw.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 55049, 55050 }, ["starts"] = { { ["x"] = 0.392, ["y"] = 0.672, ["mapID"] = 1670, ["npcID"] = 164277 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 174833, ["x"] = 0.445, ["y"] = 0.411 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.411 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 10565 } }, ["questGiverID"] = 164277, ["questType"] = "standard", ["sourceQuests"] = { 59179, 59246 }, ["questLines"] = { { ["id"] = 1064, ["name"] = "Daughter of the Night Warrior", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1064, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[59183] = { ["id"] = 59183, ["name"] = "Drifting Sorrow", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59183 }, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.1936, ["y"] = 0.334, ["mapID"] = 1543, ["npcID"] = 14761 } }, ["ends"] = { { ["x"] = 0.1936, ["y"] = 0.334, ["mapID"] = 1543, ["npcID"] = 14761 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questTurnInID"] = 14761, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 158314 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["db2VignetteID"] = 3848, ["db2VignetteName"] = "Drifting Sorrow" },
[59184] = { ["id"] = 59184, ["name"] = "Borr-Geth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 59184 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 157833 } } },
[59185] = { ["id"] = 59185, ["name"] = "Entangling Web", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59009, 59025, 59190, 59210 }, ["description"] = "It would seem we have a means of luring Mor'Bitan to us. But what good is a web if the prey can run free? For these rituals to work, the liches require a magical conduit. They draw runes with finely ground maldracite to channel anima. I have no doubt Mor'Bitan's necromancers have ground maldracite in the area. If we gather enough, we can draw a rune of binding to trap our target. Work with haste, $p.", ["objectivesText"] = "Collect 8 jars of Maldracite Dust . Progress: I'm waiting.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59172 }, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59188] = { ["id"] = 59188, ["name"] = "Vaunted Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["description"] = "So you are from my baroness's home world? It must be a special one to breed such powerful individuals. The necromancers here have already begun preparation for Mor'Bitan's ritual. We should capitalize on their progress. Three necromancers act as the ritual's architects. Should we acquire their drafts, we could modify them to suit our purposes. Collect the plans... and feel free to savor your victims' torment.", ["objectivesText"] = "Collect Ritual Drafts from the three Architects. Progress: We are hopeful for your success.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 174934, 175409, 175446, 175459, 175460, 175461, 178655, 178656, 178657, 178684, 178940 }, ["rewardChoices"] = { 175459, 175461, 175460, 175446 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164297, ["x"] = 0.714667, ["y"] = 0.448667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164297, ["x"] = 0.714667, ["y"] = 0.448667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.714667, ["y"] = 0.448667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59172 }, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59189] = { ["id"] = 59189, ["name"] = "The Recovery of Tyrande Whisperwind", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1543, ["storyline"] = { 59179, 59181, 59189, 59242, 59246, 60508, 60530 }, ["description"] = "The Night Warrior's power is tearing Tyrande apart. Such rage... it is consuming her. <Shandris is silent a moment.> And yet, my mother speaks true. We cannot leave the souls of my people to suffer. We shall follow Tyrande into Torghast. We must find a way to save the spirits of the kaldorei. And in the process, pray that we can save my minn'do as well.", ["objectivesText"] = "Enter Torghast to recover Tyrande Whisperwind.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 174834, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 174834, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 60530 }, ["questLines"] = { { ["id"] = 1064, ["name"] = "Daughter of the Night Warrior", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1064, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[59190] = { ["id"] = 59190, ["name"] = "Seek Your Mark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59009, 59025, 59185, 59210 }, ["description"] = "I see why Draka sent you in her stead--you accomplish what she could not. We have all the pieces. Now, we must simply put them together. The steps to the ritual are simple: place our fractured crystals in formation around the obelisk. Then comes the sigil--*our* sigil. Use the maldracite powder to draw a binding glyph at the obelisk's base. When you are through, return to me.", ["objectivesText"] = "Prepare the ritual. Progress: Work swiftly.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59185, 59188, 59210 }, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59196] = { ["id"] = 59196, ["name"] = "Go in Service", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 58843, 58980, 60013, 60180 }, ["description"] = "We cannot waste any more time. We must get an audience with the Archon, before this next attack happens! We need to find a way to get you to Elysian Hold... and quickly! Hero's Rest is a place of respite for the aspirants of Bastion . You can see it floating above from across the fields. Meet me there when you can. I have a plan.", ["objectivesText"] = "Meet Kleia at Hero's Rest. Progress: We must get moving.", ["rewardGold"] = 23870, ["rewardXP"] = 175, ["rewardItems"] = { 35884, 35885, 35886, 35887, 62892, 62893, 62894, 198606, 198607, 198609, 198611, 198612, 198613, 228773, 228774, 228775, 228776, 228777, 228778, 228779, 237578, 245345, 263454, 263455, 263456, 263457, 263458, 263459, 263460 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167038, ["x"] = 0.56, ["y"] = 0.6295 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165042, ["x"] = 0.528, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.6295 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60013 }, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[59197] = { ["id"] = 59197, ["name"] = "Steward at Work", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 59198, 59199, 59200, 59426, 60005, 60006 }, ["description"] = "Stewards are useful for many reasons. They keep Bastion tidy, fix anything broken, and offer unrivaled companionship and support. Your new steward assistant should be able to repair the beacon. Then you can summon the Polemarch to Hero's Rest.", ["objectivesText"] = "Use Summon Steward to fix the Beacon of Invocation, then use it to summon Polemarch Adrestes .", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165045, ["x"] = 0.528, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165048, ["x"] = 0.53, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 59426 }, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[59198] = { ["id"] = 59198, ["name"] = "On Swift Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 59197, 59199, 59200, 59426, 60005, 60006 }, ["description"] = "Our revered Archon has decided to grace you with an audience. It is your duty to present your discoveries to her, then follow her wise judgment. She holds audience in Elysian Hold, part of the sprawling Spires of Ascension, the home of the Ascended. We shall carry you there, for it is a place for those who can fly.", ["objectivesText"] = "Fly with Adrestes to Elysian Hold.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 173316, 178041, 178042, 178043, 178140 }, ["rewardChoices"] = { 173316 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165048, ["x"] = 0.53, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 59197 }, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[59199] = { ["id"] = 59199, ["name"] = "Kyrestia, the Firstborne", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 59197, 59198, 59200, 59426, 60005, 60006 }, ["description"] = "I will escort you to hold audience with the Archon. I beseech you to present your information succinctly and directly. Our wise Archon will hear you and make a decision on the best course of action.", ["objectivesText"] = "Speak with Adrestes to address the Archon. Progress: None shall doubt the Archon, in her infinite wisdom.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 59198 }, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[59200] = { ["id"] = 59200, ["name"] = "The Wards of Bastion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59196, 59197, 59198, 59199, 59200, 59426 }, ["series"] = { 59197, 59198, 59199, 59426, 60005, 60006 }, ["description"] = "Each temple of Bastion is protected by a ward here in Elysian Hold. As long as the wards hold, no malevolent force can launch an assault. It is concerning that the Forsworn were able to attack Purity in such force... Your orders are to examine the wards. As long as they hold, Bastion stands strong.", ["objectivesText"] = "Investigate the temple wards in Elysian Hold. Progress: The wards each protect one of the temples of Bastion . If a ward is not active, that temple stands vulnerable.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 59199 }, ["questLines"] = { { ["id"] = 1068, ["name"] = "By the Archon's Will", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1068, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1068, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[59202] = { ["id"] = 59202, ["name"] = "Among the Chosen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["description"] = "Only one rune remains... We should return to the House of the Chosen and report to Margrave Krexus. He will want to know of our progress.", ["objectivesText"] = "Return to the House of the Chosen.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164843, ["x"] = 0.389333, ["y"] = 0.650667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59009, 59231, 60733 }, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59203] = { ["id"] = 59203, ["name"] = "Leave Me a Loan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "I run a myriad of businesses here. Betting rings, performance enhancers... whatever the customer is willing to purchase. However, a few of those customers are late with their payments. And a customer who does not pay is a customer without value. Please ask them to surrender what they owe. I trust you know what to do if they refuse.", ["objectivesText"] = "Collect 6 Anima Vials from the arena spectators. Progress: Do not try to cheat me out of anything I am owed. I will know.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59879 }, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59206] = { ["id"] = 59206, ["name"] = "Words of the Primus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1670, ["storyline"] = { 59011, 59206, 60737, 61715, 61716 }, ["series"] = { 61715, 61716 }, ["description"] = "Even in his absence, the wisdom of the Primus rings true. This message must have been put here to await one who proved worthy of hearing it. <Draka peers at you.> You came to Maldraxxus to learn why Bastion was invaded. Now you know that there is treachery in our ranks. And that there are noble souls here who will set things right. Tell your allies in Oribos all you have witnessed. See that the warning of the Primus reaches the Eternal Ones. It would be an honor to fight by your side again, <name>.", ["objectivesText"] = "Return to Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.391, ["y"] = 0.499, ["mapID"] = 1536, ["npcID"] = 164545 } }, ["ends"] = { { ["x"] = 0.391, ["y"] = 0.499, ["mapID"] = 1536, ["npcID"] = 164545 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.391, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 164545, ["questTurnInID"] = 164545, ["questType"] = "standard", ["sourceQuests"] = { 60737 }, ["questLines"] = { { ["id"] = 1063, ["name"] = "The Empty Throne", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1063, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[59207] = { ["id"] = 59207, ["name"] = "Unshackled Knowledge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59207 }, ["description"] = "These Forsworn are looting the artifacts contained in Kalliope's Rest. What is worse is they have captured many of the shrine's scholars. I fear they will interrogate these aspirants for knowledge about the artifacts held within the inner chamber of the shrine. Most escaped with me, but Lano, Eratus, and Tyrana have not returned yet.", ["objectivesText"] = "Free Curator Lano , Librarian Eratus , and Historian Tyrana .", ["rewardGold"] = 289575, ["rewardXP"] = 6125, ["rewardItems"] = { 173029, 173354, 175277, 175754, 175755, 180452 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159248, ["x"] = 0.399, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.399, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[59209] = { ["id"] = 59209, ["name"] = "Rebel Reinforcements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "< General Draven looks around.> We require additional reinforcements. I know of two here that are fiercely loyal to the true purpose of Revendreth . The Fearstalker left them here to be consumed by the anima drought due to their allegiance. They are both fully capable of assisting us in our mission. Take this anima stake and infuse them. Direct them to me, I will explain the situation.", ["objectivesText"] = "Recruit Watchmaster Boromod and Tactician Sakaa . Progress: Are our allies infused?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175414, 175427, 175428, 175429, 175770, 178873, 178994 }, ["rewardChoices"] = { 175427, 175429, 175428, 175414 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164394, ["x"] = 0.432, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168471, ["x"] = 0.398, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60313 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59210] = { ["id"] = 59210, ["name"] = "Tainted Cores", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58751, 58821, 59009, 59025, 59171, 59172, 59185, 59188, 59190, 59210 }, ["series"] = { 59009, 59025, 59185, 59190 }, ["description"] = "This lich seeks a reward for his assault on the House of Eyes. But the power he craves will be his downfall. We will use our knowledge of his secret ritual to lure him out of the House of Rituals. Take these crystals, <name>. Charge them with anima reclaimed from Mor'Bitan's slain minions. But fracture them first, so that they shatter as the ritual nears completion... but not before Mor'Bitan believes that it has begun. That is when we will strike.", ["objectivesText"] = "Fracture the three Depleted Anima Crystals, then charge the Fractured Anima Crystals with deceased Morbid Ritualists. Progress: Is it done?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 31088, 174934, 175409, 178655, 178656, 178657, 178684, 178940 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164326, ["x"] = 0.735, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59172 }, ["questLines"] = { { ["id"] = 1059, ["name"] = "Matron of Spies", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1059, ["questLineOrder"] = 11 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1059, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
