[59520] = { ["id"] = 59520, ["name"] = "Plaguefall: Knee Deep In It", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57301, 58431, 59430, 59520 }, ["description"] = "There are many in the House of Plagues who survived its destruction only to later fall victim to the plagues released in the explosion. Margrave Stradama herself was driven mad from a mixture of twelve different airborne poxes! These dangers still remain and spread out from the ruins, infecting new victims daily. I need you to travel into the ruins and recover samples from the victims there.", ["objectivesText"] = "Enter Plaguefall and recover 12 Poxedskin Samples and Margrave Stradama's Plasm . Progress: Have you brought me the Poxedskin Samples ?", ["rewardGold"] = 1158300, ["rewardXP"] = 2125, ["rewardItems"] = { 175531, 175532, 175533, 175534, 176057, 183724 }, ["rewardChoices"] = { 175532, 175534, 175531, 175533 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 165052, ["x"] = 0.594, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 165052, ["x"] = 0.594, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 59223 }, ["questLines"] = { { ["id"] = 1158, ["name"] = "Mixing Monstrosities", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59554] = { ["id"] = 59554, ["name"] = "A Fine Journey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 59554 }, ["description"] = "Aspirants new and ancient, take note! The heralded Agthia's Repose calls. Make the ceremonial journey and learn about the ancient fallen Paragon who saved this very realm! Find the Repose just a short ride southwest of Hero's Rest.", ["objectivesText"] = "Speak to Keeper Mnemis in Agthia's Repose.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.453, ["y"] = 0.598, ["mapID"] = 1533, ["objectID"] = 348558 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158078, ["x"] = 0.47, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60735 }, ["nextQuests"] = { 57549 } },
[59555] = { ["id"] = 59555, ["name"] = "Enemy at the Door", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1698, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "The remaining houses of Maldraxxus have joined forces against us. Their armies besiege the Seat of the Primus, and our defenses cannot hold forever. Our reserves have met the enemy in battle. I need you to break the siege. Report to Heirmir and Marileth. They will give you the means to rain destruction on our foes.", ["objectivesText"] = "Ride Ragewing and destroy the enemy forces.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182077 }, ["starts"] = { { ["x"] = 0.496, ["y"] = 0.507, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["ends"] = { { ["x"] = 0.496, ["y"] = 0.507, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.496, ["y"] = 0.507 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161907, ["questTurnInID"] = 161907, ["questType"] = "standard", ["sourceQuests"] = { 62448 }, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[59556] = { ["id"] = 59556, ["name"] = "Welcome To Our House", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["description"] = "Your ties to the other covenants had me doubting you would return. I see now that was foolish of me. Outsider or not, you have stood bravely beside the armies of Maldraxxus. I am confident the Primus would have welcomed you into our ranks with pride. One day, he might return as well. But we cannot afford to wait. In the Primus's absence, I will name you a Necrolord of Maldraxxus.", ["objectivesText"] = "Speak with Baroness Draka to be inducted as a Necrolord in the Maldraxxus covenant hall. Progress: There is no greater honor than to defend the Shadowlands as a Necrolord of Maldraxxus.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.495, ["y"] = 0.219, ["mapID"] = 1698, ["npcID"] = 158453 } }, ["ends"] = { { ["x"] = 0.495, ["y"] = 0.219, ["mapID"] = 1698, ["npcID"] = 158453 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.495, ["y"] = 0.219 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 158453, ["questTurnInID"] = 158453, ["questType"] = "standard", ["sourceQuests"] = { 58609 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150,