[59586] = { ["id"] = 59586, ["name"] = "What's Your Specialty?", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58911, 59254, 59342, 59355, 59356, 59583, 59586, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "Hey, <name>! Have you decided on a combat specialization yet? Since you're a <class>, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Dalgrun Steelpine to learn more about specializations!", ["objectivesText"] = "Speak with Dalgrun Steelpine to learn about combat specializations. Progress: Greetings. Have you come to learn about combat specializations?", ["rewardXP"] = 505, ["rewardItems"] = { 25470, 25474, 175165, 175166, 246462 }, ["starts"] = { { ["x"] = 0.774, ["y"] = 0.672, ["mapID"] = 84, ["npcID"] = 163097 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 164960, ["x"] = 0.792, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questGiverID"] = 163097, ["questType"] = "standard", ["sourceQuests"] = { 58908 }, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 55, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
