[59603] = { ["id"] = 59603, ["name"] = "In Shadowlands Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 59598, 61388, 63054 }, ["description"] = "As Maldraxxi, we are responsible for ensuring the security of the Shadowlands. When enemies emerge, we are the ones who face them! The threats to the Shadowlands are far more than any one of us can handle. That's where I come in. I will be your eyes on the field. Allow me to demonstrate with a simple task for Marileth, so that you may both reap the benefits of my services.", ["objectivesText"] = "Use the Command Table to send Marileth on an adventure. Progress: An easy task to complete.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.482, ["mapID"] = 1698, ["npcID"] = 165321 } }, ["ends"] = { { ["x"] = 0.388, ["y"] = 0.482, ["mapID"] = 1698, ["npcID"] = 165321 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.388, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 165321, ["questTurnInID"] = 165321, ["questType"] = "standard", ["sourceQuests"] = { 63054 }, ["questLines"] = { { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
