[59706] = { ["id"] = 59706, ["name"] = "Invitation for the Countess", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59343, 59676, 59701, 59706, 59707, 59708, 59711, 59719, 59720, 61492 }, ["series"] = { 59676 }, ["description"] = "The Countess, Harvester of Desire. Her wits are sharper than most swords. While I have never seen her carry a weapon, you must assume she is never unprotected. Her mansion mirrors my own, on the Northeastern side of Castle Nathria. Her dominion was that of the Castle Ward, and it is her authority that keeps the nobles in line. She will appreciate a secret message. I will send a dredger ahead with a plan to infiltrate her party. Meet him on the Bridge of Temptation. Good luck.", ["objectivesText"] = "Find Cudgelface on the Bridge of Temptation leading to the Eternal Terrace.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165661, ["x"] = 0.423, ["y"] = 0.531 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165658, ["x"] = 0.525, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.531 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59701, 61492 }, ["questLines"] = { { ["id"] = 1069, ["name"] = "The Court of Harvesters", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1069, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59707] = { ["id"] = 59707, ["name"] = "Invitation for the Tithelord", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59343, 59676, 59701, 59706, 59707, 59708, 59711, 59719, 59720, 61492 }, ["series"] = { 59708, 59711, 59719, 59720 }, ["description"] = "The Tithelord is a bully and a coward, just like every Harvester of Envy before him. He is still a force beyond our current reckoning. I have sent Nadjia and Temel to Pridefall Hamlet in the south to ascertain the best, most non-lethal way to reach the Tithelord. Meet them there and use caution. The Tithelord would kill you in less than the blink of an eye if he thought it would gain him more power or authority.", ["objectivesText"] = "Speak with Nadjia the Mistblade at Pridefall Hamlet.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165661, ["x"] = 0.423, ["y"] = 0.531 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165818, ["x"] = 0.722, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.531 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59701, 61492 }, ["questLines"] = { { ["id"] = 1069, ["name"] = "The Court of Harvesters", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1069, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59708] = { ["id"] = 59708, ["name"] = "Invitation for the Stonewright", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59343, 59676, 59701, 59706, 59707, 59708, 59711, 59719, 59720, 61492 }, ["series"] = { 59707, 59711, 59719, 59720 }, ["description"] = "The Medallion of Wrath is in the hands of the Stonewright. She is ancient, powerful, and responsible for creating the Stone Legion. She is not someone to be subtle with. It is a very dangerous thing to ask, but would you meet with General Draven at the Dominance Gate? If we are to see the Stonewright attend, she must know the severity of our request, which means both you and Draven walking right in the front door.", ["objectivesText"] = "Speak with General Draven at the Dominance Gate.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165661, ["x"] = 0.423, ["y"] = 0.531 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165865, ["x"] = 0.402, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.423, ["y"] = 0.531 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59701, 61492 }, ["questLines"] = { { ["id"] = 1069, ["name"] = "The Court of Harvesters", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1069, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59709] = { ["id"] = 59709, ["name"] = "Afterlife Goes On", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["series"] = { 59698, 59700 }, ["description"] = "A new dawn shines on Bastion. I had my reservations, but you have proven that honor yet remains in Maldraxxus . Take my hand once more. I will return you to the temple's entrance. Let all Maldraxxi know of our victory. And for the sake of peace, ensure that this never happens again.", ["objectivesText"] = "Fly with Xandria to the entrance of the Temple of Courage.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165412, ["x"] = 0.35, ["y"] = 0.5472 }, { ["mapID"] = 1533, ["npcID"] = 165752, ["x"] = 0.296, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165794, ["x"] = 0.4448, ["y"] = 0.5836 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.5472 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 59700 }, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[59710] = { ["id"] = 59710, ["name"] = "A Curious Invitation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59710, 59712, 59713, 59714, 59715, 59716, 59724, 59726, 59846, 59868 }, ["description"] = "Psst. You there. Yeah, you. You that Maw Walker them fangs been going on about? Huh. I figured you'd be bigger. Anyway, the Taskmaster wants to ahhh ... \"extend his compliments and an invitation to visit his workings.\" That's a fancy word for a bunch of rocks me and my mates are diggin' up. If you're keen an' all that, pop down to Feeder's Thicket and meet with the fang's courier, Araak. He'll get you sorted right out.", ["objectivesText"] = "Meet with Courier Araak . Progress: The Taskmaster don't like waiting.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 177713, 177714, 177765, 177881, 179359, 179979, 179980, 179981, 180177 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165859, ["x"] = 0.608, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 169238, ["x"] = 0.594667, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57174 }, ["questLines"] = { { ["id"] = 1142, ["name"] = "The Duelist's Debt", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59711] = { ["id"] = 59711, ["name"] = "Harvester of Envy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59343, 59676, 59701, 59706, 59707, 59708, 59711, 59719, 59720, 61492 }, ["series"] = { 59707, 59708, 59719, 59720 }, ["description"] = "Thank you for meeting us at a minimum safe distance from the Caretaker's Manor. There are enough people around here that may still find the idea of me in a cage to be worth the trouble. It is too dangerous for you or I to speak to the Tithelord . He is too impulsive and eager to please Denathrius. I recommend we send Temel . The stone fiend is a common messenger for Revendreth and few aside from a handful of observers will bat an eye at his arrival. Just shove him when you are ready.", ["objectivesText"] = "Guide Temel through the Caretaker's Manor and deliver Prince Renathal 's message to the Tithelord .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165818, ["x"] = 0.722, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165661, ["x"] = 0.423, ["y"] = 0.531 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59707 }, ["questLines"] = { { ["id"] = 1069, ["name"] = "The Court of Harvesters", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1069, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59712] = { ["id"] = 59712, ["name"] = "The Lay of the Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59710, 59712, 59713, 59714, 59715, 59716, 59724, 59726, 59846, 59868 }, ["description"] = "So, yeah, not sure why he wants you. Based on a long time working for him, I'm gonna say he wants to use you to do something unsavory to further his interests. But, I'm biased. I could tell you so many stories. Let's go check on my friend, Nadjia.", ["objectivesText"] = "Check on Nadjia and investigate Taskmaster Matyas's camp. Progress: Have you found Taskmaster Matyas's journal yet?", ["rewardGold"] = 193050, ["rewardXP"] = 710, ["rewardItems"] = { 177713, 177714, 177765, 177881, 179359, 179979, 179980, 179981, 180177 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 169238, ["x"] = 0.594667, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165921, ["x"] = 0.602, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.594667, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59710 }, ["questLines"] = { { ["id"] = 1142, ["name"] = "The Duelist's Debt", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59713] = { ["id"] = 59713, ["name"] = "Active Ingredients", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59710, 59712, 59713, 59714, 59715, 59716, 59724, 59726, 59846, 59868 }, ["description"] = "Matyas will be difficult to handle until we can take my sinstone from him. We need something to knock him out. Will you fetch a few ingredients for me, mortal? I have a cunning plan.", ["objectivesText"] = "Gather ingredients for Nadjia's mixture. Progress: Do you have the ingredients?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 177713, 177714, 177765, 177881, 179359, 179979, 179980, 179981, 180177 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165864, ["x"] = 0.6, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165864, ["x"] = 0.6, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59846 }, ["questLines"] = { { ["id"] = 1142, ["name"] = "The Duelist's Debt", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59714] = { ["id"] = 59714, ["name"] = "A Fine Vintage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59710, 59712, 59713, 59714, 59715, 59716, 59724, 59726, 59846, 59868 }, ["description"] = "We will need something special to use as the base of our mixture. To get him to drink it down he will have to believe you've brought him a gift. He fancies himself quite the connoisseur. Some ancient and stuffy vintage will tempt him. Check the old cellar near the ruins. It once held supplies. Perhaps a bottle still lingers in the depths. Araak and I will work out the other details.", ["objectivesText"] = "Bring Nadjia a fancy beverage. Progress: Have you found a suitable beverage?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 177713, 177714, 177765, 177881, 179359, 179979, 179980, 179981, 180177 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165864, ["x"] = 0.6, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165864, ["x"] = 0.6, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59846 }, ["questLines"] = { { ["id"] = 1142, ["name"] = "The Duelist's Debt", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59715] = { ["id"] = 59715, ["name"] = "Message for Matyas", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59710, 59712, 59713, 59714, 59715, 59716, 59724, 59726, 59846, 59868 }, ["description"] = "Alright. Everything is prepared. When you are ready, ask Courier Araak to summon Taskmaster Matyas as though you have just arrived. I am sure a gift of a favorite drink will tempt him and the poison we've concocted will incapacitate him long enough to take my sinstone from him. Our plan will work flawlessly!", ["objectivesText"] = "Summon Taskmaster Matyas back to camp.", ["rewardGold"] = 193050, ["rewardXP"] = 710, ["rewardItems"] = { 177713, 177714, 177765, 177881, 179359, 179979, 179980, 179981, 180177 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165864, ["x"] = 0.6, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 166081, ["x"] = 0.602, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59713, 59714 }, ["questLines"] = { { ["id"] = 1142, ["name"] = "The Duelist's Debt", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[59716] = { ["id"] = 59716, ["name"] = "Comfortably Numb", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59710, 59712, 59713, 59714, 59715, 59716, 59724, 59726, 59846, 59868 }, ["description"] = "A mortal in Revendreth . It's rumored that you can traverse the Maw? Astonishing. I have so many questions. But, I must restrain my curiosity. I have a ... shall we say ... proposition for you that I feel would be advantageous for us both. If it is true that you are able to freely travel these lands then you have access to certain information I cannot reach. You see how you could be useful to me? Come, let us discuss the matter further.", ["objectivesText"] = "Poison the Taskmaster to get Nadjia's sinstone . Progress: My sinstone, please.", ["rewardGold"] = 193050, ["rewardXP"] = 710, ["rewardItems"] = { 175415, 175416, 175417, 175418, 175495, 175496, 175497, 175498, 177713, 177714, 177765, 177881, 179359, 179979, 179980, 179981, 180177 }, ["rewardChoices"] = { 175496, 175498, 175497, 175495, 175415, 175418, 175417, 175416 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 166081, ["x"] = 0.602, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165864, ["x"] = 0.6, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59715 }, ["questLines"] = { { ["id"] = 1142, ["name"] = "The Duelist's Debt", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
