[59800] = { ["id"] = 59800, ["name"] = "Team Spirit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "Even if we're competing against each other, we're all Maldraxxi. That means we cheer on everyone, regardless of which side they're on. Enter the arena and douse the challengers with the contents of this flask. It may give them the edge they need to survive combat!", ["objectivesText"] = "Douse 15 Arena Challengers with the Flask of Team Spirit .", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174324, 175413, 177835, 177837, 177877, 177957 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161559, ["x"] = 0.544, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59750, 59781 }, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59801] = { ["id"] = 59801, ["name"] = "Take the Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "Wait! Before you enter, I would ask something of you. While we have not had a wildseed in some time, we did keep stores of anima. It served us well in staving off the gorm. Whatever has happened to my village, I do not want this power to remain in their hands. It will better serve Ardenweald in other groves. Keep an eye out for any anima within the village. We will put it to better use elsewhere.", ["objectivesText"] = "Collect 8 Animacones . Progress: Were you able to find any anima?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 155876, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 59802 }, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[59802] = { ["id"] = 59802, ["name"] = "The Crumbling Village", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58161, 58162, 58163, 58164, 58165, 58166, 59801, 59802 }, ["description"] = "This journal belonged to Lewor, the leader of our grove. It says he found something to use against the gorm, but what if it caused all this? There is only one way to be sure. Come with me to the village. Or what remains of it.", ["objectivesText"] = "Follow Partik .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 155876, 173800, 173872, 173873, 177878 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160439, ["x"] = 0.716, ["y"] = 0.324667 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.324667 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58162, 58163, 58164 }, ["questLines"] = { { ["id"] = 1164, ["name"] = "An Ominous Stone", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
