[59907] = { ["id"] = 59907, ["name"] = "Mawsworn Menace", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545, 60644, 61874 }, ["description"] = "Our knights are strong, but they don't stand much chance scattered against such an opponent. We need to thin the ranks of our foe. The Ebon Blade won't do us any good if they are cut down.", ["objectivesText"] = "Defeat 8 Mawsworn enemies in the Crucible of the Damned. Progress: Let your blade do the talking!", ["rewardGold"] = 269148, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["starts"] = { { ["x"] = 0.192, ["y"] = 0.57, ["mapID"] = 1648, ["npcID"] = 166723 } }, ["ends"] = { { ["x"] = 0.192, ["y"] = 0.57, ["mapID"] = 1648, ["npcID"] = 166723 } }, ["coords"] = { ["mapID"] = 1648, ["x"] = 0.192, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13570 } }, ["questGiverID"] = 166723, ["questTurnInID"] = 166723, ["questType"] = "standard", ["sourceQuests"] = { 59751 }, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648 },
[59910] = { ["id"] = 59910, ["name"] = "Fight and Flight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "Mograine and Emeni will lead the assault on the western gate. You and Xandria will advance from the east. Secure the area and slay all who oppose you. Once we have them surrounded, we can strike the final blow against Gharmal.", ["objectivesText"] = "Fly with Xandria to the House of Constructs.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 209888 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 171483, ["x"] = 0.362, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61145 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59914] = { ["id"] = 59914, ["name"] = "Fear to Tread", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "It appears we've escaped our enemies' notice for the moment. We should take the opportunity to scout the nearby area for signs of our allies. We will draw less attention alone. The Ebon Blade will hold back, awaiting my signal. Come, let us see what awaits us in this hellscape.", ["objectivesText"] = "Scout Calcis for any signs of your allies. Progress: Champion? Tell me this is not an illusion.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["starts"] = { { ["x"] = 0.215, ["y"] = 0.417, ["mapID"] = 1648, ["npcID"] = 165918 } }, ["ends"] = { { ["x"] = 0.215, ["y"] = 0.417, ["mapID"] = 1648, ["npcID"] = 165918 } }, ["coords"] = { ["mapID"] = 1648, ["x"] = 0.215, ["y"] = 0.417 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 165918, ["questTurnInID"] = 165918, ["questType"] = "standard", ["sourceQuests"] = { 59752, 59753, 59907 }, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648 },
[59915] = { ["id"] = 59915, ["name"] = "Soul in Hand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1648, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "My instincts were correct. Whatever dark magic binds these souls together also keeps them more or less coherent. It will take time, but we will find out what this thing knows. My interrogation will require use of the helm, but rest assured I will return it to your care. Let's bring our prize to the Lord Admiral.", ["objectivesText"] = "Return to Lady Jaina Proudmoore in Forlorn Respite.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["starts"] = { { ["x"] = 0.274, ["y"] = 0.308, ["mapID"] = 1648, ["npcID"] = 166723 } }, ["ends"] = { { ["x"] = 0.274, ["y"] = 0.308, ["mapID"] = 1648, ["npcID"] = 166723 } }, ["coords"] = { ["mapID"] = 1648, ["x"] = 0.274, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 166723, ["questTurnInID"] = 166723, ["questType"] = "standard", ["sourceQuests"] = { 59758 }, ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2364, ["db2PoiUiMapID"] = 1648 },
[59916] = { ["id"] = 59916, ["name"] = "The Butchers of Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 60043, 60050, 60510, 61770, 61771, 61773 }, ["description"] = "Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these monstrosities?! No! The butchers of Bastion made clear their hearts that day! They deserve only the eternal darkness that awaits them. Ensure that they meet it!", ["objectivesText"] = "Kill 10 House of Constructs forces in the Separation Chamber.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168743, ["x"] = 0.352, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168743, ["x"] = 0.352, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59910 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59917] = { ["id"] = 59917, ["name"] = "Kill Them, Of Course", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "These mindless monstrosities hail from the farthest reaches of the Shadowlands. The anima drought has fueled their relentless hunger, driving them to seek new sources. Their presence here is inconvenient, to put it mildly. They tear at the land searching for any anima they can find. We must thin their numbers and buy time to safeguard the knowledge locked within the Sepulcher. Exactly the sort of work you're accustomed to, yes?", ["objectivesText"] = "Slay 8 Enraged Gluttons . Progress: How did the hunting go?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166664, ["x"] = 0.43, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58619 }, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59919] = { ["id"] = 59919, ["name"] = "An Earned Bond", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["series"] = { 58844, 58846, 58847, 58854 }, ["description"] = "There is one more thing you should do, Maw Walker. In rebuilding the Crest of Ascension you have earned more than just the trust of your fellow kyrian. It would seem our Forgelite Prime, Mikanikos, has rather enjoyed your time together and would like to soulbind with you. Given his predilection towards, well, himself, I am as surprised as you are. You must have truly impressed him.", ["objectivesText"] = "Soulbind with Mikanikos. Progress: This is a moment to remember.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 58847 }, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[59920] = { ["id"] = 59920, ["name"] = "Light the Forge, Forgelite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57715, 57908, 57909, 58174, 59920, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["series"] = { 57713, 57908 }, ["description"] = "I think we have the materials I will need to light the forge, at long last. I am afraid the place is in a state of disrepair. Between failed attempts at working without anima and simple neglect, I cannot hope to work the forge as it currently stands. I would very much appreciate your help to get the place in order while I coax the forge to life once more.", ["objectivesText"] = "Help Forgelite Sophone .", ["rewardGold"] = 236340, ["rewardXP"] = 1415, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57263, 57265, 57267 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[59921] = { ["id"] = 59921, ["name"] = "All I Ever Will Be", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "This is the site of an ancient battle won by the previous Paragon of Courage. She sacrificed herself to serve the Shadowlands. I only hope my own end will prove as exemplary. Many of my disciples meditate upon the scrolls here. With them, we remember the foundation of our courage. Accompany Alexandros as he reflects on his shrines. Aid him in understanding where the source of his courage lies. He will learn that this afterlife is not the one suited for him.", ["objectivesText"] = "Reflect on the Scrolls of Remembrance with Alexandros Mograine. Progress: What have you learned?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165794, ["x"] = 0.4448, ["y"] = 0.5836 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165794, ["x"] = 0.4448, ["y"] = 0.5836 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.4448, ["y"] = 0.5836 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 59748 }, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[59922] = { ["id"] = 59922, ["name"] = "Do Not Forget", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1533, ["storyline"] = { 59625, 59645, 59648, 59650, 59653, 59659, 59678, 59698, 59700, 59709, 59748, 59894, 59921, 59922 }, ["description"] = "The Arbiter's judgment was, as always, infallible. Though Alexandros's devotion to the Light is undeniable, it is the memory of his loved ones that truly fuels his strength. He was meant for Maldraxxus , not Bastion. Nonetheless, our reclamation of the temple stands. My vengeance is not yet complete, but now I know that some of the Maldraxxi can still be trusted. Go now. Return to your leader with news of our victory today. And tomorrow, we shall purge our foes once and for all.", ["objectivesText"] = "Return to Draka in the Seat of the Primus.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 44362, 44363, 44364, 44365, 44785, 44788, 46723, 46800, 46824, 116404, 258990 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165794, ["x"] = 0.4448, ["y"] = 0.5836 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 165794, ["x"] = 0.4448, ["y"] = 0.5836 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.4448, ["y"] = 0.5836 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questTurnInID"] = 165794, ["questType"] = "standard", ["sourceQuests"] = { 59921 }, ["questLines"] = { { ["id"] = 1119, ["name"] = "Do Not Forget", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1119, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[59929] = { ["id"] = 59929, ["name"] = "Murloc Mania", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "The shore is littered with shipwrecks. This must be where the lost expedition crashed. We'll need more supplies to help the injured recover. The nearby murlocs stole most of what washed up. Slay those murlocs to get back what belongs to the Horde.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["starts"] = { { ["npcID"] = 166782, ["x"] = 0.618, ["y"] = 0.828, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 166782, ["x"] = 0.618, ["y"] = 0.828, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.618, ["y"] = 0.828, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59928 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59930] = { ["id"] = 59930, ["name"] = "Emergency First Aid", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "We must treat our wounded before we can begin for the missing expedition. Take this first aid kit and tend to the survivors. I'll handle the others nearby.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["rewardItems"] = { 174780 }, ["starts"] = { { ["npcID"] = 166782, ["x"] = 0.618, ["y"] = 0.828, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 166782, ["x"] = 0.618, ["y"] = 0.828, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.618, ["y"] = 0.828, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59929 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59931] = { ["id"] = 59931, ["name"] = "Finding the Lost Expedition", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Breka Grimaxe went north to look for survivors. Join her to see what she's found. I'm going to go up ahead to see if I can find anyone else. We'll meet again further within the island.", ["rewardGold"] = 285, ["rewardXP"] = 100, ["starts"] = { { ["npcID"] = 166782, ["x"] = 0.618, ["y"] = 0.828, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 166854, ["x"] = 0.582, ["y"] = 0.746, ["mapID"] = 1409 }, { ["npcID"] = 166906, ["x"] = 0.582, ["y"] = 0.746, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.618, ["y"] = 0.828, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59930 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59932] = { ["id"] = 59932, ["name"] = "Cooking Meat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "This is Won'sa , a shaman who was with the expedition. She is dying of starvation. A death unfit for the Horde! Slay some of the nearby wildlife for their meat and cook it over the fire. Won'sa can tell us what happened to the missing expedition after she eats.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["rewardItems"] = { 117 }, ["starts"] = { { ["npcID"] = 166906, ["x"] = 0.582, ["y"] = 0.746, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 166854, ["x"] = 0.582, ["y"] = 0.746, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.582, ["y"] = 0.746, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59931 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59933] = { ["id"] = 59933, ["name"] = "Enhanced Combat Tactics", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Won'sa said the quilboar have kidnapped the missing expedition. The quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs. I won't see you die by their hands. We're going to spar one last time. When we are done, you will cleave a path straight through the quilboar!", ["rewardGold"] = 565, ["rewardXP"] = 200, ["starts"] = { { ["npcID"] = 166906, ["x"] = 0.582, ["y"] = 0.746, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 166906, ["x"] = 0.582, ["y"] = 0.746, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.582, ["y"] = 0.746, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59932 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59934] = { ["id"] = 59934, ["name"] = "Enhanced Combat Tactics", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Won'sa said the quilboar have kidnapped the missing expedition... including my daughter. The quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs. I won't see you die by their hands. We're going to spar one last time. When we are done, you will cleave a path straight through the quilboar!", ["rewardGold"] = 565, ["rewardXP"] = 200, ["starts"] = { { ["npcID"] = 166906, ["x"] = 0.582, ["y"] = 0.746, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 166906, ["x"] = 0.582, ["y"] = 0.746, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.582, ["y"] = 0.746, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59932 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59935] = { ["id"] = 59935, ["name"] = "Northbound", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Da quilboar kidnapped da rest of da expedition and took dem north. Dey said dey gonna use da expedition for some sorta sacrifice! Ya gotta head north as fast as ya can ta stop dem!", ["rewardGold"] = 285, ["rewardXP"] = 100, ["starts"] = { { ["npcID"] = 175030, ["x"] = 0.582, ["y"] = 0.746, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 166996, ["x"] = 0.626, ["y"] = 0.698, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.582, ["y"] = 0.746, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59932, 59933, 59934 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59937] = { ["id"] = 59937, ["name"] = "Taming the Wilds", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 3 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "A hunter like yourself needs a good pet by your side. Did you not bring one with you? Hmm. I suppose I shall have to compensate for your lack of training. Listen closely and learn quickly. I will teach you how to tame a beast and make it your pet. You will need one if you are to fight the quilboar.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["starts"] = { { ["npcID"] = 166996, ["x"] = 0.626, ["y"] = 0.698, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 166996, ["x"] = 0.626, ["y"] = 0.698, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.626, ["y"] = 0.698, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59935 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59938] = { ["id"] = 59938, ["name"] = "Down with the Quilboar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "I have discovered that the quilboar are performing a shadow ritual on a survivor from the missing expedition. The ritual is being performed by the tribe's leader, Geolord Grek'og . Slay Grek'og and save the survivor. Show this brute that the Horde is not to be trifled with.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["starts"] = { { ["npcID"] = 166996, ["x"] = 0.626, ["y"] = 0.698, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167019, ["x"] = 0.562, ["y"] = 0.59, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.626, ["y"] = 0.698, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59935, 59937 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59939] = { ["id"] = 59939, ["name"] = "Forbidden Quilboar Shadow Magic", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Quilboar are savage and violent. I did not think they knew how to use shadow magic. Obviously, we cannot allow them to continue their rituals. And certainly not on members of the Horde. Slay the quilboar in the den. They must learn the fatal error of their ways.", ["rewardGold"] = 565, ["rewardXP"] = 200, ["rewardChoices"] = { 175181, 175213, 175183, 175215, 175182, 175214, 175180, 175212 }, ["starts"] = { { ["npcID"] = 166996, ["x"] = 0.626, ["y"] = 0.698, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167020, ["x"] = 0.562, ["y"] = 0.59, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.626, ["y"] = 0.698, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59935, 59937 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59940] = { ["id"] = 59940, ["name"] = "The Choppy Booster Mk. 5", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "You're in luck, 'cause I'm the ONE goblin who can help you find the rest of the expedition! Feast your eyes on this fancy device here. Stole it off a gnome, improved on it, and made it my own! I call it the Choppy Booster Mk. 5 . Use it to find Shuja and the others.", ["rewardGold"] = 285, ["rewardXP"] = 100, ["starts"] = { { ["npcID"] = 167019, ["x"] = 0.562, ["y"] = 0.59, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167019, ["x"] = 0.562, ["y"] = 0.59, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.562, ["y"] = 0.59, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59938, 59939 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59941] = { ["id"] = 59941, ["name"] = "Re-sizing the Situation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "I call this gadget \"the Re-Sizer.\" It's what I used to unshrink the Choppy Booster Mk. 5. Look, I'm gonna be honest. I got, at best, a passing understandin' of how this thing works. That means I'm gonna be pushing a lot of buttons to see what happens. I'm sure we'll figure out how to upsize one of these boars. Then we'll use it to trample those undead goons! You hold the Re-Sizer while I fiddle with it. Then just press the button and, uh... hope for the best?", ["rewardGold"] = 425, ["rewardXP"] = 150, ["starts"] = { { ["npcID"] = 167019, ["x"] = 0.562, ["y"] = 0.59, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167021, ["x"] = 0.562, ["y"] = 0.59, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.562, ["y"] = 0.59, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59940 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59942] = { ["id"] = 59942, ["name"] = "The Re-Deather", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "I got the perfect plan. You're gonna ride the Choppy Booster Mk. 5 and BLAST those walkin' cadavers from the sky! I hereby dub the Re-Sizer the \"Re-Deather.\" We're gonna show them where the undead belong! Er, except for OUR undead. They're totally fine. Anyway, hop on the Choppy Booster Mk. 5 and I'll pilot it. Once we save Wrathion , we'll blast our way to all the other survivors!", ["rewardGold"] = 1130, ["rewardXP"] = 250, ["rewardChoices"] = { 175161, 175172, 175171, 175170, 175173, 175174, 175162, 175169, 175165, 175168, 175163, 175167, 175164, 175166 }, ["starts"] = { { ["npcID"] = 167019, ["x"] = 0.562, ["y"] = 0.59, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167128, ["x"] = 0.524, ["y"] = 0.532, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.562, ["y"] = 0.59, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59941 }, ["questLines"] = { { ["id"] = 5369, ["name"] = "The Missing Expedition", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5369, ["questLineOrder"] = 0 } } },
[59943] = { ["id"] = 59943, ["name"] = "The Harpy Problem", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "The ogres are planning to sacrifice the rest of the expedition to fuel this ritual to control Kalecgos, leader of the blue dragonflight. It seems one of the survivors was taken to the hills north of here. Bo scouted ahead to investigate. Come, we'll see what he has found.", ["rewardGold"] = 860, ["rewardXP"] = 440, ["starts"] = { { ["npcID"] = 167219, ["x"] = 0.538, ["y"] = 0.522, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167291, ["x"] = 0.568, ["y"] = 0.462, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.538, ["y"] = 0.522, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59950 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59944] = { ["id"] = 59944, ["name"] = "The Rescue of Herbert Gloomburst", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "The harpies plan to sacrifice the expedition's mage, a Forsaken by the name of Herbert Gloomburst . Herbert's ethics are... questionable, but he always strives to serve the Horde. We'll need his magic to stop the ogres. Let's move.", ["rewardGold"] = 1720, ["rewardXP"] = 875, ["starts"] = { { ["npcID"] = 167290, ["x"] = 0.568, ["y"] = 0.462, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167182, ["x"] = 0.568, ["y"] = 0.462, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.568, ["y"] = 0.462, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59943 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59945] = { ["id"] = 59945, ["name"] = "Harpy Culling", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "The harpies seem to be in league with the ogres. Many of them are gathering to attack our camp. We must thin their numbers and thwart their attempts to eliminate us. Perhaps they will learn it is best to leave the Horde be.", ["rewardGold"] = 1720, ["rewardXP"] = 875, ["starts"] = { { ["npcID"] = 167291, ["x"] = 0.568, ["y"] = 0.462, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167291, ["x"] = 0.568, ["y"] = 0.462, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.568, ["y"] = 0.462, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59943 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59946] = { ["id"] = 59946, ["name"] = "Purge the Totems", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "The harpies have placed vile totems throughout the area to attain more power. We must destroy those totems in order to debilitate our foes. Take this torch and burn any totems you see. It is wise to weaken one's enemy before the fight even begins.", ["rewardGold"] = 1720, ["rewardXP"] = 875, ["rewardChoices"] = { 175200, 175238, 175202, 175233, 175201, 175232, 175199, 175231 }, ["starts"] = { { ["npcID"] = 167291, ["x"] = 0.568, ["y"] = 0.462, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167291, ["x"] = 0.568, ["y"] = 0.462, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.568, ["y"] = 0.462, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59943 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59947] = { ["id"] = 59947, ["name"] = "Message to Base", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Let us return to camp with Herbert in tow. We're one step closer towards thwarting the ogres and their plans.", ["rewardGold"] = 860, ["rewardXP"] = 440, ["rewardChoices"] = { 175192, 175224, 175194, 175226, 175193, 175225, 175191, 175223 }, ["starts"] = { { ["npcID"] = 167290, ["x"] = 0.568, ["y"] = 0.462, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167212, ["x"] = 0.522, ["y"] = 0.552, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.568, ["y"] = 0.462, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59944, 59945, 59946 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59948] = { ["id"] = 59948, ["name"] = "Westward Bound", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Thrall wants us to search west of here for the site of the next ritual. We could use your help. I've already died once. It's not an experience I'd care to repeat.", ["rewardGold"] = 860, ["rewardXP"] = 440, ["starts"] = { { ["npcID"] = 167221, ["x"] = 0.528, ["y"] = 0.564, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167225, ["x"] = 0.528, ["y"] = 0.564, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.528, ["y"] = 0.564, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59950 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59949] = { ["id"] = 59949, ["name"] = "Who Lurks in the Pit", ["level"] = 6, ["requiredLevel"] = 6, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "There's a whole lot of shadow energy coming from this pit. I'm guessing a ritual is being performed down there. And that means a sacrifice. Do you hear that? I've got the best hearing around, ever since I got this new ear sewn onto me. It sounds like there are some more of our soldiers trapped down there. Probably all webbed up. Won'sa and I will... stay up here and help anyone who gets out. You should jump in and rescue anyone who is left down there!", ["rewardGold"] = 2940, ["rewardXP"] = 1095, ["rewardChoices"] = { 175203, 175234, 175206, 175237, 175205, 175236, 175204, 175235 }, ["starts"] = { { ["npcID"] = 167225, ["x"] = 0.528, ["y"] = 0.564, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167212, ["x"] = 0.522, ["y"] = 0.552, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.528, ["y"] = 0.564, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59948 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 23, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59950] = { ["id"] = 59950, ["name"] = "Stocking Up on Supplies", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Provisioner Jin'hake managed to recover some other supplies from the shipwreck. Take a look at what he has before heading out.", ["rewardGold"] = 1500, ["rewardXP"] = 150, ["rewardItems"] = { 175239 }, ["starts"] = { { ["npcID"] = 167212, ["x"] = 0.522, ["y"] = 0.552, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167212, ["x"] = 0.522, ["y"] = 0.552, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.552, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59942 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59951] = { ["id"] = 59951, ["name"] = "A Druid's Form", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 11 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Thank you for rescuing me, . Allow me to aid you in your druidic studies. To escape from the pit, I took on the form of a stag. I may know of a way you can learn to do the same. Come with me. There is an ancient druid stone nearby. Let us use it to commune with the wilds.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 166575, ["x"] = 0.454, ["y"] = 0.492, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167473, ["x"] = 0.454, ["y"] = 0.492, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.454, ["y"] = 0.492, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59949 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 26, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59952] = { ["id"] = 59952, ["name"] = "A Hunter's Trap", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 3 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "If you want to be called a true hunter, you'll need to learn the art of trapping. Fortunately, I happen to be an expert in it. First, you will need to gather supplies from the surrounding area so you can fashion a proper freezing trap . Herbert can supply you with a mote of ice. Scavenge the area for other materials. You will need the trap to handle another issue that has recently arisen.", ["rewardGold"] = 1470, ["rewardXP"] = 200, ["starts"] = { { ["npcID"] = 167215, ["x"] = 0.524, ["y"] = 0.554, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167215, ["x"] = 0.524, ["y"] = 0.554, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.524, ["y"] = 0.554, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59947 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 27, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59953] = { ["id"] = 59953, ["name"] = "Hunting the Stalker", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 3 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Now that you have your trap, we can move onto the true problem at hand. A strange creature not native to this island has been stalking our camp. I think we should capture it and see how it can help us. Set the freezing trap within these ruins to lure it out. We'll see just what we are dealing with.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["starts"] = { { ["npcID"] = 167215, ["x"] = 0.524, ["y"] = 0.554, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167215, ["x"] = 0.524, ["y"] = 0.554, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.524, ["y"] = 0.554, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59952 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 28, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59954] = { ["id"] = 59954, ["name"] = "A Mage's Knowledge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "You've got some good spells for a novice mage. There are a few things holding you back, though. For instance, it's absolutely clear to me you don't know Polymorph . If you did, you would've been using it on the harpies that were attacking us! Let's fix that. My spellbook has details on how to cast it... but my captors threw it into the nearby lake. Grab it for me, would you? Oh, and don't look through the book beforehand. You will almost certainly regret it if you do.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167309, ["x"] = 0.522, ["y"] = 0.554, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167309, ["x"] = 0.522, ["y"] = 0.554, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.554, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59947 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 29, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59955] = { ["id"] = 59955, ["name"] = "The Best Way to Use Sheep", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "I can't send you off without making sure you can cast Polymorph correctly. Why, if you messed it up you may transform someone into something completely different! I want to make sure I'm around to take notes if that happens. Let's see... ah, Throg will do nicely! I can spot a prime test subject from a mile away. Shall we begin?", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167309, ["x"] = 0.522, ["y"] = 0.554, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167309, ["x"] = 0.522, ["y"] = 0.554, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.554, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59954 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 30, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59956] = { ["id"] = 59956, ["name"] = "A Monk's Focus", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "You fought well against the harpies, but you'll need even more skill to best the challenges ahead. We must meditate and focus if we are to gain more strength. Come. I know of a place we can go.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167308, ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167537, ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.52, ["y"] = 0.552, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59947, 59949 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 31, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59957] = { ["id"] = 59957, ["name"] = "One Last Spar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Let's have a quick sparring session before returning to camp. I can sense new power rising from within you. I want to see it in action!", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167537, ["x"] = 0.52, ["y"] = 0.552, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167212, ["x"] = 0.522, ["y"] = 0.552, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.52, ["y"] = 0.552, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59956 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 32, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59958] = { ["id"] = 59958, ["name"] = "A Paladin's Service", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "While you were destroying that army of the undead, the ghost of a paladin approached me... and asked for you! They floated over to the ruins nearby. You should see what this ghost wants. I do not know much about the Light... but I know not to ignore a ghost.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167216, ["x"] = 0.52, ["y"] = 0.554, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167179, ["x"] = 0.576, ["y"] = 0.52, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.52, ["y"] = 0.554, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59950 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 33, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59959] = { ["id"] = 59959, ["name"] = "The Brand Holds the Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59960, 59962, 59966, 59973, 59974, 60972 }, ["description"] = "<Darion is unresponsive. The cage is locked, and doesn't appear easily broken. Perhaps the holder of the key is this \"Brand\" he mentioned.>", ["objectivesText"] = "Find the key to free Darion. Progress: Are you willing to listen to my proposition?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["x"] = 0.383, ["y"] = 0.485, ["mapID"] = 1543, ["objectID"] = 355798 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 171770, ["x"] = 0.3555, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3555, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["sourceQuests"] = { 59960 }, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960 },
[59960] = { ["id"] = 59960, ["name"] = "A Cooling Trail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13587, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59962, 59966, 59973, 59974, 60972 }, ["description"] = "<The amulet burns hot in your hand. The magic that runs through it tugs slightly at your grip. Perhaps the enchantment spoken of by Bolvar can now be used to find Mograine.>", ["objectivesText"] = "Use the Amulet of the Horsemen to find Darion Mograine.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["ends"] = { { ["npcID"] = 355798, ["x"] = 0.384, ["y"] = 0.485, ["mapID"] = 1543 }, { ["npcID"] = 355798, ["x"] = 0.384, ["y"] = 0.485, ["mapID"] = 1543 } }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["sourceQuests"] = { 60972 }, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960 },
[59961] = { ["id"] = 59961, ["name"] = "A Priest's End", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "You're a trained priest, right ? I have a grim request for you. I passed by some injured members of the first expedition. I did what I could... but they were too far gone. Can you perform a ritual to lay them to rest? Their spirits deserve to rest with honor.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167216, ["x"] = 0.52, ["y"] = 0.554, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167188, ["x"] = 0.562, ["y"] = 0.536, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.52, ["y"] = 0.554, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59950 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 34, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59962] = { ["id"] = 59962, ["name"] = "Hope Never Dies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59960, 59966, 59973, 59974, 60972 }, ["description"] = "So, mortal, you are here looking for someone. Well it just so happens that, clever as I am, it's quite possible I know where they are. Allow me to propose a trade. That amulet you carry... it holds an interesting power. You give me the amulet, and I will help you find this Maldraxxi baron. And then you will leave. I don't mean to be rude, but I really prefer to keep a low profile. Allow me to speed things along.", ["objectivesText"] = "Follow Ve'nari .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 171770, ["x"] = 0.3555, ["y"] = 0.559 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 171770, ["x"] = 0.3555, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3555, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["sourceQuests"] = { 59959 }, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960 },
[59965] = { ["id"] = 59965, ["name"] = "Resurrecting the Recruits", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 5 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Ya gotta cast Resurrection on dese recruits ta be savin' dem. Da necrotic magic of dis place be tuggin' at deir souls. Quickly, now!", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167188, ["x"] = 0.562, ["y"] = 0.536, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167188, ["x"] = 0.562, ["y"] = 0.536, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.562, ["y"] = 0.536, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59961 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 35, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59966] = { ["id"] = 59966, ["name"] = "Delving Deeper", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59960, 59962, 59973, 59974, 60972 }, ["description"] = "It's quite a thrill to have a mortal for a business partner! The amulet really is intriguing. What's that? Oh yes, that baron you're searching for... Well it so happens that I learned of a Maldraxxi warlord being held in the lower courtyard of Perdition Hold. As you might guess by the name, it's not the most charming of places. I would prefer to avoid the attention of the Jailer's forces. Fortunately, I have just the thing. Give the word, and I will conceal us from the Mawsworn.", ["objectivesText"] = "Follow Ve'nari to Perdition Hold.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 171770, ["x"] = 0.3555, ["y"] = 0.559 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 172414, ["x"] = 0.33, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3555, ["y"] = 0.559 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["sourceQuests"] = { 59962 }, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960 },
[59967] = { ["id"] = 59967, ["name"] = "A Rogue's End", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Shuja mentioned a rogue from the first expedition. Goes by Drizza Sidestabber . Drizza was last seen heading northwest... towards a large bear's den. None of us can sneak around like you. See if you can find Drizza and bring her back here.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167216, ["x"] = 0.52, ["y"] = 0.554, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167586, ["x"] = 0.456, ["y"] = 0.56, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.52, ["y"] = 0.554, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59950 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 36, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59968] = { ["id"] = 59968, ["name"] = "The Deadliest of Poisons", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "You've got the poison. Now you gotta to take out that ogre. Goon's name is Gutgruk the Tough. He usually patrols around the citadel. I betcha it's lookin' for your expedition right now! Poison your blades, then take that monster down. Show him he ain't so tough!", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167586, ["x"] = 0.456, ["y"] = 0.56, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167216, ["x"] = 0.52, ["y"] = 0.554, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.456, ["y"] = 0.56, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59967 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 37, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59969] = { ["id"] = 59969, ["name"] = "A Shaman's Duty", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["storyline"] = { 59969 }, ["description"] = "Greetings, young one. Your compatriots cannot see me. Only you, for you have been trained in the ways of a shaman. The necrotic energies of this island have ensnared my pack. I need your aid to free them. Gather veil blossoms from surrounding area. Burn them on the campfire and breath deep of their smoke. Then you will be able to see my packmates and release them from their bonds.", ["objectivesText"] = "Gather 4 ghost blossoms to burn on the campfire in order to rescue the ghost wolf 's companions.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 174947, 174968 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard" },
[59970] = { ["id"] = 59970, ["name"] = "A Warlock's Bargain", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "While scouting the area, I saw an open portal near the bridge up the hill. That does not bode well for any of us. It seemed like another warlock tried to seal the portal, but failed. I know you dabble in such... affairs. Perhaps you could put your knowledge to good use and close that portal.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167216, ["x"] = 0.52, ["y"] = 0.554, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167481, ["x"] = 0.526, ["y"] = 0.456, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.52, ["y"] = 0.554, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59950 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 39, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59971] = { ["id"] = 59971, ["name"] = "A Warrior's End", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Hail, ! You've grown stronger since we sparred on the boat. You may one day become a warrior of great renown! Speaking of which... I encountered a ghost on the bridge to the north that demands to meet a true warrior. Perhaps you can see what it wants. It did not seem hostile. It might even be willing to help us.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 167216, ["x"] = 0.52, ["y"] = 0.554, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 162943, ["x"] = 0.516, ["y"] = 0.478, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.52, ["y"] = 0.554, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59950 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 40, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59972] = { ["id"] = 59972, ["name"] = "Hjalmar's Final Execution", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "You now wield my most powerful skill, young warrior. Now use it to finish me! These ogres trapped my spirit here long ago for daring to defy them. Only through a glorious death will I finally be allowed to rest. It is the only way I will see my brothers and sisters in the afterlife.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["starts"] = { { ["npcID"] = 162943, ["x"] = 0.516, ["y"] = 0.478, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167216, ["x"] = 0.52, ["y"] = 0.554, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.516, ["y"] = 0.478, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59971 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 41, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59973] = { ["id"] = 59973, ["name"] = "A Bond Beyond Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59960, 59962, 59966, 59974, 60972 }, ["description"] = "Since crossing into the Shadowlands, I've been so focused on our mission that I never even considered the souls of my family being here somewhere. Whatever this realm called Maldraxxus is, I hope it is worthy of my father's service! We must free him, <name>. There is... much I need to say to him.", ["objectivesText"] = "Protect Darion while he frees Alexandros. Progress: Every moment spent here tears at one's soul.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 172414, ["x"] = 0.33, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 172414, ["x"] = 0.33, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["sourceQuests"] = { 59962 }, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960 },
[59974] = { ["id"] = 59974, ["name"] = "A Soul Saved", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59960, 59962, 59966, 59973, 60972 }, ["description"] = "Vyraz... all this time... This cannot stand, <name>. We must avenge Krexus and cut him down! He must have sent you to the Maw expecting that you would never return. He underestimated you. A fatal mistake. Go with Mograine and claim Vyraz's head. I will warn our forces at the Seat of the Primus.", ["objectivesText"] = "Meet Alexandros Mograine at the House of the Chosen in Maldraxxus .", ["rewardGold"] = 28900, ["rewardXP"] = 175, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["x"] = 0.391, ["y"] = 0.499, ["mapID"] = 1670, ["npcID"] = 167903 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162801, ["x"] = 0.412, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 10565 } }, ["questGiverID"] = 167903, ["questType"] = "standard", ["sourceQuests"] = { 62654 }, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59975] = { ["id"] = 59975, ["name"] = "To Darkmaul Citadel", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "The last remaining survivor is being held within the ogre's citadel. Crenna and Herbert have a plan to get us inside. A small group of us will gather up north. You're coming with us. If we fail here, the ogres will gain control of Kalecgos and his powerful blue dragon magic.", ["rewardGold"] = 1000, ["rewardXP"] = 505, ["starts"] = { { ["npcID"] = 167212, ["x"] = 0.522, ["y"] = 0.552, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167596, ["x"] = 0.522, ["y"] = 0.552, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.552, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59947, 59949, 59951, 59955, 59957, 60162, 85679 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 42, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59978] = { ["id"] = 59978, ["name"] = "Right Beneath Their Eyes", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "We need to get into Darkmaul Citadel, rescue the last survivor, and stop Gor'groth. Herbert and Crenna are going to cast a spell to make you look an ogre... and then you're going to take us in as your \"prisoners.\" Speak with Herbert when you're ready.", ["rewardGold"] = 2000, ["rewardXP"] = 1010, ["starts"] = { { ["npcID"] = 167596, ["x"] = 0.522, ["y"] = 0.552, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167633, ["x"] = 0.402, ["y"] = 0.324, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.522, ["y"] = 0.552, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59975 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 43, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59979] = { ["id"] = 59979, ["name"] = "Like Ogres to the Slaughter", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "This is worse than I thought. The ogres were counting on us to stage a rescue attempt. It seems that they plan to attack our camp while they near completion of the ritual. We can't let that happen. Crush the ogres! Show them the strength of the Horde!", ["rewardGold"] = 2000, ["rewardXP"] = 1010, ["rewardChoices"] = { 175186, 175218, 175184, 175216, 175187, 175219, 175185, 175217 }, ["starts"] = { { ["npcID"] = 167632, ["x"] = 0.402, ["y"] = 0.324, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167632, ["x"] = 0.402, ["y"] = 0.324, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.402, ["y"] = 0.324, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59978 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 44, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59980] = { ["id"] = 59980, ["name"] = "Catapult Destruction", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "As we snuck in here I noticed the ogres erecting catapults to destroy our camp. Cork must have anticipated this and gave me several explosives to use, \"just in case\". Take these explosives and blow up those catapults ! Also don't shake them too hard.", ["rewardGold"] = 2000, ["rewardXP"] = 1010, ["starts"] = { { ["npcID"] = 167630, ["x"] = 0.402, ["y"] = 0.326, ["mapID"] = 1409 }, { ["npcID"] = 167631, ["x"] = 0.404, ["y"] = 0.324, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167630, ["x"] = 0.402, ["y"] = 0.326, ["mapID"] = 1409 }, { ["npcID"] = 167631, ["x"] = 0.404, ["y"] = 0.324, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.402, ["y"] = 0.326, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59978 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 45, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59981] = { ["id"] = 59981, ["name"] = "Controlling their Stones", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Warlord Thunderwalker won't last much longer. Soon, his life essence will be completely drained. Gor'groth mentioned that they are keeping him captive through the use of ward stones . I want you to recover these ward stones and bring them here so we can release Thunderwalker.", ["rewardGold"] = 2000, ["rewardXP"] = 1010, ["starts"] = { { ["npcID"] = 167633, ["x"] = 0.402, ["y"] = 0.324, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167183, ["x"] = 0.4, ["y"] = 0.322, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.402, ["y"] = 0.324, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59978 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 27, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 46, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59984] = { ["id"] = 59984, ["name"] = "Dungeon: Darkmaul Citadel", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10424, ["mapID"] = 1409, ["description"] = "Gor'groth seeks to use shadow magic to gain control of Kalecgos, the aspect of the Blue Dragonflight. He's collected enough life essence to attempt to finish the ritual. I do not know what will happen, but we cannot let him complete it! Gor'groth will not stop until he is slain! You must storm the citadel and slay Gor'groth before he can complete his ritual! I would charge in beside you, were I not still recovering from his dark magic.", ["rewardGold"] = 8000, ["rewardXP"] = 2020, ["rewardChoices"] = { 175188, 175220, 175190, 175222, 175189, 175221, 175175, 175207 }, ["starts"] = { { ["npcID"] = 167183, ["x"] = 0.4, ["y"] = 0.322, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 167675, ["x"] = 0.396, ["y"] = 0.32, ["mapID"] = 1409 } }, ["coords"] = { ["x"] = 0.4, ["y"] = 0.322, ["source"] = "quest_giver", ["mapID"] = 1409 }, ["mapCandidates"] = { ["npc"] = { 1409 }, ["zone"] = { 10424 } }, ["questType"] = "standard", ["sourceQuests"] = { 59979, 59980, 59981 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 28, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 47, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59985] = { ["id"] = 59985, ["name"] = "An End to Beginnings", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13644, ["mapID"] = 2022, ["description"] = "You've done well here, . Kalecgos and Wrathion are planning to continue on to the Dragon Isles. I must return to Orgrimmar. This shadow magic is concerning... and requires that I look into it more. Talk with Kalecgos . He'll get you to the Dragon Isles and inform you about what's going on there.", ["rewardGold"] = 2000, ["rewardXP"] = 2020, ["rewardChoices"] = { 175179, 175211, 175178, 175210, 175177, 175209, 175176, 175208 }, ["starts"] = { { ["npcID"] = 167675, ["x"] = 0.396, ["y"] = 0.32, ["mapID"] = 1409 } }, ["ends"] = { { ["npcID"] = 168431, ["x"] = 0.524, ["y"] = 0.882, ["mapID"] = 85 }, { ["npcID"] = 244496, ["x"] = 0.812, ["y"] = 0.28, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.396, ["y"] = 0.32, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 85, 1409, 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 59984 }, ["questLines"] = { { ["id"] = 5370, ["name"] = "A Dark Ritual", ["orderIndex"] = 29, ["flags"] = 0 }, { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 48, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 213, ["title"] = "Exile's Reach", ["questLineID"] = 5370, ["questLineOrder"] = 1 } } },
[59986] = { ["id"] = 59986, ["name"] = "Wide Worlds of Catalysts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["mapID"] = 1662, ["storyline"] = { 59986 }, ["description"] = "Catalysts come in different forms, for now we shall introduce you to two of them. Speed catalysts can speed up the restoration process. This can obviously be helpful for managing how many souls we can recover. Quality catalysts improve the quality of the material goods that a spirit might offer upon their restoration. Return to me when you have found an example of each. I will be eager to see whether your small little eyes are sharp enough to spot them.", ["objectivesText"] = "Identify the different types of Catalysts", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[59994] = { ["id"] = 59994, ["name"] = "Trust Fall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "Let us ponder the meaning of the Archivist's last words: \"Victory only belongs to those brave enough to fall.\" Hmm. It could be reference to the Volume of Victory. That is the most well-known of all the writings said to be kept in this tower. That book is priceless, <name>. I mean that almost literally. We must do whatever is necessary to find it! But, uh... What do you suppose \"brave enough to fall\" refers to?", ["objectivesText"] = "Jump from the tower. Progress: You have it?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 175516, 175517, 175518, 175519, 178020, 182732 }, ["rewardChoices"] = { 175517, 175519, 175518, 175516 }, ["starts"] = { { ["npcID"] = 162476 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166806, ["x"] = 0.452, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questGiverID"] = 162476, ["questType"] = "standard", ["sourceQuests"] = { 60900 }, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[59999] = { ["id"] = 59999, ["name"] = "Rebirth of the Grove", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["mapID"] = 1662, ["description"] = "Though not yet withered, the conservatory wilts amidst the drought. This grove is not what it once was. As warden, I bear the twin burdens of guilt and shame. Fate saw to this grove's decay and my failure to prevent it. But fate has also seen to hope in its renewal. Hope in you. I beseech you, mortal, to seek out Zayhad in the Heart of the Forest and restore what has been lost. For as the wounded spirits must be reborn, so too must this grove.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 166476, ["x"] = 0.334, ["y"] = 0.61, ["mapID"] = 1662 } }, ["ends"] = { { ["npcID"] = 166476, ["x"] = 0.334, ["y"] = 0.61, ["mapID"] = 1662 } }, ["coords"] = { ["x"] = 0.334, ["y"] = 0.61, ["source"] = "quest_giver", ["mapID"] = 1662 }, ["mapCandidates"] = { ["npc"] = { 1662 }, ["zone"] = { 13367 } }, ["questType"] = "standard", ["sourceQuests"] = { 59873 }, ["questLines"] = { { ["id"] = 1139, ["name"] = "The Queen's Conservatory", ["orderIndex"] = 3, ["flags"] = 0 } } },
[60003] = { ["id"] = 60003, ["name"] = "A Valiant Effort", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60169, 60827, 60828, 60843, 60861, 60867, 60871, 60932, 62157, 62185, 62225 }, ["description"] = "It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale. While we managed to escort many to safety, there are some who were wounded in the chaos. Search the training grounds for any survivors from the onslaught. We need all the help we can get.", ["objectivesText"] = "Rescue 6 Wounded Valiants from the training grounds. Progress: Any word on survivors?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183797 }, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 59877 }, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[60004] = { ["id"] = 60004, ["name"] = "A Valiant Effort", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60932, 62157, 62185, 62225 }, ["description"] = "It has been quite some time since we faced such a large number of Scourge. We were ill-prepared for an assault of this scale. While we managed to escort many to safety, there are some who were wounded in the chaos. Search the training grounds for any survivors from the onslaught. We need all the help we can get.", ["objectivesText"] = "Rescue 6 Wounded Valiants from the training grounds. Progress: Any word on survivors?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183689 }, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 60727 }, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[60005] = { ["id"] = 60005, ["name"] = "Imminent Danger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["series"] = { 59197, 59198, 59199, 59200, 59426, 60006 }, ["description"] = "The Temple of Courage must not fall! All kyrian learn to fight in its hallowed halls. Not only to protect Bastion , but to ensure their own safety when retrieving souls from across the veil. Travel there at once. Seek out Thanikos , the Paragon of Courage's loyal hand.", ["objectivesText"] = "Seek out Thanikos at Xandria's Vigil.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167873, ["x"] = 0.412, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 59200 }, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60006] = { ["id"] = 60006, ["name"] = "Now or Never", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["series"] = { 59197, 59198, 59199, 59200, 59426, 60005 }, ["description"] = "In a fair fight our warriors could stand against countless swarms of these Maldraxxi. This was no fair fight, outsider. They came without warning. Without cause. We were caught unprepared. They must not be allowed to encroach any further. This stops here.", ["objectivesText"] = "Reclaim Xandria's Vigil. Progress: We will not go down without a fight.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167873, ["x"] = 0.412, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167873, ["x"] = 0.412, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60005 }, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60007] = { ["id"] = 60007, ["name"] = "Stay Scrappy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["description"] = "I can rebuild this colossus's core systems, but a few things are beyond repair. Thankfully there were enough centurions present here that I believe we can improvise. Replacements are in order! I require an Anima Conflux to charge its systems, some Eternity Plating to protect its core, and an Archonic Resonator to make it go boom! I'll take care of the rest. Quickly, now!", ["objectivesText"] = "Recover the Anima Conflux , Eternity Plating , and Archonic Resonator . Progress: Do you have the parts?", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 178041, 178042, 178043, 178140, 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167135, ["x"] = 0.408, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167135, ["x"] = 0.408, ["y"] = 0.554 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60006 }, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60008] = { ["id"] = 60008, ["name"] = "Rip and Tear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["description"] = "We will show these Maldraxxi insurgents the price for their betrayal. The northern grounds have been taken by the House of Constructs, home to Maldraxxus' most resilient warriors. They have earned no mercy this day, and we will give them none. We will carve through them side by side until this sacred ground is cleansed.", ["objectivesText"] = "Slay House of Constructs forces. Progress: This is what must be done.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["rewardItems"] = { 178041, 178042, 178043, 178140 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167134, ["x"] = 0.405, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167134, ["x"] = 0.405, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questTurnInID"] = 167134, ["questType"] = "standard", ["sourceQuests"] = { 60006 }, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60009] = { ["id"] = 60009, ["name"] = "Fight Another Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60005, 60006, 60007, 60008, 60009, 60052, 60053, 60054, 60055 }, ["description"] = "Some of our brethren are still alive in there! While many were lost in the initial assault, they seem keen on taking any survivors prisoner. I know not what they intend, but given their mastery of corpses we must assume the worst. Some have already been taken to their necropolis above, but others remain in cages on the ground. Free all you can.", ["objectivesText"] = "Save 6 captured kyrian. Progress: The kyrian leave none behind on the field of battle.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175718, 178041, 178042, 178043, 178140 }, ["rewardChoices"] = { 175718 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167269, ["x"] = 0.412, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167269, ["x"] = 0.412, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60006 }, ["questLines"] = { { ["id"] = 1066, ["name"] = "The Temple of Courage", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1066, ["questLineOrder"] = 5 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1066, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60013] = { ["id"] = 60013, ["name"] = "Leave it to Mnemis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58771, 58799, 58800, 58843, 58976, 58977, 58978, 58979, 58980, 60013, 60180 }, ["series"] = { 58843, 58980, 59196, 60180 }, ["description"] = "I have deduced by the urgency in your collective voices that you wish to leave. I will expedite your exit. There is a transport pad in the antechamber. I will ensure that the chamber is sealed once again on your exit. Please accompany me.", ["objectivesText"] = "Use the Transport Pad in the Vault of the Archon.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 178046, 178094, 178145, 178146, 183802 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167504, ["x"] = 0.563333, ["y"] = 0.673333 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167038, ["x"] = 0.56, ["y"] = 0.6295 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.563333, ["y"] = 0.673333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60180 }, ["questLines"] = { { ["id"] = 1109, ["name"] = "Chasing a Memory", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1109, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1109, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60020] = { ["id"] = 60020, ["name"] = "An Opportunistic Strike", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "I'm impressed you made it this far. But don't get too full of yourself. Most of the fodder you plowed your way through were amateurs at best. Only one combatant will leave this arena a champion. Each of the five... uh, three houses has fighters in the field. Most merely seek to test their own limits or earn a bit of favor. Only a few have a real chance at claiming victory. Seek out those challengers if you wish to claim true glory this day.", ["objectivesText"] = "Slay 10 elite contenders. Progress: Are they finished?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 172020, 178496 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57390 }, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60021] = { ["id"] = 60021, ["name"] = "Champion the Cause", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["description"] = "Now you're starting to show potential! I'm guessing your name was well known on whatever mortal world you hail from. But don't rest on your laurels. The harder you fight, the harder others will strive to strike you down. That's the Maldraxxi way! Nothing wins the favor of the crowd like taking down a former champion. Two are in attendance today, attempting to recapture their past glories. Slaughter them!", ["objectivesText"] = "Slay Champion Rin'mar and Champion Gutrend . Progress: Is it done?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 147905, 172020, 178496 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164244, ["x"] = 0.503333, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60020 }, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
