[60110] = { ["id"] = 60110, ["name"] = "Never Had a Friend Like Me", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60110 }, ["description"] = "I feel like you could use a little help, Maw Walker. There is knowledge I have which could make you more useful to the Necrolords. So just this once... I will teach you something and you won't even have to lose a limb. Soulbind with me and we'll see if you can learn anything.", ["objectivesText"] = "Complete the soulbinding ritual.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.383, ["y"] = 0.367, ["mapID"] = 1698, ["npcID"] = 161906 } }, ["ends"] = { { ["x"] = 0.383, ["y"] = 0.367, ["mapID"] = 1698, ["npcID"] = 161906 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.383, ["y"] = 0.367 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161906, ["questTurnInID"] = 161906, ["questType"] = "standard", ["sourceQuests"] = { 60049 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[60111] = { ["id"] = 60111, ["name"] = "Forging A Friendship", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60111 }, ["description"] = "When you first arrived I was uncertain of your potential. The Primus demands such perfection in his work... and you are far from perfect. I see now that you bring new knowledge and ideas to our house. Your actions make us stronger. The Primus would be proud of you and wish for us all to learn from you. I am ready now to know your ways. Let me soulbind with you now, so we can grow stronger together.", ["objectivesText"] = "Complete the soulbinding ritual.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.428, ["y"] = 0.322, ["mapID"] = 1698, ["npcID"] = 161905 } }, ["ends"] = { { ["x"] = 0.428, ["y"] = 0.322, ["mapID"] = 1698, ["npcID"] = 161905 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.428, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161905, ["questTurnInID"] = 161905, ["questType"] = "standard", ["sourceQuests"] = { 62406 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[60112] = { ["id"] = 60112, ["name"] = "Cut to the Bone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["series"] = { 61518 }, ["description"] = "I fear if our presence is known, so too is the presence of our comrades. We must develop a contingency. With the foundry on such high alert, we cannot sneak about undetected. Unless, of course, you were to provide a distraction. Perhaps thinning their numbers would suffice.", ["objectivesText"] = "Eliminate 5 Ossein Workers and 10 Violent Animates .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172574, ["x"] = 0.3, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172574, ["x"] = 0.3, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61518 }, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60113] = { ["id"] = 60113, ["name"] = "An Urgent Request", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 59876, 59877, 60113, 60116, 60117, 60766, 60767 }, ["series"] = { 59876, 60116, 60117, 60669, 60670, 60725, 60759, 60761 }, ["description"] = "Champion, A matter of great urgency has arisen--one that requires your immediate attention. Due to the sensitive nature of recent events, I must withhold further details until we meet. We have much to discuss. King Greymane and I await your arrival at Lion's Rest.", ["objectivesText"] = "Report to Genn Greymane at Lion's Rest in Stormwind City.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 167329, ["x"] = 0.395, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1128, ["name"] = "An Uncertain Fate", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2DetailThemeID"] = 24, ["db2PoiUiMapID"] = 84 },
[60114] = { ["id"] = 60114, ["name"] = "Aerial Advantage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "Gharmal's rocs dominate the skies above, striking at our forces as we advance. We cannot move the necropolis into position until they are cleared out! I would slaughter them myself, but the cowards remain out of reach, and I am not constructed for flight. You, however, seem slight enough of build. Take my riding hook and latch onto a roc. Once you are atop of one, beat it to a pulp. Worry about the landing later.", ["objectivesText"] = "Grapple 6 Battlesewn Rocs out of the sky. Progress: Annihilate them!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180899 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167810, ["x"] = 0.282, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167810, ["x"] = 0.282, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60050 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60115] = { ["id"] = 60115, ["name"] = "An Urgent Request", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["description"] = "Champion, A matter of great urgency has arisen--one that requires your immediate attention. Due to the sensitive nature of recent events, I must withhold further details until we can speak in person. There is much to discuss. Regent Lord Lor'themar Theron awaits your arrival in Orgrimmar.", ["objectivesText"] = "Report to Lor'themar Theron atop Grommash Hold in Orgrimmar.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169928, ["x"] = 0.488667, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.488667, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2DetailThemeID"] = 25, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[60116] = { ["id"] = 60116, ["name"] = "Cause for Distraction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 59876, 59877, 60113, 60116, 60117, 60766, 60767 }, ["series"] = { 59876, 60113, 60117, 60669, 60670, 60725, 60759, 60761 }, ["description"] = "The very heart of the Alliance is under attack. The undead Scourge is swarming in numbers not seen since the return of Arthas Menethil. Amidst the chaos, something... terrible has happened. What I am about to share with you has not yet been revealed to our allies. They will be told in due time, but I needed to speak to you directly before word gets out. Allow me to explain.", ["objectivesText"] = "Speak with Genn Greymane at Lion's Rest in Stormwind City. Progress: There is much to discuss.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 167329, ["x"] = 0.395, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 167329, ["x"] = 0.395, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 60113 }, ["questLines"] = { { ["id"] = 1128, ["name"] = "An Uncertain Fate", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[60117] = { ["id"] = 60117, ["name"] = "Return of the Crusade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 59876, 59877, 60113, 60116, 60117, 60766, 60767 }, ["series"] = { 59876, 60113, 60116, 60669, 60670, 60725, 60759, 60761 }, ["description"] = "The Scourge's unbound hunger has been unleashed. It's only a matter of time before those monsters swarm our streets. We need expertise in dealing with this menace. The death knights of the Ebon Blade have stepped forward to aid us, but even they can't do this alone. The Argent Crusade has answered the call. I need you to work with them to keep our people safe, <name>. I have sent word of your arrival to their commander. He awaits you at their camp just inside the city gates.", ["objectivesText"] = "Speak with Commander Gregor in the Trade District of Stormwind City.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["rewardItems"] = { 33447 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 167329, ["x"] = 0.395, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 166383, ["x"] = 0.655, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 60116 }, ["questLines"] = { { ["id"] = 1128, ["name"] = "An Uncertain Fate", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[60120] = { ["id"] = 60120, ["name"] = "Burning Crusade: To Outland!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 84, ["storyline"] = { 28708, 39181, 39188, 39197, 39199, 39202, 49550, 60120, 60959 }, ["description"] = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the draenei. Adventurers of the Alliance are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion. Travel to the Blasted Lands, and pass through the Dark Portal.", ["objectivesText"] = "Go through the Dark Portal in Blasted Lands. The Honor Hold Mage in the Mage District can help you get there.", ["starts"] = { { ["x"] = 0.563, ["y"] = 0.173, ["mapID"] = 84, ["npcID"] = 167032 } }, ["ends"] = { { ["x"] = 0.563, ["y"] = 0.173, ["mapID"] = 84, ["npcID"] = 167032 } }, ["coords"] = { ["mapID"] = 84, ["x"] = 0.563, ["y"] = 0.173 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 167032, ["questTurnInID"] = 167032, ["questType"] = "standard", ["nextQuests"] = { 10288, 60959 }, ["questLines"] = { { ["id"] = 5577, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[60123] = { ["id"] = 60123, ["name"] = "Burning Crusade: To Outland!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 85, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["description"] = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the orcs. Adventurers of the Horde are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion. Travel to the Blasted Lands, and pass through the Dark Portal.", ["objectivesText"] = "Go through the Dark Portal in Blasted Lands. The Thrallmar Mage in the Orgrimmar Portal Room can help you get there.", ["starts"] = { { ["x"] = 0.408, ["y"] = 0.799, ["mapID"] = 85, ["npcID"] = 167032 } }, ["ends"] = { { ["x"] = 0.408, ["y"] = 0.799, ["mapID"] = 85, ["npcID"] = 167032 } }, ["coords"] = { ["mapID"] = 85, ["x"] = 0.408, ["y"] = 0.799 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 167032, ["questTurnInID"] = 167032, ["questType"] = "standard", ["nextQuests"] = { 60961 }, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[60125] = { ["id"] = 60125, ["name"] = "Mists of Pandaria: To Pandaria!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 60125, 60965 }, ["series"] = { 29547, 29548, 31732, 31733, 49556 }, ["description"] = "Please come to Stormwind Keep immediately for a briefing with King Varian Wrynn. We have received word of a conflict in the seas to the south, and we need the help of an experienced <class> to assist in the investigation.", ["objectivesText"] = "Report to Rell Nightwind in Stormwind.", ["starts"] = { { ["x"] = 0.563, ["y"] = 0.173, ["mapID"] = 84, ["npcID"] = 167032 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 55789, ["x"] = 0.791, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.791, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questGiverID"] = 167032, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5583, ["name"] = "Mists of Pandaria Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[60126] = { ["id"] = 60126, ["name"] = "Mists of Pandaria: To Pandaria!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60126, 60964 }, ["series"] = { 29611, 29612, 29690, 31765, 31766, 31767, 31768, 31769, 31853, 49538 }, ["description"] = "You are hereby ordered to present yourself at Grommash Hold immediately. We have received word of a new, resource-rich continent in the south, and we intend to send you and a small contingent of soldiers to claim it for the Horde.", ["objectivesText"] = "Report to Grommash Hold in Orgrimmar.", ["starts"] = { { ["x"] = 0.408, ["y"] = 0.799, ["mapID"] = 85, ["npcID"] = 167032 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 54870, ["x"] = 0.485, ["y"] = 0.707 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.707 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questGiverID"] = 167032, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5582, ["name"] = "Mists of Pandaria Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[60127] = { ["id"] = 60127, ["name"] = "Missing Stone Fiend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "You or I could wield these sinstones directly, but I much prefer to use stone fiends for such tasks. Exceptional results, no personal risk. Unfortunately, my stone fiend did not return from its last errand. Speak with Cryptkeeper Kassir in the archives above. He is loyal to the Accuser and will loan us his stone fiend.", ["objectivesText"] = "Speak with Cryptkeeper Kassir .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57925 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60128] = { ["id"] = 60128, ["name"] = "Ready to Serve", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "Do not mind Temel. His zeal for heralding sins is powerful, but he is still a stone fiend. He will obey. Give Archivist Fane my regards.", ["objectivesText"] = "Return to Archivist Fane .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160248, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57927 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60129] = { ["id"] = 60129, ["name"] = "Stranger in an Even Stranger Land", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "<You arrive alone at the precipice of a strange city, knowing the leaders of Azeroth remain trapped in the Maw. Wherever you are, it is clearly very, very far from home. It appears your arrival has been noticed.>", ["objectivesText"] = "Find your way inside Oribos to learn what is happening. Progress: Try to communicate with the guards and enter the city.", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["starts"] = { { ["x"] = 0.204, ["y"] = 0.503, ["mapID"] = 1670 } }, ["ends"] = { { ["x"] = 0.204, ["y"] = 0.503, ["mapID"] = 1670 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.204, ["y"] = 0.503 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["sourceQuests"] = { 59770 }, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[60132] = { ["id"] = 60132, ["name"] = "Constellan Writs and Stygia", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60132 }, ["description"] = "There is much to discover within the Maw , and much of it can be turned to future profit. Information is an investment. There are many objects that I find interesting in this place, and I am happy to barter with you should you find any. Find one and we shall open negotiations. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(60132)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(60132))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["rewardItems"] = { 175769 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[60136] = { ["id"] = 60136, ["name"] = "Into Torghast", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "The bond to your covenant is growing stronger, <name>. Good. The power lies within you to venture into Torghast and rescue our allies. You saw Baine Bloodhoof while assisting the broker in the Maw . Perhaps this Ve'nari knows a way to breach the Jailer's tower and find the chieftain. When I peered into Torghast once before, you stood at my side. I believe that connection will allow me to see through your eyes as you navigate its torments. Seek out Ve'nari and request her aid, Maw Walker.", ["objectivesText"] = "Find a way into Torghast, Tower of the Damned. Progress: Do whatever you can, Maw Walker. We are depending on you.", ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 63029, 63030, 63032, 63033 }, ["questLines"] = { { ["id"] = 1210, ["name"] = "Torghast", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1242, ["name"] = "Torghast", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1243, ["name"] = "Torghast", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1244, ["name"] = "Torghast", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1245, ["name"] = "Torghast", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 153, ["title"] = "9.0 Covenant Campaigns Ch 2 - Torghast", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1242, ["questLineOrder"] = 1 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1243, ["questLineOrder"] = 1 }, { ["id"] = 146, ["title"] = "Catchi