[60139] = { ["id"] = 60139, ["name"] = "Torment Chamber: Jaina", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1670, ["storyline"] = { 60139, 60146, 62836, 62932, 62935, 62938, 62966, 62969 }, ["description"] = "<Bolvar studies the objects you acquired from the brokers in Torghast.> I sense Lady Proudmoore's magic upon this debris. And these notes describe methods to contain her power. <The Highlord focuses on the items, peering into the darkness.> By the Light! They are tormenting her with white-hot fires. Though her will is strong, there is only so much any mortal can endure. I will modify Ve'nari's Attuned Shard using the items you returned. You must find her, $p. Before it is too late.", ["objectivesText"] = "Rescue Jaina Proudmoore from Torghast. Progress: You must find Jaina Proudmoore in Torghast.", ["rewardGold"] = 1123600, ["rewardXP"] = 16330, ["rewardItems"] = { 184550 }, ["rewardCurrencies"] = { { ["id"] = 1828, ["amount"] = 200 } }, ["starts"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.399, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 62938 }, ["questLines"] = { { ["id"] = 1136, ["name"] = "Torghast", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 154, ["title"] = "Torghast Story Progression Skip", ["questLineID"] = 1136, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[60145] = { ["id"] = 60145, ["name"] = "Third Talon Vartox", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "This \"win the spirit of the people\" operation is noble and good. However, we must set our sights on cutting down our foe's tools. Third Talon Vartox , the leader of this incursion, also serves as the top stoneborn at the Tithelord's estate. If we strike her down here, the Tithelord will be left exposed for our attack.", ["objectivesText"] = "Kill Third Talon Vartox . Progress: Is Vartox dealt with?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167381, ["x"] = 0.562, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167381, ["x"] = 0.562, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57727 }, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60146] = { ["id"] = 60146, ["name"] = "Torment Chamber: Thrall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1670, ["storyline"] = { 60139, 60146, 62836, 62932, 62935, 62938, 62966, 62969 }, ["series"] = { 62969 }, ["description"] = "Using the totem you recovered, I will alter the Attuned Shard to guide you to Thrall 's location. <Bolvar hands you the crystalline object.> Take care. You know the torments Baine and Lady Proudmoore endured in that accursed place. Thrall 's confinement will be no less harrowing. Beware. The deeper you journey into the Tower of the Damned, the closer you get to the Jailer himself. Free Thrall , <name>... before all hope is lost.", ["objectivesText"] = "Rescue Thrall from Torghast, Tower of the Damned. Progress: All our allies must be saved, <name>.", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardItems"] = { 184551 }, ["rewardCurrencies"] = { { ["id"] = 1828, ["amount"] = 200 } }, ["starts"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.399, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 62969 }, ["questLines"] = { { ["id"] = 1136, ["name"] = "Torghast", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 154, ["title"] = "Torghast Story Progression Skip", ["questLineID"] = 1136, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[60147] = { ["id"] = 60147, ["name"] = "Mirror Attunement: The Eternal Terrace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60060, 60147, 60159, 60160, 60164, 60165 }, ["description"] = "Work has been completed on a mirror that will allow travel between Sinfall and The Eternal Terrace. However, it has yet to be attuned. The attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", ["objectivesText"] = "Enter the mirror in The Eternal Terrace.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.472, ["y"] = 0.573, ["mapID"] = 1699, ["npcID"] = 167160 } }, ["ends"] = { { ["x"] = 0.472, ["y"] = 0.573, ["mapID"] = 1699, ["npcID"] = 167160 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.472, ["y"] = 0.573 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 167160, ["questTurnInID"] = 167160, ["questType"] = "standard", ["sourceQuests"] = { 57536 }, ["questLines"] = { { ["id"] = 1040, ["name"] = "The Mirror Network", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60148] = { ["id"] = 60148, ["name"] = "No Place for the Living", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "A living mortal ... incredible! Forgive my astonishment. I am Kah-Delen, an overseer of the Arbiter's attendants here in the Eternal City of Oribos . You stand within the heart of the Shadowlands. While we are accustomed to receiving souls from all manner of worlds within the mortal realm, never before has one arrived that is quite so ... corporeal. Answer honestly, mortal. Did you truly escape the Maw?", ["objectivesText"] = "The Overseers want to know more about how you escaped the Maw. Progress: So where did you come from stranger?", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["starts"] = { { ["x"] = 0.397, ["y"] = 0.661, ["mapID"] = 1670, ["npcID"] = 167425 } }, ["ends"] = { { ["x"] = 0.397, ["y"] = 0.661, ["mapID"] = 1670, ["npcID"] = 167425 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.397, ["y"] = 0.661 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 167425, ["questTurnInID"] = 167425, ["questType"] = "standard", ["sourceQuests"] = { 60129 }, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[60149] = { ["id"] = 60149, ["name"] = "Audience with the Arbiter", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "I am Tal-Inara , Honored Voice of the Arbiter. I speak for she who is ever silent. The Arbiter watches over Oribos . She blesses us with her wisdom. Every mortal soul that enters the Shadowlands passes before her for judgment. In the merest fraction of a moment, she sees every glory, every folly, every joy, every regret. With this knowledge, she chooses an ideal afterlife for that soul. At least, she did. Not long ago, catastrophe struck, and ... Come. Some things are better seen than explained.", ["objectivesText"] = "The Voice of the Arbiter wishes you to join them in the Arbiter's chamber. Progress: The Purpose guides us always.", ["rewardGold"] = 144600, ["rewardXP"] = 3410, ["starts"] = { { ["x"] = 0.405, ["y"] = 0.659, ["mapID"] = 1670, ["npcID"] = 167486 } }, ["ends"] = { { ["x"] = 0.405, ["y"] = 0.659, ["mapID"] = 1670, ["npcID"] = 167486 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.405, ["y"] = 0.659 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 167486, ["questTurnInID"] = 167486, ["questType"] = "standard", ["sourceQuests"] = { 60148 }, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[60150] = { ["id"] = 60150, ["name"] = "Tether to Home", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "It is disappointing that you were unable to stir the Arbiter, but we must not give up hope. Your continued presence in the Shadowlands may help our cause. Perhaps your efforts would benefit from creating a tether to the mortal plane. The map table in this chamber was put in place long ago by the First Ones, the wise architects of all you see. If you have a memento from your homeworld, place it there. The table's magic can establish a connection.", ["objectivesText"] = "Affix the Helm of Domination fragment to the console.", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["starts"] = { { ["x"] = 0.397, ["y"] = 0.661, ["mapID"] = 1670, ["npcID"] = 167425 } }, ["ends"] = { { ["x"] = 0.397, ["y"] = 0.661, ["mapID"] = 1670, ["npcID"] = 167425 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.397, ["y"] = 0.661 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 167425, ["questTurnInID"] = 167425, ["questType"] = "standard", ["sourceQuests"] = { 60149 }, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[60151] = { ["id"] = 60151, ["name"] = "A Doorway Through the Veil", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "The Helm fragment connected us while you were in the Maw. As if through a darkened pane of glass, I saw glimpses of what you endured. The terrors you faced. At least the heroes of Azeroth yet live. They must be saved. By affixing the Helm here, you gave us a tether to Azeroth that served to bring a few of us across the veil. But you, and other heroes who join us, require a stronger connection. Our acolytes can open portals back. No doubt these attendants will be particular about their placement.", ["objectivesText"] = "Establish portals back to Azeroth. Progress: Have you helped the acolytes open the portals yet?", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["starts"] = { { ["x"] = 0.4, ["y"] = 0.653, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.4, ["y"] = 0.653, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.4, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 60150 }, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLine