[60152] = { ["id"] = 60152, ["name"] = "The Eternal City", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "You should become familiar with the Eternal City and how best to navigate it. We, the attendants, serve Oribos as its caretakers. Everything you see here is done in service to the Purpose. In this time of chaos and drought, we must adapt our perspective. It seems we are to serve the Purpose in a new way. You mortals are not the only visitors here. Others have come as well. Like you, the brokers are not of Oribos . They are congenial and willing to aid you. Usually for a price.", ["objectivesText"] = "Tour the Eternal City of Oribos . Progress: Have you concluded your tour yet?", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["starts"] = { { ["x"] = 0.397, ["y"] = 0.661, ["mapID"] = 1670, ["npcID"] = 167424 } }, ["ends"] = { { ["x"] = 0.397, ["y"] = 0.661, ["mapID"] = 1670, ["npcID"] = 167424 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.397, ["y"] = 0.661 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 167424, ["questTurnInID"] = 167424, ["questType"] = "standard", ["sourceQuests"] = { 60151 }, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[60153] = { ["id"] = 60153, ["name"] = "Into the Unknown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 60153 }, ["description"] = "Come to pay old Marasmius a visit? I have a special task for you. One of my shoots has found a strange place, a place even I've never seen before. I'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for! What do you say, <name>? Up for an adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: Keep your guard up. It could lead anywhere!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 179500, 179508, 179513, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181403, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181419, 181420, 181421, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181430, 181457, 181458, 181459, 181477, 181479, 181541, 182469, 182605, 183132, 183167, 183466, 183473, 183479, 183482, 183485, 183487, 184381, 184382, 184383, 184384 }, ["starts"] = { { ["x"] = 0.536, ["y"] = 0.527, ["mapID"] = 1819, ["npcID"] = 167455 } }, ["ends"] = { { ["x"] = 0.536, ["y"] = 0.527, ["mapID"] = 1819, ["npcID"] = 167455 } }, ["coords"] = { ["mapID"] = 1819, ["x"] = 0.536, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questGiverID"] = 167455, ["questTurnInID"] = 167455, ["questType"] = "standard", ["sourceQuests"] = { 57583 } },
[60154] = { ["id"] = 60154, ["name"] = "Understanding the Shadowlands", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1671, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "As I sat upon the Frozen Throne all those years, <name>, I could peer into the Shadowlands. Brief glimpses, clouded and uncertain. Sights both wondrous and terrible. We must work together to make sense of what has happened. To prevent the Maw from consuming all of reality. Whatever Sylvanas and the Jailer want, we must stop them. But we cannot do so alone. Perhaps Tal-Inara can put us on the path to find answers.", ["objectivesText"] = "Speak to Tal-Inara . Progress: Let us align your path to the Purpose.", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["starts"] = { { ["x"] = 0.4, ["y"] = 0.648, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.4, ["y"] = 0.648, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.4, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 60152 }, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, [