[60156] = { ["id"] = 60156, ["name"] = "The Path to Bastion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1671, ["storyline"] = { 60129, 60148, 60149, 60150, 60151, 60152, 60154, 60156 }, ["description"] = "Within the Arbiter's Chamber are gateways to the infinite realms of the Shadowlands. As each soul was judged, a gateway would be opened to the appropriate afterlife. But since the... incident, all gateways have remained closed. Dormant. We dare not use the Arbiter's sacred chamber for so mundane a purpose as travel. But here in the upper ring of the city, gateways can be configured for your needs. Before us stands the means to activate a gateway. Together we can channel the anima to power it.", ["objectivesText"] = "Open the gateway to Bastion. Progress: Your destiny and the Purpose are being drawn together.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["starts"] = { { ["x"] = 0.505, ["y"] = 0.62, ["mapID"] = 1671, ["npcID"] = 175829 } }, ["ends"] = { { ["x"] = 0.505, ["y"] = 0.62, ["mapID"] = 1671, ["npcID"] = 175829 } }, ["coords"] = { ["mapID"] = 1671, ["x"] = 0.505, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 175829, ["questTurnInID"] = 175829, ["questType"] = "standard", ["sourceQuests"] = { 60154 }, ["questLines"] = { { ["id"] = 1135, ["name"] = "Arrival in the Shadowlands", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1135, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1135, ["questLineOrder"] = 2 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1135, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1671 },
[60158] = { ["id"] = 60158, ["name"] = "Rule 7: Betrayal is Inevitable", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60158, 60281, 60284, 60285, 62461, 63022, 63051 }, ["description"] = "Our arrangement has been quite lucrative. Reliable associates like yourself can be so hard to find. I believe I can entrust you with a task I would usually perform on my own. While working with the tracking runes you retrieved for me earlier, I detected a device of broker origin nearby. It must have been brought into the Maw by the captured expedition. Please examine it and prepare it for transport back to the refuge. I will join you shortly. This could be a valuable discovery.", ["objectivesText"] = "Recover the broker device outside of Perdition Hold. Progress: Have you found the device?", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 184361 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 60285 }, ["questLines"] = { { ["id"] = 1200, ["name"] = "New Rules", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60159] = { ["id"] = 60159, ["name"] = "Mirror Attunement: Halls of Atonement", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60060, 60147, 60159, 60160, 60164, 60165 }, ["description"] = "Work has been completed on a mirror that will allow travel between Sinfall and the Halls of Atonement. However, it has yet to be attuned. The attunement process is quite simple. Just head to the mirror's location in the world, and pass through it once, returning to Sinfall. When you have done so, travel between the two mirrors should be seamless.", ["objectivesText"] = "Enter the mirror in the Halls of Atonement.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.476, ["y"] = 0.573, ["mapID"] = 1699, ["npcID"] = 167160 } }, ["ends"] = { { ["x"] = 0.476, ["y"] = 0.573, ["mapID"] = 1699, ["npcID"] = 167160 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.476, ["y"] = 0.573 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 167160, ["questTurnInID"] = 167160, ["questType"] = "standard", ["sourceQuests"] = { 57536 }, ["questLines"] = { { ["id"] = 1040, ["name"] = "The Mirror Network", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
