[60215] = { ["id"] = 60215, ["name"] = "Timely Gate Crashers", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 60215 }, ["description"] = "Did you see that giant mechanical monstrosity just walking around in the dunes outside? How about the icky shadowy Sha of Anger ? Or that big frost giant in the north? Yeah, they aren't native to this area. They tell me the timeways are screwy around this time of year. They have asked me to organize a clean-up crew. Would you be up to the challenge? If you like this challenge, I have another for you as well.", ["objectivesText"] = "Defeat Doomwalker , Sha of Anger , and Archavon the Stone Watcher in Tanaris. Progress: How's it going?", ["rewardGold"] = 1366400, ["rewardXP"] = 8230, ["rewardItems"] = { 44083, 87771, 185907, 208572, 232877, 233014 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 100 }, { ["id"] = 3100, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223882, ["x"] = 0.622, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223882, ["x"] = 0.622, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
[60217] = { ["id"] = 60217, ["name"] = "The Archon's Answer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12, 13 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57263, 57265, 57266, 57267, 57288, 57291, 57709, 57710, 57711, 57713, 57714, 57908, 57909, 58174, 59920, 60217 }, ["description"] = "Your cleansing is complete, and you are whole. Our plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene 's attention once more. Now is our opportunity to request an audience with the Archon. Stand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", ["objectivesText"] = "Speak to Kalisthene .", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 172516, 177954 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158862, ["x"] = 0.5335, ["y"] = 0.843 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 156217, ["x"] = 0.535, ["y"] = 0.87 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5335, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57266 }, ["questLines"] = { { ["id"] = 1055, ["name"] = "The Aspirant's Crucible", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1055, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1055, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
