[60230] = { ["id"] = 60230, ["name"] = "More the Merrier", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60230 }, ["description"] = "News of our work here has spread, new souls have arrived seeking to join us! Take their requests for new construct bodies. We'll see if we can build them new constructs too!", ["objectivesText"] = "Take the construct requests from the souls present.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60041 } },
[60231] = { ["id"] = 60231, ["name"] = "State of Decay", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60231 }, ["objectivesText"] = "Kill Slimed enemies or Players", ["rewardXP"] = 8165, ["rewardItems"] = { 177245 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Kill Slimed enemies or Players", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[60236] = { ["id"] = 60236, ["name"] = "RSVP: Cryptkeeper Kassir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60236 }, ["description"] = "I would be most honored to attend Prince Renathal's Ember Court. I prefer to wear my official signet ring for such prestigious occasions. It was given to me by the Accuser herself when I was first charged with my duties. However, the Lord Chamberlain's goons have stolen it once more. They hide their ill-gotten gains inside of these crypts... But I have no idea which one houses my ring. It may take some time to find Atonement Crypt Keys, but any venthyr here in the halls could have one.", ["objectivesText"] = "Collect Atonement Crypt Keys from venthyr around the Halls of Atonement and open Atonement Crypts until you find the Lost Cryptkeeper's Ring . Progress: Desired objects tend to be in the last place we look, do they not? Perhaps we shall be fortunate this time.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172957, 176120, 177231, 178526, 180380, 180397, 184225 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57928, 61704 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60237] = { ["id"] = 60237, ["name"] = "Old Stomping Grounds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60237 }, ["description"] = "Once, long ago, I journeyed to Ardenweald to assist in putting down a threat now long forgotten. I remember that while there, I saw small creatures taking tiny clusters of anima--animacones, the fae called them--and buried them under the soil. If those clusters are still there, we must gather them for ourselves! I should be able to unearth any of the animacones we encounter. Let's go hunt for them!", ["objectivesText"] = "Collect 15 Lost Animacones . Use Toothpick 's World Shaker to unearth them.", ["rewardXP"] = 8165, ["rewardItems"] = { 182488, 182497, 182506, 182515, 183043, 183744, 183755, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159212, ["x"] = 0.548, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58414 } },
