[60239] = { ["id"] = 60239, ["name"] = "A Winter Veil Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60239 }, ["rewardItems"] = { 34426, 43504, 46740, 67443, 70938, 90892, 104319, 116761, 128653, 139341, 151350, 162644, 172224, 178528, 178533, 187561, 192094, 209871, 218311, 244908 }, ["starts"] = { { ["objectID"] = 187236 }, { ["npcID"] = 187236, ["x"] = 0.335, ["y"] = 0.66, ["mapID"] = 87 }, { ["npcID"] = 187236, ["x"] = 0.494, ["y"] = 0.775, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 187236, ["x"] = 0.335, ["y"] = 0.66, ["mapID"] = 87 }, { ["npcID"] = 187236, ["x"] = 0.494, ["y"] = 0.775, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.335, ["y"] = 0.66, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85, 87 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[60242] = { ["id"] = 60242, ["name"] = "Trading Favors: Necrotic Wake", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60242 }, ["description"] = "We of the brokers place value on things that may seem strange to an outsider like yourself. Objects that are unusual or one-of-a-kind are things we may find more valuable than others. So let us make a deal, hm? Should you find yourself in possession of one such object, I will offer a trade for something you may find more valuable. I hear that the forces of Maldraxxus have made an attack on Bastion. Such things rarely happen without objects of power in tow, no?", ["objectivesText"] = "Obtain Nalthor's Phylactery Instructions from Nalthor the Rimebinder in the Necrotic Wake. Progress: Have you found any objects of interest?", ["rewardItems"] = { 178577, 184374 }, ["rewardChoices"] = { 184374 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.524, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12916 } }, ["questGiverID"] = 167880, ["questTurnInID"] = 167880, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60243] = { ["id"] = 60243, ["name"] = "Trading Favors: Sanguine Depths", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60243 }, ["description"] = "The generals of Revendreth are outfitted with only the finest arms and armor, procured by Sire Denathrius in his unquenchable appetite for power. In terms of profitable trades and exchanges, he has been a shrewd partner in trade to us. It would please me greatly to see the return of some relics that were traded in a way that benefited him far more than us. There are few things more insulting to my kind.", ["objectivesText"] = "Obtain a Medallion of Orientation from General Kaal in the Sanguine Depths. Progress: What have you brought before me?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178584, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.524, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12842 } }, ["questGiverID"] = 167880, ["questTurnInID"] = 167880, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60244] = { ["id"] = 60244, ["name"] = "Trading Favors: Halls of Atonement", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60244 }, ["description"] = "The mechanisms by which each land of the Shadowlands operates are quite intriguing. Yet, I have always held a particular fascination with the venthyr of Revendreth. How they siphon souls of their sins, storing them in strange stones, and dredge up minions from the muck that surrounds them -- it is all quite novel. They keep their secrets close at hand, however, and will not willingly part with information. I offer trades for any of their tomes you might come into possession of.", ["objectivesText"] = "Obtain the Tome of Dredger Alchemy from Lord Chamberlain in the Halls of Atonement. Progress: Have you found something of interest?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178583, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.524, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12831 } }, ["questGiverID"] = 167880, ["questTurnInID"] = 167880, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60245] = { ["id"] = 60245, ["name"] = "Trading Favors: De Other Side", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60245 }, ["description"] = "Mueh'zala is an ancient and primitive creature that commands a place known as De Other Side. Little is known about this land, as we are not permitted to visit. We have sent many offers of trade, yet there has never been a reply. A pity, as the few that have escaped Mueh'zala's clutches claim his domain to be a place of many oddities. We would never ask you to venture into such danger. There is, however, a standing offer of trade for things procured from Mueh'zala's grasp.", ["objectivesText"] = "Obtain a Golden Death Mask from Mueh'zala in De Other Side. Progress: You have the stench of death about you.", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178582, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.524, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 167880, ["questTurnInID"] = 167880, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60246] = { ["id"] = 60246, ["name"] = "Trading Favors: Tirna Scithe", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60246 }, ["description"] = "The gorm devour anything in their path when left unchecked. We have sold more than a few of them as both pets and weapons. You do not want to see what a world looks like when they are introduced to it and allowed to infest. Or perhaps, mhm, you do? For some, that is entertainment. It is difficult for us to explore Ardenweald with things as they are at this time. A fat, healthy gorm larva would fetch a fine price on the markets. I trust my meaning is understood?", ["objectivesText"] = "Obtain an Engorged Gorm Larva from Tred'ova in the Mists of Tirna Scithe. Progress: Have you completed the task?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178581, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.524, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13334 } }, ["questGiverID"] = 167880, ["questTurnInID"] = 167880, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60247] = { ["id"] = 60247, ["name"] = "Trading Favors: Theater of Pain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60247 }, ["description"] = "Grandmaster Vole runs the arena in Maldraxxus, where the champions of each of the houses compete for glory. Naturally, prizes are often awarded to the victors. Those of our kind do not often participate in such battles. To find such a prize for sale by one of us would be quite unusual indeed. I trust I need say no more? Let us keep this transaction between us, and I will be happy to part with some valuable goods.", ["objectivesText"] = "Obtain a Champion's Coin from Mordretha in the Theater of Pain. Progress: Six, seven, eight... oh, yes? Do you have an offer of trade? I have much more inventory to catalogue.", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178580, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.524, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12841 } }, ["questGiverID"] = 167880, ["questTurnInID"] = 167880, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60248] = { ["id"] = 60248, ["name"] = "Trading Favors: Plaguefall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60248 }, ["description"] = "Is is such a shame what happened to poor Margrave Stradama. Just between us, she was once one of our most favored trading partners. When things get lost in Maldraxxus they tend to end up at the bottom of her blighted pools. You would not, perhaps, be interested in continuing this relationship on her behalf? We would, of course, compensate you quite well. I am sure she has little use for these possessions in her current state.", ["objectivesText"] = "Obtain one of Stradama's Lost Ledgers from Margrave Stradama in Plaguefall. Progress: Oh, it is you again.", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178579, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.524, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13228 } }, ["questGiverID"] = 167880, ["questTurnInID"] = 167880, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60249] = { ["id"] = 60249, ["name"] = "Trading Favors: Spires of Ascension", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60249 }, ["description"] = "The Kyrians of Bastion serve a unique role in the Shadowlands, ferrying mortal souls from their realms to ours. They are able to do so in great numbers, it would seem, in times of crisis or devastation. We would like to know more about their travels to the realms beyond. Surely one of them has brought something back from another land? They are, after all, so very interested in memories.", ["objectivesText"] = "Obtain a Strange Doll from Devos, Paragon of Doubt in the Spires of Ascension. Progress: How may I assist you?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178578, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.553, ["mapID"] = 1670, ["npcID"] = 167880 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.524, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12837 } }, ["questGiverID"] = 167880, ["questTurnInID"] = 167880, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60250] = { ["id"] = 60250, ["name"] = "A Valuable Find: Theater of Pain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60250 }, ["description"] = "The Theater of Pain in Maldraxxus is a brutal place, where only the strongest survive. With the houses so fiercely in competition with one another, it is considered a great point of pride to house a champion with a winning record. As such, the house lords often outfit their contenders with powerful arms, armor, and trinkets. Often these are storied items that have been passed down through many battles. I would very much like to see such an item.", ["objectivesText"] = "Obtain the Ring of Otherworldly Metal from Mordretha in the Theater of Pain. Progress: Were you victorious, or have you come to tend to your wounds?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178572, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.514, ["y"] = 0.437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12841 } }, ["questGiverID"] = 167881, ["questTurnInID"] = 167881, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60251] = { ["id"] = 60251, ["name"] = "A Valuable Find: Plaguefall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60251 }, ["description"] = "Life in Maldraxxus is one of constant warfare, the great houses in perpetual competition with one another. Every once in a great while, a house lord obtains an item or piece of knowledge of such rarity that it tips the scales in their favor. It is possible, even probable, that this was the cause of the fate that befell the House of Plagues. I do not need to tell you how valuable such a rarity would be to us, do I?", ["objectivesText"] = "Obtain A Slimy Correspondence from Margrave Stradama in Plaguefall. Progress: Yes? I am quite busy here.", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178571, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.514, ["y"] = 0.437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13228 } }, ["questGiverID"] = 167881, ["questTurnInID"] = 167881, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60252] = { ["id"] = 60252, ["name"] = "A Valuable Find: Spires of Ascension", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60252 }, ["description"] = "You have, no doubt, visited Bastion and seen what happens to souls that are accepted there. Their memories are extracted, viewed, and even stored in their great Temple of Wisdom. This temple houses memories that may answer some of the greatest questions we have about our realm and the worlds beyond. It is a shame they are locked away. We have heard that the fallen Paragon of Loyalty has interest in these memories. Any memory that would catch her attention would surely be worth trading for.", ["objectivesText"] = "Obtain the Fading Memory Glass from Devos, Paragon of Doubt in the Spires of Ascension. Progress: You have the look of one who has something to say.", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178570, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.514, ["y"] = 0.437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12837 } }, ["questGiverID"] = 167881, ["questTurnInID"] = 167881, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60253] = { ["id"] = 60253, ["name"] = "A Valuable Find: Necrotic Wake", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60253 }, ["description"] = "Once in a rare while, we find ourselves in possession of an object of exceptionally cryptic origin. These objects allow us a brief glimpse into the realms beyond our comprehension. It may seem to you that I speak in riddles, yet so much of this realm is shrouded in mystery, even to us. There are others that have sought to unravel the history of this realm. Should you happen upon one of their works, I will offer you a trade of exceptional value.", ["objectivesText"] = "Obtain \" The Origin of Death \" from Nalthor the Rimebinder in the Necrotic Wake. Progress: What have you found?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178569, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.514, ["y"] = 0.437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12916 } }, ["questGiverID"] = 167881, ["questTurnInID"] = 167881, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60254] = { ["id"] = 60254, ["name"] = "A Valuable Find: Tirna Scithe", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60254 }, ["description"] = "The gorm are indiscriminate in what they consume, so long as it does not contain anima. A gorm queen that has lived for many generations may have any number of indestructible artifacts lodged within her belly. For this reason, sifting through a queen's carcass is not unlike treasure hunting for us. One of the largest queens is currently consuming Tirna Scithe. She surely is bloated with valuables. Should you come upon anything particularly unusual, know that we will compensate you in kind.", ["objectivesText"] = "Obtain the Unusual Automaton Parts from Tred'ova in the Mists of Tirna Scithe. Progress: You look as if you have been sifting through gorm carcass, or perhaps that is simply what you always look like?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178573, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.514, ["y"] = 0.437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13334 } }, ["questGiverID"] = 167881, ["questTurnInID"] = 167881, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60255] = { ["id"] = 60255, ["name"] = "A Valuable Find: De Other Side", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60255 }, ["description"] = "Mueh'zala has been around for many generations, how many exactly we cannot say. His domain is a land of mystery to us all. But we are a people of probabilities and margins. A creature of that age, with such power, and the many ancient souls within his domain, has a great chance to be in possession of a relic of unfathomable rarity. <The light around Ta'lan's head flares brightly for a moment. He seems... excited?> Slay the foolish creature, bring me his secrets, I will reward you handsomely!", ["objectivesText"] = "Obtain a Strange Ritual Mask from Mueh'zala in De Other Side. Progress: Have you brought something of interest?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178574, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.514, ["y"] = 0.437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 167881, ["questTurnInID"] = 167881, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60256] = { ["id"] = 60256, ["name"] = "A Valuable Find: Halls of Atonement", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60256 }, ["description"] = "The aristocracy of Revendreth trade in decadent and priceless shows of status with one another, but rarely with our kind. Often they will travel with a piece or two affixed to their garb as a show of status. Now, many of their kind have sided with Sire Denathrius and against the denizens of the Shadowlands. They must, of course, be stopped. Of course. Yet should you, in the process of doing so, relieve them of some of these possessions, know that I will trade generously.", ["objectivesText"] = "Obtain the Golden Orb of Energy from Lord Chamberlain in the Halls of Atonement. Progress: How does the battle fare?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178575, 178590, 178591, 178592, 178593, 184374 }, ["rewardChoices"] = { 178593, 178592, 178590, 178591, 1804, 1805, 1806, 1807 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.514, ["y"] = 0.437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12831 } }, ["questGiverID"] = 167881, ["questTurnInID"] = 167881, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60257] = { ["id"] = 60257, ["name"] = "A Valuable Find: Sanguine Depths", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60257 }, ["description"] = "General Kaal has slain many foes, and in a bag at her side, she holds the skulls of those she considers her most precious kills. Not all of them, of course, have skulls -- it is a bag of eclectic contents. Contained within, we have heard, is the head of one of our kind. We do not know to whom it might belong, for we do not often find ourselves running afoul of the venthyr. Such a strange mystery must be solved. I will, of course, provide great compensation.", ["objectivesText"] = "Obtain an Ancient Broker Headpiece from General Kaal in the Sanguine Depths. Progress: What information do you bring?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178576, 184374 }, ["rewardChoices"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.437, ["mapID"] = 1670, ["npcID"] = 167881 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.514, ["y"] = 0.437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12842 } }, ["questGiverID"] = 167881, ["questTurnInID"] = 167881, ["questType"] = "dungeon", ["sourceQuests"] = { 60274 } },
[60264] = { ["id"] = 60264, ["name"] = "Soul Survivor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60264 }, ["description"] = "I knew when you helped me in the Etheric Vault, that you were a just and worthy leader. I have come here to offer you my help and services in your efforts to bring Maldraxxus back into balance. Please, build a construct for me, and allow me to help you as you have helped me.", ["objectivesText"] = "Take specifications for Miru's construct. Progress: Are you willing to do this?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 119151 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167877, ["x"] = 0.55, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59747 } },
[60265] = { ["id"] = 60265, ["name"] = "Disrupting the Chain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57646, 57727, 57729, 57771, 57772, 60145, 60183, 60265 }, ["description"] = "From the desk of the Tithelord: All supply carriages must re-route to Stonevigil for collection assistance. Once complete, you may resume your regularly scheduled routes.", ["objectivesText"] = "Destroy the Darkhaven and Manor carriages in Stonevigil Overlook.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178557 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.574, ["y"] = 0.692, ["mapID"] = 1525 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167380, ["x"] = 0.562, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57727 }, ["questLines"] = { { ["id"] = 1041, ["name"] = "Envy", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1041, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
