[60268] = { ["id"] = 60268, ["name"] = "Deep Within", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1912, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["description"] = "Who... who are you? Have you come to extract more of my memories? I'm afraid there aren't any useful ones left, save for the memories of my imprisonment. Or perhaps you're here for something else?", ["objectivesText"] = "Speak with the prisoner and learn of his situation. Progress: What do you want of me?", ["starts"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["coords"] = { ["mapID"] = 1912, ["x"] = 0.506, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 164937, ["questTurnInID"] = 164937, ["questType"] = "standard", ["sourceQuests"] = { 60267, 62967 }, ["questLines"] = { { ["id"] = 1210, ["name"] = "Torghast", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1242, ["name"] = "Torghast", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1243, ["name"] = "Torghast", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1244, ["name"] = "Torghast", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1245, ["name"] = "Torghast", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questL