[60270] = { ["id"] = 60270, ["name"] = "A Damned Pact", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["series"] = { 60271, 60272 }, ["description"] = "Yes... I begin to remember. Power. Power with a purpose. That is what I can offer. Runes. Runes are the key. I've recalled some of them, but to infuse them into your equipment, I require my hands. Well, one hand would suffice. Both would be better. Find a way to free me from my bonds, mortal. Then I can offer the power you seek. After that, freedom... and perhaps the downfall of the one who bound me.", ["objectivesText"] = "Discover a way to break the Runecarver free from his chains.", ["starts"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questGiverID"] = 164937, ["questType"] = "standard", ["sourceQuests"] = { 60269 }, ["questLines"] = { { ["id"] = 1210, ["name"] = "Torghast", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1242, ["name"] = "Torghast", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1243, ["name"] = "Torghast", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1244, ["name"] = "Torghast", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1245, ["name"] = "Torghast", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["