[60271] = { ["id"] = 60271, ["name"] = "A Grave Chance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["series"] = { 60270, 60272 }, ["description"] = "First you'll need a vessel to house anima and a way to expel it. I happen to possess such a device, which I'll be pleased to give to you. For a price, of course. You recall Zovaal's Cauldron, I trust? The denizens there were forged in unholy fire. Assuming their anima is of a similar nature, it should be able to melt even the metals of the tower. With my device and their anima, I believe you can achieve your goal, Maw Walker.", ["objectivesText"] = "Purchase an Anima Supricifer from Ve'nari and recover 5 Molten Anima . Progress: Were you able to acquire the anima?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178562, 181324 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 60270 }, ["questLines"] = { { ["id"] = 1210, ["name"] = "Torghast", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1242, ["name"] = "Torghast", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1243, ["name"] = "Torghast", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1244, ["name"] = "Torghast", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1245, ["name"] = "Torghast", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"]