[60274] = { ["id"] = 60274, ["name"] = "Trading Favors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60274 }, ["description"] = "Welcome, friend. I can see by your garb that you must have quite a storied history. Many unique relics befitting of one that has traveled the worlds and vanquished many foes. There are those of us that find great value in such things, and would willingly part with our own valuables for a taste of what you may find. Let your curiosity guide you to the dark hallway across from the cookpots in the next room. Down there, you will find answers.", ["objectivesText"] = "Report to Finder Ta'sul in Oribos .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 1804, 1805, 1806, 1807, 184374 }, ["starts"] = { { ["x"] = 0.672, ["y"] = 0.506, ["mapID"] = 1670, ["npcID"] = 156688 } }, ["ends"] = { { ["x"] = 0.672, ["y"] = 0.506, ["mapID"] = 1670, ["npcID"] = 156688 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.672, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 156688, ["questTurnInID"] = 156688, ["questType"] = "standard" },
[60275] = { ["id"] = 60275, ["name"] = "WANTED: Enforcer Kristof", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60275 }, ["description"] = "WARNING! Shrouded patrols have increased throughout the Ember Ward. By order of Enforcer Kristof , all who are found near the asylum will be forced to endure the Light. Use extreme caution when venturing beyond our sanctuary. Even the shadows are not safe so long as Kristof remains in power. A reward awaits whoever is able to rid the ward of this tyrant. - Dispatcher Raluca", ["objectivesText"] = "Find and slay Enforcer Kristof .", ["rewardXP"] = 12250, ["rewardItems"] = { 181714 }, ["starts"] = { { ["x"] = 0.306, ["y"] = 0.489, ["mapID"] = 1525, ["objectID"] = 351874 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168120, ["x"] = 0.306, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57025 }, ["questLines"] = { { ["id"] = 1182, ["name"] = "WANTED: Enforcer Kristof", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60276] = { ["id"] = 60276, ["name"] = "WANTED: Summoner Marcelis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60276 }, ["description"] = "Be advised: Summoner Marcelis and his cohorts are dabbling in dangerous magics. They are calling forth ashen elementals to ravage these Light-scorched lands. We cannot let such acts continue. Any who can are urged to put an end to this madness. - Dispatcher Raluca", ["objectivesText"] = "Find and slay Summoner Marcelis . Progress: You'll get your reward when you slay Marcelis, and not a moment sooner.", ["rewardXP"] = 2125, ["rewardItems"] = { 180459 }, ["starts"] = { { ["x"] = 0.308, ["y"] = 0.49, ["mapID"] = 1525, ["objectID"] = 351888 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168120, ["x"] = 0.306, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57025 }, ["questLines"] = { { ["id"] = 1181, ["name"] = "WANTED: Summoner Marcelis", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60277] = { ["id"] = 60277, ["name"] = "WANTED: Aggregate of Doom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60277 }, ["description"] = "Attention all workers: We got ourselves a problem down in the thicket. A golem is trekking through the worksite, causing all sorts of trouble. Grab a rock and get to throwin'. The dredger that takes it out gets the rest of the day off. - Foreman Scug", ["objectivesText"] = "Find and slay the Aggregate of Doom .", ["rewardXP"] = 2125, ["rewardItems"] = { 180288 }, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.692, ["mapID"] = 1525, ["objectID"] = 351885 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168122, ["x"] = 0.588, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "group", ["sourceQuests"] = { 57025 }, ["questLines"] = { { ["id"] = 1191, ["name"] = "WANTED: Aggregate of Doom", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60278] = { ["id"] = 60278, ["name"] = "WANTED: Duke Anton", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60278 }, ["description"] = "Loyal Citizens of Revendreth : Duke Anton and his decrepit house are relics of noble venthyr society. His attempts to tarnish my name are laughable at best. It is time someone rid us of Duke Anton 's presence for good. I shall offer double whatever pathetic sum he can muster. Sincerely, Lord Darion of House Redelav", ["objectivesText"] = "Find and slay Duke Anton of House Briarbane.", ["rewardItems"] = { 179380, 180289 }, ["starts"] = { { ["x"] = 0.607, ["y"] = 0.401, ["mapID"] = 1525, ["objectID"] = 351886 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168121, ["x"] = 0.608, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57025 }, ["questLines"] = { { ["id"] = 1184, ["name"] = "WANTED: Duke Anton", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60279] = { ["id"] = 60279, ["name"] = "WANTED: The Pale Doom", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60279 }, ["description"] = "Notice to all: A lingering menace lurks in the Endmire, dangerously close to Darkhaven's border. If alone in your travels, take care to avoid this monstrosity, lest it make you meet your true death. Those with a sense of adventure and a well-armed brigade might manage to slay this beast. If so, a reward will await you upon your return. Sincerely, Taskmaster Gavril", ["objectivesText"] = "Find and slay The Pale Doom within the Endmire. Progress: There's no shame in turning down the bounty. Not everyone has what it takes to slay a devourer.", ["rewardXP"] = 10205, ["rewardItems"] = { 180458 }, ["starts"] = { { ["x"] = 0.622, ["y"] = 0.635, ["mapID"] = 1525, ["objectID"] = 351889 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168057, ["x"] = 0.62, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "group", ["sourceQuests"] = { 57025 }, ["questLines"] = { { ["id"] = 1180, ["name"] = "WANTED: The Pale Doom", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60280] = { ["id"] = 60280, ["name"] = "WANTED: Lord Darion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60280 }, ["description"] = "To Whom it May Concern: Lord Darion of House Redelav thinks that he can buy his place in society. He flaunts his wealth, using it to win favor of other lords and ladies. Is there no price on decency? This is not the way the noble houses of Revendreth should conduct themselves. I implore you to find Lord Darion and help him meet his true death. The honor of House Briarbane rests in your capable hands. Warmest Regards, Duke Anton of House Briarbane", ["objectivesText"] = "Find and slay Lord Darion of House Redelav.", ["rewardXP"] = 12250, ["rewardItems"] = { 180289 }, ["starts"] = { { ["x"] = 0.608, ["y"] = 0.4, ["mapID"] = 1525, ["objectID"] = 351887 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168121, ["x"] = 0.608, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57025 }, ["questLines"] = { { ["id"] = 1183, ["name"] = "WANTED: Lord Darion", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60281] = { ["id"] = 60281, ["name"] = "Rule 4: Make A List", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60158, 60281, 60284, 60285, 62461, 63022, 63051 }, ["description"] = "I've discovered that one of the Jailer's inquisitors is attempting to devise a method to track my movements. Clearly, that is a problem for me... and by extension, it is a problem for you. The inquisitor has risen to the top of my list of potential threats. In the past, I would have had to deal with him myself. But now... I have a business partner. Put an end to him, yes? And if you can, determine exactly how he intended to track me.", ["objectivesText"] = "Kill Inquisitor Devaki and find out how he is trying to track Ve'nari . Progress: Have you learned anything of Inquisitor Devaki 's tracking methods?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 184492 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 63051 }, ["questLines"] = { { ["id"] = 1200, ["name"] = "New Rules", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60283] = { ["id"] = 60283, ["name"] = "Specter Of War: Visectus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60283 }, ["objectivesText"] = "Progress: We have conjured Visectus to lead our attack, but we need your help to prepare it properly. We require more Anima-bound Wraps to strengthen the summons.", ["rewardItems"] = { 173202, 178594, 183619 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161668, ["x"] = 0.535, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161668, ["x"] = 0.535, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60284] = { ["id"] = 60284, ["name"] = "Rule 5: Be Audacious", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60158, 60281, 60284, 60285, 62461, 63022, 63051 }, ["description"] = "You have proven yourself a useful associate, <class>. In thanks, I have crafted a cypher that will allow you to venture further into the Maw . But... it is experimental in nature. You will have to test it in the field. And I have just the test in mind. Cartel Ve has foolishly sent more agents into the Maw . They were captured and taken to Perdition Hold. I must know why. Breach the fortress and learn what has become of the captive brokers. Nothing is more valuable than knowledge of your enemy's plans.", ["objectivesText"] = "Investigate the increased activity within Perdition Hold. Progress: What have you discovered, Maw Walker?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 182688 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 60281 }, ["questLines"] = { { ["id"] = 1200, ["name"] = "New Rules", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60285] = { ["id"] = 60285, ["name"] = "Rule 6: Concealment is Everything", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60158, 60281, 60284, 60285, 62461, 63022, 63051 }, ["description"] = "I have made a startling discovery, <name>. Do you recall how the captured agents of my cartel were taken to the Beastwarrens? The Mawsworn seem to think they possess a means of tracking me. And now, strange new runes empower the Jailer's hounds. Clearly, we cannot have that. This new cypher will grant you solace from the screeching in the Beastwarrens. Brave its caverns and secure those runes for inspection. If we are to counter their effects, I must know how they work.", ["objectivesText"] = "Retrieve 15 Broker Hunting Runes from The Beastwarrens. Progress: The runes... you have them?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 182955, 182956 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 60284 }, ["questLines"] = { { ["id"] = 1200, ["name"] = "New Rules", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60287] = { ["id"] = 60287, ["name"] = "Rule 1: Have an Escape Plan", ["level"] = 55, ["requiredLevel"] = 55, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 58160, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Many doomed souls suffer within the Maw . You must be careful if you do not wish to join them. Your Soulkeeper can hold a small number of souls until you return to your covenant. But that will be of little benefit if you do not survive this place yourself. There is a substance, stygia, that is found on some creatures within the Maw . The stronger the soul, the more stygia they have. Collect some of it for me and I can fashion it into many things you will find quite useful.", ["objectivesText"] = "Rescue 5 souls and retrieve 60 Stygia. Stronger enemies will have a higher chance to drop large amounts of Stygia. Use the Stygia to purchase a Cypher of Relocation from Ve'nari . Progress: I will gladly assist you in the acquisition of survival tools... provided you bring me the stygia.", ["rewardGold"] = 257400, ["rewardXP"] = 7490, ["rewardItems"] = { 185973 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 62882 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the K