[60291] = { ["id"] = 60291, ["name"] = "Corpse Run", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60291 }, ["description"] = "There's work that needs doing 'round here. Mmmm hmmm. Spotted a big ol' carcass nearby. I aim to salvage it for parts. Figure you could come along, help me drag it to Rathan . He'd like that. Mmmm hmmm. Reckon I could even carry you there and back. You don't look too big. Ready to get going?", ["objectivesText"] = "Return the Bone Carcass to Rathan at Butcher Block. Progress: Did you bring back the carcass?", ["rewardXP"] = 8165, ["rewardItems"] = { 178599, 182483, 182492, 182501, 182510, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1543, ["npcID"] = 158300, ["x"] = 0.332, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536, 1543 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57597 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60292] = { ["id"] = 60292, ["name"] = "Dangerous Discourse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57037, 57264, 57269, 57270, 57446, 57447, 57716, 57717, 57719, 57977, 59147, 60292 }, ["description"] = "I found this scroll while you were cleansing the temple. These are dire words, and I suspect it only gets worse. Collect more of these scrolls so I can determine just what these so-called Forsworn want.", ["objectivesText"] = "Collect 6 Dark Sermons . Progress: We must defend the temple, <name>.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 171215 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 159762, ["x"] = 0.576, ["y"] = 0.7528 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.7528 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57717 }, ["questLines"] = { { ["id"] = 1056, ["name"] = "The Temple of Purity", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1056, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1056, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60296] = { ["id"] = 60296, ["name"] = "Pride or Unit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57931, 57932, 57933, 57934, 57935, 57936, 57937, 58037, 58038, 58039, 58040, 58041, 58042, 58103, 58184, 58185, 60296 }, ["description"] = "You have made great strides with our pride. I hope you found value and fulfillment in working with the larion. The time to meet with Pelodis has come. You must decide whose way of life is more rewarding, and which you would prefer to pursue.", ["objectivesText"] = "Meet with Pelodis and Nemea , then pick a side. Progress: The pack has welcomed you, <name>. I hope that you feel it.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 168408, 173269, 173307, 173690, 173691, 173692, 173702, 181368, 181377, 181569, 181573, 181574, 181583, 181585, 181602, 181610, 181611, 181628, 181629, 181630, 181631, 181632, 181634, 181745, 182107, 182307, 182469, 182653, 182743, 183126, 183467, 183479, 183483, 184294, 184362, 184363, 184765, 184766, 184767, 184768 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.442667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57937, 58042 }, ["questLines"] = { { ["id"] = 1150, ["name"] = "Pride or Unit", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60313] = { ["id"] = 60313, ["name"] = "Dredhollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "That was a narrow escape. But I believe this presents an opportunity to finally turn the tide of this strife and defeat the Fearstalker. Meet me at Dredhollow: the abandoned hunting lodge of the Fearstalker. We must take separate paths. The Fearstalker will soon be after us again.", ["objectivesText"] = "Meet the Accuser at Dredhollow.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156554, ["x"] = 0.515, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168217, ["x"] = 0.432, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57159 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60315] = { ["id"] = 60315, ["name"] = "WANTED: Gorgebeak", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60315 }, ["description"] = "Thief! Pilferer! Menace! The insidious menace known as Gorgebeak threatens our harvest of ambrosi for tribute to our great Archon. She must be stopped! If any are willing to take on this foul fowl, I have tracked her nest to the western edges of Firstborne's Bounty. Proof of her demise shall be amply rewarded. -- Gerdus", ["objectivesText"] = "Collect Gorgebeak's Bill for Gerdus in Firstborne's Bounty. Progress: What business have you with this simple tender?", ["rewardGold"] = 709020, ["rewardXP"] = 1770, ["rewardItems"] = { 173345, 173346, 173347, 173348, 178683 }, ["rewardChoices"] = { 173345, 173346, 173347, 173348 }, ["starts"] = { { ["x"] = 0.532, ["y"] = 0.464, ["mapID"] = 1533, ["objectID"] = 352027 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 161499, ["x"] = 0.51, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "group", ["sourceQuests"] = { 60735 }, ["questLines"] = { { ["id"] = 1153, ["name"] = "WANTED: Gorgebeak", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60316] = { ["id"] = 60316, ["name"] = "WANTED: Altered Sentinel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60316 }, ["description"] = "Praetor broken! At Aspirant's Crucible. Attacking everybody! Something wrong. Maybe changed? Simo not know how to fix. Tried everything! Must destroy!", ["objectivesText"] = "Destroy the Altered Sentinel for Forgehand Simo in Aspirant's Rest.", ["rewardGold"] = 709020, ["rewardXP"] = 1770, ["rewardItems"] = { 173349 }, ["starts"] = { { ["x"] = 0.491, ["y"] = 0.728, ["mapID"] = 1533, ["objectID"] = 352028 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160596, ["x"] = 0.49, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "group", ["sourceQuests"] = { 57715, 60217, 60218, 60219, 60220, 60221, 60222, 60223, 60224, 60225, 60226, 60229 }, ["questLines"] = { { ["id"] = 1154, ["name"] = "WANTED: Altered Sentinel", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
