[60338] = { ["id"] = 60338, ["name"] = "Journey to Ardenweald", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["series"] = { 60341, 60763, 60778 }, ["description"] = "The warning you received from the Primus needs to reach the Winter Queen of Ardenweald , <name>. The Eternal Ones must stand together against the coming darkness. The Winter Queen oversees the cycle between Death and Life. In her forest slumber ancient spirits of nature that must be reborn. I fear the anima drought will have taken an especially grim toll upon her realm. The night fae can lead you to the Queen. Bring her this message, and she will know what needs to be done.", ["objectivesText"] = "Travel to Ardenweald and find someone to take you to the Winter Queen.", ["rewardGold"] = 24570, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.699, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 168341, ["x"] = 0.682, ["y"] = 0.184 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 61715 }, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60339] = { ["id"] = 60339, ["name"] = "The Ember Court", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60339 }, ["description"] = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker. Be sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court. Remember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy! Talk to Lady Ilinca if you have any questions about guests. Once everything's ready, talk to me and I'll open the court!", ["objectivesText"] = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests. Progress: I can't wait to see who attends today's court!", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 176126, 176127, 176128, 176130, 176131, 176132, 176134, 176135, 176136, 176138, 176139, 176140, 176850, 179958, 181521, 181524, 181536, 182342, 182343 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[60340] = { ["id"] = 60340, ["name"] = "Hands on Approach", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60340 }, ["description"] = "When I was imprisoned in the Etheric Vault, the anima scroungers would come to steal what little strength my soul still had. I swore I'd have revenge upon them should I ever escape. Now, with my blade hands... it's time for my revenge! I've seen anima scroungers near the House of Constructs. I want their leader dead and the anima they took from me recovered!", ["objectivesText"] = "Slay Wurtzog Soultap and recover 12 anima traces . Progress: Did you kill them all?", ["rewardXP"] = 8165, ["rewardItems"] = { 178788, 182484, 182493, 182502, 182511, 183127, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159214, ["x"] = 0.544, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58416 } },
[60341] = { ["id"] = 60341, ["name"] = "First on the Agenda", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["series"] = { 60338, 60763, 60778 }, ["description"] = "Let's make a deal, <name>. I'll seek out the Winter Queen on your behalf if you complete a few of my duties in my stead. The Queen isn't the only one who's been kept busy by the drought! First, you're going to help my fellow fae here with their spriggan problem. Boot their leader off that poor moth! Featherlight will tell you where to go after that. We'll reunite in Tirna Vaal if you survive. Oh, and I would stay on the path if I were you. Ardenweald can be dangerous for the unwary!", ["objectivesText"] = "Slay Mothbane the Mighty . Progress: Not bad! Not bad at all!", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 157788, ["x"] = 0.65, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170175, ["x"] = 0.660667, ["y"] = 0.191333 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60763 }, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60342] = { ["id"] = 60342, ["name"] = "Cut 'Em Down to Size", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60342 }, ["description"] = "Idle hands are a wasted opportunity. I need to keep my hands busy, or else these blades wouldn't be worth anything! I hear there's a devourer in Revendreth that's as tall as a house. Let's show the other constructs a thing or two by taking that monster out!", ["objectivesText"] = "Slay Charthox in the Dredgewood of Revendreth.", ["rewardXP"] = 8165, ["rewardItems"] = { 182484, 182493, 182502, 182511, 183127, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159214, ["x"] = 0.544, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58416 } },
[60343] = { ["id"] = 60343, ["name"] = "Welcome to Orgrimmar", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["series"] = { 60344 }, ["description"] = "The warchief will be waiting for our mission report from Exile's Reach. I must deliver it at once. For now, Cork Fizzlepop will show you around the city. Orgrimmar has much to offer, so explore it as you see fit. I'll send for you once I've given my report to the warchief.", ["rewardGold"] = 1000, ["rewardXP"] = 505, ["starts"] = { { ["npcID"] = 168431, ["x"] = 0.524, ["y"] = 0.882, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 168441, ["x"] = 0.52, ["y"] = 0.854, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.524, ["y"] = 0.882, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 59985 }, ["questLines"] = { { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 54, ["flags"] = 0 } } },
[60344] = { ["id"] = 60344, ["name"] = "Finding Your Way", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["series"] = { 60343 }, ["description"] = "Orgrimmar 's a big city. Way too big to explore on foot. Warlord Grimaxe has arranged for you to receive a mount to help you get around. She said to speak with Rohaka at the stables... but I can't seem to remember the way there. Don't worry, ! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go. Let's ask a nearby guard for directions to the stable master. Then we can be on our way!", ["rewardXP"] = 505, ["rewardChoices"] = { 25474 }, ["starts"] = { { ["npcID"] = 168441, ["x"] = 0.52, ["y"] = 0.854, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 168540, ["x"] = 0.714, ["y"] = 0.474, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.52, ["y"] = 0.854, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 60343 }, ["questLines"] = { { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 55, ["flags"] = 0 } } },
[60346] = { ["id"] = 60346, ["name"] = "What's Your Specialty?", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["requiredClasses"] = { 11 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["description"] = "Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Telotha Pinegrove to learn more about specializations!", ["rewardXP"] = 505, ["starts"] = { { ["x"] = 0.615, ["y"] = 0.33, ["mapID"] = 85, ["npcID"] = 168545 } }, ["ends"] = { { ["npcID"] = 168553, ["x"] = 0.73, ["y"] = 0.434, ["mapID"] = 85 } }, ["coords"] = { ["mapID"] = 85, ["x"] = 0.615, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questGiverID"] = 168545, ["questType"] = "standard", ["sourceQuests"] = { 60344 }, ["questLines"] = { { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 57, ["flags"] = 0 } } },
