[60355] = { ["id"] = 60355, ["name"] = "What's Your Specialty?", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["description"] = "Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Kazak Darkscream to learn more about specializations!", ["rewardXP"] = 505, ["starts"] = { { ["x"] = 0.615, ["y"] = 0.33, ["mapID"] = 85, ["npcID"] = 168545 } }, ["ends"] = { { ["npcID"] = 168623, ["x"] = 0.746, ["y"] = 0.472, ["mapID"] = 85 } }, ["coords"] = { ["mapID"] = 85, ["x"] = 0.615, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questGiverID"] = 168545, ["questType"] = "standard", ["sourceQuests"] = { 60344 }, ["questLines"] = { { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 65, ["flags"] = 0 } } },
[60357] = { ["id"] = 60357, ["name"] = "What's Your Specialty?", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["description"] = "Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Gormok Ogrefist to learn more about specializations!", ["rewardXP"] = 505, ["starts"] = { { ["x"] = 0.615, ["y"] = 0.33, ["mapID"] = 85, ["npcID"] = 168545 } }, ["ends"] = { { ["npcID"] = 168596, ["x"] = 0.736, ["y"] = 0.468, ["mapID"] = 85 } }, ["coords"] = { ["mapID"] = 85, ["x"] = 0.615, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questGiverID"] = 168545, ["questType"] = "standard", ["sourceQuests"] = { 60344 }, ["questLines"] = { { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 66, ["flags"] = 0 } } },
[60358] = { ["id"] = 60358, ["name"] = "Gildenite Grab", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1707, ["storyline"] = { 60358 }, ["description"] = "Took our gildenite ! Stole it! Stole it and took it away! Need it, need it to make armor! Weapons! Can't make armor without gildenite ! You understand? Yes? Why you still here?", ["objectivesText"] = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", ["rewardItems"] = { 179321 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 182, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60359] = { ["id"] = 60359, ["name"] = "Home Is Where the Hearth Is", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["description"] = "I don't know about you, but I'm in the mood for some good ol' fashioned recreation! Why don't we head over to The Wyvern's Tail and cool off with a few pints of Cobo Cola? While we're there, speak with Innkeeper Nufa to make The Wyvern's Tail your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn. Not only is it faster than a wyvern, but you'll save yourself some dough in the process!", ["rewardXP"] = 505, ["starts"] = { { ["x"] = 0.736, ["y"] = 0.434, ["mapID"] = 85, ["npcID"] = 168545 } }, ["ends"] = { { ["npcID"] = 46642, ["x"] = 0.704, ["y"] = 0.49, ["mapID"] = 85 } }, ["coords"] = { ["mapID"] = 85, ["x"] = 0.736, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questGiverID"] = 168545, ["questType"] = "standard", ["sourceQuests"] = { 60346, 60347, 60348, 60349, 60350, 60351, 60352, 60353, 60355, 60357 }, ["questLines"] = { { ["id"] = 1107, ["name"] = "The Missing Expedition", ["orderIndex"] = 67, ["flags"] = 0 } } },
[60360] = { ["id"] = 60360, ["name"] = "An Urgent Meeting", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60360 }, ["description"] = "I've been looking for you all over Orgrimmar , <name>. Warlord Grimaxe has delivered her mission report to the warchief. The Horde has need of you once again. I was ordered to find you and deliver the message without delay. It has been an honor to fight alongside you, <name>. Lok-tar ogar!", ["objectivesText"] = "Speak with Warlord Breka Grimaxe at Grommash Hold.", ["rewardXP"] = 125, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 168771, ["x"] = 0.707333, ["y"] = 0.493333 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 168431, ["x"] = 0.511333, ["y"] = 0.827667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.707333, ["y"] = 0.493333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 60359 } },
[60361] = { ["id"] = 60361, ["name"] = "Battle for Azeroth: Mission Statement", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8499, ["mapID"] = 862, ["description"] = "The warchief has requested to meet with you in person. Lady Sylvanas was impressed with the prowess and courage you displayed during our mission to Exile's Reach. Now that you've arrived, I will make the introduction.", ["rewardGold"] = 200, ["rewardXP"] = 125, ["rewardChoices"] = { 178941, 178942 }, ["starts"] = { { ["npcID"] = 168431, ["x"] = 0.524, ["y"] = 0.882, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 121210, ["x"] = 0.58, ["y"] = 0.628, ["mapID"] = 862 } }, ["coords"] = { ["x"] = 0.524, ["y"] = 0.882, ["source"] = "quest_giver", ["mapID"] = 862 }, ["mapCandidates"] = { ["npc"] = { 85, 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 60360 }, ["questLines"] = { { ["id"] = 5389, ["name"] = "Unrest in Zuldazar", ["orderIndex"] = 78, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5389, ["questLineOrder"] = 0 } } },
[60362] = { ["id"] = 60362, ["name"] = "Blank", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 60362 }, ["series"] = { 46727, 46728, 46729, 47098, 47099, 51341, 57766, 58983, 59641 }, ["description"] = "Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore. Many have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father. Perhaps she feels the time has come to atone for this. Loath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance. Good luck.", ["objectivesText"] = "Speak with Lady Jaina Proudmoore in Stormwind Harbor.", ["rewardGold"] = 119340, ["rewardXP"] = 1415, ["rewardItems"] = { 204985, 205188 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[60363] = { ["id"] = 60363, ["name"] = "Gildenite Grab", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1698, ["storyline"] = { 60363 }, ["description"] = "Hshh... the golden ore, we need it. Golden ore of Bastion. Make their armor with it. We need, many uses. Armors, weapons, trinkets and rings. Many uses. Travel to Bastion. The eyes have shown me stores of it, stolen and hidden throughout their lands. They do not use it. We will. Go now.", ["objectivesText"] = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", ["rewardItems"] = { 179321 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 226, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60364] = { ["id"] = 60364, ["name"] = "Gildenite Grab", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 60364 }, ["description"] = "Our allies in Bastion are in possession of a special ore known as gildenite . A golden metal used for many things in their lands, it is also useful to us. Once upon a time, we would have traded for it. Now, we have little to trade, and they have little to give. Yet it is a necessary component to focus our magics, capable of harnessing magical energy and amplifying it. Should you come across any in your travels, liberate it, and return it to me. I shall use what we need, and share the remainder.", ["objectivesText"] = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", ["rewardItems"] = { 179321 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 204, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60365] = { ["id"] = 60365, ["name"] = "Gildenite Grab", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1700, ["storyline"] = { 60365 }, ["description"] = "The golden ore known as gildenite is found only in Bastion. Used to make many of their own armors, it is useful to us all. We harden our own armors and weapons with it, and it holds magical charge well. Our stores are nearly depleted, and we have little to trade, but our needs are great. Let us reflect. In Bastion, there are those that have turned their backs on their own people. We may relieve these deceivers of their gildenite without remorse.", ["objectivesText"] = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", ["rewardItems"] = { 179321 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 248, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60366] = { ["id"] = 60366, ["name"] = "WANTED: Darkwing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60366 }, ["description"] = "The Cloudfeather matriarch, Darkwing, has fallen to a great and terrible sickness. She has grown aggressive, dominating her children and driving them to violence. Darkwing must be slain if her flock is to ever return to the Archon's grace. Please use the attached whistle to call her to her nest. I shall consider one of her crown feathers sufficient proof of the deed. -- Eumelia , Stable Master", ["objectivesText"] = "Collect an Umbral Plume from Darkwing in Greatwing Roost for Eumelia . Progress: Until Darkwing rests at last I fear her brood will know no peace.", ["rewardGold"] = 772200, ["rewardXP"] = 1770, ["rewardItems"] = { 175762, 178790, 178791, 180643 }, ["rewardChoices"] = { 175762 }, ["starts"] = { { ["x"] = 0.532, ["y"] = 0.464, ["mapID"] = 1533, ["objectID"] = 352027 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160178, ["x"] = 0.524, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "group", ["sourceQuests"] = { 60735 }, ["questLines"] = { { ["id"] = 1152, ["name"] = "WANTED: Darkwing", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60369] = { ["id"] = 60369, ["name"] = "A Wealth of Wealdwood", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 60369 }, ["description"] = "The shapers of our lands cultivate a very special form of wood we call wealdwood . It contains the essence of Ardenweald, of the plants and animals that make up our soil and our air. It can be enchanted with powerful magics, and it will not burn. It is the basis of our arms and armor, and in these dark days, it is a target of our enemies. They steal and hoard it, out there in the wilds. Find them, and return our treasures to us.", ["objectivesText"] = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", ["rewardItems"] = { 179320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 203, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60370] = { ["id"] = 60370, ["name"] = "A Wealth of Wealdwood", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1700, ["storyline"] = { 60370 }, ["description"] = "In Ardenweald, the shapers form boughs into a magical form of wood. Wealdwood , an enchanted substance used for many sorcerous purposes, is a key component in our rituals. Without it, our magics pale in comparison to those of our enemies. Yet in these times, Ardenweald is beset by many foes. They steal the supplies of the Night Fae and scurry off into the dark places. Travel to those places, and return to us once you have brought atonement to these vile creatures.", ["objectivesText"] = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", ["rewardItems"] = { 179320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 247, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60371] = { ["id"] = 60371, ["name"] = "A Wealth of Wealdwood", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1698, ["storyline"] = { 60371 }, ["description"] = "The eyes have shown me supplies, in Ardenweald. Hidden in the boughs, hidden from us, but they cannot hide from the eyes. They do not use it, not as we would. We must use it. It is ours to take. Kshhhh... bring it to us, the shaped wood. Many uses, very magical. Holds magic as a pitcher holds slime, fills with it. Need it for our sorcerers. Cannot win in battle without our magic. Must win, no other way.", ["objectivesText"] = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", ["rewardItems"] = { 179320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 225, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60372] = { ["id"] = 60372, ["name"] = "A Wealth of Wealdwood", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1707, ["storyline"] = { 60372 }, ["description"] = "Ardenweald in trouble! We in trouble too! No Ardenweald, no wealdwood . wealdwood magical, help us make many thing. You find some? Bring to Sika? Yes? Hoo? Yes. See?", ["objectivesText"] = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", ["rewardItems"] = { 179320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 181, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60373] = { ["id"] = 60373, ["name"] = "A Source of Sorrowvine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 60373 }, ["description"] = "There is a dark, evil vine that grows in Revendreth, known as sorrowvine . They say it feeds off of the anguish of the souls as they are broken. Regardless of its origins, it is used in many of our potions and spells. It contains a powerful magic, likely a product of its origin. Revendreth has little opportunity to trade with us these days. Should you find any of these vines, I will gladly accept them.", ["objectivesText"] = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", ["rewardItems"] = { 179318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 206, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60374] = { ["id"] = 60374, ["name"] = "Bonemetal Bonanza", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 60374 }, ["description"] = "The denizens of Maldraxxus are used to a life of battle, and in doing so, find themselves in possession of so very many bones. They form their armors out of a cultivated form of bone we call bonemetal . Harder than most metals, yet pliable, it can be forged into a variety of shapes without losing its strength. We have many uses for it, both as a means of attachment, and when ground up, as a reagent. We cannot ask them for resources now, but if you find any, I would use it.", ["objectivesText"] = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", ["rewardItems"] = { 179317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 205, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60375] = { ["id"] = 60375, ["name"] = "Bonemetal Bonanza", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1700, ["storyline"] = { 60375 }, ["description"] = "Maldraxxus no longer answers our calls, and the houses are in disarray. Yet we have need of them. Once, they supplied us with bonemetal , a strong yet malleable material useful for many armors. There are those in Maldraxxus that hoard the material, seeking to profit from the chaos. They must atone for these sins.", ["objectivesText"] = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", ["rewardItems"] = { 179317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 249, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60376] = { ["id"] = 60376, ["name"] = "Bonemetal Bonanza", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1698, ["storyline"] = { 60376 }, ["description"] = "Ksh-ksh-ksh... you are needed. So many betrayers in our lands, many deaths, much armor destroyed. Need to rebuild. The eyes have shown me stores of bonemetal , hoarded by our foes. Bring them to me.", ["objectivesText"] = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", ["rewardItems"] = { 179317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 227, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60377] = { ["id"] = 60377, ["name"] = "Bonemetal Bonanza", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1707, ["storyline"] = { 60377 }, ["description"] = "No bonemetal ! Again, out of bonemetal ! Hoo! Where you come from? Oh, OH. bonemetal ! You get? Get from Maldraxxus. Help us out! That way!", ["objectivesText"] = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", ["rewardItems"] = { 179317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 183, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60378] = { ["id"] = 60378, ["name"] = "A Source of Sorrowvine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1700, ["storyline"] = { 60378 }, ["description"] = "Sorrowvine grows only here, in the lowlands of Revendreth. It has power contained within the leaves and seeds, perhaps a byproduct of the cleansing of sins. We use it for many things, from potions to venoms. It is a versatile reagent. Our stores are low, and we have little ability to forage these days with the forces of our enemies bearing down on us. As you travel our lands, should you come upon any, we would make good use of it.", ["objectivesText"] = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", ["rewardItems"] = { 179318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 250, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60379] = { ["id"] = 60379, ["name"] = "A Source of Sorrowvine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1698, ["storyline"] = { 60379 }, ["description"] = "Kshh... need you today. Stores of sorrowvine getting low, need it for our venoms. Revendreth does not answer our calls. The eyes show me conflict and strife in their lands. This matters little to us. Shh... travel there, find their vines, return to me.", ["objectivesText"] = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", ["rewardItems"] = { 179318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 228, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60380] = { ["id"] = 60380, ["name"] = "A Source of Sorrowvine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1707, ["storyline"] = { 60380 }, ["description"] = "Need sorrowvine ! Please help! Revendreth not sending us supplies, not answering Sika! Can't make potions now. What we do? You go! Go go!", ["objectivesText"] = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", ["rewardItems"] = { 179318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 184, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60381] = { ["id"] = 60381, ["name"] = "Aiding Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60381 }, ["description"] = "Today, we must turn our gaze inward. We are beset by foes here, in Ardenweald, from all sides. Travel our lands, weapon in hand, and bring hope and victory with you. Bring aid to those in need, and remind them that we are here for them, and Ardenweald will not fall. Remind them that our great purpose will be fulfilled, and we will not let the groves wither. You, Maw Walker, will unite us today.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald. Progress: Have you brought hope and faith to our people today?", ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.537, ["y"] = 0.062, ["mapID"] = 1701, ["npcID"] = 167195 } }, ["ends"] = { { ["x"] = 0.537, ["y"] = 0.062, ["mapID"] = 1701, ["npcID"] = 167195 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.537, ["y"] = 0.062 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167195, ["questTurnInID"] = 167195, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 207, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60382] = { ["id"] = 60382, ["name"] = "Aiding Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60382 }, ["description"] = "We do not turn out backs on our allies, even when we face darkness here in Ardenweald. In Revendreth, they battle against the forces of Sire Denathrius, who has proven himself a false leader. We cannot allow those that make Sinfall their home to lose hope. Travel to Revendreth and supply aid to them. Show them that we will not let them falter, that we are stronger together.", ["objectivesText"] = "Complete 3 World Quests in Revendreth. Progress: How goes the battle in Revendreth?", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.537, ["y"] = 0.0642, ["mapID"] = 1701, ["npcID"] = 167195 } }, ["ends"] = { { ["x"] = 0.537, ["y"] = 0.0642, ["mapID"] = 1701, ["npcID"] = 167195 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.537, ["y"] = 0.0642 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167195, ["questTurnInID"] = 167195, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 210, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60383] = { ["id"] = 60383, ["name"] = "Aiding Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60383 }, ["description"] = "Maldraxxus defends us from forces that threaten the Shadowlands, or at least, they once did. Now they are plagued by infighting and an imbalance in power. We have few allies there, but those that remain, we must maintain. Go there, give them aid, and help them reunite the houses such that the armies of the undying may defend us once more. Without them, we are but one invasion from complete annihilation.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus. Progress: Have you aided the forces of Maldraxxus?", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.531, ["y"] = 0.061, ["mapID"] = 1701, ["npcID"] = 167195 } }, ["ends"] = { { ["x"] = 0.531, ["y"] = 0.061, ["mapID"] = 1701, ["npcID"] = 167195 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.531, ["y"] = 0.061 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167195, ["questTurnInID"] = 167195, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 209, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60384] = { ["id"] = 60384, ["name"] = "Aiding Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60384 }, ["description"] = "The denizens of Bastion have long served the Shadowlands with faith and honor. Without them, souls would not arrive for us to nurture, and our lands would wither and die. We cannot allow them to fall, for without Bastion, we are lost. Travel to the golden fields, weapon in hand, and provide aid to our besieged allies. We will show them that in these dark times, they are not alone.", ["objectivesText"] = "Complete 3 World Quests in Bastion. Progress: Have you aided Bastion today?", ["rewardItems"] = { 181372 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.537, ["y"] = 0.0653, ["mapID"] = 1701, ["npcID"] = 167195 } }, ["ends"] = { { ["x"] = 0.537, ["y"] = 0.0653, ["mapID"] = 1701, ["npcID"] = 167195 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.537, ["y"] = 0.0653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167195, ["questTurnInID"] = 167195, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 208, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60385] = { ["id"] = 60385, ["name"] = "Training in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 60385 }, ["description"] = "The dark lands of Revendreth, ruled over by the traitor Denathrius, pose a great risk to us, and a great opportunity for training. Come here, trainee! Today, you hunt with the Maw Walker. Should you return to me, we will celebrate, with a hunt. For tomorrow, we hunt.", ["objectivesText"] = "Complete 3 World Quests in Revendreth with your trainee.", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 214, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60386] = { ["id"] = 60386, ["name"] = "Training in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 60386 }, ["description"] = "The forces of Maldraxxus are some of the most highly trained and well-regimented in all of the Shadowlands. Once, they defended us all, now we must fend for ourselves. There is little better place for our trainees to gain real combat and strategy experience than on their blood-soaked battlefields. Take this one with you on your travels today, so that they may see what real combat looks like.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus with your trainee. Progress: Do you return with a trainee, or a coward?", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 213, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60387] = { ["id"] = 60387, ["name"] = "Training in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 60387 }, ["description"] = "Our hunters do not have the time for proper training, and so we must train them in the field. Our allies in Bastion are in desperate need of support, and I wish one of the trainees to accompany you in this endeavor. Do you hear that, trainee? Today, you accompany the Maw Walker! Maw Walker, do not go easy on this one.", ["objectivesText"] = "Complete 3 World Quests in Bastion with your trainee. Progress: I hope that today's trainee survived the trip, but I am not overly confident.", ["rewardItems"] = { 181372 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 212, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60388] = { ["id"] = 60388, ["name"] = "Training Our Forces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 60388 }, ["description"] = "Get up, trainee, you must get up! Look at this one! Needs much more training before we stand a fighting chance against our enemies. We have precious little time to build combat prowess these days, with so many foes at our backs. Take this one with you today, show them the ways of battle, and keep them safe from overwhelming odds. It is the only way we will make enough progress.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald with your trainee. Progress: How goes the training?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 211, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60389] = { ["id"] = 60389, ["name"] = "Aiding Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 60389 }, ["description"] = "Ay there, ya got a moment? Lotta things going on down in Ardenweald. Bad stuff, bugs and things. Look delicious, but probably give me ol' stomach a nasty one. We're lookin' pretty solid here today, ya see? Probably could use a hand down there. Maybe they give us a hand in return, see? Do I gotta spell it out for you? Get on over there, ya big goof.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald.", ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.622, ["y"] = 0.763, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["ends"] = { { ["x"] = 0.622, ["y"] = 0.763, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.622, ["y"] = 0.763 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 165302, ["questTurnInID"] = 165302, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 251, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60390] = { ["id"] = 60390, ["name"] = "Aiding Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60390 }, ["description"] = "We are attacked by enemies on all sides, Maw Walker. And Ardenweald faces a similar threat. It is in our best strategic interests to forge lasting alliances with those outside of Maldraxxus. Though we may be under assault, we are still the strongest military might in the Shadowlands. Under our protection, they will thrive and grow, and in turn, provide us with aid in our times of need. Together, we are strong. This is the doctrine of the phalanx, and it will be ours as well.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald. Progress: Have you secured allies in Ardenweald?", ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.542, ["y"] = 0.688, ["mapID"] = 1536, ["npcID"] = 158339 } }, ["ends"] = { { ["x"] = 0.542, ["y"] = 0.688, ["mapID"] = 1536, ["npcID"] = 158339 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.542, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 158339, ["questTurnInID"] = 158339, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 229, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60391] = { ["id"] = 60391, ["name"] = "Aiding Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60391 }, ["description"] = "Ardenweald has long been one of our closest companions in the shepherding and nurturing of souls. Now they are beset by many foes, and we will not allow them to fall! Make haste to their forested lands, and with the blessing of the Archon upon you, serve a glorious purpose. Stand with them in their time of need, a gilded shield, a reminder that they are not alone! Bastion stands with them, and with us, they will never falter!", ["objectivesText"] = "Complete 3 World Quests in Ardenweald. Progress: Have you served in Ardenweald today?", ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.41, ["y"] = 0.412, ["mapID"] = 1707, ["npcID"] = 160387 } }, ["ends"] = { { ["x"] = 0.41, ["y"] = 0.412, ["mapID"] = 1707, ["npcID"] = 160387 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.41, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 160387, ["questTurnInID"] = 160387, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 185, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60392] = { ["id"] = 60392, ["name"] = "Aiding Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60392 }, ["description"] = "In our own golden hills, evil abounds. We will not allow it to take root and fester! Raise your voice, Maw Walker, and shout to the foes of Bastion! We are coming for them! With haste, now, seek out those in need of your might. Bring the sharpened blade of faith to bear against doubt and uncertainty. Crush despair with a gilded fist, and let it know the vengeance of the Archon! For Bastion!", ["objectivesText"] = "Complete 3 World Quests in Bastion. Progress: Do the hills echo with the cries of your victories, Maw Walker?", ["rewardItems"] = { 181372 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.41, ["y"] = 0.411, ["mapID"] = 1707, ["npcID"] = 160387 } }, ["ends"] = { { ["x"] = 0.41, ["y"] = 0.411, ["mapID"] = 1707, ["npcID"] = 160387 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.41, ["y"] = 0.411 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 160387, ["questTurnInID"] = 160387, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 186, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60393] = { ["id"] = 60393, ["name"] = "Aiding Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60393 }, ["description"] = "The kyrians of Bastion serve a unique purpose in the Shadowlands, and without them we will be unable to replenish our forces. Should we wish to stand triumphant in Maldraxxus, we must extend some of our might to aid them. Travel to Bastion and provide support, so as to stabilize their situation. In doing so, we will secure the future of our armies and cut off the supply to our enemies. War is not always fought on the battlefield, but often in the means of replenishment.", ["objectivesText"] = "Complete 3 World Quests in Bastion. Progress: Have you secured the situation in Bastion?", ["rewardItems"] = { 181372 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.542, ["y"] = 0.688, ["mapID"] = 1536, ["npcID"] = 158339 } }, ["ends"] = { { ["x"] = 0.542, ["y"] = 0.688, ["mapID"] = 1536, ["npcID"] = 158339 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.542, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 158339, ["questTurnInID"] = 158339, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 230, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60394] = { ["id"] = 60394, ["name"] = "Aiding Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 60394 }, ["description"] = "If'n the kyrians of Bastion don't get souls to the Shadowlands, we got no one to join up, and no anima to gain in them sinstones. Be in a bad place, you know, now and in the future, if things ever bother to get better. We got things figured out here today. Head on over to them golden hills of Bastion and give 'em a hand. Bet they pay us back some day. They're all about honor an' stuff. < Rendle wipes his nose loudly.>", ["objectivesText"] = "Complete 3 World Quests in Bastion.", ["rewardItems"] = { 181372 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.62, ["y"] = 0.762, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["ends"] = { { ["x"] = 0.62, ["y"] = 0.762, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.62, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 165302, ["questTurnInID"] = 165302, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 252, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60395] = { ["id"] = 60395, ["name"] = "Aiding Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60395 }, ["description"] = "In the fetid wastes of Maldraxxus, we yet find allies. Their sacred duty, to defend the Shadowlands, has not been forgotten by all. We must take flight, now, to stand side by side with our bone-bound brethren. Shoulder to shoulder, hand in hand, we will push back those that would sow chaos and discord. A spear of gold and bone we will form! And thrust it into the heart of evil! Go now, Maw Walker, as the tip of the spear, to glorious battle!", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus. Progress: Have you pierced the heart of evil in Maldraxxus?", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.409, ["y"] = 0.41, ["mapID"] = 1707, ["npcID"] = 160387 } }, ["ends"] = { { ["x"] = 0.409, ["y"] = 0.41, ["mapID"] = 1707, ["npcID"] = 160387 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.409, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 160387, ["questTurnInID"] = 160387, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 187, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60396] = { ["id"] = 60396, ["name"] = "Aiding Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60396 }, ["description"] = "The allies we have here in Maldraxxus may be few, but we cannot turn our backs on them. Every hand we pull out of darkness and into our fold, is a hand that can hold a weapon or wand. Walk our lands, find those seeking aid, and provide it. Crush our enemies, and show them that we are at once everywhere. Make them fear you. Fear is the seed that breeds doubt, and doubt is the root that crumbles empires.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus. Progress: How goes the battle?", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.542, ["y"] = 0.688, ["mapID"] = 1536, ["npcID"] = 158339 } }, ["ends"] = { { ["x"] = 0.542, ["y"] = 0.688, ["mapID"] = 1536, ["npcID"] = 158339 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.542, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 158339, ["questTurnInID"] = 158339, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 231, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60397] = { ["id"] = 60397, ["name"] = "Aiding Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 60397 }, ["description"] = "Once was a time that those bony lot in Maldraxxus were the defenders o' all of us here in the Shadowlands. Now they spend their time destroyin' what little they got left. All's I know is that if things keep up like this, one big ol' swath of devourers could sweep in and wipe us all out. Get over there and help them good ones keep the peace, maybe they help us out some day, too.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus.", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.62, ["y"] = 0.761, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["ends"] = { { ["x"] = 0.62, ["y"] = 0.761, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.62, ["y"] = 0.761 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 165302, ["questTurnInID"] = 165302, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 253, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60398] = { ["id"] = 60398, ["name"] = "Aiding Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60398 }, ["description"] = "Our allies in Revendreth are all that stem the tide of Denathrius's forces from overtaking the rest of the Shadowlands. Once, we would be charged with righting this wrong, but our armies have dwindled with the actions of our rival houses. Today, you will be the messenger from Maldraxxus, carrying a message of justice in the name of the great cycle of which we all take part. It is your Primus-given duty to aid Sinfall against those that seek to break the cycle.", ["objectivesText"] = "Complete 3 World Quests in Revendreth. Progress: Have you broken the forces of Denathrius?", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.542, ["y"] = 0.688, ["mapID"] = 1536, ["npcID"] = 158339 } }, ["ends"] = { { ["x"] = 0.542, ["y"] = 0.688, ["mapID"] = 1536, ["npcID"] = 158339 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.542, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 158339, ["questTurnInID"] = 158339, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 232, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60399] = { ["id"] = 60399, ["name"] = "Aiding Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 60399 }, ["description"] = "Oi there, got somethin' for you to do today. Lots of problems outside of Sinfall, there are. Big problems, little problems, all sorts of problems. We're not gonna make much headway against Denathrius with his lot at our heels all the time, ay? Get out there an' get some muck on your boots.", ["objectivesText"] = "Complete 3 World Quests in Revendreth. Progress: What do ya want?", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.622, ["y"] = 0.763, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["ends"] = { { ["x"] = 0.622, ["y"] = 0.763, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.622, ["y"] = 0.763 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 165302, ["questTurnInID"] = 165302, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 254, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60400] = { ["id"] = 60400, ["name"] = "Aiding Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60400 }, ["description"] = "Take flight to Revendreth, where those that are loyal to the Shadowlands are under siege from the forces of Sire Denathrius. We cannot allow them to fall. Without the aid of Sinfall, the forces of Revendreth will grow unchecked, and their dark alliance with the Jailer will threaten us all. We of Bastion will not allow this to happen! Raise your swords, ready your shields, take wing and bring the glory of Bastion to Revendreth!", ["objectivesText"] = "Complete 3 World Quests in Revendreth.", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.409, ["y"] = 0.41, ["mapID"] = 1707, ["npcID"] = 160387 } }, ["ends"] = { { ["x"] = 0.409, ["y"] = 0.41, ["mapID"] = 1707, ["npcID"] = 160387 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.409, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 160387, ["questTurnInID"] = 160387, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 188, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60401] = { ["id"] = 60401, ["name"] = "Training in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60401 }, ["description"] = "I have another trainee for you to look after, they need some training on the battlefield. Take them out to, oh, let's say Ardenweald. <Sakaa waves her hand vaguely in the direction of Ardenweald.> Plenty of things to maim over there, maybe they learn a thing or two about wood. <Sakaa smirks.>", ["objectivesText"] = "Complete 3 World Quests in Ardenweald with your trainee.", ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.578, ["y"] = 0.587, ["mapID"] = 1699, ["npcID"] = 164741 } }, ["ends"] = { { ["x"] = 0.578, ["y"] = 0.587, ["mapID"] = 1699, ["npcID"] = 164741 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.578, ["y"] = 0.587 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 164741, ["questTurnInID"] = 164741, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 255, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60402] = { ["id"] = 60402, ["name"] = "Training in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60402 }, ["description"] = "Look at this lot! Bones and gristle, all of them. Need some meat on their bones and some training in their heads. Take this trainee out and get them some real combat experience. Ardenweald's a good spot, plenty of things to fight there. Learn some new tactics, get them used to the chaos of battle, all that stuff.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald with your trainee. Progress: You back already?", ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.518, ["y"] = 0.288, ["mapID"] = 1698, ["npcID"] = 167209 } }, ["ends"] = { { ["x"] = 0.518, ["y"] = 0.288, ["mapID"] = 1698, ["npcID"] = 167209 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.518, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167209, ["questTurnInID"] = 167209, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 233, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60403] = { ["id"] = 60403, ["name"] = "Training in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60403 }, ["description"] = "It is our great duty to take our aspiring warriors and train them in combat. Today, this is your trainee. Take them to Ardenweald, show them what it means to be in the glorious service of the Archon. Defend our allies, and bring faith to their lands. Teach them the ways of battle and honor.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald with your trainee. Progress: How fares the training?", ["rewardItems"] = { 171263, 171301, 171349, 171436, 171439, 173126, 174285, 177040, 178227, 179286, 180318, 181475, 184500, 184501, 184502, 184503, 184504, 184507 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.373, ["y"] = 0.61, ["mapID"] = 1707, ["npcID"] = 168517 } }, ["ends"] = { { ["x"] = 0.373, ["y"] = 0.61, ["mapID"] = 1707, ["npcID"] = 168517 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.373, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 168517, ["questTurnInID"] = 168517, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 189, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60404] = { ["id"] = 60404, ["name"] = "Training Our Forces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60404 }, ["description"] = "What better place to stretch our wings than right here on our own fields? Take one of our trainees out with you today, show them the ways of combat in Bastion against the growing threats we face here. Part of their training will be courage when facing off against those they thought their brethren. It has been known to break hearts and ranks before.", ["objectivesText"] = "Complete 3 World Quests in Bastion with your trainee. Progress: How fares your heart today?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.373, ["y"] = 0.611, ["mapID"] = 1707, ["npcID"] = 168517 } }, ["ends"] = { { ["x"] = 0.373, ["y"] = 0.611, ["mapID"] = 1707, ["npcID"] = 168517 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.373, ["y"] = 0.611 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 168517, ["questTurnInID"] = 168517, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 190, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60405] = { ["id"] = 60405, ["name"] = "Training in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60405 }, ["description"] = "Useless minions, the lot of them. All of this fodder needs to get trained. Here, take this one with you today. Get them away from me, go to... Bastion. Yeah, Bastion, far away from me. Plenty of things to test them against, there. If you get them killed, I don't want to hear it.", ["objectivesText"] = "Complete 3 World Quests in Bastion with your trainee. Progress: Any luck with this sad lot?", ["rewardItems"] = { 181372 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.518, ["y"] = 0.288, ["mapID"] = 1698, ["npcID"] = 167209 } }, ["ends"] = { { ["x"] = 0.518, ["y"] = 0.288, ["mapID"] = 1698, ["npcID"] = 167209 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.518, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167209, ["questTurnInID"] = 167209, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 234, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60406] = { ["id"] = 60406, ["name"] = "Training in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60406 }, ["description"] = "I have yet another minion, er, recruit that needs training. Take them on out to the fertile fields of Bastion. There is plenty to learn over there that they won't find around these parts, perhaps it will help them grow into a better soldier. Maybe you pick up some new tricks while you're out there, too.", ["objectivesText"] = "Complete 3 World Quests in Bastion with your trainee.", ["rewardItems"] = { 92683, 116424, 171268, 171270, 171441, 181372, 184090 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.578, ["y"] = 0.595, ["mapID"] = 1699, ["npcID"] = 164741 } }, ["ends"] = { { ["x"] = 0.578, ["y"] = 0.595, ["mapID"] = 1699, ["npcID"] = 164741 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.578, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 164741, ["questTurnInID"] = 164741, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 256, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60407] = { ["id"] = 60407, ["name"] = "Training in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60407 }, ["description"] = "Our aspiring warriors must be trained in the thick of battle, in the harshest conditions, for wars do not happen lightly, and never will it give them pause for breath. Take this one to Maldraxxus--the heart of the armies of the Shadowlands resides there. It is a land in chaos and turmoil, filled with fallen champions and gladiators. There, they will face true challenges, and return with great knowledge.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus with your trainee. Progress: Has your trainee survived the fields of battle?", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 168517 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 168517, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 191, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60408] = { ["id"] = 60408, ["name"] = "Training Our Forces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60408 }, ["description"] = "Our armies are nothing without some combat training, but every time we send them out, they come back as a pile of bones and meat. Take a trainee out and pit them against the forces of the other houses. Just don't get them killed, alright? Not all the way killed. A little killed is fine.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus with your trainee. Progress: Any luck out there?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.518, ["y"] = 0.288, ["mapID"] = 1698, ["npcID"] = 167209 } }, ["ends"] = { { ["x"] = 0.518, ["y"] = 0.288, ["mapID"] = 1698, ["npcID"] = 167209 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.518, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167209, ["questTurnInID"] = 167209, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 235, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60409] = { ["id"] = 60409, ["name"] = "Training in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60409 }, ["description"] = "Another trainee needs some looking after, if you don't mind. Maldraxxus is a place of constant battle, and probably the best place to take them. They've got to learn about war and strategy and, you know, all that. Just throw them in the arena or something. 'Sink or swim' is an effective training strategy.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus with your trainee. Progress: Could really go for a nap I could.", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.578, ["y"] = 0.595, ["mapID"] = 1699, ["npcID"] = 164741 } }, ["ends"] = { { ["x"] = 0.578, ["y"] = 0.595, ["mapID"] = 1699, ["npcID"] = 164741 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.578, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 164741, ["questTurnInID"] = 164741, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 257, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60410] = { ["id"] = 60410, ["name"] = "Training Our Forces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60410 }, ["description"] = "I have yet more troops for you to train, and there are plenty of things to do right here in our domain. Take them out and give them a good, solid, and probably bloody taste of what we're up against. Now, if you get them killed? That's none of my business. <Sakaa sips a thick and sweet-smelling beverage.>", ["objectivesText"] = "Complete 3 World Quests in Revendreth with your trainee. Progress: Did you manage to bring them back alive?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.578, ["y"] = 0.595, ["mapID"] = 1699, ["npcID"] = 164741 } }, ["ends"] = { { ["x"] = 0.578, ["y"] = 0.595, ["mapID"] = 1699, ["npcID"] = 164741 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.578, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 164741, ["questTurnInID"] = 164741, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 258, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60411] = { ["id"] = 60411, ["name"] = "Training in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60411 }, ["description"] = "Lousy, useless, bunch of bones. This army's less of an army than it is a bunch of dead meat walking. Do me a favor, take out this trainee and head over to Revendreth. Give them some good battle training against some of our enemies, a little taste of strategy and tactics and maybe getting hit in the face with a little magic. Won't do us any good unless we find a way to train them that doesn't end up in a bunch of dead minions.", ["objectivesText"] = "Complete 3 World Quests in Revendreth with your trainee. Progress: Well? You bring back a pile of bones or a trainee?", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.518, ["y"] = 0.288, ["mapID"] = 1698, ["npcID"] = 167209 } }, ["ends"] = { { ["x"] = 0.518, ["y"] = 0.288, ["mapID"] = 1698, ["npcID"] = 167209 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.518, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167209, ["questTurnInID"] = 167209, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 236, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60412] = { ["id"] = 60412, ["name"] = "Training in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60412 }, ["description"] = "A trainee is in need of your guiding hand. Take them to Revendreth, where you will find the armies of Denathrius thirsting for our demise. Wade in to battle with them against our mighty foes. Return victorious, as their shield and mentor, so that our armies will be bolstered this day.", ["objectivesText"] = "Complete 3 World Quests in Revendreth with your trainee.", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.372, ["y"] = 0.61, ["mapID"] = 1707, ["npcID"] = 168517 } }, ["ends"] = { { ["x"] = 0.372, ["y"] = 0.61, ["mapID"] = 1707, ["npcID"] = 168517 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.372, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 168517, ["questTurnInID"] = 168517, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 192, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60414] = { ["id"] = 60414, ["name"] = "Rare Resources", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60414 }, ["description"] = "The Brokers are odd characters, but useful. They can find many things across the vast realms of the Shadowlands that we cannot. We have relied upon them to bring us useful materials for many years, but these days, we have little to trade. They value a currency of their own making, coins of brokerage, as a general means of trade. If you find any in your travels, I would appreciate a handful, as it would allow me to procure some rare and necessary items.", ["objectivesText"] = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Have you found any coins?", ["rewardItems"] = { 179327, 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 168513, ["x"] = 0.435, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 168513, ["x"] = 0.435, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 202, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60415] = { ["id"] = 60415, ["name"] = "Rare Resources", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60415 }, ["description"] = "Hello! Yes! Hello. Brokers, you know them? < Sika does her best attempt at looking like a broker. It is not convincing.> Trade many things with us. Things we no get. Things we want. Need coins. Clink clink! < Sika makes a circle with her finger feathers.> Find them everywhere, bring them to Sika !", ["objectivesText"] = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Bring coins to Sika ? Need trade with brokers. You know this?", ["rewardItems"] = { 179327, 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168519, ["x"] = 0.634, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168519, ["x"] = 0.634, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 180, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60416] = { ["id"] = 60416, ["name"] = "Rare Resources", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60416 }, ["description"] = "Kh-kh-kh... the brokers, they go to many places. Many places we cannot. The eyes cannot follow them. Find many secrets, they do. Bring us supplies, strange and rare. Need things to trade. Need broker coins. They trade with all. Find coins in all lands. Slay those that hold them, bring the coins to me. You may eat their corpses, I will not judge. Just need coins.", ["objectivesText"] = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Bring me coins? Coins for brokers. Many uses. You see?", ["rewardItems"] = { 179327, 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.468, ["y"] = 0.386, ["mapID"] = 1698, ["npcID"] = 167201 } }, ["ends"] = { { ["x"] = 0.468, ["y"] = 0.386, ["mapID"] = 1698, ["npcID"] = 167201 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.468, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167201, ["questTurnInID"] = 167201, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 224, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60417] = { ["id"] = 60417, ["name"] = "Rare Resources", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13400, ["mapID"] = 1700, ["storyline"] = { 60417 }, ["description"] = "The brokers are an enigmatic group. We know little about them, save that they can travel to many lands in the Shadowlands that we cannot. How they do this, we are not sure. They are willing partners in trade, though, and through them we have acquired many rare and valuable resources that cannot be found elsewhere. They hold in high regard a currency of their own creation, you may find such coins in your travels. I will gladly take them off of your hands to bolster our supplies.", ["objectivesText"] = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Have you found any of the broker's coins?", ["rewardItems"] = { 179327, 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.613, ["y"] = 0.667, ["mapID"] = 1700, ["npcID"] = 158713 } }, ["ends"] = { { ["x"] = 0.613, ["y"] = 0.667, ["mapID"] = 1700, ["npcID"] = 158713 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.613, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13400 } }, ["questGiverID"] = 158713, ["questTurnInID"] = 158713, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 246, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60418] = { ["id"] = 60418, ["name"] = "A Call to Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60418 }, ["description"] = "Our allies in Bastion are absolutely necessary for the Shadowlands to function at all. They alone can bring us the souls we need to keep the cycle moving. If they fall to darkness, it's only a matter of time before we, too, dwindle and fade. They are beset by all manner of problems. We have to get over there and help them!", ["objectivesText"] = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: How are the Kyrians?", ["rewardItems"] = { 181372 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.599, ["y"] = 0.317, ["mapID"] = 1701, ["npcID"] = 167193 } }, ["ends"] = { { ["x"] = 0.599, ["y"] = 0.317, ["mapID"] = 1701, ["npcID"] = 167193 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.599, ["y"] = 0.317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167193, ["questTurnInID"] = 167193, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 194, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60419] = { ["id"] = 60419, ["name"] = "Troubles at Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60419 }, ["description"] = "They say that all of the Shadowlands is a stage, and right now, I think we're in a tragedy! All throughout Ardenweald, we are under attack. They seek our anima and the souls that we protect. If the cycle stops here, so many great souls will be lost... forever. There's no time to waste, we need your help! Defend Ardenweald!", ["objectivesText"] = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: Are things improving in the glades?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.597, ["y"] = 0.313, ["mapID"] = 1701, ["npcID"] = 167193 } }, ["ends"] = { { ["x"] = 0.597, ["y"] = 0.313, ["mapID"] = 1701, ["npcID"] = 167193 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.597, ["y"] = 0.313 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167193, ["questTurnInID"] = 167193, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 193, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60420] = { ["id"] = 60420, ["name"] = "A Call to Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60420 }, ["description"] = "I'm glad you're here! We've got some problems in Maldraxxus. The forces of Maldraxxus are the defenders of the Shadowlands. They've always managed to balance one another out, like actors on a stage, never stealing too much of the spotlight. But now, some of the houses have overthrown the balance, and seek to conquer the rest of us! Our allies there need our help! Aid them however you can.", ["objectivesText"] = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons. Progress: Are things improving in Maldraxxus?", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.599, ["y"] = 0.321, ["mapID"] = 1701, ["npcID"] = 167193 } }, ["ends"] = { { ["x"] = 0.599, ["y"] = 0.321, ["mapID"] = 1701, ["npcID"] = 167193 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.599, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167193, ["questTurnInID"] = 167193, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 195, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60421] = { ["id"] = 60421, ["name"] = "A Call to Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60421 }, ["description"] = "Oh, I'm glad you're here, we've got a problem! Our friends in Revendreth are struggling under the rule of Sire Denathrius. He was always a cruel leader, and now he's thrown in his lot with the Jailer! If Denathrius's control of Revendreth isn't broken, he'll come for us next... Let's do whatever we can to help them out!", ["objectivesText"] = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: How are things in Revendreth?", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.599, ["y"] = 0.324, ["mapID"] = 1701, ["npcID"] = 167193 } }, ["ends"] = { { ["x"] = 0.599, ["y"] = 0.324, ["mapID"] = 1701, ["npcID"] = 167193 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.599, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167193, ["questTurnInID"] = 167193, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 196, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60422] = { ["id"] = 60422, ["name"] = "A Call to Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60422 }, ["description"] = "We cannot stand alone. If one section of the Shadowlands falls, we will all be in danger. The great soul-trees of Ardenweald are under assault from many foes that seek to harness their power. We must aid our allies in the Night Fae, and punish their enemies for these transgressions. We are stronger together.", ["objectivesText"] = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: Have you completed your task?", ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.512, ["y"] = 0.377, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["ends"] = { { ["x"] = 0.512, ["y"] = 0.377, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.512, ["y"] = 0.377 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 158653, ["questTurnInID"] = 158653, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 237, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60423] = { ["id"] = 60423, ["name"] = "A Call to Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60423 }, ["description"] = "Ardenweald was once a place of peace and regrowth, now beset by dark forces from all sides. Maldraxxus alone is responsible for challenging those that would disrupt the cycle. Take our banners, steady your weapons, and bring war to Ardenweald. For the Shadowlands.", ["objectivesText"] = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: How do the boughs break?", ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.596, ["y"] = 0.435, ["mapID"] = 1698, ["npcID"] = 167210 } }, ["ends"] = { { ["x"] = 0.596, ["y"] = 0.435, ["mapID"] = 1698, ["npcID"] = 167210 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.596, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167210, ["questTurnInID"] = 167210, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 215, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60424] = { ["id"] = 60424, ["name"] = "A Call to Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60424 }, ["description"] = "Ardenweald is one of our closest allies, and to them we ferry some of the most powerful souls. Should the weald fall, the devastation that would be unleashed could destroy us all. We must aid the Winter Queen. It is the will of the Archon. Go now, and provide support to the Night Fae.", ["objectivesText"] = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: Have things improved in Ardenweald?", ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 171, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60425] = { ["id"] = 60425, ["name"] = "Troubles at Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60425 }, ["description"] = "Sometimes we must look inward to find true darkness. Here, in Bastion, where once there was harmony, now we face many foes. Today, we root them out. Head into the golden fields, with your weapon in hand. Cleanse us of these foul creatures, aid our forces when they have need of you. In the name of the Archon.", ["objectivesText"] = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: Are the fields cleansed?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 172, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60426] = { ["id"] = 60426, ["name"] = "A Call to Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60426 }, ["description"] = "We, the defenders of the Shadowlands, will never let a great foe go unchallenged. The Kyrians of Bastion have long served all denizens of the Shadowlands by ferrying souls. We would be lost without their services. Now, they too are under attack from within. We must defend them in their time of need. Go now, and bring glory in the name of the Primus.", ["objectivesText"] = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: Are the golden fields bathed in blood?", ["rewardItems"] = { 179327, 181372 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.596, ["y"] = 0.435, ["mapID"] = 1698, ["npcID"] = 167210 } }, ["ends"] = { { ["x"] = 0.596, ["y"] = 0.435, ["mapID"] = 1698, ["npcID"] = 167210 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.596, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167210, ["questTurnInID"] = 167210, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 216, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60427] = { ["id"] = 60427, ["name"] = "A Call to Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60427 }, ["description"] = "The denizens of Bastion are a key component to the cycle of power here in the Shadowlands. Without them, we cannot replenish our ranks, and the forces of the Jailer will grow ever stronger. They have their own troubles in these times, as well. Today, we must look without, and aid our allies. Travel to the golden fields, and rid them of their foes. Only with allies do we stand a chance against Denathrius.", ["objectivesText"] = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: Have you completed your task?", ["rewardItems"] = { 181372 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.518, ["y"] = 0.374, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["ends"] = { { ["x"] = 0.518, ["y"] = 0.374, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.518, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 158653, ["questTurnInID"] = 158653, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 238, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60428] = { ["id"] = 60428, ["name"] = "The Blade of the Primus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["series"] = { 60453 }, ["description"] = "That's everything I need. Time to get to work. I'd stay close, if I were you. Forging a weapon is never a simple task when the Primus's handiwork is involved. If he taught me anything, it was to expect the unexpected.", ["objectivesText"] = "Help Bonesmith Heirmir forge your runeblade. Progress: Stay close, now.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.418667, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58618, 58726 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60429] = { ["id"] = 60429, ["name"] = "Troubles at Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60429 }, ["description"] = "Look! Look around you! All around us, foes await the crushing hand of victory. There is an upset in the balance of power, and with it, the defenders of the Shadowlands are weakened. The only cure is more combat! Challenge the houses that sought to disrupt Maldraxxus, bring them to heel under the weight of your boots.", ["objectivesText"] = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons. Progress: Have you littered the ground with the bones of your enemies?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.597, ["y"] = 0.437, ["mapID"] = 1698, ["npcID"] = 167210 } }, ["ends"] = { { ["x"] = 0.597, ["y"] = 0.437, ["mapID"] = 1698, ["npcID"] = 167210 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.597, ["y"] = 0.437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167210, ["questTurnInID"] = 167210, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 217, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60430] = { ["id"] = 60430, ["name"] = "A Call to Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60430 }, ["description"] = "The forces of Maldraxxus have long defended the Shadowlands from threats outside of our lands. Now, they face their greatest threats from within. The balance of power between the houses is broken. It has led them to assault us, and others. Their problems are many, our solutions are just. Travel to Maldraxxus and slay those that would do the Shadowlands harm, providing shelter to your allies when you find them.", ["objectivesText"] = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 173, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60431] = { ["id"] = 60431, ["name"] = "A Call to Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60431 }, ["description"] = "The forces of Maldraxxus were once intended to defend the Shadowlands against threats from beyond. They are all but broken, now. The houses are in disarray, infighting with one another. We have few allies there, and those that have sided with us are bruised and beaten. Go now, aid them, and slay their foes. Bring balance back to Maldraxxus, and in turn, will they aid us.", ["objectivesText"] = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.512, ["y"] = 0.378, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["ends"] = { { ["x"] = 0.512, ["y"] = 0.378, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.512, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 158653, ["questTurnInID"] = 158653, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 239, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60432] = { ["id"] = 60432, ["name"] = "Troubles at Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60432 }, ["description"] = "There are many tasks that need your attention outside of the walls of Sinfall. Our closest allies are under assault from all sides, and the forces of Denathrius are unrelenting. Take your weapon and steel yourself. Today, we defend Revendreth, and in doing so, further bulwark ourselves against our enemies. We will take back what is ours.", ["objectivesText"] = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: Have you reclaimed our homeland?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.518, ["y"] = 0.374, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["ends"] = { { ["x"] = 0.518, ["y"] = 0.374, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.518, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 158653, ["questTurnInID"] = 158653, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 240, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60433] = { ["id"] = 60433, ["name"] = "A Call to Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60433 }, ["description"] = "We fight not only for might and glory, but for the greater good of the Shadowlands. It is our calling to bring war upon those that would disrupt the flow of souls. There is one such betrayer - Sire Denathrius. Bring the vengeance of Maldraxxus down upon his foul crown. Slay his allies, serve his foes, end his reign in carnage.", ["objectivesText"] = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: How fares the battle for Revendreth?", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.596, ["y"] = 0.435, ["mapID"] = 1698, ["npcID"] = 167210 } }, ["ends"] = { { ["x"] = 0.596, ["y"] = 0.435, ["mapID"] = 1698, ["npcID"] = 167210 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.596, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167210, ["questTurnInID"] = 167210, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 218, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60434] = { ["id"] = 60434, ["name"] = "A Call to Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60434 }, ["description"] = "We all serve the greater purpose here, even those in Revendreth that we may not agree with. We take souls to them in need of a harsher form of cleansing, and it is just. Yet Sire Denathrius has gone too far, and now seeks to control all of the Shadowlands. We have friends there, amongst the Venthyr. Aid them, and put their enemies to rest. The Word of the Archon is with you.", ["objectivesText"] = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: Have you returned victorious?", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 174, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60435] = { ["id"] = 60435, ["name"] = "Challenges in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60435 }, ["description"] = "We never truly counted the forces of Denathrius as our allies, and now he has shown his true colors. Over many years, he has built an army. One capable of destroying any other land, provided we were divided, and not united. He has empowered monstrous creations and broken them to his will. What better way to secure our allies and test our strength, than to eliminate his most fervent champions. Go now, and hunt.", ["objectivesText"] = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: Have you thinned Denathrius's forces?", ["rewardItems"] = { 181557 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.371, ["y"] = 0.255, ["mapID"] = 1701, ["npcID"] = 167206 } }, ["ends"] = { { ["x"] = 0.371, ["y"] = 0.255, ["mapID"] = 1701, ["npcID"] = 167206 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.371, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167206, ["questTurnInID"] = 167206, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 200, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60436] = { ["id"] = 60436, ["name"] = "Challenges in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60436 }, ["description"] = "Maldraxxus is a land of conflict and strife. There is little better place than to test yourself against the might of the Shadowlands. There, you will find warriors that are bred on combat, honed by the sword and hammer, tested in arenas and battlegrounds. Crash into them like the felling of a great branch, let them see the might of Ardenweald is no less terrifying.", ["objectivesText"] = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Have you returned victorious?", ["rewardItems"] = { 181733 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.371, ["y"] = 0.255, ["mapID"] = 1701, ["npcID"] = 167206 } }, ["ends"] = { { ["x"] = 0.371, ["y"] = 0.255, ["mapID"] = 1701, ["npcID"] = 167206 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.371, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167206, ["questTurnInID"] = 167206, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 199, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60437] = { ["id"] = 60437, ["name"] = "Challenges in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60437 }, ["description"] = "Bastion has long been one of our closest allies, and a key to the inner workings of the Shadowlands. We cannot abide dysfunctions in the passage of souls. They are beset by a host of issues brought on by dissension in their ranks. Every day, doubt gnaws at their forces, bleeding away their hope, and plunging us further into chaos. Doubt is a powerful foe, and not easily dispatched. Keep your wits about you and crush these dark thoughts.", ["objectivesText"] = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Have you aided the denizens of Bastion?", ["rewardItems"] = { 181741 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.371, ["y"] = 0.255, ["mapID"] = 1701, ["npcID"] = 167206 } }, ["ends"] = { { ["x"] = 0.371, ["y"] = 0.255, ["mapID"] = 1701, ["npcID"] = 167206 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.371, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167206, ["questTurnInID"] = 167206, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 198, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60438] = { ["id"] = 60438, ["name"] = "Challenges in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60438 }, ["description"] = "The Wild Hunt count as our prey the most dangerous creatures in the weald. Here, you may test yourself against challenges the likes of which you may not have faced in your previous life. In our current state, my gravest concern is with Tirna Scithe. Once full of life, it is now overtaken by multitudes of foul creatures. They siphon its power, and though we may never regain the glade, we must not allow this to continue. Take on this trial, and put an end to the invaders of Tirna Scithe.", ["objectivesText"] = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: How goes the hunt?", ["rewardItems"] = { 181476 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.371, ["y"] = 0.255, ["mapID"] = 1701, ["npcID"] = 167206 } }, ["ends"] = { { ["x"] = 0.371, ["y"] = 0.255, ["mapID"] = 1701, ["npcID"] = 167206 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.371, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167206, ["questTurnInID"] = 167206, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 197, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60439] = { ["id"] = 60439, ["name"] = "Challenges in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60439 }, ["description"] = "Our close companions in Ardenweald face challenges unlike any that have previously plagued their peaceful glades. Ready your weapons, for now is the time that the golden shields of Bastion shine. Now is the time to take flight into the weald and show courage in the face of darkness. It is not always about us, you see. True courage means fighting for others when necessary, even against overwhelming odds and the most vile of evils. Light shines only in darkness.", ["objectivesText"] = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: Have you cleansed the weald?", ["rewardItems"] = { 181476 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.621, ["y"] = 0.376, ["mapID"] = 1707, ["npcID"] = 154627 } }, ["ends"] = { { ["x"] = 0.621, ["y"] = 0.376, ["mapID"] = 1707, ["npcID"] = 154627 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.621, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 154627, ["questTurnInID"] = 154627, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 175, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60440] = { ["id"] = 60440, ["name"] = "Challenges in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60440 }, ["description"] = "Looking to prove yourself? I hear there are powerful creatures invading Ardenweald. Sounds like a challenge, no? So ready your weapon and get out there! What better place to prove your might? Smash them to pieces, in the name of Maldraxxus!", ["objectivesText"] = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: Rip and tear!", ["rewardItems"] = { 181476 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.565, ["y"] = 0.44, ["mapID"] = 1698, ["npcID"] = 167208 } }, ["ends"] = { { ["x"] = 0.565, ["y"] = 0.44, ["mapID"] = 1698, ["npcID"] = 167208 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.565, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167208, ["questTurnInID"] = 167208, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 219, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60441] = { ["id"] = 60441, ["name"] = "Challenges in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60441 }, ["description"] = "Ardenweald was once a place of peace and regrowth, but no longer. Foes assault the weald from all sides, dark creatures that serve no masters. They will not be exempted from the hand of justice. We will bring the trials of Revendreth to bear upon them. They will see what we do to those that must be broken. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", ["objectivesText"] = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: Has justice been served?", ["rewardItems"] = { 181476 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 241, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60442] = { ["id"] = 60442, ["name"] = "Challenges in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60442 }, ["description"] = "Sometimes we need look no further than our own golden hills to find a suitable challenge. Doubt has crept into the minds of some of the most stoic shieldbearers of the Kyrian people. It has poisoned them against us, and in doing so, harmed the ability of the Shadowlands to heal from this blight. We must stand against them, now. It will not be easy, but things that are worth fighting for rarely are.", ["objectivesText"] = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Have you seen the face of doubt and shown it certainty?", ["rewardItems"] = { 181741 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.62, ["y"] = 0.374, ["mapID"] = 1707, ["npcID"] = 154627 } }, ["ends"] = { { ["x"] = 0.62, ["y"] = 0.374, ["mapID"] = 1707, ["npcID"] = 154627 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.62, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 154627, ["questTurnInID"] = 154627, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 176, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60443] = { ["id"] = 60443, ["name"] = "Challenges in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60443 }, ["description"] = "We consider the denizens of Bastion to be allies of a sort. Without their service, we would have no souls, and without souls, we could not raise armies, and without armies, we could not smash our fists against one another in the glorious theatre of battle! <Grandmaster Volo laughs and smashes his weapon around.> We must aid them against their foes, or else the arena will sit barren, and we can't have that! Find their greatest enemies and turn their bones into golden dust.", ["objectivesText"] = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Have you clipped their wings?", ["rewardItems"] = { 181741 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.565, ["y"] = 0.44, ["mapID"] = 1698, ["npcID"] = 167208 } }, ["ends"] = { { ["x"] = 0.565, ["y"] = 0.44, ["mapID"] = 1698, ["npcID"] = 167208 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.565, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167208, ["questTurnInID"] = 167208, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 220, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60444] = { ["id"] = 60444, ["name"] = "Challenges in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60444 }, ["description"] = "Our allies in Bastion have long served the cycle of the Shadowlands, delivering souls in need of our services. Yet, within their ranks, doubt has grown and festered. If this continues, we will all pay. Their loss of focus shall not be allowed to continue. We will punish their wandering hearts. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", ["objectivesText"] = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Has justice been served?", ["rewardItems"] = { 181741 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 242, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60445] = { ["id"] = 60445, ["name"] = "Challenges in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60445 }, ["description"] = "The purpose of Maldraxxus is to raise the most competent and confident warriors that the Shadowlands has ever seen, to create the perfect army in order to defend us against threats from the outer worlds. Here, you will find some of your greatest challenges. Seek out the champions of the strongest houses, stand against them, and let them see your might.", ["objectivesText"] = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Do you stand victorious?", ["rewardItems"] = { 181502, 181733, 183484 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.565, ["y"] = 0.44, ["mapID"] = 1698, ["npcID"] = 167208 } }, ["ends"] = { { ["x"] = 0.565, ["y"] = 0.44, ["mapID"] = 1698, ["npcID"] = 167208 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.565, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167208, ["questTurnInID"] = 167208, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 221, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60446] = { ["id"] = 60446, ["name"] = "Challenges in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60446 }, ["description"] = "Those of Maldraxxus are the chosen warriors of the Shadowlands, charged with defending us against threats from other worlds. For many years, a careful balance has been maintained between the houses. Now, there are those that have broken this balance, and we are all left weakened and defenseless. They must pay for these transgressions. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", ["objectivesText"] = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Has justice been served?", ["rewardItems"] = { 181733 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 243, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60447] = { ["id"] = 60447, ["name"] = "Challenges in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60447 }, ["description"] = "In Maldraxxus, the House of the Chosen have taken control of large swaths of land, upsetting the balance of power amongst the houses. To them flock the most seasoned gladiators and warriors. What better place to test yourself? Head into the land of bones and blood, and stand against their most powerful minions. Prove true what you know to be inside of yourself.", ["objectivesText"] = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Have you found the truth in courage?", ["rewardItems"] = { 181733 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.619, ["y"] = 0.374, ["mapID"] = 1707, ["npcID"] = 154627 } }, ["ends"] = { { ["x"] = 0.619, ["y"] = 0.374, ["mapID"] = 1707, ["npcID"] = 154627 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.619, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 154627, ["questTurnInID"] = 154627, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 177, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60448] = { ["id"] = 60448, ["name"] = "Challenges in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60448 }, ["description"] = "Those that have taken up arms against us in the name of Sire Denathrius and the Jailer have turned their backs on us all. Some are mere pawns in this game, others command them. Those that lead the charge of this crisis bear the greatest responsibility. They are the mightiest of Denathrius's allies, and they must be brought to justice. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", ["objectivesText"] = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: Has justice been served?", ["rewardItems"] = { 181557 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 244, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60449] = { ["id"] = 60449, ["name"] = "Challenges in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60449 }, ["description"] = "I've never really trusted the Venthyr of Revendreth. Maybe it's those long coats they wear, or maybe it's those pointy teeth, but something about them creeps me out. Their leader, Denathrius, has sided with the Jailer against the rest of us, so I guess I was right. I want you to find his most powerful allies in Revendreth and smash them to a bloody pulp. Send him a message from Maldraxxus.", ["objectivesText"] = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: You didn't let them bite you, right?", ["rewardItems"] = { 181557 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.565, ["y"] = 0.44, ["mapID"] = 1698, ["npcID"] = 167208 } }, ["ends"] = { { ["x"] = 0.565, ["y"] = 0.44, ["mapID"] = 1698, ["npcID"] = 167208 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.565, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167208, ["questTurnInID"] = 167208, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 222, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60450] = { ["id"] = 60450, ["name"] = "Challenges in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60450 }, ["description"] = "Challenging oneself is a necessary part of ascension, for what is courage in the face of normalcy? In this current state of unrest, opportunities abound to prove ourselves. Consider it the gilded lining to a tarnished shield. None more so than in Revendreth, where Sire Denathrius has consolidated power and influence, and seeks to overthrow the natural order of the Shadowlands. And here is where you must challenge yourself today.", ["objectivesText"] = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: Have you proven your worth in Revendreth?", ["rewardItems"] = { 181557 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.62, ["y"] = 0.373, ["mapID"] = 1707, ["npcID"] = 154627 } }, ["ends"] = { { ["x"] = 0.62, ["y"] = 0.373, ["mapID"] = 1707, ["npcID"] = 154627 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.62, ["y"] = 0.373 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 154627, ["questTurnInID"] = 154627, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 178, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60451] = { ["id"] = 60451, ["name"] = "Never Enough", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "Well done, recruit. These were merely the first of many assignments in your future. Matters here demand my attention. Report to Baroness Draka and see what need she has of you. I will watch closely as this war unfolds.", ["objectivesText"] = "Return to Baroness Draka .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157895, ["x"] = 0.362, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58351, 58617 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60452] = { ["id"] = 60452, ["name"] = "Storm the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60452 }, ["description"] = "Oh no, no no no. The Jailer's taken all the souls, and now he's also got a whole lot of anima! Who knows what he's going to do with it! You need to go back there! You're the Maw Walker! See what you can learn of his power, and slow him down however you can. I believe in you! Be careful, ok?", ["objectivesText"] = "Kill 3 rare or special encounter bosses in The Maw.", ["rewardXP"] = 6140, ["rewardItems"] = { 136350, 181476, 181557, 181733, 181741 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.339, ["y"] = 0.435, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["ends"] = { { ["x"] = 0.339, ["y"] = 0.435, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.339, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 158553, ["questTurnInID"] = 158553, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 262, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60453] = { ["id"] = 60453, ["name"] = "The Path to Glory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["series"] = { 60428 }, ["description"] = "It's been some time since I had a chance to craft a weapon that powerful! Good to know that the skills I learned from the Primus haven't dulled. You'd best get back to the baroness with that runeblade. I'm sure the margrave will want to know you wield it, as well. The Primus was notorious for thinking ten paces ahead of everyone else. I suspect he knew that someone like you would take up that blade.", ["objectivesText"] = "Return to Baroness Draka with your runeblade.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.418667, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60428 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60454] = { ["id"] = 60454, ["name"] = "Storm the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60454 }, ["description"] = "We have been able to do little to stem the flood of souls into the maw, until now. You, Maw Walker, have the power to put a stop to this. We know little about the Jailer's lands, save that he is powerful beyond imagining. I ask something of you today that I would not place upon anyone else. You must travel to his lands, and do what you can to slow the growth of his forces. We must buy more time.", ["objectivesText"] = "Kill 3 rare or special encounter bosses in The Maw.", ["rewardXP"] = 6140, ["rewardItems"] = { 136350, 181476, 181557, 181733, 181741 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 263, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60455] = { ["id"] = 60455, ["name"] = "Storm the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60455 }, ["description"] = "We cannot allow the Jailer to grow in power. You alone can take the battle to his lands, and you must do so, or we will all fall. Return to his lands, Maw Walker. He has already shown his hand, and we know he grows in power with each passing day. His forces must be slowed, make what progress you can.", ["objectivesText"] = "Kill 3 rare or special encounter bosses in The Maw. Progress: You seem different, somehow.", ["rewardXP"] = 6140, ["rewardItems"] = { 136350, 181476, 181557, 181733, 181741 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.432, ["y"] = 0.478, ["mapID"] = 1698, ["npcID"] = 167207 } }, ["ends"] = { { ["x"] = 0.432, ["y"] = 0.478, ["mapID"] = 1698, ["npcID"] = 167207 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.432, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167207, ["questTurnInID"] = 167207, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 265, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60456] = { ["id"] = 60456, ["name"] = "Storm the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60456 }, ["description"] = "We know little about the maw, Maw Walker. Only you have the power to traverse those lands and return. What I am about to ask of you I would not dare ask of another. We cannot allow the Jailer to grow in power. You must travel to the Maw and take the battle to his lands. Make what progress you can, we must slow down his forces however possible.", ["objectivesText"] = "Kill 3 rare or special encounter bosses in The Maw.", ["rewardXP"] = 6140, ["rewardItems"] = { 136350, 181476, 181557, 181733, 181741 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.454, ["y"] = 0.285, ["mapID"] = 1699, ["npcID"] = 164738 } }, ["ends"] = { { ["x"] = 0.454, ["y"] = 0.285, ["mapID"] = 1699, ["npcID"] = 164738 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.454, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 164738, ["questTurnInID"] = 164738, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 267, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60457] = { ["id"] = 60457, ["name"] = "Anima Salvage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60457 }, ["description"] = "So many souls that should have been nurtured here have been lost to the Maw, it pains me to think of it. Maw Walker, we ask you now to do that which we cannot. Traverse the Jailer's domain, walk his barren fields, climb his accursed tower. Bring us that which we lack.", ["objectivesText"] = "Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you recovered the Anima Embers ?", ["rewardItems"] = { 181372, 181475, 181556, 181732, 184561 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.339, ["y"] = 0.435, ["mapID"] = 1565, ["npcID"] = 158553 } }, ["ends"] = { { ["x"] = 0.339, ["y"] = 0.435, ["mapID"] = 1565, ["npcID"] = 158553 } }, ["coords"] = { ["mapID"] = 1565, ["x"] = 0.339, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 158553, ["questTurnInID"] = 158553, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 261, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60458] = { ["id"] = 60458, ["name"] = "Anima Salvage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60458 }, ["description"] = "When we ferried souls to the Arbiter, we never thought this would happen. We watched in despair as they were cast into the Maw, one by one, then by the hundreds and thousands. Souls that have been devoured, consumed, their anima lost to us. Return to us what you can.", ["objectivesText"] = "Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you secured the lost Anima Embers ?", ["rewardItems"] = { 181372, 181475, 181556, 181732, 184561 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 260, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60459] = { ["id"] = 60459, ["name"] = "Anima Salvage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60459 }, ["description"] = "The Arbiter has done us a great disservice. Our armies dwindle in number as souls are cast into the Maw instead of taking their place on the battlefields of Maldraxxus. The Undying Army must not be snuffed out. If the Shadowlands are to survive, we must be able to supply our troops. Travel now into the Maw, Maw Walker, and enter Torghast. Return with Anima Embers to help kindle our supplies.", ["objectivesText"] = "Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you brought Anima Embers for our stockpiles?", ["rewardItems"] = { 181372, 181475, 181556, 181732, 184561 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.432, ["y"] = 0.478, ["mapID"] = 1698, ["npcID"] = 167207 } }, ["ends"] = { { ["x"] = 0.432, ["y"] = 0.478, ["mapID"] = 1698, ["npcID"] = 167207 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.432, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167207, ["questTurnInID"] = 167207, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 264, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60460] = { ["id"] = 60460, ["name"] = "Anima Salvage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60460 }, ["description"] = "Revendreth is not a place that many souls choose to go, but it is a place that they must go. Here, their sins are laid bare before them, and they are broken and re-formed to function in our society. This is a necessary part of the cycle. Yet now, the cycle is broken, and are unable to serve our great purpose. In order for us to do our work we require Anima. Travel to Torghast, Maw Walker, gather that which we can not. Without it, we wither and fade.", ["objectivesText"] = "Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you brought the Anima Embers to us?", ["rewardItems"] = { 181372, 181475, 181556, 181732, 184561 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.454, ["y"] = 0.285, ["mapID"] = 1699, ["npcID"] = 164738 } }, ["ends"] = { { ["x"] = 0.454, ["y"] = 0.285, ["mapID"] = 1699, ["npcID"] = 164738 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.454, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 164738, ["questTurnInID"] = 164738, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 266, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60461] = { ["id"] = 60461, ["name"] = "Meet the Margrave", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "Word of the runeblade has reached Margrave Krexus . He wishes to see it for himself. With such a weapon by your side, you pose a threat that the other houses cannot ignore. Perhaps we can use that to our advantage. But enough talk. Follow me.", ["objectivesText"] = "Present your runeblade to Margrave Krexus .", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 174499, 178662, 178676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159065, ["x"] = 0.384, ["y"] = 0.660667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 158007, ["x"] = 0.379, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.660667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60453 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60462] = { ["id"] = 60462, ["name"] = "Anima Appeal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1702, ["storyline"] = { 60462 }, ["description"] = "Maw Walker! The Anima Reservoir is nearly depleted. Without more anima, the groves shall soon wither and die. Search the realms for additional nourishment and deliver it to the sanctum. Ardenweald cannot continue without your aid!", ["objectivesText"] = "Deposit 600 anima in the Anima Reservoir at the Heart of the Forest in Ardenweald.", ["starts"] = { { ["x"] = 0.489, ["y"] = 0.393, ["mapID"] = 1565, ["npcID"] = 167196 } }, ["ends"] = { { ["x"] = 0.489, ["y"] = 0.393, ["mapID"] = 1565, ["npcID"] = 167196 } }, ["coords"] = { ["mapID"] = 1565, ["x"] = 0.489, ["y"] = 0.393 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 167196, ["questTurnInID"] = 167196, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1702, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 201, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60463] = { ["id"] = 60463, ["name"] = "Anima Appeal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1700, ["storyline"] = { 60463 }, ["description"] = "Maw Walker! Our anima stores have run low, and soon we will have nothing to sate our thirst... Seek out additional sources of anima amongst the realms of the Shadowlands and deliver it to the sanctum. These are dire circumstances. Our fate is in your hands.", ["objectivesText"] = "Deposit 600 anima in the Anima Reservoir at Sinfall in Revendreth.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 245, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60464] = { ["id"] = 60464, ["name"] = "Anima Appeal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1698, ["storyline"] = { 60464 }, ["description"] = "Maw Walker! Our anima reserves are nearly depleted. Without an additional supply of anima, our mission of conquest will be lost! Scour the realms for all the anima you can gather and deliver it here to the sanctum. Victory depends on your success!", ["objectivesText"] = "Deposit 600 anima in the Anima Reservoir at Seat of the Primus in Maldraxxus.", ["starts"] = { { ["npcID"] = 167205 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 167205, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 223, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60465] = { ["id"] = 60465, ["name"] = "Anima Appeal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1707, ["storyline"] = { 60465 }, ["description"] = "Maw Walker! Our supply of anima is dwindling and the reservoir is nearly depleted. We must replenish our reserves before it is too late! Search the realms for all the anima you can gather and deliver it to the sanctum. Time is short. Move swiftly, <class>.", ["objectivesText"] = "Deposit 600 anima in the Anima Reservoir at Elysian Hold in Bastion.", ["starts"] = { { ["x"] = 0.64, ["y"] = 0.2, ["mapID"] = 1533, ["npcID"] = 158773 } }, ["ends"] = { { ["x"] = 0.64, ["y"] = 0.2, ["mapID"] = 1533, ["npcID"] = 158773 } }, ["coords"] = { ["mapID"] = 1533, ["x"] = 0.64, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 158773, ["questTurnInID"] = 158773, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 179, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60466] = { ["id"] = 60466, ["name"] = "The Old Ways", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60466, 62714, 62715 }, ["description"] = "You there! Might I ask your help? I must confess, with the lack of new souls arriving, our supplies have dwindled. We lack the means to clothe arrivals in proper kyrian attire. Before the forging of the centurions, aspirants trained against the native wildlife. Perhaps there is another way these beasts can prove useful. If you collect materials from the cloudstriders and larions nearby, we can use them to ensure our new arrivals look the part. Oh, and some thread from Mirene, if you would!", ["objectivesText"] = "Collect an Elysian Thread , 4 Cloudstrider Pelts , and 12 Larion Plumes . Progress: How goes the hunt?", ["rewardGold"] = 772200, ["rewardXP"] = 1770, ["rewardItems"] = { 173797, 178885, 178890, 178891, 245707, 245708, 245709, 245710 }, ["rewardChoices"] = { 173797 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160598, ["x"] = 0.478, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160598, ["x"] = 0.478, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57676, 57677 }, ["questLines"] = { { ["id"] = 1151, ["name"] = "An Act of Service", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60467] = { ["id"] = 60467, ["name"] = "A Rousing Aroma", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60467, 60468, 60469, 60470 }, ["description"] = "< Sabina is unresponsive. Her exposed flesh cracked and blistered. Perhaps something with a pungent aroma will rouse her.>", ["objectivesText"] = "Collect 4 Pungent Swarmer Toxin from Ravenous Swarms. Progress: Sabina remains unresponsive.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 178898, 178904 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168455, ["x"] = 0.35, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168455, ["x"] = 0.35, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1147, ["name"] = "Revelations of the Light", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60468] = { ["id"] = 60468, ["name"] = "Rubble Rummaging", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60467, 60468, 60469, 60470 }, ["description"] = "I do not know how long it's been since my captors left me here, but the Light has... taken its toll. You must help me escape. The key to my shackles should be hidden nearby. Perhaps among the rubble? That's likely where I'd hide something small.", ["objectivesText"] = "Find a Shackle Key among the rubble within Ashen Traverse. Progress: Have you found the key?", ["rewardGold"] = 425550, ["rewardXP"] = 1415, ["rewardItems"] = { 178898, 178904 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168455, ["x"] = 0.35, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168455, ["x"] = 0.35, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60467 }, ["questLines"] = { { ["id"] = 1147, ["name"] = "Revelations of the Light", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60469] = { ["id"] = 60469, ["name"] = "Safe in the Shadows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60467, 60468, 60469, 60470 }, ["description"] = "I cannot recollect what happened. Perhaps the Light has burdened my memory? Who knows how long I've been out here... The last thing I remember before things went dark... my companions and I had finally found refuge in the shadows. I worry for their well-being. So long as my assailants remain at large, my companions could be in danger. Will you find them and ensure they're still safe in the shadows?", ["objectivesText"] = "Find out what happened to Sabina 's companions.", ["rewardGold"] = 425550, ["rewardXP"] = 1415, ["rewardItems"] = { 178898, 178904 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168455, ["x"] = 0.35, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168455, ["x"] = 0.35, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 60467 }, ["questLines"] = { { ["id"] = 1147, ["name"] = "Revelations of the Light", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60470] = { ["id"] = 60470, ["name"] = "Setting Sabina Free", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60467, 60468, 60469, 60470 }, ["description"] = "Release me. Please, you must do so. I cannot linger in the Light any longer. This unease, it's so... familiar, but it will pass. I will feel myself once again, once I have returned to the shade. I'll stay as still as silence while you work the lock.", ["objectivesText"] = "Release Sabina from her shackles.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 178898, 178904 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168455, ["x"] = 0.35, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168455, ["x"] = 0.35, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 168455, ["questType"] = "standard", ["sourceQuests"] = { 60468, 60469 }, ["questLines"] = { { ["id"] = 1147, ["name"] = "Revelations of the Light", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60474] = { ["id"] = 60474, ["name"] = "Spawn Tracking Unit-Specified World Effect in a WMO Bug", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 4019, ["storyline"] = { 60474 }, ["description"] = "There seems to be a bug when you setup a world effect containing a gold dot on the minimap through Spawn Tracking that is set to Unit, rather than Objective. It seems to only happen with spawns inside WMOs. Might also be happening with setting it to Object as well. If the Spawn Tracking on the World Effect is set to Objective, everything's fine. However, if it is set to Unit, the golden dot will not show up on the minimap. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(60474)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(60474))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Attempt to figure out why the WMO spawned objective's minimap golden dot will not appear when its spawn tracking is set to Unit instead of Objective.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4019 } }, ["questType"] = "standard" },
