[60480] = { ["id"] = 60480, ["name"] = "The Endmire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60480 }, ["description"] = "Oi! You. Not sure what landed you in the Endmire but I need your help. See these torches? It's my gig to keep 'em lit. But it ain't like they runnin' on flint n' tinder. My stash of infused rubies got hauled off by some devourers when my back was turned. Can ya find 'em before we both get ate by one of these horrors?", ["objectivesText"] = "Find 5 Infused Rubies . Progress: Just going to be clear on this: I... HATE... THIS... GIG.", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 175751 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168618, ["x"] = 0.652, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168618, ["x"] = 0.652, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1143, ["name"] = "The Endmire", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60482] = { ["id"] = 60482, ["name"] = "See With My Eyes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60482 }, ["description"] = "After the destruction of our house, the spiders in this area become increasingly hostile. They expand their domain, and prey upon the few survivors that live here. There are weapons we could use to help protect ourselves, but they lie hidden within the Sightless Hold, webbed over by the weavers that inhabit it now. Journey to the hold, use my sightless vision to see the weapons and recover what you can.", ["objectivesText"] = "Collect 10 hidden weapons Progress: Have you recovered the weapons.", ["rewardGold"] = 238680, ["rewardXP"] = 8165, ["rewardItems"] = { 178992, 178993, 181501, 181502, 181503, 181507, 181625, 181626, 181638, 181645, 181646, 181647, 181648, 181649, 181651, 181662, 181664, 181665, 181666, 181671, 181672, 181674, 181679, 181680, 181681, 181682, 181686, 181689, 181690, 181695, 184305, 184772, 184773, 184774, 184775, 184776 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60487] = { ["id"] = 60487, ["name"] = "It Used to Be Quiet Here", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57919, 57920, 57921, 57922, 57923, 57924, 57925, 57926, 57927, 57928, 57929, 58092, 60127, 60128, 60487 }, ["description"] = "Well... You don't look like the rest of 'em, do you? < Chiselgrump shrugs.> Doesn't bother me. Keep my head down and do my job, making sure these sinstones stay in good shape. Keep breaking my tools, though. Bring me some more chisels and I'll teach you an old dredger construction trick.", ["objectivesText"] = "Collect 8 Dredger Chisels . Progress: Got those chisels yet?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 173695, 173696, 173697, 173733, 173735, 173737, 173738, 173739, 179002 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168698, ["x"] = 0.694667, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168698, ["x"] = 0.694667, ["y"] = 0.534667 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.694667, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57173 }, ["questLines"] = { { ["id"] = 1144, ["name"] = "The Final Atonement", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60489] = { ["id"] = 60489, ["name"] = "The Path of Ascension", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60489, 60493, 60494, 60495, 60496, 60497, 60498, 61473 }, ["description"] = "With the anima you collected, we can once again start up the Path of Ascension. The eternal training ground of the kyrian, the Path is an ancient tradition and favored amongst many of the kyrian, aspirant and ascended alike. The Hands of Courage, Apolon and Artemede, have stepped up to lead this tradition. Once you herald the Path's rebirth, speak to them to learn more.", ["objectivesText"] = "Activate the Path of Ascension.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 178995, 179008, 179009, 179010, 179378, 180472, 180477, 180478, 180579, 184811, 184812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1209, ["name"] = "The Path of Ascension", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[60491] = { ["id"] = 60491, ["name"] = "Among the Kyrian", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 60492, 63211 }, ["description"] = "You will be well at home among the kyrian, <brother/sister>. We welcome your aid. The Archon was so confident in this outcome that she has arranged a grand reception for you in honor of your efforts against the Maldraxxus incursion into our realm. For now, all you must do is journey to the Seat of Eternal Hymns. I shall meet you there.", ["objectivesText"] = "Meet Polemarch Adrestes at the Seat of Eternal Hymns in Bastion.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.361, ["y"] = 0.641, ["mapID"] = 1670, ["npcID"] = 171787 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168742, ["x"] = 0.5732, ["y"] = 0.3032 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5732, ["y"] = 0.3032 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10565 } }, ["questGiverID"] = 171787, ["questType"] = "standard", ["sourceQuests"] = { 57878, 62000, 63211 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60492] = { ["id"] = 60492, ["name"] = "A Proper Reception", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 60491, 63211 }, ["description"] = "Though the path you follow is not that of a traditional ascended, it is a kyrian path all the same. To follow it is to bask in the footsteps of the innumerable lives before us, forever in service to a good far greater than we can achieve alone. To join us amidst such strife is an accomplishment worthy of recognition. Our Archon has called all among us to join her in welcoming you to our ranks.", ["objectivesText"] = "Join the Kyrian Covenant. Progress: This is the final step of joining our ranks. Should you have second thoughts, have them now.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168742, ["x"] = 0.5732, ["y"] = 0.3032 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168906, ["x"] = 0.584, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.5732, ["y"] = 0.3032 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60491 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60493] = { ["id"] = 60493, ["name"] = "Humble Gatherer", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60489, 60493, 60494, 60495, 60496, 60497, 60498, 61473 }, ["series"] = { 60494, 60495 }, ["description"] = "Before your soulbinds step foot in the coliseum, you must challenge your first opponent. There is a tradition to this, as with all things. You will need to gather specific items, then bring them back here to fashion armaments to help execute your challenge. In the case of your first challenge, you will find the materials throughout Bastion. Return to me once you have collected everything, then we will continue.", ["objectivesText"] = "Collect 2 Depleted Goliath Cores from Forsworn goliaths, 6 Tampered Anima Chargers from Forsworn centurions, and 5 Soul Mirror Shards from Forsworn kyrian. Progress: Though the Path of Ascension leads to glory, participants must remember to stay humble and grounded in the tradition.", ["rewardXP"] = 8165, ["rewardItems"] = { 178995, 179008, 179009, 179010, 179378, 180472, 180477, 180478, 180579 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60489 }, ["questLines"] = { { ["id"] = 1209, ["name"] = "The Path of Ascension", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60494] = { ["id"] = 60494, ["name"] = "Your Friend, Dactylis", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60489, 60493, 60494, 60495, 60496, 60497, 60498, 61473 }, ["series"] = { 60493, 60495 }, ["description"] = "With the materials you gathered, you are now ready to craft your lure. Report to Dactylis. She will be able to help you craft not only this, but many more items of all kinds later. Once you craft your lure, return to me and I will give you your next instruction.", ["objectivesText"] = "Speak to Dactylis to craft 2 Overcharged Goliath Cores and 1 Soul Mirror . Progress: Inspired by the Collectors, we must take the time to craft by hand. Through crafting we practice patience, diligence, and humility.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 178995, 179008, 179009, 179010, 179378, 180472, 180477, 180478, 180579 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 60493 }, ["questLines"] = { { ["id"] = 1209, ["name"] = "The Path of Ascension", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60495] = { ["id"] = 60495, ["name"] = "A Suitable Opponent", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60489, 60493, 60494, 60495, 60496, 60497, 60498, 61473 }, ["series"] = { 60493, 60494 }, ["description"] = "The opponents you train against in the coliseum are not physical beings, but rather manifestations of such. Your first opponent is one you and your soulbinds have met numerous times before -- the Ascended Kalisthene. Asking another kyrian to be your opponent in the Path is a great honor, as it tells them that you have much to learn from them. Go to Aspirant's Awakening and use the cores to summon Kalisthene by calling back to your first introduction. It is as ceremony states.", ["objectivesText"] = "Use the Overcharged Goliath Cores on the Depleted Goliaths in Aspirant's Awakening, then use the Soul Mirror to capture a memory of Kalisthene.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178995, 179008, 179009, 179010, 179378, 180472, 180477, 180478, 180579, 181782 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60494 }, ["questLines"] = { { ["id"] = 1209, ["name"] = "The Path of Ascension", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60496] = { ["id"] = 60496, ["name"] = "Into the Coliseum", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60489, 60493, 60494, 60495, 60496, 60497, 60498, 61473 }, ["series"] = { 60497, 61473 }, ["description"] = "The time of your challenge has come! As you are not a being of Bastion, you shall act as a tactician for your soulbinds. You have developed mighty bonds between each other... let us see how they handle the coliseum. Let me know when you are ready to begin. Show us the merit of your bonds!", ["objectivesText"] = "Speak to Artemede to challenge the Path of Ascension. Progress: This is just the first of many challenges ahead of you, <name>. Remember to stay humble.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178995, 179008, 179009, 179010, 179378, 180472, 180477, 180478, 180481, 180579, 181499 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 60495 }, ["questLines"] = { { ["id"] = 1209, ["name"] = "The Path of Ascension", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60497] = { ["id"] = 60497, ["name"] = "Herald's Footpads", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60489, 60493, 60494, 60495, 60496, 60497, 60498, 61473 }, ["series"] = { 60496, 61473 }, ["description"] = "Sometimes, sheer force of will is not enough. A piece of equipment can save your life. This blueprint you found can teach you to craft your first piece of equipment. Bring it over to Dactylis . She will be able to aid you in this as well.", ["objectivesText"] = "Bring the Blueprint: Herald's Footpads to Dactylis . Progress: Welcome back. How may I aid you?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 178995, 179008, 179009, 179010, 179378, 180464, 180472, 180477, 180478, 180579 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 60496 }, ["questLines"] = { { ["id"] = 1209, ["name"] = "The Path of Ascension", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60498] = { ["id"] = 60498, ["name"] = "Overcoming the Trial", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60489, 60493, 60494, 60495, 60496, 60497, 60498, 61473 }, ["description"] = "These new footpads can give Pelagos the edge he may need to defeat Kalisthene . Return to the Path, <name>. Equip Pelagos with these footpads and overcome your opponent. It may take a few tries, but all trials do. Go in service, and in glory!", ["objectivesText"] = "Defeat Kalisthene in the Path of Ascension.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 178995, 179008, 179009, 179010, 179378, 180472, 180477, 180478, 180579 }, ["rewardCurrencies"] = { { ["id"] = 1819, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 61473 }, ["questLines"] = { { ["id"] = 1209, ["name"] = "The Path of Ascension", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[60500] = { ["id"] = 60500, ["name"] = "Halls of Atonement: Medallion of Pride", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 60500 }, ["description"] = "Our attempts at a parley were met with skepticism, at best. Acquiring the medallions may take more work than originally intended. However, not all hope is lost. I do believe that we can win over many of the Harvesters, and for those we cannot, a more direct approach will need to be taken. Lord Chamberlain falls into this latter category. His medallion must be taken by force.", ["objectivesText"] = "Recover the Medallion of Pride from Lord Chamberlain within the Halls of Atonement. Progress: Have you recovered the medallion?", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardItems"] = { 179024 }, ["rewardCurrencies"] = { { ["id"] = 1807, ["amount"] = 750 } }, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.308, ["mapID"] = 1699, ["objectID"] = 352520 } }, ["ends"] = { { ["x"] = 0.568, ["y"] = 0.308, ["mapID"] = 1699, ["objectID"] = 352520 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.568, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 59324, 62921 } },
[60501] = { ["id"] = 60501, ["name"] = "Redemption for the Redeemer", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60501 }, ["description"] = "<Energies of death and innervation struggle to free themselves from the blade and consume you to your very core.> <The bonds of warding placed on this blade by Prince Renathal will not hold for long. It should be taken to Sinfall where more permanent arrangements have been made for this prisoner.>", ["objectivesText"] = "Deliver Remornia to General Draven on the edge of Sinfall. Provided item:", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardItems"] = { 179358, 181552 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168893, ["x"] = 0.26, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "raid", ["startItems"] = { 179358 } },
[60502] = { ["id"] = 60502, ["name"] = "Sanguine Depths: An Ally Within", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12842, ["mapID"] = 1525, ["storyline"] = { 60502 }, ["description"] = "There are whispers of a prisoner within these depths that may be of use to our cause. Whether this information can be relied upon is unknown. It is just as likely to be a trap, but still, we must investigate. We cannot afford to ignore an opportunity such as this. Venture into the Sanguine Depths and recover this valuable prisoner.", ["objectivesText"] = "Recover the valuable prisoner from within the Sanguine Depths.", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardItems"] = { 181549 }, ["starts"] = { { ["npcID"] = 166689 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168893, ["x"] = 0.26, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 12842 } }, ["questGiverID"] = 166689, ["questType"] = "dungeon" },
[60504] = { ["id"] = 60504, ["name"] = "Strengthen the Bond", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "To bond souls is but the first step. You must now explore its potential. Just as Pelagos will gain strength from you, so too shall you grow from him. As your bond grows over time you will touch deeper into one another's souls, and so your strength shall increase. All you must do is place your hand upon the Forge of Bonds to augment your bond. There is no price to pay--the only limitation is your connection to our sacred covenant.", ["objectivesText"] = "Activate a Soulbind Power using the Forge of Bonds. Progress: This device is merely a pathway to the strength that lies within you both.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 180847, 181373, 181467, 181469, 181512, 181539, 181600, 181639, 181707, 181759, 181774, 181775, 181840, 181962, 181974, 182106, 182108, 182113, 182129, 182130, 182133, 182288, 182295, 182317, 182321, 182324, 182331, 182335, 182336, 182345, 182347, 182348, 182440, 182448, 182460, 182463, 182466, 182469, 182584, 182646, 182651, 182685, 182767, 182777, 182778, 182960, 182962, 182964, 183199, 183463, 183466, 183467, 183471, 183473, 183474, 183492, 183494, 183495, 183496, 183500, 199456, 199459, 199460 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57898 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1708 },
[60505] = { ["id"] = 60505, ["name"] = "Spider's Lair", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60505 }, ["description"] = "When our house fell in ruins, Manipulator Zalisar seized the opportunity to reform the house under his leadership. He found few followers and soon vanished into the ruins nearby. He has begun to manipulate the spiders and train them to be his soldiers. Spiders under his control have begun to prey upon our forces. We need to deal with this threat before it grows any worse. I need you eliminate Manipulator Zalisar and his spider forces.", ["objectivesText"] = "Slay 8 Razorweb Weavers and Manipulator Zalisar .", ["rewardGold"] = 257400, ["rewardItems"] = { 181501, 181502, 181638, 181645, 181646, 181647, 181648, 181649, 181650, 181656, 181658, 181671, 181672, 181673, 181674, 181679, 181681, 184305, 184772, 184773, 184774, 184775, 184776 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60506] = { ["id"] = 60506, ["name"] = "The Accuser", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 57098, 57131, 57136, 57159, 57164, 57189, 57190, 58916, 58941, 59014, 59209, 59256, 60313, 60506 }, ["description"] = "It is time to hunt our final prey, the Accuser . Anima drought or not, her sycophantic adherence to sacred \"rituals\" flies in the face of the Master's will. I can't wait to see the fear in her eyes.", ["objectivesText"] = "Hunt the Accuser .", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 175770, 178873, 178994 }, ["starts"] = { { ["npcID"] = 156499 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156554, ["x"] = 0.515, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questGiverID"] = 156499, ["questType"] = "standard", ["sourceQuests"] = { 57136, 57164 }, ["questLines"] = { { ["id"] = 996, ["name"] = "The Penitent Hunt", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 996, ["questLineOrder"] = 3 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 996, ["questLineOrder"] = 28 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60508] = { ["id"] = 60508, ["name"] = "On the Trail", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1543, ["storyline"] = { 59179, 59181, 59189, 59242, 59246, 60508, 60530 }, ["description"] = "In my visions, I witnessed Tyrande cutting through an endless storm of malevolent, nightmarish beings. Up ahead... is that...? Yes. I believe it is the very place I saw. Come. It may hold a clue as to where my mother has gone.", ["objectivesText"] = "Look for signs of Tyrande Whisperwind.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 35823, 35824, 35826, 35827, 35829, 35830, 65679, 65700, 65718, 82584, 82585, 82586, 82587, 82588, 87399, 88384, 121602, 121603, 121604, 121605, 129983, 130904, 131694, 141390 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 174833, ["x"] = 0.445, ["y"] = 0.411 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 168929, ["x"] = 0.301, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.411 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 59181 }, ["questLines"] = { { ["id"] = 1064, ["name"] = "Daughter of the Night Warrior", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1064, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60509] = { ["id"] = 60509, ["name"] = "Not My Job", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60509 }, ["series"] = { 57471 }, ["description"] = "Right. So, 'em devourers are going to start creepin' out of the Endmire soon. And with the anima drought puttin' the squeeze to the fangs... well... we ain't gettin' help from them until it's too late. Us dredgers could use someone in your line of work. Professional destroyer as it were. If you can spare the time, meet me out at the Dredgewood. We'll scoop up a couple of lads and see if we can't make a stand.", ["objectivesText"] = "Meet Rendle in the Dredgewood.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 25784, 25785, 32865, 32866, 32867, 32868, 33457, 33458, 33459, 33460, 33461, 33462, 35844, 35846, 35848, 59044, 59045, 59046, 59096, 59097, 59098, 90347, 90348, 90349, 90350, 90351, 90352, 90353, 90354, 90355, 118075, 118076, 118077, 118078, 131452, 131512, 171966, 208128, 208129, 225947, 233289, 233298 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 158057, ["x"] = 0.675, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 56942 }, ["nextQuests"] = { 57471, 62190 } },
[60510] = { ["id"] = 60510, ["name"] = "Descended", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["series"] = { 59916, 60043, 60050, 61770, 61771, 61773 }, ["description"] = "Though we have stopped the creation of more juggernauts, one of their most vile creations yet draws breath. It was born of one of the most pained souls they took from my temple in Bastion. As I flew above their ranks I could hear their surgeons chanting its name above the din of combat-- Woeblade . It is an affront to all the kyrian stand for, an atrocity beyond any other. Mark it with the flames of courage when you engage, and we will help you destroy it.", ["objectivesText"] = "Slay Woeblade the Atrocity.", ["rewardGold"] = 117300, ["rewardXP"] = 10205, ["rewardItems"] = { 174295, 177056, 178159, 179946 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59916, 60043, 61396 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60514] = { ["id"] = 60514, ["name"] = "Hunting Trophies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60514 }, ["description"] = "To be a hopebreaker is to conquer all prey, not just souls. The Banewood is home to many dangerous creatures: deathwalkers, fearspinners, and the horrifying doomfangs. If you wish to really master the art of the hunt, you should be able to defeat these foes. Bring me trophies as proof of your conquests. Then, you may just earn my respect.", ["objectivesText"] = "Collect 3 Doomfang Skulls , 3 Pristine Deathwalker Paws , and 3 Prized Fearspinner Fangs . Progress: Have you conquered the creatures of the Banewood?", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 178996, 178997, 179316 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156384, ["x"] = 0.485, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156384, ["x"] = 0.485, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59014 }, ["questLines"] = { { ["id"] = 1178, ["name"] = "Hunting Trophies", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60517] = { ["id"] = 60517, ["name"] = "The Toll of the Road", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60517 }, ["description"] = "This vessel appears to be brimming with anima. It is certainly tolls collected from denizens traveling by this crossroads. I am sure with all that is going on, Mistress Mihaela in Darkhaven would appreciate these tolls brought to her to cover the Village Ward's obligations.", ["objectivesText"] = "Return the tolls to Darkhaven. Provided item:", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 179363 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["startItems"] = { 179363 } },
[60519] = { ["id"] = 60519, ["name"] = "Audience with the Winter Queen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["series"] = { 60520, 60521, 60522, 60630, 60631, 60632 }, ["description"] = "Zephyrs herald the Queen's arrival. Hushed silence descends upon the grove. Wait, watch, and speak when the time has come.", ["objectivesText"] = "Speak to Moonberry and await the Winter Queen's arrival. Progress: The Queen shoulders so much because of this drought. But she is powerful, and I know we will make it through.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169031, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60724 }, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60520] = { ["id"] = 60520, ["name"] = "Nightmares Manifest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60520, 60521, 60522, 60628, 60629, 60630, 60631, 60632 }, ["series"] = { 60519, 60521, 60522, 60630, 60631, 60632 }, ["description"] = "Oh, this isn't good. As soon as you left, the spirit's nightmares spilled out all over Tirna Vaal. I've done everything to try to soothe her. I've tried singing to her, I've tried telling her stories, but nothing I do seems to calm her. Please, would you confront and dispel her nightmares? That might be the only thing that will work.", ["objectivesText"] = "Confront the wildseed's nightmares in Tirna Vaal. Progress: Her dreams are usually beautiful.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 180061 }, ["starts"] = { { ["x"] = 0.652, ["y"] = 0.366, ["mapID"] = 1565, ["npcID"] = 169142 } }, ["ends"] = { { ["x"] = 0.652, ["y"] = 0.366, ["mapID"] = 1565, ["npcID"] = 169142 } }, ["coords"] = { ["mapID"] = 1565, ["x"] = 0.652, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questGiverID"] = 169142, ["questTurnInID"] = 169142, ["questType"] = "standard", ["sourceQuests"] = { 60522 }, ["questLines"] = { { ["id"] = 1126, ["name"] = "Glitterfall Heights", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1126, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60521] = { ["id"] = 60521, ["name"] = "Call of the Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60520, 60521, 60522, 60628, 60629, 60630, 60631, 60632 }, ["series"] = { 60519, 60520, 60522, 60630, 60631, 60632 }, ["description"] = "You've done so much, but the Queen's focus is still divided across the forest. If you want to deliver your message, then we need to help lessen her burden. Let's start with the Wild Hunt. They are the protectors of Ardenweald , and dealing with the threat of the masked fae has stretched them thin. Seek out Hunt-Captain Korayn at Glitterfall Basin. Last I heard, her hunting party could use reinforcements. And don't let her ferocity put you off. She's quite nice as long as you're not her prey!", ["objectivesText"] = "Seek out Hunt-Captain Korayn in Glitterfall Basin.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 180061 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169031, ["x"] = 0.635, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169584, ["x"] = 0.512, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60519 }, ["questLines"] = { { ["id"] = 1126, ["name"] = "Glitterfall Heights", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1126, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60522] = { ["id"] = 60522, ["name"] = "Return to Tirna Vaal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60520, 60521, 60522, 60628, 60629, 60630, 60631, 60632 }, ["series"] = { 60519, 60520, 60521, 60630, 60631, 60632 }, ["description"] = "We of the Wild Hunt are always prepared to return to the cycle in defense of Ardenweald . I must move on, and so should you. I advise you to return to Droman Tashmur in Tirna Vaal. Others will need your help. Here, take this. It is a gift and a thank you. Helping each other is the only way to survive this drought.", ["objectivesText"] = "Return to Tirna Vaal.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 180061, 180207 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169935, ["x"] = 0.512, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169935, ["x"] = 0.512, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 169935, ["questType"] = "standard", ["sourceQuests"] = { 60632 }, ["questLines"] = { { ["id"] = 1126, ["name"] = "Glitterfall Heights", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1126, ["questLineOrder"] = 20 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1126, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60530] = { ["id"] = 60530, ["name"] = "The Sea of Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1543, ["storyline"] = { 59179, 59181, 59189, 59242, 59246, 60508, 60530 }, ["description"] = "Some force here seeks to keep us from finding Tyrande. The trail of bodies seems to go into this... stream of souls. I suggest we split up. I will follow along the bank of the river. You enter its current and follow the trail. Should you need me, I will be close at hand. We will find Tyrande, no matter where this course leads.", ["objectivesText"] = "Follow the trail of corpses to Tyrande Whisperwind.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 168929, ["x"] = 0.301, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 174834, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.301, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 60508 }, ["questLines"] = { { ["id"] = 1064, ["name"] = "Daughter of the Night Warrior", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1064, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
