[60545] = { ["id"] = 60545, ["name"] = "Shadowlands: A Chilling Summons", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 59751, 59752, 59753, 59754, 59755, 59756, 59757, 59758, 59759, 59760, 59761, 59762, 59765, 59766, 59767, 59770, 59776, 59907, 59914, 59915, 60545 }, ["description"] = "The time has come, <class>. Highlord Bolvar Fordragon requests your presence atop Icecrown Citadel. Meet me in Stormwind, and I will take you to him. I would not keep him waiting.", ["objectivesText"] = "Meet Darion Mograine outside Stormwind Keep.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 178495, 178553, 178558, 180050, 184313 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 176554, ["x"] = 0.765, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 176554, ["x"] = 0.765, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1637 } }, ["questTurnInID"] = 176554, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1108, ["name"] = "Through the Shattered Sky", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1267, ["name"] = "Maw Intro", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 125, ["title"] = "Shadowlands Campaign", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1108, ["questLineOrder"] = 0 }, { ["id"] = 160, ["title"] = "Catching Up!", ["questLineID"] = 1267, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2147, ["db2PoiUiMapID"] = 1360 },
[60557] = { ["id"] = 60557, ["name"] = "First Time? You Have to Fight!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "When it comes to warfare, strength of will is as critical as strength of arms. A demoralized soldier is a defeated soldier! We have the numbers to overwhelm the constructs with a full scale assault, but only if our forces are fully committed to the charge. Some may fall, but their sacrifice will secure our victory! Take this battle horn and rally our troops. Remind them of their duty to the Chosen!", ["objectivesText"] = "Rally 8 demoralized soldiers . Progress: Have you rallied the troops?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159894, ["x"] = 0.392, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 169226, ["x"] = 0.394, ["y"] = 0.466 }, { ["mapID"] = 1536, ["npcID"] = 169359, ["x"] = 0.394, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57912 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60563] = { ["id"] = 60563, ["name"] = "Tending to Wildseeds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "We infuse wildseeds with anima from the animacones we collect in the surrounding area. But the caretakers are missing, and we have wildseeds in need of an anima infusion. This is an absolute mess that must be corrected before the Winter Queen arrives! I've already gathered a basket of animacones . Can you use them to infuse a few of the wildseeds ? I'll show you how it's done, but then I have to look for the missing caretakers.", ["objectivesText"] = "Collect basket of animacones , then use them on 4 wildseeds .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176445, 179389, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169116, ["x"] = 0.642, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169202, ["x"] = 0.614, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57816 }, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
