[60566] = { ["id"] = 60566, ["name"] = "Into the Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["description"] = "I am afraid that you must endure the next stretch of the stroll without me, $p. While my compatriots and I have secured access to the elevator that shall carry us up to Sinfall, we are unable to utilize it. The Master has redirected a massive beam of Light directly onto the elevator's landing. Venthyr that get close are obliterated. Dredgers sent up never return. We need someone who can walk in the Light to discover what is happening up there. Lady Sybille will show you the way.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 158694, ["x"] = 0.32, ["y"] = 0.476, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 169105, ["x"] = 0.304, ["y"] = 0.456, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.32, ["y"] = 0.476, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57461 }, ["questLines"] = { { ["id"] = 998, ["name"] = "The Mad Duke", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 111, ["title"] = "The Master of Revendreth", ["questLineID"] = 998, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 998, ["questLineOrder"] = 29 } } },
[60567] = { ["id"] = 60567, ["name"] = "Shooing Wildlife", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "Things are chaotic here in the Tranquil Pools. I'd be devastated if the Winter Queen saw this. This is meant to be a peaceful place where we give anima to wildseeds. But with the current drought, starving beasts have encroached on the pools and are trying to feed on the anima themselves. Sadly, we need to put them down... or else they may endanger the spirits within the wildseeds.", ["objectivesText"] = "Slay 8 Anima-Starved wildlife. Progress: I hate having to do this, but if it's a choice between sparing the beasts and saving the wildseeds, I have to choose the wildseeds.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 176445, 179921, 179922, 179978 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169116, ["x"] = 0.642, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169202, ["x"] = 0.614, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57816 }, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60572] = { ["id"] = 60572, ["name"] = "For the Sake of Spirit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58589, 58590, 58591, 58592, 58593, 60572, 60578 }, ["description"] = "With all of the anima you recovered from Tirna Noch, it is only a matter of time before my grove becomes the target of every anima-seeking enemy of Ardenweald . I hope Dreamweaver knows what he is doing with this ritual. Proceed quickly. Speak with Dreamweaver , and see what needs to be done to aid the spirit within the wildseed.", ["objectivesText"] = "Speak with Dreamweaver to prepare the ritual.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160962, ["x"] = 0.6, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58524 }, ["questLines"] = { { ["id"] = 1027, ["name"] = "Visions of the Dreamer", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1027, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1027, ["questLineOrder"] = 23 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
