[60594] = { ["id"] = 60594, ["name"] = "One Special Spirit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57816, 57947, 57948, 57949, 57950, 57951, 60563, 60567, 60575, 60577, 60594 }, ["description"] = "You've been a huge help to Tirna Vaal. I need to bring this anima to one of our newest wildseeds. I'd love for you to come with me. It's only fair, since you're the one who recovered the animacones. I'm quite excited for you! Let's go.", ["objectivesText"] = "Go with Dreamweaver to feed anima to the wildseed in Tirna Vaal. Progress: The howling wind becomes a gentle breeze. All is well once again.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 176445, 179921, 179922, 179978, 179983 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169217, ["x"] = 0.622, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60575, 60577 }, ["questLines"] = { { ["id"] = 1008, ["name"] = "Aiding Tirna Vaal", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1008, ["questLineOrder"] = 1 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1008, ["questLineOrder"] = 17 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60597] = { ["id"] = 60597, ["name"] = "Trouble at the Gormling Corral", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60597 }, ["objectivesText"] = "Take the Modified Gormling Lure Deliver Gormdaughters to the wrangler", ["rewardXP"] = 8165, ["rewardItems"] = { 90177 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Take the Modified Gormling Lure", ["amount"] = 1, ["type"] = 2, ["objectID"] = 352833, ["orderIndex"] = 0 }, { ["text"] = "Deliver Gormdaughters to the wrangler", ["amount"] = 8, ["type"] = 0, ["objectID"] = 158887, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[60600] = { ["id"] = 60600, ["name"] = "Preparing for the Winter Queen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "Tirna Vaal is ready for the Winter Queen's arrival! And it's all thanks to you. You have more than upheld your end of our bargain... and yet I was not able to do the same. That is absolutely unacceptable for a faerie like me! What would the others think if they knew I had failed to honor our agreement? Please, allow me to make it up to you. I may not have been able to deliver your message to the Queen, but I have a special surprise that I hope you'll accept instead!", ["objectivesText"] = "Receive Ardenweald 's essence from Lady Moonberry . Progress: Joy follows Lady Moonberry , a scent that lingers as a flower blooms.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169031, ["x"] = 0.635, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57951, 60594 }, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
