[60660] = { ["id"] = 60660, ["name"] = "Flight Test", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60660 }, ["series"] = { 59262, 59263, 59311, 59348, 59351, 59865 }, ["description"] = "I fix these to my arms... then they become wings, yes? Then I jump off cliff. And fly! You watch?", ["objectivesText"] = "Observe Kowalskos ' test flight. Progress: Did you watch me?", ["rewardGold"] = 289575, ["rewardXP"] = 6125, ["rewardItems"] = { 175791, 175792, 175967, 175968, 176812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 164640, ["x"] = 0.427, ["y"] = 0.429 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.427, ["y"] = 0.429 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 59263 } },
[60661] = { ["id"] = 60661, ["name"] = "Dying Dreams", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58714, 58719, 58720, 58721, 58723, 58724, 58869, 60621, 60661 }, ["series"] = { 58721 }, ["description"] = "We have lost so much... and this one is special. <Moonberry looks at you, resolute. Her voice is strangely formal, her manner commanding.> Come, <name>. We will carry her on the Path of Rebirth and entreat the Queen to save her. Hurry and make preparations. We have little time.", ["objectivesText"] = "Take Ysera's wildseed to the Heart of the Forest.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 174864 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 161847, ["x"] = 0.6, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169869, ["x"] = 0.466, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58869 }, ["questLines"] = { { ["id"] = 1033, ["name"] = "Awaken the Dreamer", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1033, ["questLineOrder"] = 7 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1033, ["questLineOrder"] = 24 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60669] = { ["id"] = 60669, ["name"] = "Cause for Distraction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59876, 60113, 60116, 60117, 60670, 60725, 60759, 60761 }, ["description"] = "The Horde has come under siege, $p. The undead Scourge rises like a grim tide, in numbers not seen since Arthas Menethil sat upon the frozen throne. And as if that were not concerning enough... something terrible has occurred. What I am about to tell you, I share in the strictest confidence. This information will be known by all soon enough, but I needed to speak with you directly first. Allow me to explain.", ["objectivesText"] = "Speak with Lor'themar Theron atop Grommash Hold in Orgrimmar. Progress: There is much to discuss.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 169928, ["x"] = 0.488667, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169928, ["x"] = 0.488667, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.488667, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 60115 }, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[60670] = { ["id"] = 60670, ["name"] = "Return of the Crusade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59876, 60113, 60116, 60117, 60669, 60725, 60759, 60761 }, ["description"] = "I have witnessed the relentless advance of the Scourge firsthand. It is only a matter of time before they swarm our gates. The fate that befell Silvermoon must never be repeated. Death knights from the Ebon Blade have stepped forward to combat the threat, but even they will need reinforcements. The Argent Crusade has answered the call once more. I ask that you aid them in keeping our people safe, <name>. Their commander awaits your arrival.", ["objectivesText"] = "Speak with Commander Throgg in the Valley of Strength in Orgrimmar.", ["rewardGold"] = 23870, ["rewardXP"] = 850, ["rewardItems"] = { 33447 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 169928, ["x"] = 0.488667, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169878, ["x"] = 0.528, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.488667, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 60669 }, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[60671] = { ["id"] = 60671, ["name"] = "The Sacrifices We Must Make", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "Hurry! We can use the animacones we gathered to save Derawyn. I know they're intended for the wildseeds... but we can't let these monsters take anyone else from us.", ["objectivesText"] = "Use the recovered animacones to save Wagonmaster Derawyn .", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["npcID"] = 169868 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 169985, ["x"] = 0.662, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questGiverID"] = 169868, ["questType"] = "standard", ["sourceQuests"] = { 60647, 60648 }, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60673] = { ["id"] = 60673, ["name"] = "The Traitor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["description"] = "Right, looks like I should let you in now. Can't promise Mateo will be too kind though. I prefer my old boss, but don't tell him that. Wonder what happened to her. Denathrius seemed awfully upset when they last spoke. Anyways, let me just get that door open for ya.", ["objectivesText"] = "Kill Sinkeeper Mateo and collect his mirror shard. Progress: Do you have Mateo's mirror shard ?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 22980, 22982, 22984, 22995, 44358, 44359, 44360, 44361, 59171, 59172, 59173, 63912, 63913, 63914, 63915, 63916, 113232, 113233, 113234, 113235, 131466, 155462, 155471, 155479, 155487, 156941, 158599, 158600, 158601, 158602, 174092, 180900, 180913, 180914, 180915, 182251, 182260, 182269, 182278, 248065, 248069, 250355, 251330, 251548 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161298, ["x"] = 0.775, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160941, ["x"] = 0.726, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58421 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60709] = { ["id"] = 60709, ["name"] = "Recovering the Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "Darkness grasps the heart of Droman Krelnor, as he grasps the heart of the grove. Anima drains from the heart, nectar taken from ripened fruit. It must be stopped. Foul magic bars the way. Anima in peril, anima the salvation. Beseech Te'zan . An old soul, brimming with anima, the spark to ignite our hope.", ["objectivesText"] = "Speak with Te'zan to break down the droman's barrier, then confront Droman Krelnor.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 180126, 180172 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 169956, ["x"] = 0.662, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170012, ["x"] = 0.654, ["y"] = 0.266 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60671 }, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60721] = { ["id"] = 60721, ["name"] = "The Anima Must Flow", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 60721 }, ["series"] = { 63066 }, ["description"] = "This device you see here can be used to send anima to the thirsting wards, aiding our people. As each ward regains its flow of anima, it will begin to flourish. You may find those that live there ready to aid you in your journeys, or you may even find new challenges that await you. Once you have brought some anima to our sanctum, use the device to direct it to a ward, and see the results for yourself.", ["objectivesText"] = "Use the Anima Conductor to channel anima to a location in Revendreth.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.483, ["y"] = 0.563, ["mapID"] = 1700, ["npcID"] = 164739 } }, ["ends"] = { { ["x"] = 0.483, ["y"] = 0.563, ["mapID"] = 1700, ["npcID"] = 164739 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.483, ["y"] = 0.563 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 164739, ["questTurnInID"] = 164739, ["questType"] = "standard", ["sourceQuests"] = { 63066 } },
[60722] = { ["id"] = 60722, ["name"] = "Tower Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["storyline"] = { 60722 }, ["series"] = { 63057 }, ["description"] = "This device is used to channel anima to our towers across Maldraxxus, empowering our forces stationed at them. Though you may find the support they offer useful, bear in mind that the anima will likely attract the attention of our foes. Use the device to direct our stores of anima toward one of our towers. You will soon see what true power can accomplish.", ["objectivesText"] = "Use the Anima Conductor to channel anima to a location in Maldraxxus. Progress: The anima must flow!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 142342 }, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.36, ["mapID"] = 1698, ["npcID"] = 167205 } }, ["ends"] = { { ["x"] = 0.49, ["y"] = 0.36, ["mapID"] = 1698, ["npcID"] = 167205 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.49, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 167205, ["questTurnInID"] = 167205, ["questType"] = "standard", ["sourceQuests"] = { 63057 } },
[60723] = { ["id"] = 60723, ["name"] = "The Roots Thirst", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 60723 }, ["series"] = { 63067 }, ["description"] = "This device can soak the roots of our great canopy in anima. The branches thirst for it. As each of the great trunks is filled with anima, it will begin to bloom once more. You may find those under its boughs ready to aid you, or you may find new challenges that await you in the shade. Now, bring anima to the sanctum, and use the device to direct it out into the weald. Let the blooms flourish once more.", ["objectivesText"] = "Use the Anima Conductor to channel anima to a location in Ardenweald. Progress: The leaves shake in anticipation.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.637, ["mapID"] = 1702, ["npcID"] = 167196 } }, ["ends"] = { { ["x"] = 0.501, ["y"] = 0.637, ["mapID"] = 1702, ["npcID"] = 167196 } }, ["coords"] = { ["mapID"] = 1702, ["x"] = 0.501, ["y"] = 0.637 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167196, ["questTurnInID"] = 167196, ["questType"] = "standard", ["sourceQuests"] = { 63067 } },
[60724] = { ["id"] = 60724, ["name"] = "Heartless", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60519, 60600, 60624, 60637, 60638, 60639, 60647, 60648, 60671, 60709, 60724 }, ["description"] = "So many of my friends have returned to the cycle... all because of those strange masks. Why did they take my friends? What was the point of destroying the heart of my grove? You have to return to Tirna Vaal and tell Droman Tashmur what happened here. I'll make my way there eventually. I just... need some time to say goodbye.", ["objectivesText"] = "Return to Droman Tashmur in Tirna Vaal.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 175648, 175649, 175650, 175651, 180126, 180172 }, ["rewardChoices"] = { 175650, 175649, 175648, 175651 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170012, ["x"] = 0.654, ["y"] = 0.266 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158487, ["x"] = 0.635, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60709 }, ["questLines"] = { { ["id"] = 1125, ["name"] = "Waning Grove", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1125, ["questLineOrder"] = 2 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1125, ["questLineOrder"] = 19 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60725] = { ["id"] = 60725, ["name"] = "Field Reports", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59876, 60113, 60116, 60117, 60669, 60670, 60759, 60761 }, ["description"] = "We cannot anticipate where and when the Scourge will strike. In order to mount a defense, the Argent Crusade has set up outposts at several key locations. But we have yet to receive word from them. Seek out my field officers along the southern road. I expect a full report when you return.", ["objectivesText"] = "Gather reports from officers in Durotar and the Barrens. Progress: Reinforcements? Thank the Light!", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["rewardItems"] = { 180231, 180232, 180233 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 169878, ["x"] = 0.528, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 170084, ["x"] = 0.494, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 10, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 60670 }, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10 },
[60727] = { ["id"] = 60727, ["name"] = "A Message from Icecrown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59877, 60169 }, ["description"] = "Our forces in Northrend have sent word. Justicar Trueheart requests our immediate assistance. We must respond to this summons at once, no matter what terrors await us in Icecrown. A <class> like you would do much to bolster our chances on the battlefield. You have my word that Orgrimmar will be protected in your absence. Battle calls, <name>. I trust you are ready.", ["objectivesText"] = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["rewardItems"] = { 46874 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 169878, ["x"] = 0.528, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 85, 118 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 60761 }, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[60732] = { ["id"] = 60732, ["name"] = "Disrupting the Flow", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60732 }, ["description"] = "<The tortured embodiment of the soul before you burns with magmatic flame. Whatever purpose it was meant for here in the cauldron has since been served. The complete disregard for the remaining husk of this soul is unsettling. These efforts will continue if something isn't done. Send the inhabitants of Zovaal's Cauldron a message.>", ["objectivesText"] = "Disrupt the Mawsworn's efforts in Zovaal's Cauldron.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 177698, 177699, 178874, 178877, 178880, 178881, 178882, 178883 }, ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 400 }, { ["id"] = 1880, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 176164, ["x"] = 0.394, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60733] = { ["id"] = 60733, ["name"] = "Front and Center", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57912, 57976, 57979, 57982, 57983, 57984, 57985, 57986, 57987, 57993, 57994, 58268, 59616, 60557, 60733 }, ["description"] = "The runes on that blade... they are the same as the ones etched on the door to the Seat of the Primus. And one of them just began to glow... Is this what I think it is, $p? Do you have the means to unseal the Seat? If so, then perhaps Vyraz's gambit was not for nothing. This could turn the tide of the entire war!", ["objectivesText"] = "Empower the Rune of Might at the Seat of the Primus. Progress: Come! Victory awaits!", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 176456, 179923, 180120 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 170094, ["x"] = 0.376, ["y"] = 0.29 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.29 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57994 }, ["questLines"] = { { ["id"] = 1060, ["name"] = "House of Constructs", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1060, ["questLineOrder"] = 12 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1060, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60735] = { ["id"] = 60735, ["name"] = "Trouble in Paradise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57102, 57261, 57584, 57676, 57677, 59773, 59774, 60735 }, ["series"] = { 57261, 57584 }, ["description"] = "I have given your presence here some thought, <name>. It is clear to me that you are no ordinary arrival from Oribos. I do not know why you are here, nor what you hope to achieve. That alone is simply unprecedented. You must understand... individuals do not merely come to Bastion on a whim. This fate is earned, and those that are chosen for it are uniquely suited to this existence. So... I ask you... why are you here, truly?", ["objectivesText"] = "Answer Kleia 's question. Progress: < Kalisthene peers down at you.> What is it, mortal?", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 165107, ["x"] = 0.461333, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166306, ["x"] = 0.422, ["y"] = 0.782 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.461333, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57584 }, ["questLines"] = { { ["id"] = 1001, ["name"] = "Eternity's Call", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1001, ["questLineOrder"] = 0 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1001, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60736] = { ["id"] = 60736, ["name"] = "Quest 02", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60736 }, ["objectivesText"] = "Open the door to the Seat of the Primus.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 6797, 6798, 61487, 61488, 61489, 81787, 81788, 81789, 81790, 81791, 81792, 81793, 81794, 81795, 94219, 94220, 95622, 95623 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60737] = { ["id"] = 60737, ["name"] = "The Door to the Unknown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 59011, 59206, 60737, 61715, 61716 }, ["description"] = "You empowered the final rune? Then we might yet turn the tide of battle! Open the door, <name>! We'll hold the enemy back as long as we can!", ["objectivesText"] = "Open the door to the Seat of the Primus.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 170309, ["x"] = 0.504, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 170309, ["x"] = 0.504, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 170309, ["questType"] = "standard", ["sourceQuests"] = { 59011 }, ["questLines"] = { { ["id"] = 1063, ["name"] = "The Empty Throne", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1063, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60738] = { ["id"] = 60738, ["name"] = "The Way to Hibernal Hollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60738, 60764, 60839, 60856, 60881, 60901, 60905 }, ["description"] = "I've never seen a wildseed quite like this one. Even the ones that bonded with their caretakers in the past never manifested nightmares like this. Then again, we've also never had a living mortal in our midst. We need to bring this wildseed to Hibernal Hollow. There it can receive the care and attention it needs. I'll place it into the spirit cradle. Can you ask Niya if she would accompany you? The poor sylvar has been directionless since the fall of her grove. This would be good for her.", ["objectivesText"] = "Recruit Niya to help you bring the wildseed to Hibernal Hollow.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.652, ["y"] = 0.366, ["mapID"] = 1565, ["npcID"] = 169142 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170171, ["x"] = 0.645, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questGiverID"] = 169142, ["questType"] = "standard", ["sourceQuests"] = { 60520 }, ["questLines"] = { { ["id"] = 1127, ["name"] = "This Is the Way", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1127, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60739] = { ["id"] = 60739, ["name"] = "Tough Crowd", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60739 }, ["rewardXP"] = 8165, ["rewardItems"] = { 158149, 187244 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 8, ["objectID"] = 170080 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[60759] = { ["id"] = 60759, ["name"] = "Damned Intruders", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59876, 60113, 60116, 60117, 60669, 60670, 60725, 60761 }, ["description"] = "It is imperative that these reports reach Commander Throgg, but we are hard-pressed to defend the Crossroads. Before you depart, I ask that you aid us in thinning the Scourge's numbers. It may grant us the reprieve we need.", ["objectivesText"] = "Kill 6 Cultists and 4 Bloodthirsty Ghouls at the Crossroads. Progress: In troubled times, the Light guides our path.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 170084, ["x"] = 0.494, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 170084, ["x"] = 0.494, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["sourceQuests"] = { 60725 }, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10 },
[60761] = { ["id"] = 60761, ["name"] = "Return of the Scourge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 60115, 60669, 60670, 60725, 60727, 60759, 60761 }, ["series"] = { 59876, 60113, 60116, 60117, 60669, 60670, 60725, 60759 }, ["description"] = "Deliver these reports to Commander Throgg . He must be told of the full extent of the threat we face. If we fail to hold the line against the Scourge... then Light help us all.", ["objectivesText"] = "Bring Lieutenant Althera 's report to Commander Throgg in the Valley of Strength in Orgrimmar. Provided item:", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["rewardItems"] = { 180269 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 170084, ["x"] = 0.494, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169878, ["x"] = 0.528, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 10, 85 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["sourceQuests"] = { 60759 }, ["questLines"] = { { ["id"] = 1129, ["name"] = "An Uncertain Fate", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[60762] = { ["id"] = 60762, ["name"] = "Death Motes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60762 }, ["description"] = "I have a task for you, Maw Walker. Souls deemed suitable for service among the Mawsworn are broken down to their barest essence. The resulting creature forms a black shade, devoid of all individual will. It is a tragic end. I wish to better understand this process--what is it about a soul that causes this transformation? Fragments of broken souls rain down across Ruin's Cradle. Bring me some of them, so that I might learn more about our common adversaries.", ["objectivesText"] = "Collect 10 Death Motes from Ruin's Cradle in The Maw .", ["rewardItems"] = { 177698, 178874, 178880, 178881, 178882, 178883, 185717 }, ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 400 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60763] = { ["id"] = 60763, ["name"] = "I Moustache You to Lend a Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["series"] = { 60338, 60341, 60778 }, ["description"] = "A message from the Primus of Maldraxxus, you say? We haven't heard from him in... Well, it's been a long time. This isn't a prank, is it? The Queen doesn't have time for pranks. But I do! <Moonberry leans in close and whispers to you.> And for this one, I think we need one more lily. <Moonberry winks.> Let me take a look at this message. You bring that last night lily to Featherlight, and then we'll talk.", ["objectivesText"] = "Assist Moonberry and Featherlight.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 178747 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 168341, ["x"] = 0.682, ["y"] = 0.184 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 157788, ["x"] = 0.65, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60338 }, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60764] = { ["id"] = 60764, ["name"] = "Soothing Song", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60738, 60764, 60839, 60856, 60881, 60901, 60905 }, ["description"] = "I will fly ahead to Hibernal Hollow and convince the Droman Aliothe to help us. Hopefully she will have agreed by the time you and Niya arrive. This wildseed seems to take comfort in your presence, so you'll need to stick close to it. Niya will also need to sing to the wildseed to keep it calm... or else the nightmares may return. Spriggans love to interrupt our songs, so be on the lookout for them. Let me know when you're ready to head off.", ["objectivesText"] = "Travel with Niya to take the wildseed to Hibernal Hollow. Progress: How strange that such a small wildseed could cause so much trouble...", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170172, ["x"] = 0.645, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170290, ["x"] = 0.624, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60738 }, ["questLines"] = { { ["id"] = 1127, ["name"] = "This Is the Way", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1127, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60765] = { ["id"] = 60765, ["name"] = "Cure For All Ills", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60765 }, ["description"] = "Many survivors from the House of Plagues are still in need help. Their suffering fills me with great sadness. Maw Walker, I'd do anything to help them. Even saving a few is better than saving none. Please, help me cure them!", ["objectivesText"] = "Use Roseboil 's Regenerative Molt to cure 15 Plague-ridden Survivors .", ["rewardXP"] = 8165, ["rewardItems"] = { 178680, 182487, 182496, 182505, 182514, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 159241, ["x"] = 0.55, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57605 } },
[60766] = { ["id"] = 60766, ["name"] = "Damned Intruders", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 59876, 59877, 60113, 60116, 60117, 60766, 60767 }, ["series"] = { 60767 }, ["description"] = "Before you depart... we are in desperate need of reinforcements. These reports must reach Commander Gregor. But if you would help us thin the Scourge's numbers first, it would grant us a much needed reprieve.", ["objectivesText"] = "Kill 12 Scourge in the area. Progress: In troubled times, the Light guides our path.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 166184, ["x"] = 0.735, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 166184, ["x"] = 0.735, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["sourceQuests"] = { 59876 }, ["questLines"] = { { ["id"] = 1128, ["name"] = "An Uncertain Fate", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 47 },
