[60825] = { ["id"] = 60825, ["name"] = "Amateur Spies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60825 }, ["objectivesText"] = "Progress: Your court is infested with spies, Maw Walker. Necromancers from Maldraxxus, amateurs hoping to ambush me while my guard is down. I will dispatch any that I come across, but I would prefer to focus my attentions on the court. Bring me the heads of shrouded necromancers to prove you have some competence in counterintelligence.", ["rewardItems"] = { 180296 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168444, ["x"] = 0.512, ["y"] = 0.466667 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168444, ["x"] = 0.512, ["y"] = 0.466667 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.466667 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[60827] = { ["id"] = 60827, ["name"] = "Advancing the Effort", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60871, 60932, 62157, 62185, 62225 }, ["series"] = { 62157 }, ["description"] = "While the other crusaders regain control of the tournament grounds, you and I must press on. Our forces previously attempted to set up a forward camp farther into Icecrown, but they were overrun. With you by our side, I am confident we can reclaim the area.", ["objectivesText"] = "Secure a foothold atop the Ironwall Rampart in Icecrown. Progress: There is no stopping what has begun. We must continue our efforts.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 62157 }, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[60828] = { ["id"] = 60828, ["name"] = "A New Foothold", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60871, 60932, 62157, 62185, 62225 }, ["description"] = "Our preparations are complete. It is time we take the fight to the Scourge. Justicar Trueheart has tasked me with leading our efforts at the forward camp. Meet me there and we shall continue our work together.", ["objectivesText"] = "Meet Crusader Renn at the Argent Camp atop the Ironwall Rampart in Icecrown.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168123, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 62157, 62162, 62163 }, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[60831] = { ["id"] = 60831, ["name"] = "Fit For a Margrave", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58011, 58016, 58027, 58031, 58036, 58045, 59130, 59223, 59231, 60831 }, ["series"] = { 58031, 58036, 58045, 59223, 59231 }, ["description"] = "We're finally ready, my apprentice. We shall craft our greatest potion! Though what the potion is meant for escapes me, I'm simply so proud of your progress. Margrave Stradama will be thrilled by your achievements! Come, now. Let's present what we've made to her!", ["objectivesText"] = "Present your potion to Margrave Stradama. Progress: Go on, apprentice!", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 173368, 173536, 173891, 175410, 175722, 175723, 180235, 180236, 180237, 180238, 180271 }, ["rewardChoices"] = { 175722, 175723 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159930, ["x"] = 0.5876, ["y"] = 0.6868 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.5876, ["y"] = 0.6868 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59223 }, ["questLines"] = { { ["id"] = 1061, ["name"] = "House of Plagues", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1061, ["questLineOrder"] = 13 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1061, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60837] = { ["id"] = 60837, ["name"] = "Wrath of Aliothe", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60837 }, ["objectivesText"] = "Garden of Night cleansed Spriggan slain", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Garden of Night cleansed", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Spriggan slain", ["amount"] = 25, ["type"] = 0, ["objectID"] = 170440, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[60839] = { ["id"] = 60839, ["name"] = "Remnants of the Wild Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60738, 60764, 60839, 60856, 60881, 60901, 60905 }, ["description"] = "The Wild Hunt is holding the line against these monsters, lest they overrun the road to Hibernal Hollow. Too many of my fellow hunters have been possessed by the dark magic of those twisted masks. But with you here, we might be able to turn the tide. Aid any hunters you can find before our foes turn them against us. I will meet you farther within the meadow. If we rally our numbers, we can bring an end to this battle.", ["objectivesText"] = "Rescue 5 Wounded Defenders from Soryn's Meadow.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170290, ["x"] = 0.624, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170485, ["x"] = 0.642, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60764 }, ["questLines"] = { { ["id"] = 1127, ["name"] = "This Is the Way", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1127, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
