[60856] = { ["id"] = 60856, ["name"] = "Toppling the Brute", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60738, 60764, 60839, 60856, 60881, 60901, 60905 }, ["description"] = "A nearby monstrosity has been thwarting our efforts to clear the meadow. Together, we can bring it down. You and I will face off against the beast. When the time is right, I will call for the hunt to charge. The Wild Hunt has suffered too many losses. Today we will claim victory against these monsters!", ["objectivesText"] = "Defeat the Blighted Beast .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175983, 175984, 175985, 175986, 175987, 175988, 175989, 175990, 175992, 178029 }, ["rewardChoices"] = { 175986, 175983, 175984, 175985, 175990, 175987, 175988, 175989, 175992, 178029 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170485, ["x"] = 0.642, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170485, ["x"] = 0.642, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60839 }, ["questLines"] = { { ["id"] = 1127, ["name"] = "This Is the Way", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1127, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60857] = { ["id"] = 60857, ["name"] = "We Can't Save Them All", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["description"] = "I am surprised--but pleased--that you weren't torn to pieces! Well done. But now... I fear we have a far more serious task to complete. The Winter Queen has decreed that Heartwood Grove's anima is to be reclaimed, and its denizens must leave it to wither. Not all of their wildseeds will go with them. In fact, only a few have been chosen to be saved. We are to bring the final list to Droman Krelnor .", ["objectivesText"] = "Bring the list of saved wildseeds to Droman Krelnor at the Heartwood Grove. Progress: Move along, stranger.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 180436 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170324, ["x"] = 0.676, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 168528, ["x"] = 0.678, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60778 }, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60858] = { ["id"] = 60858, ["name"] = "Flight School: Up and Away!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60858 }, ["objectivesText"] = "Updraft entered Temple summit reached", ["rewardXP"] = 8165, ["rewardItems"] = { 109076, 118938, 152550, 166544 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Updraft entered", ["amount"] = 1, ["type"] = 0, ["objectID"] = 170566, ["orderIndex"] = 0 }, { ["text"] = "Temple summit reached", ["amount"] = 1, ["type"] = 0, ["objectID"] = 170565, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[60859] = { ["id"] = 60859, ["name"] = "Souls of the Forest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 57787, 60338, 60341, 60763, 60778, 60857, 60859 }, ["series"] = { 57787 }, ["description"] = "If you're standing in for Lady Moonberry, then maybe you can help! Wagonmaster Derawyn was escorting a bunch of us to a new grove when we were attacked by a pack of hungry predators! The wolf be a fast soulshape, so I got away... but some of the little ones weren't so lucky. They're being hunted like prey! Come on! They're just down the road!", ["objectivesText"] = "Rescue souls in peril. Progress: Well, that was exciting.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175652, 175653, 175654, 175655 }, ["rewardChoices"] = { 175654, 175652, 175653, 175655 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170537, ["x"] = 0.667333, ["y"] = 0.261333 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170533, ["x"] = 0.667, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.667333, ["y"] = 0.261333 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60857 }, ["questLines"] = { { ["id"] = 1002, ["name"] = "Welcome to Ardenweald", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1002, ["questLineOrder"] = 16 }, { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1002, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60861] = { ["id"] = 60861, ["name"] = "Secrets in Shadows", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60871, 60932, 62157, 62185, 62225 }, ["series"] = { 60843, 60867, 60932, 62185, 62225 }, ["description"] = "Though we have been monitoring the cultist presence at Mord'rethar, we have not yet discovered what mysteries lie within its chambers. Take these robes. Make your way into the inner sanctum and see what you can discover. This may be our only chance to learn their intentions, <name>.", ["objectivesText"] = "Use the Collaborator's Robes in Mord'rethar to discover what secrets lie within. Progress: Find something?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 60843, 62185 }, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[60867] = { ["id"] = 60867, ["name"] = "A Message from Above", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60871, 60932, 62157, 62185, 62225 }, ["series"] = { 60843, 60861, 60932, 62185, 62225 }, ["description"] = "This is troubling news, $p. Whoever this \"Banished One\" may be, it is clear he is behind the Scourge's return. That the undead are amassing in great numbers outside Icecrown Citadel cannot be a coincidence. Lead our hippogryph riders in surveying the area from above. Determine if the dark herald you saw is among them, and then clear a path for reinforcements. Let us hope she possesses the answers we seek.", ["objectivesText"] = "Discover the location of Herald Dalora. Destroy the Scourge forces surrounding Icecrown Citadel. Progress: The skies over the citadel may be dangerous, but we need to know what we're up against.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 62225 }, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[60869] = { ["id"] = 60869, ["name"] = "With Hope in Hand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60932, 62157, 62185, 62225 }, ["description"] = "You must bring word of what we have uncovered back to Orgrimmar. One of our mages can open a portal for you at the tournament grounds. As for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use. May the Light protect you, <name>.", ["objectivesText"] = "Establish a portal to Orgrimmar at the Argent Tournament Grounds. Deliver the news to Lor'themar Theron atop Grommash Hold in Orgrimmar.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169928, ["x"] = 0.488667, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 85, 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 60932 }, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[60871] = { ["id"] = 60871, ["name"] = "With Hope in Hand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60169, 60827, 60828, 60843, 60861, 60867, 60871, 60932, 62157, 62185, 62225 }, ["description"] = "You must bring word of what we have uncovered back to Stormwind. One of our mages can open a portal for you at the tournament grounds. As for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use. May the Light protect you, <name>.", ["objectivesText"] = "Establish a portal to Stormwind at the Argent Tournament Grounds. Deliver the news to Genn Greymane at Lion's Rest in Stormwind City.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 167329, ["x"] = 0.395, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 84, 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 60932 }, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
