[60881] = { ["id"] = 60881, ["name"] = "Ride of the Wild Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60738, 60764, 60839, 60856, 60881, 60901, 60905 }, ["description"] = "Thanks to your efforts, we have turned the tide of battle. We won't soon forget your aid. We should be able to hold Soryn's Meadow, now that this brute is dead. Ride with us, <name>. Let us return to the road and your wildseed.", ["objectivesText"] = "Ride with the Wild Hunt to Niya and the wildseed.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170485, ["x"] = 0.642, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170290, ["x"] = 0.624, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60856 }, ["questLines"] = { { ["id"] = 1127, ["name"] = "This Is the Way", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1127, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60886] = { ["id"] = 60886, ["name"] = "The Seat of the Primus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57514, 57516, 58351, 58616, 58617, 58618, 58726, 60428, 60451, 60453, 60461, 60886 }, ["description"] = "This cannot be a coincidence. It is clear that your runeblade is somehow connected to the Seat of the Primus. I will not pretend to know the Primus's agenda. But I would not be surprised if he left behind a way for the worthy to open the door to his sanctum. Draka will bring you to the Seat of the Primus. If you hold the key, mortal, then our victory is all but assured.", ["objectivesText"] = "Go with Draka to the Seat of the Primus. Progress: What is it?", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 174499, 178662, 178676, 180818, 180819, 180820, 180821, 180822, 180823, 180824, 180825, 180826 }, ["rewardChoices"] = { 180826, 180818, 180824, 180825, 180823, 180819, 180820, 180822, 180821 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158007, ["x"] = 0.379, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168381, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.379, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60461 }, ["questLines"] = { { ["id"] = 1058, ["name"] = "House of the Chosen", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1058, ["questLineOrder"] = 10 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1058, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60887] = { ["id"] = 60887, ["name"] = "Cataclysm: Onward to Adventure in Kalimdor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27718, 27721, 27722, 28557, 28717, 60887 }, ["description"] = "There are people across Azeroth that could use your help, <name>. They come from different walks of life, but are all working towards finding their place on this beautiful world. Examine the Warchief's Command Board and see where your adventure awaits!", ["objectivesText"] = "Find the Warchief's Command Board in Orgrimmar. Progress: I cannot wait to hear your stories someday.", ["starts"] = { { ["x"] = 0.408, ["y"] = 0.799, ["mapID"] = 85, ["npcID"] = 167032 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 172387, ["x"] = 0.493333, ["y"] = 0.765333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.493333, ["y"] = 0.765333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questGiverID"] = 167032, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5580, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[60889] = { ["id"] = 60889, ["name"] = "Favor: She Had a Stone Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60889 }, ["description"] = "This item will be of great interest to the brokers. Per your previous deal with The Night Market, you should bring it to Ta'xera . You will be fairly compensated.", ["objectivesText"] = "Bring the She Had a Stone Hearth poem to Ta'xera at The Night Market in Revendreth . Provided item:", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["rewardItems"] = { 180453, 184373, 184374 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 160081, ["x"] = 0.524, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 58062 }, ["startItems"] = { 180453 } },
