[60900] = { ["id"] = 60900, ["name"] = "Archival Protection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58619, 58620, 58621, 58622, 58623, 59917, 59994, 60900 }, ["description"] = "The rarest volumes are kept at the top of this tower, protected by an entity called the Archivist . This stoic guardian is incorruptible. Intractable. Completely uninterested in striking a fair bargain! Its utter lack of business acumen is really quite upsetting. Ah, well. I fear we have no choice but to dispatch this impediment. Shall we?", ["objectivesText"] = "Defeat the Archivist .", ["rewardGold"] = 386100, ["rewardXP"] = 1415, ["rewardItems"] = { 174377, 178020, 182732 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 170667, ["x"] = 0.418, ["y"] = 0.235 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 170667, ["x"] = 0.418, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 170667, ["questType"] = "standard", ["sourceQuests"] = { 58622 }, ["questLines"] = { { ["id"] = 1157, ["name"] = "Archival Protection", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60901] = { ["id"] = 60901, ["name"] = "Passage to Hibernal Hollow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60738, 60764, 60839, 60856, 60881, 60901, 60905 }, ["description"] = "You have done the Wild Hunt a great service. I must repay you in some way. The battle for Soryn's Meadow has turned. With the brute defeated, the Blighted forces lose their strength. Allow us to escort you to Hibernal Hollow. Speak to me whenever you wish to depart.", ["objectivesText"] = "Speak with Ara'lon to receive an escort to Hibernal Hollow.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170290, ["x"] = 0.624, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60881 }, ["questLines"] = { { ["id"] = 1127, ["name"] = "This Is the Way", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 124, ["title"] = "The Groves of Ardenweald", ["questLineID"] = 1127, ["questLineOrder"] = 4 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1127, ["questLineOrder"] = 21 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
