[60916] = { ["id"] = 60916, ["name"] = "RSVP: Stonehead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["description"] = "Hi, best bud! Me no go party. Stonehead shakes his head vigorously.> Got to stay for job!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178686 }, ["starts"] = { { ["npcID"] = 157199, ["x"] = 0.39, ["y"] = 0.66, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 157199, ["x"] = 0.39, ["y"] = 0.66, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.39, ["y"] = 0.66, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
