[60928] = { ["id"] = 60928, ["name"] = "Blackthorn Captives", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "These disguises will allow us to explore the grove undetected, but beware of the overseers. Their Drust magic will more than likely be able to pierce through our deception. We need to save the rest of my hunting party while we still can.", ["objectivesText"] = "Locate the missing hunters in Blackthorn Grove. Progress: The Drust have taken so much from us...", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180523 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170705, ["x"] = 0.4296, ["y"] = 0.4572 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170705, ["x"] = 0.4296, ["y"] = 0.4572 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4296, ["y"] = 0.4572 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 170705, ["questType"] = "standard", ["sourceQuests"] = { 60910 }, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
