[60930] = { ["id"] = 60930, ["name"] = "Lower Your Standards", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60930 }, ["objectivesText"] = "Progress: < Picky Stefan leans in close and whispers.> Maw Walker, we are running low on refreshments! Thankfully, you chose to serve such a humble ... \"delicacy\" that we can find more just about anywhere. As you find fungus around the Ember Court, bring them to me and I shall have the dredgers sneak it onto the empty platters.", ["rewardItems"] = { 180470 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165500, ["x"] = 0.358923, ["y"] = 0.590615 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165500, ["x"] = 0.358923, ["y"] = 0.590615 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.358923, ["y"] = 0.590615 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[60932] = { ["id"] = 60932, ["name"] = "Only Shadows Remain", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 60003, 60004, 60169, 60827, 60828, 60843, 60861, 60867, 60869, 60871, 60932, 62157, 62185, 62225 }, ["series"] = { 60843, 60861, 60867, 62185, 62225 }, ["description"] = "We may not know who this dark herald serves, but it is clear that the message she brings has emboldened the Scourge and the Cult of the Damned alike. This cannot be allowed to continue. We must vanquish her and strike a definitive blow against her master's new minions. Lead the charge, $p. The Argent Crusade stands with you. Light willing, we will put an end to this madness here and now.", ["objectivesText"] = "Defeat Herald Dalora in the Cathedral of Darkness. Progress: May we continue our fight together.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 60867 }, ["questLines"] = { { ["id"] = 1130, ["name"] = "Return of the Scourge", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[60934] = { ["id"] = 60934, ["name"] = "Report to Lord Herne", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "I will do whatever it takes to save Gweyir from the Drust's curse. Lord Herne must be informed of what befell my hunting party. Deliver my report to him while I escort Gweyir back to the Heart of the Forest. Gweyir was under my leadership during the ambush... she is my responsibility. I will make sure she gets home safely.", ["objectivesText"] = "Deliver Ara'lon's report to Lord Herne . Progress: Did you find the lost hunting party?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 175603, 179772, 179894, 180606, 181916 }, ["rewardChoices"] = { 175603, 179772, 181916, 179894 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170705, ["x"] = 0.4296, ["y"] = 0.4572 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170848, ["x"] = 0.462, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4296, ["y"] = 0.4572 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60928 }, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[60935] = { ["id"] = 60935, ["name"] = "Medallion of Avarice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 58325, 58326, 58337, 58372, 58421, 58424, 58428, 58440, 58444, 58842, 60673, 60935 }, ["series"] = { 58842 }, ["description"] = "The Medallion of Avarice was the tool of the Curator. With its power it granted her authority over the Catacombs Ward. Combined with her knowledge of the vast library of sinstones Revendreth has accumulated over the ages, the Curator was a master of her craft. When Denathrius defeated my first rebellion, he tossed both myself and the Curator into the Maw. The Curator was clever, though, and she hid the medallion before Denathrius could act. Come, let us speak of plans.", ["objectivesText"] = "Speak with Prince Renathal .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.549, ["y"] = 0.309, ["mapID"] = 1699, ["objectID"] = 353949 } }, ["ends"] = { { ["x"] = 0.549, ["y"] = 0.309, ["mapID"] = 1699, ["objectID"] = 353949 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.549, ["y"] = 0.309 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["sourceQuests"] = { 57893 }, ["questLines"] = { { ["id"] = 1024, ["name"] = "Avarice", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1024, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
[60945] = { ["id"] = 60945, ["name"] = "Deep Echo Trident", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60945 }, ["description"] = "<The trident glistens in the sunlight. This should give your soulbinds the ability to interrupt their foes in the Path of Ascension.>", ["objectivesText"] = "Bring the Deep Echo Trident to Paolone .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardCurrencies"] = { { ["id"] = 1819, ["amount"] = 2 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171816, ["x"] = 0.628, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60946 }, ["startItems"] = { 181499 } },
[60946] = { ["id"] = 60946, ["name"] = "Blueprint: Deep Echo Trident", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60946 }, ["description"] = "<You have discovered plans for a trident that may give your soulbinds an edge in the Path of Ascension. Dactylis should be able to help you with crafting this piece of equipment.>", ["objectivesText"] = "Bring the Blueprint: Deep Echo Trident to Dactylis . Provided item:", ["rewardItems"] = { 178995, 179008, 179009, 179010, 179378, 180472, 180477, 180478, 180579 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 180472 } },
[60947] = { ["id"] = 60947, ["name"] = "Blueprint: Charm of Fortitude", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60947 }, ["description"] = "<You have discovered plans for a charm that seems to fortify your soulbinds in the Path of Ascension. Dactylis should be able to help you with crafting this charm.>", ["objectivesText"] = "Bring the Blueprint: Charm of Fortitude to Dactylis . Provided item:", ["rewardItems"] = { 180482 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 180482 } },
[60948] = { ["id"] = 60948, ["name"] = "RSVP: The Countess", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60948 }, ["description"] = "The Prince wishes to host court? Well, that should be interesting... I am sure you understand that one musn't give without receiving something of value in return. It sets a terrible precedent, provides unrealistic expectations, and encourages beggars. So you shall do something for me. House Briarbane is very proud of their new mascot. They have been flaunting it in the streets and irritating the other houses. Steal it for me, but incriminate one of the other houses in the act.", ["objectivesText"] = "Disguise yourself as a member of House Iremoore and steal the House Briarbane mascot. Progress: It would be a shame to waste such a fine mascot on such an unworthy house.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176114, 180497 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 171106, ["x"] = 0.58, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 171106, ["x"] = 0.58, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60950] = { ["id"] = 60950, ["name"] = "A Matter of Stealth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60950 }, ["objectivesText"] = "Obtain Disguise from Amberfoot Fallen Sylvar Enraged", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Obtain Disguise from Amberfoot", ["amount"] = 1, ["type"] = 0, ["objectID"] = 170928, ["orderIndex"] = 0 }, { ["text"] = "Fallen Sylvar Enraged", ["amount"] = 6, ["type"] = 0, ["objectID"] = 170791, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[60955] = { ["id"] = 60955, ["name"] = "Noko's Flute", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60955 }, ["objectivesText"] = "Progress: < Noko breathes in slowly.> The stage manager says he cannot find my flute anywhere. The last time this happened, one of the rowdy roadies had run off with it. You can find those troublesome dredgers causing trouble around the party. Retrieve my flute from them and I will play for your guests.", ["rewardItems"] = { 180484, 180485, 180486 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 170874, ["x"] = 0.5355, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 170874, ["x"] = 0.5355, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5355, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[60957] = { ["id"] = 60957, ["name"] = "Ansel's Lucky Violin", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60957 }, ["objectivesText"] = "Progress: < Lucky Ansel reluctantly breaks gaze with his sinstone.> My burdens are still far too heavy. I will never be free of the Maw's dangers while even a single sin remains on this stone. Luckily, my exceptional music warrants praise from my venthyr controllers, and I am assured that aiding Prince Renathal's court is a worthwhile endeavor. Retrieve my violin from the band supplies over near the dancers and I will begin my public penance.", ["rewardItems"] = { 180484, 180485, 180486 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 170881, ["x"] = 0.5352, ["y"] = 0.3684 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 170881, ["x"] = 0.5352, ["y"] = 0.3684 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5352, ["y"] = 0.3684 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
