[60960] = { ["id"] = 60960, ["name"] = "Chiu's Lute", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60960 }, ["objectivesText"] = "Progress: I am nervous, <name>. Music lays bare my soul for all to see. And while this sinstone reminds all of the darkness within me, I hope that my music will expose the light that also dwells within. Lord Garridan at your embassy agreed. He as most kind and enjoyed the music I played for him when I first arrived. I must've left my lute with him. Please retrieve it for me while I continue my pre-show meditation.", ["rewardItems"] = { 180484, 180485, 180486 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 170878, ["x"] = 0.5336, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 170878, ["x"] = 0.5336, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5336, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
