[60972] = { ["id"] = 60972, ["name"] = "The Hunt for the Baron", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1960, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["series"] = { 59897, 59959, 59960, 59962, 59966, 59973, 59974 }, ["description"] = "<The amulet Bolvar gave you flickers with a faint red light, then grows dim. To be useful in finding Darion Mograine, you must find a way to restore its potency. You recall an area called Zovaal's Cauldron that was teeming with dark magic. Perhaps the amulet's power could be restored there.>", ["objectivesText"] = "Charge the Amulet of the Horsemen.", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 178018, 181174 }, ["starts"] = { { ["x"] = 0.449, ["y"] = 0.409, ["mapID"] = 1543 } }, ["ends"] = { { ["x"] = 0.449, ["y"] = 0.409, ["mapID"] = 1543 } }, ["coords"] = { ["mapID"] = 1543, ["x"] = 0.449, ["y"] = 0.409 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 59897 }, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960 },
