[60993] = { ["id"] = 60993, ["name"] = "Citadel of Loyalty", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "The medallions, the source of magic the crown focuses, are still bent to the will of Denathrius. Forge cannot solve this. Citadel of Loyalty can. Taken over by the Forsworn in recent times. If we can get the crown to the temple, we can break the loyalty to the medallion's former master.", ["objectivesText"] = "Meet Mikanikos at the Citadel of Loyalty.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160280, ["x"] = 0.502, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171001, ["x"] = 0.227, ["y"] = 0.263 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 58656 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60994] = { ["id"] = 60994, ["name"] = "Lowering Their Defenses", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "We can alter the crown to expunge Denathrius's corruption in the medallions. Problem, Forsworn have set large barrier protecting the temple. Only there can Denathrius's influence be truly broken. Drain the anima from the barrier's sources that power it. Barrier will disappear.", ["objectivesText"] = "Drain the anima from the Forsworn Barrier Sources.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171001, ["x"] = 0.227, ["y"] = 0.263 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171001, ["x"] = 0.227, ["y"] = 0.263 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.227, ["y"] = 0.263 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60993 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60995] = { ["id"] = 60995, ["name"] = "Disloyalty", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "There are many enemies of Bastion here. If we thin their numbers, it will further mend the tension between our realms. Show no remorse. I will take to the skies to support from above. I will be able to provide ground support when needed.", ["objectivesText"] = "Kill 15 Forsworn in the Citadel of Loyalty.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 170999, ["x"] = 0.244, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171001, ["x"] = 0.227, ["y"] = 0.263 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60993 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[60996] = { ["id"] = 60996, ["name"] = "Face Your Fears", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["description"] = "The temple is now accessible. We must go now to aid Mikanikos in breaking the Sire's influence on the crown. Prepare yourself. Denathrius's magic has always been potent and destructive. This won't be easy.", ["objectivesText"] = "Speak to General Draven to go to the Temple of Loyalty. Then, aid Mikanikos in purifying the Crown of the Harvesters .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 180605 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171147, ["x"] = 0.230444, ["y"] = 0.252222 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171175, ["x"] = 0.232, ["y"] = 0.256333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.230444, ["y"] = 0.252222 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60994, 60995 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[61050] = { ["id"] = 61050, ["name"] = "How to Wear Seven Medallions", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 58530, 58555, 58584, 58585, 58586, 58600, 58603, 58630, 58656, 59233, 60993, 60994, 60995, 60996, 61050 }, ["series"] = { 58530 }, ["description"] = "One venthyr cannot wear seven medallions and command the power they bestow, nor command respect from anyone looking at them. What I propose is the crafting of an artifact that can contain the power of the medallions. Focusing that power to one wielder. Unfortunately, Revendreth lacks the craftsmanship needed to channel such powers. Not without turning the wearer into a puppet of Denathrius. No, for this, we must employ the aid of a realm that specializes in service. Draven has the details.", ["objectivesText"] = "Speak with General Draven .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.513, ["y"] = 0.38, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["ends"] = { { ["x"] = 0.513, ["y"] = 0.38, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.513, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 158653, ["questTurnInID"] = 158653, ["questType"] = "standard", ["sourceQuests"] = { 58444 }, ["questLines"] = { { ["id"] = 1026, ["name"] = "The Crowned Prince", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1026, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
[61051] = { ["id"] = 61051, ["name"] = "The Absent-Minded Artisan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58022, 58023, 58024, 58025, 58026, 61051 }, ["series"] = { 57818, 57824, 57825, 57952 }, ["description"] = "Of all the foolhardy, misguided, exasperating... < Guardian Kota snorts and stomps a hoof.> But standing here does Sha'lor no good. We must find him and bring him back safely. Come, meet me at the Autumnal Rise. We can survey the burrows below and see if there is any sign that he lives.", ["objectivesText"] = "Search for Master Sha'lor on the Autumnal Rise.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 172953, 172955, 173268, 173534, 180543 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158921, ["x"] = 0.626, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171099, ["x"] = 0.628, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 57825 }, ["questLines"] = { { ["id"] = 1161, ["name"] = "When a Gorm Eats a God", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61057] = { ["id"] = 61057, ["name"] = "By Trials Forged", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 61057 }, ["description"] = "You have shown strength, cunning and compassion since your arrival in Ardenweald. These are the values the greatest hunters possess. It has been a privilege to fight by your side, <name>. It would be my honor to continue, as your Soulbind.", ["objectivesText"] = "Complete the soulbinding ritual with Korayn. Progress: Together we are stronger!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.474, ["mapID"] = 1701, ["npcID"] = 165659 } }, ["ends"] = { { ["x"] = 0.352, ["y"] = 0.474, ["mapID"] = 1701, ["npcID"] = 165659 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.352, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 165659, ["questTurnInID"] = 165659, ["questType"] = "standard", ["sourceQuests"] = { 60108, 62900 } },
[61058] = { ["id"] = 61058, ["name"] = "Bound in Dreams", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 61058 }, ["description"] = "I knew you were something special when Ysera's wildseed reacted to you. Without you, she would have been lost! It would have been a tragedy not just for Ardenweald, but your world as well! Since then, I have seen you take on many more tasks to help others in need. With your help, Ardenweald grows stronger. I would be honored to help you continue the good work you have been doing, and to become your soulbind.", ["objectivesText"] = "Complete the soulbinding ritual with Dreamweaver . Progress: I am humbled by the care you have shown for others.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.337, ["y"] = 0.476, ["mapID"] = 1701, ["npcID"] = 160482 } }, ["ends"] = { { ["x"] = 0.337, ["y"] = 0.476, ["mapID"] = 1701, ["npcID"] = 160482 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.337, ["y"] = 0.476 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 160482, ["questTurnInID"] = 160482, ["questType"] = "standard", ["sourceQuests"] = { 59242, 62900 } },
[61059] = { ["id"] = 61059, ["name"] = "RSVP: Rendle and Cudgelface", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 61059 }, ["description"] = "I heard about the prince wanting Rendle and me at 'is court. I aim to please 'im an all, but Rendle says 'e haven't got proper ah-tire. Says 'e needs a sootible hat, maybe somethin' posh that hints at 'is inner depths. He says the only good hats are: Red Noggin Candle, or one a them Fae Revel Masques. Or mebbe a Pink Party Hat, or a fancy Crown o' the Righteous.", ["objectivesText"] = "\"Sootible\" hats may be crafted by players who have the recipe and appropriate tradeskill.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 10290, 171286, 171287, 171829, 173058, 173059, 173108, 173109, 173110, 173202, 176118, 177061, 177062, 180751, 180752, 180755, 180760, 183950, 183953, 183954 }, ["starts"] = { { ["x"] = 0.619, ["y"] = 0.77, ["mapID"] = 1700, ["npcID"] = 171190 } }, ["ends"] = { { ["x"] = 0.619, ["y"] = 0.77, ["mapID"] = 1700, ["npcID"] = 171190 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.619, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 171190, ["questTurnInID"] = 171190, ["questType"] = "standard", ["sourceQuests"] = { 61943 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700 },
