[61061] = { ["id"] = 61061, ["name"] = "Ulfar's Guidance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["series"] = { 61076, 61102 }, ["description"] = "There is one who may know how to dispel the curse from Gweyir. In the mountains of Drustvar lives Ulfar , an ancient Thornspeaker who sided with the humans of Kul Tiras against his fellow Drust. Journey to his den and ask for his wisdom. He may hold the answers you seek. Lord Herne and I will tend to Gweyir once she arrives with Ara'lon.", ["objectivesText"] = "Speak with Ulfar at Ulfar 's Den in Drustvar.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171138, ["x"] = 0.46, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 141159, ["x"] = 0.452, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 896, 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["sourceQuests"] = { 60934 }, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896 },
