[61096] = { ["id"] = 61096, ["name"] = "The Arbiter's Will", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1671, ["storyline"] = { 57386, 57390, 57425, 57511, 57512, 57515, 60020, 60021, 60179, 60181, 61096, 61107 }, ["series"] = { 60055, 60056 }, ["description"] = "We will all suffer if Bastion and Maldraxxus fall into war. For some time, the Necrolords have been isolated. You must travel to their realm and seek the truth of their incursion. Though our anima reserves remain low, they will be enough to open the way for you.", ["objectivesText"] = "Meet Kah-Sher in the Ring of Transference in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.389, ["y"] = 0.699, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.389, ["y"] = 0.699, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.389, ["y"] = 0.699 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 60056 }, ["questLines"] = { { ["id"] = 1057, ["name"] = "Champion of Pain", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1133, ["name"] = "Tidings of War", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1057, ["questLineOrder"] = 9 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1057, ["questLineOrder"] = 0 }, { ["id"] = 114, ["title"] = "Bastion", ["questLineID"] = 1133, ["questLineOrder"] = 6 }, { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1133, ["questLineOrder"] = 8 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1133, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, [