[61097] = { ["id"] = 61097, ["name"] = "Supplies from The Ascended", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61097 }, ["description"] = "The Ascended would like to thank you for your efforts in aiding Bastion . Please accept a gift in recognition of your service to our cause and our people.", ["objectivesText"] = "Speak with Adjutant Nikos in Hero's Rest in Bastion .", ["rewardItems"] = { 180647 }, ["starts"] = { { ["x"] = 0.522, ["y"] = 0.47, ["mapID"] = 1533, ["npcID"] = 160470 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160470, ["x"] = 0.522, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questGiverID"] = 160470, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2441, ["threshold"] = 10000 } } } },
[61098] = { ["id"] = 61098, ["name"] = "Supplies from The Wild Hunt", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61098 }, ["description"] = "The Wild Hunt thanks you for your efforts in aiding Ardenweald . Take these gifts as recognition for your aid. May they help you in whatever trials may come.", ["objectivesText"] = "Speak with Aithlyn at the Heart of the Forest in Ardenweald .", ["rewardItems"] = { 180649 }, ["starts"] = { { ["x"] = 0.484, ["y"] = 0.504, ["mapID"] = 1565, ["npcID"] = 158556 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158556, ["x"] = 0.484, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questGiverID"] = 158556, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2444, ["threshold"] = 10000 } } } },
[61099] = { ["id"] = 61099, ["name"] = "The Search for Baine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "I dare not step inside that accursed tower myself, of course. While I cannot tell you exactly where your comrade is being held, I offer a gift to assist you. Use it inside Torghast. It should take you somewhere near your missing ally. Baine Bloodhoof was his name, yes? Either that, or you'll end up trapped within the tower's ever-shifting halls for all eternity. But those are the risks one must take, I suppose. Best of luck!", ["objectivesText"] = "Enter Torghast and search for Baine. Progress: You've found him!", ["rewardGold"] = 1239200, ["rewardXP"] = 16330, ["rewardItems"] = { 184544, 184757 }, ["rewardChoices"] = { 184757 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questTurnInID"] = 162804, ["questType"] = "standard", ["sourceQuests"] = { 60136 }, ["questLines"] = { { ["id"] = 1210, ["name"] = "Torghast", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1242, ["name"] = "Torghast", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1243, ["name"] = "Torghast", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1244, ["name"] = "Torghast", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1245, ["name"] = "Torghast", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 153, ["title"] = "9.0 Covenant Campaigns Ch 2 - Torghast", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1210, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1242, ["questLineOrder"] = 1 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1243, ["questLineOrder"] = 1 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 124