[61129] = { ["id"] = 61129, ["name"] = "RSVP: Droman Aliothe", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61129 }, ["description"] = "I serve my Queen and abide by my oath to guard this hollow and tend the spirits it encloses. Once, I might have enjoyed your Prince's party, but I am no longer suited to revelry. My world was destroyed long ago, and perhaps I have lost the joy I felt as its wild guardian. I would dearly like a reminder of my old home. I have heard those strange traders, the brokers, have unusual objects from other worlds. Perhaps they have something from mine?", ["objectivesText"] = "Investigate the offers of the Brokers to see whether a remnant of Aliothe's world may be found. Progress: Have you found a reminder of my home for me?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171828, 176121, 179315, 180774, 180969, 180970, 180971, 180972, 180973 }, ["rewardCurrencies"] = { { ["id"] = 1851, ["amount"] = 90 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61130] = { ["id"] = 61130, ["name"] = "RSVP: Sika", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61130 }, ["description"] = "Hello, <name>! Sika like to help. So much to do. Would go to Ember Court, but too many things only Sika can do. Very sorry.", ["objectivesText"] = "Find others in Olympic Village to take on Sika 's tasks so she can attend the Ember Court. Progress: Busy, busy. Too busy. No one else can do all the things.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176125, 180965, 180966, 180967, 180968 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[61135] = { ["id"] = 61135, ["name"] = "Heart of the Crest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58775, 58816, 58832, 58856, 58857, 58905, 58937, 58938, 58939, 58995, 58997, 61135, 61697 }, ["series"] = { 58997 }, ["description"] = "With this greatest of gifts from Ardenweald, we have the final piece to rebuild the Crest of Ascension. Let us make certain Willowblossom's sacrifice is not in vain.", ["objectivesText"] = "Place the Vessel of Ardenweald at the Crest of Ascension. Progress: <The vessel seems drawn to the spot.>", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174843, 174845, 175153, 175982, 176446, 180633, 180766, 180778, 181295 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questTurnInID"] = 160037, ["questType"] = "standard", ["sourceQuests"] = { 58997 }, ["questLines"] = { { ["id"] = 1093, ["name"] = "A Vessel of Ardenweald", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1093, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
