[61139] = { ["id"] = 61139, ["name"] = "RSVP: Choofa", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61139 }, ["description"] = "Oooh a party! I love parties. My friends have to come too or it's just not as much fun. Ask them please! You need to find Awool, Rury, and Slanknen so we can go together.", ["objectivesText"] = "Make sure all of Choofa 's friends are able to attend the party. Progress: Friends all ready?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 8827, 85500, 107950, 133755, 176119, 177951, 183956 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160814, ["x"] = 0.634, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160814, ["x"] = 0.634, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
