[61190] = { ["id"] = 61190, ["name"] = "Wake of Ashes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["description"] = "It feels as if the Maw itself is sentient... and taking notice of our presence. We must leave at once. Bolvar must be informed of what is happening here. I will bring my father with us. Lead the way out of here, <name>. With haste.", ["objectivesText"] = "Escape from the Maw and report to Bolvar in Oribos.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 178018, 181174, 204584, 204592, 204600, 204608, 205989 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 172414, ["x"] = 0.33, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 13587 } }, ["questType"] = "standard", ["sourceQuests"] = { 59966 }, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2456, ["db2PoiUiMapID"] = 1960 },
[61193] = { ["id"] = 61193, ["name"] = "A Light Touch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61193 }, ["description"] = "Need Firstborne's Light ! You know? Named after Archon! Always in water. Kofi 's favorite! Shine big light when grown. And go to shore! Easy to see!", ["objectivesText"] = "Collect 15 Firstborne's Light in water sources. Progress: Only grown flowers! Little ones won't work.", ["rewardGold"] = 30900, ["rewardXP"] = 8165, ["rewardItems"] = { 180897, 181368, 181377, 181612, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184842 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61196] = { ["id"] = 61196, ["name"] = "The Secret Ingredient", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61196 }, ["description"] = "At times, even the most seasoned kyrian may have difficulty meditating. Recently, such problems have become increasingly common. There is a special draught crafted from our purest waters that can be used to focus the mind. I believe it may prove useful in our work here as well, perhaps as a catalyst for more potent reactions. Will you gather some? Move swiftly, for the liquid becomes unstable once removed from our sacred pools.", ["objectivesText"] = "Collect 10 Ephemeral Draught . Progress: Were you able to find the draught?", ["rewardGold"] = 549600, ["rewardXP"] = 8165, ["rewardItems"] = { 180898, 181368, 181377, 181583, 181601, 181610, 181703, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184840, 184841, 184842 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61199] = { ["id"] = 61199, ["name"] = "Arms Day", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61199 }, ["description"] = "Many battles here. Especially lately! Now weapons all over. Too many. We can use! Go to big battle places and grab them. We will use better!", ["objectivesText"] = "Collect 20 Blessed Armaments from battlefields. Progress: Careful with the pointy end!", ["rewardXP"] = 8165, ["rewardItems"] = { 180946, 181368, 181377, 181599, 181609, 181610, 181629, 181632, 181636, 181703, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61209] = { ["id"] = 61209, ["name"] = "A Somber Melody", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61209 }, ["description"] = "Though we kyrian cease to be should we perish in battle here, there is much power within Bastion itself that can call forth echoes of our former brothers and sisters. These memories wander the roads. At times, they take on some purpose they served in their eternity here--crafting goods, guarding our sacred grounds, and the like. Take my lyre. Its ancient melody will dispel the memories, and in the process charge it with the residual energy of our realm.", ["objectivesText"] = "Dissipate 15 Kyrian memories along the roads of Bastion.", ["rewardXP"] = 8165, ["rewardItems"] = { 180990, 181368, 181377, 181570, 181578, 181581, 181589, 181594, 181599, 181606, 181609, 181614, 181635, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
