[61226] = { ["id"] = 61226, ["name"] = "Extra Limbs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "We cannot carry out the baroness's plans alone. What she proposes will require a well-coordinated unit. Three individuals maintained Nurakkir alongside me. When the necropolis fell, two of my soulbinds fell with it. There remains a single soul paired with mine. My sister, Xennir, survived the wreckage--though grief besets her. Meet with Xennir. Guide her through her trauma, and return when she is ready to rejoin the fight.", ["objectivesText"] = "Locate and assist Navigator Xennir .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158529, ["x"] = 0.498, ["y"] = 0.178 }, { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 158604, ["x"] = 0.509333, ["y"] = 0.166667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57649, 59265 }, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61227] = { ["id"] = 61227, ["name"] = "The Other Foot", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "It is a fool's errand to command a necropolis without someone to repair it and keep it airborne. Nurrakir's mechanic was slain in the crash. But opportunity arises in dire times. Vyn has told me of an... altercation among the constructs. One of their own resisted the reckless scavenging of Nurakkir, and was promptly detained for his objections. Find this individual. An enemy deserter could make for a potential ally.", ["objectivesText"] = "Locate Mechanic Ansid.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164646, ["x"] = 0.498, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159814, ["x"] = 0.493, ["y"] = 0.177 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57649, 59265 }, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
