[61230] = { ["id"] = 61230, ["name"] = "Outside Influence", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["series"] = { 61252 }, ["description"] = "It takes a particular kind of magic to pilot a necropolis. The Eyes' helmsman perished with Nurakkir. But Baroness Vashj has informed me of a means to acquire a new helmsman. Follow me to our house's communications beacon. My baroness has taught me a way to summon just the individual we require. I suspect she will not be pleased at the prospect of serving us. I trust you will encourage her compliance.", ["objectivesText"] = "Meet with Khaliiq at the House of Eyes' communications pillar.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 173312, 175796 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 171875, ["x"] = 0.502, ["y"] = 0.169 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 174343, ["x"] = 0.542, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.169 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57649, 59265 }, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
