[61246] = { ["id"] = 61246, ["name"] = "Power of the Chosen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "The necropolis is nearly in position. Now is the time to strike! We must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts. The Margrave will be unable to ignore their deaths. Once they leave their blighted tower, we can finish them once and for all.", ["objectivesText"] = "Destroy the Bilebloat Juggernauts . Progress: Every moment the juggernauts remain standing, our position is in jeopardy!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60044, 60114, 61567 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
