[61252] = { ["id"] = 61252, ["name"] = "Call In a Favor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["series"] = { 61230 }, ["description"] = "We will do just as my baroness commands. Let us conjure a helmsman before us... however displeased it might make her. Activate the beacon and prepare yourself for a fight. The liches regard all Eyes as their enemies, and I am certain your reputation among them does you no favors.", ["objectivesText"] = "Summon Helmsman Caliroux and defeat her.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181162 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 174343, ["x"] = 0.542, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 171875, ["x"] = 0.502, ["y"] = 0.169 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61230 }, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61255] = { ["id"] = 61255, ["name"] = "RSVP: Alexandros Mograine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61255 }, ["description"] = "It would be an honor to represent Maldraxxus at the Ember Court of Prince Renathal. But before I leave my post, I must ensure my comrades will be safe while I am away. Fight your way into the Ossein Foundry and retrieve weapons from our rivals there. I will have them distributed among the troops while I make ready to depart.", ["objectivesText"] = "Collect 9 Ossein Staves and 3 Ossein Battleaxes from the Ossein Foundry. Progress: Have you gotten the weapons yet?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176115, 181160, 181161 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 171933, ["x"] = 0.504, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 171933, ["x"] = 0.504, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61943 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
