[61323] = { ["id"] = 61323, ["name"] = "See What You've Done", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57644, 57648, 57649, 58007, 59265, 59555, 61226, 61227, 61230, 61252, 61323, 61335, 62448 }, ["description"] = "We have gathered what forces we can. I hope it is enough. Within the ruins of our necropolis awaits one final challenge. The one leading the salvage effort calls herself Gorgantus. To preserve all that remains to us, we must end her. Lead the attack, and the Eyes will join you. We will reclaim our home.", ["objectivesText"] = "Slay Gorgantus the Gutter .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181162, 182256, 182265, 182274, 182283 }, ["rewardChoices"] = { 182265, 182274, 182283, 182256 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158529, ["x"] = 0.498, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164619, ["x"] = 0.505, ["y"] = 0.2005 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57644, 61252, 61335 }, ["questLines"] = { { ["id"] = 1088, ["name"] = "The House of Eyes", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1088, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
