[61396] = { ["id"] = 61396, ["name"] = "Dark Developments", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "<The torn document appears to have been written by Surgeon Stitchflesh.> ...the kyrian flesh improves strength, obedience, and dexterity twofold! Such potential! Now, if subject number one-three-five succeeds in a proper wing transplant at last... <It continues on for some time. You should bring this to your kyrian allies.>", ["objectivesText"] = "Bring the Abhorrent Design to Artemede . Provided item:", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 181285 }, ["starts"] = { { ["x"] = 0.335, ["y"] = 0.241, ["mapID"] = 1536, ["objectID"] = 355825 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168744, ["x"] = 0.352, ["y"] = 0.268 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.268 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59910 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61397] = { ["id"] = 61397, ["name"] = "Opportunity Strikes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 62839, 62840, 62843 }, ["description"] = "This sanctum cannot function on anima alone. It will take many willing souls working in harmony to unlock the full potential of the Seat of the Primus. Our Soul Warden is always in search of new souls to induct into the sanctum. Your ability to travel back and forth from the Maw will undoubtedly prove useful to him. You should pay him a visit to see what assistance you can offer.", ["objectivesText"] = "Speak to Osbourne Black .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161909, ["questTurnInID"] = 161909, ["questType"] = "standard", ["sourceQuests"] = { 62840 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[61398] = { ["id"] = 61398, ["name"] = "Ember Court: Traditional", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61398 }, ["description"] = "Of course Darkhaven is honored to provide traditional decorations for Prince Renathal's court. Venthyr decor is all about setting a certain mood. That means lurking stonefiends and death blossom scented candles in vast quantity. Our resources are stretched thin, <name>. We can supply stonefiends easily, but our artisans need wax to melt with fresh death blossom . There should be candle remnants and drips in the village to scrape up. Death blossoms can be harvested from the plants themselves.", ["objectivesText"] = "Collect 50 Candle Wax and 20 Death Blossoms . Death Blossoms can be harvested with the herbalism skill. Progress: Have you managed to gather the raw materials for our artisans yet?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 169701, 172061, 176126, 181473 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61399] = { ["id"] = 61399, ["name"] = "Ember Court: Mortal Reminders", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 61399 }, ["description"] = "For a reasonable renumeration, Ta Cartel can supply the decorations you require. Restocking unique and intriguing items is an important aspect of doing business. As you can freely return to your own world, you can provide me some new and exciting products to offer. Your world has captured the imagination of many of our clients. I have buyers looking for some specific things native to Azeroth.", ["objectivesText"] = "Help Keeper Ta'saran replenish stock by retrieving the items on the list he's provided you. Progress: Have you found something that fits each item on the list?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173057, 176128, 181336, 181354, 181356, 181367 }, ["starts"] = { { ["x"] = 0.592, ["y"] = 0.751, ["mapID"] = 1670, ["npcID"] = 156791 } }, ["ends"] = { { ["x"] = 0.592, ["y"] = 0.751, ["mapID"] = 1670, ["npcID"] = 156791 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.592, ["y"] = 0.751 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 156791, ["questTurnInID"] = 156791, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[61400] = { ["id"] = 61400, ["name"] = "Ember Court: Mystery Mirrors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61400 }, ["description"] = "I support Prince Renathal's efforts and will certainly help the Ember Court! Mystery mirrors will be dangerous but add real excitement to the party. I will need a lot of mirror fragments to complete enough of them in time. You will also need to refresh my supply of Ashen Cores so I can get the glass sufficiently molten to work.", ["objectivesText"] = "Collect 12 Shrouded Mirror Shards , 12 Scorched Mirror Fragments , and 3 Molten Cores. Progress: Have you found the mirror fragments and an Ashen Core ?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176127, 181519, 182097, 183912, 183919 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 172986, ["x"] = 0.246, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 172986, ["x"] = 0.246, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61401] = { ["id"] = 61401, ["name"] = "Ember Court: Venthyr Volunteers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61401 }, ["description"] = "Oh, hello again! Did you hear that I have been given command of the guard for the Ember Court? That would probably be more impressive if there were already recruits. I need to get these recruiting posters up. If you can take care of that, I can meet the interested recruits here and then we can test their combat skills when you return.", ["objectivesText"] = "Place 6 Recruiting Posters and test 3 Sinfall Recruits. Progress: Those posters need to be put in visible locations and the recruits need to be tested.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176138, 181716 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 172614, ["x"] = 0.61, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 172614, ["x"] = 0.61, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61402] = { ["id"] = 61402, ["name"] = "Ember Court: Stoneborn Reserves", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61402 }, ["description"] = "To call up the reserves to provide security for the Ember Court we will need anima. Good, loyal troops are ready as soon as we can animate them. We will also need weapons for them. Sort that out and I will make sure the Prince and his guests are well protected.", ["objectivesText"] = "Fill the anima canister by defeating enemy stoneborn in Dominance Keep. Collect 12 Stoneborn Glaives . Progress: Have you filled the anima canister and found enough weapons to equip our new comrades?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 176139, 181500 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 172502, ["x"] = 0.265, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 172502, ["x"] = 0.265, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.265, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "group", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[61403] = { ["id"] = 61403, ["name"] = "Ember Court: Maldraxxus Army", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61403 }, ["description"] = "So your prince's little parties have attracted unwanted attention? < Emeni laughs.> I have my own long list of enemies, and far too many of them hide from me in the land of the living. Cowards! But I have finally found a solution. Take this crystal to my remains on Azeroth, and use it to project my image among the living for a short time so that I may exact revenge on my old kin.", ["objectivesText"] = "Release Emeni 's projection in Vol'dun and help her defeat her ancient sethrak enemies. Progress: What are you waiting for? Those sethrak won't impale themselves.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176140, 181519, 181523 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172964, ["x"] = 0.542, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172964, ["x"] = 0.542, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58407 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61404] = { ["id"] = 61404, ["name"] = "Ember Court: Tubbins's Tea Party", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61404 }, ["description"] = "Theotar need tea for party? Tubbins make best! Special tea. Very special. Only I can make. Recipe need very good water from garden place. Good pool on special floaty island! You go get and Tubbins makes tea!", ["objectivesText"] = "Collect Pristine Water from Ardenweald's Distant Grotto. Progress: Need special water to make special tea. Makes sense.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 176134, 181370, 183943 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167863, ["x"] = 0.31, ["y"] = 0.575 }, { ["mapID"] = 1525, ["npcID"] = 173299, ["x"] = 0.312, ["y"] = 0.574 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167863, ["x"] = 0.31, ["y"] = 0.575 }, { ["mapID"] = 1525, ["npcID"] = 173299, ["x"] = 0.312, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "group", ["sourceQuests"] = { 61705 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[61405] = { ["id"] = 61405, ["name"] = "Ember Court: Divine Desserts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61405 }, ["description"] = "Recipes very important. Must not be lost! I learn new foods from many mortals, add to my book. Best way is taste some of thing so can know what is good. You teach recipe to me this way and bring me right ingredients so I cook too. Then taste yours, then taste mine. Helps me learn. I bring desserts to Ember Court. Fair, yes?", ["objectivesText"] = "Collect a sample of Banana Beef Pudding , 30 Aethereal Meat , and 20 Phantasmal Haunch . Then taste-test Stewart 's concoction. Progress: You ready to give ingredients and taste test?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172052, 172055, 172069, 176135 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 172448, ["x"] = 0.34, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 172448, ["x"] = 0.34, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 61880 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[61406] = { ["id"] = 61406, ["name"] = "Ember Court: Mushroom Surprise!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61406 }, ["description"] = "I had not realized the fame of my fungi had reached so far. I'd be delighted to provide a mushroom feast to the Ember Court! Hmmm... I will need you to collect some rare specimens and will loan you my favorite foraging bag. It will help you find the very best fungi. It's never failed me. Let's see, I need tiny lacy bells from Bastion and some of those Ardenweald fancy purple frills. From the very tops of our mushrooms here I will need the feather caps . You'll need to grapple your way up there.", ["objectivesText"] = "Collect 18 Feather Caps , 24 Lacy Bell Morels , and 4 Violet Frills . Progress: Have you filled the foraging bag?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176136, 181522, 181828, 181829, 181830, 181839 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168429, ["x"] = 0.402, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168429, ["x"] = 0.402, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61407] = { ["id"] = 61407, ["name"] = "Ember Court: Atoning Rituals", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61407 }, ["description"] = "If Prince Renathal wishes to impart knowledge of Revendreth's highest calling to his guests, we would be honored to demonstrate the rituals of atonement. However, I must ask for your assistance preparing the necessary components quickly. Capture nearby fugitive souls that hide from the Lord Chamberlain's corrupt venthyr. Bring them to our avowed ritualists across the halls. They will prepare the souls for our purpose. Sinstone fragments will also help us identify the sins of these lost souls.", ["objectivesText"] = "Collect 125 Sinstone Fragments and deliver 2 Fugitive Souls to Avowed Ritualists. Progress: Fugitive souls can be found hiding in the darkest corners of the Halls of Atonement.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176130 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167332, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167332, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 57929, 61706 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61408] = { ["id"] = 61408, ["name"] = "Ember Court: Glimpse of the Wilds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61408 }, ["description"] = "It would be wonderful to show Revendreth the wild creatures of Ardenweald! You can get some Radiant Groupers near the waterfalls. They're fast so you have to grab them as they swim by. Here's a net to use to subdue the Territorial Waders. They should follow you once you've caught them. Highland Runestags will let you ride them if you aren't aggressive. Bring a few here to me, please. Watch out for the bulls, they're not at all friendly. We will get others to help too. This sounds like fun.", ["objectivesText"] = "Bring 3 Highland Runestags, 8 Radiant Groupers and 4 subdued Territorial Waders to Niya . Progress: We need Radiant Groupers, Highland Runestags, and Territorial Waders please.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 168417, 176131, 183944 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 172352, ["x"] = 0.562, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172352, ["x"] = 0.562, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61880 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61411] = { ["id"] = 61411, ["name"] = "Our Heart Will Go On", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61411 }, ["objectivesText"] = "Speak to Zayhad Drust invaders slain Good memories collected Scene 01 Complete Scene 02 Complete Scene 03 Complete Scene 04 Complete Scene 05 Complete Scene 06 Complete Scene 07 Complete Scene 08 Complete Scene 09 Complete Zayhad spoken to Return good memories to Zayhad", ["rewardXP"] = 8165, ["rewardItems"] = { 181284 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Speak to Zayhad", ["amount"] = 1, ["type"] = 0, ["objectID"] = 172185, ["orderIndex"] = 0 }, { ["text"] = "Drust invaders slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 172193, ["orderIndex"] = 1 }, { ["text"] = "Good memories collected", ["amount"] = 3, ["type"] = 0, ["objectID"] = 172278, ["orderIndex"] = 2 }, { ["text"] = "Scene 01 Complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 172266, ["orderIndex"] = 3 }, { ["text"] = "Scene 02 Complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 172267, ["orderIndex"] = 4 }, { ["text"] = "Scene 03 Complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 172268, ["orderIndex"] = 5 }, { ["text"] = "Scene 04 Complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 172269, ["orderIndex"] = 6 }, { ["text"] = "Scene 05 Complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 172270, ["orderIndex"] = 7 }, { ["text"] = "Scene 06 Complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 172271, ["orderIndex"] = 8 }, { ["text"] = "Scene 07 Complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 172272, ["orderIndex"] = 9 }, { ["text"] = "Scene 08 Complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 172273, ["orderIndex"] = 10 }, { ["text"] = "Scene 09 Complete", ["amount"] = 1, ["type"] = 0, ["objec