[61412] = { ["id"] = 61412, ["name"] = "An Early End", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57470, 57473, 57475, 57530, 57636, 59910, 59916, 60043, 60044, 60050, 60067, 60098, 60114, 60510, 61145, 61180, 61246, 61396, 61412, 61567, 61586 }, ["description"] = "Within the Hall of Chains lie more constructs that are nearly complete. As we speak, the Margrave's forces work fervently to graft the last pieces of flesh to their horrific visages. If they are allowed to finish their work, then the destruction we have wrought thus far will make little difference in the final conflict. Our flank will be overrun by a fresh wave of horrors, and the day will be lost. That must not come to pass. Destroy any of these abominations you encounter.", ["objectivesText"] = "Destroy 6 Inert Butchers .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168743, ["x"] = 0.352, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168743, ["x"] = 0.352, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 59916, 60043, 61396 }, ["questLines"] = { { ["id"] = 1120, ["name"] = "A Golden Dawn", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1120, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61414] = { ["id"] = 61414, ["name"] = "Faulty Fireworks (+Safe)", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61414 }, ["objectivesText"] = "Progress: < Prince Renathal looks at the Flimsy Firework you're carrying with great concern.> This cheap party favor could send all of Sinfall up in flames!", ["rewardItems"] = { 181355 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164965, ["x"] = 0.459, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164965, ["x"] = 0.459, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.459, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
