[61473] = { ["id"] = 61473, ["name"] = "Sourcing Your Own Materials", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60489, 60493, 60494, 60495, 60496, 60497, 60498, 61473 }, ["series"] = { 60496, 60497 }, ["description"] = "I can aid you in crafting many pieces of equipment for your soulbinds. Though they may only equip one at a time, each piece grants a new ability that they may not have without it. This time you must source your own materials from around the Shadowlands. When you have collected them, return to me and we can create the footpads!", ["objectivesText"] = "Craft the Herald's Footpads with Dactylis . Check the materials in the crafting window to learn where you can gather them. Progress: You find materials okay? Blueprint can help!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178995, 179008, 179009, 179010, 179378, 180472, 180477, 180478, 180579, 180594, 180595, 184444 }, ["rewardCurrencies"] = { { ["id"] = 1819, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171816, ["x"] = 0.628, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 60497 }, ["questLines"] = { { ["id"] = 1209, ["name"] = "The Path of Ascension", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[61475] = { ["id"] = 61475, ["name"] = "The Heart of the Forest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1565, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 63214 }, ["description"] = "I knew we were gonna get along! Welcome to our covenant. Well, almost. There's just a few details left. Little things. You know. Oaths to be made, blood pacts to sort out, firstborns to be promised. <Moonberry snorts a laugh.> I'm just kidding! Well, not about the oaths part. We take those seriously around here. I'll meet you at the camp outside the Heart of the Forest!", ["objectivesText"] = "Meet Lady Moonberry at the Refugee Camp beside the Heart of the Forest in Ardenweald.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 56636, 56637, 56638, 131303 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 10565 } }, ["questType"] = "standard", ["sourceQuests"] = { 57878, 62000, 63214 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
