[61478] = { ["id"] = 61478, ["name"] = "Humble Beginnings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61478 }, ["series"] = { 61372 }, ["description"] = "With Humility's Guard whole once more, you may be able to coax Athanos back into the arena. Travel to Aspirant's Crucible, where your journey began so long ago. Seek Forgelite Sophone --she guides all those who seek an encounter with Athanos. Present the spear to her. She will know your intent and instruct you further.", ["objectivesText"] = "Bring Humility's Guard to Forgelite Sophone in Aspirant's Crucible. Progress: What is that you have there?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 181471 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 175295, ["x"] = 0.516, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 61371 } },
[61479] = { ["id"] = 61479, ["name"] = "The Boon of Shapes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["description"] = "<Moonberry looks serious.> Mortal though you are, you have chosen to become one of our champions. While you uphold our cause, we are obligated to extend hospitality to you within our sacred hall and grant you certain boons. As a member of the Court of Night, I can bestow our powers on chosen mortals. <name>, <class> of Azeroth, I bid you welcome to the first tree, Tirna Achiad, the Heart of the Forest. Please, follow me.", ["objectivesText"] = "Accompany Lady Moonberry into the Heart of the Forest and take part in the ceremony. Progress: Accept this boon and use it for the benefit of Ardenweald.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["sourceQuests"] = { 61475 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[61485] = { ["id"] = 61485, ["name"] = "I'll Only Say This Once", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["series"] = { 57778 }, ["description"] = "At last, we are fully prepared to enact the baroness's plan. Now that you have arrived, I will recount our roles one final time. Then we will seize our fate. Listen closely.", ["objectivesText"] = "Speak with Whisperer Vyn about the plan.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 160518, ["x"] = 0.502, ["y"] = 0.167 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172574, ["x"] = 0.3, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.167 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57778 }, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61486] = { ["id"] = 61486, ["name"] = "The Banshee's Champion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 61486 }, ["description"] = "I... we... I mean... he's... <The young courier gulps.> We found him. We found the Blightcaller. I was on patrol like I'd done a hundred times before only there he was sitting on the front porch of that old house with those terrible dogs and I swear he smirked at me and stared with those fiery red eyes and-- <The young courier wipes his brow.> He's at the Marris Stead. Our forces have him surrounded, but, uh... You should probably gather your friends. I don't think he plans to surrender.", ["objectivesText"] = "Confront Nathanos Blightcaller at Marris Stead in Eastern Plaguelands. Progress: What news do you bring of the Blightcaller?", ["rewardGold"] = 772200, ["rewardXP"] = 10225, ["rewardItems"] = { 165608, 165610, 165611, 165613, 165614, 165619, 165621, 165622, 165623, 165624, 165625, 165627, 165628, 166482, 166898 }, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 172510, ["x"] = 0.655333, ["y"] = 0.766667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 167329, ["x"] = 0.395, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.655333, ["y"] = 0.766667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 60767 } },
[61488] = { ["id"] = 61488, ["name"] = "The Banshee's Champion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 61488 }, ["description"] = "<The messenger appears visibly shaken.> Word has reached us of... well, I'm not quite sure how to put it... The Blightcaller has been found. Horde forces have been scouring Azeroth for any sign of him. Determined to make him answer for his crimes. One of our Argent patrols has found him. Not hiding in some distant land. Just... waiting at his old homestead. We have him surrounded, but, uh, I confess I don't like our odds. Perhaps you could gather your allies and bring him to justice.", ["objectivesText"] = "Confront Nathanos Blightcaller at Marris Stead in Eastern Plaguelands.", ["rewardGold"] = 716040, ["rewardXP"] = 10225, ["rewardItems"] = { 165608, 165610, 165611, 165613, 165614, 165619, 165621, 165622, 165623, 165624, 165625, 165627, 165628, 166482, 166898 }, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 172514, ["x"] = 0.528, ["y"] = 0.774 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 169928, ["x"] = 0.488667, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 60761 } },
[61489] = { ["id"] = 61489, ["name"] = "Of Hearsay and Heresy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61489 }, ["description"] = "Echthra has taken residence in one of the few remaining structures in the former House of Eyes in Maldraxxus. Bring the anointment oil to her, and she should allow you to capture her memory. Take caution, for she is well-known both as a master marksman and--perhaps more notably--for her quick trigger finger. Good luck, Maw Walker.", ["objectivesText"] = "Find Echthra in the House of Eyes in Maldraxxus. Progress: Be cautious. There are many in the House of Eyes who would not tolerate your presence.", ["rewardGold"] = 257400, ["rewardItems"] = { 178995, 179378, 180477, 180478, 180594, 180595, 181273, 181701, 181706 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172515, ["x"] = 0.566, ["y"] = 0.116 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533, 1536 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 61356 } },
[61490] = { ["id"] = 61490, ["name"] = "War of Information", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61490 }, ["series"] = { 61357 }, ["description"] = "Ah, the anointment oil. I had expected one of Adrestes' recruits. No matter. You seek my memory for your trials, yes? I am afraid mere oil will not suffice. With our house gone, we are left to fend for ourselves. Though this tower offers some protection, we are left cornered to any who may desire our end. Information is the key to survival. Use my anointed talisman to give me eyes across all the realms...even in Bastion. Follow the list precisely--no questions. Then can we resolve payment.", ["objectivesText"] = "Place Eyes of Hatred in the House of Rituals in Maldraxxus, Eonian Archives in Bastion, Tirna Vaal in Ardenweald, and Castle Nathria in Revendreth. Progress: There will be no negotiation in this matter.", ["rewardGold"] = 257400, ["rewardItems"] = { 178995, 179378, 180477, 180478, 180594, 180595, 181273, 181683, 181699, 181701 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172515, ["x"] = 0.566, ["y"] = 0.116 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172515, ["x"] = 0.566, ["y"] = 0.116 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.116 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61489 } },
[61492] = { ["id"] = 61492, ["name"] = "The Princeguard", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 59343, 59676, 59701, 59706, 59707, 59708, 59711, 59719, 59720, 61492 }, ["description"] = "Renathal carries himself well, but hides great pain. His wounds from Denathrius have not healed. He is vulnerable. He intends to send you to secure his old fortress of Darkwall Tower with banners and rely on his own strength to deter enemies. This is a poor tactical choice. Take this small reserve of anima with you and revive Chelra the Bladewall . She was last seen at Darkwall. Revive her and she can aid you in taking the tower.", ["objectivesText"] = "Revive Chelra the Bladewall and drive enemies out of Darkwall Tower. Progress: I have suffered in stillness for months. I worried I would never wake again.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181516 }, ["starts"] = { { ["x"] = 0.463, ["y"] = 0.157, ["mapID"] = 1699, ["npcID"] = 161977 } }, ["ends"] = { { ["x"] = 0.463, ["y"] = 0.157, ["mapID"] = 1699, ["npcID"] = 161977 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.463, ["y"] = 0.157 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 161977, ["questTurnInID"] = 161977, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["questLines"] = { { ["id"] = 1069, ["name"] = "The Court of Harvesters", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1069, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61509] = { ["id"] = 61509, ["name"] = "Shinies of Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61509 }, ["description"] = "Chordy is bored, boooored! You want to go look for luckydos? Go on adventure with Chordy ? We go to land of wing people, go look for valuable luckydos there. Ready?", ["objectivesText"] = "Use Chordy to locate and collect 10 valuable salvage around Bastion. Progress: Did we find anything good?", ["rewardXP"] = 8165, ["rewardItems"] = { 174101, 178554, 182489, 182498, 182507, 182516, 183744, 183804, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 161270, ["x"] = 0.55, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60041 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61510] = { ["id"] = 61510, ["name"] = "A Bountiful Haul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61510 }, ["description"] = "Chordy want to go on adventure! You want to go too, yes? I scavenge, weapons, armor, and valuable luckydos! Though, luckydos seem to be in short supply these days. We go to land of tree people! If we search together, we'll find many luckydos!", ["objectivesText"] = "Use Chordy to locate and collect 10 valuable salvage in Ardenweald. Progress: Did we find anything good?", ["rewardXP"] = 8165, ["rewardItems"] = { 174101, 178554, 182489, 182498, 182507, 182516, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 161270, ["x"] = 0.55, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60041 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61511] = { ["id"] = 61511, ["name"] = "Things They Leave Behind", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61511 }, ["description"] = "Chordy bored. Chordy want to go on adventure! You want to go too, yes? Pale people in tall buildings have many shinies and luckydos. We go there and find some for ourselves! You ready to go?", ["objectivesText"] = "Use Chordy to locate and collect 10 valuable salvage in Revendreth. Progress: Did we find anything good?", ["rewardXP"] = 8165, ["rewardItems"] = { 174101, 178554, 182489, 182498, 182507, 182516, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 161270, ["x"] = 0.55, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 60041 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61518] = { ["id"] = 61518, ["name"] = "Follow Me", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["series"] = { 60112 }, ["description"] = "Assuming the others are in position, we are prepared to steal the necropolis. You and I must push forward to rendezvous with Ansid. Khaliiq will regroup with Vyn once their tasks are complete. Come along, $p, and stay near. I will shroud the both of us in shadow, so long as you are at my side.", ["objectivesText"] = "Follow Navigator Xennir to the rendezvous point. Progress: Keep your eyes open.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 57363, 57364, 57365, 66891, 66892, 66893, 264468, 264469 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172574, ["x"] = 0.3, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172574, ["x"] = 0.3, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61485 }, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
