[61522] = { ["id"] = 61522, ["name"] = "Corpse Run", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61522 }, ["description"] = "There's work that needs doing 'round here. Mmmm hmmm. Spotted a big ol' carcass nearby. I aim to salvage it for parts. Figure you could come along, help me drag it to Rathan . He'd like that. Mmmm hmmm. Reckon I could even carry you there and back. You don't look too big. Ready to get going?", ["objectivesText"] = "Return the Bone Carcass to Rathan at Butcher Block. Progress: Yes? Did you find anything on your supply run?", ["rewardXP"] = 8165, ["rewardItems"] = { 178599, 182483, 182492, 182501, 182510, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 158300, ["x"] = 0.542, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57597 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
