[61541] = { ["id"] = 61541, ["name"] = "The Forge of Bonds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "<name>, are you ready for another gift? The next boon we grant thee is one of bonds. As you have bound yourself to us, we shall bind to you. In the binding of souls, we become something greater. <Moonberry leans in close.> Sounds scary, huh? Don't worry! You and your soulbind will both strengthen each other. When I asked for volunteers, many fae stepped forward. I picked someone I just know you're going to like. And this will be a boon for her, too. Go to Flutterby . She'll help you both.", ["objectivesText"] = "Meet Flutterby at the Forge of Bonds.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questTurnInID"] = 172431, ["questType"] = "standard", ["sourceQuests"] = { 62898 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 25, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61542] = { ["id"] = 61542, ["name"] = "The Boon of Binding", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "< Flutterby clasps her hands before her and assumes an air of tranquility.> Soulbinding is not an irrevocable act. However, such a bond must be carefully considered before it is made. You and your soulbind will know each other's hearts and minds. Your hopes and fears; your dreams and memories; all will be shared between you. As long as the bond exists, you are intertwined; always together even when apart. Once complete, your connection will transcend physical space and empower you both.", ["objectivesText"] = "Complete the soulbinding ritual. Progress: When you are ready, we may proceed.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.341, ["y"] = 0.436, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["ends"] = { { ["x"] = 0.341, ["y"] = 0.436, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.341, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 158553, ["questTurnInID"] = 158553, ["questType"] = "standard", ["sourceQuests"] = { 61541 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 27, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
