[61550] = { ["id"] = 61550, ["name"] = "Strengthening the Bond", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "I know how you feel... and what you have endured for the sake of your world. You now know of my own triumphs and tragedies as well. Our bond will grow stronger over time. But for now, let us see what it has granted us. Ardenweald has needs of us. We must do everything in our power to save it.", ["objectivesText"] = "Activate a Soulbind Power using the Forge of Bonds. Progress: We are stronger together.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180847, 181373, 181467, 181469, 181512, 181539, 181639, 181707, 181774, 181775, 181840, 181962, 182106, 182108, 182113, 182129, 182130, 182133, 182288, 182317, 182324, 182331, 182335, 182336, 182347, 182348, 182448, 182460, 182463, 182466, 182469, 182584, 182651, 182685, 182767, 182777, 182962, 182964, 183199, 183463, 183466, 183467, 183473, 183474, 183494, 183495, 183496, 183500, 199456, 199459, 199460 }, ["starts"] = { { ["x"] = 0.337, ["y"] = 0.45, ["mapID"] = 1701, ["npcID"] = 172677 } }, ["ends"] = { { ["x"] = 0.337, ["y"] = 0.45, ["mapID"] = 1701, ["npcID"] = 172677 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.337, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 172677, ["questTurnInID"] =