[61551] = { ["id"] = 61551, ["name"] = "Crush 'Em All", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["series"] = { 61548 }, ["description"] = "The mooring platform will be our best launching point to access the necropolis above. But one more fight remains before us. Enforcer Borgulla oversees all of the work efforts that take place here. We'll need to eliminate her if we are to proceed unhindered. She is a formidable foe. It appears Ansid has kept some of his explosives on his person. Let us utilize this advantage.", ["objectivesText"] = "Use Ansid's Explosive to kill Enforcer Borgulla .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 31537, 31538, 31539, 31540, 43858, 43911, 43927, 43928, 43929, 49927, 57357, 57358, 57359, 59050, 59051, 59052, 63821, 63822, 63823, 131516, 182250, 182259, 182268, 182277 }, ["rewardChoices"] = { 182268, 182259, 182277, 182250 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172573, ["x"] = 0.2876, ["y"] = 0.4564 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172573, ["x"] = 0.2876, ["y"] = 0.4564 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.2876, ["y"] = 0.4564 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61548 }, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61552] = { ["id"] = 61552, ["name"] = "The Hunt Watches", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61552 }, ["series"] = { 61553 }, ["description"] = "The Wild Hunt protects. Many eyes watch for danger. Many ears listen for secrets. Watcher Vesperbloom directs the eyes and ears of the forest. Seek out our new growth, then turn to her for guidance.", ["objectivesText"] = "Activate Adventures then seek out Watcher Vesperbloom . Progress: Ah. You're here. Good.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.397, ["y"] = 0.557, ["mapID"] = 1702, ["npcID"] = 165702 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 164023, ["x"] = 0.446, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questGiverID"] = 165702, ["questType"] = "standard" },
[61553] = { ["id"] = 61553, ["name"] = "Know Where to Strike", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61553 }, ["series"] = { 61552 }, ["description"] = "It is the Wild Hunt's duty to hunt down those who would harm our charges and to ensure the security of our borders. But as the crisis has grown, so have our duties to Queen and Grove. This is where I come in. It is my duty to be aware of all that goes on within the endless forest. It is my charge to help deploy our resources, so that we may aid our queen. Allow me to demonstrate...", ["objectivesText"] = "Use the Command Table to send your forces on an adventure. Progress: Every victory furthers our cause.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 164023, ["x"] = 0.446, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 164023, ["x"] = 0.446, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61552 } },
[61554] = { ["id"] = 61554, ["name"] = "The Play's The Thing", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 61554 }, ["series"] = { 58104, 58157, 58158, 58159 }, ["description"] = "You may be wondering about the last boon we may grant thee, O' champion of Ardenweald, petitioner to our Hunt. Before our Queen grants you our power and we accept you formally into our midst, there are certain... Traditions which we must uphold. Lady Moonberry awaits you in the Sanctum Hall with more information. Break a leg.", ["objectivesText"] = "Seek out Lady Moonberry in the Heart of the Forest central hall.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[61556] = { ["id"] = 61556, ["name"] = "Party Crashers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 61556 }, ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 54302, 54303 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 172780 } }, ["db2QuestInfoID"] = 272, ["db2QuestInfoName"] = "VenthyrPartyQuest" },
[61557] = { ["id"] = 61557, ["name"] = "An Echo in the Darkness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 61557, 61558, 61559, 62569 }, ["description"] = "$p, I... I am beset by dark visions. A power emanating from within Torghast. A familiar sensation. One I have not felt since... Come to Oribos . Do not delay.", ["objectivesText"] = "Meet Bolvar Fordragon in Oribos .", ["rewardGold"] = 128700, ["rewardXP"] = 1020, ["rewardItems"] = { 179358, 184315 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["sourceQuests"] = { 60501, 61730 }, ["questLines"] = { { ["id"] = 1140, ["name"] = "A Fateful Vision", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[61558] = { ["id"] = 61558, ["name"] = "The Highlord's Vision", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 61557, 61558 }, ["description"] = "< Thrall 's brow is furrowed.> We were speaking with the Highlord when he was struck by a jolt of agony. He said he could see something stirring in the Maw. Inside the Jailer's tower. The pain seems to be getting worse. We need to find out what he's sensing.", ["objectivesText"] = "Find out what Bolvar senses inside Torghast. Progress: We must know the truth.", ["rewardItems"] = { 184315 }, ["starts"] = { { ["x"] = 0.4, ["y"] = 0.684, ["mapID"] = 1670, ["npcID"] = 171362 } }, ["ends"] = { { ["x"] = 0.4, ["y"] = 0.684, ["mapID"] = 1670, ["npcID"] = 171362 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.4, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 171362, ["questTurnInID"] = 171362, ["questType"] = "standard", ["sourceQuests"] = { 61730 }, ["questLines"] = { { ["id"] = 1138, ["name"] = "Peering into Darkness", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1140, ["name"] = "A Fateful Vision", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 155, ["title"] = "9.0 Covenant Campaigns Ch 3 - Peering Into Darkness", ["questLineID"] = 1138, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questL