[61701] = { ["id"] = 61701, ["name"] = "Searching the Grove", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "It is clear that a struggle took place here. I fear that Kivarr may have been taken by the Drust. I scouted the surrounding area before you arrived. Eventide Grove has been overrun. The Drust cannot have taken her far. We may yet be able to find her. I just pray that we are not too late...", ["objectivesText"] = "Search for Kivarr at Eventide Grove in Ardenweald.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 170705, ["x"] = 0.4296, ["y"] = 0.4572 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171413, ["x"] = 0.448, ["y"] = 0.6912 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.4296, ["y"] = 0.4572 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61113 }, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61702] = { ["id"] = 61702, ["name"] = "A Swift Intervention", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "The Drust just took Kivarr away. They said they were going to sacrifice her in one of their rituals! If we hurry, you may still be able to save her! I've seen where the Drust keep their sacrificial altar... it's scary, but I can take you there! There's no time to waste! Follow me!", ["objectivesText"] = "Rescue Kivarr from Eventide Grove in Ardenweald.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173612, ["x"] = 0.465, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171413, ["x"] = 0.448, ["y"] = 0.6912 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 58773 }, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61703] = { ["id"] = 61703, ["name"] = "Nox Root", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "In order to perform the ritual, I will need some nox root from Darkreach. It is a unique plant that only grows within soil that has been corrupted by Drust magic. Darkreach lies to the west, not far from my den. What was once a peaceful, verdant grove is now filled with blight and ruin. I will travel to the Heart of the Forest to prepare the ritual. Meet me there when you have gathered the nox root .", ["objectivesText"] = "Collect 12 Nox Root from Darkreach in Ardenweald . Progress: Have you brought the reagents?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182958 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171413, ["x"] = 0.448, ["y"] = 0.6912 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171413, ["x"] = 0.448, ["y"] = 0.6912 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.6912 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61143 }, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61704] = { ["id"] = 61704, ["name"] = "Ember Court: Guest RSVPs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59660, 59661, 61616, 61704, 61705, 61706, 61880, 61882, 61884 }, ["description"] = "Prince Renathal will wish to invite certain guests to each Ember Court. In the future, we'll be able to adjust the guest list to make it easier to please everyone in attendance. But, we should follow the Prince's lead on this first one. Work with Lord Garridan and Lady Ilinca to ensure that Cryptkeeper Kassir is able to attend and returns his RSVP. If you haven't met Cryptkeeper Kassir yet in your adventures, you may need to introduce yourself before he'll listen to you.", ["objectivesText"] = "Speak with Lord Garridan to see your Guest List, then meet Cryptkeeper Kassir to earn his RSVP.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 179958 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59661 }, ["questLines"] = { { ["id"] = 1196, ["name"] = "The Ember Court", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61705] = { ["id"] = 61705, ["name"] = "Ember Court: Refreshments", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59660, 59661, 61616, 61704, 61705, 61706, 61880, 61882, 61884 }, ["description"] = "We should always serve refreshments in the Ember Court, tailoring our choice of refreshment type to the preferences of our guests. Luckily, I know our first guest well. Like Theotar, he prefers it to be Formal. Work with Picky Stefan to acquire everything we need to throw a fancy tea party.", ["objectivesText"] = "Speak with Picky Stefan to see your Refreshment options, then complete Tubbins 's quest to earn the tea party contract.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176134 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167863, ["x"] = 0.31, ["y"] = 0.575 }, { ["mapID"] = 1525, ["npcID"] = 173299, ["x"] = 0.312, ["y"] = 0.574 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59661 }, ["questLines"] = { { ["id"] = 1196, ["name"] = "The Ember Court", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61706] = { ["id"] = 61706, ["name"] = "Ember Court: Entertainment", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59660, 59661, 61616, 61704, 61705, 61706, 61880, 61882, 61884 }, ["description"] = "Everyone loves entertainment! Our first guest is from the Halls of Atonement, so he will certainly appreciate a presentation of the powerful rituals the Accuser is capable of. Work with Hips to acquire everything we need to host atoning rituals at the Ember Court.", ["objectivesText"] = "Speak with Hips to see your Entertainment options, then complete Gresit 's quest to earn the rituals contract.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176130 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167332, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 59661 }, ["questLines"] = { { ["id"] = 1196, ["name"] = "The Ember Court", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61707] = { ["id"] = 61707, ["name"] = "Crumbled Reality", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61707 }, ["description"] = "As the drought and devourers eat our buildin's, the structures lose their hold on reality. Thing is, it ain't a clean process. Some of that debris is still infused with anima. When your out, be a stoneback an' bring us whatever infused debris you can find. See, we can recycle it into new structures as you hero types go and get the anima flowin' again. Bring it here an we'll get it sorted.", ["objectivesText"] = "Recover 100 Infused Rubble . Progress: Impressed 'ow much you can carry with 'em 'itty bitty arms.", ["rewardItems"] = { 181176, 181177, 181179, 181181, 181185, 181186, 181192, 181196, 181197, 181200, 181202, 181217, 181334, 181545, 181546, 181547, 181548, 181550, 181708, 182158, 184147, 184150, 184777, 184870, 185854 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173036, ["x"] = 0.712, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173036, ["x"] = 0.712, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61708] = { ["id"] = 61708, ["name"] = "Drawing Out the Poison", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61708 }, ["objectivesText"] = "Ride Grimshadow to the Flayedwing Nesting Grounds Phylactery of Arin'gore found Phylactery of Arin'gore destroyed", ["rewardXP"] = 8165, ["rewardItems"] = { 174043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Ride Grimshadow to the Flayedwing Nesting Grounds", ["amount"] = 1, ["type"] = 0, ["objectID"] = 160917, ["orderIndex"] = 0 }, { ["text"] = "Phylactery of Arin'gore found", ["amount"] = 1, ["type"] = 0, ["objectID"] = 162224, ["orderIndex"] = 1 }, { ["text"] = "Phylactery of Arin'gore destroyed", ["amount"] = 1, ["type"] = 0, ["objectID"] = 161292, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[61709] = { ["id"] = 61709, ["name"] = "Witch's Satchel", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "I sent Ara'lon to steal a witch's satchel from the Drust... a dangerous task from which he has yet to return. The Drust's nightscreamers carry many reagents we need to perform the ritual. We cannot proceed without one. You must go to the Oaken Assembly to procure one of their satchels... and find Ara'lon, if you can.", ["objectivesText"] = "Collect 1 Witch's Satchel from the Oaken Assembly in Ardenweald . Progress: Do you have the satchel? And what of Ara'lon?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182963 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171413, ["x"] = 0.448, ["y"] = 0.6912 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171413, ["x"] = 0.448, ["y"] = 0.6912 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.6912 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61703 }, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61710] = { ["id"] = 61710, ["name"] = "The Broken Spear", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "<The shattered remains of a sylvari spear litter the ground. You recognize the spear as belonging to Ara'lon. This confirms that Ara'lon was here. Unfortunately, he is nowhere to be found. Lord Herne will want to know of your discovery.>", ["objectivesText"] = "Deliver the remains of Ara'lon's spear to Lord Herne at Heart of the Forest in Ardenweald . Progress: What news do you bring?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 122102, 182966 }, ["starts"] = { { ["x"] = 0.338, ["y"] = 0.544, ["mapID"] = 1565, ["objectID"] = 357726 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 170848, ["x"] = 0.462, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61703 }, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61711] = { ["id"] = 61711, ["name"] = "Ritual of Purification", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58773, 60898, 60910, 60928, 60934, 61061, 61076, 61102, 61113, 61143, 61171, 61701, 61702, 61703, 61709, 61710, 61711 }, ["description"] = "I have finished making preparations for the ritual. The moment of truth has come. The Drust fetish that Ulfar gave you will channel the ritual's power into Gweyir. It should counteract the curse that imprisons her mind. This will not be pleasant. It may not even work. But this is the only chance we have to free her.", ["objectivesText"] = "Complete the Ritual of Purification. Progress: The ritual is our only hope of freeing Gweyir. We must try...", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171413, ["x"] = 0.448, ["y"] = 0.6912 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171413, ["x"] = 0.448, ["y"] = 0.6912 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.6912 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61709, 61710 }, ["questLines"] = { { ["id"] = 1104, ["name"] = "Drust to Drust", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1104, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61713] = { ["id"] = 61713, ["name"] = "Blueprint: Charm of Quickness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61713 }, ["description"] = "<You have discovered plans for a charm that seems to make your soulbinds fleet of foot in the Path of Ascension. Dactylis should be able to help you with crafting this charm.>", ["objectivesText"] = "Bring the Blueprint: Charm of Quickness to Dactylis . Provided item:", ["rewardItems"] = { 182162 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 182162 } },
[61714] = { ["id"] = 61714, ["name"] = "Gilded Abacus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 61714 }, ["description"] = "steward will appreciate this as not only a useful gift, but an exquisite one.>", ["objectivesText"] = "Summon your steward companion via Summon steward , then give them the Gilded Abacus . Provided item:", ["rewardItems"] = { 184580 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 62971 }, ["startItems"] = { 184580 } },
[61715] = { ["id"] = 61715, ["name"] = "Request of the Highlord", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 59011, 59206, 60737, 61715, 61716 }, ["series"] = { 59206, 61716 }, ["description"] = "The information you uncovered in Maldraxxus should quell the drums of war between the Necrolords and the Kyrian. And this message from the Primus... extraordinary! I would advise you to enlist Highlord Fordragon's counsel, but he appears preoccupied. Visitors from your world have come to seek him out. Quite insistently, I might add. The nuances of mortal interaction elude me. But it seems the nature of their dialogue was rather... intense. Perhaps you can assist the Highlord with this matter.", ["objectivesText"] = "Speak to Bolvar Fordragon.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.544, ["y"] = 0.542, ["mapID"] = 1670, ["npcID"] = 162928 } }, ["ends"] = { { ["x"] = 0.544, ["y"] = 0.542, ["mapID"] = 1670, ["npcID"] = 162928 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.544, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 162928, ["questTurnInID"] = 162928, ["questType"] = "standard", ["sourceQuests"] = { 59206 }, ["questLines"] = { { ["id"] = 1063, ["name"] = "The Empty Throne", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1063, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[61716] = { ["id"] = 61716, ["name"] = "A Glimpse into Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 59011, 59206, 60737, 61715, 61716 }, ["series"] = { 59206, 61715 }, ["description"] = "When I put the Lich King's crown upon my head, I wanted the world to believe I was dead. Even my daughter, Taelia. I... thought a lie would be kinder than the truth. But she is no longer the little girl I left in Kul Tiras. I see my choice was a selfish one. <Bolvar pauses.> She and Lady Menethil have asked me to peer into the Maw to see if our allies yet live. It is a dangerous request, but one I cannot refuse. Help me focus on the broken helm. Together, we may find a glimpse of truth.", ["objectivesText"] = "Witness Bolvar's vision of the Maw. Progress: There is much to do.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 184165 }, ["starts"] = { { ["x"] = 0.403, ["y"] = 0.687, ["mapID"] = 1670, ["npcID"] = 173384 } }, ["ends"] = { { ["x"] = 0.403, ["y"] = 0.687, ["mapID"] = 1670, ["npcID"] = 173384 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.403, ["y"] = 0.687 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 173384, ["questTurnInID"] = 173384, ["questType"] = "standard", ["sourceQuests"] = { 61715 }, ["questLines"] = { { ["id"] = 1063, ["name"] = "The Empty Throne", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1063, ["questLineOrder"] = 15 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1063, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
