[61730] = { ["id"] = 61730, ["name"] = "The Captive King", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["storyline"] = { 61558, 61559, 61730, 62569 }, ["series"] = { 62836 }, ["description"] = "King Anduin has not been found inside Torghast. I fear we could spend eternity searching those endless corridors to no avail. We must know what fate has befallen him. To peer into the tower represents a grave risk, yet we have little choice. Stand with me, <name>. We will use the broken Helm of Domination to see into that hellish place. Perhaps together we can hold back the hungry darkness.", ["objectivesText"] = "Use the Helm of Domination to peer into Torghast. Progress: We must peer into Torghast before Anduin is lost to us.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 184276, 184277, 184278 }, ["rewardCurrencies"] = { { ["id"] = 1828, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.682, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.682, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.402, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 62836 }, ["questLines"] = { { ["id"] = 1138, ["name"] = "Peering into Darkness", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 155, ["title"] = "9.0 Covenant Campaigns Ch 3 - Peering Into Darkness", ["questLineID"] = 1138, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 3 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1138, ["questLineOrder"] = 3 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1138, ["questLineOrder"] = 3 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1138, ["questLineOrder"] = 3 } } },
[61731] = { ["id"] = 61731, ["name"] = "Magical Curios", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61731 }, ["objectivesText"] = "Progress: Curious. Most curious trinkets... May I keep to study? Will learn much.", ["rewardItems"] = { 182212 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 171831, ["x"] = 0.644667, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 171831, ["x"] = 0.644667, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.644667, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[61732] = { ["id"] = 61732, ["name"] = "Old Habits Never Die", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61732 }, ["description"] = "Your redistribution of anima has been commendable so far. But venthyr are still venthyr. They may spend eons educating souls on the folly of greed and hoarding, but they often fail to acknowledge the return of that trait in themselves, given enough time. My scouts have witnessed a number of venthyr siphoning the anima you have redistributed and hoarding it within their estates and dwellings. Search these places and recover this hoarded anima so that we might put it to better use.", ["objectivesText"] = "Recover 10 Hoarded Anima Cages .", ["rewardItems"] = { 181176, 181178, 181181, 181198, 181201, 181203, 181206, 181211, 181216, 181217, 181545, 181546, 181547, 181548, 181550, 181708, 184147, 184150, 184777, 185854 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173042, ["x"] = 0.722, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173042, ["x"] = 0.722, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61733] = { ["id"] = 61733, ["name"] = "Big Bag of Creepers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61733 }, ["description"] = "Right. You've been a polished bit of gray so far and it's appreciated from the bottom up for sure. Well, now I got a task for 'ou that would help all of us dredgers put that anima you obtained to good use. Creepers. Not just any creepers, but 'em mire creepers . 'Ey got a look about 'em and a taste about 'em that just sings when you put it to good use. As you go trippin' around Revendreth, grab any creepers ya find an' stick 'em in this here sack. I'll pay ya.", ["objectivesText"] = "Collect 20 Mire Creepers . Progress: Creepers. 'Ey like chewin' on the mortar at holds all these walls up.", ["rewardItems"] = { 180939, 181176, 181177, 181180, 181182, 181189, 181197, 181198, 181204, 181217, 181218, 181224, 181334, 181545, 181546, 181547, 181548, 181550, 181708, 182583, 184147, 184150, 184777, 185854, 185942 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173127, ["x"] = 0.714, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173036, ["x"] = 0.712, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61734] = { ["id"] = 61734, ["name"] = "Census of Sins", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61734 }, ["description"] = "The Curator once knew the contents and locations of every sinstone in Revendreth dating back to the founding of this realm. Sadly, her time in the Maw disrupted those essential parts of her vast intellect and we can no longer rely upon her for such knowledge. At least, not for a while. And so it falls to me to rebuild a 'living' archive. As you venture into Revendreth I would ask that you recover the contents and location of certain sinstones. This will help us orient our archive.", ["objectivesText"] = "Inspect 7 Lost Sinstones.", ["rewardItems"] = { 181175, 181176, 181177, 181179, 181180, 181182, 181183, 181184, 181185, 181191, 181194, 181196, 181197, 181198, 181199, 181200, 181202, 181204, 181206, 181207, 181216, 181217, 181218, 181224, 181334, 181545, 181546, 181547, 181548, 181550, 181708, 182724, 184147, 184150, 184777, 185854, 185942 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173532, ["x"] = 0.722, ["y"] = 0.758 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173532, ["x"] = 0.722, ["y"] = 0.758 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.758 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61735] = { ["id"] = 61735, ["name"] = "Awaken Our Allies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61735 }, ["description"] = "I have need of your services. I have identified a collection of stoneborn throughout Revendreth whom may be swayed to our cause, or were already members of our cause before returning to their stone slumber. You have provided us with the anima we needed, now it is time to put it to use. Seek out our allies and awaken them. I have fashioned an anima container for easier transport to aid in this endeavor. We need an army if we are to face an army.", ["objectivesText"] = "Awaken 15 Allied Stoneborn.", ["rewardItems"] = { 180939, 181175, 181178, 181180, 181186, 181191, 181192, 181193, 181196, 181198, 181201, 181202, 181205, 181217, 181218, 181334, 181545, 181546, 181547, 181548, 181550, 181708, 182291, 182724, 184147, 184150, 184777, 185854 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173038, ["x"] = 0.715, ["y"] = 0.764 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173038, ["x"] = 0.715, ["y"] = 0.764 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.764 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61736] = { ["id"] = 61736, ["name"] = "Stolen Away", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 61736 }, ["description"] = "There is much you need to be told, . The Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked. What's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war. Speak to Whitemane. She can tell you the rest.", ["objectivesText"] = "Speak to Sally Whitemane about the abductions.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[61737] = { ["id"] = 61737, ["name"] = "Stolen Away", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 61737 }, ["description"] = "There is much you need to be told, . The Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked. What's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war. Speak to Nazgrim. He can tell you the rest.", ["objectivesText"] = "Speak to Nazgrim about the abductions.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[61738] = { ["id"] = 61738, ["name"] = "Ember Court: Lost Chalice Band", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61738 }, ["description"] = "Hips was smart to send you my way. The Lost Chalice Band plays the best music this side of the Maw! The band is not quite ready to tour yet, however. The musicians are all safe in the crypt behind me, but their instruments have been confiscated by our obnoxious neighborhood authorities! Noise complaints and all that. Help me get those back, and perhaps recruit a few groupies and roadies along the way to help out, and we shall throw the best concert your court has ever seen!", ["objectivesText"] = "Use band posters to recruit 10 groupies and 10 roadies and recover 3 Confiscated Band Supplies. Progress: Any venthyr or dredger will do. We are not picky about our fans.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176132, 181520, 182302, 182310, 182311, 182312 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173173, ["x"] = 0.55, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173173, ["x"] = 0.55, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61739] = { ["id"] = 61739, ["name"] = "The Wayward Baron", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "It has come to my attention that you seek to uncover a plot by the baron Kel'Thuzad. That upstart has been a thorn in my side since he arrived at the House of Rituals. Not only did he pilfer my rightfully earned title, he has since shut me out of the house's dealings. I have yet to find evidence that would mar Sin'dane's adoration for her new baron, and thus I offer an arrangement. I grant you access to the House of Rituals, and in return you help me bring down Kel'Thuzad. Do we have an accord?", ["objectivesText"] = "Open Balmedar's Supplies at the tower near the Scaplian Ridge.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173420, ["x"] = 0.594, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 62388 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61740] = { ["id"] = 61740, ["name"] = "Playing Favorites", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "We will have to construct an illusion to allow you entry into the House of Rituals. However, not just any illusion will do. In order to join Kel'Thuzad's inner circle, we require something... specific. We're going to need a body. Fortunately for us, one of the baron's favorite acolytes is performing a ritual outside of the house itself. You'll need to fight your way to her, but of that I'm sure you're capable.", ["objectivesText"] = "Defeat Acolyte Nelesis and bring her corpse back to the tower near Scaplian Ridge. Progress: Don't you have a corpse to procure?", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["starts"] = { { ["x"] = 0.593, ["y"] = 0.329, ["mapID"] = 1536, ["npcID"] = 173422 } }, ["ends"] = { { ["x"] = 0.593, ["y"] = 0.329, ["mapID"] = 1536, ["npcID"] = 173422 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.593, ["y"] = 0.329 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questGiverID"] = 173422, ["questTurnInID"] = 173422, ["questType"] = "standard", ["sourceQuests"] = { 61739 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61741] = { ["id"] = 61741, ["name"] = "Pilfered Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "The illusion ritual will require a substantive amount of anima to complete. Since such a resource isn't simply lying around these days, we will need to take some. The abominations from the House of Constructs recently arrived with a delivery of anima-rich spoils from the raid on Bastion. Use the maldracite crystal I've included in the parcel to extract enough anima for our ritual.", ["objectivesText"] = "Drain anima from the Kyrian Spoils in the House of Rituals to fill the maldracite crystal.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.593, ["y"] = 0.329, ["mapID"] = 1536, ["npcID"] = 173422 } }, ["ends"] = { { ["x"] = 0.593, ["y"] = 0.329, ["mapID"] = 1536, ["npcID"] = 173422 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.593, ["y"] = 0.329 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 173422, ["questTurnInID"] = 173422, ["questType"] = "standard", ["sourceQuests"] = { 61739 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61742] = { ["id"] = 61742, ["name"] = "A Fitting Guise", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "The ritual to complete your disguise should be quite simple with the assistance of my oculus. Even a <class> like you should be able to manage it. When you are ready, simply hold the empowered crystal above Nelesis's corpse. My oculus will do the rest.", ["objectivesText"] = "Meet Balmedar in the Hall of Blades at the House of Rituals.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["npcID"] = 173422 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questGiverID"] = 173422, ["questType"] = "standard", ["sourceQuests"] = { 61740, 61741, 62414 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61743] = { ["id"] = 61743, ["name"] = "The Pupil Returns", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "Now that you have your disguise--and I have assurance of your loyalty--it is time you reported to your new master. Find Kel'Thuzad within the Vault of Souls. Do whatever tasks he requires of you, but keep your eyes open for anything untoward. My oculus will continue to accompany you so that I can provide guidance when the time is right. We will uncover this new baron's true intentions.", ["objectivesText"] = "Meet Kel'Thuzad within the Vault of Souls.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172923, ["x"] = 0.702, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61742 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1652 },
[61744] = { ["id"] = 61744, ["name"] = "The Baron's Plan", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "You have done well in my service, Nelesis. When the time has come to take my rightful place, you will be well rewarded. Until then, I will require your utmost devotion and secrecy. Our preparations are almost complete. Come, walk with me, and I will show you the splendor of our works.", ["objectivesText"] = "Walk with Kel'Thuzad . Progress: Walk with me, acolyte.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172923, ["x"] = 0.702, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172923, ["x"] = 0.702, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61743 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1652 },
[61745] = { ["id"] = 61745, ["name"] = "Mistress of Tomes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "The kyrian will no doubt make a worthy sacrifice for our ritual, but I am not entirely versed with the magics of his kind. I have requested that the Baroness Ninadar assemble a list of appropriate literature, so that I can ensure my ritual will have the desired effect. As you know, the baroness enjoys exploiting her title, so expect to be faced with some manner of mundane tasks in exchange for her cooperation. Return when you have procured the tomes, acolyte.", ["objectivesText"] = "Speak with Baroness Ninadar in the Grimoirium.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172923, ["x"] = 0.702, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172924, ["x"] = 0.662, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61744 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61746] = { ["id"] = 61746, ["name"] = "Cantrip Collections", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "One of the... more regrettable duties of the Mistress of Tomes is the collation and maintenance of our scroll library. Unfortunately, many of our acolytes are less than prompt when it comes to returning items they have borrowed, which requires me to seek them out and retrieve them myself. Of course, this is far too menial a task for a baroness, but that is why lackeys like you exist. Go, and retrieve my scrolls. Feel free to use whatever persuasive means you have at your disposal.", ["objectivesText"] = "Collect 6 Overdue Scrolls from Necrotic Acolytes in the Grimoirium. Progress: Have you found my scrolls?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182609 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172924, ["x"] = 0.662, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172924, ["x"] = 0.662, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61745 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61747] = { ["id"] = 61747, ["name"] = "Errant Enchantments", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "The House of Rituals is a place of constant study. Every day, new incantations and formulae are concocted to further the arts of necromancy. It can be difficult to keep track of such innovation. To aid in cataloguing our progress, our sorcerers have applied the use of enchanted quills and parchment. Unfortunately, if not properly stored, these implements tend to run amok. Of course, they were not properly stored. Find the implements and return them to where they belong.", ["objectivesText"] = "Retrieve 4 Errant Quills and 6 Rampant Grimoires in the Grimoirium. Progress: Enchanted quills will not collect themselves, now will they?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182615, 182616 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172924, ["x"] = 0.662, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172924, ["x"] = 0.662, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61745 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61748] = { ["id"] = 61748, ["name"] = "The Hall of Tomes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "Very well, you can have your list. The volumes you seek can be found in the Hall of Tomes. Now, run back to your master like a good little pet.", ["objectivesText"] = "Collect the required volumes from the Hall of Tomes and return them to Kel'Thuzad in the Vault of Souls. Progress: You have returned? Do you have my tomes?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 182642, 182643, 182644, 182645 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172924, ["x"] = 0.662, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172923, ["x"] = 0.702, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61746, 61747 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1652 },
[61749] = { ["id"] = 61749, ["name"] = "Necessary Ingredients", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "As you are well aware, a ritual of this complexity requires several reagents. I have asked that Carver Jor'dan prepare what I'll need. Seek him out in the Reagentry, and provide whatever assistance he requests.", ["objectivesText"] = "Speak with Jor'dan the Powerful in the Reagentry.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172923, ["x"] = 0.702, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173492, ["x"] = 0.7, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61748 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61750] = { ["id"] = 61750, ["name"] = "Heart of the Forest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "The baron requests a veilwing's heart , but procuring one is going to be something of a problem. <Jor'dan gestures to the disarray nearby.> As you can plainly see, one of our sorcerers proved incapable of restraining the beast. I regret to inform you that our only specimen has escaped. It cannot have gone far, though. If you follow its tracks you should be able to catch up with it and retrieve the heart yourself. I assure you the baron will not be able to perform his ritual without it.", ["objectivesText"] = "Collect a Veilwing's Heart from the Elusive Veilwing in the House of Rituals. Progress: Did you find the veilwing?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 56636, 56637, 56638, 131303, 182676 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173492, ["x"] = 0.7, ["y"] = 0.326 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173492, ["x"] = 0.7, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61749 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61751] = { ["id"] = 61751, ["name"] = "Cage Free Spores", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "I will need your assistance with the collection of one other reagent for your master. These spore clusters he requests--while normally a trivial matter--will require a bit of work. You see, as the veilwing rampaged throughout the Reagentry, it toppled and broke several nearby cages hosting the blightrays from which we harvest the clusters. You will have to collect them through more... conventional means. The clusters are fragile, however, so try not to damage them while subduing the creatures.", ["objectivesText"] = "Collect 6 Intact Spore Clusters from Escaped Blightrays in the Reagentry. Progress: Do you have the spore clusters?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182678 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173492, ["x"] = 0.7, ["y"] = 0.326 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173492, ["x"] = 0.7, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61749 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61752] = { ["id"] = 61752, ["name"] = "The Final Reagent", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "I have gathered most of the remaining reagents on your master's list. All that remains is the special shipment he requested from Oribos. The brokers have yet to deliver the shipment. When it arrives, your master will have all he needs to complete his ritual.", ["objectivesText"] = "Bring the Bundle of Reagents to Balmedar in the House of Rituals. Progress: Let us see what we have here.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 182252, 182261, 182270, 182279, 182679 }, ["rewardChoices"] = { 182270, 182261, 182279, 182252 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173492, ["x"] = 0.7, ["y"] = 0.326 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61750, 61751 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61753] = { ["id"] = 61753, ["name"] = "Explosive Schemes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "The brokers deal in objects most exotic and profound. If Kel'Thuzad requires reagents from them, his ritual must be outside the normal scope of the House of Rituals. This mysterious reagent could be the key to unlocking Kel'Thuzad's plan. We must get a hold of this delivery from Oribos. I have taken the liberty of concocting an alchemical bomb. Use it to ambush the caravan and retrieve whatever they are transporting.", ["objectivesText"] = "Use the Alchemical Explosive to ambush the Broker caravan at the Scaplian Ridge. Progress: The caravan will arrive any moment now. Make haste!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 173172, ["questType"] = "standard", ["sourceQuests"] = { 61752 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61754] = { ["id"] = 61754, ["name"] = "No Crate Unturned", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "That explosion will likely bring onlookers from the House of Rituals. We must act quickly. Search through the debris for anything that looks out of the ordinary. It is likely that Kel'Thuzad's mystery reagent won't be hard to spot.", ["objectivesText"] = "Search the Broker's Crates for Kel'Thuzad's special reagent.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182734, 182735 }, ["starts"] = { { ["npcID"] = 173422 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questGiverID"] = 173422, ["questType"] = "standard", ["sourceQuests"] = { 61753 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61755] = { ["id"] = 61755, ["name"] = "Blinding the Brokers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "We cannot allow Kel'Thuzad to discover who stopped his shipment. None must be left to tell the tale of what transpired here.", ["objectivesText"] = "Kill 8 broker witnesses in the Scaplian Ridge.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 173422 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questGiverID"] = 173422, ["questType"] = "standard", ["sourceQuests"] = { 61753 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61756] = { ["id"] = 61756, ["name"] = "Designed to Fail", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["description"] = "The pieces are all coming together. The kyrian, the Paths of the First Ones, and runes of domination? Kel'Thuzad is looking to breach the Maw! We cannot allow this to happen! The Maw has been locked away from the Shadowlands for good reason. Opening that floodgate could be catastrophic! The baron is too powerful to confront headlong, so we will stop his ritual instead. Return to him with his reagents. I have made some \"modifications\" that should provide a calamitous end to his scheme.", ["objectivesText"] = "Bring the Bundle of \"Modified\" Reagents to Kel'Thuzad in the Vault of Souls. Progress: My acolyte returns. What have you brought me?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 182779 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172923, ["x"] = 0.702, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61754, 61755 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1652 },
[61757] = { ["id"] = 61757, ["name"] = "Caught in the Act", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["series"] = { 61758, 61759 }, ["description"] = "Well then, since it was you who managed to procure the missing reagent, I find it only fair that you assist me with the final ritual! I can guarantee that this incantation will see you promoted to a full sorcerer of the house! The preparations are already made. We can begin as soon as you are ready.", ["objectivesText"] = "Assist Kel'Thuzad in completing the ritual.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172923, ["x"] = 0.702, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172923, ["x"] = 0.702, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 172923, ["questType"] = "standard", ["sourceQuests"] = { 61756 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1652 },
[61758] = { ["id"] = 61758, ["name"] = "Improvised Implements", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1652, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["series"] = { 61757, 61759 }, ["description"] = "There must be some way we can get ourselves out of these cells. I don't see anything I can use over here. Search your cell for anything that can facilitate our escape.", ["objectivesText"] = "Search your cell for something that can be used to escape.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.542, ["y"] = 0.679, ["mapID"] = 1652 } }, ["ends"] = { { ["x"] = 0.542, ["y"] = 0.679, ["mapID"] = 1652 } }, ["coords"] = { ["mapID"] = 1652, ["x"] = 0.542, ["y"] = 0.679 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 61757 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1652 },
[61759] = { ["id"] = 61759, ["name"] = "A Helpful Hand", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["series"] = { 61757, 61758 }, ["description"] = "It takes but a simple act of necromancy to animate a hand. Unfortunately, since you will be in closest proximity, you must be the one to command it. When you are ready, I will reanimate the hand. Once you have control, use it to pull the lever at the end of the hall. Couldn't be simpler, right?", ["objectivesText"] = "Navigate the Reanimated Hand to the end of the hall and activate the Corroded Lever .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.542, ["y"] = 0.679, ["mapID"] = 1652 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61758 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1652 },
[61760] = { ["id"] = 61760, ["name"] = "The Traitor Unmasked", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["description"] = "We must waste no time in warning the margrave of Kel'Thuzad 's treachery. His reckless toying with forbidden powers could bring ruin to the house and beyond! Let us put an end to this!", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardChoices"] = { 182269, 182260, 182278, 182251 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322, ["mapID"] = 1536 } }, ["ends"] = { { ["npcID"] = 173172, ["x"] = 0.662, ["y"] = 0.322, ["mapID"] = 1536 } }, ["coords"] = { ["x"] = 0.662, ["y"] = 0.322, ["source"] = "quest_giver", ["mapID"] = 1536 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 173172, ["questType"] = "standard", ["sourceQuests"] = { 61759 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 23, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } } },
[61761] = { ["id"] = 61761, ["name"] = "The Better Part of Valor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61739, 61740, 61741, 61742, 61743, 61744, 61745, 61746, 61747, 61748, 61749, 61750, 61751, 61752, 61753, 61754, 61755, 61756, 61757, 61758, 61759, 61760, 61761, 62388, 62414 }, ["series"] = { 58833, 62391 }, ["description"] = "We now have no choice but to make a strategic retreat. Kel'Thuzad is far too fortified within the necropolis, and if Ninadar is his ally, then the House of Rituals is firmly in his grasp. It will take nothing short of an army to save the margrave now.", ["objectivesText"] = "Return to the Seat of the Primus.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 183847 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.699, ["y"] = 0.27, ["mapID"] = 1536, ["npcID"] = 173831 } }, ["ends"] = { { ["x"] = 0.699, ["y"] = 0.27, ["mapID"] = 1536, ["npcID"] = 173831 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.699, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 173831, ["questTurnInID"] = 173831, ["questType"] = "standard", ["sourceQuests"] = { 61760 }, ["questLines"] = { { ["id"] = 1115, ["name"] = "The House of Rituals", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1115, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61762] = { ["id"] = 61762, ["name"] = "Making a Smarter Dredger", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61762 }, ["series"] = { 61763, 61764, 61851, 62361, 62985 }, ["description"] = "If he be hostin' fancy courts with you and Temel, this dredger's gotta be special... Smarter. Stronger. Quicker to apologize when they accidentally knock over the refreshments table and spill anima all over some poor duchess... I got an idea! Broker bloke at the Night Market was tryin' to sell me some important drinks. Kaja'Extreme or somethin'. Says it bigguns the brain, yeah? That's just what we need! Take these Scorchshrooms, that broker loves them, but note he rotates his costs each week.", ["objectivesText"] = "Purchase a bottle of Kaja'Extreme from Ta'tru at the Night Market. Progress: You got the Kaja'Extreme ?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182298, 184448 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 61851 } },
[61763] = { ["id"] = 61763, ["name"] = "Dredging up an Assistant", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61763 }, ["series"] = { 61762, 61764, 61851, 62361, 62985 }, ["description"] = "Here we go, onto the dredging part. Just like we made that biggun here earlier! I mean we don't need the stone of binding or three other dredgers, but you'll still be throwing stuff into the muck! So it's the same. You head to the shore with this here Kaja-Infused Dredger Mix I whipped up for you. Toss it into that muck pool and let's meet that new dredger butler of yours!", ["objectivesText"] = "Throw the Kaja-Infused Dredger Mix into the muck pool to create your dredger butler.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182301, 182683 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 61762 } },
[61764] = { ["id"] = 61764, ["name"] = "Dredging up a Name", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 61764 }, ["series"] = { 61762, 61763, 61851, 62361, 62985 }, ["description"] = "Oi, why aren't you addressing me by my proper name? Wait, I don't remember my name, proper or other. Does this mean I have amnesias? Oh no, I don't have a name, please, help!", ["objectivesText"] = "Talk with your assistant and decide on a name for them.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 49040 }, ["starts"] = { { ["npcID"] = 172854 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 172854, ["questType"] = "standard", ["sourceQuests"] = { 62361 } },
[61765] = { ["id"] = 61765, ["name"] = "Words of Warding", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["description"] = "The towering citadel in the distance is protected by perilous walls, but its greatest dangers cannot be seen with mortal eyes. The Mawsworn have placed invisible runes of warding throughout Perdition Hold. These traps have caught many intruders unaware. The runes can be dispelled, but only if you can see them. I believe one of their soulcloaks should give you the sight you require. Good luck.", ["rewardItems"] = { 177698, 177699, 178874, 178877, 178880, 178881, 178882, 178883, 185717 }, ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 600 }, { ["id"] = 1880, ["amount"] = 475 } }, ["starts"] = { { ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416, ["mapID"] = 1543 } }, ["ends"] = { { ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416, ["mapID"] = 1543 } }, ["coords"] = { ["x"] = 0.468, ["y"] = 0.416, ["source"] = "quest_giver", ["mapID"] = 1543 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "group", ["sourceQuests"] = { 60284 } },
[61766] = { ["id"] = 61766, ["name"] = "Homegrown Help", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61766 }, ["description"] = "Every good party herald needs an assistant. Which is why I have you! But every good party herald's assistant... also needs an assistant. Which is why I procured permission from the prince for you to create your own dredger butler. We can start him on security while we cozy up to the guests and procure the necessary reading materials to train him on the social protocols of the different realms. He'll be entertaining the whole court in no time. No, don't thank me. You've earned this!", ["objectivesText"] = "Meet Rendle in Dredgewood to make a dredger butler.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182298 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61767] = { ["id"] = 61767, ["name"] = "A Perilous Journey", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 61768, 61769, 61785 }, ["description"] = "Mograine has rallied the House of the Chosen to strike at Margrave Gharmal and his House of Constructs. They grow in strength with each passing day--this may be our only chance. We will join them on the field of battle. We will have justice for the fallen at my temple, as well as Mograine's own fallen kin. Rendezvous at Spider's Watch within Maldraxxus' northern reaches. We will move from there.", ["objectivesText"] = "Meet Xandria at Spider's Watch in Maldraxxus.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 180845, 180899, 181285, 181476, 181557, 181733, 182334, 182341 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.618, ["y"] = 0.375, ["mapID"] = 1707, ["npcID"] = 154627 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173222, ["x"] = 0.377, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.377, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11012 } }, ["questGiverID"] = 154627, ["questType"] = "standard", ["sourceQuests"] = { 61785 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61768] = { ["id"] = 61768, ["name"] = "Stronger Together", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 61767, 61769, 61785 }, ["description"] = "We are to meet Baroness Draka aboard the Zerekriss above this position. Trust our allies' judgment in the battle ahead--true courage is knowing when to rely on the wisdom of others. The plan is simple. Clear out our flanks to ensure Gharmal's forces do not interfere with our true goal, then assault the Margrave himself. If we fail, we fail in the name of justice.", ["objectivesText"] = "Fly with Xandria into the necropolis Zerekriss.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173222, ["x"] = 0.377, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 171483, ["x"] = 0.362, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.377, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61767 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61769] = { ["id"] = 61769, ["name"] = "Fight and Flight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 61767, 61768, 61785 }, ["description"] = "Alexandros and Emeni will lead the Chosen assault on the western gate. You and Xandria will direct your forces at the eastern gate. Secure the area and eliminate any resistance. Once both flanks are secured we can attack Gharmal directly.", ["objectivesText"] = "Fly with Xandria to the House of Constructs.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341, 209888 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 171483, ["x"] = 0.362, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61768 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61770] = { ["id"] = 61770, ["name"] = "The Butchers of Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 59916, 60043, 60050, 60510, 61771, 61773 }, ["description"] = "Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these things?! No! The butchers of Bastion made clear their hearts that day! They deserve only the eternal darkness that awaits them. Ensure they see it!", ["objectivesText"] = "Kill 10 House of Constructs forces in the Separation Chamber. Progress: Go bravely, <name>.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168743, ["x"] = 0.352, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168743, ["x"] = 0.352, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61769 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61771] = { ["id"] = 61771, ["name"] = "Justice from Above", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 59916, 60043, 60050, 60510, 61770, 61773 }, ["description"] = "Our forces above cannot fully descend upon this area while the Margrave's crystals cover the sky in destructive blasts. The Margrave's foul butchers work even now to extract the remaining anima from the kyrian they abducted in their assault on Bastion. We must advance at once. I shall imbue you with the flames of courage so that you may mark the crystals. Once marked, I will destroy them from afar.", ["objectivesText"] = "Destroy 5 Maldracite Cores .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61769 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61772] = { ["id"] = 61772, ["name"] = "Dark Developments", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["description"] = "<The torn design document appears to be written by the late Surgeon Stitchflesh.> ...the kyrian flesh improves strength, obedience, and dexterity twofold! Such potential! Now, if subject number one-three-five succeeds in a proper wing transplant at last... <It continues on for some time. You should bring this to Artemede .>", ["objectivesText"] = "Bring the Abhorrent Design to Artemede outside the Hall of Chains. Provided item:", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["x"] = 0.335, ["y"] = 0.241, ["mapID"] = 1536, ["objectID"] = 357246 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168744, ["x"] = 0.352, ["y"] = 0.268 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.268 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61769 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61773] = { ["id"] = 61773, ["name"] = "Descended", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 59916, 60043, 60050, 60510, 61770, 61771 }, ["description"] = "Though we have stopped the creation of more juggernauts, one of their most vile creations yet draws breath. It was born of one of the most pained souls they took from my temple. As I flew above their ranks I could hear their surgeons chanting its name above the din of combat-- Woeblade . It is an affront to all the kyrian stand for, an atrocity beyond any other. Mark it with the flames of courage when you engage, and we will help you destroy it.", ["objectivesText"] = "Slay Woeblade the Atrocity.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 174295, 177056, 178159, 179946, 180845, 180899, 181285, 182334, 182341 }, ["rewardChoices"] = { 178159, 177056, 179946, 174295 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166333, ["x"] = 0.355, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61770, 61771, 61772 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61774] = { ["id"] = 61774, ["name"] = "Burn Before Reading", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["description"] = "The scroll you recovered details all manner of horrific ways to 'integrate' fallen kyrian into Gharmal's abomination constructs. It is also incomplete. There must be more of these among Stitchflesh's remaining followers. I saw a number of surgeons and their lackeys retreat into the Hall of Chains just ahead as we arrived. I suspect they hold more of these scrolls. We must ensure they are never read again.", ["objectivesText"] = "Collect 6 Stitchflesh Designs . Progress: This foul work must be destroyed.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168744, ["x"] = 0.352, ["y"] = 0.268 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168744, ["x"] = 0.352, ["y"] = 0.268 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.268 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61770, 61771, 61772 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61775] = { ["id"] = 61775, ["name"] = "An Early End", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["description"] = "Within the Hall of Chains lie more abominations that are nearly complete. As we speak the Margrave's forces work fervently to graft the last pieces of flesh to their horrific visages. If they are allowed to finish their work, the constructs we have destroyed so far will mean little in the final conflict. Our flank will be overrun by a fresh wave of horrors, and the day will be lost. That must not come to pass. Destroy any abominations you come across.", ["objectivesText"] = "Destroy 6 Inert Butchers . Progress: May your blade strike true.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168743, ["x"] = 0.352, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168743, ["x"] = 0.352, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61770, 61771, 61772 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61776] = { ["id"] = 61776, ["name"] = "Trouble on the Western Front", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["description"] = "Alexandros and our Maldraxxi allies need reinforcement at the western gate on the Margrave's opposite flank. They are barely holding on! Our forces will reinforce our position here and push forward towards Gharmal. We must make haste to Mograine--without both flanks we cannot hope to achieve victory.", ["objectivesText"] = "Fly with Kynthia to report to Alexandros at the Stitchyard.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168860, ["x"] = 0.332, ["y"] = 0.302667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.302667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61773, 61774, 61775 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61777] = { ["id"] = 61777, ["name"] = "Charging The Blade", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["description"] = "We can't advance with those juggernauts bombarding our position! I led a strike against the nearest, but conventional weapons do nothing against their imbued hides. Thankfully, I have an idea. Your old runeblade can't deal with them as it stands, but if you could purge Gharmal's empowered masses and absorb their essence into the blade...", ["objectivesText"] = "Charge your runeblade by killing enemy constructs in the Stitchyard.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61776 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61778] = { ["id"] = 61778, ["name"] = "Aerial Advantage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["description"] = "Gharmal's rocs dominate the skies above, striking at our forces as we advance. The Zerekriss can't get into position until they are cleared out! I would take care of them myself, but I'm not much of a flier. Don't have the balance for it! Take my riding hook and latch onto a roc. Once you're riding, just start hitting it 'til the job is done.", ["objectivesText"] = "Grapple 6 Battlesewn Rocs out of the sky. Progress: Teach 'em a lesson!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167810, ["x"] = 0.282, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167810, ["x"] = 0.282, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61776 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61779] = { ["id"] = 61779, ["name"] = "Grave Intent", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["description"] = "My spies have identified several astral projectors that Margrave Gharmal uses to rally his troops in the Stitchyard. I do not wish for a swarm of frenzied constructs to descend upon us during the final confrontation. Surely you see the wisdom in cutting their fervor. See to it that these projectors are destroyed. We believe them to be along the yard's perimeter.", ["objectivesText"] = "Destroy the Southwestern, Northwestern, and Northeastern Astral Projectors . Progress: A blow inflicted to the enemy's morale can be as effective as traditional combat.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167173, ["x"] = 0.286, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167173, ["x"] = 0.286, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61776 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61780] = { ["id"] = 61780, ["name"] = "Power of the Chosen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["description"] = "The Zerekriss is nearly in position. Now is the time to strike! We must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts. The Margrave will be unable to ignore their deaths. Once he leaves his blighted tower, we can finish him once and for all.", ["objectivesText"] = "Destroy the Bilebloat Juggernauts . Progress: Every moment the juggernauts live our position is in jeopardy!", ["rewardGold"] = 257400, ["rewardXP"] = 4085, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61777, 61778, 61779 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61781] = { ["id"] = 61781, ["name"] = "The End is Now", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["series"] = { 60067, 60098 }, ["description"] = "Our forces have control of the House of Constructs, thanks to your intervention. Now, all that remains is the fall of the instigator themselves--Margrave Gharmal. This battle has been long in the making, $p. I am at your side without hesitation. Let us go to this monster. We will join Xandria to see him slain.", ["objectivesText"] = "Meet with Xandria near the central chamber of the House of Constructs.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 180845, 180899, 181285, 182334, 182341 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 166211, ["x"] = 0.288, ["y"] = 0.382 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172002, ["x"] = 0.318, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.382 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61780 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61782] = { ["id"] = 61782, ["name"] = "Pursuit of Justice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61767, 61768, 61769, 61770, 61771, 61772, 61773, 61774, 61775, 61776, 61777, 61778, 61779, 61780, 61781, 61782, 61785, 61876, 61877, 61878 }, ["description"] = "Draka stands ready to unleash the power of the Zerekriss upon Gharmal. We need only buy her time to focus its weapon. What we do now, we do for all of us. Bastion and Maldraxxus have both lost many to these fiends. He will not be defeated easily, but united our forces will finally bring him to justice!", ["objectivesText"] = "Defeat Margrave Gharmal .", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 174294, 177055, 178158, 179945, 180845, 180899, 181285, 182334, 182341 }, ["rewardChoices"] = { 178158, 177055, 179945, 174294 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172002, ["x"] = 0.318, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173193, ["x"] = 0.31, ["y"] = 0.29 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 61781 }, ["questLines"] = { { ["id"] = 1096, ["name"] = "Righteous Retribution", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1096, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
