[61869] = { ["id"] = 61869, ["name"] = "Search the Place", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 57778, 58820, 59722, 60112, 61485, 61518, 61548, 61551, 61569, 61594, 61869, 62169 }, ["description"] = "Zerekriss is ours... along with everything it contains. The Primus was personally involved in the design of this necropolis. It was truly a sight to witness his hands shape the form of this vessel. It would be wise to search the room. Perhaps he kept some tools here that might be of use to us.", ["objectivesText"] = "Check the Foreman's Chest for anything valuable. Progress: What did you find?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 182249 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 164679, ["x"] = 0.463161, ["y"] = 0.443177 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 164679, ["x"] = 0.463161, ["y"] = 0.443177 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.463161, ["y"] = 0.443177 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 164679, ["questType"] = "standard", ["sourceQuests"] = { 61594 }, ["questLines"] = { { ["id"] = 1134, ["name"] = "Grand Theft Necropolis", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1134, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
