[61880] = { ["id"] = 61880, ["name"] = "Honored Attendance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 59660, 59661, 61616, 61704, 61705, 61706, 61880, 61882, 61884 }, ["description"] = "It is my humble honor to be the Ember Court's first guest. Please inform Prince Renathal and all of your other compatriots that I will certainly attend whenever you wish to open the gates.", ["objectivesText"] = "Inform Temel that Cryptkeeper Kassir will attend the Ember Court.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 176120 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 61704 }, ["questLines"] = { { ["id"] = 1196, ["name"] = "The Ember Court", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
