[61945] = { ["id"] = 61945, ["name"] = "The Professionals", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61945 }, ["description"] = "Smart move bringing in the specialists, $p. Once you get into this week's Ember Court, be sure to let the specialists know what you want them to do. Breakfist down in the dredger pools can smash or clean things to make the court more Messy or Clean for you. Crooked Crick in the refreshments area can adjust Decadence. Lady Ilinca in the embassy area can adjust Formality. Cosmin the Illusionist on stage can adjust Excitement. Wing Commander Vulpek at the front gates can adjust Danger.", ["objectivesText"] = "Enter the Ember Court, then give orders to one of the specialist staff members.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
