[61950] = { ["id"] = 61950, ["name"] = "Hunting the Wilds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61950 }, ["description"] = "The supply of attuned anima is running low again. I'm surprised that we've managed to stretch our resources so far without a resupply. You've proven yourself proficient at tracking down what is needed, perhaps you could assist us once again? The runestags that roam Ardenweald's forests are particularly suffused with the power of the wilds, anima retrieved from them will be optimal for our needs. Good hunting!", ["objectivesText"] = "Collect 10 Feral Anima from Runestags. Progress: Worry not about the runestags, after some time they will return. This is just one part of the eternal cycle.", ["rewardGold"] = 257400, ["rewardItems"] = { 175713, 175740, 179517, 179532, 181401, 181402, 181407, 181409, 181410, 181418, 181425, 181457, 181458, 181459, 181477, 181479, 181541, 182387, 184378, 184381, 184382, 184383, 184384, 184487, 184519 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173282, ["x"] = 0.596, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173282, ["x"] = 0.596, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
