[61963] = { ["id"] = 61963, ["name"] = "Called to the Hunt", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61963 }, ["series"] = { 61358, 61360, 61965 }, ["description"] = "The Wild Hunt is made up of fae who have dedicated their lives to the protection of Ardenweald and its denizens. Each member has skill sharp as a blade and sense unlike no other. We have spoken to a duo, an evoker and a huntress, who will permit us to capture their memories for training if we help them on a particular hunt. Meet Alderyn in Claw's Edge. He is one you seek.", ["objectivesText"] = "Find Alderyn in Claw's Edge in Ardenweald. Progress: You are not of these lands. How may I aid you?", ["rewardGold"] = 257400, ["rewardItems"] = { 178995, 179378, 180477, 180478, 180594, 180595, 181274, 182580 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173402, ["x"] = 0.512, ["y"] = 0.743 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533, 1565 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 61358 } },
[61965] = { ["id"] = 61965, ["name"] = "Piercing the Shell", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61965 }, ["series"] = { 61358, 61360, 61963 }, ["description"] = "Our quarry is one of the gorm, native creatures who were once helpful beasts of the realm, until the drought drove them mad. This particular beast has not only grown to a frightening size, but also has a shell so strong that none of our weapons or arrows have managed to pierce it. This spear you bring, infused with the anima of Bastion, could be the exact weapon we need to pierce the gorm's armor and put him down. My sister went ahead to scout. Let's not linger.", ["objectivesText"] = "Find Myn'ir in the Gormhive, then kill the Fortified Desiccator .", ["rewardGold"] = 514800, ["rewardItems"] = { 178995, 179378, 180477, 180478, 180594, 180595, 181274, 182580 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173402, ["x"] = 0.512, ["y"] = 0.743 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173403, ["x"] = 0.518, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.743 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 61963 } },
[61967] = { ["id"] = 61967, ["name"] = "Remedial Lessons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61967 }, ["objectivesText"] = "Ancient Instructors restored Manifestations of Pride slain Speak to Voitha", ["rewardXP"] = 8165, ["rewardItems"] = { 182457, 182458, 182477 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Ancient Instructors restored", ["amount"] = 3, ["type"] = 0, ["objectID"] = 173426, ["orderIndex"] = 0 }, { ["text"] = "Manifestations of Pride slain", ["amount"] = 15, ["type"] = 0, ["objectID"] = 156364, ["orderIndex"] = 1 }, { ["text"] = "Speak to Voitha", ["amount"] = 1, ["type"] = 0, ["objectID"] = 156327, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[61968] = { ["id"] = 61968, ["name"] = "Just Wing It", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61968 }, ["description"] = "For untold ages, the humble Ardenmoth has supplied the scales for the creation of armor for the Wild Hunt . Now, with our attention divided between the threats to the realm and the anima drought, it has become increasingly difficult for our foragers to find the perfect scales that we require. Only the scales of the highest quality are suitable. If you should obtain any in your travels and return with them, I shall ensure you are well rewarded.", ["objectivesText"] = "Collect 28 Perfect Ardenmoth Wing Scales from Ardenmoths. Progress: Have you the scales?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175740, 179517, 181399, 181400, 181401, 181402, 181403, 181404, 181405, 181406, 181411, 181412, 181413, 181415, 181416, 181417, 181425, 181457, 181458, 181459, 181477, 181479, 181541, 182450, 182584, 183467, 184378, 184381, 184382, 184383, 184384, 184487, 184519 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173282, ["x"] = 0.596, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173282, ["x"] = 0.596, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[61981] = { ["id"] = 61981, ["name"] = "Replenish the Reservoir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 59314, 59315, 59321, 59323, 60287, 60289, 61334, 61355, 61981, 62695, 62837, 62856, 62857, 62867, 62868, 62869, 62870, 62882, 62902, 62903, 62904, 62905, 62914, 62915, 62918, 62919, 62920, 62921, 63215 }, ["description"] = "Right, here's the gig: we need anima. Not just a bit or a pinch, but a lot. See, anythin' worth doin' can't be done without anima. Not in the Shadowlands. Not if we are gonna fix this mess Denathrius got us in. So, we need your increasin'ly resourceful self to beg, borrow, steal, nick, burglarize, pulverize, pirate-ize, earn, swindle, or otherwise become the source of a great charity of any anima you can get. Bring it to me, an' I'll stock our coffers, as it were, so you can put it to use.", ["objectivesText"] = "Collect anima sources for the Anima Reservoir at Sinfall in Revendreth. Progress: How goes the anima hunt? You pinch us a pint or boost us keg?", ["rewardGold"] = 1029600, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.555, ["y"] = 0.263, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["ends"] = { { ["x"] = 0.555, ["y"] = 0.263, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.555, ["y"] = 0.263 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 172605, ["questTurnInID"] = 172605, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 25, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61982] = { ["id"] = 61982, ["name"] = "Replenish the Reservoir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["description"] = "Hail, Maw Walker. As our influence over Bastion grows, so too does our need for our most precious resource--anima. We must replenish our reserves. Scour the realms for all that you can find and return here with the anima. With our precious reserves replenished, we can direct the anima wherever it is needed most. Go in service, <class>.", ["objectivesText"] = "Collect anima sources for the Anima Reservoir at Elysian Hold in Bastion. Progress: Every drop of anima is a gift in these times.", ["rewardGold"] = 1029600, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 28, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[61983] = { ["id"] = 61983, ["name"] = "Replenish the Reservoir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59609, 60287, 60289, 61333, 61355, 61359, 61388, 61397, 61983, 62833, 62834, 62835, 62837, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 62864, 62865, 62866, 62882, 63003, 63212, 65157, 65165 }, ["description"] = "We require your strength, Maw Walker. The houses of our enemies grow stronger by the hour. In order to press the attack we must find new sources of anima to bolster our reserves. Search the realms for this precious resource and bring it back here to the Sanctum. Let none deny you! With your help the rival houses shall fall, one by one, and we will emerge victorious!", ["objectivesText"] = "Collect anima sources for the Anima Reservoir at Seat of the Primus in Maldraxxus. Progress: The march to victory will require more anima.", ["rewardGold"] = 1029600, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161909, ["questTurnInID"] = 161909, ["questType"] = "standard", ["sourceQuests"] = { 59609 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 26, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[61984] = { ["id"] = 61984, ["name"] = "Replenish the Reservoir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1702, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["description"] = "Greetings, Maw Walker. The Tirna Achiad, Heart of Ardenweald, flourishes in our care, yet more anima is needed for our Sanctum. The cycle of rebirth, our purpose, must continue. To help our Queen, we must acquire more. Will you help us replenish the reservoir?", ["objectivesText"] = "Collect anima sources for the Anima Reservoir at the Heart of the Forest in Ardenweald. Progress: Have you come to dedicate anima to our sacred purpose?", ["rewardGold"] = 1029600, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.505, ["y"] = 0.629, ["mapID"] = 1702, ["npcID"] = 167196 } }, ["ends"] = { { ["x"] = 0.505, ["y"] = 0.629, ["mapID"] = 1702, ["npcID"] = 167196 } }, ["coords"] = { ["mapID"] = 1702, ["x"] = 0.505, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167196, ["questTurnInID"] = 167196, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 31, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1702 },
[61985] = { ["id"] = 61985, ["name"] = "Wake The Sleepers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61985 }, ["description"] = "The land speaks to me, <name>. Ardenweald is a realm of cycles, but it has never faced an anima drought such as this. We will need the aid of all who reside here if we are to make it through this crisis. Many souls slumber within the forests and hills. If they can provide us some of their anima, we may be able to endure a little longer. Should you encounter any of the souls in your travels, please awaken them and send them to me.", ["objectivesText"] = "Awaken 8 Slumbering Souls .", ["rewardGold"] = 257400, ["rewardItems"] = { 175713, 175728, 175740, 179517, 179532, 179547, 179562, 181401, 181402, 181407, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181457, 181459, 181477, 181479, 181541, 184378, 184381, 184382, 184383, 184384, 184487, 184519 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173277, ["x"] = 0.596, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173277, ["x"] = 0.596, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[61996] = { ["id"] = 61996, ["name"] = "Say The Magic Words", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61996 }, ["description"] = "Ever since I cast my first spell, I've not been able to get enough of magic! It's not as hard as all those liches say it is. You focus your thoughts, say the words, and magic starts happening! There are tomes documenting ancient spells stored in the Archivam of Revendreth. Help me gather them so I can learn some new spells!", ["objectivesText"] = "Help Sabrina learn 12 new spells in Revendreth.", ["rewardXP"] = 8165, ["rewardItems"] = { 182474, 182485, 182494, 182503, 182512, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159226, ["x"] = 0.548, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57600 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61998] = { ["id"] = 61998, ["name"] = "Legacy of Stone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61998 }, ["objectivesText"] = "Progress: We got room for another big statue on this here spot. You get me some stone and I'll make whatever kind of statue you want, yeah? Maybe one of you, or someone else, yeah?", ["rewardItems"] = { 182211 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173065, ["x"] = 0.664, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173065, ["x"] = 0.664, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[62000] = { ["id"] = 62000, ["name"] = "Choosing Your Purpose", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 62000, 62159, 62704, 62716 }, ["series"] = { 62704, 62716 }, ["description"] = "Each covenant is vital to the Shadowlands. Though they have been isolated and divided as of late, the Purpose depends on the success of their efforts. All of the covenants must bolster their strength to face the threat of the Banished One. But your contributions cannot be divided. They must be focused upon a single path. Other mortals may make a different choice. Speak to your potential allies. Then make your choice at the map of the Shadowlands before me.", ["objectivesText"] = "Speak to the Covenants. Decide how your path is entwined with the Purpose. Progress: Have you made your decision?", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.7, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.388, ["y"] = 0.7, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.388, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 62716 }, ["questLines"] = { { ["id"] = 1175, ["name"] = "Aiding the Shadowlands", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1197, ["name"] = "Choosing Your Purpose (DNT)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1175, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[62041] = { ["id"] = 62041, ["name"] = "In A Bad Light", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62041 }, ["description"] = "I've heard about the chaos in Revendreth. Reports of exiles driven mad and burned in the Desiccation. The very thought of all that suffering fills me with the urge to do something about it. If you are headed there, please let me accompany you. I simply must help as many as I can!", ["objectivesText"] = "Use Roseboil 's Regenerative Molt to cure 15 Light-Seared Exiles. Progress: Did we cure them all?", ["rewardXP"] = 8165, ["rewardItems"] = { 178680, 182487, 182496, 182505, 182514, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 159241, ["x"] = 0.55, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57605 } },
[62043] = { ["id"] = 62043, ["name"] = "Prove Your Worth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["storyline"] = { 62043 }, ["description"] = "You must prove your worth to us again <name>. We have not forgotten your betrayal. Yet you say you seek penance. This task will start to demonstrate that you are serious about earning back our trust.", ["objectivesText"] = "Complete the task for the Kyrian.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 163604 }, ["starts"] = { { ["x"] = 0.362, ["y"] = 0.642, ["mapID"] = 1670, ["npcID"] = 171787 } }, ["ends"] = { { ["x"] = 0.362, ["y"] = 0.642, ["mapID"] = 1670, ["npcID"] = 171787 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.362, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questGiverID"] = 171787, ["questTurnInID"] = 171787, ["questType"] = "standard" },
[62044] = { ["id"] = 62044, ["name"] = "Standing Toe To Toe", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 62044 }, ["description"] = "<The gorger is clearly bigger, it gestures with its head towards one of the other gorgers as if urging you to attack it.>", ["objectivesText"] = "Defeat devourer gorgers. Progress: Attack and defeat devourer gorgers in the Endmire.", ["rewardXP"] = 4085, ["rewardItems"] = { 173939, 180583, 182589, 182594 }, ["starts"] = { { ["x"] = 0.6, ["y"] = 0.58, ["mapID"] = 1525, ["npcID"] = 174482 } }, ["ends"] = { { ["x"] = 0.6, ["y"] = 0.58, ["mapID"] = 1525, ["npcID"] = 174482 } }, ["coords"] = { ["mapID"] = 1525, ["x"] = 0.6, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 174482, ["questTurnInID"] = 174482, ["questType"] = "standard", ["sourceQuests"] = { 61844 } },
[62045] = { ["id"] = 62045, ["name"] = "Ready for More", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["storyline"] = { 62045 }, ["description"] = "<Again the gorger is strutting ready for more fighting, staring down the the closest gorger.>", ["objectivesText"] = "Defeat devourer gorgers. Progress: Attack and defeat devourer gorgers in the Endmire.", ["rewardXP"] = 4085, ["rewardItems"] = { 182586 }, ["starts"] = { { ["x"] = 0.6, ["y"] = 0.58, ["mapID"] = 1525, ["npcID"] = 174482 } }, ["ends"] = { { ["x"] = 0.6, ["y"] = 0.58, ["mapID"] = 1525, ["npcID"] = 174482 } }, ["coords"] = { ["mapID"] = 1525, ["x"] = 0.6, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 174482, ["questTurnInID"] = 174482, ["questType"] = "standard", ["sourceQuests"] = { 62044 } },
[62046] = { ["id"] = 62046, ["name"] = "A New Pack", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["storyline"] = { 62046 }, ["description"] = "<The gorger is more than fully grown, rivaling most of the other devourers in the area. It clearly wants to stay with you, but it appears to be uneasy straying too far from the world eaters. Maybe if you take one down together it will not hold as much sway over the gorger.>", ["objectivesText"] = "Defeat an Unbidden Worldeater . Progress: <The gorger gestures in the direction of a worldeater, seemingly feeling up to the challenge with you by its side.>", ["rewardXP"] = 4085, ["rewardItems"] = { 182589 }, ["starts"] = { { ["x"] = 0.6, ["y"] = 0.58, ["mapID"] = 1525, ["npcID"] = 174482 } }, ["ends"] = { { ["x"] = 0.6, ["y"] = 0.58, ["mapID"] = 1525, ["npcID"] = 174482 } }, ["coords"] = { ["mapID"] = 1525, ["x"] = 0.6, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questGiverID"] = 174482, ["questTurnInID"] = 174482, ["questType"] = "standard", ["sourceQuests"] = { 62045 } },
[62051] = { ["id"] = 62051, ["name"] = "Gormling Toss: Spirit Glen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62051 }, ["objectivesText"] = "Gormling in a Bag acquired Wayward Gormlings knocked down and bagged", ["rewardXP"] = 8165, ["rewardItems"] = { 182600, 184487 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Gormling in a Bag acquired", ["amount"] = 1, ["type"] = 0, ["objectID"] = 173520, ["orderIndex"] = 0 }, { ["text"] = "Wayward Gormlings knocked down and bagged", ["amount"] = 8, ["type"] = 0, ["objectID"] = 173521, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest", ["db2WidgetSetID"] = 472 },
[62052] = { ["id"] = 62052, ["name"] = "Exiled by Paranoia", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62052 }, ["series"] = { 61367, 61368, 62053 }, ["description"] = "The liches of the House of Rituals were an instrumental piece in the Maldraxxi attack on Bastion. They are not currenty our allies, and it would be difficult to convince one to let us capture their memory for our training purposes. We have made contact with a necromancer who has a score to settle with one of the liches. Find her and she will aid you in capturing this memory.", ["objectivesText"] = "Find Karaxi the Defector in the Challenger's Promenade in Maldraxxus. Progress: <Karaxi is sifting through a book very carefully.>", ["rewardGold"] = 257400, ["rewardItems"] = { 181278 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173495, ["x"] = 0.576, ["y"] = 0.416667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533, 1536 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 61367 } },
[62053] = { ["id"] = 62053, ["name"] = "Necromantic Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62053 }, ["series"] = { 61367, 61368, 62052 }, ["description"] = "My old master, Thran'tiok, is the epitome of paranoia. She believes everybody will turn on her, and it led to my exilement from not only her service, but the House of Rituals as a whole. I had no intent to cross her... but that has changed. Take the crystal casing you have built and slay my old colleagues to infuse it with necromantic energy. It shall lead you to Thran'tiok's phylactery, which should be exactly what we both seek.", ["objectivesText"] = "Charge the Soulseeker Crystal by defeating foes in the House of Rituals, then use it to find Thran'tiok's phylactery. Progress: Thran'tiok thinks I am a threat... I will show her what that word truly means.", ["rewardGold"] = 257400, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173495, ["x"] = 0.576, ["y"] = 0.416667 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173495, ["x"] = 0.576, ["y"] = 0.416667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.416667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 62052 } },
[62054] = { ["id"] = 62054, ["name"] = "Castle Nathria: Getting a Head", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13224, ["storyline"] = { 62054 }, ["description"] = "We need to show Denathrius that we mean business. His dredger... pet... should do the trick. Bring me his head. Four times should do it. Dredgers are curious creatures.", ["objectivesText"] = "Collect 4 Sludgefist's Head from Sludgefist within Castle Nathria on Normal Difficulty. Progress: I need the heads or we cannot make a profound statement.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 182601 }, ["starts"] = { { ["npcID"] = 172653 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13224 } }, ["questGiverID"] = 172653, ["questType"] = "raid" },
