[62057] = { ["id"] = 62057, ["name"] = "Those Who Hunger", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62057 }, ["description"] = "I've heard reports that the number of gorm sightings have risen greatly the past few days. Normally they're simple decomposers, playing their part in the great cycle, but in great numbers the gorm can be aggressive. If left unchecked, their ravenous hunger will cause untold destruction. The Wild Hunt has called for a gorm hunt. Meet your quota and you will be well-rewarded.", ["objectivesText"] = "Destroy 20 Gorm in Ardenweald.", ["rewardGold"] = 257400, ["rewardItems"] = { 175740, 179517, 179532, 181402, 181404, 181405, 181406, 181415, 181416, 181418, 181420, 181421, 181424, 181425, 181426, 181428, 181429, 181430, 181477, 181479, 181541, 182464, 184378, 184381, 184382, 184383, 184384, 184487, 184519 }, ["rewardCurrencies"] = { { ["id"] = 1885, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173282, ["x"] = 0.596, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173282, ["x"] = 0.596, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
