[62062] = { ["id"] = 62062, ["name"] = "Restock: Stolen Rugs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62062 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, those thieves steal more than memories. They steal rugs too! New rugs be so heavy thieves can't carry! Bring me things to make heavy rugs. Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171840, 173202 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62064] = { ["id"] = 62064, ["name"] = "Restock: Broken Mirrors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62064 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, those prisoners break all the mirrors when they escape! Laurent help me fix, but need pieces. Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173109 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62065] = { ["id"] = 62065, ["name"] = "Restock: My Favorite Table", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62065 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, one of them big bad dredgers sit on my favorite table, break in half! Need wood to fix table. Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 177061 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62066] = { ["id"] = 62066, ["name"] = "Restock: Dredger Pool", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62066 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, that big slimeball leaked slimeball slime into our muckpool. Every new dredger all slimy! Need way to get rid of all bad stuff... You know thing does that? Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171263 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62067] = { ["id"] = 62067, ["name"] = "Restock: Statues", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62067 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, dredgers see big new statue made. All want statues now! Bring me stone and I carve tiny statues to hold. Make all dredgers happy. Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171840 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
