[62170] = { ["id"] = 62170, ["name"] = "You'll Never Walk Alone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62170 }, ["description"] = "<You have stumbled upon some messy notes. Some of the lines seem incomprehensible while others seem melodic.> Like wind and rain, discord storms my mind, tossing and blowing. ... I must find the golden skies. ... Remember, walk on, heart full of hope, and you'll never walk alone. <It seems as though an aspirant cannot find their way home. You should inform someone at Hero's Rest.>", ["objectivesText"] = "Turn these notes in to Inkiep in Hero's Rest.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 179363 }, ["starts"] = { { ["x"] = 0.593, ["y"] = 0.609, ["mapID"] = 1533 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160173, ["x"] = 0.532, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["startItems"] = { 182693 } },
