[62232] = { ["id"] = 62232, ["name"] = "Arboreal Tactics", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62232 }, ["description"] = "The spriggan of Ardenweald have always been a nuisance. But under Mueh'zala's influence, they could grow into a threat that looms over all of the Shadowlands. Let's test these troops against a real opponent.", ["objectivesText"] = "Eliminate 12 Bristlecone Spriggan in Mistveil Tangle in Ardenweald.", ["rewardXP"] = 8165, ["rewardItems"] = { 178679, 182482, 182491, 182500, 182509, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 158301, ["x"] = 0.542, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 57611 } },
[62234] = { ["id"] = 62234, ["name"] = "Power of the Colossus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["description"] = "I have another task for you, Maw Walker. Deep within Perdition Hold, there lurks a menacing mechanization known as the Soulsteel Colossus. It must be destroyed before it wreaks havoc upon us. Travel to the Hold, and then across the bridge into the Altar of Domination. There, casting its vast shadow upon The Maw , you will find the Soulsteel Colossus. Shatter the colossus and bring me its power source as proof of your victory.", ["rewardItems"] = { 177698, 178874, 178881, 178882, 185717 }, ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 600 } }, ["starts"] = { { ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416, ["mapID"] = 1543 } }, ["ends"] = { { ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416, ["mapID"] = 1543 } }, ["coords"] = { ["x"] = 0.468, ["y"] = 0.416, ["source"] = "quest_giver", ["mapID"] = 1543 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "group" },
