[62237] = { ["id"] = 62237, ["name"] = "Mysterious Soul Mirror", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62237 }, ["description"] = "<A shimmering soul mirror draws your attention on Devos's corpse. Peculiar that she would keep one on her person. Perhaps Thenios will want to see this.>", ["objectivesText"] = "Bring the Mysterious Soul Mirror to Thenios at the temple in the Eonian Archives. Progress: How can I be of service?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 183054 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 }, { ["mapID"] = 1533, ["npcID"] = 173771, ["x"] = 0.402, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["startItems"] = { 183054 } },
[62238] = { ["id"] = 62238, ["name"] = "Soul Led Astray", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62238 }, ["description"] = "Uther was a being of justice on your world. I am sure it was quite surprising for you to see his fate here, following a leader who embodies what he stood against in life. I believe you should witness this memory firsthand. Take it to my soul mirror. View the memories within.", ["objectivesText"] = "Use the Soul Mirror at the Eonian Archives to view Uther's arrival in Bastion . Progress: Sometimes the hard truths are the most important to witness.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 }, { ["mapID"] = 1533, ["npcID"] = 173771, ["x"] = 0.402, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 }, { ["mapID"] = 1533, ["npcID"] = 173771, ["x"] = 0.402, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 62237 } },
[62239] = { ["id"] = 62239, ["name"] = "Rodent Removal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 62239 }, ["description"] = "<The weapon buzzes with a dark, static energy. Whatever this Mawsworn was testing, it appears to have been somewhat successful on the nearby rodents. Further investigation may yield additional information.>", ["objectivesText"] = "Test the Tormentor's Rod on 8 Giant Mawrats in The Beastwarrens.", ["rewardItems"] = { 137663, 177698, 178874, 178881, 178882, 183105 }, ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 400 } }, ["starts"] = { { ["x"] = 0.603, ["y"] = 0.721, ["mapID"] = 1543, ["objectID"] = 365084 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[62241] = { ["id"] = 62241, ["name"] = "Training Regimen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62241 }, ["objectivesText"] = "Gatamatos retrieved Speak to Pelodis First formation complete Second formation complete Third formation complete Gatamatos placed", ["rewardXP"] = 8165, ["rewardItems"] = { 183121 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Gatamatos retrieved", ["amount"] = 1, ["type"] = 14, ["objectID"] = 87409, ["orderIndex"] = 0 }, { ["text"] = "Speak to Pelodis", ["amount"] = 1, ["type"] = 0, ["objectID"] = 158765, ["orderIndex"] = 4 }, { ["text"] = "First formation complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 159878, ["orderIndex"] = 5 }, { ["text"] = "Second formation complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 159888, ["orderIndex"] = 6 }, { ["text"] = "Third formation complete", ["amount"] = 1, ["type"] = 0, ["objectID"] = 159889, ["orderIndex"] = 7 }, { ["text"] = "Gatamatos placed", ["amount"] = 1, ["type"] = 0, ["objectID"] = 159686, ["orderIndex"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[62244] = { ["id"] = 62244, ["name"] = "Digging Around", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62244 }, ["description"] = "The thin pale ones of Revendreth have been hoarding anima. I've heard they've been hiding it away, digging holes in the woods and just leaving it there. Anyone could come along and take it. I say that should be us! Let's go get some anima.", ["objectivesText"] = "Collect 15 Lost Anima Caches .", ["rewardXP"] = 8165, ["rewardItems"] = { 182488, 182497, 182506, 182515, 183043, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159212, ["x"] = 0.548, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 58414 } },
[62246] = { ["id"] = 62246, ["name"] = "A Fallen Friend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62246 }, ["description"] = "A bracelet delicately woven with living vines falls from Vivanna's wrist as she is slain. In the vines is written, \"Until Winter's end. - Flwngyrr \"", ["objectivesText"] = "Return this bracelet to Flwngyrr at the Heart of the Forest Provided item:", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 178217, 183091 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 168032, ["x"] = 0.484, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["startItems"] = { 183091 } },
[62250] = { ["id"] = 62250, ["name"] = "A New Adventure Awaits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 62250 }, ["description"] = "<name>! You're needed in the present. Things have... well, you should just come back to see. I would finish what you're doing then head back. I can't keep you in the past for much longer!", ["objectivesText"] = "Return to Stormwind to embark on a new adventure. Chromie 's magic will run out soon, returning you to Stormwind.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 183185 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101759, ["x"] = 0.762, ["y"] = 0.172 }, { ["mapID"] = 84, ["npcID"] = 172334, ["x"] = 0.625333, ["y"] = 0.306 }, { ["mapID"] = 84, ["npcID"] = 189569, ["x"] = 0.618, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[62256] = { ["id"] = 62256, ["name"] = "Asset Extraction", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Hey, it's my good pal ! Listen, I'm in a bit of a bind here. I've been trying to negotiate a deal with the broker Au'larrynar and he needs a little something, a job done before he'll accept. The deal is he had an associate who went missing with a rare item. He's asked that I... we... locate and return the missing property. The associate was last seen in Ardenweald. I know, strange place, way too bright for me. But, I... we... really need this deal to go through! So, you ready to go?", ["rewardXP"] = 8165, ["rewardItems"] = { 183744, 184843 }, ["starts"] = { { ["npcID"] = 158259, ["x"] = 0.504, ["y"] = 0.474, ["mapID"] = 1536 }, { ["npcID"] = 159238, ["x"] = 0.552, ["y"] = 0.682, ["mapID"] = 1536 } }, ["ends"] = { { ["npcID"] = 166640, ["x"] = 0.536, ["y"] = 0.478, ["mapID"] = 1536 } }, ["coords"] = { ["x"] = 0.504, ["y"] = 0.474, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 58410 } },
