[62308] = { ["id"] = 62308, ["name"] = "Mantle of Mastery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62308 }, ["description"] = "You have done much to establish yourself as a promising acolyte. Your superiors have made it known that you are ready to be tested for your ritualist's mantle . When you are ready, begin the Ritual of Ancient Summoning to call forth an elder spirit of Maldraxxus . Conquer the spirit, and prove your mettle!", ["objectivesText"] = "Summon an elder spirit of Maldraxxus through the Prime Arcanum and defeat it. Summoning requires three players.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 183399, 183847, 187869 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172813, ["x"] = 0.679, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172813, ["x"] = 0.679, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.679, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "group", ["sourceQuests"] = { 61754, 61755 } },
