[62371] = { ["id"] = 62371, ["name"] = "Tirna Scithe: A Warning Silence", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62371 }, ["description"] = "The songs of Tirna Scithe have faded as the grove wanes, yet there is now silence. Droman Oulfarran's voice has not been heard in some time. The trees whisper of penumbral shadows, discordant songs, and dying roots. All is not well. Friend of Ardenweald, travel to Root-home. Delve into the Mists. Remove that which threatens us.", ["objectivesText"] = "Defeat Tred'ova in The Mists of Tirna Scithe. Progress: What has silenced the grove of Tirna Scithe?", ["rewardGold"] = 1029600, ["rewardXP"] = 13630, ["rewardItems"] = { 184515, 184516, 184517, 184518 }, ["rewardChoices"] = { 184516, 184517, 184518, 184515 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 168032, ["x"] = 0.484, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 168032, ["x"] = 0.484, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 60905 }, ["questLines"] = { { ["id"] = 1188, ["name"] = "Tirna Scithe: A Warning Silence", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
