[62382] = { ["id"] = 62382, ["name"] = "Into the Unknown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62382 }, ["description"] = "Come to pay old Marasmius a visit? I have a special task for you. One of my shoots has found a strange place, a place even I've never seen before. I'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for! What do you say, <name>? Up for an adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: Keep your guard up. It could lead anywhere!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 179500, 179508, 179513, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181403, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181419, 181420, 181421, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181430, 181457, 181458, 181459, 181477, 181479, 181541, 182469, 182605, 183132, 183167, 183466, 183473, 183479, 183482, 183485, 183487, 184381, 184382, 184383, 184384 }, ["starts"] = { { ["x"] = 0.536, ["y"] = 0.527, ["mapID"] = 1819, ["npcID"] = 167455 } }, ["ends"] = { { ["x"] = 0.536, ["y"] = 0.527, ["mapID"] = 1819, ["npcID"] = 167455 } }, ["coords"] = { ["mapID"] = 1819, ["x"] = 0.536, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questGiverID"] = 167455, ["questTurnInID"] = 167455, ["questType"] = "standard", ["sourceQuests"] = { 57583 } },
