[62452] = { ["id"] = 62452, ["name"] = "A Spirit's Might", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62452 }, ["description"] = "I seek to understand more about the Martial beings in this realm. If you could place one in a wildseed, as you did for me, I could observe the restoration process.", ["objectivesText"] = "Place a Martial Spirit into a wildseed. Progress: Find a Martial spirit to restore. That is what I wish to see today.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176832, 176921, 176922 }, ["rewardChoices"] = { 176922, 176921, 176832 }, ["starts"] = { { ["x"] = 0.24, ["y"] = 0.533, ["mapID"] = 1662, ["npcID"] = 174329 } }, ["ends"] = { { ["x"] = 0.24, ["y"] = 0.533, ["mapID"] = 1662, ["npcID"] = 174329 } }, ["coords"] = { ["mapID"] = 1662, ["x"] = 0.24, ["y"] = 0.533 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questGiverID"] = 174329, ["questTurnInID"] = 174329, ["questType"] = "standard", ["sourceQuests"] = { 62454 } },
[62453] = { ["id"] = 62453, ["name"] = "Into the Unknown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62453 }, ["description"] = "Come to pay old Marasmius a visit? I have a special task for you. One of my shoots has found a strange place, a place even I've never seen before. I'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for! What do you say, <name>? Up for an adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: Keep your guard up. It could lead anywhere!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 179500, 179508, 179513, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181403, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181419, 181420, 181421, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181430, 181457, 181458, 181459, 181477, 181479, 181541, 182469, 182605, 183132, 183167, 183466, 183473, 183479, 183482, 183485, 183487, 183961, 183963, 184381, 184382, 184383, 184384 }, ["rewardCurrencies"] = { { ["id"] = 1877, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.536, ["y"] = 0.527, ["mapID"] = 1819, ["npcID"] = 167455 } }, ["ends"] = { { ["x"] = 0.536, ["y"] = 0.527, ["mapID"] = 1819, ["npcID"] = 167455 } }, ["coords"] = { ["mapID"] = 1819, ["x"] = 0.536, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 167455, ["questTurnInID"] = 167455, ["questType"] = "standard", ["sourceQuests"] = { 57583 } },
[62454] = { ["id"] = 62454, ["name"] = "A Rare and Unusual Spirit", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62454 }, ["description"] = "I awaken. I exist once more. And yet... There is an emptiness within. A lingering tether to a home that no longer exists. So much wonder... so much splendor... lost. Now I have no purpose. No fate. No path. Will you teach me of this place, awakener? I sense there is much to be understood. Many secrets. Many truths. In so doing, perhaps a new fate will emerge.", ["objectivesText"] = "Speak to Falir and bring them essences from the realms of the Shadowlands. Progress: Return to me when you have the essences from each realm.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 183704, 183805, 183806 }, ["starts"] = { { ["x"] = 0.24, ["y"] = 0.533, ["mapID"] = 1662, ["npcID"] = 174329 } }, ["ends"] = { { ["x"] = 0.24, ["y"] = 0.533, ["mapID"] = 1662, ["npcID"] = 174329 } }, ["coords"] = { ["mapID"] = 1662, ["x"] = 0.24, ["y"] = 0.533 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questGiverID"] = 174329, ["questTurnInID"] = 174329, ["questType"] = "standard", ["sourceQuests"] = { 62447 } },
[62456] = { ["id"] = 62456, ["name"] = "De Other Side: Dealin' Wit' Da Boss", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13309, ["storyline"] = { 62456 }, ["series"] = { 62458 }, ["description"] = "Ay, mon. Long time no see! I be havin' a bit of trouble wit' me boss, Mueh'zala. Now, now... don't you worry. Your ol' friend Bwonsamdi got dis whole ting under control! I just be needin' some help gatherin' me mojo back from a few ungrateful business partners. You bring me da mojo, and we goin' ta take care of ol' Mueh'zala once and for all!", ["objectivesText"] = "Defeat Mueh'zala in De Other Side. Progress: First you get da mojo, then I get da powa'... then we be gettin' Mueh'zala!", ["rewardItems"] = { 184519 }, ["starts"] = { { ["npcID"] = 174327 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13309 } }, ["questGiverID"] = 174327, ["questType"] = "dungeon", ["sourceQuests"] = { 62458 } },
[62458] = { ["id"] = 62458, ["name"] = "De Other Side", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62458 }, ["series"] = { 62456 }, ["description"] = "Ay, dere <name>! Ya be just da <class> I've been lookin' for! It be your ol' pal Bwonsamdi reachin' out ta ya from De Other Side! I be havin' a little problem over here wit' de boss... Ya be lookin' mighty bored just standin' around here in Ardenweald. Why don't ya come to De Other Side and help out an ol' friend? Bwonsamdi promise he gonna make it worth ya while! Ya might want ta bring a few more adventurers wit' ya... just ta be safe.", ["objectivesText"] = "Speak with the Mask of Bwonsamdi in De Other Side.", ["rewardGold"] = 25740, ["rewardXP"] = 2090, ["rewardItems"] = { 1804, 1805, 1806, 1807, 177904, 184374, 184519 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 174341, ["x"] = 0.648, ["y"] = 0.196 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 174341, ["x"] = 0.648, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questTurnInID"] = 174341, ["questType"] = "dungeon", ["nextQuests"] = { 62456 } },
[62459] = { ["id"] = 62459, ["name"] = "Go Beyond!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62459 }, ["description"] = "Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181420, 181421, 181422, 181423, 181424, 181425, 181427, 181428, 181429, 181430, 181457, 181459, 181461, 181477, 181479, 181541, 183725, 184381, 184382, 184383, 184384, 194371, 194372, 194376, 194393, 194416, 199461, 200960, 204076, 204586, 204594, 204602, 204610, 210024 }, ["rewardCurrencies"] = { { ["id"] = 1877, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.536, ["y"] = 0.527, ["mapID"] = 1819, ["npcID"] = 167455 } }, ["ends"] = { { ["x"] = 0.536, ["y"] = 0.527, ["mapID"] = 1819, ["npcID"] = 167455 } }, ["coords"] = { ["mapID"] = 1819, ["x"] = 0.536, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questGiverID"] = 167455, ["questTurnInID"] = 167455, ["questType"] = "standard", ["sourceQuests"] = { 57583 } },
[62461] = { ["id"] = 62461, ["name"] = "Stalking the Warrens", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["description"] = "So, they are creating magical beasts deep within the Warrens. Their power is... substantial. Maw Walker, I must trust in you to handle this. While I can provide insight, in combat I must admit your prowess exceeds my own. Hunt the beasts that they train to hunt us. Show the Mawsworn that we too can bare fangs.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416, ["mapID"] = 1543 } }, ["ends"] = { { ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416, ["mapID"] = 1543 } }, ["coords"] = { ["x"] = 0.468, ["y"] = 0.416, ["source"] = "quest_giver", ["mapID"] = 1543 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "group", ["sourceQuests"] = { 60285 }, ["questLines"] = { { ["id"] = 1200, ["name"] = "New Rules", ["orderIndex"] = 4, ["flags"] = 0 } } },
[62462] = { ["id"] = 62462, ["name"] = "WANTED: The Key of Eyes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62462 }, ["description"] = "I seek a mercenary of unparalleled might to venture into the House of Eyes and procure the \" Key of Eyes \". Above average compensation is assured for the one who can both deliver the key and regale me with the story of its previous owner's demise. Be warned that the grounds once belonging to the House of Eyes are extremely dangerous and lone exploration is highly discouraged.", ["objectivesText"] = "Eliminate Chelicera and obtain the Key of Eyes . Progress: So, you've seen my posting?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181645, 181647, 181649, 183728, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["x"] = 0.53, ["y"] = 0.414, ["mapID"] = 1536, ["objectID"] = 358382 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 169964, ["x"] = 0.532, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "group", ["questLines"] = { { ["id"] = 1170, ["name"] = "WANTED: The Key of Eyes", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
