[62467] = { ["id"] = 62467, ["name"] = "Seed of a Thought", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["mapID"] = 1662, ["storyline"] = { 59862, 59871, 59872, 59873, 59999, 60640, 60641, 60642, 62467 }, ["description"] = "Within wildseeds, spirits slumber and grow. But so too can catalysts, when seeds take the place of spirits. Seed Merchant Daybreak trades in such seeds. She can supply you with the ones you seek. Choose one to plant within a wildseed. The forest holds its breath and awaits your choice.", ["objectivesText"] = "Acquire a seed and plant it within a wildseed. Progress: Your talents as a cultivator continue to thrive.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 176832, 183522 }, ["starts"] = { { ["x"] = 0.334, ["y"] = 0.62, ["mapID"] = 1662, ["npcID"] = 166476 } }, ["ends"] = { { ["x"] = 0.334, ["y"] = 0.62, ["mapID"] = 1662, ["npcID"] = 166476 } }, ["coords"] = { ["mapID"] = 1662, ["x"] = 0.334, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questGiverID"] = 166476, ["questTurnInID"] = 166476, ["questType"] = "standard", ["sourceQuests"] = { 59871 }, ["questLines"] = { { ["id"] = 1139, ["name"] = "The Queen's Conservatory", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2363, ["db2PoiUiMapID"] = 1662 },
[62473] = { ["id"] = 62473, ["name"] = "What's Old is New", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62473 }, ["description"] = "These damn Scourge make me sick! <Brollen spits on the ground.> They're only good fer one thing--bein' dead! Head tae the valley southwest o' here. Plenty o' gear fer the pickin' over there! Gather up what ye can. I'll make do with what ye find.", ["objectivesText"] = "Gather 8 Jagged Blades and 8 Battleworn Chainmail from the Conflagration. Progress: Find somethin' worth smeltin'?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183757, 183758 }, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 167577, ["x"] = 0.72, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167577, ["x"] = 0.72, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 60932 }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[62477] = { ["id"] = 62477, ["name"] = "Blueprint: Skystrider Glider", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62477 }, ["description"] = "<You have discovered plans for a single use glider, invented by Dresaelus. Dactylis should be able to help you with crafting this kit.>", ["objectivesText"] = "Bring the Blueprint: Skystrider Glider to Dactylis . Provided item:", ["rewardItems"] = { 183761 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 183761 } },
