[62484] = { ["id"] = 62484, ["name"] = "Werk In Progress", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62484 }, ["description"] = "We received an... unusual delivery recently. I'm still in a bit of shock. Some sort of flying contraption released a huge crate just overhead, parachute and all. If it weren't for the wind it would have landed nearby. Instead, it drifted down the hill below. They left a note too. It would have been lost had it not been wrapped around a sizeable rock. < Darkrider Arly massages a spot on her forehead.> I don't know what it is, but if it'll help clear out the area, I'm all for it.", ["objectivesText"] = "Locate the delivery. Use the device on a Reconstructed Abomination, then destroy the Scourge presence at the Fleshwerks. Progress: Any luck locating that thing?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183795 }, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 173997, ["x"] = 0.354, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 173997, ["x"] = 0.354, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 60932 }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[62486] = { ["id"] = 62486, ["name"] = "Blueprint: Empyrean Refreshment", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62486 }, ["description"] = "<You have discovered plans for a table of refreshing snacks that would be quite useful while out adventuring. Dactylis should be able to help you with the crafting.>", ["objectivesText"] = "Bring the Blueprint: Empyrean Refreshment to Dactylis . Provided item:", ["rewardItems"] = { 183794 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 183794 } },
[62536] = { ["id"] = 62536, ["name"] = "The Lost of Teldrassil", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62536 }, ["description"] = "I learned that Sylvanas burned Teldrassil. I felt my heart break for the night elves. And that was only the beginning. We know now that the souls lost that day did not go to their intended rest. But you have the power to begin to correct that, Maw Walker. If you find yourself in the Maw, look for any of those lost. Please, bring them home.", ["objectivesText"] = "Travel to the Maw and rescue Lost Souls.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171138, ["x"] = 0.46, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 171138, ["x"] = 0.46, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questTurnInID"] = 171138, ["questType"] = "standard", ["sourceQuests"] = { 59242 } },
