[62544] = { ["id"] = 62544, ["name"] = "From a Dark Place", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62544 }, ["description"] = "You rescued some of the night elves from the Maw before. While the danger is still great, I must ask you to do it again. I have to believe that we can save them. As many of them as possible. Please, go and see if you can recover any more lost souls.", ["objectivesText"] = "Travel to the Maw and rescue Lost Souls.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.39, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.39, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.446, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 160262, ["questTurnInID"] = 160262, ["questType"] = "standard", ["sourceQuests"] = { 62536 } },
[62546] = { ["id"] = 62546, ["name"] = "No Wisp Left Behind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62546 }, ["description"] = "More of the Kaldorei souls still languish in the Maw. I ask you once again, Maw Walker, to find them. Help correct this wrong.", ["objectivesText"] = "Travel to the Maw and rescue Lost Souls from the Tremaculum and the Planes of Torment.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.39, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.39, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.446, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 160262, ["questTurnInID"] = 160262, ["questType"] = "standard", ["sourceQuests"] = { 62544 } },
[62549] = { ["id"] = 62549, ["name"] = "No Wisp Left Behind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62549 }, ["description"] = "More of the Kaldorei souls still languish in the Maw. I ask you once again, Maw Walker, to find them. Help correct this wrong.", ["objectivesText"] = "Travel to the Maw and rescue Lost Souls from the Tremaculum and the Planes of Torment.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.39, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.39, ["mapID"] = 1701, ["npcID"] = 160262 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.446, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 160262, ["questTurnInID"] = 160262, ["questType"] = "standard", ["sourceQuests"] = { 62546 } },
[62553] = { ["id"] = 62553, ["name"] = "Delaying Their Efforts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62553 }, ["description"] = "The Scourge continue to replenish their weapons of war from blighted grounds. Stopping their workers slows their production, but a decisive blow to their stockpiles would be far more effective. Take these and head to the area southeast of here. Plant the bombs, then make a quick exit. Weakening their supply lines should provide us ample time to retaliate.", ["objectivesText"] = "Plant the bombs at the Northern, Eastern and Western sites of The Bombardment. Remove 12 Decrepit Laborers from the area.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardCurrencies"] = { { ["id"] = 1754, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["sourceQuests"] = { 62157 }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
