[62555] = { ["id"] = 62555, ["name"] = "A Touch of Humility", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 57113, 57114, 57115, 57116, 57117, 57118, 57120, 57121, 57122, 57123, 57124, 57125, 57207, 62555 }, ["series"] = { 57124, 57125 }, ["description"] = "With the Temple of Humility under our control, its power shall flow back into the Crest of Ascension once more. Join me below so that we may witness it together. Mikanikos has ensured it will become even more magnificent as its power grows.", ["objectivesText"] = "Witness the Crest of Ascension become empowered by the Temple of Humility.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 170550 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57125 }, ["questLines"] = { { ["id"] = 1094, ["name"] = "Closing In", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1094, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
