[62557] = { ["id"] = 62557, ["name"] = "Our Realm Reclaimed", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 58844, 58846, 58847, 58854, 59919, 62557 }, ["description"] = "Though Forsworn still fight across Bastion , the Temple of Loyalty is ours, and with it our realm. We will have to stay diligent to maintain control of all of the temples, and much remains to be decided with the fate of our fallen brethren, but today is a day of great victory. Join me at the Crest of Ascension, and witness its final empowerment.", ["objectivesText"] = "Witness the Crest of Ascension become empowered by the Temple of Loyalty.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 180764 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 59919 }, ["questLines"] = { { ["id"] = 1036, ["name"] = "The Bell Tolls", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1036, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
