[62567] = { ["id"] = 62567, ["name"] = "Adventurers Wanted: Chromie's Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 62567 }, ["description"] = "Chromie is seeking veteran adventurers to embark on expeditions through time and space. This is your opportunity to experience the legendary adventures of the past--today! Speak with Chromie near the Stormwind Embassy for more information.", ["objectivesText"] = "Speak with Chromie in Stormwind.", ["rewardGold"] = 13740, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.562, ["y"] = 0.176, ["mapID"] = 84, ["npcID"] = 167032 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 167032, ["x"] = 0.561, ["y"] = 0.174 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.174 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questGiverID"] = 167032, ["questType"] = "standard" },
