[62569] = { ["id"] = 62569, ["name"] = "The Jailer's Grasp", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 61557, 61559, 62569 }, ["description"] = "By peering into the Maw, Bolvar drew the Jailer's attention. His worst fears have come to pass. You must help me break the link, <name>! The fragment of the Helm is the key!", ["objectivesText"] = "Help Jaina Proudmoore sever the Jailer's connection to Bolvar.", ["rewardItems"] = { 184315 }, ["starts"] = { { ["x"] = 0.398, ["y"] = 0.68, ["mapID"] = 1670, ["npcID"] = 170153 } }, ["ends"] = { { ["x"] = 0.398, ["y"] = 0.68, ["mapID"] = 1670, ["npcID"] = 170153 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.398, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 170153, ["questTurnInID"] = 170153, ["questType"] = "standard", ["sourceQuests"] = { 61559 }, ["questLines"] = { { ["id"] = 1138, ["name"] = "Peering into Darkness", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1140, ["name"] = "A Fateful Vision", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 155, ["title"] = "9.0 Covenant Campaigns Ch 3 - Peering Into Darkness", ["questLineID"] = 1138, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1138, ["questLineOrder"] = 4 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1138, ["ques