[62653] = { ["id"] = 62653, ["name"] = "Stop the Inquisition", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62653 }, ["description"] = "The Lord Chamberlain's inquisitors still torment the poor souls trapped under their care. You must put a stop to their wicked deeds! Speak with Archivist Fane, whom you worked with before to defeat an inquisitor, to acquire the sinstone of another inquisitor in the halls. With their sinstone, you will be able to shatter that inquisitor's defenses and lead the charge to defeat them. Bring friends, $p. Many of the inquisitors are far too dangerous to approach alone.", ["objectivesText"] = "Defeat any inquisitor in Halls of Atonement. Archivist Fane can provide Inquisitor Sinstones to help you in your hunt. Progress: Archivist Fane can help you acquire an inquisitor's sinstone.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172996, 173006, 179535, 180376 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167332, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173705, ["x"] = 0.73, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "group", ["sourceQuests"] = { 57929 }, ["questLines"] = { { ["id"] = 1190, ["name"] = "Stop the Inquisition", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[62654] = { ["id"] = 62654, ["name"] = "Maw Walker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1543, ["storyline"] = { 59202, 59874, 59897, 59959, 59960, 59962, 59966, 59973, 59974, 60972, 61190, 62654 }, ["description"] = "I believe now it is time for you to leave. You are a Maw Walker, one who can activate the waystone between the Maw and the lands beyond. While your friends may not hold the same title, there is a way to send them through the gate. Souls can be connected. In theory, if you let someone attune themselves to your soul while you activate the waystone, you both should be able to leave. Even fleeting connections may produce some result. Go with your other two guests and see if my hypothesis is correct.", ["objectivesText"] = "Attune with Darion and Alexandros and assist them in leaving the Maw.", ["rewardGold"] = 245700, ["rewardXP"] = 1415, ["rewardItems"] = { 175511, 175524, 175525, 175526, 178018, 181174 }, ["rewardChoices"] = { 175524, 175526, 175525, 175511 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questTurnInID"] = 162804, ["questType"] = "standard", ["sourceQuests"] = { 59973 }, ["questLines"] = { { ["id"] = 1062, ["name"] = "Ritual for the Damned", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 130, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1062, ["questLineOrder"] = 14 }, { ["id"] = 118, ["title"] = "Blade of the Primus", ["questLineID"] = 1062, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[62691] = { ["id"] = 62691, ["name"] = "A Calling in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 62691 }, ["series"] = { 59323, 62695, 62856, 62857 }, ["description"] = "We got a lot of problems out there, boss. Big ones, little ones, really smelly ones, it's a lot. If we're gonna take on Denathrius, the first thing we gotta do is clean up right here in Revendreth. We get things cleaned up, yeah? Then we get some new allies, and we probably get our hands on some anima to boot. It's a call to action, it is. And it's important that we get started right away. Get on out there and get your boots muddy!", ["objectivesText"] = "Complete 3 World Quests in Revendreth. Progress: What do ya want?", ["rewardItems"] = { 181556 }, ["rewardCurrencies"] = { { ["id"] = 1191, ["amount"] = 35 }, { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.616, ["y"] = 0.756, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["ends"] = { { ["x"] = 0.616, ["y"] = 0.756, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.616, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 165302, ["questTurnInID"] = 165302, ["questType"] = "standard", ["sourceQuests"] = { 62695 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest" },
[62692] = { ["id"] = 62692, ["name"] = "A Calling in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 62692 }, ["series"] = { 57895, 57905, 62698, 62789, 62790, 62791, 62792, 62832 }, ["description"] = "Our forces are weakened by doubt and our temples are under assault. If we are to aid the rest of the Shadowlands, we must begin here, in Bastion. Travel the golden fields and root out evil wherever you may find it. In time, we will rebuild our forces and our anima stores, and stand tall once more. Today, you walk the path of courage--it is your calling. Show our people that doubt will not fester here.", ["objectivesText"] = "Complete 3 World Quests in Bastion. Progress: Do the hills echo with the cries of your victories, Maw Walker?", ["rewardItems"] = { 181372 }, ["rewardCurrencies"] = { { ["id"] = 1191, ["amount"] = 35 } }, ["starts"] = { { ["x"] = 0.522, ["y"] = 0.47, ["mapID"] = 1533, ["npcID"] = 160470 } }, ["ends"] = { { ["x"] = 0.522, ["y"] = 0.47, ["mapID"] = 1533, ["npcID"] = 160470 } }, ["coords"] = { ["mapID"] = 1533, ["x"] = 0.522, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 160470, ["questTurnInID"] = 160470, ["questType"] = "standard", ["sourceQuests"] = { 62698 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest" },
[62693] = { ["id"] = 62693, ["name"] = "A Calling in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 62693 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Ardenweald is fractured, its roots strangled. Before we can begin to regrow our glades, we must unearth the evils that have festered here. We call to you, today, to defend our forests. Take the weald paths through our lands, aiding our allies and defeating our enemies. With these actions, we will renew our forces, and rebuild our anima. In time, hope will blossom. Our trust is in you, our newest seedling.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald. Progress: Have you brought hope and faith to our people today?", ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1191, ["amount"] = 35 }, { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.538, ["y"] = 0.062, ["mapID"] = 1701, ["npcID"] = 165702 } }, ["ends"] = { { ["x"] = 0.538, ["y"] = 0.062, ["mapID"] = 1701, ["npcID"] = 165702 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.538, ["y"] = 0.062 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 165702, ["questTurnInID"] = 165702, ["questType"] = "standard", ["sourceQuests"] = { 62697 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest" },
[62694] = { ["id"] = 62694, ["name"] = "A Calling in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 62694 }, ["series"] = { 62833, 62834, 62835 }, ["description"] = "Today marks the beginning of our path to victory. Enemies surround us on all sides. Aid our troops on the battlefield and return with the resources we need to wage our war. Once we have secured our home front, we can direct our efforts outwards. Such is your calling. Failure is unacceptable.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus. Progress: How goes the battle?", ["rewardItems"] = { 181732 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.477, ["y"] = 0.291, ["mapID"] = 1698, ["npcID"] = 158339 } }, ["ends"] = { { ["x"] = 0.477, ["y"] = 0.291, ["mapID"] = 1698, ["npcID"] = 158339 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.477, ["y"] = 0.291 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 158339, ["questTurnInID"] = 158339, ["questType"] = "standard", ["sourceQuests"] = { 62835 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest" },
[62695] = { ["id"] = 62695, ["name"] = "A Call to Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 59323, 62691, 62856, 62857 }, ["description"] = "An opportunity has arisen that will be perfect for you to display your... prowess... to the denizens of Revendreth. Speak with Rendle . That dredger is disturbingly effective when it comes to hatching schemes. He says he has a plan for you.", ["objectivesText"] = "Speak with Rendle .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.54, ["y"] = 0.272, ["mapID"] = 1699, ["npcID"] = 175772 } }, ["ends"] = { { ["x"] = 0.54, ["y"] = 0.272, ["mapID"] = 1699, ["npcID"] = 175772 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.54, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 175772, ["questTurnInID"] = 175772, ["questType"] = "standard", ["sourceQuests"] = { 62857 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1204, ["name"] = "Sinfall", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 137, ["title"] = "Covenant Tutorials", ["questLineID"] = 1204, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2Po