[62697] = { ["id"] = 62697, ["name"] = "A Call to Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "< Laurel picks out a sad tune on her harp.> Our groves wilt and wither, and enemies wait at our gates! The forest calls out in sorrow, \"Please help us before it's too late!\" <The melody becomes a call to arms.> O <huntsman/huntress>, now answer our calling! Ardenweald is in need of your might! Envoy Blodwyn will give you a mission, to ride with the Wild Hunt tonight!", ["objectivesText"] = "Speak with Blodwyn .", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.343, ["y"] = 0.368, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["ends"] = { { ["x"] = 0.343, ["y"] = 0.368, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.343, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 176096, ["questTurnInID"] = 176096, ["questType"] = "standard", ["sourceQuests"] = { 62884 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 