[62700] = { ["id"] = 62700, ["name"] = "Ashes of the Tower", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10472, ["storyline"] = { 62700 }, ["description"] = "Your first step towards obtaining the power is to retrieve... something. Yes, I believe it's coming back to me.", ["objectivesText"] = "Collect 1250 Soul Ash in Torghast. Progress: Have you recovered what is needed?", ["rewardItems"] = { 187077 }, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["coords"] = { ["mapID"] = 1912, ["x"] = 0.506, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 164937, ["questTurnInID"] = 164937, ["questType"] = "standard", ["sourceQuests"] = { 60272 } },
[62704] = { ["id"] = 62704, ["name"] = "The Threads of Fate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 62000, 62159, 62704, 62716 }, ["series"] = { 62000, 62716 }, ["description"] = "It is my duty to observe the strands of fate. The wondrous possibilities that the Purpose lays before us. Fate flows around you, mortal. It shifts. It changes. But I have stilled its movements to offer you... a choice. You may journey through the Shadowlands in the same manner as those who came before you have done. Or you may choose a different path. One that lets you forge a bond with a covenant now, and move freely through the realms of Death to forge your own destiny. What say you, mortal?", ["objectivesText"] = "Speak with Fatescribe Roh-Tahl and decide how you want to experience Shadowlands. Progress: Fate is not fickle. Should you accept its offer, there will be no turning back.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["rewardItems"] = { 188167, 190189 }, ["starts"] = { { ["x"] = 0.196, ["y"] = 0.502, ["mapID"] = 1670, ["npcID"] = 174871 } }, ["ends"] = { { ["x"] = 0.196, ["y"] = 0.502, ["mapID"] = 1670, ["npcID"] = 174871 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.196, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 174871, ["questTurnInID"] = 174871, ["questType"] = "standard", ["sourceQuests"] = { 59770 }, ["questLines"] = { { ["id"] = 1175, ["name"] = "Aiding the Shadowlands", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1257, ["name"] = "Time Skip", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1175, ["questLineOrder"] = 0 }, { ["id"] = 156, ["title"] = "Shadowlands", ["questLineID"] = 1257, ["questLineOrder"] = 32 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[62705] = { ["id"] = 62705, ["name"] = "Scour the Temple", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62705 }, ["objectivesText"] = "Defend the temple Terrified Steward rescued Vesper of Purity cleansed Vesper of Harmony cleansed Forsworn Axiom destroyed", ["rewardGold"] = 1239200, ["rewardXP"] = 13630, ["starts"] = { { ["x"] = 0.584, ["y"] = 0.752, ["mapID"] = 1533 } }, ["ends"] = { { ["x"] = 0.584, ["y"] = 0.752, ["mapID"] = 1533 } }, ["coords"] = { ["mapID"] = 1533, ["x"] = 0.584, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 62159 }, ["db2Objectives"] = { { ["text"] = "Defend the temple", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Terrified Steward rescued", ["amount"] = 13, ["type"] = 0, ["objectID"] = 174875, ["orderIndex"] = 5 }, { ["text"] = "Vesper of Purity cleansed", ["amount"] = 7, ["type"] = 0, ["objectID"] = 157622, ["orderIndex"] = 7 }, { ["text"] = "Vesper of Harmony cleansed", ["amount"] = 7, ["type"] = 0, ["objectID"] = 157625, ["orderIndex"] = 8 }, { ["text"] = "Forsworn Axiom destroyed", ["amount"] = 20, ["type"] = 0, ["objectID"] = 174876, ["orderIndex"] = 10 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[62707] = { ["id"] = 62707, ["name"] = "The Elysian Fields", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62707 }, ["series"] = { 62723, 62729, 63034 }, ["description"] = "You must travel to Bastion , eternal home of the winged kyrian. Do not be fooled by their golden fields and shining spires--the kyrian have been weakened by the great anima drought, and face the brink of civil war against their own fallen brethren. They will benefit greatly from your aid. Seek one known as Kalisthene in the crossroads called Hero's Rest. She will direct you further. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", ["objectivesText"] = "Speak to Kalisthene at Hero's Rest in Bastion .", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.7, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 163427, ["x"] = 0.51, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 62275 } },
[62712] = { ["id"] = 62712, ["name"] = "War of Attrition", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62712 }, ["objectivesText"] = "Wear down the enemy Forces", ["rewardGold"] = 1239200, ["rewardXP"] = 13630, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.484, ["mapID"] = 1536 } }, ["ends"] = { { ["x"] = 0.388, ["y"] = 0.484, ["mapID"] = 1536 } }, ["coords"] = { ["mapID"] = 1536, ["x"] = 0.388, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 62159 }, ["db2Objectives"] = { { ["text"] = "Wear down the enemy Forces", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[62714] = { ["id"] = 62714, ["name"] = "A Gift for an Acolyte", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60466, 62714, 62715 }, ["description"] = "The materials you supplied were more than sufficient for my purposes. For that, you have my gratitude. I think I know how to make the best use of the excess. A dear friend of mine recently achieved the role of Acolyte in service to the Temple of Purity. You are new here, so I will spare you the details, but it is an honor to serve a temple before one reaches ascension. I want to celebrate her success with a gift. Will you take this parcel to Acolyte Amalthina ?", ["objectivesText"] = "Deliver Klystere's Gift to Acolyte Amalthina in the Temple of Purity. Progress: Welcome to the Temple of Purity. How may I be of service?", ["rewardGold"] = 26210, ["rewardXP"] = 175, ["rewardItems"] = { 183966 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160598, ["x"] = 0.478, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 174900, ["x"] = 0.538, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 60466 }, ["questLines"] = { { ["id"] = 1151, ["name"] = "An Act of Service", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[62715] = { ["id"] = 62715, ["name"] = "More Than A Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60466, 62714, 62715 }, ["description"] = "You have no idea what you just delivered, do you? <She opens the parcel to reveal a wreath of Larion plumage.> I will explain, but first... I wish to return the favor. Klystere and I frequent a resting place to the north of here, along the path to the Temple of Courage. We planted a flower for our enjoyment, as we spend so much of our free time there. Bring me this bloom, if you would be so kind. Then I will tell you about the significance of this gift.", ["objectivesText"] = "Acquire 1 Cultivated Windblossom . Progress: Did you find the place I mentioned? And the flower?", ["rewardGold"] = 265883, ["rewardXP"] = 1060, ["rewardItems"] = { 183967 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 174900, ["x"] = 0.538, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 174900, ["x"] = 0.538, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 62714 }, ["questLines"] = { { ["id"] = 1151, ["name"] = "An Act of Service", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[62716] = { ["id"] = 62716, ["name"] = "Re-Introductions", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 62000, 62159, 62704, 62716 }, ["series"] = { 62000, 62704 }, ["description"] = "Though you have chosen your path, the fate of the Shadowlands has yet to be determined. The power of the Banished One grows. It falls to you, and others of your kind, to thwart him. The Arbiter's Honored Voice, Tal-Inara , will aid you in choosing a covenant. Bolstering their strength offers our best chance at victory. Let the Purpose guide you, <name>. Always.", ["objectivesText"] = "Speak with Tal-Inara within the Enclave in Oribos .", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.196, ["y"] = 0.502, ["mapID"] = 1670, ["npcID"] = 164173 } }, ["ends"] = { { ["x"] = 0.196, ["y"] = 0.502, ["mapID"] = 1670, ["npcID"] = 164173 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.196, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164173, ["questTurnInID"] = 164173, ["questType"] = "standard", ["sourceQuests"] = { 62704 }, ["nextQuests"] = { 62000 }, ["questLines"] = { { ["id"] = 1175, ["name"] = "Aiding the Shadowlands", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1175, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[62718] = { ["id"] = 62718, ["name"] = "Hero's Rest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62718 }, ["description"] = "In light of the new arrivals to Bastion , Kalisthene has enabled the anima gateways to Hero's Rest once more! Those wishing to partake of breathtaking views, unparalleled steward service, and all manner of training and repair facilities should venture to this most remarkable of locations at their earliest convenience. Simply follow the path north and bear to the right at the crossroads. Kalisthene will personally greet all new arrivals for this most joyous of occasions!", ["objectivesText"] = "Speak to Kalisthene in Hero's Rest.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.488, ["y"] = 0.733, ["mapID"] = 1533, ["objectID"] = 362489 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 163427, ["x"] = 0.51, ["y"] = 0.468 }, { ["mapID"] = 1533, ["npcID"] = 165045, ["x"] = 0.528, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57266 }, ["nextQuests"] = { 59426 } },
[62719] = { ["id"] = 62719, ["name"] = "The Final Pieces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["storyline"] = { 62719 }, ["description"] = "The final components you'll need to acquire are... vessels... rune vessels! Armor to hold the might that will be imbued. And... powers? No... missives? Yes! Missives will allow your item to enhance your own personal strengths. But they cannot be the same. No, the two must offer different benefits. All of these can be obtained from souls with the correct crafting knowledge. And lastly, more of my memories. Memories of the runes, of the powers... of myself.", ["objectivesText"] = "Acquire a Runecarver Memory, an Armor Rune Vessel suitable to your class, and two different Missives. These items can be obtained through crafting, or can be found on the Auction House. Progress: Have you acquired the remaining items?", ["rewardItems"] = { 173160, 173161, 173162, 173163, 183243, 183244, 183249 }, ["starts"] = { { ["x"] = 0.504, ["y"] = 0.538, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["ends"] = { { ["x"] = 0.504, ["y"] = 0.538, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["coords"] = { ["mapID"] = 1912, ["x"] = 0.504, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 164937, ["questTurnInID"] = 164937, ["questType"] = "standard", ["sourceQuests"] = { 60272 } },
