[62723] = { ["id"] = 62723, ["name"] = "Bolstering Bastion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62723, 62729 }, ["series"] = { 62707, 62729, 63034 }, ["description"] = "You are no aspirant, but I welcome any aid that Oribos might bring us in these dire times. Please, aid our people in any way you can. With anima in low supply and the insidious Forsworn encroaching from all sides, there is no shortage of trials to overcome. Do this for us, and I will see to it myself that our almighty Archon hears of your deeds in service of the kyrian. Mark well my words, and follow the path.", ["objectivesText"] = "Aid Bastion by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Bastion dungeons.", ["rewardGold"] = 4118400, ["rewardXP"] = 13630, ["rewardItems"] = { 181632, 181743 }, ["rewardChoices"] = { 181632 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 163427, ["x"] = 0.51, ["y"] = 0.468 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 163427, ["x"] = 0.51, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 62159, 62704 }, ["questLines"] = { { ["id"] = 1155, ["name"] = "Bolstering Bastion", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1155, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[62724] = { ["id"] = 62724, ["name"] = "Ye Olde Test of Strength", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 62724 }, ["description"] = "A test of strength this be. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(62724)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(62724))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Complete the Test.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
