[62748] = { ["id"] = 62748, ["name"] = "Rallying Maldraxxus", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62748, 62761 }, ["series"] = { 62738, 62761, 63035 }, ["description"] = "We need all the help we can get! It's taking all we have to hold our ground against the other houses, let alone gain any ground against them. Truth be told, your blade will be welcome anywhere. There are no shortage of battles to be won, foes to be toppled, or weary soldiers to be relieved. Help us regain control of Maldraxxus , and in the name of the Primus I will see you are amply rewarded.", ["objectivesText"] = "Aid Maldraxxus by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Maldraxxus dungeons.", ["rewardGold"] = 4118400, ["rewardXP"] = 13630, ["rewardItems"] = { 181648, 181687, 181692 }, ["rewardChoices"] = { 181687, 181692 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 175008, ["x"] = 0.528, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 175008, ["x"] = 0.528, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 62159, 62704 }, ["questLines"] = { { ["id"] = 1160, ["name"] = "Rallying Maldraxxus", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1160, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[62761] = { ["id"] = 62761, ["name"] = "Return to Oribos", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62748, 62761 }, ["series"] = { 62738, 62748, 63035 }, ["description"] = "I wouldn't be a tactician if I didn't recognize when the mission is complete. Much remains to be done before Maldraxxus can stand tall once again, but that day will come thanks to your efforts. There are other realms in need of your skills more than us. You should return to Oribos and see to it that they receive it.", ["objectivesText"] = "Speak to Tal-Inara in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 175008, ["x"] = 0.528, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 175008, ["x"] = 0.528, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questTurnInID"] = 175008, ["questType"] = "standard", ["sourceQuests"] = { 62748 }, ["questLines"] = { { ["id"] = 1160, ["name"] = "Rallying Maldraxxus", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1160, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[62763] = { ["id"] = 62763, ["name"] = "Support the Court", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62763, 62776 }, ["series"] = { 62739, 62776, 63036 }, ["description"] = "Groves are under attack everywhere! There simply aren't enough of us to protect them all! You just might be our only hope. We must restore order, or more precious souls will be lost to us. Please, help anyone you can, anywhere you can. My heart cannot bear to see any more pain! I'll make sure the Winter Queen hears of your deeds, don't you worry!", ["objectivesText"] = "Defend Ardenweald by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Ardenweald dungeons.", ["rewardGold"] = 4118400, ["rewardXP"] = 13630, ["rewardItems"] = { 179584, 184379 }, ["rewardChoices"] = { 179584 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 62159, 62704 }, ["questLines"] = { { ["id"] = 1168, ["name"] = "Aiding Ardenweald", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 131, ["title"] = "Threads of Fate", ["questLineID"] = 1168, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
