[62793] = { ["id"] = 62793, ["name"] = "It's All Coming Together", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Our brothers and sisters are spread thin fighting the Forsworn, maintaining order among aspirants waiting to ascend, and countless other duties. The willing souls you recovered from the Maw will be a great boon to our capabilities in these dire times. Go to Haephus at once--he has long been searching for aid in activating some of our sanctum's most powerful features. It is time we saw Elysian Hold brought to its full potential.", ["objectivesText"] = "Speak to Haephus .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 174292, 177053, 178156, 179942 }, ["rewardChoices"] = { 174292, 177053, 178156, 179942 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 62796 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 1201, ["name"] = "Among the Kyrian", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 133, ["title"] = "Covenant Tutorials", ["questLineID"] = 1201, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[62794] = { ["id"] = 62794, ["name"] = "Enhancing the Hold", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "As thanks for your efforts in recovering the anima and souls we now have available, you may decide which of Elysian Hold's features we upgrade first. Once active, it shall expand our capabilities to help not only Bastion, but all the Shadowlands. Do not worry--as you continue to recover anima and willing souls we will activate them all in time. For now, a single upgrade must suffice.", ["objectivesText"] = "Start a Sanctum Upgrade. Progress: Take your time. The first step on the path is always the most difficult.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 174292, 177053, 178156, 179942 }, ["rewardChoices"] = { 178156, 177053, 179942, 174292 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 62837 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 1201, ["name"] = "Among the Kyrian", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 133, ["title"] = "Covenant Tutorials", ["questLineID"] = 1201, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[62795] = { ["id"] = 62795, ["name"] = "A Conduit for Good", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "While the gifts your bond shall bring you are substantial, you may also empower yourself further through the use of conduits. Conduits act to channel the energy of your soulbind into your form more directly, increasing your potential in a myriad of ways. Use the ones I have given you as a test of this power, but fear not--you will find others as you aid the Shadowlands.", ["objectivesText"] = "Add the Conduits to the Forge of Bonds, then apply one to a slot on Pelagos. Progress: This is a crucial step in the path.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 60504 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[62796] = { ["id"] = 62796, ["name"] = "Return to Adrestes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Baine suffers within Torghast, but at least we know that he yet lives. Rushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one. In the meantime, I suggest you bring the souls you rescued to Elysian Hold. The kyrian are vital to the Shadowlands. If Bastion remains in turmoil, then all might soon be lost.", ["objectivesText"] = "Report to Polemarch Adrestes at Elysian Hold in Bastion.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardCurrencies"] = { { ["id"] = 1810, ["amount"] = 5 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.399, ["y"] = 0.686, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 62837 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 1201, ["name"] = "Among the Kyrian", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 133, ["title"] = "Covenant Tutorials", ["questLineID"] = 1201, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[62797] = { ["id"] = 62797, ["name"] = "The Vessels of Metal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13476, ["storyline"] = { 62797 }, ["description"] = "You have the bearing of one familiar with the art of smithing. But perhaps you have more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", ["objectivesText"] = "Bring the memory back to Smith Au'berk in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["coords"] = { ["mapID"] = 1912, ["x"] = 0.506, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164937, ["questTurnInID"] = 164937, ["questType"] = "standard", ["sourceQuests"] = { 60272 } },
[62798] = { ["id"] = 62798, ["name"] = "The Vessels of Leather and Bone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13476, ["storyline"] = { 62798 }, ["description"] = "You have the bearing of one familiar with the art of leatherworking. But perhaps you have more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", ["objectivesText"] = "Bring the memory back to Tanner Au'qil in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["coords"] = { ["mapID"] = 1912, ["x"] = 0.506, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164937, ["questTurnInID"] = 164937, ["questType"] = "standard", ["sourceQuests"] = { 60272 } },
[62799] = { ["id"] = 62799, ["name"] = "The Vessels of the Thread", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13476, ["storyline"] = { 62799 }, ["description"] = "You have the bearing of one familiar with the art of thread work. But perhaps you have more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", ["objectivesText"] = "Bring the memory back to Stitcher Au'phes in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 172230, 172439, 173202, 173204, 178787 }, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["coords"] = { ["mapID"] = 1912, ["x"] = 0.506, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164937, ["questTurnInID"] = 164937, ["questType"] = "standard", ["sourceQuests"] = { 60272 } },
[62800] = { ["id"] = 62800, ["name"] = "The Vessels of Jewels", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13476, ["storyline"] = { 62800 }, ["description"] = "You have the bearing of a lapidary. Though familiar with the art of jewelcraft, perhaps there is yet more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", ["objectivesText"] = "Bring the memory back to Appraiser Au'vesk in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.572, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["coords"] = { ["mapID"] = 1912, ["x"] = 0.506, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164937, ["questTurnInID"] = 164937, ["questType"] = "standard", ["sourceQuests"] = { 60272 } },
[62801] = { ["id"] = 62801, ["name"] = "The Call of Fate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 62801 }, ["description"] = "I am the Arbiter's fatescribe. It is my duty to observe the strands of destiny that the Purpose lays before us. Fate flows through you, mortal, as you journey through the Shadowlands. And now it offers you... a choice. Return to Oribos , , that I might help guide your path. The Purpose is our way.", ["objectivesText"] = "Meet Fatescribe Roh-Tahl in Oribos .", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["sourceQuests"] = { 59770 } },
[62804] = { ["id"] = 62804, ["name"] = "Filling the Tanks", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62804 }, ["description"] = "<The containment pack appears to be intact, albeit empty. Perhaps refilling it with the appropriate mixture of liquids will render it functional once more. Slaying the correct combination of slimes should provide all the fluid necessary.>", ["objectivesText"] = "Slay the variety of slimes to fill the tanks with fluid.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 184155, 184156 }, ["starts"] = { { ["x"] = 0.586, ["y"] = 0.742, ["mapID"] = 1536 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157945, ["x"] = 0.59, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["startItems"] = { 184155 } },
[62807] = { ["id"] = 62807, ["name"] = "Forest Refugees", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62807 }, ["description"] = "Some of those displaced by the fallen groves have made a home for themselves at the base of the Heart of the Forest. Hibernal Hollow is fortunate. We have supplies, when they may not. If you would, bring these to Flwngyrr . They care for the refugees there.", ["objectivesText"] = "Bring Hibernal Hollow supplies to Flwngyrr in the Heart of the Forest. Provided item:", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 184157 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 168032, ["x"] = 0.484, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 60905 } },
[62832] = { ["id"] = 62832, ["name"] = "Friends in Dark Places", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57895, 57905, 62692, 62698, 62789, 62790, 62791, 62792 }, ["description"] = "Even with all your aid, our sanctum will grow weaker without souls willing to help us. Many souls that may have been destined for Bastion are trapped within the Maw. If you can find a way to free them, they will help us restore Elysian Hold's power. Seek out what aid you can and do what we cannot, Maw Walker. Our very future may depend on it.", ["objectivesText"] = "Find Ve'nari in the Maw.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533, 1543 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["sourceQuests"] = { 57905 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1201, ["name"] = "Among the Kyrian", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1239, ["name"] = "Catching Up!", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 }, { ["id"] = 133, ["title"] = "Covenant Tutorials", ["questLineID"] = 1201, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1239, ["questLineOrder"] = 0 }, { ["id"] = 149, ["title"] = "Intro Start", ["questLineID"] = 1239, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
