[62834] = { ["id"] = 62834, ["name"] = "Glorious Ambition", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 62694, 62833, 62835 }, ["description"] = "The renown you earn through your deeds can and will greatly benefit our covenant. Our ambition is not confined within the borders of Maldraxxus, after all. Allow me to demonstrate what we achieve as you gain renown.", ["objectivesText"] = "Examine your Renown with the Necrolord Covenant. Progress: Talent is nothing without ambition.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.467, ["y"] = 0.404, ["mapID"] = 1698, ["npcID"] = 175998 } }, ["ends"] = { { ["x"] = 0.467, ["y"] = 0.404, ["mapID"] = 1698, ["npcID"] = 175998 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.467, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 175998, ["questTurnInID"] = 175998, ["questType"] = "standard", ["sourceQuests"] = { 62833 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["ques