[62835] = { ["id"] = 62835, ["name"] = "A Call to Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 62694, 62833, 62834 }, ["description"] = "We may hold the Seat of the Primus, but it will do us no good without the anima to power it. As you fight beside our troops on the battlefield, seek out opportunities to recover anima to support the war effort. Speak with Sergeant Romark . He can offer you additional guidance.", ["objectivesText"] = "Speak with Sergeant Romark .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.467, ["y"] = 0.404, ["mapID"] = 1698, ["npcID"] = 175998 } }, ["ends"] = { { ["x"] = 0.467, ["y"] = 0.404, ["mapID"] = 1698, ["npcID"] = 175998 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.467, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 175998, ["questTurnInID"] = 175998, ["questType"] = "standard", ["sourceQuests"] = { 62834 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLine