[62836] = { ["id"] = 62836, ["name"] = "Signs of the Lion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1670, ["storyline"] = { 60139, 60146, 62836, 62932, 62935, 62938, 62966, 62969 }, ["series"] = { 61730 }, ["description"] = "Thanks to your efforts, Thrall, Jaina Proudmoore, and Baine Bloodhoof are safe. Yet so long as the Jailer holds any hero of Azeroth, I fear he has power over us all. It seems Anduin has been taken deeper into the tower than the others. Before I risk peering inside, you must make one last attempt to find him. You say the Jailer spoke of honing a weapon. I fear we are running out of time. Do not relent, <name>. Search the twisting corridors of Torghast for any sign of the Young Lion.", ["objectivesText"] = "Enter Torghast and explore the Twisting Corridors for any sign of Anduin Wrynn. Progress: Did you find any sign of Anduin?", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardItems"] = { 184166, 184223, 184276, 184277, 184278, 184617, 184618, 184619, 184652 }, ["rewardCurrencies"] = { { ["id"] = 1828, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.399, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 60146 }, ["questLines"] = { { ["id"] = 1136, ["name"] = "Torghast", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 154, ["title"] = "Torghast Story Progression Skip", ["questLineID"] = 1136, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[62837] = { ["id"] = 62837, ["name"] = "Hopeful News", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["description"] = "The terms of our bargain have been met. You may depart with the souls you acquired. Perhaps the fate of this \"Baine\" is of interest to you or your allies. I suggest you return to Oribos and consult them. No need to rush. After all, those held within Torghast are tortured for centuries. Kindly remember not to tell anyone about our arrangement. Discretion is key between business partners, after all.", ["objectivesText"] = "Speak with Bolvar Fordragon in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questTurnInID"] = 162804, ["questType"] = "standard", ["sourceQuests"] = { 60289 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 1123, ["name"] = "Return to the Maw", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1201, ["name"] = "Among the Kyrian", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1202, ["name"]