[62839] = { ["id"] = 62839, ["name"] = "Anima is Strength", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 61397, 62840, 62843 }, ["description"] = "You are victorious, Maw Walker. And with your success, our forces grow stronger. Stay alert. Your strength will be called upon again soon enough. Bring the anima you recovered to Akradia Moa at once. She will ensure its proper storage.", ["objectivesText"] = "Speak to Arkadia Moa", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.477, ["y"] = 0.291, ["mapID"] = 1698, ["npcID"] = 158339 } }, ["ends"] = { { ["x"] = 0.477, ["y"] = 0.291, ["mapID"] = 1698, ["npcID"] = 158339 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.477, ["y"] = 0.291 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 158339, ["questTurnInID"] = 158339, ["questType"] = "standard", ["sourceQuests"] = { 62835 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiM