[62840] = { ["id"] = 62840, ["name"] = "Into the Reservoir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 61397, 62839, 62843 }, ["description"] = "With anima in short supply, Baroness Draka has tasked me with carefully managing our reserves as they are needed. You may deposit any anima you recover into the reservoir here. Be assured that the Necrolords will defend it at all costs.", ["objectivesText"] = "Deposit Anima into your sanctum's Reservoir.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 181475 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161909, ["questTurnInID"] = 161909, ["questType"] = "standard", ["sourceQuests"] = { 62839 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["qu