[62844] = { ["id"] = 62844, ["name"] = "Return to Draka", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["description"] = "Baine suffers within Torghast, but at least we know that he yet lives. Rushing to his rescue would prove disastrous without a plan of attack. I will do what I can to prepare one. In the meantime, you received a summons from Baroness Draka asking that you return to the Seat of the Primus. The Necrolords are the key to saving the Shadowlands, <name>. I suggest you return to them as soon as you are able.", ["objectivesText"] = "Report to Baroness Draka at the Seat of the Primus in Maldraxxus.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardCurrencies"] = { { ["id"] = 1810, ["amount"] = 5 }, { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.4, ["y"] = 0.684, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.4, ["y"] = 0.684, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.4, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 62837 }, ["nextQuests"] = { 62845 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 17, ["flags"] = 1 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineI