[62846] = { ["id"] = 62846, ["name"] = "Sanctum Improvements", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Your will to succeed is strong, Maw Walker. With the anima and the souls you have recovered, we can now begin to unlock our sanctum's true potential. As we acquire more souls and more anima, we can gain even greater power from the Seat of the Primus. Remain relentless in your pursuit, and victory will be ours.", ["objectivesText"] = "Start a Sanctum Upgrade. Progress: This is only the beginning.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161909, ["questTurnInID"] = 161909, ["questType"] = "standard", ["sourceQuests"] = { 62845 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 1202, ["name"] = "Covenant Hall Intro", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 134, ["title"] = "Covenant Tutorials", ["questLineID"] = 1202, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[62848] = { ["id"] = 62848, ["name"] = "Conduits, What Are They For?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59598, 59603, 59609, 61359, 61388, 61397, 62833, 62834, 62835, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 63212 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "While the benefits of soulbinding are substantial, you may strengthen them further through the use of conduits. Conduits act to channel the anima of our bond in a myriad of ways, vastly increasing both of our potential. Let us test out the ones I have given you. Fear not--many others like it can be found throughout the Shadowlands.", ["objectivesText"] = "Add the Conduits to the Forge of Bonds, then apply one to a slot on Plague Deviser Marleth. Progress: This is an important lesson, my apprentice.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.324, ["mapID"] = 1698, ["npcID"] = 161904 } }, ["ends"] = { { ["x"] = 0.388, ["y"] = 0.324, ["mapID"] = 1698, ["npcID"] = 161904 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.388, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161904, ["questTurnInID"] = 161904, ["questType"] = "standard", ["sourceQuests"] = { 61388 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 1240, ["name"] = "Catching Up!", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1240, ["questLineOrder"] = 0 }, { ["id"] = 150, ["title"] = "Intro Start", ["questLineID"] = 1240, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[62849] = { ["id"] = 62849, ["name"] = "Paragon of the Court of Harvesters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62849 }, ["description"] = "Maw Walker. Your efforts have provided the Court of Harvesters a decisive edge in their ongoing conflict with the zealots and sycophants who cling to the lost cause of Sire Denathrius. If you will join me in Darkhaven we can express our gratitude to you in a more... physical... way. With treasure, of course.", ["objectivesText"] = "Speak with Mistress Mihaela in Darkhaven.", ["starts"] = { { ["x"] = 0.614, ["y"] = 0.638, ["mapID"] = 1525, ["npcID"] = 156822 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questGiverID"] = 156822, ["questType"] = "standard" },
[62850] = { ["id"] = 62850, ["name"] = "Paragon of the Ascended", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62850 }, ["objectivesText"] = "Speak with Adjutant Nikos in Hero's Rest in Bastion .", ["starts"] = { { ["x"] = 0.522, ["y"] = 0.47, ["mapID"] = 1533, ["npcID"] = 160470 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160470, ["x"] = 0.522, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questGiverID"] = 160470, ["questType"] = "standard" },
[62851] = { ["id"] = 62851, ["name"] = "Paragon of the Undying Army", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62851 }, ["description"] = "Your continued advancement of the Undying Army objectives has earned you the continued respect of our forces. I have been authorized to provide you with a portion of recent spoils of war in gratitude. Please join me at the Seat of the Primus to collect these spoils at your earliest convenience.", ["objectivesText"] = "Speak with Nalcorn Talsen at the Theater of Pain.", ["rewardItems"] = { 172924 }, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.534, ["mapID"] = 1536, ["npcID"] = 173003 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173003, ["x"] = 0.506, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questGiverID"] = 173003, ["questType"] = "standard" },
