[62855] = { ["id"] = 62855, ["name"] = "Edict of the Eternal Ones", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 62855 }, ["description"] = "Death appears to function differently for you, Maw Walker. Alas, you have shed some of your stygia. Return to the place of your passing, and you shall find what you left behind.", ["objectivesText"] = "Recover your Dropped Stygia from your corpse.", ["rewardGold"] = 128700, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[62856] = { ["id"] = 62856, ["name"] = "Building Your Renown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 59323, 62691, 62695, 62857 }, ["description"] = "As you aid the court in your travels across the Shadowlands, your connection to us shall grow ever stronger. In time, you will be able to reap the benefits of your growing Renown. One of my most trusted and loyal followers, Rahel , has been watching you for some time. She can report as to your standing and the Renown you have garnered with my people. Speak to her and she might explain better how this Renown might be best put to work.", ["objectivesText"] = "Speak with Rahel .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.455, ["y"] = 0.287, ["mapID"] = 1700, ["npcID"] = 171934 } }, ["ends"] = { { ["x"] = 0.455, ["y"] = 0.287, ["mapID"] = 1700, ["npcID"] = 171934 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.455, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 171934, ["questTurnInID"] = 171934, ["questType"] = "standard", ["sourceQuests"] = { 59323 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1204, ["name"] = "Sinfall", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 137, ["title"] = "Covenant Tutorials", ["questLineID"] = 1204, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700 },
[62857] = { ["id"] = 62857, ["name"] = "The Court's Bounty", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 59323, 62691, 62695, 62856 }, ["description"] = "Venthyr are drawn to new things, so we are going to make you the figurehead of our Sanctum. As your Renown throughout the Shadowlands grows, we will grow with you, accumulating power and influence we otherwise would not have access to. It will fall to me to track your Renown and quantify it as a resource. A true currency of Courts, if you will. Observe.", ["objectivesText"] = "Examine your Renown with Sinfall. Progress: With enough anima, anything is possible.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.54, ["y"] = 0.272, ["mapID"] = 1699, ["npcID"] = 175772 } }, ["ends"] = { { ["x"] = 0.54, ["y"] = 0.272, ["mapID"] = 1699, ["npcID"] = 175772 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.54, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 175772, ["questTurnInID"] = 175772, ["questType"] = "standard", ["sourceQuests"] = { 62856 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1204, ["name"] = "Sinfall", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 137, ["title"] = "Covenant Tutorials", ["questLineID"] = 1204, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
