[62882] = { ["id"] = 62882, ["name"] = "Setting the Ground Rules", ["level"] = 55, ["requiredLevel"] = 55, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Back to rescue more souls? How intrepid. Though I must say, your earlier escapade has drawn the Jailer's attention... and his ire. After all, none have successfully eluded him before. Except for me. Now his forces are on high alert, hunting down any errant souls that the fabled Maw Walker may try to steal from him. It has made things quite... inconvenient for me. If you and I are going to work together, we need to set a few ground rules. And you must be properly equipped.", ["objectivesText"] = "Set the ground rules about working together with Ve'nari . Progress: Let us discuss the terms of our arrangement.", ["rewardXP"] = 3745, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 62832, 62843, 62893, 62905 }, ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 12, ["flags"] = 0 }, {