[62883] = { ["id"] = 62883, ["name"] = "Keeper of Great Renown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "As you grow in renown across the Shadowlands, the Heart of the Forest shall grow with you. Seek out Laurel , our Keeper of Renown. She will acquaint you with the magic that we bestow upon our huntsmen and huntresses.", ["objectivesText"] = "Seek out Laurel the Heart of the Forest.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 156634, ["x"] = 0.454, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 156634, ["x"] = 0.454, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questTurnInID"] = 156634, ["questType"] = "standard", ["sourceQuests"] = { 58160 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["titl