[62884] = { ["id"] = 62884, ["name"] = "The Forest Will Sing Your Name", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "< Laurel picks out an intricate melody on deft fingers, and sings.> The keeper of word and deed, am I, the weaver of song and lore. Boons are granted as you grow in Renown, fulfilling the oaths we swore. Each deed that you do is a seed of strength, which will blossom in fabulous power. Speak with me now and see what awaits, our magic is yours to discover!", ["objectivesText"] = "Examine your Renown with the Night Fae Covenant. Progress: I cannot wait to compose a song for you!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.343, ["y"] = 0.368, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["ends"] = { { ["x"] = 0.343, ["y"] = 0.368, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.343, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 176096, ["questTurnInID"] = 176096, ["questType"] = "standard", ["sourceQuests"] = { 62883 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[62886] = { ["id"] = 62886, ["name"] = "A Call to Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 62886 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "The Heart of the Forest requires anima to be renewed and to grow. The Wild Hunt will need your help to recover what we need. Together we strand strong. Speak with Blodwyn. She has been guiding assistance to where it is most needed.", ["objectivesText"] = "Speak with Blodwyn.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62890] = { ["id"] = 62890, ["name"] = "Who Shapes the Forest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1702, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "You have fulfilled your calling, Maw Walker, and brought calm to our forest. Stay vigilant, for others will similarly call upon you in time. The anima you have recovered will be of great use to the Heart of the Forest. Bring it to Zayhad. They will ensure it is safe until it is needed. You will find them deep in the roots of the Heart of the Forest.", ["objectivesText"] = "Find Zayhad in the Roots of the Heart of the Forest.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.538, ["y"] = 0.062, ["mapID"] = 1701, ["npcID"] = 167195 } }, ["ends"] = { { ["x"] = 0.538, ["y"] = 0.062, ["mapID"] = 1701, ["npcID"] = 167195 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.538, ["y"] = 0.062 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 167195, ["questTurnInID"] = 167195, ["questType"] = "standard", ["sourceQuests"] = { 62697 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questL