[62891] = { ["id"] = 62891, ["name"] = "Into the Reservoir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1702, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Groves wither, and our Queen weeps on barren soil. Anima, precious as water, now rare as snow. Our Queen gives of her own, shelters all beneath her boughs... but one tree does not a forest make. Your gift will be treasured and protected. Anima nourishes our roots, as hope nourishes our hearts. Ardenweald may yet flourish once more.", ["objectivesText"] = "Deposit Anima into your sanctum's Reservoir. Progress: None to waste, and none shall be wasted. It will be safe until needed.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.397, ["y"] = 0.557, ["mapID"] = 1702, ["npcID"] = 165702 } }, ["ends"] = { { ["x"] = 0.397, ["y"] = 0.557, ["mapID"] = 1702, ["npcID"] = 165702 } }, ["coords"] = { ["mapID"] = 1702, ["x"] = 0.397, ["y"] = 0.557 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 165702, ["questTurnInID"] = 165702, ["questType"] = "standard", ["sourceQuests"] = { 62890 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1702 },
[62892] = { ["id"] = 62892, ["name"] = "Recover the Lost", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Anima and souls. Wind and rain. Ardenweald needs both to thrive. Souls meant for our boughs suffer in darkness. None escape the Maw... but you walk its shadows and return. You are their salvation. Flutterby shepherds the flock with care and compassion. Speak with her. Bring our lost souls home.", ["objectivesText"] = "Speak to Flutterby in the Heart of the Forest.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.397, ["y"] = 0.557, ["mapID"] = 1702, ["npcID"] = 165702 } }, ["ends"] = { { ["x"] = 0.397, ["y"] = 0.557, ["mapID"] = 1702, ["npcID"] = 165702 } }, ["coords"] = { ["mapID"] = 1702, ["x"] = 0.397, ["y"] = 0.557 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 165702, ["questTurnInID"] = 165702, ["questType"] = "standard", ["sourceQuests"] = { 62891 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[62893] = { ["id"] = 62893, ["name"] = "Do What We Cannot", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1543, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "Rumor has it that you've been to the Maw and back... and that you even made friends with a broker in there! So many souls destined for Ardenweald are trapped in that dark realm. They need our help... and we need theirs! We can't cultivate the Heart of the Forest's magic without them. I know this is a lot to ask... but you may be our only hope of rescuing them. Please, venture into the Maw and do what we cannot. Ardenweald's future depends on it!", ["objectivesText"] = "Find Ve'nari in the Maw.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.341, ["y"] = 0.436, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 12858 } }, ["questGiverID"] = 158553, ["questType"] = "standard", ["sourceQuests"] = { 62892 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[62894] = { ["id"] = 62894, ["name"] = "Flutterback", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1701, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Baine suffers within Torghast, but at least we know that he yet lives. Rushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one. In the meantime, I suggest you bring the souls you rescued back to Ardenweald. They deserve respite after their harrowing ordeal in the Maw, and they will surely prove vital to the Night Fae's efforts.", ["objectivesText"] = "Report to Flutterby in the Heart of the Forest in Ardenweald.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardCurrencies"] = { { ["id"] = 1810, ["amount"] = 5 }, { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.4, ["y"] = 0.684, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.4, ["y"] = 0.684, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.4, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 62837 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[62897] = { ["id"] = 62897, ["name"] = "Recovered Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1702, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62899, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Oh, I wonder what sorts of shapes these souls might take! Words can't express how grateful we are that you saved them. Not only have you brought an end to their torment, but they might be willing to aid us as well. Go speak with Zayhad. They haven't been able to tend the forest in a long while, but that might be about to change. This is all so exciting!", ["objectivesText"] = "Speak to Zayhad.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.341, ["y"] = 0.436, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["ends"] = { { ["x"] = 0.341, ["y"] = 0.436, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.341, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 158553, ["questTurnInID"] = 158553, ["questType"] = "standard", ["sourceQuests"] = { 62894 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1702 },
[62898] = { ["id"] = 62898, ["name"] = "The First New Growth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 61475, 61479, 62697, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 63214 }, ["description"] = "Long have we lain dormant. With souls, with anima, we grow once more. A choice now awaits. How shall we grow? You may decide which flower blooms first. In time, with more anima and willing souls, the whole garden will prosper. For now, a single blossom signals hope for the future. Lady Moonberry will want to know of your choice. Seek her out once it is made.", ["objectivesText"] = "Start a Sanctum Upgrade.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.397, ["y"] = 0.557, ["mapID"] = 1702, ["npcID"] = 165702 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questGiverID"] = 165702, ["questType"] = "standard", ["sourceQuests"] = { 62897 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 1203, ["name"] = "For Queen and Grove!", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 1205, ["name"] = "For Queen and Grove!", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1237, ["name"] = "Catching Up!", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 }, { ["id"] = 135, ["title"] = "Covenant Tutorials", ["questLineID"] = 1203, ["questLineOrder"] = 0 }, { ["id"] = 136, ["title"] = "Covenant Tutorials", ["questLineID"] = 1205, ["questLineOrder"] = 0 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1237, ["questLineOrder"] = 0 }, { ["id"] = 148, ["title"] = "Intro Start", ["questLineID"] = 1237, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[62899] = { ["id"] = 62899, ["name"] = "The Endless Forest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62900, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Well, that's all I have for you! Whew! You've been on a whirlwind tour of things around here, haven't you? Up and down and slantways and even into the Maw! Your head must be practically spinning. < Flutterby giggles.> You should check in with Lady Moonberry and let her know your training is complete! She probably won't quiz you on what you've learned. Probably.", ["objectivesText"] = "Return to Lady Moonberry .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.341, ["y"] = 0.436, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["ends"] = { { ["x"] = 0.341, ["y"] = 0.436, ["mapID"] = 1701, ["npcID"] = 158553 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.341, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 158553, ["questTurnInID"] = 158553, ["questType"] = "standard", ["sourceQuests"] = { 62900 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 30, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[62900] = { ["id"] = 62900, ["name"] = "A Conduit for Growth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62932, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "While our bond is powerful in and of itself, you can also enhance it through the use of conduits. Conduits channel the anima between soulbinds in many different ways, increasing both of our potential in the process. They allow us to attune ourselves to each other's unique strengths. Let's use a few now. If they can further empower our bond, then they can aid us in protecting the forest.", ["objectivesText"] = "Add the Conduits to the Forge of Bonds, then apply one to a slot on Niya . Progress: We're going to do great things together.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 190184, 190640 }, ["starts"] = { { ["x"] = 0.337, ["y"] = 0.45, ["mapID"] = 1701, ["npcID"] = 172677 } }, ["ends"] = { { ["x"] = 0.337, ["y"] = 0.45, ["mapID"] = 1701, ["npcID"] = 172677 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.337, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 172677, ["questTurnInID"] = 172677, ["questType"] = "standard", ["sourceQuests"] = { 61550 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 29, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[62902] = { ["id"] = 62902, ["name"] = "Anima is Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "You did well, boss. Keep it up like that, right, and we just might 'ave a chance of survivin' this mess. Keep your eyes open, though. Word of success like this gets 'round and it's only a matter of time till uvvers come callin' for your 'elp. Now, right, all that anima you've recovered can be put to use 'round 'ere. Bring it down to Foreman Flatfinger . He'll ensure it stored away nice and secure.", ["objectivesText"] = "Speak to Foreman Flatfinger .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.616, ["y"] = 0.757, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["ends"] = { { ["x"] = 0.616, ["y"] = 0.757, ["mapID"] = 1700, ["npcID"] = 165302 } }, ["coords"] = { ["mapID"] = 1700, ["x"] = 0.616, ["y"] = 0.757 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 165302, ["questTurnInID"] = 165302, ["questType"] = "standard", ["sourceQuests"] = { 62691 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1204, ["name"] = "Sinfall", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 137, ["title"] = "Covenant Tutorials", ["questLineID"] = 1204, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Cat