[62903] = { ["id"] = 62903, ["name"] = "Into the Reservoir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62904, 62905, 63006, 63101 }, ["description"] = "With anima in short supply these days, I've been entrusted to manage the reserves 'till they be needed. Go 'ead and deposit any anima you collect into the reservoir 'ere. Be assured, It'll be safe an' secure in me care.", ["objectivesText"] = "Deposit Anima into your sanctum's Reservoir. Progress: I assure you, this here reservoir is the safest place to keep Anima in all of Revendreth.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 181475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.549, ["y"] = 0.263, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["ends"] = { { ["x"] = 0.549, ["y"] = 0.263, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.549, ["y"] = 0.263 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 172605, ["questTurnInID"] = 172605, ["questType"] = "standard", ["sourceQuests"] = { 62902 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1204, ["name"] = "Sinfall", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 137, ["title"] = "Covenant Tutorials", ["questLineID"