[62904] = { ["id"] = 62904, ["name"] = "The Souls Plight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62905, 63006, 63101 }, ["description"] = "Anima enables us to do many fings, but this sanctum can not function on anima alone. It'll require the combined effort of many souls workin' togeffer to unlock its full potential. The Soul Warden is eager to be of service ever since you rescued 'im from the Maw. Your unique ability 'ta brin' souls from there will prove useful to him. Why don't you go pay 'im a visit?", ["objectivesText"] = "Speak to Tenaval .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.549, ["y"] = 0.263, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["ends"] = { { ["x"] = 0.549, ["y"] = 0.263, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.549, ["y"] = 0.263 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 172605, ["questTurnInID"] = 172605, ["questType"] = "standard", ["sourceQuests"] = { 62903 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1204, ["name"] = "Sinfall", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 137, ["title"] = "Covenant Tutorials", ["questLineID"] = 1204, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["