[62914] = { ["id"] = 62914, ["name"] = "A Coalition of the Willing", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 62870, 62915 }, ["description"] = "The good people of Revendreth continue to suffer under the oppression of Denathrius's loyalists. We must bolster our forces before we can move openly against our former Master. The willing souls you recovered from the Maw will prove a boon in these trying times. Go to Foreman Flatfinger . He has been searching for assistance with building enhancements for our sanctum. Together, we will see Sinfall reach its full potential.", ["objectivesText"] = "Speak to Foreman Flatfinger .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.459, ["y"] = 0.276, ["mapID"] = 1699, ["npcID"] = 164738 } }, ["ends"] = { { ["x"] = 0.459, ["y"] = 0.276, ["mapID"] = 1699, ["npcID"] = 164738 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.459, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 164738, ["questTurnInID"] = 164738, ["questType"] = "standard", ["sourceQuests"] = { 62870 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 1204, ["name"] = "Sinfall", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 137, ["title"] = "Covenant Tutorials", ["questLineID"] = 1204, ["questLineOrder"] = 0 }, { ["id"] = 143, ["ti