[62915] = { ["id"] = 62915, ["name"] = "Home Improvement", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 62870, 62914 }, ["description"] = "I've been finkin' of a bit of ways we could improve the place, but since you brought in all of the anima and souls to do it, I fink you should be the one to decide which improvement we start on first. Don't get overwhelmed. As you bring in more anima and find more willin' souls, we'll be able to bring more capabilities to the place. For now, a single upgrade will fit the bill.", ["objectivesText"] = "Start a Sanctum Upgrade. Progress: Take your time. The first step's always the hard one.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.274, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["ends"] = { { ["x"] = 0.553, ["y"] = 0.274, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.553, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 172605, ["questTurnInID"] = 172605, ["questType"] = "standard", ["sourceQuests"] = { 62837 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 1204, ["name"] = "Sinfall", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 137, ["title"] = "Covenant Tutorials", ["questLineID"] = 1204, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
[62916] = { ["id"] = 62916, ["name"] = "Your Next Best Friend", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62916 }, ["description"] = "You looking for a new friend? Hoo-hoo! Lots of stewards who are happy to be friend. Plus, current friend can take break! Maybe go to Cliffs of Respite, rest feet, eat cake... < Sika gets lost in a daydream.> Hoo! Right! I call stewards. You make new friend!", ["objectivesText"] = "Select a new steward companion, then return to Sika . Progress: New friends, new friends! Stewards love making new friends!", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 175426, ["x"] = 0.53, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 175426, ["x"] = 0.53, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 59196 } },
[62917] = { ["id"] = 62917, ["name"] = "Shared Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1699, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 62918, 62919 }, ["description"] = "The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another. Doing so has no known drawbacks, but offers many advantages for both parties involved. The Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.", ["objectivesText"] = "Meet The Accuser at the Forge of Bonds.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
[62918] = { ["id"] = 62918, ["name"] = "Binding Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 62917, 62919 }, ["description"] = "The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another. To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly. You will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense. Once complete, your connection will transcend physical space and make you stronger in more than mere brawn.", ["objectivesText"] = "Complete the soulbinding ritual.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.462, ["y"] = 0.216, ["mapID"] = 1699, ["npcID"] = 171950 } }, ["ends"] = { { ["x"] = 0.462, ["y"] = 0.216, ["mapID"] = 1699, ["npcID"] = 171950 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.462, ["y"] = 0.216 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 171950, ["questTurnInID"] = 171950, ["questType"] = "standard", ["sourceQuests"] = { 62915 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[62919] = { ["id"] = 62919, ["name"] = "Strengthening the Bond", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 62917, 62918 }, ["description"] = "Do you feel it, too? Our connection is stronger than I imagined could be possible. I have been told that the bond will continue to grow over time, though we do have the ability to accelerate the process. Sinfall needs our strength. Perhaps it is best we engage in this method now.", ["objectivesText"] = "Use the Forge of Bonds to strengthen your bond with Nadjia. Do so by selecting a power and activating it. Progress: This will benefit us both.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 180847, 181373, 181467, 181469, 181512, 181539, 181639, 181707, 181774, 181775, 181840, 181962, 182106, 182108, 182113, 182129, 182130, 182133, 182288, 182317, 182324, 182331, 182335, 182336, 182347, 182348, 182448, 182460, 182463, 182466, 182469, 182584, 182651, 182685, 182767, 182777, 182962, 182964, 183199, 183463, 183466, 183467, 183473, 183474, 183494, 183495, 183496, 183500, 199456, 199459, 199460 }, ["starts"] = { { ["x"] = 0.439, ["y"] = 0.179, ["mapID"] = 1699, ["npcID"] = 171979 } }, ["ends"] = { { ["x"] = 0.439, ["y"] = 0.179, ["mapID"] = 1699, ["npcID"] = 171979 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.439, ["y"] = 0.179 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 171979, ["questTurnInID"] = 171979, ["questType"] = "standard", ["sourceQuests"] = { 62918 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] =