[62920] = { ["id"] = 62920, ["name"] = "A Conduit For Change", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 62921, 63033 }, ["description"] = "While the powers from your bond are substantial, you may also strengthen the bond further through the use of conduits. Conduits act to channel the energy of your soulbind into your form more directly, increasing your potential in many ways. Use the ones I have given you as a test of this power, but fear not--you will find others in your travels.", ["objectivesText"] = "Add the Conduits to the Forge of Bonds, then apply one to a slot on Nadjia the Mistblade. Progress: This step is crucial for your advancement.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.201, ["mapID"] = 1699, ["npcID"] = 171950 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.201, ["mapID"] = 1699, ["npcID"] = 171950 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.446, ["y"] = 0.201 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 171950, ["questTurnInID"] = 171950, ["questType"] = "standard", ["sourceQuests"] = { 62919 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
[62921] = { ["id"] = 62921, ["name"] = "Our True Purpose", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 62920, 63033 }, ["description"] = "We are grateful for this partnership, Maw Walker. With your help, Renathal will lead us into a new era, one that will see Revendreth reclaim its true purpose. Return to him now so that the real work can begin.", ["objectivesText"] = "Return to Prince Renathal .", ["rewardGold"] = 929400, ["rewardXP"] = 12250, ["rewardItems"] = { 180909, 180910, 180911, 180912 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.201, ["mapID"] = 1699, ["npcID"] = 171950 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.201, ["mapID"] = 1699, ["npcID"] = 171950 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.446, ["y"] = 0.201 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 171950, ["questTurnInID"] = 171950, ["questType"] = "standard", ["sourceQuests"] = { 62920 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[62928] = { ["id"] = 62928, ["name"] = "Blueprint: Ring of Warding", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62928 }, ["description"] = "<You have discovered plans for a defensive ward that may give your soulbinds an edge in the Path of Ascension. Dactylis should be able to help you with crafting this piece of equipment.>", ["objectivesText"] = "Bring the Blueprint: Ring of Warding to Dactylis . Provided item:", ["rewardItems"] = { 184348 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 184348 } },
[62932] = { ["id"] = 62932, ["name"] = "Explore Torghast", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1670, ["storyline"] = { 60139, 60146, 62836, 62932, 62935, 62938, 62966, 62969 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 63002, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "Baine is safe, but our other allies are still prisoners of the Jailer. They remain in grave peril. Torghast is a constantly changing place, shifting according to the will of its master. It may be impossible to track them through normal means. Enter its cell blocks and see what information you can find. Seek any clue that might lead us to our missing friends, and bring it back to me.", ["objectivesText"] = "Explore Torghast for clues to locate your allies. Progress: What did you find?", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardItems"] = { 184198, 184758 }, ["rewardChoices"] = { 184758 }, ["rewardCurrencies"] = { { ["id"] = 1828, ["amount"] = 200 } }, ["starts"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.399, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 61099 }, ["questLines"] = { { ["id"] = 1136, ["name"] = "Torghast", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 154, ["title"] = "Torghast Story Progression Skip", ["questLineID"] = 1136, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[62935] = { ["id"] = 62935, ["name"] = "Remnants of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1670, ["storyline"] = { 60139, 60146, 62836, 62932, 62935, 62938, 62966, 62969 }, ["description"] = "I studied the key you brought back from Torghast, <name>. It confirms that Jaina Proudmoore is still being held somewhere in the tower. However we do not know precisely where. Countless souls are captive inside that wretched place. A few may be intact, but many are shattered and broken. Take pity upon the remnants and free those you can. Perhaps they will be able to aid our search.", ["objectivesText"] = "See if you can gain any new insights from the trapped Soul Remnants in Torghast.", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardCurrencies"] = { { ["id"] = 1828, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.399, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 62932 }, ["questLines"] = { { ["id"] = 1136, ["name"] = "Torghast", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 154, ["title"] = "Torghast Story Progression Skip", ["questLineID"] = 1136, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[62938] = { ["id"] = 62938, ["name"] = "Information for a Price", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1670, ["storyline"] = { 60139, 60146, 62836, 62932, 62935, 62938, 62966, 62969 }, ["description"] = "We must continue our search for Jaina Proudmoore. I have a new strategy to suggest. Since arriving in Oribos, I have been approached by many of the brokers. Some ask questions, others offer help--for a price. You have encountered others of their kind inside Torghast. They may possess information we can use, though I doubt they will part with it freely. Seek them out and appeal to their avarice. Offer to pay for whatever information they possess.", ["objectivesText"] = "Question the Brokers trapped inside Torghast. Progress: A promising lead.", ["rewardGold"] = 1123600, ["rewardXP"] = 16330, ["rewardItems"] = { 184199, 184200 }, ["rewardCurrencies"] = { { ["id"] = 1828, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.399, ["y"] = 0.685, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.399, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 62935 }, ["questLines"] = { { ["id"] = 1136, ["name"] = "Torghast", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 154, ["title"] = "Torghast Story Progression Skip", ["questLineID"] = 1136, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[62951] = { ["id"] = 62951, ["name"] = "Path of Ascension: Kleia", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62951 }, ["description"] = "Artemede has been personally training Kleia , running her through combat meditations and drills. She has come far, and she is prepared to take on another trial in the Path of Ascension. Return to the coliseum and guide her as her tactician so that she may reach victory.", ["objectivesText"] = "Win any Path of Ascension trial as Kleia .", ["rewardItems"] = { 184812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[62952] = { ["id"] = 62952, ["name"] = "Path of Ascension: Pelagos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62952 }, ["description"] = "Though combat is not his strong suit, Pelagos has been reading, meditating, and training to better himself on the Path. We believe he is ready to seek victory. He requests you by his side to help him strategize. He is stronger with the help of his friends.", ["objectivesText"] = "Win any Path of Ascension trial as Pelagos .", ["rewardItems"] = { 184812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[62953] = { ["id"] = 62953, ["name"] = "Path of Ascension: Mikanikos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62953 }, ["description"] = "Mikanikos has been hard at work at the Eternal Forge, calibrating Bron and tuning his combat procedures. He is confident in his recent changes, and requests permission to attempt another trial. Enter the Path with Mikanikos so that he may assess his goliath's strengths and weaknesses.", ["objectivesText"] = "Win any Path of Ascension trial as Mikanikos .", ["rewardItems"] = { 184812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[62954] = { ["id"] = 62954, ["name"] = "Path of Ascension: Kalisthene", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62954 }, ["description"] = "Your soulbinds request your strategic mind in another trial. Their sights this week are set on Kalisthene , that they may learn from the lessons her memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Kalisthene to prove their growth.", ["objectivesText"] = "Defeat Kalisthene in the Path of Ascension with any soulbind.", ["rewardItems"] = { 184812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[62966] = { ["id"] = 62966, ["name"] = "Finding a Witness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1670, ["storyline"] = { 60139, 60146, 62836, 62932, 62935, 62938, 62966, 62969 }, ["description"] = "You have rescued two of our allies from Torghast, but Anduin and Thrall have yet to be found. That tower's corridors are vast... seemingly endless. You could spend an eternity wandering those unholy halls. In your expeditions, you have encountered many unfortunate prisoners. Perhaps one of them has seen or heard something that could guide our search. Seek out any captives that might have the information we need, <name>.", ["objectivesText"] = "Look for a prisoner in Torghast who might know where Anduin or Thrall is being held.", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardCurrencies"] = { { ["id"] = 1828, ["amount"] = 50 } }, ["starts"] = { { ["x"] = 0.4, ["y"] = 0.653, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["x"] = 0.4, ["y"] = 0.653, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.4, ["y"] = 0.653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questTurnInID"] = 164079, ["questType"] = "standard", ["sourceQuests"] = { 60139 }, ["questLines"] = { { ["id"] = 1136, ["name"] = "Torghast", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 154, ["title"] = "Torghast Story Progression Skip", ["questLineID"] = 1136, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[62967] = { ["id"] = 62967, ["name"] = "Prison of the Forgotten", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["description"] = "I discovered an interesting item off the Warden you killed in the tower. Best not to ask how I know what you do and where you do it within the tower. Let's just say, I have my ways. But this key could lead to something interesting within Torghast. Or something horrible. Most likely horrible. You ought to explore a bit and see what it unlocks.", ["objectivesText"] = "Figure out where to use the Key of the Forgotten. Provided item:", ["rewardXP"] = 4085, ["rewardItems"] = { 178585 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questTurnInID"] = 162804, ["questType"] = "standard", ["sourceQuests"] = { 61099 }, ["questLines"] = { { ["id"] = 1210, ["name"] = "Torghast", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1242, ["name"] = "Torghast", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1243, ["name"] = "Torghast", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1244, ["name"] = "Torghast", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1245, ["name"] = "Torghast", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1210, ["