[63002] = { ["id"] = 63002, ["name"] = "Dangerous to Go Alone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 57895, 57897, 57898, 57904, 57905, 60287, 60289, 60491, 60492, 60504, 61332, 61355, 61982, 62698, 62789, 62790, 62791, 62792, 62793, 62794, 62795, 62796, 62832, 62837, 62861, 62862, 62863, 62882, 63002, 63211, 65147, 65168 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63003, 63008, 63029, 63030, 63032 }, ["description"] = "I trust you know well all that Elysian Hold can provide, but that alone will not be enough to thwart Denathrius. You must have a soulbind to aid you, Maw Walker. Seek out Soulguide Daelia in the chamber below. She has prepared for the ritual.", ["objectivesText"] = "Speak with Soulguide Daelia in the Sanctum of Binding.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1014, ["name"] = "Among the Kyrian", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1014, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1708 },
[63003] = { ["id"] = 63003, ["name"] = "Collective Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 58609, 59556, 59596, 59597, 59609, 60287, 60289, 61333, 61355, 61359, 61388, 61397, 61983, 62833, 62834, 62835, 62837, 62839, 62840, 62843, 62844, 62845, 62846, 62848, 62864, 62865, 62866, 62882, 63003, 63212, 65157, 65165 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63008, 63029, 63030, 63032 }, ["description"] = "You know conflict as well as any soldier in Maldraxxus, Maw Walker. But we do not fight alone. There is great wisdom in leaning on the strengths of your allies. That is the Maldraxxi way. Speak to Plague Deviser Marileth . He will show you how to soulbind and best reap its benefits.", ["objectivesText"] = "Speak with Plague Deviser Marileth about the soulbinding process.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.504, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["ends"] = { { ["x"] = 0.497, ["y"] = 0.504, ["mapID"] = 1698, ["npcID"] = 161907 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.497, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161907, ["questTurnInID"] = 161907, ["questType"] = "standard", ["sourceQuests"] = { 62846 }, ["questLines"] = { { ["id"] = 1087, ["name"] = "Loyal to the Primus", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1087, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698 },
[63006] = { ["id"] = 63006, ["name"] = "For Queen and Grove!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63101 }, ["description"] = "You have already done so much to help us since you first step foot in our realm! I'm so glad you decided to join our covenant. There will be plenty of time for reminiscing later, though. You have an audience with the Winter Queen herself to go to! Let's not keep her waiting!", ["objectivesText"] = "Join the Night Fae Covenant. Progress: Welcome to the Hunt.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.401, ["mapID"] = 1701, ["npcID"] = 161509 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 156634, ["x"] = 0.454, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questGiverID"] = 161509, ["questType"] = "standard", ["sourceQuests"] = { 58104 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1703 },
[63008] = { ["id"] = 63008, ["name"] = "The Forge of Bonds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 58104, 58157, 58158, 58159, 58160, 60287, 60289, 61331, 61355, 61475, 61479, 61541, 61542, 61550, 61984, 62697, 62837, 62858, 62859, 62860, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62894, 62897, 62898, 62899, 62900, 63006, 63008, 63214 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63029, 63030, 63032 }, ["description"] = "To best serve the court and the forest, you must bond with another fae. It is an ancient ritual, one which will grant you great strength to face the many trials ahead. Flutterby below will guide you further.", ["objectivesText"] = "Meet Flutterby at the Forge of Bonds.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 156634, ["x"] = 0.454, ["y"] = 0.655 }, { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 156634, ["x"] = 0.454, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questTurnInID"] = 156634, ["questType"] = "standard", ["sourceQuests"] = { 58160 }, ["questLines"] = { { ["id"] = 1098, ["name"] = "For Queen and Grove!", ["orderIndex"] = 26, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1098, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701 },
[63022] = { ["id"] = 63022, ["name"] = "Rule 6 Addendum: Save Me At Any Cost", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60158, 60281, 60284, 60285, 62461, 63022, 63051 }, ["series"] = { 63060 }, ["description"] = "You! You, there! Wait! You are the infamous Maw Walker, yes? I have heard much about you. Please, help me! My compatriots have been drained of their essence. The Mawsworn are using it to fashion their foul runes. One of them bound me here, and I am sure to be next on his list. You must slay him in order to free me! I can make it worth your while. I have collected a fair amount of stygia during my time in the Maw . It is yours, all of it, if you save me!", ["objectivesText"] = "Slay Runemaster Mavrok . Progress: There is no time to waste. Hurry, before the Mawsworn return!", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 182955 }, ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 223 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 175703, ["x"] = 0.57, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 175703, ["x"] = 0.57, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 60284, 63060 }, ["questLines"] = { { ["id"] = 1200, ["name"] = "New Rules", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63029] = { ["id"] = 63029, ["name"] = "The Highlord Calls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1533, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["series"] = { 57897, 57898, 57899, 57900, 57904, 59596, 59609, 60136, 60504, 61099, 61359, 61541, 61542, 61550, 62793, 62794, 62795, 62796, 62845, 62846, 62848, 62894, 62897, 62899, 62900, 62932, 63002, 63003, 63008, 63030, 63032 }, ["description"] = "We have received word from Highlord Fordragon urging you to return to him in Oribos at once. All I know is it pertains to the Maw . You should go to him with haste. Anything involving that dark place must be our top priority.", ["objectivesText"] = "Report to Highlord Bolvar Fordragon in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questTurnInID"] = 160037, ["questType"] = "standard", ["sourceQuests"] = { 57904 }, ["questLines"] = { { ["id"] = 1210, ["name"] = "Torghast", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1243, ["name"] = "Torghast", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 141, ["title"] = "Catching