[63033] = { ["id"] = 63033, ["name"] = "The Highlord Calls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1670, ["storyline"] = { 60136, 60267, 60268, 60269, 60270, 60271, 60272, 61099, 62967, 63029, 63030, 63032, 63033 }, ["series"] = { 62920, 62921 }, ["description"] = "A messenger from Oribos has informed us that Highlord Fordragon has requested your presence in Oribos. It seems it pertains to the Maw ... and the Master's plans, no doubt. I suggest you heed his summons, Maw Walker. We must leave nothing to chance.", ["objectivesText"] = "Report to Highlord Bolvar Fordragon in Oribos.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.512, ["y"] = 0.378, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["ends"] = { { ["x"] = 0.512, ["y"] = 0.378, ["mapID"] = 1699, ["npcID"] = 158653 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.512, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 158653, ["questTurnInID"] = 158653, ["questType"] = "standard", ["sourceQuests"] = { 59324, 62921 }, ["questLines"] = { { ["id"] = 1210, ["name"] = "Torghast", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1245, ["name"] = "Torghast", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 119, ["title"] = "Kyrian Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 115, ["title"] = "The Art of War", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 117, ["title"] = "Night Fae Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1210, ["questLineOrder"] = 1 }, { ["id"] = 143, ["title"] = 