[63034] = { ["id"] = 63034, ["name"] = "The Elysian Fields", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["storyline"] = { 63034 }, ["series"] = { 62707, 62723, 62729 }, ["description"] = "You must travel to Bastion , eternal home of the winged kyrian. Do not be fooled by their golden fields and shining spires--the kyrian have been weakened by the great anima drought, and face the brink of civil war against their own fallen brethren. They will benefit greatly from your aid. Seek one known as Kalisthene in your new sanctum, Elysian Hold. She will direct you further. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", ["objectivesText"] = "Speak to Kalisthene at Elysian Hold in Bastion .", ["rewardGold"] = 18275, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.7, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.388, ["y"] = 0.7, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.388, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 62275 } },
[63035] = { ["id"] = 63035, ["name"] = "A Fresh Blade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 63035 }, ["series"] = { 62738, 62748, 62761 }, ["description"] = "Though they were once unified in defending the Shadowlands, the houses of Maldraxxus have turned against each other. Their armies clash within their realm and have even orchestrated an assault on Bastion. Now only the Necrolords remain loyal to the Primus. Speak to Secutor Mevix at the Seat of the Primus in Maldraxxus . His tactical skills will ensure you are sent where you are most needed. Pathscribe Roh-Avonavi in the Ring of Transference above can provide you with transportation.", ["objectivesText"] = "Speak to Secutor Mevix at the Seat of the Primus in Maldraxxus .", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.7, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 175008, ["x"] = 0.528, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 62278 } },
[63036] = { ["id"] = 63036, ["name"] = "Restoring Balance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 63036 }, ["series"] = { 62739, 62763, 62776 }, ["description"] = "Ardenweald is crucial to the cycle of rebirth for nature spirits that enter their realm. Unfortunately, the anima drought has led to the loss of entire groves--souls that will never complete their cycle. Now foes seek to destroy what remains of the once tranquil forests, threatening the already beleaguered Court of Night. Lady Moonberry of the Court has requested aid. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", ["objectivesText"] = "Speak to Lady Moonberry at the Heart of the Forest in Ardenweald .", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.7, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 62277 } },
[63037] = { ["id"] = 63037, ["name"] = "Dark Aspirations", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["storyline"] = { 63037 }, ["series"] = { 62740, 62778, 62779 }, ["description"] = "Prince Renathal has started a daring rebellion against his father, the nefarious Sire Denathrius who betrayed us all by pouring Revendreth 's vast anima stores into the Maw. You must travel to Revendreth and aid Renathal in his efforts. He is our best hope at restoring Revendreth to order. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", ["objectivesText"] = "Speak to Prince Renathal in Sinfall in Revendreth .", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.7, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.388, ["y"] = 0.7, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.388, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 62279 } },
[63038] = { ["id"] = 63038, ["name"] = "Guaranteed Delivery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["description"] = "Ve'nari . Clutched in their hand is a list of items and a containment orb . Finishing this broker's task and sending the items back to Ve'nari will surely earn you some compensation.>", ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 600 }, { ["id"] = 1880, ["amount"] = 475 } }, ["starts"] = { { ["npcID"] = 175797, ["x"] = 0.306, ["y"] = 0.584, ["mapID"] = 1543 } }, ["ends"] = { { ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416, ["mapID"] = 1543 } }, ["coords"] = { ["x"] = 0.306, ["y"] = 0.584, ["source"] = "quest_giver", ["mapID"] = 1543 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "group", ["sourceQuests"] = { 60284 } },
[63039] = { ["id"] = 63039, ["name"] = "A Monument to Vengeance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63039 }, ["description"] = "<Corpses of Ebon Blade knights litter the Crucible of the Damned, displaying the aftermath of your first foray into this desolate place. Their sacrifice should not be forgotten.>", ["objectivesText"] = "Collect 8 Ebon Runeblades and build a monument to the Ebon Blade's sacrifice in the Crucible of the Damned. Progress: <This precipice is highly visible throughout the Maw . Building the monument here will surely draw the Jailer's ire.>", ["rewardItems"] = { 184511 }, ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 400 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 175807, ["x"] = 0.222, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 175807, ["x"] = 0.222, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questTurnInID"] = 175807, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
