[63045] = { ["id"] = 63045, ["name"] = "Feed Your Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["description"] = "They... drained my anima... to fuel their ritual... Souls of great power are brought here... to this altar... and sacrificed to conjure unspeakable horrors bound to the Jailer. I was powerful once... Imbue me with the anima they stole... and I can be powerful again. Then, together... we will destroy the one who leads their efforts.", ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 600 }, { ["id"] = 1880, ["amount"] = 475 } }, ["starts"] = { { ["npcID"] = 175866, ["x"] = 0.25, ["y"] = 0.666, ["mapID"] = 1543 } }, ["ends"] = { { ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416, ["mapID"] = 1543 } }, ["coords"] = { ["x"] = 0.25, ["y"] = 0.666, ["source"] = "quest_giver", ["mapID"] = 1543 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "group", ["sourceQuests"] = { 60284 } },
[63046] = { ["id"] = 63046, ["name"] = "The End and the Beginning", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 63046 }, ["description"] = "I am so happy you restored our connection to the Queen's Conservatory! In light of this accomplishment, the Winter Queen has requested you attend her at the Grove of Awakening! You will see first hand the purpose of Ardenweald and gain a greater understanding of our sacred charge before you too, take it upon yourself. Hurry! Don't keep everyone waiting!", ["objectivesText"] = "Learn about Wildseeds from the Winter Queen .", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 129258, 129259, 129260, 129346, 129347, 129348, 129349, 141393, 175176, 175177, 175178, 175179, 175208, 175209, 175210, 175211 }, ["starts"] = { { ["x"] = 0.56, ["y"] = 0.682, ["mapID"] = 1702, ["npcID"] = 173171 } }, ["ends"] = { { ["x"] = 0.56, ["y"] = 0.682, ["mapID"] = 1702, ["npcID"] = 173171 } }, ["coords"] = { ["mapID"] = 1702, ["x"] = 0.56, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 173171, ["questTurnInID"] = 173171, ["questType"] = "standard", ["sourceQuests"] = { 62624 } },
[63047] = { ["id"] = 63047, ["name"] = "Acquisition: Runeforged Shackles", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63047 }, ["description"] = "<The chains here are carved with domination runes, imbuing them with the magic needed to subdue the most powerful of the Mawsworn's prisoners. No doubt Ve'nari could find some use in studying these runes.>", ["objectivesText"] = "Collect 9 Runeforged Shackles and return them to Ve'nari in the Maw . Progress: Another transaction?", ["rewardItems"] = { 184552 }, ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 400 } }, ["starts"] = { { ["x"] = 0.256, ["y"] = 0.242, ["mapID"] = 1543, ["objectID"] = 364926 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63050] = { ["id"] = 63050, ["name"] = "Acquisition: Blazing Ingots", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63050 }, ["description"] = "<The runesmiths have imbued this ingot with an enchantment that causes it to burn with inextinguishable flames. It is likely that this metal is used to empower the Mawsworn protectors of Zovaal's Cauldron. Bringing some samples of this ore to Ve'nari could aid her attempts at unlocking the Jailer's secrets.>", ["objectivesText"] = "Collect 12 Blazing Ingots and return them to Ve'nari in the Maw . Progress: What's this?", ["rewardItems"] = { 184556 }, ["rewardCurrencies"] = { { ["id"] = 1880, ["amount"] = 175 } }, ["starts"] = { { ["x"] = 0.39, ["y"] = 0.399, ["mapID"] = 1543, ["objectID"] = 364932 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63051] = { ["id"] = 63051, ["name"] = "Trust Issues", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60158, 60281, 60284, 60285, 62461, 63022, 63051 }, ["description"] = "Ah, Maw Walker! Allow me to introduce myself. I am Ve'rayn . I deal with assets and liabilities for Cartel Ve. I have heard that you are able to freely travel between Oribos and the Maw , a place of great interest to my cartel. Would you mind if I ask you a few questions about it? You will, of course, be properly compensated for your time and information. They are the most valuable of commodities, after all.", ["objectivesText"] = "Answer Ve'rayn 's questions about the Maw .", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 178585, 187264 }, ["starts"] = { { ["npcID"] = 168432 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questGiverID"] = 168432, ["questType"] = "standard", ["sourceQuests"] = { 61099 }, ["questLines"] = { { ["id"] = 1200, ["name"] = "New Rules", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63052] = { ["id"] = 63052, ["name"] = "Step of Faith", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63052, 63053 }, ["description"] = "Our ascended fly across Bastion with ease, ensuring safety and prosperity across the realm. Long ago we established a network of anima gateways to help our aspirants, goliaths, and stewards traverse our realm more quickly. Go forth and activate the network once more, so that you too may be wherever you are needed in the mere blink of an eye.", ["objectivesText"] = "Activate the Transportation Network.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 167745, ["x"] = 0.648, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questTurnInID"] = 167745, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1206, ["name"] = "Transport Network", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[63053] = { ["id"] = 63053, ["name"] = "At a Moment's Notice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 63052, 63053 }, ["description"] = "No longer must you take a larion across Bastion, Maw Walker. With our gateways active once more, you shall enjoy instantaneous travel wherever you are needed. Do note that you must still utilize a larion to return to Oribos or travel to the other realms. Give it a try and see for yourself.", ["objectivesText"] = "Use the Eternal Gateway to travel somewhere in Bastion, then use any Eternal Gateway to return to Elysian Hold. Progress: It really is amazing, is it not?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.489, ["y"] = 0.627, ["mapID"] = 1707, ["npcID"] = 175907 } }, ["ends"] = { { ["x"] = 0.489, ["y"] = 0.627, ["mapID"] = 1707, ["npcID"] = 175907 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.489, ["y"] = 0.627 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 175907, ["questTurnInID"] = 175907, ["questType"] = "standard", ["sourceQuests"] = { 63052 }, ["questLines"] = { { ["id"] = 1206, ["name"] = "Transport Network", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[63054] = { ["id"] = 63054, ["name"] = "Strength in Numbers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["storyline"] = { 63054 }, ["series"] = { 59598, 59603, 61388 }, ["description"] = "Every soul in Maldraxxus has the potential for greatness, and we will need all we can muster if we hope to restore order to the Shadowlands. With this addition to the sanctum, we can mobilize our forces and give them the chance to prove themselves on the field of battle. Seek out Merick Feldscar . He will see to the deployment of our soldiers.", ["objectivesText"] = "Activate the Command Table.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161909, ["questTurnInID"] = 161909, ["questType"] = "standard" },
[63055] = { ["id"] = 63055, ["name"] = "Powering the Portals", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["storyline"] = { 63055 }, ["series"] = { 63059 }, ["description"] = "The Primus once maintained a network of portals that linked the necropoli of Maldraxxus directly to the Seat of the Primus. The lack of anima and recent destruction of many of the necropoli have rendered those connections inactive. With the anima you have provided us, we have managed to reconnect one of those portals. You shall once more be able to travel to one of our great necropoli... assuming it still exists.", ["objectivesText"] = "Activate the Transportation Network.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161909, ["questTurnInID"] = 161909, ["questType"] = "standard" },
[63056] = { ["id"] = 63056, ["name"] = "Sanctum Upgrade: Mirror Network", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1699, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427, 63056 }, ["series"] = { 57531, 60051 }, ["description"] = "Right. So, we got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work. Thing is, after you going to need a proper mirror maker to get 'em up an' workin'. Prince Renathal might know a fang with the right skills. Best speak with him.", ["objectivesText"] = "Use the Scroll of Dark Empowerment to conjure a Mirror Network. Progress: Enough anima in the right hands and we can construct whatever is needed in Revendreth .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.271, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["ends"] = { { ["x"] = 0.553, ["y"] = 0.271, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.553, ["y"] = 0.271 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 172605, ["questTurnInID"] = 172605, ["questType"] = "standard", ["sourceQuests"] = { 62915 }, ["questLines"] = { { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
[63057] = { ["id"] = 63057, ["name"] = "Restoring Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["storyline"] = { 63057 }, ["series"] = { 60722 }, ["description"] = "Anima is power, <name>! When it was plentiful, the Primus ensured that his soldiers received all of the anima they required. Now, in the midst of this drought, the Maldraxxi fight amongst themselves for any anima they can find. As our stockpile of anima grows, we can distribute it throughout Maldraxxus. It falls to us Necrolords to carry out the Primus's duty in his absence. Speak to Yondare Hex . She will show you how to do so.", ["objectivesText"] = "Activate the Anima Conductor. Progress: Yes, yes, you! You can help!", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.524, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 161909, ["questTurnInID"] = 161909, ["questType"] = "standard" },
[63058] = { ["id"] = 63058, ["name"] = "Abominable Stitching and Me", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 63058 }, ["description"] = "Constructs have formed the backbone of Maldraxxi armies in more wars than anyone can count. A well-constructed body can turn any soul into a potent frontline weapon. There is an old abominable stitching table outside of the sanctum that could be used to build our own constructs. With the anima you've secured for our covenant, we should be able to restore it. Report to Miggsie once the work has begun. You can find her at Butchers Block.", ["objectivesText"] = "Activate the Abomination Factory. Progress: You made the right choice.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.384, ["mapID"] = 1698, ["npcID"] = 161909 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 175967, ["x"] = 0.548, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questGiverID"] = 161909, ["questType"] = "standard" },
[63059] = { ["id"] = 63059, ["name"] = "Blink of an Eye", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12876, ["storyline"] = { 63059 }, ["series"] = { 63055 }, ["description"] = "This was once a long tauralus ride, but not anymore! By simply stepping through this portal, you can now journey to the House of Eyes in an instant. The House of Eyes may not be what it once was, but valuable allies can still be found in the ruins of their once great necropolis. Travel there now to test the portal's functionality.", ["objectivesText"] = "Travel through the Nurakkir, House of Eyes portal, then use the Seat of the Primus portal to return. Progress: It worked! That was most unexpected.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 140192, 143785 }, ["starts"] = { { ["x"] = 0.598, ["y"] = 0.318, ["mapID"] = 1698, ["npcID"] = 175963 } }, ["ends"] = { { ["x"] = 0.598, ["y"] = 0.318, ["mapID"] = 1698, ["npcID"] = 175963 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.598, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 175963, ["questTurnInID"] = 175963, ["questType"] = "standard", ["sourceQuests"] = { 63055 } },
[63060] = { ["id"] = 63060, ["name"] = "Rule 6 Footnote: Don't Forget Anything", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63060 }, ["series"] = { 63022 }, ["description"] = "In the Maw , you must never forget to take everything with you. Many things crawl within the Beastwarrens. The runes you brought back indicate that something of interest may have been left behind by the brokers who were taken there. See if you can find it.", ["objectivesText"] = "Look for whatever was left behind by the brokers in the Beastwarrens.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 182955 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 175703, ["x"] = 0.57, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 60285 }, ["nextQuests"] = { 63022 } },
[63062] = { ["id"] = 63062, ["name"] = "Torment for the Taking", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63062 }, ["description"] = "<A broker device has been abandoned here. It seems like it was being used to siphon energy from rifts of soul energy that have erupted in the area. The brokers surely would not have sought to harness this energy if it didn't have a use. Perhaps you should finish what they started.>", ["objectivesText"] = "Fill the Phasic Siphoner from the Soul Fissures in Detrithos and return it to Ve'nari in the Maw .", ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 400 } }, ["starts"] = { { ["x"] = 0.28, ["y"] = 0.47, ["mapID"] = 1543, ["objectID"] = 364937 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63063] = { ["id"] = 63063, ["name"] = "Sanctum Upgrade: Mirror Network", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 63063 }, ["description"] = "We got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work. Once you do the conjurin', then ol' Laurent should be able to work 'is magic as it were. Right proper glass guy he is.", ["objectivesText"] = "Use the Scroll of Dark Empowerment to conjure a Mirror Network.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["npcID"] = 172605, ["x"] = 0.558, ["y"] = 0.272, ["mapID"] = 1525 } }, ["ends"] = { { ["npcID"] = 167160, ["x"] = 0.47, ["y"] = 0.572, ["mapID"] = 1525 } }, ["coords"] = { ["x"] = 0.558, ["y"] = 0.272, ["source"] = "quest_giver", ["mapID"] = 1525 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard" },
[63064] = { ["id"] = 63064, ["name"] = "Sanctum Upgrade: Command Table", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["storyline"] = { 63064 }, ["series"] = { 59319 }, ["description"] = "We got a Scroll of Dark Empowerment ready for youz that should manifest a command table for you. Not just any command table, but one of 'em magic ones that lets you issue orders from afar. Tactician Sakaa insisted she be your wing for that one. Never much trusted 'em wings as they ain't too kind to us dredgers but put 'em in charge of war and even Maldraxxus flinches.", ["objectivesText"] = "Use the Scroll of Dark Empowerment to conjure a Command Table. Progress: Maw Walker.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.554, ["y"] = 0.27, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["ends"] = { { ["x"] = 0.554, ["y"] = 0.27, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.554, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 172605, ["questTurnInID"] = 172605, ["questType"] = "standard" },
[63065] = { ["id"] = 63065, ["name"] = "Sanctum Upgrade: The Ember Court", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["storyline"] = { 63065 }, ["series"] = { 59660 }, ["description"] = "We got a Scroll of Dark Empowerment ready for youz that should provide you with enough resources to get one of 'em fancy parties the fangs are fond of. The Mad Duke is the one you should chat with 'bout this one. He used to run all the court parties back before he got roasted.", ["objectivesText"] = "Use the Scroll of Dark Empowerment to begin the Ember Court.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.555, ["y"] = 0.27, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["ends"] = { { ["x"] = 0.555, ["y"] = 0.27, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.555, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 172605, ["questTurnInID"] = 172605, ["questType"] = "standard" },
[63066] = { ["id"] = 63066, ["name"] = "Sanctum Upgrade: Anima Conductor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["storyline"] = { 63066 }, ["series"] = { 60721 }, ["description"] = "Right. So we got all this anima you been collecting. Thing is, all that anima originally got squeezed out of the other realms. The Master, he was big on drainin' anything that weren't him. So, we set up a Scroll of Dark Empowerment for you on the lower level. Should conjure somefin' strong enough for you to channel anima back into the Shadowlands, by way of Revendreth Wards. Seems to me there'd be some fringe benefits from somefin like that.", ["objectivesText"] = "Use the Scroll of Dark Empowerment to conjure an Anima Conductor.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.554, ["y"] = 0.27, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["ends"] = { { ["x"] = 0.554, ["y"] = 0.27, ["mapID"] = 1699, ["npcID"] = 172605 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.554, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 172605, ["questTurnInID"] = 172605, ["questType"] = "standard" },
[63067] = { ["id"] = 63067, ["name"] = "Root Restoration", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 63067 }, ["series"] = { 60723 }, ["description"] = "Anima once flowed freely, but we have been thirsting. You bring us nourishment in times of trouble. We grow. We may now help others and share our bounty. Watch our growth, then speak with Sesselie . They will guide you further.", ["objectivesText"] = "Activate the Anima Conductor, then seek out Sesselie . Progress: Ah. You're here. Good.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.396, ["y"] = 0.55, ["mapID"] = 1702, ["npcID"] = 165702 } }, ["ends"] = { { ["x"] = 0.396, ["y"] = 0.55, ["mapID"] = 1702, ["npcID"] = 165702 } }, ["coords"] = { ["mapID"] = 1702, ["x"] = 0.396, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 165702, ["questTurnInID"] = 165702, ["questType"] = "standard" },
[63068] = { ["id"] = 63068, ["name"] = "Settling Disputes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63068 }, ["description"] = "In my search to find kyrian that would fit our purposes here, I have landed on two in particular -- Pelodis and Nemea . However, the two are involved in quite the rivalry, and struggle to focus their attention elsewhere. I propose that you aid them in settling their dispute so that they may focus on the task at hand. I doubt they shall work together, however, so you will need to pick one to aid us.", ["objectivesText"] = "Meet with Pelodis at Forgefire Outpost or Nemea at Nemea 's Retreat.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 42997 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160389, ["x"] = 0.648, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 }, { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 57899 }, ["nextQuests"] = { 57931, 58037 } },
[63069] = { ["id"] = 63069, ["name"] = "What They Know", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63069 }, ["description"] = "<It looks like this broker was gathering information before he met his unfortunate end. Ve'nari would likely be very interested in what he found. Unfortunately, his notes look to have been scattered far and wide by the local beasts.>", ["objectivesText"] = "Collect 18 Torn Journal Pages in the Hungering Wastes and return them to Ve'nari in the Maw . Progress: That book... that is a pathfinder's journal you carry!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 184579 }, ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 400 }, { ["id"] = 1880, ["amount"] = 175 } }, ["starts"] = { { ["x"] = 0.464, ["y"] = 0.623, ["mapID"] = 1543, ["objectID"] = 364987 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 60285 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63072] = { ["id"] = 63072, ["name"] = "Acquisition: Stygic Ore", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63072 }, ["description"] = "<The rock columns in this area are teeming with veins of a glowing, otherworldly metal. The Mawsworn have employed souls to mine it, but it looks like they didn't last long. Ve'nari could certainly find use for some of this ore, if you can manage to mine it.>", ["objectivesText"] = "Collect 15 pieces of Stygic Ore in Marrow's Coppice and return them to Ve'nari in the Maw . Progress: What do you carry, Maw Walker?", ["rewardItems"] = { 184585 }, ["rewardCurrencies"] = { { ["id"] = 1767, ["amount"] = 400 } }, ["starts"] = { { ["x"] = 0.472, ["y"] = 0.827, ["mapID"] = 1543, ["objectID"] = 364994 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
