[63179] = { ["id"] = 63179, ["name"] = "Drowned and Torn Asunder", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63179 }, ["description"] = "Maw Walker! I am relieved to see you in this place. A dark sect of kyrian who have allied themselves with the Maw stole my brothers and sisters from their posts in Bastion. They turned us over to a foul sea witch, the likes of which I've never seen. This... Helya, I believe they called her... seems determined to break us so that we might also join her ranks. Please, if you can, save my brethren.", ["objectivesText"] = "Free 8 Drowning Kyrian in Gorgoa, the River of Souls.", ["rewardCurrencies"] = { { ["id"] = 1880, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 176144, ["x"] = 0.388, ["y"] = 0.235 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 176144, ["x"] = 0.388, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63181] = { ["id"] = 63181, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63181 }, ["description"] = "Are you prepared for a challenge, <name>? It seems Pelagos has been struggling with his trials. I believe, with your guidance, some extra training on the Path is just what he needs! Athanos has many lessons to teach. With your aid, Pelagos can achieve victory and new experience to meditate on.", ["objectivesText"] = "Defeat Athanos as Pelagos in a Trial of Loyalty or higher in the Path of Ascension.", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63182] = { ["id"] = 63182, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63182 }, ["description"] = "Are you prepared for a challenge, <name>? Pelagos's time spent in Ardenweald taught him many lessons. I would like to witness what he has learned. A trial against Nuuminuuru should allow him this chance. With your aid, Pelagos can achieve victory and new experience to meditate on.", ["objectivesText"] = "Defeat Nuuminuuru as Pelagos in a Trial of Loyalty or higher in the Path of Ascension. Progress: Are you up for the challenge?", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63184] = { ["id"] = 63184, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63184 }, ["description"] = "Are you prepared for a challenge, <name>? Mikanikos has requested an additional trial to train Bron. Splinterbark Nightmare's memory was captured with the help of his praetors, and should prove a worthy challenge for his goliath. With your guidance, Mikanikos and Bron can overcome another trial.", ["objectivesText"] = "Defeat Splinterbark Nightmare as Mikanikos in a Trial of Loyalty or higher in the Path of Ascension.", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63185] = { ["id"] = 63185, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63185 }, ["description"] = "Are you prepared for a challenge, <name>? Kleia is ready for another challenge. She is hungry to get back to the Path so she may exercise her new abilities further. Echthra's memory shall provide her with new lessons. With your aid, Kleia can overcome this challenge and incorporate its lessons into her eternal training.", ["objectivesText"] = "Defeat Echthra as Kleia in a Trial of Loyalty or higher in the Path of Ascension. Progress: Are you up for the challenge?", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[63186] = { ["id"] = 63186, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63186 }, ["description"] = "Are you prepared for a challenge, <name>? Kleia is ready for another challenge. She is hungry to get back to the Path so she may exercise her new abilities further. If she is to bear souls across the veil, she will need be prepared to contend against devourers like Azaruux. With your aid, Kleia can overcome this challenge and incorporate its lessons into her eternal training.", ["objectivesText"] = "Defeat Azaruux as Kleia in a Trial of Loyalty or higher in the Path of Ascension.", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
