[63188] = { ["id"] = 63188, ["name"] = "Path of Ascension: Artemede's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63188 }, ["description"] = "Are you prepared for a challenge, <name>? Thenios has requested a Trial of Wisdom to exercise your strategic mind, as well as your soulbinds' abilities. A trial against Alderyn and Myn'ir shall suffice. Let us see you and your soulbinds can do.", ["objectivesText"] = "Defeat Alderyn and Myn'ir in a Trial of Wisdom in the Path of Ascension. Progress: Are you up for the challenge?", ["rewardItems"] = { 184811 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168427, ["x"] = 0.628, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
