[63210] = { ["id"] = 63210, ["name"] = "The Last Step", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 63210 }, ["description"] = "Just one realm remains which requires your aid, mortal. Speak with me when you are ready, and I shall inform you further. Such is the Purpose.", ["objectivesText"] = "Choose where to go in the Shadowlands.", ["rewardGold"] = 128700, ["rewardXP"] = 3410, ["rewardItems"] = { 106135, 106149, 106157, 107302, 210957, 245438 }, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.699, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.388, ["y"] = 0.699, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.388, ["y"] = 0.699 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 63209 } },
