[63215] = { ["id"] = 63215, ["name"] = "Report to Draven", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 59314, 59315, 59321, 59323, 62695, 62856, 62857, 62870, 62902, 62903, 62904, 62905, 62914, 62915, 62917, 62918, 62919, 62920, 62921, 63215 }, ["series"] = { 59314, 59315 }, ["description"] = "You have chosen well. The Venthyr must return to their duty helping souls atone for their sins, saving them from an eternity in the Maw. Denathrius's treachery must be righted. Speak with General Draven and begin your future with your covenant.", ["objectivesText"] = "Report to General Draven .", ["rewardGold"] = 28300, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.392, ["y"] = 0.697, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.392, ["y"] = 0.697, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.392, ["y"] = 0.697 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 57878, 62000 }, ["nextQuests"] = { 59314 }, ["questLines"] = { { ["id"] = 1065, ["name"] = "Sinfall", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1241, ["name"] = "Catching Up!", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 113, ["title"] = "Venthyr Campaign", ["questLineID"] = 1065, ["questLineOrder"] = 0 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1241, ["questLineOrder"] = 0 }, { ["id"] = 151, ["title"] = "Intro Start", ["questLineID"] = 1241, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[63340] = { ["id"] = 63340, ["name"] = "Sinfall Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1670, ["storyline"] = { 63340, 63341 }, ["description"] = "Sinfall's influence grows thanks to your triumphs, <name>! Your accomplishments have not gone unnoticed, even beyond the borders of Revendreth. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["x"] = 0.541, ["y"] = 0.268, ["mapID"] = 1699, ["npcID"] = 175772 } }, ["ends"] = { { ["x"] = 0.541, ["y"] = 0.268, ["mapID"] = 1699, ["npcID"] = 175772 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.541, ["y"] = 0.268 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 175772, ["questTurnInID"] = 175772, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1211, ["name"] = "Sinfall Combatant", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
