[63346] = { ["id"] = 63346, ["name"] = "Night Fae Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 63346, 63347 }, ["description"] = "Ardenweald is safer than it has been in quite some time, thanks to you. Your accomplishments have not gone unnoticed, even beyond the borders of Ardenweald. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["x"] = 0.34, ["y"] = 0.37, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["ends"] = { { ["x"] = 0.34, ["y"] = 0.37, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.34, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 176096, ["questTurnInID"] = 176096, ["questType"] = "standard", ["sourceQuests"] = { 62899 }, ["questLines"] = { { ["id"] = 1214, ["name"] = "Night Fae Combatant", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[63347] = { ["id"] = 63347, ["name"] = "Night Fae Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 63346, 63347 }, ["description"] = "Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["x"] = 0.34, ["y"] = 0.37, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["ends"] = { { ["x"] = 0.34, ["y"] = 0.37, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.34, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 176096, ["questTurnInID"] = 176096, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1214, ["name"] = "Night Fae Combatant", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[63418] = { ["id"] = 63418, ["name"] = "Exploited Explorers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 63418 }, ["description"] = "Chuck explains that something weird is happening in the jungle, and that his group has been captured by wild fungarians. He asks you to rescue his friends to help find out what's going on with the jungle.", ["objectivesText"] = "Rescue Chuck's friends", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[63419] = { ["id"] = 63419, ["name"] = "Spores Galore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 63419 }, ["description"] = "Chuck goes over again how the jungle seems to be alive and all wrong. He asks you to recover the spores that are on the fungarians and the beasts they've infected. Chuck is worried whatever is happening isn't natural.", ["objectivesText"] = "Collect 12 strange", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[63435] = { ["id"] = 63435, ["name"] = "Temple Throwdown", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 63435 }, ["description"] = "My parents are busy defending the Shrine of the... Eight... Coconuts? I wasn't paying attention. That's probably why they left me here. They told me I could train with the big white cat! I'm going to be a ninja! < Anthea kicks several times in your direction.> Ya! Kya! You better watch out! ... I'm bored, do you want to pet battle? I brought all of my favorite pets with me.", ["objectivesText"] = "Defeat Anthea in a pet battle. Progress: I'm gonna get you! < Anthea punches the air several times.> Biff! Pow!", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 184866 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 176655, ["x"] = 0.704, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 176655, ["x"] = 0.704, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[63447] = { ["id"] = 63447, ["name"] = "Fear No Evil", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 32 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 63447 }, ["description"] = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers! Take this prayer book with you into the field and cast the Light's healing touch on the injured.", ["objectivesText"] = "Revive 4 Injured Stormwind Soldiers.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 57256, 57257, 57258, 65733, 131874 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 951, ["x"] = 0.485, ["y"] = 0.381 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 951, ["x"] = 0.485, ["y"] = 0.381 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard", ["sourceQuests"] = { 29080 } },
[63455] = { ["id"] = 63455, ["name"] = "Dead On Their Feet", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63455 }, ["description"] = "As the Jailer twists the souls here to his will, there are still some that continue to resist him. I shall give you the ability to aid them in their resistance. Through Necrotic Cohesion we shall bind the runes, armor, and bones that reside here to create bodies for these souls. Bodies that will allow them to fight for us and their freedom! Bind the Zealous souls and build us an army!", ["objectivesText"] = "Use the Cohesion Crystal to create bodies for 10 Defiant Souls .", ["rewardItems"] = { 181501, 181502, 181507, 181645, 181647, 181649, 181653, 181659, 181660, 181661, 181662, 181663, 181671, 181672, 181673, 181674, 181675, 181676, 181677, 181678, 181679, 181680, 181681, 181682, 182610, 182753, 184305, 184772, 184773, 184774, 184775, 184776, 184876 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177076, ["x"] = 0.335, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 }, { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63479] = { ["id"] = 63479, ["name"] = "Summons from the Matriarch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 2037, ["mapID"] = 110, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63480, 65652 }, ["description"] = "Greetings, <name>. Let us not mince words--you are urgently needed in Silvermoon. We're experiencing a resurgence of Scourge in Quel'Thalas. With nothing to hold the Scourge in check, we'll soon be overrun. We must hold the line! Meet me in the Hall of Blood, and we will get you a full briefing.", ["objectivesText"] = "Meet Lady Liadrin in Silvermoon.", ["rewardGold"] = 25740, ["rewardItems"] = { 45585, 191565, 191566, 191604 }, ["starts"] = { { ["x"] = 0.254, ["y"] = 0.521, ["mapID"] = 1670, ["npcID"] = 176789 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.898, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 10565 } }, ["questGiverID"] = 176789, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110 },
[63480] = { ["id"] = 63480, ["name"] = "Briefing", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63479, 65652 }, ["description"] = "We haven't much time. The Scourge have attacked Tranquillien, and there's nothing to hold them back. We must take decisive action.", ["objectivesText"] = "Listen to the briefing. Progress: We will find a way.", ["rewardGold"] = 25740, ["rewardXP"] = 3440, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.898, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard", ["sourceQuests"] = { 63479, 65652 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110 },
[63481] = { ["id"] = 63481, ["name"] = "Tranquillien Besieged", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 2037, ["mapID"] = 110, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "Rommath has opened the way for us to quickly travel to Tranquillien. I warn you, it's already a bloody battlefield. Take the portal, and I will be along right after you. And <name>... keep an eye on Salandria. She may have excelled in her training thus far, but she has yet to be tested like this.", ["objectivesText"] = "Take the portal to Tranquillien.", ["rewardGold"] = 25740, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.898, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 95, 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard", ["sourceQuests"] = { 63480 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95 },
[63482] = { ["id"] = 63482, ["name"] = "Death to the Scourge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "I haven't seen Scourge mustering in numbers like this since... <Liadrin shakes her head, steeling herself.> Never mind. There's no use dwelling in the past. Our first priority is thinning their numbers enough that we can find out what--or who--is really behind this attack. Slay as many of the undead as you can.", ["objectivesText"] = "Slay Scourge in Tranquillien. Progress: Once we've thinned out the numbers of the Scourge, we can strike at Vorath in his lair.", ["rewardGold"] = 257400, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["sourceQuests"] = { 63481 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95 },
[63483] = { ["id"] = 63483, ["name"] = "Magus Installation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "This is no mindless strike... I have a strong suspicion that some powerful entity is manipulating the Scourge. Ever since the Helm of Domination was shattered, there has been a conceivable risk that someone else could exert their will and assume control over the undead--at least temporarily. Rommath and I can help defend Tranquillien, but we need to break those lines. Clear a spot for us. Let us see if we can draw out their leader.", ["objectivesText"] = "Help Aethas and Rommath set up defenses in Tranquillien. Progress: Rommath and I are ready to help set up the wards, once you clear out a spot for us.", ["rewardGold"] = 257400, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176829, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176829, ["x"] = 0.485, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["sourceQuests"] = { 63481 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95 },
[63484] = { ["id"] = 63484, ["name"] = "A Knight's Weapon", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "It's clear that this san'layn has decided to use the Scourge to empower himself somehow. We can keep taking him out, but he will just keep coming back. We need a weapon that can break him for good. I think I have a solution. Upstairs, you will find a newly forged ranseur . It has yet to be tempered with magic--we will need to unlock its full potential. It will be our instrument of the Light.", ["objectivesText"] = "Collect the Ranseur from upstairs in Tranquillien. Progress: Have you acquired the ranseur?", ["rewardGold"] = 25740, ["rewardItems"] = { 184895, 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["sourceQuests"] = { 63482, 63483 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95 },
[63485] = { ["id"] = 63485, ["name"] = "An Honest Heart", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "If we are to defeat Vorath, we need to amplify the power of the ranseur. But we will not cut corners or impose our will to do it. That lesson has been learned. However, the kyrian of Bastion are masters of ushering souls to their proper places. Perhaps they would lend a fragment of their power to our cause. Go to Bastion , and find a way to empower the ranseur.", ["objectivesText"] = "Travel to Agthia's Repose in Bastion .", ["rewardGold"] = 25740, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 176930, ["x"] = 0.45, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95, 1533 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["sourceQuests"] = { 63484 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63486] = { ["id"] = 63486, ["name"] = "An Unbreakable Will", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "We're clearly dealing with someone who is using terrible magic to suspend his own death. There's another force we know of that uses magic in this fashion. The Maldraxxi are intimately familiar with the trappings of death, and equally familiar with how to subvert it. Perhaps one of the Houses knows of a way to help us. Go there, and seek out power that can break this unnatural loop.", ["objectivesText"] = "Travel to the Theater of Pain in Maldraxxus .", ["rewardGold"] = 25740, ["rewardXP"] = 9515, ["rewardItems"] = { 191565, 191566, 191604, 204220 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 176914, ["x"] = 0.462, ["y"] = 0.454 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95, 1536 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["sourceQuests"] = { 63484 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[63487] = { ["id"] = 63487, ["name"] = "Return to the Ghostlands", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 1536, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63488, 63489 }, ["description"] = "Such power! Surely not even Vorath can withstand the might of this weapon now. We have what we came to the Shadowlands for. The ranseur is ready. Let's get back to Lady Liadrin in Tranquillien. I hope we're not too late to make a difference!", ["objectivesText"] = "Return to Lady Liadrin in Tranquillien.", ["rewardGold"] = 25740, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 176914, ["x"] = 0.462, ["y"] = 0.454 }, { ["mapID"] = 1533, ["npcID"] = 176930, ["x"] = 0.45, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 95, 1533, 1536 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63519, 63522 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95 },
[63488] = { ["id"] = 63488, ["name"] = "I Am the Blade of the Light", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63487, 63489 }, ["description"] = "It's time to put all that power and training into the field. Take the empowered ranseur, and cut a swath of destruction through the Scourge! We'll meet you at the doorstep of Deatholme.", ["objectivesText"] = "Use the empowered ranseur to slay Scourge in the Dead Scar.", ["rewardGold"] = 257400, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176826, ["x"] = 0.485, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176882, ["x"] = 0.3472, ["y"] = 0.7552 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["sourceQuests"] = { 63487 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95 },
[63489] = { ["id"] = 63489, ["name"] = "Justice Long Overdue", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["series"] = { 63487, 63488 }, ["description"] = "You made short work of the Scourge in the Dead Scar, but we've a bigger target to face. It's time to test the mettle of your weapon against Vorath . Let us finish this, together.", ["objectivesText"] = "Slay Vorath . Progress: We will protect our homeland.", ["rewardGold"] = 514800, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176882, ["x"] = 0.3472, ["y"] = 0.7552 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 176882, ["x"] = 0.3472, ["y"] = 0.7552 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.3472, ["y"] = 0.7552 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["sourceQuests"] = { 63488 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95 },
[63490] = { ["id"] = 63490, ["name"] = "Blood Knight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredClasses"] = { 2 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "The power of the ranseur has been spent, but we are victorious! With Vorath defeated, perhaps the Scourge will be more easily dealt with--thanks to you. Meet me back in Silvermoon. Your efforts and heroism today will not go unrecognized.", ["objectivesText"] = "Receive accolades from Lady Liadrin in Silvermoon City.", ["rewardGold"] = 25740, ["rewardXP"] = 11765, ["rewardItems"] = { 191565, 191566, 191604, 191957, 204379, 263465, 268489, 269701 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 176882, ["x"] = 0.3472, ["y"] = 0.7552 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 176796, ["x"] = 0.898, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.3472, ["y"] = 0.7552 }, ["mapCandidates"] = { ["npc"] = { 95, 110 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["sourceQuests"] = { 63489 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110 },
[63494] = { ["id"] = 63494, ["name"] = "The Anvil-Thane's Designs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1584, ["mapID"] = 84, ["description"] = "I see you eyein' our weapons here. Wouldnae ye know, I forged them myself! So far, I've got designs for a staff, a one-handed axe, and a shield... I could make ye some, if you'd like! O' course, that's what I'd normally say. Unfortunately I lost the designs in a bet down at the Grim Guzzler. If ye could get them back, as well as gather the materials, I'd be happy to forge ye some weapons!", ["rewardGold"] = 31200, ["rewardXP"] = 850, ["starts"] = { { ["npcID"] = 144154, ["x"] = 0.57, ["y"] = 0.318, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 176828, ["x"] = 0.516, ["y"] = 0.33, ["mapID"] = 84 } }, ["coords"] = { ["x"] = 0.57, ["y"] = 0.318, ["source"] = "quest_giver", ["mapID"] = 84 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1584 } }, ["questType"] = "standard", ["sourceQuests"] = { 51483 } },
[63498] = { ["id"] = 63498, ["name"] = "Brawl or Brew", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1584, ["storyline"] = { 63498 }, ["description"] = "Ach, Thurgaden sent ye did he? Ye'd think the Anvil-Thane would be made o' tougher stuff than the rest of this drunken lot, but I guess I was mistaken! If ye want tae win back his designs, yer gonna have tae win 'em fair and square. I've only got one question left fer ye. Brawl? Or Brew?", ["objectivesText"] = "Defeat Strongarm Jarden in one of her competitions. Progress: Not a single dwarf in 'ere has beaten me. What makes ye different?", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 38466, 184894, 184915, 184916, 184917, 184922, 190606, 191123 }, ["starts"] = { { ["x"] = 0.517, ["y"] = 0.331, ["mapID"] = 1186, ["npcID"] = 176828 } }, ["ends"] = { { ["x"] = 0.517, ["y"] = 0.331, ["mapID"] = 1186, ["npcID"] = 176828 } }, ["coords"] = { ["mapID"] = 1186, ["x"] = 0.517, ["y"] = 0.331 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questGiverID"] = 176828, ["questTurnInID"] = 176828, ["questType"] = "standard", ["sourceQuests"] = { 63494 } },
[63501] = { ["id"] = 63501, ["name"] = "It's Called Borrowing", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1584, ["mapID"] = 84, ["storyline"] = { 63501 }, ["series"] = { 63502, 65563, 65564 }, ["description"] = "Thurgaden's designs for his weaponry, but are hard to parse. Notes are scribbled in the margins in messy handwriting, listing modifications and notes Thurgaden left for himself. Two notes in particular stand out to you. One denotes that he lent his engraving tool to the core hound trainer Kasea Angerforge, and the other wonders how many elementals they employ at the Grim Guzzler brewing operation.>", ["objectivesText"] = "Find 5 Darkforged Ingot , a Boiling Flamecore , and the Flamepoint Engraver around Shadowforge City. Progress: <Thurgaden is mumbling and cursing under his breath about how he will defeat Jarden in their next competition.>", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 184894, 184915, 184916, 184917, 184922, 190606, 191123 }, ["ends"] = { { ["npcID"] = 144154, ["x"] = 0.57, ["y"] = 0.318, ["mapID"] = 84 } }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1584 } }, ["questType"] = "standard", ["sourceQuests"] = { 63498 }, ["startItems"] = { 184894 } },
[63502] = { ["id"] = 63502, ["name"] = "Weapons o' the Dark Iron", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1584, ["storyline"] = { 63502 }, ["series"] = { 63501, 65563, 65564 }, ["description"] = "One step left, friend. Lend me a hand in my craftin', then you'll have yer hands on the most powerful weapons forged in the deepest fires of Blackrock Mountain!", ["objectivesText"] = "Aid Anvil-Thane Thurgaden in crafting your new weapons. Progress: These weapons shall rival even my own!", ["rewardGold"] = 241020, ["rewardXP"] = 6815, ["rewardItems"] = { 184915, 184916, 184917, 184922, 190606, 191123 }, ["starts"] = { { ["x"] = 0.572, ["y"] = 0.319, ["mapID"] = 1186, ["npcID"] = 144154 } }, ["ends"] = { { ["x"] = 0.572, ["y"] = 0.319, ["mapID"] = 1186, ["npcID"] = 144154 } }, ["coords"] = { ["mapID"] = 1186, ["x"] = 0.572, ["y"] = 0.319 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questGiverID"] = 144154, ["questTurnInID"] = 144154, ["questType"] = "standard", ["sourceQuests"] = { 63501 } },
[63519] = { ["id"] = 63519, ["name"] = "Unfair Fight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "A cowardly pest that cheats his way out of the glory of death? Bah! I have something that'll cut him down where he stands. But such an enhancement requires one who is strong enough to wield it properly. Show me your mettle and fight! If you can prove yourself, I'll empower that ranseur of yours.", ["objectivesText"] = "Prove your strength to Fightlord San .", ["rewardGold"] = 257400, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 176915, ["x"] = 0.466, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 176915, ["x"] = 0.466, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["sourceQuests"] = { 63486 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[63522] = { ["id"] = 63522, ["name"] = "A Fair Race", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63479, 63480, 63481, 63482, 63483, 63484, 63485, 63486, 63487, 63488, 63489, 63490, 63519, 63522, 65652, 65653 }, ["description"] = "A soul that refuses to cross the veil is a problem we kyrian are familiar with. I can help you. But before I grant your weapon this power, I must know that you will not abuse it, and that your heart is true. Let us run a race. Along the course, ring the bells. If your heart is pure, they will aid your speed. You must have at least five bells recently rung in order to complete the race. Do not be distracted by shortcuts. And do not try to cheat to get ahead, it will not work. Are you ready?", ["objectivesText"] = "Run an honest race with Vandellor .", ["rewardGold"] = 257400, ["rewardItems"] = { 191565, 191566, 191604 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176932, ["x"] = 0.45, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 176932, ["x"] = 0.45, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63485 }, ["questLines"] = { { ["id"] = 1216, ["name"] = "Knights of Blood", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63543] = { ["id"] = 63543, ["name"] = "Necrolord Assault", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63543 }, ["description"] = "The Jailer's forces have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination! Your help is needed Maw Walker. Assist our forces on the battlefield!", ["objectivesText"] = "Complete 1 quests in Perdition Hold and the Face of Oblivion.", ["rewardItems"] = { 185720, 185992 }, ["starts"] = { { ["x"] = 0.338, ["y"] = 0.548, ["mapID"] = 1543, ["npcID"] = 177072 } }, ["ends"] = { { ["x"] = 0.338, ["y"] = 0.548, ["mapID"] = 1543, ["npcID"] = 177072 } }, ["coords"] = { ["mapID"] = 1543, ["x"] = 0.338, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questGiverID"] = 177072, ["questTurnInID"] = 177072, ["questType"] = "standard", ["sourceQuests"] = { 63902 }, ["db2Objectives"] = { { ["text"] = "Report to Draka at the gates of Perdition Hold", ["amount"] = 1, ["type"] = 0, ["objectID"] = 177674, ["orderIndex"] = 0 }, { ["text"] = "Help Maldraxxi forces assault Perdition Hold", ["amount"] = 1, ["type"] = 14, ["objectID"] = 92362, ["orderIndex"] = 1 }, { ["text"] = "Use Draka's Battlehorn to signal the advance", ["amount"] = 1, ["type"] = 0, ["objectID"] = 177290, ["orderIndex"] = 2 }, { ["text"] = "Advance to the Altar of Domination", ["amount"] = 1, ["type"] = 0, ["objectID"] = 177532, ["orderIndex"] = 3 } }, ["db2DetailThemeID"] = 29, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[63545] = { ["id"] = 63545, ["name"] = "Putting A Plan Together", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63545 }, ["description"] = "While Maldraxxus pushes the main gate, we can take the side gate with the help of our Centurions. The remains of many Corrupted Centurions taken by the Jailor litter this area. Their parts could be used to build new ones to help in the assault. See if you can locate the parts we need to build a new Centurion.", ["objectivesText"] = "Deliver 3 Centurion Parts and 15 Automaton Bolts to Mikanikos Progress: Have you found the parts I requested?", ["rewardItems"] = { 180935, 181377, 181572, 181573, 181581, 181599, 181609, 181610, 181703, 181843, 181866, 182127, 182385, 182470, 182667, 183132, 183480, 183506, 184294, 184362, 184363, 184513, 184766, 184767, 184768, 184839, 185685, 186573, 186603, 186604, 187508 }, ["rewardCurrencies"] = { { ["id"] = 1804, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3975, ["y"] = 0.5425 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 63772 } },
[63576] = { ["id"] = 63576, ["name"] = "The First Move", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 63576, 63578, 63638, 63639, 63856, 63857, 63904, 63949 }, ["description"] = "While the covenants labor to defend the Shadowlands, the Jailer has not sat idle within Torghast. It seems he intends to set the next phase of his scheme into motion. Polemarch Adrestes has brought us disturbing news from Elysian Hold. He will recount what he witnessed once you arrive. Make haste. I fear that time grows short.", ["objectivesText"] = "Speak with Polemarch Adrestes in Oribos . Progress: We will continue to fight.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 186017, 186094, 186599, 187439 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["sourceQuests"] = { 62569 }, ["questLines"] = { { ["id"] = 1219, ["name"] = "Battle of Ardenweald", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1219, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching