[63578] = { ["id"] = 63578, ["name"] = "The Battle of Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1565, ["storyline"] = { 63576, 63578, 63638, 63639, 63856, 63857, 63904, 63949 }, ["series"] = { 63638, 63639, 63856, 63857, 63904 }, ["description"] = "With the betrayal of Sire Denathrius, and the absence of the Primus of Maldraxxus, we must assume that the Winter Queen is the Jailer's next target. And we won't let anyone take her sigil! Ardenweald has endured much, but it is a realm of great and mysterious power. Things aren't always what they seem. We'll use this to our advantage, no matter who comes for the Queen!", ["objectivesText"] = "Protect the Winter Queen's sigil in the Battle of Ardenweald.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 179498, 179511, 179515, 179531, 179536, 179546, 179564, 179583, 182322, 182323 }, ["rewardChoices"] = { 179511, 179515, 179531, 179536, 179546, 179564, 182322, 182323 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["x"] = 0.409, ["y"] = 0.662, ["mapID"] = 1670, ["npcID"] = 177141 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 177148, ["x"] = 0.486, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 10565 } }, ["questGiverID"] = 177141, ["questType"] = "standard", ["sourceQuests"] = { 63857 }, ["questLines"] = { { ["id"] = 1219, ["name"] = "Battle of Ardenweald", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1219, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[63579] = { ["id"] = 63579, ["name"] = "A Paladin's Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "Bolvar Fordragon has seen visions of a vault hidden deep within Torghast where the Jailer keeps souls he deems valuable. Uther was struck down by a mourneblade. When such a weapon is wielded with rage, it can shatter a soul into fragments. If the Jailer holds a part of Uther's soul, it cannot be fully mended until the lost piece is restored. Take this attuned shard to Torghast, $p. It should guide you to the vault's location. Find the lost fragment of Uther's soul so that he can be made whole.", ["objectivesText"] = "Reclaim the Remnant of Justice from the Ossuary of the Banished in Torghast. Progress: Greetings Maw Walker. Your arrival is fortuitous.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 42997, 185679, 185680, 185853 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179356, ["x"] = 0.628, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1533, 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64437 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 30, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63580] = { ["id"] = 63580, ["name"] = "Wounded Memories", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "The arrival of Uther's wounded soul was the impetus for many events that led us to our current struggles. Devos's broken trust. Her involvement with Helya. The rise of the Forsworn. Bastion needs to change, but we struggle to find a solution. Perhaps this soul fragment will provide valuable insight.", ["objectivesText"] = "Help Uther forge a connection to the Remnant of Justice. Progress: I have never seen a soul torn as Uther's has been.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63579 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 31, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63581] = { ["id"] = 63581, ["name"] = "Step Into the Light", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "It is as I feared. This fragment of Uther's soul was darkened by the mourneblade that slew him. His memories are shattered and twisted. For Uther to move past his pain, to move past his grief, he must experience his past once again. But he does not have to do this alone. Using my soul mirror, we can aid Uther in walking through these memories. He can then come to terms with the emotions they contain. We must help him see past the distortions and understand the truths they hold.", ["objectivesText"] = "Use the Soul Mirror to aid Uther in reliving his past. Progress: We can learn from this.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63580 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 32, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63582] = { ["id"] = 63582, ["name"] = "He Was My Student", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "Uther's memories of this Prince Arthas haunt him deeply. He is the reason Uther's soul was fragmented, why Devos fell the way she did. The pain in these memories is palpable. We have to dig deeper. Uther must face the source of this darkness. Once again, you need to enter his past to protect his future.", ["objectivesText"] = "Aid Uther in reliving his second memory. Progress: Uther needs our support.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 62199, 62200, 62201, 107640, 109076, 131635, 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177123, ["x"] = 0.284, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63581 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 33, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63583] = { ["id"] = 63583, ["name"] = "I Intend to Live Forever", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "Please, <name>. I am not finished. There is one more memory that I must see. One more that must be faced. It... it will not be easy. I will need support from all of you. But it must be done.", ["objectivesText"] = "Aid Uther in reliving his final memory. Progress: <Adrestes is deep in thought.>", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 180733, ["x"] = 0.402, ["y"] = 0.202 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63582 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 34, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63584] = { ["id"] = 63584, ["name"] = "A Triumphant Return", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63590 }, ["description"] = "This temple represents a new dawn for Bastion, <name>. The Temple of Devotion will stand as a place of fellowship. We will work with the Forsworn, as well as aspirants and kyrian of all experience and backgrounds, to forge a future of which all can be proud. Let us return to Elysian Hold. I request that you join us for a momentous occasion--the ascension of a new Paragon and the creation of a new sigil.", ["objectivesText"] = "Meet Kalisthene at Elysian Hold. The Kyrian Courier can provide a flight.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 60726, 60727, 60730, 60734, 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questTurnInID"] = 177116, ["questType"] = "standard", ["sourceQuests"] = { 63590 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 35, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[63585] = { ["id"] = 63585, ["name"] = "Blind Loyalty", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63586, 63589 }, ["description"] = "The path forward for the kyrian is clear to me now. First we will speak with Nikolon. I urge you to stay and listen. Afterward, we must return to Elysian Hold. There I will request an audience with the Archon, and I need you all by my side as I do so.", ["objectivesText"] = "Join Polemarch Adrestes at Elysian Hold for an audience with the Archon. Progress: The kyrian must forge a new path.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63583 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 36, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707 },
[63586] = { ["id"] = 63586, ["name"] = "Compassion in Devotion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63585, 63589 }, ["description"] = "Our first order of business is to rededicate the Temple of Loyalty. Pelagos has volunteered to stay here and help prepare for the ceremony. I requested that Nikolon bring his companions to meet us at Steward's Rest, to aid us in convincing some of the Forsworn of our new path. Meet us there when you are able.", ["objectivesText"] = "Meet Adrestes at Steward's Rest.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63585 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 37, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63587] = { ["id"] = 63587, ["name"] = "Reclaimable Anima", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "Mikanikos has explained much about Forsworn centurions to me, <name>. I cannot say that I understood all of it, but it seems he has not yet found a reliable way to return them to their proper operating standards. Their anima can still be useful, though! Adrestes has focused on how to rededicate the temple, but not on his own safety. I worry the process will drain much of his anima. If you can reclaim cores from the Forsworn centurions, we can use them as anima stores for Adrestes.", ["objectivesText"] = "Collect 5 Tainted Centurion Cores from Forsworn centurions. Progress: I've been working with Mikanikos on methods to reuse anima from Forsworn centurions. I can handle this!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177123, ["x"] = 0.284, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177123, ["x"] = 0.284, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63586 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 38, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63588] = { ["id"] = 63588, ["name"] = "Rebuilding Faith", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["description"] = "The Forsworn are lost, <name>. They are like ghosts, haunting the Temple of Loyalty. Nowhere else to go. Leaderless, purposeless, abandoned. We must show them that there is a path forward. Let me accompany you into the temple. Allow me to talk to them, speak to their sensibilities. Perhaps we can convince them to give Adrestes's new path a chance.", ["objectivesText"] = "Convince 10 Forsworn to return to the Path. Progress: The Forsworn may have abandoned the Path, but we had good reason.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 137663, 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177300, ["x"] = 0.282667, ["y"] = 0.243333 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177300, ["x"] = 0.282667, ["y"] = 0.243333 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.282667, ["y"] = 0.243333 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questTurnInID"] = 177300, ["questType"] = "standard", ["sourceQuests"] = { 63586 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 39, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63589] = { ["id"] = 63589, ["name"] = "Directing Dedication", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63585, 63586 }, ["description"] = "The five temples of Bastion have stood strong since its very creation. The idea of rededicating one has never been broached before, and will no doubt require a significant amount of anima. Underneath this temple are stores of anima we rationed for the drought. Now that anima is returning, we can use these reserves for our purposes. You will need to use channelers and collectors throughout the grounds to redirect anima to the top. That should give me the power I need.", ["objectivesText"] = "Redirect anima from the Citadel of Loyalty to the temple. Progress: We endeavor to perform a monumental feat, one that has never been attempted before.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63586 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 40, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63590] = { ["id"] = 63590, ["name"] = "The Vesper Rings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1533, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63584 }, ["description"] = "Loyalty shall no longer be a demanded tenet of the Path, but rather a virtue that is earned. A choice. We must show devotion to those who struggle, whether they are recently arrived souls or peers who need our aid. It will take all the anima at hand to rededicate this temple. And in so doing, to ring in a new age for the kyrian. I fear the Mawsworn may attempt to thwart our plans. Protect me during this ritual, <name>. We must see this through.", ["objectivesText"] = "Protect Polemarch Adrestes as he rededicates the Temple of Loyalty. Progress: <Adrestes cannot be distracted as he uses every ounce of himself for the task at hand.>", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 177116, ["x"] = 0.283333, ["y"] = 0.242667 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.283333, ["y"] = 0.242667 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 63587, 63588, 63589 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 41, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[63591] = { ["id"] = 63591, ["name"] = "The Grand Reception", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 2017, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63592, 63593 }, ["description"] = "<name>, you have aided the kyrian in the most trying of times. Your devotion to our cause has helped usher in a new beginning for all of us. We would be honored if you would join us for a gathering prior to the ceremony. Many members of our covenant wish to express their appreciation for all you have done. This is a day of great joy. I am so pleased that you are here to witness it!", ["objectivesText"] = "Speak to Kalisthene to attend the gathering, then mingle with your soulbinds and the other kyrian.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 185680, 185853 }, ["starts"] = { { ["x"] = 0.64, ["y"] = 0.191, ["mapID"] = 1707, ["npcID"] = 168517 } }, ["ends"] = { { ["x"] = 0.64, ["y"] = 0.191, ["mapID"] = 1707, ["npcID"] = 168517 } }, ["coords"] = { ["mapID"] = 1707, ["x"] = 0.64, ["y"] = 0.191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 168517, ["questTurnInID"] = 168517, ["questType"] = "standard", ["sourceQuests"] = { 63584 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 42, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2482, ["db2PoiUiMapID"] = 2017 },
[63592] = { ["id"] = 63592, ["name"] = "The New Path", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1695, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63591, 63593 }, ["description"] = "Today, a new paragon is anointed. And for the first time since the dawn of our realm, a temple is rededicated to represent our devotion to one another. A new paragon, a new sigil, and a new path for all kyrian. This ceremony shall be glorious indeed!", ["objectivesText"] = "Speak to Kalisthene to take part in the ceremony at the Seat of the Archon.", ["rewardGold"] = 283700, ["rewardXP"] = 8165, ["rewardItems"] = { 181743, 185680, 185853 }, ["starts"] = { { ["x"] = 0.558, ["y"] = 0.299, ["mapID"] = 2017, ["npcID"] = 180189 } }, ["ends"] = { { ["x"] = 0.558, ["y"] = 0.299, ["mapID"] = 2017, ["npcID"] = 180189 } }, ["coords"] = { ["mapID"] = 2017, ["x"] = 0.558, ["y"] = 0.299 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questGiverID"] = 180189, ["questTurnInID"] = 180189, ["questType"] = "standard", ["sourceQuests"] = { 63591 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 43, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2285, ["db2PoiUiMapID"] = 1695 },
[63593] = { ["id"] = 63593, ["name"] = "New Sigil of the Kyrian", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593 }, ["series"] = { 63591, 63592 }, ["description"] = "With a future of kinship and devotion secured for Bastion, a new sigil is born to represent our path forward. Please report all that you have done to the Primus . When he is ready, we will deliver the sigil to him. Let us hope he can use it to thwart the Jailer's plan and save the Shadowlands.", ["objectivesText"] = "Report back to the Primus in Korthia .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 185680, 185853 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.46, ["y"] = 0.58, ["mapID"] = 2018, ["npcID"] = 179379 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177194, ["x"] = 0.63, ["y"] = 0.250667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.250667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 11012 } }, ["questGiverID"] = 179379, ["questType"] = "standard", ["sourceQuests"] = { 63592 }, ["questLines"] = { { ["id"] = 1218, ["name"] = "A New Path", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 44, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1218, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineI