[63612] = { ["id"] = 63612, ["name"] = "The Chains of Command", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "If we must hold a position so near to the Jailer's lands, we need to provide some assurances. Vyraz and Helya have retreated within the walls of Desmotaeron. They have grown lax in their expected safety, which provides us with an opportunity. We will take them by surprise. Strike swiftly and without mercy, and perhaps we can cut the heads off those snakes.", ["objectivesText"] = "Meet Draka near Desmotaeron.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 181648, 185742, 185772 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177194, ["x"] = 0.63, ["y"] = 0.250667 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177560, ["x"] = 0.628, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.250667 }, ["mapCandidates"] = { ["npc"] = { 1543, 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63727 }, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 45, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiU