[63614] = { ["id"] = 63614, ["name"] = "Weapon in Hand", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "A moment, <name>. I threw my axe Dra'gora at Helya during our first encounter in the Maw, and I haven't seen it since. If this is truly where she commands her forces, then perhaps it's held here. I crafted that weapon in Nagrand, and it reminds me of many good days spent beside my family there. I want to feel its weight in my hands once again.", ["objectivesText"] = "Find Thrall's axe, Dra'gora . Progress: I threw my axe in the heat of the moment...", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 181648, 185742, 185772 }, ["starts"] = { { ["x"] = 0.628, ["y"] = 0.66, ["mapID"] = 1543, ["npcID"] = 177589 } }, ["ends"] = { { ["x"] = 0.628, ["y"] = 0.66, ["mapID"] = 1543, ["npcID"] = 177589 } }, ["coords"] = { ["mapID"] = 1543, ["x"] = 0.628, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questGiverID"] = 177589, ["questTurnInID"] = 177589, ["questType"] = "standard", ["sourceQuests"] = { 63612 }, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 47, ["flags"] = 0 }, { ["id"] = 6016, ["name"] = "Lorewalking: Thrall", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 