[63615] = { ["id"] = 63615, ["name"] = "Clip Their Wings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "The skies are dark with Helya's kyrian followers. If we do not thin their numbers, Zerekriss and our aerial allies may have difficulties pushing forward. I've noticed that the Mawsworn often use magical chains. We could turn their equipment against them and tear them down from the sky.", ["objectivesText"] = "Use Mawsworn Chains to kill 6 Helsworn Soulbreakers . Progress: We need to clear out the skies before we can begin the real assault.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 39804, 39854, 39855, 39867, 181648, 185742, 185772 }, ["starts"] = { { ["x"] = 0.628, ["y"] = 0.66, ["mapID"] = 1543, ["npcID"] = 177586 } }, ["ends"] = { { ["x"] = 0.628, ["y"] = 0.66, ["mapID"] = 1543, ["npcID"] = 177586 } }, ["coords"] = { ["mapID"] = 1543, ["x"] = 0.628, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questGiverID"] = 177586, ["questTurnInID"] = 177586, ["questType"] = "standard", ["sourceQuests"] = { 63612 }, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 48, ["flags"] = 0 }, { ["id"] = 6016, ["name"] = "Lorewalking: Thrall", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["q