[63617] = { ["id"] = 63617, ["name"] = "Bending Bars", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "In all the chaos, the gates of the upper hold have been left open. If we slip through, they might not even notice us until it is too late. One of Helya's lieutenants stands between us and Helgarde Keep. End them.", ["objectivesText"] = "Slay Ironkeeper Salryx . Progress: We need to get through that gate.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 181648, 185742, 185772 }, ["starts"] = { { ["x"] = 0.686, ["y"] = 0.529, ["mapID"] = 1543, ["npcID"] = 177586 } }, ["ends"] = { { ["x"] = 0.686, ["y"] = 0.529, ["mapID"] = 1543, ["npcID"] = 177586 } }, ["coords"] = { ["mapID"] = 1543, ["x"] = 0.686, ["y"] = 0.529 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questGiverID"] = 177586, ["questTurnInID"] = 177586, ["questType"] = "standard", ["sourceQuests"] = { 63616 }, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 50, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63618] = { ["id"] = 63618, ["name"] = "What Maldraxxus Does Best", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "Every enemy we vanquish here is one our army does not have to contend with. We will make sure they will not soon forget the true purpose of Maldraxxus. Show them what happens to those we deem a threat towards the Shadowlands. Kill every Mawsworn in sight.", ["objectivesText"] = "Slay 10 Mawsworn in upper Desmotaeron. Progress: Each Mawsworn we defeat is one less that will bother our forces in Korthia .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181648, 185742, 185772 }, ["starts"] = { { ["x"] = 0.652, ["y"] = 0.484, ["mapID"] = 1543, ["npcID"] = 177586 } }, ["ends"] = { { ["x"] = 0.652, ["y"] = 0.484, ["mapID"] = 1543, ["npcID"] = 177586 } }, ["coords"] = { ["mapID"] = 1543, ["x"] = 0.652, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questGiverID"] = 177586, ["questTurnInID"] = 177586, ["questType"] = "standard", ["sourceQuests"] = { 63617 }, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 51, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222,