[63619] = { ["id"] = 63619, ["name"] = "Forsworn and Forgotten", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "Wait... I know you! The Maw Walker! My brothers and sisters have been twisted... tainted. Some took power willingly from Helya, but others resisted. Now all of us are forced to submit to her power. I escaped when the fighting started, but most of the remaining Forsworn are being subjected to horrific rituals. Please, I beg you to free them. Then we will return to Bastion and submit to the Archon's judgment.", ["objectivesText"] = "Free 5 Forsworn Prisoners .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181648, 185742, 185772 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177288, ["x"] = 0.655, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177288, ["x"] = 0.655, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questTurnInID"] = 177288, ["questType"] = "standard", ["sourceQuests"] = { 63617 }, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 52, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"