[63620] = { ["id"] = 63620, ["name"] = "A Traitor's Due", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1543, ["storyline"] = { 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622 }, ["description"] = "Vyraz has been a constant thorn in Maldraxxus's side since he betrayed us. As Baroness of the House of the Chosen, it is my duty to see this threat eliminated... and the murder of Margrave Krexus avenged. As the Primus said, we must remove the head from this snake. The time to strike is now!", ["objectivesText"] = "Kill Vyraz. Progress: Vyraz is a stain upon Maldraxxus as long as he still draws breath.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181648, 185742, 185772 }, ["starts"] = { { ["npcID"] = 177586 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178103, ["x"] = 0.618, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questGiverID"] = 177586, ["questType"] = "standard", ["sourceQuests"] = { 63618, 63619 }, ["questLines"] = { { ["id"] = 1224, ["name"] = "An Army of Bone and Steel", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 53, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1224, ["questLineOrder"] = 4 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63621] = { ["id"] = 63621, ["name"] = "Pulling His Chain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63621 }, ["description"] = "They call this one the Keeper of Chains . Do not underestimate his power. He has bound nearby souls in preparation for an attack against our position. I need you to eliminate this threat, Maw Walker, before it moves against our forces.", ["objectivesText"] = "Eliminate the Keeper of Chains . Progress: Have you eliminated this threat?", ["rewardItems"] = { 181368, 181571, 181572, 181573, 181576, 181580, 181581, 181589, 181599, 181601, 181603, 181604, 181609, 181610, 181614, 181704, 181745, 184294, 184362, 184363, 184513, 184767, 184768 }, ["rewardCurrencies"] = { { ["id"] = 1804, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177226, ["x"] = 0.396, ["y"] = 0.537 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177226, ["x"] = 0.396, ["y"] = 0.537 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.537 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "group", ["sourceQuests"] = { 63772 } },
