[63651] = { ["id"] = 63651, ["name"] = "Cryptograms", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1699, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "If the nathrezim have infiltrated Sinfall they will be communicating, and not just through hand gestures or spoken words. They like to use magical written messages concealed by a simple cantrip, invisible to the average observer. However, I have developed an incantation that should allow you to see these messages. Find these cryptograms and bring me their contents. I can translate them if they are beyond your understanding.", ["objectivesText"] = "Transcribe 10 Infernal Cryptograms . Progress: If the nathrezim have a flaw it is that they assume they are the only ones who get better over time.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185734, 185855, 185857, 185859, 185860, 185861, 185863, 185864, 185865, 185866, 185867, 185868, 185870, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185879, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185888, 185893, 185894, 185895, 185897, 185898, 185899, 185900, 185901, 185903, 185905, 18