[63654] = { ["id"] = 63654, ["name"] = "The Nathrezim", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63644, 63645, 63646, 63647, 63648, 63650, 63652, 63653, 63659 }, ["description"] = "The Medallion of Wrath is more than just a powerful artifact. In the hands of a nathrezim it could be used to shape this realm to their dark purpose. What is more, while they hold it we are denied the ability to forge a new sigil. They already nearly destroyed the Ember Ward with their reckless schemes. I will not have my medallion used for their ends. Come, let us get it back.", ["objectivesText"] = "Recover the Medallion of Wrath from the nathrezim.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 130282, 130309, 181549, 185734 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 178337, ["x"] = 0.252, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 178413, ["x"] = 0.23, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.252, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "