[63655] = { ["id"] = 63655, ["name"] = "Medallion of Wrath", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "Maw Walker. I will march with my stoneborn into the depths of the Maw and rend the head off every nathrezim I find there. However, Revendreth is still too strategic in this war to lose out of misplaced vanity. Therefore, as Harvester of Wrath, the second of that title, I offer you my medallion for safe keeping and utilization while I wage this war. Use it to empower the Harvesters so they can prevent Denathrius from simply returning and regaining control with a snap of his fingers.", ["objectivesText"] = "Bring the Medallion of Wrath to the dais in Sinfall. Progress: <The platform surges with power as it feels the proximity of the medallion.>", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187124 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 179978, ["x"] = 0.23, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 179978, ["x"] = 0.23, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.23, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 179978, ["questType"] = "standard", ["sourceQuests"] = { 63654 }, ["questLines"] = { { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 68, ["flags"] = 0 }, { ["id"] = 1252, ["name"] = "Medallion of Wrath", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699 },
[63656] = { ["id"] = 63656, ["name"] = "The Meaning of Wrath", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "I will gather my forces and dispense a portion to Korthia immediately. I will also see to it that they are provided the tools Baroness Vashj and Kael'thas were able to conjure so that we might further defend against nathrezim incursions. Other duties require my attention before I can descend on Korthia . I must secure Dominance Keep against further infiltrators. I suppose the Primus will want an update. You may tell him you were successful.", ["objectivesText"] = "Report to the Primus .", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 185734 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 179978, ["x"] = 0.23, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177194, ["x"] = 0.63, ["y"] = 0.250667 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.23, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 1525, 1961 }, ["zone"] = { 10413 } }, ["questT