[63660] = { ["id"] = 63660, ["name"] = "Opening the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 63660, 63661, 63662, 63663, 63665, 63994, 64007, 64555, 64556 }, ["series"] = { 63661, 63662 }, ["description"] = "The Jailer has gained another sigil, and his forces actively assault Oribos . Bolvar Fordragon and Draka of Maldraxxus suggest taking the fight to the Jailer. To do so, we need a way for their forces to safely come and go from the Maw. This was considered impossible before you arrived, but now I believe we have a chance. I must examine your anima to see if this is truly what the Purpose wills.", ["objectivesText"] = "Allow Tal-Inara to examine your anima. Progress: I do not do this lightly, Maw Walker.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 185754, 186170, 187436, 187437, 187438, 187439, 187504 }, ["starts"] = { { ["x"] = 0.392, ["y"] = 0.694, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.392, ["y"] = 0.694, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.392, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 63639 }, ["questLines"] = { { ["id"] = 1225, ["name"] = "Maw Walkers", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1225, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { [