[63661] = { ["id"] = 63661, ["name"] = "Link to the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1543, ["storyline"] = { 63660, 63661, 63662, 63663, 63665, 63994, 64007, 64555, 64556 }, ["series"] = { 63660, 63662 }, ["description"] = "The Fatescribe is certain that a second waystone has emerged in the Maw. It falls to you to locate it. I will create an anchor here in Oribos that links to your anima. Once you attune yourself to the waystone, this anchor will be bound to it. If you are successful, the covenants will be able to send their forces inside and safely leave the Maw again. Use what resources you have within the Maw to find this waystone. Good luck, mortal. May the Purpose guide us all.", ["objectivesText"] = "Ask Ve'nari about the location of a second waystone. Progress: You have that look about you, Maw Walker. The one that tells me you are about to ask for my help.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 185754, 186170, 187436, 187437, 187438, 187439, 187504 }, ["starts"] = { { ["x"] = 0.392, ["y"] = 0.694, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 63660 }, ["questLines"] = { { ["id"] = 1225, ["name"] = "Maw Walkers", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1225, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Sta