[63663] = { ["id"] = 63663, ["name"] = "Korthia, the City of Secrets", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1961, ["storyline"] = { 63660, 63661, 63662, 63663, 63665, 63994, 64007, 64555, 64556 }, ["description"] = "We are on the threshold of attaining our desires, Maw Walker. Your grand waystone cannot be far off. Of course, my needs are much more modest. A bit of useful information here, a priceless relic there... I will survey the area to see if there is anything useful--or hazardous--nearby. Then we can proceed.", ["objectivesText"] = "Have Ve'nari scan the area, then investigate whatever is found.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 185754, 186170, 187436, 187437, 187438, 187439, 187504 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177202, ["x"] = 0.584667, ["y"] = 0.146667 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177227, ["x"] = 0.638, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.584667, ["y"] = 0.146667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63662 }, ["questLines"] = { { ["id"] = 1225, ["name"] = "Maw Walkers", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1225, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[63664] = { ["id"] = 63664, ["name"] = "Get to the Point", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63664 }, ["description"] = "Our position near the bridge to the Altar of Domination is under heavy attack! We can not afford to lose the ballista we have set up there. Maw Walker, I need you to defend that position till our troops can push forward!", ["objectivesText"] = "Defend the forward position inside Perdition Hold. Progress: Is our position safe?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 180896, 181501, 181502, 181625, 181647, 181649, 181651, 181652, 181654, 181656, 181671, 181672, 181673, 181674, 182464, 184305, 184772, 184773, 184774, 184775 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177126, ["x"] = 0.332, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63665] = { ["id"] = 63665, ["name"] = "Opening to Oribos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1961, ["storyline"] = { 63660, 63661, 63662, 63663, 63665, 63994, 64007, 64555, 64556 }, ["description"] = "The prophecies told us that one day this dormant waystone would be needed by a Maw Walker. That it would prove crucial to the fate of the Shadowlands. It seems that day has come. Draw upon the anima within you to activate this waystone. It will then be usable by all those who aid your cause. If, as you say, Tal-Inara has created an anchor in Oribos , then that anchor will bring you back to us. Go, <name>. Inform your allies that the Maw awaits... and that Korthia needs their help.", ["objectivesText"] = "Activate the waystone and travel to Oribos .", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 185754, 186170, 187436, 187437, 187438, 187439, 187504 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177227, ["x"] = 0.638, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177227, ["x"] = 0.638, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questTurnInID"] = 177227, ["questType"] = "standard", ["sourceQuests"] = { 63994 }, ["questLines"] = { { ["id"] = 1225, ["name"] = "Maw Walkers", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1225, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1225, [