[63669] = { ["id"] = 63669, ["name"] = "Somebody Feed Kevin", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63669 }, ["description"] = "My family of slimes is always hungry for anima. Thankfully the bodies of the defeated here are a good source! The more the slimes consume the larger they grow. Then what remains of the fallen will become part of our wonderful, happy family. Take Kevin and let him consume fallen enemies till he is fully grown, then unleash him upon our foes!", ["objectivesText"] = "Consume 8 fallen enemies to grow Kevin to full size.", ["rewardGold"] = 341600, ["rewardXP"] = 8165, ["rewardItems"] = { 181503, 181645, 181647, 181649, 181651, 181660, 181661, 181662, 181663, 181664, 181665, 181666, 181675, 181676, 181677, 181678, 181679, 181680, 181681, 181686, 181689, 181734, 181864, 182470, 182667, 184305, 184772, 184773, 184774, 184775, 184776 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 163295, ["x"] = 0.328, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 }, { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63671] = { ["id"] = 63671, ["name"] = "Favor: The Nathrezim Documents", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 63671 }, ["description"] = "This item will be of great interest to the brokers. Per your previous deal with The Night Market, you should bring it to Ta'xera. You will be fairly compensated.", ["objectivesText"] = "Bring The Nathrezim Documents to Ta'xera at The Night Market in Revendreth . Provided item:", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["rewardItems"] = { 185484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10413 } }, ["questType"] = "standard", ["startItems"] = { 185484 } },
