[63703] = { ["id"] = 63703, ["name"] = "Vault of Secrets", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "You've helped us regain a semblance of order, Maw Walker, but the outlook is dire. The Jailer's forces have launched an all-out assault upon the ruins of our vault at the outer reaches of Korthia . Clearly the Banished One seeks something of value inside. The vault's defenses activate when the structure is threatened, so getting inside won't be easy. But we must recover whatever the Jailer is seeking before his Mawsworn do. I've enlisted the aid of a necrolord who can help open the vault.", ["objectivesText"] = "Meet with Tal-Galan outside of Scholar's Den.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 21413, 21414, 21415, 185716, 185719, 185921, 185965, 187218 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177927, ["x"] = 0.628, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177423, ["x"] = 0.576, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.248 }, ["mapCandidates"] = {