[63705] = { ["id"] = 63705, ["name"] = "The Knowledge Keepers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "Our vault was built to store countless secrets and artifacts. Even if we gain entrance, we can't be certain of what the Jailer is looking for. Certain attendants are given the title of record keeper . They track items stored in the vault, and are known for their utmost discretion. A number of keepers have been taken captive by the Mawsworn and are being tortured for information. Save the record keepers , <name>. They can help us determine what the Banished One seeks.", ["objectivesText"] = "Rescue 5 record keepers from Scholar's Den.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185716, 185719, 185921, 185965, 187218 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177423, ["x"] = 0.576, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177423, ["x"] = 0.576, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63703 }, ["questLines"] = { { ["id"] = 1222, ["name"] = "The Last Sigil", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 80, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1222, ["questLineOrder"] = 3 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1222, ["questLineOrder"] = 7 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1222, ["questLineOrder"] = 7 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1222, ["questLineOrder"] = 7 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1222, ["questLineOrder"] = 7 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1222, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[63706] = { ["id"] = 63706, ["name"] = "Let the Anima Flow", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "Tal-Galan briefed me on the situation and explained the vault's workings. As well as any scholarly type could, at least. First we need to ensure the vault is getting power. They use underground conduits to feed it anima. The attendant says that one of these conduits is tucked away in a cave in Scholar's Den. You get me there and I'll find a way to fix it. Just watch my back while I figure out how these Korthian devices work.", ["objectivesText"] = "Help Bonesmith Heirmir repair the Anima Conduit.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185716, 185719, 185921, 185965, 187218 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177449, ["x"] = 0.572, ["y"] = 0.3 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177449, ["x"] = 0.572, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests