[63709] = { ["id"] = 63709, ["name"] = "Secrets of the Vault", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "What fortune! You rescued the record keepers before the Mawsworn could steal their knowledge of the vault's relics. But their records are fragmented. Incomplete. I pray there's enough left to learn the truth. I will attempt to coalesce the knowledge that remains into a message. If the Purpose wills it, we will learn what the Jailer wants and to whom this item originally belonged. I must focus for a moment. Let me know when you are ready to begin.", ["objectivesText"] = "Examine the recovered recordings with Tal-Galan . Progress: Are you ready to begin?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 21413, 21414, 21415, 185716, 185719, 185921, 185965, 187218 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177423, ["x"] = 0.576, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177423, ["x"] = 0.576, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.296 }, ["mapCandidates"] = {