[63714] = { ["id"] = 63714, ["name"] = "To the Vault", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "Thanks to the Bonesmith's repairs of both conduits, anima should now be flowing to the vault. That gives us a chance to get inside--assuming we can reach it. Our Maldraxxi allies have wrangled transportation to get us to and from the vault. I suggest we make haste. If the Jailer's minions obtain the sigil of the Primus before we do, it won't just be Korthia that suffers. All the Shadowlands may be forfeit. Let's go, Maw Walker. Our forces will be awaiting us.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 177451, ["x"] = 0.35, ["y"] = 0.352, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 177459, ["x"] = 0.49, ["y"] = 0.642, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.35, ["y"] = 0.352, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63713 }, ["questLines"] = { { ["id"] = 1222, ["name"] = "The Last Sigil", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 87, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1222, ["questLineOrder"] = 3 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1222, ["questLineOrder"] = 7 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1222, ["questLineOrder"] = 7 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1222, ["questLineOrder"] = 7 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1222, ["questLineOrder"] = 7 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1222, ["questLineOrder"] = 7 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }