[63726] = { ["id"] = 63726, ["name"] = "Untangling the Sigil", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "The Primus 's sigil is bound together with the magic of memory. It reminds me of something you have encountered before. You made an ally of the Runecarver, that poor soul trapped in the bowels of Torghast. He took those memories you found and helped you forge them into weapons and armor. Perhaps he can separate the sigil from this tangle of memories. It's our best chance to secure the sigil. But the way will be perilous.", ["objectivesText"] = "Speak with Bolvar to discuss what to do with the sigil.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185716, 185719, 185921, 185965, 187218 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questTurnInID"] = 177228, ["q