[63771] = { ["id"] = 63771, ["name"] = "Fate's Reminder", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 63771 }, ["description"] = "Fatescribe Roh-Tahl awaits you within Oribos , should you ever wish to change the course of fate. You may speak with him at your leisure.", ["objectivesText"] = "Meet Fatescribe Roh-Tahl in Oribos if you wish to enter the Threads of Fate.", ["rewardGold"] = 25975, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["sourceQuests"] = { 62704 } },
[63772] = { ["id"] = 63772, ["name"] = "Waiting in the Wings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63772 }, ["description"] = "Kyrian forces have arrived to assist in the assault. They have secured our flank and will lay siege to the south gate of Perdition Hold. Report to Artemede and assist the Kyrians however you can!", ["objectivesText"] = "Assist Artemede and the Kyrian forces outside the southern gate of Perdition Hold.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 184513 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177226, ["x"] = 0.396, ["y"] = 0.537 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63773] = { ["id"] = 63773, ["name"] = "You and What Army", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63773 }, ["description"] = "The Jailer has dispatched a force of elite troops to strike our rear lines. Their attack threatens our whole assault! I need you and one other soldier to eliminate these enemies. A volunteer from each of the five houses of Maldraxxus has requested to assist you, <name>. Pick one and give them the honor of serving alongside you.", ["objectivesText"] = "Select a champion and Eliminate 3 Mawchained Rampagers and 5 Mawchained Demolishers .", ["rewardGold"] = 1123600, ["rewardXP"] = 19030, ["rewardItems"] = { 181501, 181503, 181507, 181625, 181626, 181645, 181647, 181649, 181651, 181652, 181653, 181654, 181655, 181660, 181661, 181662, 181663, 181664, 181665, 181666, 181667, 181668, 181669, 181670, 181671, 181673, 181676, 181679, 181680, 181681, 181682, 181686, 181864, 184305, 184772, 184773, 184774, 184775, 184776 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 }, { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63774] = { ["id"] = 63774, ["name"] = "An Embarrassment of Corpses", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63774 }, ["description"] = "Look around us, $p. Everywhere you turn there are corpses piling up like mountains. These disembodied souls are desperate to return to battle. We will use their fervor to turn the tide. Rally the disembodied souls around the battlefield and bring them to my stitchers at the corpse piles to build them new bodies!", ["objectivesText"] = "Deliver 4 Disembodied Souls to Front-Line Stitchers who will craft them new bodies. Progress: Find the disembodied souls and bring them to my stitchers!", ["rewardItems"] = { 181498, 181626, 181645, 181647, 181649, 181651, 181656, 181658, 181659, 181661, 181664, 181665, 181666, 181667, 181672, 181673, 181674, 181675, 181676, 181677, 181678, 181679, 181680, 181681, 181682, 181688, 181842, 182110, 182338, 182584, 183470, 184305, 184772, 184773, 184774, 184775, 184776, 187533 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177720, ["x"] = 0.335, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177720, ["x"] = 0.335, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63775] = { ["id"] = 63775, ["name"] = "Cryptograms and Keys", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63775 }, ["description"] = "The repositories of knowledge within Korthia have layers of security--for very good reasons. Each vault requires cryptographs in order to decode and disable the barriers. They are, for lack of a better term, the keys to every secret. Search outside the Vault for cryptographs stolen by the Mawsworn and return them to me. I will keep them, and the secrets they protect, safe.", ["objectivesText"] = "Retrieve 6 Stolen Cryptographs from outside the Vault and Seeker's Quorum. Progress: We cannot allow the Jailer to raid the Vaults of Korthia .", ["rewardItems"] = { 185746, 185855, 185857, 185859, 185860, 185861, 185863, 185864, 185865, 185866, 185867, 185868, 185870, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185879, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185888, 185893, 185894, 185895, 185897, 185898, 185899, 185900, 185901, 185903, 185905, 185944, 186155, 186156, 186201, 186205, 186206, 186663, 186664, 186665, 186666, 186667, 186668, 186669, 186670, 186734, 186735, 186736, 186737, 186738, 186739, 186740, 186741, 186742, 186743, 186744, 186745, 186746, 186747, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186758, 186759, 186760, 186761, 186770, 186976, 187506, 187507 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179082, ["x"] = 0.64, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179082, ["x"] = 0.64, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[63776] = { ["id"] = 63776, ["name"] = "Observational Records", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63776 }, ["description"] = "Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The Scholar's Den records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Be sure to check in the caverns below ground, as well! Bring those data to me, and I will reward you handsomely.", ["objectivesText"] = "Collect 5 Observational Records from the Scholar's Den. Progress: Have you retrieved the observational records from the Scholar's Den?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 184374, 185758, 185855, 185856, 185857, 185858, 185859, 185860, 185861, 185862, 185863, 185864, 185865, 185866, 185867, 185868, 185869, 185870, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185879, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185887, 185888, 185889, 185890, 185891, 185893, 185894, 185895, 185896, 185897, 185898, 185899, 185900, 185901, 185903, 185905, 185941, 185944, 186017, 186155, 186156, 186170, 186201, 186205, 186206, 186663, 186664, 186665, 186666, 186667, 186668, 186669, 186670, 186734, 186735, 186736, 186737, 186738, 186739, 186740, 186741, 186742, 186743, 186744, 186745, 186746, 186747, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186758, 186759, 186760, 186761, 186762, 186763, 186764, 186765, 186766, 186767, 186768, 186769, 186770, 186771, 186976, 187506, 187507 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178844, ["x"] = 0.648, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178844, ["x"] = 0.648, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[63777] = { ["id"] = 63777, ["name"] = "Sealed Secrets", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63777 }, ["description"] = "Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in the Scholar's Den. Don't worry: they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.", ["objectivesText"] = "Retrieve 5 Sealed Containers from the Scholar's Den. Progress: Do you have the sealed containers ?", ["rewardItems"] = { 184374, 185763, 185855, 185856, 185857, 185858, 185859, 185860, 185861, 185862, 185863, 185864, 185865, 185866, 185867, 185868, 185869, 185870, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185879, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185887, 185888, 185889, 185890, 185891, 185893, 185894, 185895, 185896, 185897, 185898, 185899, 185900, 185901, 185903, 185905, 185941, 185944, 186017, 186155, 186156, 186175, 186201, 186205, 186206, 186663, 186664, 186665, 186666, 186667, 186668, 186669, 186670, 186734, 186735, 186736, 186737, 186738, 186739, 186740, 186741, 186742, 186743, 186744, 186745, 186746, 186747, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186758, 186759, 186760, 186761, 186762, 186763, 186764, 186765, 186766, 186767, 186768, 186769, 186770, 186771, 186976, 187506, 187507 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178845, ["x"] = 0.645333, ["y"] = 0.254667 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178845, ["x"] = 0.645333, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.645333, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[63778] = { ["id"] = 63778, ["name"] = "We Move Forward", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "It breaks my heart to see another land so utterly obliterated. I can imagine how beautiful Korthia must have been, once. But we must not wallow in what we've lost. Like Ara'lon taught me: we don't have to stand still. We can choose to fight. You can help by taking anima back from those Mawsworn. We can put it to use, building up our own forces and defenses.", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178840, ["x"] = 0.61, ["y"] = 0.212, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178840, ["x"] = 0.61, ["y"] = 0.212, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.61, ["y"] = 0.212, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63779] = { ["id"] = 63779, ["name"] = "A Semblance of Normalcy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "$p, we have to help the attendants of Korthia . They have lost so much, so suddenly. Nearby, in the Sanctuary of Guidance, they would take offerings and leave them at shrines. Since the mawsworn invaded, they haven't been able to enter the Sanctuary or retrieve their precious offerings. If you could collect the offerings and retrieve them. It might allow the attendants some semblance of their normal lives.", ["rewardItems"] = { 184983, 184984, 184985, 184986, 185009, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 179134, ["x"] = 0.618, ["y"] = 0.24, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 179134, ["x"] = 0.618, ["y"] = 0.24, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.618, ["y"] = 0.24, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63780] = { ["id"] = 63780, ["name"] = "See How THEY Like It!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "Just thinking about how the Jailer's forces breached Ardenweald makes me so mad! And when I get mad, I get even. Or rather, I get your help with getting even! Slay those Mawsworn and bring back their emblems to show me how many you killed. I don't really care where you get them, as long as they come from those Maw jerks!", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1806, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178838, ["x"] = 0.612, ["y"] = 0.212, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178838, ["x"] = 0.612, ["y"] = 0.212, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.612, ["y"] = 0.212, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63781] = { ["id"] = 63781, ["name"] = "Mawsworn Battle Plans", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "Which is more damaging to the enemy, destroying a contingent of their forces or interrupting their communications? Better yet, what if that communication allows you to best place your forces to ambush their reinforcements? I see you understand. There will be a Mawsworn lieutenant, Voxiferus, traveling from the Maw into Korthia , by way of the northern road. Find them, kill them, and bring me the battle plans.", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1807, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178795, ["x"] = 0.618, ["y"] = 0.252, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178795, ["x"] = 0.618, ["y"] = 0.252, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.618, ["y"] = 0.252, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63782] = { ["id"] = 63782, ["name"] = "Mawsworn Rituals", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "The Mawsworn have a myriad of magic users among their forces. Their magic is unknown to us and that makes it deadly. We need to learn what they are capable of to properly prepare a defense. My own curiosity about their methods and rituals is secondary. Hunt down these vile casters and bring me their grimoires.", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1804, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178799, ["x"] = 0.616, ["y"] = 0.234, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178799, ["x"] = 0.616, ["y"] = 0.234, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.616, ["y"] = 0.234, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63783] = { ["id"] = 63783, ["name"] = "Anima Reclamation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "Our efforts here need a constant supply of troops, supplies, and anima. The last one is the hardest, for obvious reasons. But I've learned to be resourceful. Nearby there is a plentiful source of anima: the devourers that currently swarm the Sanctuary of Guidance. It's not as easy as beating it out of a soul, but it's just as effective, if you're strong enough. Are you?", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178793, ["x"] = 0.618, ["y"] = 0.256, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178793, ["x"] = 0.618, ["y"] = 0.256, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.618, ["y"] = 0.256, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63784] = { ["id"] = 63784, ["name"] = "Gold's No Object", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "$p! How's things? We 'eard there was all kinds of interestin' stuff out 'ere. So, 'em sneakin' hoppers? Hard to see, innit? They've got 'emselves a shiny pelt as me 'n' the lads could use to stay out of sight, as it were. You know, avoid the bosses n' such. I need ya to capture a bundle of 'em. Gold's no object, just bring me the little pests alive.", ["rewardItems"] = { 186201, 186205, 186206, 186680, 186688, 186690, 186691, 186692, 186693, 186705, 186706, 186707, 186708, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1807, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 179221, ["x"] = 0.616, ["y"] = 0.26, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 179221, ["x"] = 0.616, ["y"] = 0.26, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.616, ["y"] = 0.26, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63785] = { ["id"] = 63785, ["name"] = "Continued Efforts: Seeker's Quorum", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "The onslaught from Zovaal's forces continues to devastate these lands. We must send them a message. Show them we will not back down, . The might of Ardenweald stands with you.", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1806, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178841, ["x"] = 0.61, ["y"] = 0.216, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178841, ["x"] = 0.61, ["y"] = 0.216, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.61, ["y"] = 0.216, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63786] = { ["id"] = 63786, ["name"] = "Sweep the Windswept Aerie", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "The skies over Korthia are a dangerous place. Not only do the Mawsworn threaten our forces; the native creatures are also openly hostile. We must keep the skies safe for our own winged allies and beasts. The source of the native flyers is the Windswept Aerie. Go there and clear the aerie of aggressive creatures. Then, we shall have aerial supremacy.", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1807, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178794, ["x"] = 0.614, ["y"] = 0.25, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178794, ["x"] = 0.614, ["y"] = 0.25, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.614, ["y"] = 0.25, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63787] = { ["id"] = 63787, ["name"] = "Continued Efforts: Mauler's Outlook", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "My Eyes tell me that the Mauler's Outlook is near the newly formed road from the Maw into Korthia . It would provide a strategic and tactical advantage. Unfortunately, the area is overrun with shardhides. If we can secure the area, it will provide us with a clear path to the west, as well as a point of observation to monitor the Jailer's forces.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 179149, ["x"] = 0.608, ["y"] = 0.28, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 179149, ["x"] = 0.608, ["y"] = 0.28, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.608, ["y"] = 0.28, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63788] = { ["id"] = 63788, ["name"] = "Continued Efforts: Sanctuary of Guidance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "The attendant's home has been destroyed by the Jailer, but we can help them in this trying time. Nearby is the Sanctuary of Guidance. They speak of it with reverence and great sadness. It is a place they go to pray and seek truth. It's currently infested with devourers. Clear out the devourers, so they may once more seek solace in their rituals and prayers.", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178800, ["x"] = 0.616, ["y"] = 0.236, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178800, ["x"] = 0.616, ["y"] = 0.236, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.616, ["y"] = 0.236, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63789] = { ["id"] = 63789, ["name"] = "Continued Efforts: Scholar's Den", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "We cannot allow the mawsworn a foothold so close to our own encampment. The attendants say they keep this place hidden from eyes, but I will not rest easy while I can see them. Enter the Scholar's Den and cleanse the Jailer's forces from it.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178807, ["x"] = 0.604, ["y"] = 0.284, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178807, ["x"] = 0.604, ["y"] = 0.284, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.604, ["y"] = 0.284, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
