[63811] = { ["id"] = 63811, ["name"] = "A Hate-Hate Relationship", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1971, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["description"] = "When the first of my sisters went missing, we were concerned. Those sent to find her did not return. Nor did the next. What we have discovered is a dreadful betrayal by someone we once trusted. Come, we must tell Odyn what we have witnessed in the Maw. His wrath will be great.", ["objectivesText"] = "Accompany Danica to the Great Mead Hall and inform Odyn of Helya's actions. Progress: I do not fault the messenger, <name>.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["x"] = 0.58, ["y"] = 0.588, ["mapID"] = 1971, ["npcID"] = 177603 } }, ["ends"] = { { ["x"] = 0.58, ["y"] = 0.588, ["mapID"] = 1971, ["npcID"] = 177603 } }, ["coords"] = { ["mapID"] = 1971, ["x"] = 0.58, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 177603, ["questTurnInID"] = 177603, ["questType"] = "standard", ["sourceQuests"] = { 63764 }, ["questLines"] = { { ["id"] = 1234, ["name"] = "Focusing the Eye", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLine