[63827] = { ["id"] = 63827, ["name"] = "Encouraging Words", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63827 }, ["description"] = "Our forces have been battling relentlessly for hours. No doubt they grow tired and disheartened. Take this codex and recite the words within to our troops. Do not be fooled. Though the prose may seem meaningless, it holds immense power. Hearing these words will reinvigorate our exhausted Protectors with hope.", ["objectivesText"] = "Recite the words within the codex to 8 Exhausted Protectors .", ["rewardItems"] = { 180933, 181368, 181377, 181464, 181511, 181569, 181571, 181575, 181576, 181577, 181580, 181589, 181591, 181596, 181604, 181605, 181608, 181610, 181627, 181628, 181630, 181631, 181632, 181633, 181634, 181635, 181636, 181637, 181702, 181703, 181704, 181738, 181745, 181845, 182128, 182187, 182203, 182344, 182385, 182466, 182621, 182622, 182675, 183044, 183402, 183468, 183479, 183481, 183504, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 185775 }, ["rewardCurrencies"] = { { ["id"] = 1804, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63828] = { ["id"] = 63828, ["name"] = "Mine's Bigger", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63828 }, ["description"] = "The Jailer has deployed a large number of newly forged constructs to oppose our forces. Fortunately, I was completely prepared for this possibility. I have readied our largest Centurion to repel this threat. Please Maw Walker, ride with our Centurion and direct it in combat.", ["objectivesText"] = "Use the Centurion Demolisher to eliminate the Jailer's constructs. Progress: Have we driven back their constructs?", ["rewardItems"] = { 181368, 181377, 181455, 181509, 181569, 181570, 181571, 181574, 181576, 181577, 181580, 181589, 181591, 181596, 181601, 181604, 181605, 181608, 181610, 181614, 181709, 181745, 182139, 182304, 182608, 182769, 183184, 183488, 183514, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184840, 190641 }, ["rewardCurrencies"] = { { ["id"] = 1804, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3975, ["y"] = 0.5425 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63829] = { ["id"] = 63829, ["name"] = "No One Floats Down Here", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63829 }, ["description"] = "Now is our chance to free those we had assumed were lost! Many of our aspirants were seized by the Jailer to make troops for his army. Those that resisted him are locked in the cages that float above us, left there till their souls are broken. Shatter the Chains of Domination and free the Trapped Aspirants from the cages.", ["objectivesText"] = "8 Trapped Aspirants rescued.", ["rewardItems"] = { 181368, 181377, 181569, 181576, 181577, 181589, 181591, 181603, 181612, 181703, 184294, 184363, 184765, 184767, 184768, 184839 }, ["rewardCurrencies"] = { { ["id"] = 1804, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63831] = { ["id"] = 63831, ["name"] = "Fury Given Voice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1971, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["description"] = "I will answer this attack upon my val'kyr with relentless fury! You have a vital role to play in this, <class>. You will muster the courage that you have demonstrated this day to lure my Eye to battle. But first, a simpler task ... the creation of the horn that will summon my wrath. Master Smith Helgar will guide you.", ["objectivesText"] = "Assist Master Smith Helgar at the Forge of Odyn . Progress: Where is the horn that you have forged?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.838, ["mapID"] = 1971, ["npcID"] = 177726 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.838, ["mapID"] = 1971, ["npcID"] = 177726 } }, ["coords"] = { ["mapID"] = 1971, ["x"] = 0.583, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 177726, ["questTurnInID"] = 177726, ["questType"] = "standard", ["sourceQuests"] = { 63811 }, ["questLines"] = { { ["id"] = 1234, ["name"] = "Focusing the Eye", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLineOrder"]