[63845] = { ["id"] = 63845, ["name"] = "Wrath of Odyn", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1971, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["description"] = "The horn has been forged and the worthy have been selected. Now, <name>, we have only to bind my chosen val'kyr to the horn and infuse them with my power that they may strike with my fury. Come, bear witness.", ["objectivesText"] = "Bear witness to the empowerment of the chosen val'kyr and the binding of the Ilskahorn Progress: Yes? Did you have a question?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.838, ["mapID"] = 1971, ["npcID"] = 177726 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.838, ["mapID"] = 1971, ["npcID"] = 177726 } }, ["coords"] = { ["mapID"] = 1971, ["x"] = 0.583, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 177726, ["questTurnInID"] = 177726, ["questType"] = "standard", ["sourceQuests"] = { 63831, 63844 }, ["questLines"] = { { ["id"] = 1234, ["name"] = "Focusing the Eye", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1234