[63846] = { ["id"] = 63846, ["name"] = "The Ember Count", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63846 }, ["description"] = "Theotar's brilliance is undeniable, but far too many overlook the ingenuity of his dredger helpers, Gubbins and Tubbins. Look to that ridge beyond us. The Jailer's forges over there are spewing out Soulsteel Embers . We could accomplish many things with a mirror made from them... Gubbins has already crafted a special parasol, capable of shielding its wielder from any falling embers. Meet him by the forges and obtain some of those Soulsteel Embers !", ["objectivesText"] = "Slay 4 Enraged Forgeshard and Collect 4 Soulsteel Embers . Progress: Have you acquired the embers?", ["rewardItems"] = { 181176, 181178, 181184, 181189, 181191, 181192, 181196, 181198, 181200, 181202, 181224, 181545, 181546, 181547, 181548, 181550, 181712, 181769, 182469, 182743, 183467, 184147, 184150, 184777, 185839, 185942 }, ["rewardCurrencies"] = { { ["id"] = 1807, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178091, ["x"] = 0.43, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178091, ["x"] = 0.43, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63848] = { ["id"] = 63848, ["name"] = "A Show of Gratitude", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["series"] = { 63810, 63849, 63855, 63895 }, ["description"] = "Your presence here fulfils an ancient prophecy, Maw Walker. I am certain you and your allies will save us. Perhaps I judged your broker friend too harshly. She did escort you to Korthia , after all. Please extend our thanks to Ve'nari , and let her know we are happy to answer her questions. She... does seem to have quite a number of them.", ["objectivesText"] = "Speak with Ve'nari at Keeper's Respite in Korthia .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177927, ["x"] = 0.628, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178470, ["x"] = 0.654, ["y"] = 0.233333 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["questLines"] = { { ["id"] = 1234, ["name"] = "Focusing the Eye", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID