[63849] = { ["id"] = 63849, ["name"] = "Hearing Aid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1543, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["series"] = { 63810, 63848, 63855, 63895 }, ["description"] = "How fortuitous! You just happened to be transferred to a location in which I have a certain... interest. Place the aural sequencers I gave you and I will attempt to establish a functional signal. Such a perilous location will require the utmost discretion. You will want to use your ethereal cloak to avoid being seen.", ["objectivesText"] = "Place the Aural Sequencers in Desmotaeron to help Ve'nari eavesdrop on the inhabitants.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179078, ["x"] = 0.5685, ["y"] = 0.4675 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 179078, ["x"] = 0.5685, ["y"] = 0.4675 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.5685, ["y"] = 0.4675 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 63895 }, ["questLines"] = { { ["id"] = 1234, ["name"] = "Focusing the Eye", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["q