[63853] = { ["id"] = 63853, ["name"] = "Kill the Flame", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63853 }, ["description"] = "Can you see it? Just out of the corner of my eye, it's always there... glowing so brightly! How is one supposed to relax and enjoy a cup of tea while that reminder of fire and ash is around. Please Maw Walker do me a favor... remove it so that we may all enjoy a cup of my favorite blend!", ["objectivesText"] = "Kill Infernus the Infinite for Theotar . Progress: Have you killed that dreadful creature?", ["rewardItems"] = { 180943, 181178, 181184, 181191, 181193, 181196, 181545, 181546, 181547, 181548, 181550, 181640, 181708, 181842, 182338, 182584, 183468, 183470, 184147, 184150, 184587, 185829, 185942 }, ["rewardCurrencies"] = { { ["id"] = 1807, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178005, ["x"] = 0.429, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178005, ["x"] = 0.429, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.429, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
