[63892] = { ["id"] = 63892, ["name"] = "Diviner's Rune Chits", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63892 }, ["description"] = "<Inside the pouch is a single rune chit . It rotates and flips as if moved by an unseen hand. Runes vaguely reminiscent of the Vrykul language are delicately carved into the stone. On the back of the chit is an indication that it is part of a set.>", ["objectivesText"] = "Collect 20 rune chits , then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Goodness, is that a pouch of rune chits ? How many do you have?", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185962, 185963, 185968, 185971, 186101, 186157, 186685, 186716, 186984, 187047, 187052, 187055, 187103, 187104, 187117, 187119, 187150, 187154, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["rewardCurrencies"] = { { ["id"] = 1931, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.411, ["y"] = 0.421, ["mapID"] = 1961 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64506 }, ["startItems"] = { 187055 } },
[63895] = { ["id"] = 63895, ["name"] = "Grab Bag", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1543, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["series"] = { 63810, 63848, 63849, 63855 }, ["description"] = "Interesting. Aural sequencers and an ethereal cloak. You hang on to those, <name>. I have a suspicion they will prove useful. Ah, and something special for me as well. If I'm not mistaken--and I so rarely am--this is a projection mechanism. Very handy! And what's this? A transportation device of some kind. We should test it immediately. By \"we,\" of course I mean you.", ["objectivesText"] = "Test the transportation device from Ve'nari 's bag.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094, 186201 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 179078, ["x"] = 0.5685, ["y"] = 0.4675 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 63855 }, ["questLines"] = { { ["id"] = 1234, ["name"] = "Focusing the Eye", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 23, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro 