[63899] = { ["id"] = 63899, ["name"] = "Book of Binding: The Mad Witch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63899 }, ["description"] = "<You hear a muffled voice speaking from within this book, interspersed with crackling static. Though the utterances are mostly unintelligible, you can make out the repeated request to recover crimson pages . Flipping through the volume, you note that many of its pages are missing. If the pages were retrieved, the book could be returned to the Archivist and reassembled.>", ["objectivesText"] = "Collect 12 Crimson Pages , then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Is that book... speaking?", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185962, 185963, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187055, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["rewardCurrencies"] = { { ["id"] = 1931, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.272, ["y"] = 0.568, ["mapID"] = 1961, ["objectID"] = 368432 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64506 }, ["startItems"] = { 187206 } },
[63901] = { ["id"] = 63901, ["name"] = "Focusing the Eye", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1543, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["description"] = "The combination of grief and rage you have harvested is sufficient for your needs. Most likely. If you insist on seeing this ill-advised endeavor through, use the horn at the Terminus Platform, where the River of Souls flows upward to Torghast. The energies there are most potent indeed. The presence of your golden allies should draw the Jailer's Eye. I only hope this does not prove to be the end of you. I hate to see an investment wasted.", ["objectivesText"] = "Go to the Terminus Platform and use the Ilskahorn to summon the Wrath of Odyn.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179078, ["x"] = 0.5685, ["y"] = 0.4675 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178950, ["x"] = 0.37, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.5685, ["y"] = 0.4675 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["sourceQuests"] = { 63867, 63896 }, ["questLines"] = { { ["id"] = 1234, ["name"] = "Focusing the Eye", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 25, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 140, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 0 }, { ["id"] = 141, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 142, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 143, ["title"] = "Catching Up!", ["questLineID"] = 1246, ["questLineOrder"] = 3 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[63902] = { ["id"] = 63902, ["name"] = "Good News, Everyone!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1543, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["description"] = "Come, friend. Let us be rid of this foul place. No doubt your comrades will be eager to hear the news of the defeat of the Eye. I will bear you to them. Give the word when you are ready to depart, <name>.", ["objectivesText"] = "Fly with Danica to Korthia to give Bolvar the news. Progress: What has happened?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178950, ["x"] = 0.37, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 1543, 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63901 }, ["questLines"] = { { ["id"] = 1234, ["name"] = "Focusing the Eye", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 26, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", 