[63903] = { ["id"] = 63903, ["name"] = "Storming the Sanctum", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13561, ["mapID"] = 1961, ["storyline"] = { 63903 }, ["description"] = "The Jailer has seized the sigils of all four covenants. It is clear he means to escape the Maw and steal the Arbiter's sigil from Oribos. We cannot allow this to happen. Atop Torghast sits the Sanctum of Domination , the Jailer's seat of power. The time has come to enter this dark domain. No doubt Sylvanas Windrunner will command the forces that will attempt to thwart us. We must defeat her... and save Anduin Wrynn from her grasp. Gather your forces, <name>. The Ebon Blade will stand with you.", ["objectivesText"] = "Defeat Sylvanas Windrunner in the Sanctum of Domination . Progress: How fares the battle in the Sanctum?", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 187175 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "raid", ["sourceQuests"] = { 63727 } },
[63904] = { ["id"] = 63904, ["name"] = "The Heart of Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 63576, 63578, 63638, 63639, 63856, 63857, 63904, 63949 }, ["series"] = { 63578, 63638, 63639, 63856, 63857 }, ["description"] = "I hid my sigil in the Heart of the Forest, to keep it safe from the forces of the Maw. But the horn has called for aid. You and your allies go, see what has prompted the call.", ["objectivesText"] = "Investigate the Heart of the Forest. Progress: Is my sigil safe?", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 184379 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 177460, ["x"] = 0.47, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 177460, ["x"] = 0.47, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["sourceQuests"] = { 63638 }, ["questLines"] = { { ["id"] = 1219, ["name"] = "Battle of Ardenweald", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1219, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1219, ["questLineOrde