[63910] = { ["id"] = 63910, ["name"] = "The Netherstar", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63910 }, ["description"] = "<You recognize this relic from the Archivists' Codex. The power source is nearly empty. However, it could be restored with exposure to raw, unfiltered anima. Nearby fissures would do the trick.>", ["objectivesText"] = "Recharge the Netherstar , then bring it to Archivist Roh-Suir in the Reliquary of Remembrance.", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["rewardCurrencies"] = { { ["id"] = 1931, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.406, ["y"] = 0.413, ["mapID"] = 1961 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64511 }, ["startItems"] = { 187052 } },
[63911] = { ["id"] = 63911, ["name"] = "Singing Steel Ingot", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63911 }, ["description"] = "<The ingot wails, in a warbling vibrato.> Woe! These ruffians hammer upon me with nary a care, bending my body to suit their ill aims. Fie! Fie upon them. <The ingot emits a high-pitched battle cry.> Take the hammering to these mawsworn!", ["objectivesText"] = "Defeat mawsworn invaders, then bring the Singing Steel Ingot to Archivist Roh-Suir in the Reliquary of Remembrance.", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185962, 185963, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187055, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["rewardCurrencies"] = { { ["id"] = 1931, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.621, ["y"] = 0.568, ["mapID"] = 1961, ["objectID"] = 369254 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64506 }, ["startItems"] = { 187200 } },
[63912] = { ["id"] = 63912, ["name"] = "Celestial Shadowlands Chart", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63912 }, ["description"] = "<You recognize this relic from the Archivists' Codex. The mawsworn discarded it, believing it to be useless. And the chart is useless, without the accompanying data to plot the relative locations of Shadowlands afterlives. If the research were retrieved from deceased scholars, the chart could be returned to the Archivist, fully functional.>", ["objectivesText"] = "Collect 6 Afterlife Navigation Research scrolls, then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Is that the missing chart?", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185962, 185963, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187055, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["rewardCurrencies"] = { { ["id"] = 1931, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.455, ["y"] = 0.56, ["mapID"] = 1961, ["objectID"] = 369257 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64506 }, ["startItems"] = { 187201 } },
