[63934] = { ["id"] = 63934, ["name"] = "Assail Mail", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "Greetings, mortal! I am on a mission to deliver messages to our allies here in exciting Korthia . However, I was unable to complete my task. The messages I was programmed to transport were stolen by Mawsworn, and then incorrectly stored all over the ground. Would you collect the messages and return them to me? I will then see them delivered to their intended recipients. Thank you!", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1804, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178802, ["x"] = 0.614, ["y"] = 0.224, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178802, ["x"] = 0.614, ["y"] = 0.224, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.614, ["y"] = 0.224, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63935] = { ["id"] = 63935, ["name"] = "Precious Roots", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "Korthia . A sister forest, stricken. But in the throes of destruction, there is still hope. Gather the anima, and build anew.", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178842, ["x"] = 0.61, ["y"] = 0.214, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178842, ["x"] = 0.61, ["y"] = 0.214, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.61, ["y"] = 0.214, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63936] = { ["id"] = 63936, ["name"] = "Devoured Anima", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "Sika has idea! Devourers... devour. They eat anything! So they eat anima, too. If we take anima from devourers, then that anima is ours!", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1804, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178797, ["x"] = 0.616, ["y"] = 0.238, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178797, ["x"] = 0.616, ["y"] = 0.238, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.616, ["y"] = 0.238, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63937] = { ["id"] = 63937, ["name"] = "Nasty, Big, Pointy Teeth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "There's tons of interesting things to kill out here! Bears, birds, mawsworn, and gromits! Let's start with the gromits shall we? Go slaughter the fierce gromits in the Mauler's Outlook and bring me their FANGS! I can always use more teeth.", ["rewardItems"] = { 185011, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178805, ["x"] = 0.6, ["y"] = 0.274, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178805, ["x"] = 0.6, ["y"] = 0.274, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.6, ["y"] = 0.274, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63944] = { ["id"] = 63944, ["name"] = "Korthia Awaits", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63944, 64211, 64212, 64213, 64214, 64314 }, ["description"] = "Ready yourself, <name>. Our allies await your arrival in Korthia .", ["objectivesText"] = "Report to Tal-Galan at Keeper's Respite in Korthia .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.403, ["y"] = 0.679, ["mapID"] = 1670, ["npcID"] = 164079 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177927, ["x"] = 0.628, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 10565 } }, ["questGiverID"] = 164079, ["questType"] = "standard", ["nextQuests"] = { 64211, 64212 }, ["questLines"] = { { ["id"] = 1248, ["name"] = "What Lies Ahead", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1248, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[63945] = { ["id"] = 63945, ["name"] = "The Soul Blade", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63945 }, ["description"] = "The runeblade of a Necrolord can be a potent weapon in this realm. An abundance of souls are willing to contribute their anima to end their own suffering and bring defeat to the Jailer. Take one of my runeblades and charge it with the anima of the willing souls you find here. Once charged, use it lay waste to their forces here.", ["objectivesText"] = "Charge Heirmir's Runeblade with Willing Souls and use it to slay the Eye of Gorgoa . Progress: Has my blade tasted victory?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 181501, 181503, 181506, 181626, 181645, 181647, 181649, 181671, 181672, 181673, 181674, 181675, 181686, 184305, 184772, 184773, 184774, 184775, 184776, 186097 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178690, ["x"] = 0.222, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178887, ["x"] = 0.221333, ["y"] = 0.447333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63949] = { ["id"] = 63949, ["name"] = "Shaping Fate", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63576, 63578, 63638, 63639, 63856, 63857, 63904, 63949 }, ["description"] = "The Jailer's power and malevolence continue to grow. So must our resilience. Stand amongst your allies, <name>. Push back against the darkness that would consume us all. Together, we will yet prevail. May the Purpose guide your hand.", ["objectivesText"] = "Thwart the Jailer's efforts throughout Korthia and the Maw by completing Covenant Assaults, Daily Quests, looting treasures, slaying rare creatures, and defeating Tormentors of Torghast. Progress: One cannot run from history, but one's actions may shape the outcome.", ["rewardItems"] = { 186196, 187175, 187347 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1977, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177927, ["x"] = 0.628, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177927, ["x"] = 0.628, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63902 }, ["questLines"] = { { ["id"] = 1219, ["name"] = "Battle of Ardenweald", ["orderIndex"] = 7, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1219, ["questLineOrder"] = 0 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1219, ["questLineOrder"] = 4 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1219, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[63950] = { ["id"] = 63950, ["name"] = "Razorwing Talons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "These lands are not well known yet by my hunters, but we have discovered formidable beasts that reside here. Among these are the Razorwing: vicious predators with terrible talons... and the temper of a vorkai. Bring me some of their talons to help teach our newest hunters about the kinds of beasts they will face.", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1806, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178837, ["x"] = 0.614, ["y"] = 0.212, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178837, ["x"] = 0.614, ["y"] = 0.212, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.614, ["y"] = 0.212, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[63951] = { ["id"] = 63951, ["name"] = "A Shady Place", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63951 }, ["description"] = "Existence is not a simple thing, $p. It is layers upon layers of realities. The Jailer's traps are pulling our troops into one such rift, hidden from normal sight. I have obtained an Unbalanced Riftstone . It will give you the ability to enter the rift and destroy the traps keeping our troops trapped inside, before they are lost forever. After you've destroyed the Rift-Veiled Traps , exit the rift and pull the trapped soldiers back into our reality.", ["objectivesText"] = "Use the Unbalanced Riftstone to enter the rift and break Rift-Veiled Traps to free $1a Riftbound Vorkai . Progress: There is much we cannot see.", ["rewardItems"] = { 181503, 181507, 181625, 181638, 181645, 181649, 181651, 181652, 181653, 181654, 181655, 181664, 181665, 181666, 181667, 181670, 181681, 181682, 181688, 181689, 181690, 181691, 181693, 181694, 181697, 184305, 184772, 184773, 184774, 184775, 184776, 186190, 186191, 186300, 186310, 186713, 187012, 187347 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178890, ["x"] = 0.225, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178890, ["x"] = 0.225, ["y"] = 0.432 }, { ["mapID"] = 1543, ["npcID"] = 178891, ["x"] = 0.223333, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63952] = { ["id"] = 63952, ["name"] = "Heavy-Handed Tactics", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63952 }, ["description"] = "We need more constructs on the front lines, but we have no bodies, heads, or legs! Rathan's making the best constructs possible with what we DO have... a lot of hands. Don't ask questions! There are enemies in Calcis that we need dead. Take the hands and kill things!", ["objectivesText"] = "Slay 8 Mawsworn Soulbreakers , 4 Crystalline Guardians , Lady Nalis , and Glassmaker . Progress: Rathan is nothing if not resourceful.", ["rewardItems"] = { 181503, 181507, 181625, 181647, 181649, 181656, 181657, 181658, 181659, 181685, 181688, 181691, 184305, 184772, 184773, 184774, 184775, 184776 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178745, ["x"] = 0.228, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178891, ["x"] = 0.223333, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
