[63956] = { ["id"] = 63956, ["name"] = "Sealed Secrets", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63956 }, ["description"] = "Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in the Windswept Aerie. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.", ["objectivesText"] = "Retrieve 5 Sealed Containers from the Windswept Aerie in Korthia . Progress: Do you have the sealed containers ?", ["rewardItems"] = { 184374, 185855, 185856, 185857, 185858, 185859, 185860, 185861, 185862, 185863, 185864, 185865, 185866, 185867, 185868, 185869, 185870, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185879, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185887, 185888, 185889, 185890, 185891, 185893, 185894, 185895, 185896, 185897, 185898, 185899, 185900, 185901, 185903, 185905, 185941, 185944, 186017, 186155, 186156, 186173, 186175, 186201, 186205, 186206, 186663, 186664, 186665, 186666, 186667, 186668, 186669, 186670, 186734, 186735, 186736, 186737, 186738, 186739, 186740, 186741, 186742, 186743, 186744, 186745, 186746, 186747, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186758, 186759, 186760, 186761, 186762, 186763, 186764, 186765, 186766, 186767, 186768, 186769, 186770, 186771, 186976, 187506, 187507 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178845, ["x"] = 0.645333, ["y"] = 0.254667 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178845, ["x"] = 0.645333, ["y"] = 0.254667 } }, ["coord