[63963] = { ["id"] = 63963, ["name"] = "Broker's Bounty: Ripmaul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63963 }, ["description"] = "New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for a piece of heavily spiked hide from the beast known as Ripmaul. Faint-hearted collectors need not bother. Please bring this sample to Ta'nasi in Keeper's Respite.", ["objectivesText"] = "Retrieve a Heavy Spiked Hide from Ripmaul. Progress: Have something to trade?", ["rewardItems"] = { 184374, 185855, 185856, 185857, 185858, 185859, 185860, 185861, 185862, 185863, 185864, 185865, 185866, 185867, 185868, 185869, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185893, 185894, 185897, 185898, 185900, 185901, 185903, 185905, 185944, 186017, 186155, 186156, 186201, 186205, 186206, 186663, 186665, 186666, 186667, 186668, 186669, 186670, 186735, 186736, 186737, 186738, 186739, 186740, 186742, 186743, 186745, 186746, 186747, 186748, 186749, 186751, 186753, 186754, 186755, 186756, 186757, 186760, 186762, 186763, 186766, 186767, 186768, 186769, 186770, 186976, 187238, 187506, 187507 }, ["starts"] = { { ["x"] = 0.647, ["y"] = 0.256, ["mapID"] = 1961, ["objectID"] = 368772 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178844, ["x"] = 0.648, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "group", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
