[64012] = { ["id"] = 64012, ["name"] = "Supplies from Death's Advance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64012 }, ["description"] = "Your work toward stopping the Jailer's advances has not gone unnoticed. If it is power you seek to continue your efforts I believe I can be of some assistance.", ["objectivesText"] = "Speak with Duchess Mynx at Keeper's Respite in Korthia .", ["rewardItems"] = { 186650 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179321, ["x"] = 0.634, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2471, ["threshold"] = 10000 } } } },
[64014] = { ["id"] = 64014, ["name"] = "Mawsplaining", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1543, ["storyline"] = { 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63867, 63895, 63896, 63901, 63902, 64014 }, ["description"] = "There remains one task now before the glorious battle can begin. The horn must be anchored to the Maw so that its voice may pierce the barrier that surrounds that foul realm. How this can be done, I do not know. Seek out one that understands the mysteries of that place. Surely they can guide your hand. Danica and her sisters will listen for Ilskahorn's call. They will answer when you need them, <name>.", ["objectivesText"] = "Ask Ve'nari 's help to bind the Ilskahorn to the Maw. Progress: Have you bound the horn to the Maw?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185738, 185966, 185967, 186094 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.838, ["mapID"] = 1971, ["npcID"] = 177726 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questGiverID"] = 177726, ["questType"] = "standard", ["sourceQuests"] = { 63845 }, ["questLines"] = { { ["id"] = 1234, ["name"] = "Focusing the Eye", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 29, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 29, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1234, ["questLineOrder"] = 2 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1234, ["questLineOrder"] = 6 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1234, [