[64015] = { ["id"] = 64015, ["name"] = "Into the Meat Grinder", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64015 }, ["description"] = "All these mawsworn have got me excited for some slaughter! I've got a plan that probably won't end in you dying. Are you in?", ["objectivesText"] = "Lay a trap for the Mawsworn.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178805, ["x"] = 0.6, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178805, ["x"] = 0.6, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64016] = { ["id"] = 64016, ["name"] = "Oozing with Character", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64016 }, ["description"] = "Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! For Ooz, I'd like to know if they are able to consume organic material and increase in size.", ["objectivesText"] = "Help Ooz test their growth ability on Shardhide in the Mauler's Outlook. Progress: They're good oozes, <name>.", ["rewardItems"] = { 137663, 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 186548, 187000, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.277 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63727 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64017] = { ["id"] = 64017, ["name"] = "Oozing with Character", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64017 }, ["description"] = "Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! For Bloop, I'd like to know if their ooze is capable of propagation. Take them with you, and find those bears. Give them the command to inject the life form with their ooze and see what happens.", ["objectivesText"] = "Help Bloop test their propagation ability in the Mauler's Outlook. Progress: They're good oozes, <name>.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 186548, 187000, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.277 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63727 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64018] = { ["id"] = 64018, ["name"] = "The Weight of Stone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64018 }, ["description"] = "The campaign continues, $p. The Stone Legion is here to turn the tide of battle. First, we must deliver supplies to our allies. The broken land of Korthia means we are the only ones who can keep our troops supplied. Second, we must deal with the mawsworn and the devourers. I have a very simple strategy. We are going to drop anima onto the mawsworn. That will attract the devourers to attack. Either they kill the mawsworn, or the mawsworn kills them. Regardless, we win.", ["objectivesText"] = "Assist the Stone Legion in delivering supplies and anima.", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178794, ["x"] = 0.615, ["y"] = 0.251 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178794, ["x"] = 0.615, ["y"] = 0.251 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.251 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64040] = { ["id"] = 64040, ["name"] = "Once More, with Healing", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "The mawsworn continue to engage our forces at the Vault. There are heavy casualties on both sides. We must help! Take this and restore any wounded covenant allies you find. Mikanikos helped me create it. It runs on anima and should help patch up anyone. Even the Stoneborn or Maldraxxi.", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1804, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 179194, ["x"] = 0.616, ["y"] = 0.24, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 179194, ["x"] = 0.616, ["y"] = 0.24, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.616, ["y"] = 0.24, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[64042] = { ["id"] = 64042, ["name"] = "Rituals of Night", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1565, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63679, 63680, 63681, 63682, 63683, 64090, 64091, 64437 }, ["description"] = "Tyrande's time grows short, so we must act quickly. < Ysera frowns in concern.> We had hoped to gather more Night Warriors, but we will have to proceed with who we have and hope it is enough. < Ysera shakes her head, then looks more resolute.> Before we can begin, we must finish preparations for the ritual. Please bring these last few items with you and meet us at the grove.", ["objectivesText"] = "Assist with the preparations and ritual. Progress: Good, we may begin.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 22296, 185773 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 177434, ["x"] = 0.460667, ["y"] = 0.614 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 177434, ["x"] = 0.460667, ["y"] = 0.614 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.614 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["sourceQuests"] = { 63681 }, ["questLines"] = { { ["id"] = 1221, ["name"] = "The Power of Night", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 94, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1221, ["questLineOrder"] = 6 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[64043] = { ["id"] = 64043, ["name"] = "We Need a Healer - You!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "There are too many wounded on the battlefield! Not everyone can 'bash it and make better.' We need more healers. You: take my device and get our wounded back on their feet!", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1804, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 179216, ["x"] = 0.614, ["y"] = 0.24, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 179216, ["x"] = 0.614, ["y"] = 0.24, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.614, ["y"] = 0.24, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[64065] = { ["id"] = 64065, ["name"] = "Local Reagents", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "Korthia is an odd place. The wildlife here is different, likely due to years of exposure to the Vault and everything it contains. Are you ready to try some experiments? We'll need a good stock of reagents first. Near the Seeker's Quorum, you should be able to find shardhides, gromits, and razorwings. Watch out for their needles!", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 186548, 187000, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178806, ["x"] = 0.604, ["y"] = 0.278, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178806, ["x"] = 0.604, ["y"] = 0.278, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.604, ["y"] = 0.278, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63727 } },
[64070] = { ["id"] = 64070, ["name"] = "Staying Scrappy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "Our army always need more weapons, armor, and troops. Always. We're getting reinforcements, but I can't keep everyone properly armed at this rate. Especially without a full forge and assistants. We'll have to make do with the next best thing. I need you to go get me any kind of scrap metal from the Mawsworn you can find. I'll figure out how to turn it into usable weapons.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1805, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 179214, ["x"] = 0.632, ["y"] = 0.252, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 179214, ["x"] = 0.632, ["y"] = 0.252, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.632, ["y"] = 0.252, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[64080] = { ["id"] = 64080, ["name"] = "Down to Earth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64080 }, ["description"] = "I can hear the wings of the Mawsworn in the sky up above, taunting us. But a bird in the hand can be crushed. Take my spear and prove your aim. Pull a few down and smite them. Be sure to use the spear. Do not traipse among them so that they will chase you back down to the ground. That's not the point. I want to see you drag them out of the sky.", ["objectivesText"] = "Use Korayn's Javelin to spear 4 Mawsworn Harbingers.", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 186474, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178841, ["x"] = 0.609, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178841, ["x"] = 0.609, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.609, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64083] = { ["id"] = 64083, ["name"] = "Sinfall Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1670, ["storyline"] = { 64083, 64325 }, ["description"] = "Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, <name>. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["x"] = 0.54, ["y"] = 0.272, ["mapID"] = 1699, ["npcID"] = 175772 } }, ["ends"] = { { ["x"] = 0.54, ["y"] = 0.272, ["mapID"] = 1699, ["npcID"] = 175772 } }, ["coords"] = { ["mapID"] = 1699, ["x"] = 0.54, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questGiverID"] = 175772, ["questTurnInID"] = 175772, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1256, ["name"] = "Sinfall Combatant", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[64084] = { ["id"] = 64084, ["name"] = "Necrolord Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1670, ["storyline"] = { 64084, 64324 }, ["description"] = "You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["x"] = 0.465, ["y"] = 0.402, ["mapID"] = 1698, ["npcID"] = 175998 } }, ["ends"] = { { ["x"] = 0.465, ["y"] = 0.402, ["mapID"] = 1698, ["npcID"] = 175998 } }, ["coords"] = { ["mapID"] = 1698, ["x"] = 0.465, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questGiverID"] = 175998, ["questTurnInID"] = 175998, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1254, ["name"] = "Necrolord Combatant", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[64085] = { ["id"] = 64085, ["name"] = "Night Fae Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 64085, 64322 }, ["description"] = "Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["x"] = 0.34, ["y"] = 0.37, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["ends"] = { { ["x"] = 0.34, ["y"] = 0.37, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.34, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 176096, ["questTurnInID"] = 176096, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1255, ["name"] = "Night Fae Combatant", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[64086] = { ["id"] = 64086, ["name"] = "Kyrian Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 64086, 64323 }, ["description"] = "Look around you, <name>. Elysian Hold stands as a testament to the progress we have made thanks to you. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questTurnInID"] = 176100, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1253, ["name"] = "Kyrian Combatant", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[64089] = { ["id"] = 64089, ["name"] = "Teas and Tinctures", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "How delightful! What a lovely little spot of nature. Have you tried the local brews? Perhaps a nice herbal tea? No? Well, let's try it together! Search about this place and bring back any herbs that look... interesting. A good spot of tea, and then we shall get to work. I'll wait here.", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1807, ["amount"] = 175 }, { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 179218, ["x"] = 0.616, ["y"] = 0.258, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 179218, ["x"] = 0.616, ["y"] = 0.258, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.616, ["y"] = 0.258, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[64090] = { ["id"] = 64090, ["name"] = "The Big Squeeze", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63679, 63680, 63681, 63682, 63683, 64042, 64091, 64437 }, ["description"] = "So our missin' blue got 'imself dragged off to the big squeeze. Fortunately I am wise to the prise. We'll soft foot it in like we work there, find your moose, avoid eye contact with the fangs, and chisel out of 'ere like we're masons. Follow?", ["objectivesText"] = "Head to where Cudgelface thinks Huln was taken, and blend in. Progress: Well, this is exciting!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185773 }, ["starts"] = { { ["x"] = 0.38, ["y"] = 0.237, ["mapID"] = 1525, ["npcID"] = 177968 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 177967, ["x"] = 0.356, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questGiverID"] = 177968, ["questType"] = "standard", ["sourceQuests"] = { 64091 }, ["questLines"] = { { ["id"] = 1221, ["name"] = "The Power of Night", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 95, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1221, ["questLineOrder"] = 6 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[64091] = { ["id"] = 64091, ["name"] = "Mal'appropriated", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["series"] = { 63679, 63680, 63681, 63682, 63683, 64042, 64090, 64437 }, ["description"] = "<The dreadlord catches your eye, wishing to speak. You glance at your companions. Moonberry urges you forward with a mischievous grin. You step as close as you dare.> Free me from this prison, mortal, and you will have my favor. I am aligned with powers greater than these pathetic puppets or their masters. They have no concept of the true forces at work. All I need are the sigils of binding which hold me. The rest I can... take care of. Free me, and you will be granted untold power.", ["objectivesText"] = "Collect the Sigils of Binding Progress: Hmmm.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185773 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 179327, ["x"] = 0.379, ["y"] = 0.235 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 179327, ["x"] = 0.379, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.379, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questTurnInID"] = 179327, ["questType"] = "standard", ["sourceQuests"] = { 64092 }, ["questLines"] = { { ["id"] = 1221, ["name"] = "The Power of Night", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 96, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1221, ["questLineOrder"] = 6 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[64092] = { ["id"] = 64092, ["name"] = "Hunting Huln", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1525, ["storyline"] = { 63576, 63578, 63579, 63580, 63581, 63582, 63583, 63584, 63585, 63586, 63587, 63588, 63589, 63590, 63591, 63592, 63593, 63612, 63613, 63614, 63615, 63616, 63617, 63618, 63619, 63620, 63622, 63623, 63624, 63638, 63639, 63644, 63645, 63646, 63647, 63648, 63649, 63650, 63651, 63652, 63653, 63654, 63655, 63656, 63659, 63660, 63661, 63662, 63663, 63665, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 63679, 63680, 63681, 63682, 63683, 63703, 63704, 63705, 63706, 63709, 63710, 63711, 63712, 63713, 63714, 63717, 63722, 63725, 63726, 63727, 63728, 63754, 63764, 63810, 63811, 63831, 63844, 63845, 63848, 63849, 63855, 63856, 63857, 63867, 63895, 63896, 63901, 63902, 63904, 63990, 63994, 64007, 64014, 64042, 64090, 64091, 64092 }, ["description"] = "Huln is somewhere in the area, but the Stonewright isn't letting anyone in to her territory because of the recent, ah, troubles with Dreadlords. The guards won't let anyone in, and they're kicking out anyone who doesn't look like they belong. Luckily for Huln, Cudgelface and I came up with a foolproof plan! We just need to look like we belong and then we can ask around and find Huln. Easy!", ["objectivesText"] = "Don a disguise then search Dominance Keep for Huln Highmountain while avoiding the guards.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185773 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 177962, ["x"] = 0.297, ["y"] = 0.193 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 178254, ["x"] = 0.38, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.297, ["y"] = 0.193 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["sourceQuests"] = { 63679 }, ["questLines"] = { { ["id"] = 1221, ["name"] = "The Power of Night", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1247, ["name"] = "Patch Campaign", ["orderIndex"] = 97, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1221, ["questLineOrder"] = 6 }, { ["id"] = 144, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 145, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 146, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 }, { ["id"] = 147, ["title"] = "Catching Up!", ["questLineID"] = 1247, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[64101] = { ["id"] = 64101, ["name"] = "The Proper Procedures", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["description"] = "I came here to observe the actions of those from Revendreth. However I have been met with news that concerns me. $p, the attendants tell me that they stored anima in canisters and that anima is being looted, by our own people. That's not how this should be done. Can I entrust you to retrieve the anima, so I might see it returned to its proper place?", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187328, 187334, 187336, 187466 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["npcID"] = 178790, ["x"] = 0.618, ["y"] = 0.254, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 178790, ["x"] = 0.618, ["y"] = 0.254, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.618, ["y"] = 0.254, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 } },
[64103] = { ["id"] = 64103, ["name"] = "Old Tricks Work Best", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64103 }, ["description"] = "$p. Here we are again, fighting alongside each other to protect the Shadowlands. We're waging a losing war, but we might be able to turn the tide. I need you to seek out some very specific commanders of the Mawsworn forces. In every army, there's good commanders and bad ones. By taking out the good ones, only the bad ones advance, weakening the force as a whole. Our Eyes have brought us the names. Now I just need you to kill them.", ["objectivesText"] = "Kill Moros , Oizys , and Apate , commanders of the Mawsworn.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178808, ["x"] = 0.606, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178808, ["x"] = 0.606, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64104] = { ["id"] = 64104, ["name"] = "Think of the Critters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64104 }, ["description"] = "The wildlife of Korthia have been through so much. Some of them can't seem to find enough to eat. I've saved some extra food that we can share with them. But I'm worried that they might be too shy to trust us, and I don't blame them! Here. Take these treats and see if you can get close enough to them to feed them properly. Even small creatures are so important.", ["objectivesText"] = "Approach and feed Hungry Gromits in Korthia .", ["rewardItems"] = { 71076, 182180, 183395, 184396, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 186561, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178839, ["x"] = 0.614, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178839, ["x"] = 0.614, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64106] = { ["id"] = 64106, ["name"] = "A Unified Effort", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64106 }, ["description"] = "You have made strong allies within your covenant as well as the others within the Shadowlands. This bond is why they have decided to loan aid to our cause. They are ready to fight alongside us as we begin our advance into the Maw. Each covenant will strike at the Jailer from a different area. Help them scour this treacherous land for any who serve Zovaal so that we may put an end to his growing influence.", ["objectivesText"] = "Aid the covenants in assaulting the Jailer's forces in the Maw.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 186300, 186310, 187012, 187347 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63902 } },
[64129] = { ["id"] = 64129, ["name"] = "Charge of the Wild Hunt", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64129 }, ["description"] = "Ever since I joined the Wild Hunt I've learned so much about how to fight and how to defend the realms. I admit I'm still learning. But I am so glad to be learning alongside you, and my runestag friend, Aldermeigh . Aldermeigh is being trained to charge into battle with the bravery of a vorkai, but he needs practice. Will you take him out for a ride, and mow down all the Mawsworn you can?", ["objectivesText"] = "Mount Aldermeigh and slay Mawsworn in Korthia .", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178840, ["x"] = 0.61, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178840, ["x"] = 0.61, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64159] = { ["id"] = 64159, ["name"] = "Repatriate Rare Supplies", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 64159 }, ["description"] = "The rebels have stolen supplies from surrounding camps. You have proven yourself adept at correcting such situations. I trust you can aid us in resolving this situation.", ["objectivesText"] = "Recover supplies from the makeshift camps across the river.", ["rewardGold"] = 312800, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[64162] = { ["id"] = 64162, ["name"] = "Ritual Rival", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 64162 }, ["description"] = "Yet another rival Kahn has risen out of the rebel tribes. I'd take care of then myself, but I'm busy overseeing things here. I trust you can teach them the error of their ways?", ["objectivesText"] = "Find and defeat the Rebel Kahn in the makeshift camps across the river.", ["rewardGold"] = 312800, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[64163] = { ["id"] = 64163, ["name"] = "Revenge Against Renegades", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 64163 }, ["description"] = "Rebel clans have laid claims to some of our camps across the river. Such rebellious rabble need dealing with. I trust that you are capable of teaching these rebels a lesson on my behalf? The camps are an untidy mess as well, so just ignore the chaos for now. We can resolve that later once order is restored.", ["objectivesText"] = "Find and defeat Rebel Centaur Warriors in the makeshift camps across the river.", ["rewardGold"] = 312800, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[64166] = { ["id"] = 64166, ["name"] = "Random Memory Access", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64166 }, ["description"] = "When the Jailer snared Korthia and dragged it toward the Maw, he destroyed so much in this place. Not only mountains and buildings, but the people, too. Those people had lives, hopes, memories. I have to think that they can't all be gone, and we might be able to save something of them that lingers. Here, take some of my power. See if you can collect those memories. Bring them to me, and I'll keep them safe. No one should be forgotten.", ["objectivesText"] = "Collect Korthian Memories using the Ephemeral Wings .", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 186672, 187184, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179134, ["x"] = 0.618, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179134, ["x"] = 0.618, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64167] = { ["id"] = 64167, ["name"] = "Pets Detective", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 7578, ["storyline"] = { 64167 }, ["description"] = "I'm so glad you're here, <name>! I've been expecting a delivery of pet supplies and some new pets. But my distribution manager, Zantini has not reported in. I suspect foul play. There's been some shady people eyeballing my store for a while now. But I haven't been able to leave the store and track them down. You can. Take my pet cat, Fiona, and find these well hidden spies.", ["objectivesText"] = "Investigate the city of Dalaran with Breanni 's special spy catching cat, Fiona. Progress: What have you learned, <name>?", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["rewardItems"] = { 186553, 186695, 186772, 187128 }, ["starts"] = { { ["x"] = 0.585, ["y"] = 0.392, ["mapID"] = 627, ["npcID"] = 96479 } }, ["ends"] = { { ["x"] = 0.585, ["y"] = 0.392, ["mapID"] = 627, ["npcID"] = 96479 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.585, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 96479, ["questTurnInID"] = 96479, ["questType"] = "standard" },
