[64194] = { ["id"] = 64194, ["name"] = "War Prototype", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64194 }, ["description"] = "As Forgelite Prime, I always work to make something better! But largest centurions, they are much too large to bring to Korthia . This, I fix. Here is Atleos , field colossus prototype. Vanguard of the Kyrian! It needs testing. More testing. Must be perfect against a powerful opponent. Go, take Atleos and defeat a great Maw beast! Press all the buttons!", ["objectivesText"] = "Use the Atleos prototype in the Windswept Aerie to defeat Kraxis . Progress: You have work still, yes?", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179216, ["x"] = 0.615, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179216, ["x"] = 0.615, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64196] = { ["id"] = 64196, ["name"] = "Pet Up", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7578, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "It sounds like some group of pet poachers are up to no good in the Eye of Azshara . My supply manager's flight path takes him right over that area! Zantini and his pets, Strigfellow and Speedy IV , were bringing back a rare murloc pet, along with some other pets and supplies. <name>, please find Zantini and his pets. Help them out. Then we can try to recover the pets and the supplies.", ["objectivesText"] = "Find and help Zantini and his pets along the coast of the Eye of Azshara .", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["rewardItems"] = { 79869, 87399, 89125, 91086, 116415, 143753, 151191, 163036, 165835, 169665, 174360, 184373, 184374, 186553, 186695, 186772, 187128, 198725, 198726, 263871 }, ["starts"] = { { ["x"] = 0.585, ["y"] = 0.392, ["mapID"] = 627, ["npcID"] = 96479 } }, ["ends"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7502 } }, ["questGiverID"] = 96479, ["questType"] = "standard", ["sourceQuests"] = { 64167 }, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 790 },
[64202] = { ["id"] = 64202, ["name"] = "Gotta Hand It To Ya", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 64202 }, ["description"] = "Your power Maw Walker... it rivals even mine before Zovaal separated my body. This is but a small part of my whole, but more than enough... Allow me to aid you in your efforts against Zovaal. In doing so my vengeance will be fulfilled.", ["objectivesText"] = "Accept Nilganihmaht's help.", ["rewardItems"] = { 184513, 185972, 185973, 186653, 186654, 186713, 226506 }, ["starts"] = { { ["x"] = 0.3386, ["y"] = 0.5473, ["mapID"] = 1543, ["npcID"] = 179572 } }, ["ends"] = { { ["x"] = 0.3386, ["y"] = 0.5473, ["mapID"] = 1543, ["npcID"] = 179572 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questTurnInID"] = 179572, ["questType"] = "standard", ["sourceQuests"] = { 64197, 64198, 64199, 64200, 64201 } },
[64203] = { ["id"] = 64203, ["name"] = "The Coast is Clear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7578, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "I was on the last leg of a supply run when we were shot down! They took the pets, but the supplies are scattered over this stretch of beach. I don't know what they're planning, but I know we gotta get our supplies. You an' me, we ain't subtle.... But Speedy IV ... He won't cause all them pirates to go into hiding. He can get the supplies while Stringfellowe surveils the area from the air. Speedy's fond of you, so chat him up and let's try to recover the smoldering supplies before they all burn up.", ["objectivesText"] = "Gather pet supplies along the shores of Eye of Azshara with Speedy IV . Progress: Supplies are always in need.", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 183395, 184396, 186553, 186695, 186730, 186772, 187005, 187128 }, ["starts"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7578 } }, ["questType"] = "standard", ["sourceQuests"] = { 64196 }, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 790 },
[64210] = { ["id"] = 64210, ["name"] = "The Box of Many Things", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13546, ["mapID"] = 1912, ["storyline"] = { 64210, 64216, 64557 }, ["description"] = "Ah, Maw Walker, of course. Soon I shall be undone, claimed by this place forever. But you continue to walk its halls, unbroken! It was my great aspiration to prevail with the help of this box. Sadly, I overestimated my own capabilities. I trust I am not overestimating yours. Take the box. Prove yourself worthy of it.", ["objectivesText"] = "Bring the Box of Many Things to the Runecarver . Progress: Ah, you return.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 186732 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.682, ["mapID"] = 1967, ["npcID"] = 179598 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.682, ["mapID"] = 1967, ["npcID"] = 179598 } }, ["coords"] = { ["mapID"] = 1967, ["x"] = 0.429, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13575 } }, ["questGiverID"] = 179598, ["questTurnInID"] = 179598, ["questType"] = "standard", ["sourceQuests"] = { 64557 }, ["questLines"] = { { ["id"] = 1259, ["name"] = "The Box of Many Things", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 157, ["title"] = "Box of Many Things Intro", ["questLineID"] = 1259, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1912 },
[64211] = { ["id"] = 64211, ["name"] = "Doorway in the Dark", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["series"] = { 64213 }, ["description"] = "I fear our efforts to stop Zovaal have been thwarted, mortal. A doorway has been opened to a forbidden realm... and the Banished One has reclaimed a power taken from him long ago. I sense your allies returning from the Sanctum of Domination. I must know every detail of what transpired.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["npcID"] = 177194, ["x"] = 0.628, ["y"] = 0.262, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 180074, ["x"] = 0.63, ["y"] = 0.256, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.628, ["y"] = 0.262, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63593, 63944 }, ["questLines"] = { { ["id"] = 1248, ["name"] = "What Lies Ahead", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1248, ["questLineOrder"] = 8 } } },
[64212] = { ["id"] = 64212, ["name"] = "Doorway in the Dark", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["series"] = { 64214 }, ["description"] = "I fear our efforts to stop Zovaal have been thwarted, mortal. A doorway has been opened to a forbidden realm... and the Banished One has reclaimed a power taken from him long ago. I sense your allies returning from the Sanctum of Domination. I must know every detail of what transpired.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["npcID"] = 177194, ["x"] = 0.628, ["y"] = 0.262, ["mapID"] = 1961 } }, ["ends"] = { { ["npcID"] = 180073, ["x"] = 0.606, ["y"] = 0.278, ["mapID"] = 1961 } }, ["coords"] = { ["x"] = 0.628, ["y"] = 0.262, ["source"] = "quest_giver", ["mapID"] = 1961 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63593, 63944 }, ["questLines"] = { { ["id"] = 1248, ["name"] = "What Lies Ahead", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1248, ["questLineOrder"] = 8 } } },
[64213] = { ["id"] = 64213, ["name"] = "A Symbol of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63944, 64211, 64213, 64314 }, ["series"] = { 64211 }, ["description"] = "Before Anduin followed the Jailer through the gateway, he dropped something. I don't think this was part of the Jailer's plan. It must be a sign that Anduin's soul is still his own! <Jaina opens her hand to show you a golden compass.> This was very personal to Anduin. I feel his presence upon it. We need to know why he left it for us.", ["objectivesText"] = "Assist Jaina in examining Anduin's compass. Progress: If Anduin was able to leave this for us to find, then some part of him must still be free from the Jailer's domination...", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 180074, ["x"] = 0.631333, ["y"] = 0.248667 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 180074, ["x"] = 0.631333, ["y"] = 0.248667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.631333, ["y"] = 0.248667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64211 }, ["questLines"] = { { ["id"] = 1248, ["name"] = "What Lies Ahead", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1248, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64214] = { ["id"] = 64214, ["name"] = "A Symbol of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63944, 64212, 64214, 64314 }, ["series"] = { 64212 }, ["description"] = "Before Anduin followed the Jailer through the gateway, he dropped something. I'm not sure what it was, but Jaina picked it up. Perhaps this is a sign that Anduin is still fighting back against the Jailer! We need to find out what this object was, and why the young king left it for us.", ["objectivesText"] = "Assist in examining Anduin's compass. Progress: Why did Anduin leave this for us to find?", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 180073, ["x"] = 0.62, ["y"] = 0.2596 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 180073, ["x"] = 0.62, ["y"] = 0.2596 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.2596 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64212 }, ["questLines"] = { { ["id"] = 1248, ["name"] = "What Lies Ahead", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1248, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64215] = { ["id"] = 64215, ["name"] = "Paw Patrol", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7578, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "While Speedy IV was collecting supplies, Stringfellowe was scouting the rest of the Eye of Azshara . Turns out there is a whole mess of pirates to the west. That must be where the pets are at. Head over there and rescue the pets.", ["objectivesText"] = "Obtain keys from the Violetsail pirates along the west coast of the Eye of Azshara . Then set the captured pets free. Progress: Have you found them, <name>?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 55053, 77532, 82960, 130250, 159825, 159826, 171441, 186553, 186695, 186772, 187128 }, ["starts"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7578 } }, ["questType"] = "standard", ["sourceQuests"] = { 64203 }, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 790 },
[64216] = { ["id"] = 64216, ["name"] = "Tower Knowledge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1911, ["storyline"] = { 64210, 64216, 64557 }, ["description"] = "The woven power of this box can only be unlocked by feeding it pride and memory. In its weave are incantations I have seen used in the other realms to siphon or condition a soul. This... abomination... has used these tools of redemption and honor to create a lock. As you challenge the floors of Torghast, your skill, speed, and efficiency will all contribute to Tower Knowledge which this box can feed upon. Feed it to retrieve the powers within.", ["objectivesText"] = "Place the Box of Many Things in Torghast. Progress: < The Box of Many Things thrums with power.>", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 186732 }, ["starts"] = { { ["x"] = 0.503, ["y"] = 0.604, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["ends"] = { { ["x"] = 0.503, ["y"] = 0.604, ["mapID"] = 1912, ["npcID"] = 164937 } }, ["coords"] = { ["mapID"] = 1912, ["x"] = 0.503, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 164937, ["questTurnInID"] = 164937, ["questType"] = "standard", ["sourceQuests"] = { 64210 }, ["questLines"] = { { ["id"] = 1259, ["name"] = "The Box of Many Things", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 157, ["title"] = "Box of Many Things Intro", ["questLineID"] = 1259, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1911 },
