[64225] = { ["id"] = 64225, ["name"] = "Finding Firim", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "You found something? What luck! May I see the letter? So, an Enlightened named Xevveth heard that Firim was last seen west of the Forge of the Afterlives, and went to go seek him out. We should begin our search there.", ["objectivesText"] = "Find Firim .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 179611, ["x"] = 0.3725, ["y"] = 0.6685 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.3725, ["y"] = 0.6685 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64224 }, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 33, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64226] = { ["id"] = 64226, ["name"] = "Security Measures", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "It seems the hidden traps I placed around the grotto are not as effective as I would like, considering your presence in my home. However, they are still useful in preventing the majority of unwanted attention. Since you so kindly brought assassins to me, I cannot reset the traps myself. So you will need to do it for me. I will stay here to guard both myself and my precious research. Use this Sensory Synchronizer I placed nearby to show you which traps need to be reset.", ["objectivesText"] = "Use the Sensory Synchronizer, then reset 10 Triggered Traps near Exile's Hollow.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64225 }, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 35, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, 