[64228] = { ["id"] = 64228, ["name"] = "Now You May Speak", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 65149, 65305, 66042 }, ["description"] = "You truly brought me an oracle! Intact even! I have never known these divine beings to speak to anyone but automa. There is so much we could learn from her about Zereth Mortis . You must tell me everything!", ["objectivesText"] = "Talk to Firim about the oracle. Progress: Let me hear what happened...", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64226, 64227 }, ["questLines"] = { { ["id"] = 1250, ["name"] = "Forming an Understanding", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 36, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1250, ["questLineOrder"] = 2 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] =