[64237] = { ["id"] = 64237, ["name"] = "Gurgl and the Bandit", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7578, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "We've got all the pets back except Gurgl . <name>, we need to get that pet back for Breanni . Stringfellowe saw a nook where we think the leader of these pet poachers is hiding out. Let's get 'em!", ["objectivesText"] = "Find and battle the leader of the pet poachers.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 93040, 186553, 186695, 186772, 187128 }, ["starts"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7578 } }, ["questTurnInID"] = 179566, ["questType"] = "standard", ["sourceQuests"] = { 64215 }, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[64240] = { ["id"] = 64240, ["name"] = "Flight of the Kyrian", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64240 }, ["description"] = "We've engaged in a heavy battle at the entrance to the Vault of Secrets! Our forces could use some reinforcement. Please, guide my fellow Ascended to give support to our fighters there. The fighters on the ground can handle the clean-up, but they need shields and healing. Good luck!", ["objectivesText"] = "Assist covenant forces from the air at the Vault of Secrets. Progress: Have you helped our forces at the Vault of Secrets?", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179194, ["x"] = 0.616, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179194, ["x"] = 0.616, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
