[64266] = { ["id"] = 64266, ["name"] = "Supplies from The Archivists' Codex", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64266 }, ["description"] = "I have no words to express the warmth that fills me knowing your dedication has ensured Korthia's history remain intact. Please. Allow me to share my gratitude.", ["objectivesText"] = "Speak with Archivist Roh-Suir in the Reliquary of Remembrance in Korthia.", ["rewardItems"] = { 187028 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2473, ["threshold"] = 10000 } } } },
[64267] = { ["id"] = 64267, ["name"] = "Mysterious Gifts from Ve'nari", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13608, ["mapID"] = 1543, ["storyline"] = { 64267 }, ["description"] = "I'm impressed by your sheer tenacity to survive while remaining somewhat useful, Maw Walker. You remind me of myself when I was much younger and naive. Take this and continue your work... somewhere less conspicuous.", ["objectivesText"] = "Speak with Ve'nari at Ve'nari 's Refuge in the Maw.", ["rewardItems"] = { 187029 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2474, ["threshold"] = 10000 } } } },
[64271] = { ["id"] = 64271, ["name"] = "A More Civilized Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64271 }, ["description"] = "Ah, $p. I have a matter to discuss with you. But not here. <Nadjia eyes the other denizens of Keeper's Respite suspiciously.> Meet me where the road enters Korthia from the Maw and I will explain.", ["objectivesText"] = "Meet Nadjia near the road leading into Korthia .", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["rewardCurrencies"] = { { ["id"] = 1907, ["amount"] = 175 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178795, ["x"] = 0.618, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178795, ["x"] = 0.618, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64282] = { ["id"] = 64282, ["name"] = "Full of Surprises", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 64282 }, ["description"] = "You continue to surprise me Maw Walker, your presence here is most unexpected! Since we are both here, I believe we should work together. The Jailer has a vault full of valuables, somewhere in this rift. Locate it for me, or bring it here to be opened and we'll share the wealth together!", ["objectivesText"] = "Locate Zovaal's Vault. Progress: Have you found the vault?", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 180817, 186731, 186969, 187113 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179904, ["x"] = 0.447, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 179904, ["x"] = 0.447, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.447, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[64286] = { ["id"] = 64286, ["name"] = "Paragon of Death's Advance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64286 }, ["description"] = "The call to action has been answered, yet again. Your efforts shall not go unnoticed. Let us see if we cannot find a fitting reward for your efforts.", ["objectivesText"] = "Speak with Duchess Mynx at Keeper's Respite in Korthia .", ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179321, ["x"] = 0.634, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64287] = { ["id"] = 64287, ["name"] = "Paragon of The Archivists' Codex", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64287 }, ["description"] = "You have gone to great lengths to restore that which we cherish most dearly, Maw Walker. Meet me in my chamber when you are ready. We have one final matter to discuss.", ["objectivesText"] = "Speak with Archivist Roh-Suir at the Reliquary of Remembrance in Korthia.", ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64288] = { ["id"] = 64288, ["name"] = "Paragon of Ve'nari", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 64288 }, ["description"] = "Come, Maw Walker. Meet me at my refuge. We have one final matter to discuss. ...and do make sure you are not followed.", ["objectivesText"] = "Speak with Ve'nari at Ve'nari 's Refuge in The Maw .", ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[64289] = { ["id"] = 64289, ["name"] = "Picking Up the Pieces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64289 }, ["description"] = "Much was lost when Korthia was pulled into the Maw. Priceless relics were torn asunder. I have seen creatures carrying the remnants of these items. They must be recovered. Confront the Jailer's forces and search what remains of Korthia for these fragments of our once glorious vault.", ["objectivesText"] = "Recover 50 Relic Fragments from rare creatures and treasures throughout Korthia.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 63738 } },
[64290] = { ["id"] = 64290, ["name"] = "Collecting Research", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64290 }, ["description"] = "You have done well to collect these fragments. They will go a long way to restoring our archives. I can use what you have found to gather more research about what was lost within Korthia. Afterwards, it will be up to you to find more fragments and relics within Korthia to boost our archives.", ["objectivesText"] = "Speak with Archivist Roh-Suir to turn in any Korthian Relics for Cataloged Research. Progress: We thank you for your aid so far, Maw Walker.", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186664, 186665, 186716, 186734, 186735, 186741, 186742, 186750, 186751, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["rewardChoices"] = { 186734, 186735, 186741, 186742 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64289 } },
[64292] = { ["id"] = 64292, ["name"] = "Maelie, The Wanderer", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13625, ["mapID"] = 1961, ["storyline"] = { 64292 }, ["description"] = "I can't thank you enough for finding Maelie! You know, I think she's just a little bit more than I can handle. Would you mind watching over her? I think she's really taken a liking to you!", ["objectivesText"] = "Accept responsibility for Maelie.", ["rewardItems"] = { 184513, 186643 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179930, ["x"] = 0.606, ["y"] = 0.218 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179930, ["x"] = 0.606, ["y"] = 0.218 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.218 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64314] = { ["id"] = 64314, ["name"] = "Covenants Renewed", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63944, 64211, 64212, 64213, 64214, 64314 }, ["description"] = "Our efforts were focused on preventing the Jailer from shattering the barrier around the Maw and invading the rest of the Shadowlands. Instead, he expanded the Maw itself to envelop Oribos and claim the Aribiter's sigil. I do not fully understand what we witnessed atop Torghast. But the Primus certainly does. It is time to enact his contingency plan. The covenants will arrive with their sigils shortly. Inform the Primus that we are ready to begin.", ["objectivesText"] = "Speak to the Primus , then claim the Sigils from each covenant.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187347 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177194, ["x"] = 0.63, ["y"] = 0.250667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64213, 64214 }, ["questLines"] = { { ["id"] = 1248, ["name"] = "What Lies Ahead", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1248, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64322] = { ["id"] = 64322, ["name"] = "Night Fae Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 64085, 64322 }, ["description"] = "Ardenweald is safer than it has been in quite some time, thanks to you. Your accomplishments have not gone unnoticed, even beyond the borders of Ardenweald. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["x"] = 0.34, ["y"] = 0.37, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["ends"] = { { ["x"] = 0.34, ["y"] = 0.37, ["mapID"] = 1701, ["npcID"] = 176096 } }, ["coords"] = { ["mapID"] = 1701, ["x"] = 0.34, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questGiverID"] = 176096, ["questTurnInID"] = 176096, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1255, ["name"] = "Night Fae Combatant", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
