[64554] = { ["id"] = 64554, ["name"] = "Venthyr Assault", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1543, ["storyline"] = { 64554 }, ["description"] = "The Jailer's forces have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination! Your help is needed Maw Walker. Assist our forces on the battlefield!", ["objectivesText"] = "Complete 1 quests in Perdition Hold and the Face of Oblivion.", ["rewardItems"] = { 185990 }, ["starts"] = { { ["x"] = 0.299, ["y"] = 0.171, ["mapID"] = 1543, ["npcID"] = 178006 } }, ["ends"] = { { ["x"] = 0.299, ["y"] = 0.171, ["mapID"] = 1543, ["npcID"] = 178006 } }, ["coords"] = { ["mapID"] = 1543, ["x"] = 0.299, ["y"] = 0.171 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 178006, ["questTurnInID"] = 178006, ["questType"] = "standard", ["sourceQuests"] = { 63902 }, ["db2Objectives"] = { { ["text"] = "Ask Burly Hurly to throw you", ["amount"] = 1, ["type"] = 0, ["objectID"] = 178164, ["orderIndex"] = 0 }, { ["text"] = "Report to Prince Renathal on top of the Tremaculum wall", ["amount"] = 1, ["type"] = 0, ["objectID"] = 177926, ["orderIndex"] = 1 }, { ["text"] = "Help Venthyr and Night Fae forces assault the Tremaculum", ["amount"] = 4, ["type"] = 0, ["objectID"] = 177524, ["orderIndex"] = 2 }, { ["text"] = "Help Draven secure the upper platform", ["amount"] = 1, ["type"] = 0, ["objectID"] = 178242, ["orderIndex"] = 3 }, { ["text"] = "Travel through a Maw Mirror", ["amount"] = 1, ["type"] = 0, ["objectID"] = 178243, ["orderIndex"] = 4 }, { ["text"] = "Light directed into Maw Mirrors", ["amount"] = 4, ["type"] = 0, ["objectID"] = 178244, ["orderIndex"] = 5 }, { ["text"] = "Mirror 1", ["amount"] = 1, ["type"] = 0, ["objectID"] = 178245, ["orderIndex"] = 6 }, { ["text"] = "Mirror 2", ["amount"] = 1, ["type"] = 0, ["objectID"] = 178246, ["orderInd