[64555] = { ["id"] = 64555, ["name"] = "Surveying Secrets", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63660, 63661, 63662, 63663, 63665, 63994, 64007, 64555, 64556 }, ["description"] = "Each of the covenants have provided their own specialists in their areas of expertise. A few of them have taken to the field to scout this unknown land. Speak with them. They should all be keeping a report of their survey. Return them to me.", ["objectivesText"] = "Speak with the forward scouts in Korthia . Progress: Have you found all of the scouts?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185754, 186170, 187436, 187437, 187438, 187439, 187504 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64007 }, ["questLines"] = { { ["id"] = 1225, ["name"] = "Maw Walkers", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1246, ["name"] = "Patch Intro", ["orderIndex"] = 30, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 138, ["title"] = "Chains of Domination", ["questLineID"] = 1225, ["questLineOrder"] = 1 }, { ["id"] = 162, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1225, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1225, ["questLineOrder"]