[64557] = { ["id"] = 64557, ["name"] = "In Darkness, Found", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10472, ["mapID"] = 1961, ["storyline"] = { 64210, 64216, 64557 }, ["description"] = "Cartel Ve has a reputation for creeping around dangerous places in search of treasure. If they had any sense, they would leave the acquisition and sale of goods to the Xy. Alas. One Ve member disappeared into Torghast with a plundered box of powerful items that he assumed would help him explore in safety. Madness!", ["objectivesText"] = "Find Ve'nish in Torghast, Tower of the Damned .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178845, ["x"] = 0.645333, ["y"] = 0.254667 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178845, ["x"] = 0.645333, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.645333, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questTurnInID"] = 178845, ["questType"] = "standard", ["sourceQuests"] = { 63902 }, ["nextQuests"] = { 64210 }, ["questLines"] = { { ["id"] = 1259, ["name"] = "The Box of Many Things", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 157, ["title"] = "Box of Many Things Intro", ["questLineID"] = 1259, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64560] = { ["id"] = 64560, ["name"] = "Anima Reclamation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64560 }, ["description"] = "Our efforts here need a constant supply of troops, supplies, and anima. The last one is the hardest, for obvious reasons. But I've learned to be resourceful. Nearby there is a plentiful source of anima: the devourers that currently swarm the Sanctuary of Guidance. It's not as easy as beating it out of a soul, but it's just as effective, if you're strong enough. Are you?", ["objectivesText"] = "Reclaim 8 Devoured Anima from devourers at the Sanctuary of Guidance. Progress: Every drop of anima we reclaim is a potential weapon against the Jailer.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 185754, 186170, 186201, 186205, 186206, 187328, 187334, 187336, 187436, 187437, 187438, 187439, 187466, 187504 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178793, ["x"] = 0.618, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178793, ["x"] = 0.618, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64561] = { ["id"] = 64561, ["name"] = "Observational Records", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64561 }, ["description"] = "Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The records from the Windswept Aerie and Estuary of Awakening should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. And don't forget to look below ground! Bring those data to me, and I will reward you handsomely.", ["objectivesText"] = "Collect 5 Observational Records from the Windswept Aerie and Estuary of Awakening in Korthia . Progress: Have you retrieved the observational records from the Windswept Aerie and Estuary of Awakening?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 184374, 185754, 185855, 185856, 185857, 185858, 185859, 185860, 185861, 185862, 185863, 185864, 185865, 185866, 185867, 185868, 185869, 185870, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185879, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185887, 185888, 185889, 185890, 185891, 185893, 185894, 185895, 185896, 185897, 185898, 185899, 185900, 185901, 185903, 185905, 185941, 185944, 186017, 186155, 186156, 186170, 186201, 186205, 186206, 186663, 186664, 186665, 186666, 186667, 186668, 186669, 186670, 186734, 186735, 186736, 186737, 186738, 186739, 186740, 186741, 186742, 186743, 186744, 186745, 186746, 186747, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186758, 186759, 186760, 186761, 186762, 186763, 186764, 186765, 186766, 186767, 186768, 186769, 186770, 186771, 186976, 187436, 187437, 187438, 187439, 187504, 187506, 187507 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178844, ["x"] = 0.648, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178844, ["x"] = 0.648, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64562] = { ["id"] = 64562, ["name"] = "We Need a Healer - You!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64562 }, ["description"] = "There are too many wounded on the battlefield! Not everyone can 'bash it and make better.' We need more healers. You, take my device and get our wounded back on their feet!", ["objectivesText"] = "Restore 10 Wounded Covenant Allies in Seeker's Quorum.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 185754, 186170, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187436, 187437, 187438, 187439, 187466, 187504 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179216, ["x"] = 0.615, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179216, ["x"] = 0.615, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["sourceQuests"] = { 64556 }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64567] = { ["id"] = 64567, ["name"] = "The Missing Scholar", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64567 }, ["series"] = { 63731, 63732 }, ["description"] = "Ah, Maw Walker. Your return blesses us with great optimism, and much needed assistance. Several scholars remain unaccounted for. We believe they were last seen studying in the great court. We fear they may be lost, or worse, taken by those who seek to disrupt our way of life. Return to me when you have answers. May the path guide you.", ["objectivesText"] = "Locate Scholar Roh-Suir in Korthia.", ["rewardGold"] = 25740, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177927, ["x"] = 0.628, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178694, ["x"] = 0.59, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["nextQuests"] = { 63732 } },
