[64579] = { ["id"] = 64579, ["name"] = "Hollow Efforts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64579 }, ["description"] = "The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process. These empty metal husks still contain residual materials of creation that may be useful to us. Use my Forge-Tap near these metal spheres to harvest any Remnant Neomotes . You may also find other useful proto-materials!", ["objectivesText"] = "Collect 40 Remnant Neomotes from Progenitor Forges using Firim's Forge-Tap . Progress: Have you gathered the materials already?", ["rewardXP"] = 8165, ["rewardItems"] = { 187516, 187519, 189544, 190189, 190342, 190343, 190345, 190346, 190348, 190350, 190351, 190352, 190353, 190355, 190356, 190357, 190358, 190359, 190360, 190361, 190363, 190365, 190366, 190368, 190369, 190605, 190632, 190633, 190635, 192423, 192424, 192426, 192427, 192429, 192440, 192450, 190362 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 21 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
