[64641] = { ["id"] = 64641, ["name"] = "Mysterious Greenery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["description"] = "There's a bright power emanating from the place above. I'm drawn towards it, like a moth to a light! I want to check it out, whatever it is. Won't you join me, please? It'll be so fun!", ["rewardGold"] = 128700, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 180799, ["x"] = 0.552, ["y"] = 0.644, ["mapID"] = 1970 } }, ["ends"] = { { ["npcID"] = 179900, ["x"] = 0.604, ["y"] = 0.7, ["mapID"] = 1970 } }, ["coords"] = { ["x"] = 0.552, ["y"] = 0.644, ["source"] = "quest_giver", ["mapID"] = 1970 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65432 }, ["questLines"] = { { ["id"] = 1290, ["name"] = "Reap What You Sow", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64642] = { ["id"] = 64642, ["name"] = "Clearing the Ruins", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64641, 64642, 64643, 64644, 64645, 64646, 64647, 64648 }, ["description"] = "This place was abandoned for too long. The vegetation has overtaken the land. We must enter the Blooming Foundry to fix it. Until then: clear the area. Remove the deviants who have grown twisted over time.", ["objectivesText"] = "Kill 15 creatures within the Untamed Verdure.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187131, 187619 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 179900, ["x"] = 0.605, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 179900, ["x"] = 0.605, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64641 }, ["questLines"] = { { ["id"] = 1290, ["name"] = "Reap What You Sow", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
