[64706] = { ["id"] = 64706, ["name"] = "A Matter Of Motivation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Giants litter these sands, mortal. But I believe we can revitalize them. The smaller automa that are hiding in the desert can be utilized here. Use my Motivator to rally them to our cause. If we can gather enough, their energy can replenish these defeated behemoths to bolster our forces. Return as many as you can to me, and we will put them to work!", ["objectivesText"] = "Return 6 Motivated Automa to Firim . Progress: Have they been suitably motivated?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 188678, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180903, ["x"] = 0.563, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180903, ["x"] = 0.563, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64733 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64710] = { ["id"] = 64710, ["name"] = "Whispering Felflame Crystal", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 64710 }, ["description"] = "The crystal pulses with an eerie, felfire green glow. Holding it, you hear faint echoes of guttural demonic voices. Although the words are jumbled, one is both decipherable and repeated often: Dalaran . Perhaps someone in the city floating over the Broken Isles can tell you more about this crystal and its purpose.", ["objectivesText"] = "Bring the Whispering Felflame Crystal to Aridormi in Dalaran , floating above the Broken Isles.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 129747, 129928, 133377, 133378, 143776, 167921, 167922, 187611, 225348 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 200 }, { ["id"] = 1166, ["amount"] = 500 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 187611 } },
[64713] = { ["id"] = 64713, ["name"] = "Picking Up the Pieces... Literally", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "Orbs help us develop terrain for the Forge. Magic within the orbs draws the devourers. They tear apart the metal to reach it. We must collect the remains. Look for the fragments around the orbs. Bring them to us.", ["objectivesText"] = "Collect 30 Orb Fragments . Progress: Did you find the fragments? We need many pieces.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187615 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180919, ["x"] = 0.366, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180919, ["x"] = 0.366, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64772 }, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64717] = { ["id"] = 64717, ["name"] = "Materials of Creation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64717 }, ["description"] = "The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process. The spheres near the Forge of Afterlives contain trace amounts of materials unique to that location. I have modified my Forge-Tap to harvest those materials. Use it near the forges I have identified. The rare Eidolic Fragments have the greatest chance to be found on the largest of Progenitor Forges .", ["objectivesText"] = "Collect 10 Eidolic Fragments and 300 Minor Enigmet . Progress: Have you collected what we need?", ["rewardXP"] = 8165, ["rewardItems"] = { 187516, 187527, 187728, 187779, 187782, 187787, 187788, 187789, 187790, 187791, 187908, 188231, 189544, 190062, 190189, 190341, 190342, 190343, 190345, 190346, 190347, 190348, 190350, 190352, 190353, 190354, 190355, 190356, 190357, 190358, 190360, 190361, 190362, 190363, 190364, 190365, 190366, 190367, 190368, 190369, 190370, 190371, 190372, 190605, 190632, 190633, 190634, 190635, 192427 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 20 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64718] = { ["id"] = 64718, ["name"] = "Keys To Victory", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "The song... incomplete. Harmony is needed. Seek those who scry. Send them to serve the cycle. Mawsworn hold the keys that bind. Take the keys, set them free.", ["objectivesText"] = "Free 6 Automa Scryers from their cells.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64733 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64720] = { ["id"] = 64720, ["name"] = "Cleaving A Path", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Maw Walker! My scouts report that the Mawsworn have dominated two automa Oracles to aid them in battle. These Oracles will most certainly predict our strategy and our ultimate goal, if given the chance. We need to eliminate both Oracles before we enter the Crypts. With them out of the way, the Mawsworn troops won't know what we're doing until we're finished with it. Take Emeni with you. She's eager for battle.", ["objectivesText"] = "Slay Oracle Zoketh and Oracle Voraxxi .", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 187602, 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180928, ["x"] = 0.56, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180928, ["x"] = 0.56, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64733 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64722] = { ["id"] = 64722, ["name"] = "Knocking On Death's Door", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "This is it, mortal. The forces you have assembled should be enough to break through the Mawsworn and reach the Crypts. Getting inside, however, will require more effort. The Mawsworn have barricaded the entrance. Kbato will carry you into battle. Eliminate the Mawsworn, and destroy the devices that power the barrier.", ["objectivesText"] = "Riding Kbato, defeat the Mawsworn forces in the Endless Sands and open the way to the Crypts of the Eternal.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 188008, 188014, 188021, 188030, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180903, ["x"] = 0.563, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180903, ["x"] = 0.563, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questTurnInID"] = 180903, ["questType"] = "standard", ["sourceQuests"] = { 64706, 64718, 64720 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031 },
[64723] = { ["id"] = 64723, ["name"] = "Restoration Project", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["series"] = { 64733, 64879 }, ["description"] = "Without an Arbiter, the very purpose of the Shadowlands has been compromised. Souls flood the Maw with no direction. As Saezurah noted, Zereth Mortis would ordinarily craft a new being to take the Arbiter's place. I suspect the Jailer's forces have disrupted the land to the point where this is no longer possible. It is time to take action ourselves, and bring stability again to the Shadowlands! Speak to Saezurah, and see where we must begin.", ["objectivesText"] = "Speak with Saezurah. Progress: Have you spoken with them?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187602, 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181545, ["x"] = 0.343, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64879 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64725] = { ["id"] = 64725, ["name"] = "Unforgivable Intrusion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Darkness spreads dissonance throughout these halls. Mawsworn drain life from the air, and give only suffering in return. This must not be. If the song is to be restored, silence is needed. The Mawsworn must be destroyed.", ["objectivesText"] = "Eliminate 6 Dominated Automa and 3 Darkseer Corrupters . Progress: When the halls are silent, we may proceed.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["sourceQuests"] = { 64727 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031 },
[64726] = { ["id"] = 64726, ["name"] = "The Order Of Things", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Essences of ancient souls, tampered with--they bleed from each room. The halls must be restored, the flow of souls redirected. The spheres hold the key. Seal the breaches, restore the flow, then the vessel may be filled.", ["objectivesText"] = "Use $13oa Containment Spheres to seal the breaches. Progress: Seal the breach, restore the flow.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["sourceQuests"] = { 64727 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031 },
[64727] = { ["id"] = 64727, ["name"] = "The Infinite Circle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Creation calls--can you hear it? Yet darkness lingers below, taints the ancient melody. To forge anew, peace must be restored. The Walker must walk, and protect. There is much to be done. Lead the way.", ["objectivesText"] = "Escort Saezurah to the center of the Crypts of the Eternal.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["sourceQuests"] = { 64722 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031 },
[64728] = { ["id"] = 64728, ["name"] = "Acquaintances Forgotten", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "It is time. The song shall bring life anew. Tell me when you are ready to begin.", ["objectivesText"] = "Complete the Ritual. Progress: The ritual must be completed.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["sourceQuests"] = { 64962 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031 },
[64729] = { ["id"] = 64729, ["name"] = "Lifetimes To Consider", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["series"] = { 65238, 65329 }, ["description"] = "This song has been completed, and harmony has been restored. Yet Zereth Mortis remains haunted by discord. Dissonance lingers still, outside these walls. We must leave before it finds us. Speak with the one you call Firim--he will open the way.", ["objectivesText"] = "Return to Exile's Hollow.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475, 190980, 190981, 190982, 190986, 190987, 190988, 190992, 190993, 190994, 190998, 190999, 191000 }, ["rewardChoices"] = { 190986, 190987, 190988 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181545, ["x"] = 0.343, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64731 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64730] = { ["id"] = 64730, ["name"] = "The Turning Point", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "A pause, devoid of breath. A melody lingers on. The cycle awaits a voice. <You are unsure of what Saezurah means. Perhaps you should try to set up the ritual again, starting with the Vessel and the scryers.>", ["objectivesText"] = "Examine the Vessel and the Automa Scryers. Progress: Have you tried everything?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 30372, 30373, 30374, 30375, 30859, 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180915, ["x"] = 0.565, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["sourceQuests"] = { 64728 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031 },
[64731] = { ["id"] = 64731, ["name"] = "For Every Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["description"] = "Without the Arbiter to stem the flow of souls to the Maw, the Shadowlands will never be fully repaired. This cannot be the end. Surely you can think of something?", ["objectivesText"] = "Find a way to create a new Arbiter. Progress: This moment is of great importance.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180915, ["x"] = 0.565, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180942, ["x"] = 0.57, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13753 } }, ["questType"] = "standard", ["sourceQuests"] = { 64730 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 2031 },
[64733] = { ["id"] = 64733, ["name"] = "Help From Beyond", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64706, 64718, 64720, 64722, 64723, 64725, 64726, 64727, 64728, 64729, 64730, 64731, 64733, 64962, 65238 }, ["series"] = { 64723, 64879 }, ["description"] = "If we stand any chance of breaking through the Mawsworn forces, we will need the help of all of the covenants. I will speak with the Kyrian. You and Pelagos can speak with the others. But before you go, ask Firim if there is any way we can gain the support of the Enlightened as well.", ["objectivesText"] = "Speak with representatives from the Enlightened, Venthyr, Necrolord, and Night Fae.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181545, ["x"] = 0.343, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180914, ["x"] = 0.566, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.343, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64723 }, ["questLines"] = { { ["id"] = 1260, ["name"] = "Starting Over", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1260, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64739] = { ["id"] = 64739, ["name"] = "Zovaal's Grasp", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "I remember this metal. I saw it when I was touched by Maw magic. When I was severed... I will show you where this happened. Follow me. I will tell you my story.", ["objectivesText"] = "Follow Hanoa the Exile and listen to her story.", ["rewardGold"] = 64350, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184469, ["x"] = 0.4094, ["y"] = 0.3284 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180989, ["x"] = 0.426, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.4094, ["y"] = 0.3284 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64775 }, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64741] = { ["id"] = 64741, ["name"] = "Security Check", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["description"] = "I do not understand--these are my brethren! How can they be so careless, so unconcerned with both greedy cartels and the Mawsworn at their doorstep? Their protective technology is antiquated. It will not keep danger out. If I cannot persuade them to leave, I can at least ensure they are safe where they insist on staying. I do not want to lose my friends again. There should be four hidden conduits around the edge of the shield. Take this kit. It will allow you to inspect and repair them, if needed.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["ends"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["coords"] = { ["x"] = 0.338, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 1970 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64771 }, ["questLines"] = { { ["id"] = 1291, ["name"] = "Not Al Are Lost", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64742] = { ["id"] = 64742, ["name"] = "Traces of Tampering", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["description"] = "So the shield has been sabotaged. Of course the ruthless Cartel Xy are the first to attempt to profit off this land. Their greed has put us all in even more danger. We must stop them. Let us search together for signs of their passage.", ["rewardGold"] = 128700, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["ends"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["coords"] = { ["x"] = 0.338, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 1970 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64741 }, ["questLines"] = { { ["id"] = 1291, ["name"] = "Not Al Are Lost", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64743] = { ["id"] = 64743, ["name"] = "Xy Are You Doing This?", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["description"] = "We cannot see them, but I am certain this is where Cartel Xy has established their base. Something must have drawn Xy to this area of Zereth Mortis specifically, and we must discover what it is if we are to protect our friends here. Their cloaks do not cover their supplies very well. See what information you can gather from their belongings.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["ends"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["coords"] = { ["x"] = 0.338, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 1970 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64742 }, ["questLines"] = { { ["id"] = 1291, ["name"] = "Not Al Are Lost", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64744] = { ["id"] = 64744, ["name"] = "Broker Decloaker", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["description"] = "Do you sense a shift in the air? They may be hidden, but Cartel Xy is near. Fortunately, the devices they use to cloak themselves are familiar to me. Here; take this. Place it on the ground and it will reveal nearby agents... for a time. Stop them, even if you must take their lives.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["ends"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["coords"] = { ["x"] = 0.338, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 1970 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64742 }, ["questLines"] = { { ["id"] = 1291, ["name"] = "Not Al Are Lost", ["orderIndex"] = 3, ["flags"] = 0 } } },
[64745] = { ["id"] = 64745, ["name"] = "Selfless Preservation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "The automa were once abundant here, singing, constructing various things, carrying out the purpose of the First Ones. Then, invaders from the Maw slaughtered them all. The last automa to fall were protecting something important in a nearby structure. I witnessed one of the cursed Mawsworn steal a device by the door. The Elders say we should not meddle with artifacts, but would it be a transgression to recover what was stolen?", ["objectivesText"] = "Recover the Stolen Artifact in the Arrangement Index and restore it to its rightful place.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.631667, ["y"] = 0.412333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["sourceQuests"] = { 64829 }, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64758] = { ["id"] = 64758, ["name"] = "Following the Leader", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["description"] = "We sealed the door to the Slumbering Vault when we first arrived. It is a sanctum, a cradle of all that is precious here. The power that sleeps within should not be touched by us. If the Xy leader made it past the shields while we were distracted by the beauty of this place, I shudder to think of what they have already disturbed. Hurry! We must go to the Slumbering Vault and ensure its safety.", ["rewardGold"] = 128700, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 180936, ["x"] = 0.336, ["y"] = 0.598, ["mapID"] = 1970 } }, ["ends"] = { { ["npcID"] = 180936, ["x"] = 0.336, ["y"] = 0.598, ["mapID"] = 1970 } }, ["coords"] = { ["x"] = 0.336, ["y"] = 0.598, ["source"] = "quest_giver", ["mapID"] = 1970 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64743, 64744 }, ["questLines"] = { { ["id"] = 1291, ["name"] = "Not Al Are Lost", ["orderIndex"] = 4, ["flags"] = 0 } } },
[64759] = { ["id"] = 64759, ["name"] = "Junk's Not Dead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "This automa has been hiding here! I suspect it will not be receptive to our help. I am hesitant to suggest this, but if the servitor were to associate you with this facility, it might be more amenable. If you have the means, copy the glyphs inscribed on similar automa outside. Those that the Maw have touched will be tainted, but I saw from my vantage point a few fallen automa in the sands with untarnished glyphs.", ["objectivesText"] = "Obtain glyphs from 6 Depleted Servitors around the Arrangement Index.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.631667, ["y"] = 0.412333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["sourceQuests"] = { 64745 }, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64760] = { ["id"] = 64760, ["name"] = "Technical Difficulties", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["description"] = "The console is going haywire! We have to fix it! Maybe these buttons do something?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardChoices"] = { 190597 }, ["starts"] = { { ["npcID"] = 180936, ["x"] = 0.336, ["y"] = 0.598, ["mapID"] = 1970 } }, ["ends"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["coords"] = { ["x"] = 0.336, ["y"] = 0.598, ["source"] = "quest_giver", ["mapID"] = 1970 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64758 }, ["questLines"] = { { ["id"] = 1291, ["name"] = "Not Al Are Lost", ["orderIndex"] = 5, ["flags"] = 0 } } },
[64761] = { ["id"] = 64761, ["name"] = "Core Competency", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "The poor thing. The sacred should not be disturbed, but... will the elders judge us if we help it survive? This is preservation, not interference. ...I hope. We can power it back up. Use this depleted core as a conduit. Perhaps the larger wild animates in the nearby sands have enough energy to charge it.", ["objectivesText"] = "Charge a Depleted Automa Core by draining slain wild creatures in the Arrangement Index.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.631667, ["y"] = 0.412333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["sourceQuests"] = { 64745 }, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64762] = { ["id"] = 64762, ["name"] = "Revival of the Fittest", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "This core is brimming with energy! Use the charged core to revive the automa. Hopefully, it will no longer see us as a threat. Do be careful. The power of the First Ones is not meant for us to control.", ["objectivesText"] = "Revive the Hidden Servitor in the Arrangement Index.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.631667, ["y"] = 0.412333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64759, 64761 }, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64763] = { ["id"] = 64763, ["name"] = "Maintenance Mode", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "The architect set forth these tasks: Stay safe. Restore the Protoform Repository when danger passes. The mortal knows the cyphers. The mortal will help with the tasks. Attuning of the energy terminals is required. Each terminal requires a codex. Invaders pilfered the necessary codices. Go.", ["objectivesText"] = "Attune 4 Energy Terminals in the Arrangement Index.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.6624, ["y"] = 0.3236 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["sourceQuests"] = { 64762 }, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64766] = { ["id"] = 64766, ["name"] = "Access Request", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "The architect alone possesses the Restoration Matrix required for the restoration. The architect will restore the Protoform Repository. The mortal will gain access to the Chamber of Shaping and inform the architect of recent progress. The architect will restore the repository. Fulfillment of the task is imminent.", ["objectivesText"] = "Find the Proto Architect in the Chamber of Shaping and retrieve a Restoration Matrix . Progress: The architect will assist us.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189460, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.6624, ["y"] = 0.3236 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["sourceQuests"] = { 64762 }, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64767] = { ["id"] = 64767, ["name"] = "The Final Song", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64745, 64759, 64761, 64762, 64763, 64766, 64767, 64829, 65420 }, ["description"] = "Servitors do not possess the strength to restore the repositories. Nevertheless, the task must be completed. The mortal must stay close to protect the restoration process. Come.", ["objectivesText"] = "Stay near Kodah while keeping enemies away to capture the Protoform Repository.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 187628, 187635, 187638, 187941, 188798, 188957, 189178, 189457, 189492, 189499, 189500, 189501 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180610, ["x"] = 0.6624, ["y"] = 0.3236 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181273, ["x"] = 0.631667, ["y"] = 0.412333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.6624, ["y"] = 0.3236 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "group", ["sourceQuests"] = { 64763, 64766 }, ["questLines"] = { { ["id"] = 1285, ["name"] = "The Final Song", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
