[64771] = { ["id"] = 64771, ["name"] = "Enlightened Exodus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["description"] = "Hello, my friend! An expedition of Cartel Al was sent in search of this place long ago, and was believed lost. I entered Zereth Mortis in hopes of saving my splintered cartel from the dangers of the Maw that have preceded me. At last, I have found my old friend! And yet, she refuses to return to safety. Perhaps others can be convinced. Will you try?", ["rewardGold"] = 193050, ["rewardXP"] = 8165, ["starts"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["ends"] = { { ["npcID"] = 181003, ["x"] = 0.338, ["y"] = 0.646, ["mapID"] = 1970 } }, ["coords"] = { ["x"] = 0.338, ["y"] = 0.646, ["source"] = "quest_giver", ["mapID"] = 1970 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64958 }, ["questLines"] = { { ["id"] = 1291, ["name"] = "Not Al Are Lost", ["orderIndex"] = 6, ["flags"] = 0 } } },
[64772] = { ["id"] = 64772, ["name"] = "Broken Circle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["series"] = { 64775 }, ["description"] = "The jiro of Circle Olea work here. We make... <The jiro pauses for a moment.> They... make new lands and creatures for the Forge. Devourers attacked, but some jiro still survive. You must find them. Tell them to gather outside the cave to the north. I will clear the way. Do not tell them I sent you. They will not want to see me.", ["objectivesText"] = "Find any surviving jiro and convince them to meet outside the cave.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187804, 187824, 188793, 189980, 189986, 190333, 191039 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181091, ["x"] = 0.4, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180984, ["x"] = 0.395, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65431 }, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64773] = { ["id"] = 64773, ["name"] = "A Jiro Guide to Not Being Eaten", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "Devourers attacked. They overran the guardians. They still search for food. We are not safe. Reduce the devourers' numbers. This is how not to be eaten.", ["objectivesText"] = "Reduce the devourer presence at the Terrace of Formation. Progress: Is it safe? There are so many devourers...", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181098, ["x"] = 0.38, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181098, ["x"] = 0.38, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64772 }, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64775] = { ["id"] = 64775, ["name"] = "Mawdified Behavior", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["series"] = { 64772 }, ["description"] = "There is a devourer in the cave. It creates a rift. This should not be possible in Zereth Mortis . Enter the cave and destroy the devourer. Search for clues. See how it can open a rift. Be careful. This one is different from others. It has absorbed the magic of the First Ones. This has never happened before. Be ready for anything. I will stay here and protect the jiro.", ["objectivesText"] = "Kill the Unraveller and search it for clues. Progress: Is the devourer destroyed? Did you find any clues?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 189493 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180984, ["x"] = 0.395, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184469, ["x"] = 0.4094, ["y"] = 0.3284 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64713, 64773, 65370 }, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64778] = { ["id"] = 64778, ["name"] = "Rift Recon", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "Devourers are a problem. Rifts are a bigger problem. They will keep bringing devourers. We must close them. To do this, we need information. Take the crescendal. Use it to analyze the rifts. Bring the information back to us.", ["objectivesText"] = "Analyze 6 Warped Rifts. Progress: Do not break the crescendal. It can be... difficult to use.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181170, ["x"] = 0.426, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181170, ["x"] = 0.426, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64739 }, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64779] = { ["id"] = 64779, ["name"] = "Pound of Flesh", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "Automa remove threats to us. But there are no more automa. We must help ourselves. We need magic. Devourers ate the orb magic. Now they are warped and twisted. But also full of magic. Bring us devourer flesh. We will extract the magic. We will need it to defeat the devourers.", ["objectivesText"] = "Collect 30 Warped Flesh from devourers at Zovaal's Grasp. Progress: Devourers were not meant to eat this magic.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187950 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181174, ["x"] = 0.426, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181174, ["x"] = 0.426, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64739 }, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64780] = { ["id"] = 64780, ["name"] = "Mawsteel, Maw Problems", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64713, 64739, 64772, 64773, 64775, 64778, 64779, 64780, 65219, 65370 }, ["description"] = "Zereth Mortis is sacred. Rifts should not form here. Something creates them. The metal you found has Maw magic. Devourers use it to make rifts. This is how they skirt our protections. Mawsteel shards are strewn across the area. Take these shards. Throw them off our cliffs. Make sure devourers do not use them to create rifts.", ["objectivesText"] = "Lift 4 Mawsteel Shards and throw them off the cliffs.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181177, ["x"] = 0.426, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181177, ["x"] = 0.426, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64739 }, ["questLines"] = { { ["id"] = 1277, ["name"] = "Jiro to Hero", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64783] = { ["id"] = 64783, ["name"] = "Dance Dance Darkmoon", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 8, ["zoneID"] = 5861, ["storyline"] = { 64783 }, ["description"] = "Simon says, \"Are you ready to dance?\" Step on in and show off your sweet moves, <class>. The rules are simple. Your opponent will perform a series of stylish moves, then you gotta match 'em. Earn enough accolades and then come back to ol' Simon. Just know that the more challenging the opponent, the more accolades you can earn. Simon says, \"Are you up for the challenge?\"", ["objectivesText"] = "Earn accolades by competing in the dance competition. Progress: Simon says, \"Show me what you got.\"", ["rewardItems"] = { 93724, 187689 }, ["starts"] = { { ["x"] = 0.512, ["y"] = 0.74, ["mapID"] = 407, ["npcID"] = 181097 } }, ["ends"] = { { ["x"] = 0.512, ["y"] = 0.74, ["mapID"] = 407, ["npcID"] = 181097 } }, ["coords"] = { ["mapID"] = 407, ["x"] = 0.512, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questGiverID"] = 181097, ["questTurnInID"] = 181097, ["questType"] = "standard" },
[64785] = { ["id"] = 64785, ["name"] = "Overgrown Story", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64785 }, ["description"] = "Since our arrival here the Untamed Verdure has been a mystery waiting to be solved. The lush foliage of the area grows on everything as the creatures run amok without purpose. There could be valuable research data to be obtained from these creatures. Use a Containment Trap to subdue the elemental creatures. Once subdued, examine them for research data.", ["objectivesText"] = "Gaiagantic and 12 Geomentals examined for research data. Progress: Have you completed the research?", ["rewardXP"] = 8165, ["rewardItems"] = { 187684, 187700, 187908, 187909, 189544, 190189, 190341, 190344, 190345, 190348, 190349, 190351, 190352, 190355, 190359, 190360, 190363, 190367, 190368, 190371, 190605, 190632, 190633, 190634, 190635, 192424 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 18 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64794] = { ["id"] = 64794, ["name"] = "Knowing is Half the Battle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "<name>, you should join Shandris and infiltrate the Mawsworn forces from the east. Whatever information you two uncover will inform us of your next course of action. Take care. We have no information on what you may find.", ["objectivesText"] = "Meet Shandris near the Provis Strata.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181180, ["x"] = 0.485, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64958, 65768, 65771, 65772 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64796] = { ["id"] = 64796, ["name"] = "Scour the Sands", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "The little I have seen so far has given me almost no information about our enemies. We will have to take a closer look. I can hide the both of us from sight on your command. But stay away from the dreadlords--their eyes are sharp enough to spy even a hidden huntress.", ["objectivesText"] = "Scout Provis Strata with Shandris Feathermoon . Progress: The less attention we draw, the better.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181180, ["x"] = 0.485, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181180, ["x"] = 0.485, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questTurnInID"] = 181180, ["questType"] = "standard", ["sourceQuests"] = { 64794 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64797] = { ["id"] = 64797, ["name"] = "Harmony and Discord", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "These obelisks must be key to Zovaal's plans. Even without full knowledge of their purpose, we should stop the Mawsworn from meddling with them. I will bring this information to Highlord Bolvar. Head to Darion Mograine and do the same. He will need to plan his defenses around this.", ["objectivesText"] = "Speak with Darion Mograine at Provis Terra.", ["rewardGold"] = 128700, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 188024, 188032, 188036, 188037, 190975 }, ["rewardChoices"] = { 188032 }, ["starts"] = { { ["x"] = 0.48, ["y"] = 0.449, ["mapID"] = 1970, ["npcID"] = 182046 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questGiverID"] = 182046, ["questType"] = "standard", ["sourceQuests"] = { 64796 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64798] = { ["id"] = 64798, ["name"] = "What We Overcome", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64812, 64813, 65259 }, ["description"] = "I understand now. All of us that were touched by Domination were able to tap into something. Whether nobility or vengeance, it gave the strength to resist. With all that I have faced, I have to remember that I am still here. And if there are those willing to stand with Sylvanas, I have to believe they will stand with me as well. I'm ready to try again. This time, I will overcome whatever I face.", ["objectivesText"] = "Defeat the Mawbound Monstrosity and infuse the final shard. Progress: We will not fail. There is no other choice but oblivion.", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 187785, 188009, 188015, 188020, 188027, 190953 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 181284, ["x"] = 0.592, ["y"] = 0.884 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 64808 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[64799] = { ["id"] = 64799, ["name"] = "The Broken Crown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64800 }, ["description"] = "Our friends have returned from the Sepulcher of the First Ones with a familiar face. Anduin... What terrible things he has endured. But as difficult and painful as it is, we must uncover what he knows. The Jailer has blocked our way within the Sepulcher, and we risk falling victim to Domination ourselves if we blindly follow. He is our best hope.", ["objectivesText"] = "Speak to Anduin Wrynn in the Geometric Cavern. Progress: We must defeat Zovaal, or all is lost.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181229, ["x"] = 0.332, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64844 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64800] = { ["id"] = 64800, ["name"] = "Our Last Option", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64799 }, ["description"] = "Zovaal has blocked our pursuit. If we are to defeat him, we must find a way to withstand Domination. But to overcome it, we need to understand how it works. The Primus of Maldraxxus created Domination, he will be able to tell us more. I asked Taelia to bring a piece of the Helm of Domination to Zereth Mortis. I dread to think of what might happen were I to try to carry it again... Let us discuss the way forward.", ["objectivesText"] = "Listen to the plan. Progress: We can never turn things back to the time that was. We can only live with the choices made, and move forward.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181229, ["x"] = 0.332, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181229, ["x"] = 0.332, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64799 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64801] = { ["id"] = 64801, ["name"] = "Elder Eru", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "Since we have earned the trust of the Enlightened, I have learned more about their explorations into Zereth Mortis . They know more than they are willing to tell, but often do not act on that knowledge. Perhaps where they observe, we can be a catalyst for action. In a secluded corner called the Lexical Glade, there is an elder named Eru. She may be able to give us insight on how we might use the language of the First Ones. Seek her out, and see if she will help us.", ["objectivesText"] = "Find Elder Eru outside the Lexical Glade.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181229, ["x"] = 0.332, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181266, ["x"] = 0.562, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64802 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64802] = { ["id"] = 64802, ["name"] = "Hello, Darkness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "I created Domination as a tool to punish Zovaal. My anger informed that creation, and now we pay the price for my hubris. Even Eternal Ones err on occasion. But we are not without hope. Take the half of the broken Helm of Domination, and test it upon one of your own. If it retains enough power, it can then be used to test it elsewhere in Zereth Mortis .", ["objectivesText"] = "Test the broken Helm of Domination on Darion Mograine. Progress: We will not give up until we have stopped Zovaal.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187785 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181245, ["x"] = 0.332, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181245, ["x"] = 0.332, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64800 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64804] = { ["id"] = 64804, ["name"] = "Cryptic Catalogue", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64803, 64805, 64853 }, ["description"] = "This area is a repository of various texts. Hmmm? What do they say? I have no idea! I have dedicated myself to their catalogue and organization. This is more important than ever, with invaders destroying the balance in Zereth Mortis ! We must preserve what we have found so far. You can help. Go into the glade and memorize the phrases there, then meet me down in the grotto. There is something in it that might help you test that helm of yours further.", ["objectivesText"] = "Memorize Phrases in the Lexical Glade. Progress: Think how much we could learn if we understood the intentions of the First Ones.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187785 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181266, ["x"] = 0.562, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184182, ["x"] = 0.592, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64801 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64805] = { ["id"] = 64805, ["name"] = "The Not-Scientific Method", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64803, 64804, 64853 }, ["description"] = "The language of the First Ones is not static like most others. It evolves. Creatures like the sentries are more advanced than your average poultrid, obviously. Their more complex thought processes give them an innate resistance to the invaders' overriding magic. But you should not take my word for it. We can actually test this! In the grotto there is a librarian. Take those phrases you memorized and infuse them into it. Then try out your helm.", ["objectivesText"] = "Test the Broken Helm on an activated Lexicon Librarian and observe the results.", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 187785 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184182, ["x"] = 0.592, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184182, ["x"] = 0.592, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64803, 64804 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64806] = { ["id"] = 64806, ["name"] = "Where the Memory Resides", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "I think I know what will be asked of us in Bastion . It will not be easy. With this half of the Helm, we have collected the first part of what is needed to resist Domination. But there are those of us who have also suffered from it. Lived through it. In a way, it has marked us. All of us. There must be something in those experiences that will help us break free from Zovaal's influence. Let us go to the Chamber of First Reflection in Bastion .", ["objectivesText"] = "Meet Highlord Bolvar inside the Chamber of First Reflection in Bastion .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 172924, 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181367, ["x"] = 0.572, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 1533, 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64810, 64811 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[64807] = { ["id"] = 64807, ["name"] = "What We Wish to Forget", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "While the language of the Progenitors will aid us, there is another trait that will help break Domination's hold on us. An indomitable will. Those of us who have endured before, and survived, have that inherent resistance, which we will offer up to be infused into each of the shards. The Primus has assured me that this will work. With no other options, this is the only way. I trust that it will be worth the suffering.", ["objectivesText"] = "Assist with the ritual and infuse the Shards of Domination . Progress: We will do whatever it takes.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187785 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.881 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 64806 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[64808] = { ["id"] = 64808, ["name"] = "What Makes Us Strong", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "I wish that I knew of this place sooner. Where terrible darkness could be purged from oneself, memories examined and expunged... I am willing to do whatever it takes to help defeat Zovaal, no matter the cost. This is the only way.", ["objectivesText"] = "Assist with the ritual and infuse the Shards of Domination . Progress: It takes more than raw strength to do what must be done.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187785 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 181284, ["x"] = 0.592, ["y"] = 0.884 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 181284, ["x"] = 0.592, ["y"] = 0.884 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["sourceQuests"] = { 64807 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[64809] = { ["id"] = 64809, ["name"] = "One Half of the Equation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64810 }, ["description"] = "The Primus's theory about the language of the First Ones has borne out. Still, it may not be enough. While the Primus finalizes his plans, let us go deep into the Endless Sands to find pieces of this power to infuse the helm. Darion, Taelia, and I will meet you there to help with the Mawsworn.", ["objectivesText"] = "Travel to the Deserted Overlook.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181229, ["x"] = 0.332, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181367, ["x"] = 0.572, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64853 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64810] = { ["id"] = 64810, ["name"] = "Oppress and Destroy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64809 }, ["description"] = "What we seek is in the vaults of the Endless Sands. To reach them will require strength and numbers. Together we will destroy the Mawsworn. I look forward to taking the fight directly to them. Remember, they will be vulnerable to the broken shard from the Helm of Domination.", ["objectivesText"] = "Slay Mawsworn in the Endless Sands. Progress: Such magnificent desolation.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178061, 187785, 188957, 189161, 189459, 189704, 190197, 190198 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181367, ["x"] = 0.572, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181367, ["x"] = 0.572, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64809 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64811] = { ["id"] = 64811, ["name"] = "Aggressive Excavation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["description"] = "Elder Eru said that we could find the most complex examples of the First Ones' language out here. We'll need to fight our way to the vaults, and then infuse the helm once we find those phrases. On a personal note, I never thought I'd have the chance to fight alongside my father. Though with the stakes this high, it somehow feels like exactly the place I'm supposed to be. I am ready when you are.", ["objectivesText"] = "Collect the Inscrutible Phrases.", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 187785, 190980, 190981, 190982, 190986, 190987, 190988, 190992, 190993, 190994, 190998, 190999, 191000 }, ["rewardChoices"] = { 190986, 190987, 190988, 190992, 190993, 190994 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181372, ["x"] = 0.572, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181367, ["x"] = 0.572, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64809 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64812] = { ["id"] = 64812, ["name"] = "Forge of Domination", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13522, ["mapID"] = 1533, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64798, 64813, 65259 }, ["description"] = "We have all of the pieces we need. The broken half of the helm has been augmented with the complexity of the language of the First Ones, and the shards bear our memories. Our will to resist Domination. All that remains is for the Primus to reforge the Helm, then we will be able to draw upon that combined power for ourselves. I know that it is dangerous, but it is our only hope.", ["objectivesText"] = "Travel to The Runecarver's Oubliette in Torghast.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187785 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 181280, ["x"] = 0.588, ["y"] = 0.881 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.881 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questTurnInID"] = 181280, ["questType"] = "standard", ["sourceQuests"] = { 64798 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1912 },
[64813] = { ["id"] = 64813, ["name"] = "The Crown of Wills", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["mapID"] = 1912, ["storyline"] = { 64798, 64799, 64800, 64801, 64802, 64803, 64804, 64805, 64806, 64807, 64808, 64809, 64810, 64811, 64812, 64813, 64853 }, ["series"] = { 64798, 64812, 65259 }, ["description"] = "When I created Domination, I did not foresee how much pain it would cause the realms. Not only the Shadowlands, but yours as well. It is time we take this helm, this symbol of that magic, and reforge it anew. But, not for the same purpose it once had. Let it represent the strength of will that you and your kind possess, so that it may help us overcome and defeat Zovaal at last.", ["objectivesText"] = "Reforge the Helm of Domination. Progress: There is no going back.", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 187785 }, ["starts"] = { { ["x"] = 0.493, ["y"] = 0.586, ["mapID"] = 1912, ["npcID"] = 181384 } }, ["ends"] = { { ["x"] = 0.493, ["y"] = 0.586, ["mapID"] = 1912, ["npcID"] = 181384 } }, ["coords"] = { ["mapID"] = 1912, ["x"] = 0.493, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 181384, ["questTurnInID"] = 181384, ["questType"] = "standard", ["sourceQuests"] = { 64812 }, ["questLines"] = { { ["id"] = 1258, ["name"] = "Crown of Wills", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1258, ["questLineOrder"] = 4 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1258, ["questLineOrder"] = 10 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1258, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1912 },
[64814] = { ["id"] = 64814, ["name"] = "Battle for the Forge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "Our forces have been holding out so far, but we have not secured the area. We could use some assistance cutting down the enemy's numbers. This should be a simple task for you, Maw Walker.", ["objectivesText"] = "Kill 8 Mawsworn forces. Progress: Is it done?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 190975 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64797 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jum