[64815] = { ["id"] = 64815, ["name"] = "Together, We Ride", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "The four covenants are working together here along with the automa. Unfortunately, some of our soldiers have been separated or wounded and are unable to return back here. If you could aid them, that would help tremendously.", ["objectivesText"] = "Aid 5 covenant forces.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 190975 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181193, ["x"] = 0.385, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64797 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["titl