[64816] = { ["id"] = 64816, ["name"] = "Reality's Doorstep", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64816 }, ["description"] = "The time has come to follow Zovaal into the very heart of the Shadowlands. We must return to Zereth Mortis and finish this.", ["objectivesText"] = "Return to Zereth Mortis .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["x"] = 0.491, ["y"] = 0.695, ["mapID"] = 1912, ["npcID"] = 181379 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questGiverID"] = 181379, ["questType"] = "standard", ["sourceQuests"] = { 64813 }, ["nextQuests"] = { 64875 } },
