[64820] = { ["id"] = 64820, ["name"] = "This is Your Fault, Fix It", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "Provis Fauna is normally regulated by autonomous constructs, but there have been reports that they are no longer working. According to the reports, you are the one responsible for the tampering of these nodes. Which means it is on you to fix them. Take this tuner, it should help--and once they are repaired, do not meddle with them again.", ["objectivesText"] = "Fix 5 defense nodes.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 190975 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177486, ["x"] = 0.348, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177486, ["x"] = 0.348, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64818 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 23, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineI