[64824] = { ["id"] = 64824, ["name"] = "Fighting for the Forge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "We made our way here as soon as we could. Anduin has been sighted near the structure in the middle of this land, referred to as the Forge of Afterlives. No doubt the Jailer will join him soon. We need to leave immediately.", ["objectivesText"] = "Head to the Forge of Afterlives with Jaina.", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 187839, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 183724, ["x"] = 0.431333, ["y"] = 0.639333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 183717, ["x"] = 0.573, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.431333, ["y"] = 0.639333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64823 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 27, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chap