[64825] = { ["id"] = 64825, ["name"] = "Seeking Haven", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64218, 64219, 64223, 64224, 64225, 64226, 64227, 64228, 64230, 64794, 64796, 64797, 64814, 64815, 64817, 64818, 64820, 64821, 64822, 64823, 64824, 64825, 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65149, 65271, 65305, 65456, 65768, 65771, 65772 }, ["description"] = "I am at a loss. We have no way to follow Zovaal and Anduin. I'll open a portal back to Haven. We will discuss our next steps there.", ["objectivesText"] = "Return to Haven with Jaina and Baine.", ["rewardGold"] = 257400, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 190742, 190745, 190748, 190751, 190975 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 183717, ["x"] = 0.573, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.573, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64824 }, ["questLines"] = { { ["id"] = 1266, ["name"] = "We Battle Onward", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 28, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1266, ["questLineOrder"] = 1 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "J