[64843] = { ["id"] = 64843, ["name"] = "Key Crafting", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "With those agitated automa quelled, there is but one task ahead. We shall ferry you and your Enlightened companion up to the Creation Catalyst. The rest is up to you.", ["objectivesText"] = "Restore the Translocator Key at the Creation Catalyst. Progress: It is incredible to see the Creation Catalyst up close.", ["rewardGold"] = 257400, ["rewardXP"] = 10205, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188276 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181814, ["x"] = 0.475, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184153, ["x"] = 0.474, ["y"] = 0.885 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64842 }, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64844] = { ["id"] = 64844, ["name"] = "The Pilgrimage Ends", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64830, 64831, 64832, 64833, 64834, 64835, 64836, 64837, 64838, 64839, 64840, 64841, 64842, 64843, 64844, 64969, 65331, 65335 }, ["description"] = "You have rescued many pilgrims, and I have restored your entrance to the Sepulcher. With that, our bargain is concluded--and so, too, is my pilgrimage. But your journey continues. Return to the overlook behind Pilgrim's Grace and open the translocator. My thanks, <name>. This adventure has been... enlightening.", ["objectivesText"] = "Return to the overlook behind Pilgrim's Grace. Progress: Let us listen to what they have to say.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187730, 187731, 187732, 187835, 188010, 188016, 188023, 188028, 188276 }, ["rewardChoices"] = { 188016, 188023, 188028 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184153, ["x"] = 0.474, ["y"] = 0.885 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181948, ["x"] = 0.646, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.885 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64843 }, ["questLines"] = { { ["id"] = 1262, ["name"] = "Forging a New Path", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1262, ["questLineOrder"] = 3 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1262, ["questLineOrder"] = 9 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1262, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2374, ["db2PoiUi