[64846] = { ["id"] = 64846, ["name"] = "Torghast", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 64846 }, ["description"] = "Countless souls are tortured in the halls of Torghast. They need your help!", ["objectivesText"] = "Speak with Tal-Inara .", ["rewardGold"] = 25505, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.405, ["y"] = 0.659, ["mapID"] = 1670, ["npcID"] = 167486 } }, ["ends"] = { { ["x"] = 0.405, ["y"] = 0.659, ["mapID"] = 1670, ["npcID"] = 167486 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.405, ["y"] = 0.659 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 167486, ["questTurnInID"] = 167486, ["questType"] = "standard", ["nextQuests"] = { 64849 }, ["db2AdventureMapPoiID"] = 176 },
[64849] = { ["id"] = 64849, ["name"] = "Tower of the Damned", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13546, ["storyline"] = { 64849 }, ["series"] = { 64850, 65035 }, ["description"] = "We know little of Torghast. However, Fatescribe Roh-Tahl claims there is work that must be done there. He believes there is a path for you to reach this place... and that someone there requires your aid. Do what you must to reach Torghast and aid anyone who is within.", ["objectivesText"] = "Travel to Torghast by jumping into the Ring of Transference, then find any entity there that needs your aid.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.392, ["y"] = 0.692, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["ends"] = { { ["x"] = 0.392, ["y"] = 0.692, ["mapID"] = 1670, ["npcID"] = 159478 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.392, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questGiverID"] = 159478, ["questTurnInID"] = 159478, ["questType"] = "standard", ["sourceQuests"] = { 64846 }, ["nextQuests"] = { 64850 } },
[64850] = { ["id"] = 64850, ["name"] = "Traversing Torghast", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10472, ["mapID"] = 1911, ["storyline"] = { 64850 }, ["series"] = { 64849, 65035 }, ["description"] = "I've heard of you, the Maw Walker! You must know of me, the legendary Ve'nish . I am here to find great treasures within Torghast with the aid of my box. I can see you admiring it. Perhaps we can work together. Why don't you go into Torghast ahead of me to scout ahead? I shall even reward you for anything you discover within.", ["objectivesText"] = "Aid Ve'nish 's exploration of Torghast by completing a wing within Torghast. Use the wayfinder within Torghast to access different wings. Progress: How goes exploring the darkness of Torghast?", ["rewardGold"] = 772200, ["rewardXP"] = 13630, ["rewardCurrencies"] = { { ["id"] = 1828, ["amount"] = 150 }, { ["id"] = 1877, ["amount"] = 6 } }, ["starts"] = { { ["x"] = 0.355, ["y"] = 0.469, ["mapID"] = 1911, ["npcID"] = 181328 } }, ["ends"] = { { ["x"] = 0.355, ["y"] = 0.469, ["mapID"] = 1911, ["npcID"] = 181328 } }, ["coords"] = { ["mapID"] = 1911, ["x"] = 0.355, ["y"] = 0.469 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13400 } }, ["questGiverID"] = 181328, ["questTurnInID"] = 181328, ["questType"] = "standard", ["sourceQuests"] = { 64849 }, ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1911 },
