[64867] = { ["id"] = 64867, ["name"] = "Supplies from The Enlightened", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64867 }, ["description"] = "Ah, yes. How I've looked forward to this moment for quite some time! Come, visit me. Let us share this achievement together. I've prepared something special just for you.", ["objectivesText"] = "Speak with Vilo at Haven in Zereth Mortis .", ["rewardItems"] = { 187780 }, ["starts"] = { { ["x"] = 0.348, ["y"] = 0.641, ["mapID"] = 1970, ["npcID"] = 182257 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 182257, ["x"] = 0.348, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questGiverID"] = 182257, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2479, ["threshold"] = 10000 } } } },
