[64871] = { ["id"] = 64871, ["name"] = "The Dragon at the Door", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "That blue dragon will collapse the creche and trap us inside! He claims to serve Malygos. That name is familiar, but... why would any dragon want to keep us prisoner? Listen, $p. We were trained to fight beside the dragons, not against them. But we have been left with no choice. Time to do what must be done, evoker.", ["rewardGold"] = 14300, ["rewardXP"] = 1770, ["rewardItems"] = { 193914 }, ["starts"] = { { ["x"] = 0.623, ["y"] = 0.365, ["mapID"] = 2109, ["npcID"] = 186883 } }, ["ends"] = { { ["npcID"] = 184269, ["x"] = 0.442, ["y"] = 0.614, ["mapID"] = 85 } }, ["coords"] = { ["mapID"] = 2109, ["x"] = 0.623, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questGiverID"] = 186883, ["questType"] = "standard", ["sourceQuests"] = { 64866 }, ["questLines"] = { { ["id"] = 1261, ["name"] = "The War Creche", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1261, ["questLineOrder"] = 0 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1261, ["questLineOrder"] = 0 } } },
[64872] = { ["id"] = 64872, ["name"] = "The Fire Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "You are an evoker, . The best of the best. An elite soldier who has mastered the skills of each of our weyrns. I expect a lot of you. Your memories may be broken, but the might of dragons courses through your veins. Harness it. One of your most potent weapons is your breath attack. The fire within becomes more powerful the longer you inhale. These insects swarming over our training grounds should make fine targets.", ["rewardGold"] = 7150, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 184269, ["x"] = 0.442, ["y"] = 0.614, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 184269, ["x"] = 0.442, ["y"] = 0.614, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.442, ["y"] = 0.614, ["source"] = "quest_giver", ["mapID"] = 2151 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 64871 }, ["questLines"] = { { ["id"] = 1270, ["name"] = "Old Weyrn Grounds", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1270, ["questLineOrder"] = 1 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1270, ["questLineOrder"] = 1 } } },
[64873] = { ["id"] = 64873, ["name"] = "Stretch Your Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13769, ["mapID"] = 85, ["description"] = "I am heartened to see that so many escaped the War Creche. My own weyrn... was not as fortunate. There are other creches throughout the Reach, filled with dracthyr in peril. Strong wings will be needed to reach them. Focus. Remember your training. Get a feel for the wind again. You must regain your strength and fly to the other creches. The time for rest is over.", ["rewardGold"] = 241020, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 181054, ["x"] = 0.444, ["y"] = 0.61, ["mapID"] = 85 } }, ["ends"] = { { ["npcID"] = 192889, ["x"] = 0.448, ["y"] = 0.578, ["mapID"] = 85 } }, ["coords"] = { ["x"] = 0.444, ["y"] = 0.61, ["source"] = "quest_giver", ["mapID"] = 85 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13769 } }, ["questType"] = "standard", ["sourceQuests"] = { 64872, 65615 }, ["questLines"] = { { ["id"] = 1270, ["name"] = "Old Weyrn Grounds", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 159, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1270, ["questLineOrder"] = 1 }, { ["id"] = 173, ["title"] = "Dracthyr, Awaken", ["questLineID"] = 1270, ["questLineOrder"] = 1 } } },
[64875] = { ["id"] = 64875, ["name"] = "Something Wonderful", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "<name>, I am so glad you are here! Firim sent me to find you. It's the oracle, it... well... it's hard to describe. You should come see it for yourself. Hurry!", ["objectivesText"] = "Travel to Exile's Hollow to witness for yourself what is happening to Saezurah. Progress: We must hurry, <name>. We do not know how long this will last.", ["rewardGold"] = 64350, ["rewardXP"] = 2040, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 182556, ["x"] = 0.354, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64816 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64876] = { ["id"] = 64876, ["name"] = "Music of the Spheres", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "It started gradually, the energy emanating from the oracle in increasing amounts, until the grand design you see before you took shape. The terrible clamor ringing in our ears began shortly afterward. My attempts to approach the fractals have been... unsuccessful. But they appear to resonate with Pocopoc. You share a special bond with it; perhaps you shall have better luck than I.", ["objectivesText"] = "Examine the fractals that surround Saezurah's body.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64875 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64878] = { ["id"] = 64878, ["name"] = "What a Long Strange Trip", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "<The voice from the vision speaks through Pocopoc , albeit distant and distorted.> I... am Saezurah. Oracle. This automa... speaks with my voice. Acts with my will. For now. The pattern... is torn. Disrupted. Mending must be done. A great hunger swarms the sands. What it seeks must not be consumed. Journey with me. Follow my voice.", ["objectivesText"] = "Go with Pocopoc to make sense of your vision. Progress: Pocopoc has not reached the destination yet.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 190977, 190978, 190979, 190983, 190984, 190985, 190989, 190990, 190991, 190995, 190996, 190997 }, ["rewardChoices"] = { 190977, 190983, 190984, 190985 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.41025, ["y"] = 0.3925 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64876 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64879] = { ["id"] = 64879, ["name"] = "A Monumental Discovery", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64879 }, ["series"] = { 64723, 64733 }, ["description"] = "Maw Walker--Pelagos stopped by earlier to give a report and said that the oracle's preparations were complete, and you were urgently needed. If this is something that can help our efforts, I want you involved. Head to Exile's Hollow and see what they need.", ["objectivesText"] = "Meet Firim in Exile's Hollow.", ["rewardGold"] = 64350, ["rewardXP"] = 2040, ["rewardItems"] = { 187809, 190464, 190465, 190466, 190467, 190468, 190469, 190471, 190472, 190473, 190474, 190475 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65328 }, ["nextQuests"] = { 64723 } },
[64888] = { ["id"] = 64888, ["name"] = "Borrowed Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "The land provides. The land thirsts. Invaders devour what we require. Reclaim what has been consumed. Absorb what remains abundant. Wings need wind to fly. We need power to ascend.", ["objectivesText"] = "Defeat volatile lured enemies or soak power from pools to reclaim Cosmic Energy to empower Pocopoc . Progress: More power to Pocopoc .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.41025, ["y"] = 0.3925 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questTurnInID"] = 181706, ["questType"] = "standard", ["sourceQuests"] = { 64878 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64889] = { ["id"] = 64889, ["name"] = "Match Made in Zereth Mortis", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "The cyphers are the key. Each one, a step along the path. You must find them all. Enter the inner chamber. The Prime Locus Arrangement awaits. The first step toward ascension. Toward the vessel.", ["objectivesText"] = "Study the Locus Arrangements and use the Locus Shift to reach the Ultimus Locus. Progress: Need to gather the cyphers to reach the door where the vessel waits.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 188044, 188045, 188053, 188054, 188055, 188106, 189704, 189863, 190374 }, ["starts"] = { { ["x"] = 0.472, ["y"] = 0.294, ["mapID"] = 1970, ["npcID"] = 181706 } }, ["ends"] = { { ["x"] = 0.472, ["y"] = 0.294, ["mapID"] = 1970, ["npcID"] = 181706 } }, ["coords"] = { ["mapID"] = 1970, ["x"] = 0.472, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 181706, ["questTurnInID"] = 181706, ["questType"] = "standard", ["sourceQuests"] = { 64888, 65245 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64935] = { ["id"] = 64935, ["name"] = "Between a Rock & a Rock", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "<Piles of rock are scattered around the area. The devourers have done enough damage to obscure the cypher you seek. Perhaps one of the nearby servitors could be made to clear the rubble.>", ["objectivesText"] = "Smash the rubble barring access to the secundus locus arrangement. Progress: Until we discover the cypher, we need to keep smashing rubble.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.484, ["y"] = 0.271, ["mapID"] = 1970, ["objectID"] = 375517 } }, ["ends"] = { { ["x"] = 0.484, ["y"] = 0.271, ["mapID"] = 1970, ["objectID"] = 375517 } }, ["coords"] = { ["mapID"] = 1970, ["x"] = 0.484, ["y"] = 0.271 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64888, 65245 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64936] = { ["id"] = 64936, ["name"] = "Searching High and Low", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "Three locks upon the door, three keys hidden atop the zenith. Find the phrases. Speak the words. Secure the vessel.", ["objectivesText"] = "Gather the Ingress Phrases on the Ultimus Locus that are needed to claim the Vessel. Progress: The vessel slumbers high above.", ["rewardGold"] = 128700, ["rewardXP"] = 8165, ["starts"] = { { ["x"] = 0.488, ["y"] = 0.316, ["mapID"] = 1970, ["npcID"] = 183701 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184949, ["x"] = 0.478, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questGiverID"] = 183701, ["questType"] = "standard", ["sourceQuests"] = { 64889, 64935 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64937] = { ["id"] = 64937, ["name"] = "You Light Up My Life", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64875, 64876, 64878, 64888, 64889, 64935, 64936, 64937, 65237, 65245, 65328 }, ["description"] = "Great power entices great hunger. The insatiable devourers scale the cliffs in search of sustenance. Soon they will swarm the plateau. They seek to consume all they encounter. The vessel. Its power. Us. This must not come to pass. Wield this automa. Silence their slavering howls.", ["objectivesText"] = "Use Pocopoc to defend the vessel against the devourers.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 188007, 188013, 188022, 188029 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184949, ["x"] = 0.478, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181706, ["x"] = 0.41025, ["y"] = 0.3925 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64936 }, ["questLines"] = { { ["id"] = 1264, ["name"] = "A Means to an End", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1264, ["questLineOrder"] = 5 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1264, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64941] = { ["id"] = 64941, ["name"] = "Chicken Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 64941 }, ["description"] = "Chicken Soul is perky and voracious. The shape of the chicken will be yours to call upon.>", ["objectivesText"] = "Bring the Chicken Soul to Choofa in the Heart of the Forest. Provided item:", ["rewardItems"] = { 187813 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["startItems"] = { 187813 } },
[64942] = { ["id"] = 64942, ["name"] = "Call of the Primus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "Though we fought to stop the Jailer in the Sanctum of Domination, we failed. He enveloped Oribos in the Maw, struck down the Arbiter, and opened the way to Zereth Mortis . The time has come to follow him. Within the Arbiter's Chamber, we will forge our own path. Hurry, Maw Walker. The fate of the Shadowlands, and all the realms beyond, is at stake.", ["objectivesText"] = "Speak with Tal-Inara in Oribos to travel to the Arbiter's Chamber.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["ends"] = { { ["npcID"] = 181655, ["x"] = 0.332, ["y"] = 0.504, ["zoneID"] = 13863 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[64944] = { ["id"] = 64944, ["name"] = "A Hasty Voyage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["series"] = { 64945, 65456, 64947 }, ["description"] = "The path to Zereth Mortis is open. We must part ways here. The Eternal Ones are forbidden from returning to the place of our creation. Zovaal has defied the most sacred laws of the Progenitors. You must undertake this journey alone. Go. Find a foothold in Zereth Mortis so that we can send the covenant forces through. Then we will pursue the Jailer and end his madness.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["npcID"] = 181655, ["x"] = 0.332, ["y"] = 0.504, ["zoneID"] = 13863 } }, ["ends"] = { { ["npcID"] = 181931, ["x"] = 0.34, ["y"] = 0.608, ["mapID"] = 1970 } }, ["coords"] = { ["x"] = 0.332, ["y"] = 0.504, ["source"] = "quest_giver", ["mapID"] = 1970 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64942 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } } },
[64945] = { ["id"] = 64945, ["name"] = "Strangers in a Strange Land", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["series"] = { 64944, 64947, 65456 }, ["description"] = "Did we... did we reach Zereth Mortis ? And are we walking on water? What a wondrous place! At least, from what I can tell through this fog. I think I can make out a structure in the distance. Perhaps we will find answers there.", ["objectivesText"] = "Accompany Pelagos and explore your surroundings.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181931, ["x"] = 0.278667, ["y"] = 0.559333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181561, ["x"] = 0.305, ["y"] = 0.5475 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.278667, ["y"] = 0.559333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64944 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64947] = { ["id"] = 64947, ["name"] = "Give Me A Hand", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["series"] = { 64944, 64945, 65456 }, ["description"] = "To drive the Jailer from Zereth Mortis , we must direct all our resources against the enemy. An object of potential power lies in a nearby repository, but the chamber's defenses respond only to automa. I would never harm their kind, but I have encountered one that no longer functions. If you extract its hand, we could use the inert appendage to gain access to the repository. I find such use of the First Ones' creations unsavory, but we cannot abide the presence of Mawsworn in this realm.", ["objectivesText"] = "Assist Firim .", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 187845, 187846, 188954, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181561, ["x"] = 0.305, ["y"] = 0.5475 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.305, ["y"] = 0.5475 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65456 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64949] = { ["id"] = 64949, ["name"] = "For Research Purposes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "I have taken pains not to disturb the automa during my time in Zereth Mortis , and so far they have paid little attention to me. It seems recent events have changed that. Again, let me be clear that I have no wish to harm the creations of the First Ones. But if, in the course of your efforts, conflict with the automa becomes inevitable, we must ensure that some good can come of it. If I can examine fragments of fallen automa, it may provide knowledge to use against the Mawsworn. Go carefully.", ["objectivesText"] = "Collect 12 Intact Automa Fragments from Alerted Automa within Genesis Vestibule Progress: Did you find any useful fragments?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64947 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1