[64950] = { ["id"] = 64950, ["name"] = "A Mutual Exchange", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["series"] = { 64951 }, ["description"] = "It seems the other automa did not appreciate our appropriation of their colleague's hand. They have become hostile. Unfortunate, but we cannot allow this to impede our progress. The automa's hand should activate a console within the Genesis Repository. I believe it holds an object of great potential. After you acquire it, I will guide you to a place that may provide a means to reach the allies you left behind. Do we have an accord?", ["objectivesText"] = "Use the Automa Hand to activate an Automa Console and obtain the Repository Treasure. Progress: Did you acquire the object from the console?", ["rewardGold"] = 257400, ["rewardXP"] = 1020, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64947 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64951] = { ["id"] = 64951, ["name"] = "The Road to Haven", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["series"] = { 64950 }, ["description"] = "I did not expect to encounter a living mortal and a kyrian this day, but your assistance has been valuable. Before I begin my studies of this automa core, I will guide you to Haven, the settlement founded by my expedition upon our arrival. Though my colleagues saw fit to exile me for challenging their \"Enlightened\" dogma, I have no wish to see Haven wiped from existence by the Jailer. Aid them and they may assist your efforts to return to your allies. We brokers are nothing if not transactional.", ["objectivesText"] = "Ride with Firim out of the Genesis Repository.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184062, ["x"] = 0.312, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181561, ["x"] = 0.305, ["y"] = 0.5475 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64949, 64950 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64952] = { ["id"] = 64952, ["name"] = "Destroying the Destructors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "The Mawsworn possess terrible weapons that gather dark magic and hurl it against our gates. The defensive barrier around Haven will not hold much longer. All that we are, all that we hold dear, will soon be erased from existence. If you are who you claim to be, then prove it to us. Destroy the enemy's armaments and help defend our home. I pray to the First Ones that you succeed.", ["objectivesText"] = "Destroy 4 Maw Destructors.", ["rewardGold"] = 128700, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.336667, ["y"] = 0.679333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65271 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64953] = { ["id"] = 64953, ["name"] = "Defending Haven", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "The Mawsworn are gathering in force outside our very gates. It is clear they mean to overrun our home! The Enlightened wish only to honor the marvels of the First Ones in peace. Haven's defensive barrier was put in place to shield us from minor threats. We did not imagine the Jailer would send his forces against us. You claim to be our ally, mortal? Then help us defend this sacred land.", ["objectivesText"] = "Defeat 13 Mawsworn in the Great Veldt. Progress: Our pilgrims cannot continue like this.", ["rewardGold"] = 257400, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["rewardCurrencies"] = { { ["id"] = 1822, ["amount"] = 1 }, { ["id"] = 1822, ["amount"] = 2 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177486, ["x"] = 0.348, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177486, ["x"] = 0.348, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 65271 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64957] = { ["id"] = 64957, ["name"] = "This Old Waystone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64942, 64944, 64945, 64947, 64949, 64950, 64951, 64952, 64953, 64957, 64958, 65271, 65456 }, ["description"] = "The Jailer has withdrawn his forces. I should be relieved, but I fear this means he has found a way into the Sepulcher. < Elder Ara trembles.> Despite Elder Kreth's doubts, you have proven to be an ally. Something we need more of. When our expedition arrived in Zereth Mortis , we discovered a dormant waystone. If you are indeed a Maw Walker, then the prophecies tell us that you will be able to activate it. If your allies can save this sacred place, then the path to them must be opened. Come.", ["objectivesText"] = "Open the Waystone to Oribos.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 187839, 187845, 187846, 188955, 188956 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 178016, ["x"] = 0.336667, ["y"] = 0.679333 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.336667, ["y"] = 0.679333 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questTurnInID"] = 178016, ["questType"] = "standard", ["sourceQuests"] = { 64952, 64953 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1671 },
[64958] = { ["id"] = 64958, ["name"] = "The Forces Gather", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["description"] = "I am relieved that you survived the passage to Zereth Mortis . From what I've overheard of Pelagos's conversation with Kleia, it sounds like you had an incredible journey. These Enlightened brokers could make valuable allies. Their knowledge of the automa and the land itself should help us against the Jailer. Our forces are gathered and ready to follow you to Zereth Mortis . The final battle lies before us, $p.", ["rewardGold"] = 257400, ["rewardXP"] = 1020, ["rewardItems"] = { 189544 }, ["rewardChoices"] = { 188038, 188039, 188041, 188043, 188046, 188049, 188050, 188056 }, ["starts"] = { { ["x"] = 0.495, ["y"] = 0.375, ["mapID"] = 1670, ["npcID"] = 184698 } }, ["ends"] = { { ["npcID"] = 177486, ["x"] = 0.348, ["y"] = 0.648, ["mapID"] = 1970 } }, ["coords"] = { ["mapID"] = 1670, ["x"] = 0.495, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questGiverID"] = 184698, ["questType"] = "standard", ["sourceQuests"] = { 64957 }, ["questLines"] = { { ["id"] = 1265, ["name"] = "Into the Unknown", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 1287, ["name"] = "Patch Intro", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 158, ["title"] = "Secrets of the First Ones", ["questLineID"] = 1265, ["questLineOrder"] = 0 }, { ["id"] = 161, ["title"] = "Catching Up!", ["questLineID"] = 1287, ["questLineOrder"] = 0 }, { ["id"] = 163, ["title"] = "Intro Start", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 164, ["title"] = "Jump to Chapter 6", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 167, ["title"] = "Jump to Chapter 5", ["questLineID"] = 1287, ["questLineOrder"] = 8 }, { ["id"] = 168, ["title"] = "Jump to Chapter 7", ["questLineID"] = 1287, ["questLineOrder"] = 8 } } },
