[64977] = { ["id"] = 64977, ["name"] = "Step Into the Ring", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64977 }, ["description"] = "One of the remarkable things we have found about these lands is that they seem to be adaptive and changing, even as ancient as they are. Things are not stationary. In the depths of the Nexus of Actualization there is a forge that appears made to test these various designs, and to learn. These creatures may one day be used to defend Zereth Mortis from threats, so you should test their effectiveness where possible. Go there, challenge what the forge creates and report back to me.", ["objectivesText"] = "Defeat Generated creations in the Nexus of Actualization.", ["rewardItems"] = { 189544, 190189, 190341, 190342, 190343, 190345, 190346, 190347, 190349, 190350, 190351, 190352, 190353, 190354, 190357, 190359, 190360, 190361, 190362, 190365, 190368, 190369, 190370, 190605, 190632, 190633, 190634, 190635, 192422, 192423, 192424, 192428, 192430, 192449, 192450, 192451 }, ["rewardCurrencies"] = { { ["id"] = 1979, ["amount"] = 22 }, { ["id"] = 2009, ["amount"] = 75 } }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["sourceQuests"] = { 64230 }, ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
